INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçluyum', 'sucluyum-zeki-dagli-rx0qk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevmeyi unutmadım diye, 

Gönlümü avutmadım diye, 

Suçlusun diyoranız eğer; 

Asın gönlümü, suçluyum ben. 

Sevgileri yücelttim diye, 

Ümitleri yeşerttim diye, 

Suçlusun diyorsanız eğer; 

Asın gönlümü, suçluyum ben.

(Zeki Dağlı -Mamak Anadolu Lisesi 

Edebiyat ömğretmeni

Mamak-Ankara)', 'Sevmeyi unutmadım diye,  Gönlümü avutmadım diye,  Suçlusun diyoranız eğer;  Asın gönlümü, suçluyum ben.  Sevgileri yücelttim diye,  Ümitleri...', ARRAY['Türk Edebiyatı','Şiir','Zeki Dağlı']::text[], 8.5, '{"poet":"Zeki Dağlı","poet_slug":"zeki-dagli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sucluyum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fark', 'fark-bahar-temmuz-bwawh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalktın! 

Muhakkak kalktın.

Benden kilometrelerce uzakta, 

Gün doğarken.

Belki sen de

Gün doğumunu izledin, 

Benim gibi.

Yeni başlayan gün için, 

Dilekte bulundun, 

Benden farklı olarak.

Sen, beni unutmayı diledin; 

Bense unutmamayı.

19.08.2001

Sus kalbim! 

Sen istedin

Böyle olmasını.

Kaybettin!', 'Kalktın!  Muhakkak kalktın. Benden kilometrelerce uzakta,  Gün doğarken. Belki sen de Gün doğumunu izledin,  Benim gibi. Yeni başlayan gün i...', ARRAY['Türk Edebiyatı','Şiir','Bahar Temmuz']::text[], 8.5, '{"poet":"Bahar Temmuz","poet_slug":"bahar-temmuz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/fark-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O gün', 'o-gun-mehmet-nuri-hasar-pihst', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevmiyordum ki ben seni

		  		Biliyordum sevmiyordum

		Yalnızdım

			uzaktaydım

                                   Hasrettim

    		Okuluma arkadaşlarıma sevdiklerime

		Tutunacak dal 

			Avunacak bir öykü arıyordum ben

		Sevmiyordun ki sen beni

				Biliyordum sevmiyordun	

		Yalnızdın

			uzaktaydın

				acıyordun belki bu askere

			Mektupsuz bırakmıyayım diye

		O zaman neden vuruldum 

 			o gün ben

		Bir yanım kanıyor durmadan

		Neden

			Neden ağıtlar yakıyor yüreğim

		Neden

			Neden yanıyor. Sana benziyen tüm kızların saçları

		Neden Sığamıyorum kabıma

			Ağlıyorum sessizce sabahları

		Seçseydim o şarkılardan birini

			Gitmezdin alel acele değilmi

		Benim pişmanlığım neye yarar

		Sen varsın şimdi 

			tüm şarkılarda

		Uykusuz bir gecenin sabahında

						düşünüyorumda	

		tek şarkı kalsaydı bana senden

		Vallahi silerdim 

			en son satırını bile

					    evrenden', 'Sevmiyordum ki ben seni 		  		Biliyordum sevmiyordum 		Yalnızdım 			uzaktaydım                                    Hasrettim     		Okuluma ar...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Nuri Haşar']::text[], 8.5, '{"poet":"Mehmet Nuri Haşar","poet_slug":"mehmet-nuri-hasar","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/o-gun-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Doğumla Bir Ölüm Arası', 'bir-dogumla-bir-olum-arasi-mehmet-nuri-hasar-033wb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Merdivendeydim telefon çaldığında

	Nefes nefese daldım içeri

	Sesini duydum, benim adımı söylüyordun

	Hemen ardından kendininkini

	Gittim geldim, bir doğumla  bir ölüm arası.

	Bir doğumla ölüm arası kaç savaş yaşanır.

	Kaç kara sevda, kaç orman yakılır, 

	Kaç özlem biter.Kaç çöl sulanır

	Tanıyamadın dedin, tanıyamadın sen beni.

	Seni, sesini anımsattığın türküleri ve serçeleri

	Nasıl tanımam Baharım.nasıl tanımam Selvi Boylum

	Nasıl tanımam Cesur Yüreklim, yaşama sevincim.

	Unuttum mu sandın Hasanoğlan Öğretmen okulunu, 

	Unuttum mu sandın Livaneli''nin fındık ağaçlarını 

	Bulanık, aksi ve vahşi akan Çoruh''unu

	Unuttum mu sandın Kafkasların karlarını, çamlarını ve

									mektuplarını	

	

	Düğünümüz var diyordun bekliyoruz falanca aya.

	Kimin? Kimin düğünü var Bahar.Bizim mi	? 

	Geç kalmadık mı? 30-40 yıl kadar

	Geç kalmadık mı? Bir doğumla bir ölüm arası 

	Oğlunun demek düğün, oğulların kızların var demek.

	Var tabi, benim de var.hem de düğünleri olacak yaştalar.

	Evlendirme onları Bahar.Verme kimselere.

	Bir iğne ağaçlının  tek yaprağı kadar hatırım varsa verme 

									kimselere

	Kızlarına oğullarımı vereyim.kızımı da oğluna al.

	Karşılığında göl kıyısında ki köyün kokusunu ver bana geri.

	Hasanoğlandaki kızın önlüğünden bir parça gönder

	Ya da! başlık olarak.Görülmüştür damgalı  bir zarfın var, 

									haberini

	Pahalı bulduysan bunları,  ben öderim sana başlık parası

	Oğluma kızını alayım, kızlarıma oğullarını

	Karşılığında; Hasanoğlanı al, livaneli''ni al

	Sevdalı yüreğimi al Bahar, dayanamıyorum.

	Çok canım yanıyor.bir doğumla bir ölüm arası

	080103', 'Merdivendeydim telefon çaldığında 	Nefes nefese daldım içeri 	Sesini duydum, benim adımı söylüyordun 	Hemen ardından kendininkini 	Gittim ge...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Nuri Haşar']::text[], 8.5, '{"poet":"Mehmet Nuri Haşar","poet_slug":"mehmet-nuri-hasar","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bir-dogumla-bir-olum-arasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Adam', 'o-adam-murat-hakki-yasar-vw0lk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yeni bir günün bu ilk saatinde

Yine seni düşünüyorum yıldızların altında

Onlar kadar yanlız

Ve onlar kadar kalabalık düslerımde

Ve bir yıldıza gözlerim takılıyor

Baktıkca  seni  hatırlıyorum

Senin gibi parlak ve ışıltılı geliyor

Hatırlıyormusun o güzel günleri

Gezdigimiz yerleri 

Hatırlıyormusun bir yaşlı adam vardı

Hep  dalgın ve duyguluydu

Onu her gördügümüzde

Yanına gider sohbet ederdik

Hep o sevdigi  kızdan bahsederdi 

Ve ağlardı

Şimdi benim o yaşlı adamdan 

Hiç bir farkım yok biliyormusun

Sensizim bu diyarlarda yanlız ve kederliğim

Sigaramın dumanında sensin

Sigaramın kendisi benim

İçime çektikce kayboluyorum

(SUNGURLU/ÇORUM

20/01/2003

FATİH  BEZENİR''OĞLU)', 'Yeni bir günün bu ilk saatinde Yine seni düşünüyorum yıldızların altında Onlar kadar yanlız Ve onlar kadar kalabalık düslerımde Ve bir yıldı...', ARRAY['Türk Edebiyatı','Şiir','Murat Hakkı Yaşar']::text[], 8.5, '{"poet":"Murat Hakkı Yaşar","poet_slug":"murat-hakki-yasar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/o-adam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Celal ile Behiye', 'celal-ile-behiye-erhan-guleryuz-1l3iu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tarlayı ekti Celal.Bahar geldi.Çiçek oldu

badem, sevindi.Atı öldü.Ana avrat küfretti şansına.

Yılanları yaktı bir gece, bütün çayır kavruldu.Çok

Rakı içti yalnızlık öldü.Altmış yedi yılın hesabı

masalarda sızdı.O güzelim hatıraları leş gibi 

taşımaya çalıştı.

O gece yaktı Birinci''yi...Uzandı.Döşek, saman

hayata perde oldu tavan.

Seyretti seyretti, iki gıdım oynadı dudağı.Güldü.

Ne devlet ne dünya, bir tek o vardı evde ve

Behiye''nin on sekiz yaşındaki gülüşü...

Elini uzattı, okşadı yanaklarını.

*Kızdın mı seninle gelmedim diye? 

*Amaann Celal, sanki gel desem gelecektin.

*Gelirdim be! Gelirdim deyyusun kızı, gelirdim

tabii.Bak ne halde ev.Çiçekler hep kurudu her taraf 

toz duman.

*Oralar nasıl? Soba yakmaya halim yok, üşüyorum.

Behiye çocuksu bir gülümseyişiyle elini uzattı.

*Celal, gelsen artık diyorum.Sen sıkılırsın, bak

çocuklar, çoluğa çocuğa karıştı.Evde yalnız başına 

olur mu hiç? Gel be Celal''im

Celal güldü.Biraz yorgun, biraz kararsız.

*Ben kalkamıyorum, tut elimden.Vakit geldi.

Yavaş! sırtım ağrıyor.

Sarıldılar, gün doğdu, günler geçti, mahalle koktu

buldular onu.', 'Tarlayı ekti Celal.Bahar geldi.Çiçek oldu badem, sevindi.Atı öldü.Ana avrat küfretti şansına. Yılanları yaktı bir gece, bütün çayır kavruldu...', ARRAY['Türk Edebiyatı','Şiir','Erhan Güleryüz']::text[], 8.5, '{"poet":"Erhan Güleryüz","poet_slug":"erhan-guleryuz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/celal-ile-behiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Külkedisi', 'kulkedisi-erdogan-ciray-zlblk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '"Sen elmayı seviyorsun diye elma da seni sevmek zorunda değil" demiştin ...

Kolay güzelim; O halde ben de ayvayı yerim ! ...

Yasak meyvem; 

Elmamsın, elmamsın.

Şiirimde hecem, 

İçimde ilhamsın.

Mutluluğa kırgın, 

Tutkulara dargınsın, dargınsın.

Issız Sokakların Külkedisi! 

Rüyaların Kadını! 

Aldatanlara, ağlatanlara, 

Kızgınsın, kızgınsın.

Senin de hakkındır övülmek.

Elbebek-gülbebek sevilmek.

Var mı bu alemde aşksız ölmek? 

Dünya Güzelim! Bebeğim! 

Aşkımsın, aşkımsın.', '"Sen elmayı seviyorsun diye elma da seni sevmek zorunda değil" demiştin ... Kolay güzelim; O halde ben de ayvayı yerim ! ... Yasak meyvem;  ...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çıray']::text[], 8.5, '{"poet":"Erdoğan Çıray","poet_slug":"erdogan-ciray","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kulkedisi-serbest-calisma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolapdere''de Meditasyon', 'dolapdere-de-meditasyon-erhan-guleryuz-lel5o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adını mantram yaptım.

Tütsülerde kokun var.

Adeta sana taptım.

Şu Auram bana dar.

Astral astral giderken

aşık oldum ben sana.

Gel üçüncü gözüm ol, 

dalalım kozmoslara.', 'Adını mantram yaptım. Tütsülerde kokun var. Adeta sana taptım. Şu Auram bana dar. Astral astral giderken aşık oldum ben sana. Gel üçüncü göz...', ARRAY['Türk Edebiyatı','Şiir','Erhan Güleryüz']::text[], 8.5, '{"poet":"Erhan Güleryüz","poet_slug":"erhan-guleryuz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dolapdere-de-meditasyon-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şırnak''ta 98 Yazı', 'sirnak-ta-98-yazi-erhan-guleryuz-16sem', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eşkıya nedir öğretmenim, 

babam neden vuruldu? 

Silah nedir öğretmenim, 

dedem neden oynardı? 

Acı nedir öğretmenim, 

anam neden duruldu? 

Al kınalı kekliğim

kanadından vuruldu.

Sevda nedir öğretmenim? 

Aşık Veysel söylerdi.

Toprak nedir öğretmenim, 

neden hep mezar oldu? 

Oysa mis gibi kokar

bahar yağmurlarında.

Toprağım Anadolu, 

gökyüzünün altında.

Yalan nedir öğretmenim? 

Şeytan''ın anlattığı.

Hasret nedir öğretmenim? 

Göçenlerden duyduğum...

Ölmek nedir öğretmenim, 

yaşamak böyle midir?', 'Eşkıya nedir öğretmenim,  babam neden vuruldu?  Silah nedir öğretmenim,  dedem neden oynardı?  Acı nedir öğretmenim,  anam neden duruldu?  A...', ARRAY['Türk Edebiyatı','Şiir','Erhan Güleryüz']::text[], 8.5, '{"poet":"Erhan Güleryüz","poet_slug":"erhan-guleryuz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sirnak-ta-98-yazi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yollar', 'yollar-hudayi-can-3yz1w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben hane ber-duş yazgım yol yol alnımda

Alnımdan yollar akıyor ırmak ırmak

Yollar kılcal damarları hayatımın

Hayatımsa yollara yazgımı sormak

Kararım yok ah tek şeritli yollarda

Yolcu dursa yol akar ne mümkün durmak

Yolların tozu işlemiş mevsim mevsim kanıma

Yazgım yol üzre... tozlar gibi yollarda savrulmak

Ben hane ber-duş teselli kâr etmez hiç

Teselli mi kendini yollara vurmak

Desinler bir yolcu geçti buralardan

Alnından yollar aktı ırmak ırmak', 'Ben hane ber-duş yazgım yol yol alnımda Alnımdan yollar akıyor ırmak ırmak Yollar kılcal damarları hayatımın Hayatımsa yollara yazgımı sorma...', ARRAY['Türk Edebiyatı','Şiir','Hüdayi Can']::text[], 8.5, '{"poet":"Hüdayi Can","poet_slug":"hudayi-can","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yollar-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklemenin Rengi', 'beklemenin-rengi-hudayi-can-fl770', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nedir beklemenin rengi? 

Beklemek nedir? 

Beklemek, önce biraz mavidir şüphesiz

Belki biraz sarı, biraz pembe, 

Kara lekeler de olabilir zaman zaman kuşkular beyanında

Kızılı ocağınızdan uzak olsun dostlar

Siyahı düşman başına

Beklemek nedir, gördüm ben dostlar

O bir koşuştu yürüyen merdivende

Hem bildiği halde, iki iki dört eder

Bir saat erken varacak buluşma yerine

Sonra beklemeyi bir durakta gördüm

Beş dakikada on kez saatine baktı tazenin biri

Beklemek kaderi olur bazılarının

Bazıları bekleneni değil beklemeyi bekler

Kimileri de bekleyene hasret, beklenmeye muhtaç

Bekleyenim olsa da, der, razıyım kavuşmasam.

Biri bana resmini yap deseydi beklemenin

Sanırım bir kum saati çizerdim.

“Ama bu zamanın resmi” demeyin dostlarım

Kumunu yedirmekle zamanı büzemezsin demeyin

Saatin o ince beline mıhlanmış

Bir çift melûl gözdür bekleyen

Vaktin kar gibi erimesini ister gözlerinin yangınında

Bilir halbuki, eriyen ömürdür

Kum saati bir değirmendir bizi öğütür

Ve bilir, siz de bilirsiniz bilirim dostlar

Bütün saçlar bu değirmende ağarmıştır...

Şimdi diyebilir miyiz, 

Bunca şeyden sonra

Diyebiliriz neden olmasın

Beklemek kül rengidir dostlar

Bir yangın sonrası kum saatinin büyüyen tepeciğinde

Külleridir düşlerimizin

Kül rengidir mavi göğe savrulan.', 'Nedir beklemenin rengi?  Beklemek nedir?  Beklemek, önce biraz mavidir şüphesiz Belki biraz sarı, biraz pembe,  Kara lekeler de olabilir zam...', ARRAY['Türk Edebiyatı','Şiir','Hüdayi Can']::text[], 8.5, '{"poet":"Hüdayi Can","poet_slug":"hudayi-can","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/beklemenin-rengi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşüş', 'dusus-hudayi-can-otm9z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Uçurumun kenarındayım. Aman, 

Cehennem, tamu narındayım. Aman, 

Bir daha bakmama kararındayım

Aman, düştüm düşeceğim medet ey! 

Baktım bakacağım, ah batacağım.

Baktım mı düşeceğim, batacağım...

Bu bir uçurumdur aman, bakılmaz! 

Bu bir bakış için ey Can batılmaz.

Bir karanıkta düşüyorum, aman! 

Bir karanlığa düşüyorum, aman! 

Bir yanıyor bir üşüyorum, aman! 

İnfilak etti beyin hücrelerim.

Cayır cayır yanıyor ciğerlerim.

Alev alev yanıyorum, cehennem...

Sonra kurtulup... yok kutup, cehennem...

Kutup kutup donuyorum, cehennem...

Yanarak, donarak uyanıyorum.

Bu bir karanlıktır, aman, bakılmaz! 

Karanlığa canım adım atılmaz.

Bir kuyu, düştüm düşeceğim, aman! 

Dipsiz kuyu, ipsiz kova, sahipsiz...

Susuz kuyu, yakıyor suyu, aman! 

Damarlarımda sular tutuştu, ah! 

Damar damar, kanlarım buza döndü, 

Tuz-buz beynim... kuyu sonsuza döndü.

Bu bir zehirli bal, aman, tadılmaz! 

Bir ana ey Can sonsuzluk satılmaz.

El-aman, halas et düşmekten, medet! 

Düşüş yoluna düşmekten, sürçmekten...

Medet ki, halas zarındayım, aman! 

Uçurumun kenarındayım. Aman...', 'Uçurumun kenarındayım. Aman,  Cehennem, tamu narındayım. Aman,  Bir daha bakmama kararındayım Aman, düştüm düşeceğim medet ey!  Baktım bakac...', ARRAY['Türk Edebiyatı','Şiir','Hüdayi Can']::text[], 8.5, '{"poet":"Hüdayi Can","poet_slug":"hudayi-can","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/dusus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tüveley', 'tuveley-hudayi-can-efpmt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen ey tüveley, rüzgarların girdabı

Savruldu hayallerimiz, hatıralarımız

Savruldu önünde çer çöp misali…

Ki hangi kavak yelleri estiyse başımızda

Hangi karayel, poyraz, lodos, meltem

Ve nice bora savurduysa, 

Nice sam yeli kavurduysa ömrümüzü

Sen onların çocuğusun.

Rüzgar ektik gönüllere fırtına biçtik, 

Öfkelerimizi süzdük kalbimizden 

				Sen doğdun

Ve sen, ey tüveley, ruhumuzun girdabı

Ne kadar da mahirsin dağıtmada harmanlarımızı

İyi günlerimizi, küçük sevinçlerimizi, “gözün aydın”larımızı

Selamınla darman duman gönül çekmecelerimiz

	-selamın silm getirmedi hiçbir zaman-

Nerelere savurdun kavak yellerimizi, 

Artık birleştiremez miyiz ellerimizi? ..

Ve hatta tatlı kavgalarımızı, küçük cedellerimizi

Savurdun ey tüveley atmosferin bilinmez katmanlarına

Ve savrulduk dört yana

Doğu, batı, güney, kuzey

Ve sen ey, 

Lümmemizin izdüşümü, 

Ruhumuzun girdabı

Hilkat çamurumuzun

Ömür ağacımızın türabı

Ve ey, ve ey, ve ey…

Veyl sana tüveley!', 'Sen ey tüveley, rüzgarların girdabı Savruldu hayallerimiz, hatıralarımız Savruldu önünde çer çöp misali… Ki hangi kavak yelleri estiyse başı...', ARRAY['Türk Edebiyatı','Şiir','Hüdayi Can']::text[], 8.5, '{"poet":"Hüdayi Can","poet_slug":"hudayi-can","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/tuveley-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Çağrışımları', 'guz-cagrisimlari-hudayi-can-iz8vl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu sonbahardır; sararır yapraklar.

Benizler sararır, genizler dolar; 

Hayatın son baharı mı dersin bu.

Hayatım sonbaharın mı dersin bu, 

Ömrümden önüme düşer yapraklar.

Denizler daha karanlık bu mevsim, 

Kuşlar daha gamlı, duyuşlar lirik...

Gözler göğe dikili ürktü ürker...

Kırılır bir ince dal; ceylan, geyik

Kuzular koşar güze ve ölüme.

Nereden bilsinler bu uçurumdur! 

Yavru kuşlardır, uçarlar yuvadan; 

Kim bilir dönerler mi dönmezler mi? 

Bahar geri gelmez, gelen yeşildir

O da o bildik yeşil mi kim bilir? 

Eski yeşiller eski baharlarda, 

Eski mevsimler yeni hülyalarda.

Bu mevsim, düşler bile bir başkadır.

Hep yapraklar uçuşur rüyalarda...

Bu yapraklarıdır ömrünün ey Can! 

Kuru yapraklar; sarı, bronz, kızıl...

Seni savurur günler ve geceler.

Yapraklar toprağa, aslına döner

Artık sen, o bildik sen değilsindir...

Bu son bahardır, sararır yapraklar.

Bakışlar bulanır, gözlerin dolar...

Geçen ömürle vedalaşmak mı bu, 

Özlenen uçuruma ulaşmak mı? 

Gelen gider demiş pir, giden gelmez...

Ömrümden önüme düşer yapraklar, 

Önümde ölüme düşer yapraklar...', 'Bu sonbahardır; sararır yapraklar. Benizler sararır, genizler dolar;  Hayatın son baharı mı dersin bu. Hayatım sonbaharın mı dersin bu,  Ömr...', ARRAY['Türk Edebiyatı','Şiir','Hüdayi Can']::text[], 8.5, '{"poet":"Hüdayi Can","poet_slug":"hudayi-can","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/guz-cagrisimlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Üzerine', 'yalnizlik-uzerine-hudayi-can-hkh5t', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vefa ediyor belki aklınca, 

Ama insaf etmiyor yalnızlık.

Takvimler bitse de yaprak yaprak; 

Bitmiyor yalnızlık.

Yalnız kalmamdan korkuyor olmalı ki; 

Bir türlü başımdan gitmiyor yalnızlık.', 'Vefa ediyor belki aklınca,  Ama insaf etmiyor yalnızlık. Takvimler bitse de yaprak yaprak;  Bitmiyor yalnızlık. Yalnız kalmamdan korkuyor ol...', ARRAY['Türk Edebiyatı','Şiir','Hüdayi Can']::text[], 8.5, '{"poet":"Hüdayi Can","poet_slug":"hudayi-can","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yalnizlik-uzerine-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup Geldi', 'mektup-geldi-hudayi-can-d6wnx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hava ne güzel değil mi kuşlar? 

Buz kesse de ellerim, kulaklarım donsa da soğuktan, 

Gök kapkara bulutlarla dünkü kalbim gibi kararmış olsa da

Bu gün hava ne güzel değil mi kedicik? 

Hava kalbime göredir benim dostlar! 

Şu an bütün dostlar, sarı yapraklar, gri sis.

Hava hep keyfime bağlıdır benim.

Değil mi ki sevdiğimden mektup geldi, 

Sevgili duygumu duyup geldi mektupla, 

Bu gün hava ne güzeldir, buzlar sarksa da saçaklardan.

Beni mektupla hatırlayınca canan, 

Hatırladığını hatırlatınca, mektup yazınca, 

Bir başka bakarım sağıma soluma

Sevgi dolu, bir başka insancıl, iyimser, 

Beni görürler, sorarlar, 

Ne o, piyangodan büyük ikramiye mi kazandın? 

Cennetle mi müjdelendin, derler kimi zaman da.

Bilmezler tabii, nereden bilsinler, söylemem, 

Bana hayatımın piyangosudur canan, onun mektupları

Belki beraber cennete girmeyi ümit ediyorumdur, 

Onun cennet atmosferine girdikten sonra.', 'Hava ne güzel değil mi kuşlar?  Buz kesse de ellerim, kulaklarım donsa da soğuktan,  Gök kapkara bulutlarla dünkü kalbim gibi kararmış olsa ...', ARRAY['Türk Edebiyatı','Şiir','Hüdayi Can']::text[], 8.5, '{"poet":"Hüdayi Can","poet_slug":"hudayi-can","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mektup-geldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutlar', 'bulutlar-hudayi-can-x3cpl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Her yaz gelin olup, 

Her sonbahar ağlayan

Bulutlarım var.

	Bulutlara bağlı, 

	Bulutlarla güzel, 

	Umutlarım var.

Hayallerimi sarar, 

Benliğimi kaplar.

Beyaz  bulutlar, 

Gri  bulutlar...', 'Her yaz gelin olup,  Her sonbahar ağlayan Bulutlarım var. 	Bulutlara bağlı,  	Bulutlarla güzel,  	Umutlarım var. Hayallerimi sarar,  Benliği...', ARRAY['Türk Edebiyatı','Şiir','Hüdayi Can']::text[], 8.5, '{"poet":"Hüdayi Can","poet_slug":"hudayi-can","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bulutlar-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığa Türkü', 'yalnizliga-turku-hudayi-can-679qo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün doğarken sönen son yıldız kadar; 

Erken açan çiçek kadar yalnızım.

Büyür içimde sebebsiz bir keder, 

Sonra bir his beni sarar, yalnızım.

Issız ovada yalnız tepe gibi, 

Ya da okyanusta yalnız adacık; 

Adam okyanusta habbe misali, 

Tepe ovanın içinde ufacık.

Beklerim dört gözle her gün akşamı, 

Belki yarın ümitlenirim diye.

Yarın bürür beni yarının gamı, 

Ertesi gün demek kalır geriye.', 'Gün doğarken sönen son yıldız kadar;  Erken açan çiçek kadar yalnızım. Büyür içimde sebebsiz bir keder,  Sonra bir his beni sarar, yalnızım....', ARRAY['Türk Edebiyatı','Şiir','Hüdayi Can']::text[], 8.5, '{"poet":"Hüdayi Can","poet_slug":"hudayi-can","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalnizliga-turku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayram Mektubu', 'bayram-mektubu-hudayi-can-7074f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdi nerdesin anne? 

Yine, yatılı okul pencerelerinden seyredilen yıldızlarda mı, 

Yoksa gurbet gecelerinde dinlenen 

Anneli şarkılarda mısın? 

Yavrum aç mı susuz mu, diye

Üstü mü açıldı uykusuz mu, diye

Yine, geceler boyu kaygılarda mısın? 

Ama ben biliyorum anne! 

Nerede olursan ol, 

Bütün anneler gibi

En büyük fedakarlıklarını vazife

Küçücük tebessümlerimizi dahi lütuf sayarsın.

Lütfedip gelir mi diye yavrularım

Yolları gözlersin her gün.

Ve yine biliyorum.

Sen beklemeyi iyi bilirsin anne.

Ne zaman köye gitsem; 

Ya “Bu gün düşümde görmüştüm.”

Ya “Geleceğin içime doğmuştu.” dersin.

Demek, hep yolları gözlersin.

Derdin ki; “Yola bakmak, yere bakmaktan iyidir.”

Sen, ikisini de iyi bilirsin anne.

On parça olmuş yüreğin; 

Üçü yere, yedisi yola bakar.

Her yıl koyunların kuzular, 

Koçların gider sonra her yıl.

Koç yiğitlerin de hep gidiyor koçların gibi.

Kimi yola, kimi yere...

Ve, hep ağlarsın gidenlerin ardından, 

Her gidenin, her gidişinde yeniden.

Sen, ağlamayı iyi bilirsin anne.

Derinden “of” çekersin kuzularını otlatırken dağlarda

Boşalırsın, dolarsın her “of”ta on kez.

Özlemlerin vardır yürek dolusu

Ama, olamaz işte.

Bayram da olsa; 

“On”u bir araya gelemez yüreğinin.

Varsın olsun anne! 

Cennet ve önden gönderdiklerin...

-Hep dualarla beklediğin gibi-

Onlar da seni bekliyorlar kanımca...

Sen, sabretmeyi iyi bilirsin anne!', 'Şimdi nerdesin anne?  Yine, yatılı okul pencerelerinden seyredilen yıldızlarda mı,  Yoksa gurbet gecelerinde dinlenen  Anneli şarkılarda mıs...', ARRAY['Türk Edebiyatı','Şiir','Hüdayi Can']::text[], 8.5, '{"poet":"Hüdayi Can","poet_slug":"hudayi-can","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/bayram-mektubu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Mektubu', 'bahar-mektubu-hudayi-can-uo0tc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Fatma’ya

Yine bir bahar geldi

Yine bir bahar gönder.

Baharınla yeşillendir perişan yaylasını gönlümün, 

Ve baharınla yaşadığımı bil bütün sonbaharlarda.

Yaşayabilmek diyorum, anladın.

Seninle gezdim nehir kıyılarında, sensiz

Seninle seyrettim yağmuru, sensiz

Sensizliğe alışmaya çalıştım, sensiz

Yokluğuna yine seninle alışıyorum.

Alışmaya çalışıyorum, anladın.

“Yaşamaya çalışmak” senin sözündü, hatırladın.

Yaşamaya alışmak, alışmaya çalışmak, 

Çalışmak... Evet çalışıyorsun, biliyorum; 

Alışacaksın biliyorum, anladın.

Yine bir bahar gönder.

Yine bir baharla gel.

Bir zarfa koy sevincini, rüyanı, 

Bir kağıda dök gayretini, ızdırabını, 

Ve bir bahar ol gel perişan yaylasına gönlümün, 

Seni seninle soylayalım, gel  baharınla

Gülünle, beyazınla, kokunla gel.

Gökkuşağını bohçala, ışık ol, gel aydınlat, 

Sonra açıl bütün renklerinle, 

Seni seninle görelim

Bir bahar ol gel, anladın.', 'Fatma’ya Yine bir bahar geldi Yine bir bahar gönder. Baharınla yeşillendir perişan yaylasını gönlümün,  Ve baharınla yaşadığımı bil bütün so...', ARRAY['Türk Edebiyatı','Şiir','Hüdayi Can']::text[], 8.5, '{"poet":"Hüdayi Can","poet_slug":"hudayi-can","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bahar-mektubu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurlu Mektup', 'yagmurlu-mektup-hudayi-can-xuc0a', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hilâl’e

Sen gittin, güz geldi İstanbul’a

Gözlerinle güz tohumları mı ektin sokaklara? 

Bulutlar gözlerinin buğusuna mı özendi? 

Benden bir şeyler mi kalsın dedin ya

Sen gittin de, güz geldi İstanbul’a.

Güz geldi... hem gözümün içine baka baka geldi.

Önce yağmurunu çiseledi, toprağıyla koka koka geldi.

Sirkeci’de savrulmaya başladı yağmur, 

Sarayburnu’nda kıyıya kıyıya vurdu dalgalar.

Damlalarını gözüme gözüme, 

Dalgalarını kıyıya kıyıya vururken sonbahar

Sen geldin aklıma.

 Zaten aklımdaydın ya...

Bu sefer güzünle geldin.

Aydınlık çiseleyen yüzünle, sonbaharlardan bahar damıtan gözünle geldin.

Taksim’de kuru çınar yaprakları savruldu önümde

Ve ben savruldum, yüreğim savruldu hüzün sağanaklarıyla.

İstiklal Caddesinde ‘Şeyh Galip Kitabı’ aldım

Belki bir yol gösterir diye nasıl geçilir ateş denizinden.

‘...Sahi bütün güz yağışlarını toplasak Yerebatan Sarnıcı’nda

Üstüne hüzünlerimizi, melallerimizi, gamlarımızı eklesek

O ateşten denizi söndürebilir mi, hani üstünden aşmamız gereken? 

Ve sonbaharların bütün rüzgarlarını 

içimizde kopan fırtınalarla beraber üflesek iki hisarın arasından

Mumdan gemimiz ulaşır mı menzil-i maksuda? ..’

Dedim ya...

Sen gittin güz geldi gönül iklimime, 

Güzü seversin, bilerek mi yaptın bunu bana? 

Gözümde  sarı yapraklar uçuşur, hayalhanemde taze hatıralar, 

Gözlerin sonbahar tohumları ekerler ıslak bakışlarıyla, 

Yüzün aydınlığında damıtır bu ıslaklığı bahar takları kurar, 

Eleğimsağmalar çatar kara bulutlar meskeni göğüme

Gök açılır, ben her gece yıldızlara bakarım.

Ki biri daha vardır, yıldızlara bakar, 

Biri daha vardır, yıldızlara bakar, der...', 'Hilâl’e Sen gittin, güz geldi İstanbul’a Gözlerinle güz tohumları mı ektin sokaklara?  Bulutlar gözlerinin buğusuna mı özendi?  Benden bir ş...', ARRAY['Türk Edebiyatı','Şiir','Hüdayi Can']::text[], 8.5, '{"poet":"Hüdayi Can","poet_slug":"hudayi-can","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yagmurlu-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sekiz Mart Övgüsü', 'sekiz-mart-ovgusu-hudayi-can-3uvf8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şüphesiz, bir elmanın iki yarısı

Suya düşmüş gölgesi mi Narsis’in

Suya gölge düşünce, dağa duman, 

Yaprağa düşüşü gibi şebnemin

Düşüverir hayale bir nazenin.

Her kış sonu yeni bir başlangıçtır.

Tomurcuk patlar, kuru dal dirilir, 

Bütün sekiz martlar büyür yıl boyu, 

Baharı emerek büyür çiçekler, 

Münbit toprak ananın kollarında.

Ve...

Bahar içre bahar siz varsınız, 

Gönül genişliğiniz yayla ufku, 

Yüceliğine dağlar kadarsınız.

Kuşatır bakışlarınız dört yönden, 

İkliminizde buhar buharsınız, 

Baharlayın hayali sararsınız.

Kaygılar doğar hüzünlerinizden, 

Ve tebessümünüzden mutluluklar...

Şefkatli anne, mihriban kız kardeş, 

Gönül kuşunun kanadı yarsınız.

Şatlık-neşe dağıtmakta ber-karar, 

Bahtiyar eden bahtiyarlarsınız.

Her sekiz mart, her ilkbahar ve her yıl, 

Tarhınız gülle, sümbülle, laleyle, 

Yürekleriniz saadetle dolsun.

Gerçekten sizi sevindiryorsa, 

Her yılın her günü sekiz mart olsun.

Ki siz, müşfik annesiniz büyüten, 

Anlayan hemşire, seven yarsınız, 

Bahtiyar eden bahtiyarlarsınız.

(8 Mart 99)', 'Şüphesiz, bir elmanın iki yarısı Suya düşmüş gölgesi mi Narsis’in Suya gölge düşünce, dağa duman,  Yaprağa düşüşü gibi şebnemin Düşüverir ha...', ARRAY['Türk Edebiyatı','Şiir','Hüdayi Can']::text[], 8.5, '{"poet":"Hüdayi Can","poet_slug":"hudayi-can","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sekiz-mart-ovgusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-cem-arifoglu-lstnv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün biter çöker gecenin perdesi

Gamlı bir baykuş kalır geceye bekçi

Devrederken nöbeti bülbüle

Anlatır senin uykunda göremediklerini

Şimdi dinle ey peri güzeli

Keşke baykuş olsaydımda anlatabilseydim bülbüle seni', 'Gün biter çöker gecenin perdesi Gamlı bir baykuş kalır geceye bekçi Devrederken nöbeti bülbüle Anlatır senin uykunda göremediklerini Şimdi d...', ARRAY['Türk Edebiyatı','Şiir','Cem Arifoğlu']::text[], 8.5, '{"poet":"Cem Arifoğlu","poet_slug":"cem-arifoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gece-62-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Senden Geçemiyorum...', 'ben-senden-gecemiyorum-alim-vedat-suner-aoz0h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bugün kendimin bile anlayamadığı

saçma bir dilden konuşuyorum

anlamsız tavırlarda

seni yazamak istiyorum

kalın puntolu harflerle

gönlümün deniz fenerine

anlamsız çığlıklarımla

sağır çan zangoçunu bile üzüyorum

zamansız iç çekişlerimde

rüzgarı kesiyorum

ne yazarsam yazayım

kendimi anlatamıyorum

ben kendimde senden geçemiyorum', 'bugün kendimin bile anlayamadığı saçma bir dilden konuşuyorum anlamsız tavırlarda seni yazamak istiyorum kalın puntolu harflerle gönlümün de...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-senden-gecemiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıların Tanımsızdı', 'acilarin-tanimsizdi-alim-vedat-suner-00x9i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaralı bir kuştun

Kondun omzuma

Yaraların yardan yadigar

Acılarınsa tanımsızdı

Soğukla bir olmuştun

Sardım kollarımda

Anıların geçmişinden kalmıştı

Bugün''se bende yaşattın

(Sevgili insan Itır''a)', 'Yaralı bir kuştun Kondun omzuma Yaraların yardan yadigar Acılarınsa tanımsızdı Soğukla bir olmuştun Sardım kollarımda Anıların geçmişinden k...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/acilarin-tanimsizdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acıların Adamı', 'acilarin-adami-erdogan-ciray-fc0rq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sözlerine kanmıştın

Acıların Adamı

Sevdasına yanmıştın

Acıların Adamı

Duymaz gönül çağrını

Dindirmez kalp ağrını

Başkasına bakar da

Yakar senin bağrını

Yaraların derinmiş

Acıların Adamı

Ayrılık kaderinmiş 

Acıların Adamı', 'Sözlerine kanmıştın Acıların Adamı Sevdasına yanmıştın Acıların Adamı Duymaz gönül çağrını Dindirmez kalp ağrını Başkasına bakar da Yakar se...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çıray']::text[], 8.5, '{"poet":"Erdoğan Çıray","poet_slug":"erdogan-ciray","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/acilarin-adami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adamı...', 'adami-alim-vedat-suner-vz99x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bacaklarım titriyor

Gözlerim yanıyor

Senin de çekip gidişin

Adamı can evinden vuruyor

Ellerim üşüyor

Sözlerim susuyor

Seni de son kez görmek

Adamı harap ediyor

Dilim tutuluyor

kanım donuyor

Senin de ''Elveda'' sözün

Adamı yok ediyor

(21.01.2003 / Salı)  

 (Dostum Itır''a)', 'Bacaklarım titriyor Gözlerim yanıyor Senin de çekip gidişin Adamı can evinden vuruyor Ellerim üşüyor Sözlerim susuyor Seni de son kez görmek...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/adami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum Unutulmuyor Sevdiklerin', 'biliyorum-unutulmuyor-sevdiklerin-alim-vedat-suner-qzznt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dağılmış saçların, bırak toplama

Ellerin titrek ve soğuk, kaçırma

Biliyorum o ten değil şimdi tutan ellerini

Biliyorum unutulmuyor sevdiklerin', 'Dağılmış saçların, bırak toplama Ellerin titrek ve soğuk, kaçırma Biliyorum o ten değil şimdi tutan ellerini Biliyorum unutulmuyor sevdikler...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/biliyorum-unutulmuyor-sevdiklerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Kaldım', 'sende-kaldim-bir-garip-sair-wz4wt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'istanbul gözlerinde güzel

sıcak bir rüya bir şarkı

dudakların

seni unutmaya çalışsada

umutlarım

bu şehirde bir sevdam

bir sen

birde sana hasret

bedenim

kaldı

sende kaldım

sensiz ken', 'istanbul gözlerinde güzel sıcak bir rüya bir şarkı dudakların seni unutmaya çalışsada umutlarım bu şehirde bir sevdam bir sen birde sana has...', ARRAY['Türk Edebiyatı','Şiir','Bir Garip Şair']::text[], 8.5, '{"poet":"Bir Garip Şair","poet_slug":"bir-garip-sair","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sende-kaldim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki De Hiç Yoktun', 'belki-de-hic-yoktun-alim-vedat-suner-w1z0c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Acıttın yüreğimi

Sana bakan en mutlu günlerinde

Belki kısaydı

Belki anlamsızdı

Belki de büyükdü yüreğince

Ama hep soruydu, hep sorun

Bir çoban kavalı kadar yanıkdı

Dilimizde dolanan kelimeler

Belki anlamadı kimse

Belki anlamsızdı herkezce

Belkide kimse sevmemişti seni

Sana benim kadar değer vermemişti

Belki korktun sevgiden

Belkide hiç yoktun

                 gecelerimde...

(22.01.2003 / Çarşamba)

 (Dostum Itır''a)', 'Acıttın yüreğimi Sana bakan en mutlu günlerinde Belki kısaydı Belki anlamsızdı Belki de büyükdü yüreğince Ama hep soruydu, hep sorun Bir çob...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/belki-de-hic-yoktun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Rüya', 'buyuk-ruya-alim-vedat-suner-qrzq1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yitirilmiş sevgilerini gördüm

Silinmiş acılarını günlerinde

Hep güler bir yüzü

Ağlayan bir yüreği gördüm sende

Ben senle büyük rüya gördüm...

(21.01.2003 / Salı) 

 (Dostum Itır''a)', 'Yitirilmiş sevgilerini gördüm Silinmiş acılarını günlerinde Hep güler bir yüzü Ağlayan bir yüreği gördüm sende Ben senle büyük rüya gördüm.....', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/buyuk-ruya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke''li Zamanlar', 'keske-li-zamanlar-alim-vedat-suner-isor3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'keşke sevmeseydim seni ilk görüşte

keşke, ''Keşke''lere düşmeseydim

sende anlam kazandıkça

keşke görmeseydim gözlerini

keşke tutmsaydım ellerini

keşke seni dünden daha az sevseydim

yada sen beni sevseydin

büyütmezdim elbet bende

çürümeye mahkum gonca gülü

(23.01.2003)', 'keşke sevmeseydim seni ilk görüşte keşke, ''Keşke''lere düşmeseydim sende anlam kazandıkça keşke görmeseydim gözlerini keşke tutmsaydım elleri...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/keske-li-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem Sevdiklerime', 'sitem-sevdiklerime-alim-vedat-suner-ogjs8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gayri güvenim kalmadı günüme

Hep talan oldu yüreğim

Ketum kişilerde

Umudum yok gayri sevgiden

Hep acıyla doldum

Yalan kişilerde

(22.01.2003)', 'Gayri güvenim kalmadı günüme Hep talan oldu yüreğim Ketum kişilerde Umudum yok gayri sevgiden Hep acıyla doldum Yalan kişilerde (22.01.2003)...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sitem-sevdiklerime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gidince', 'sen-gidince-alim-vedat-suner-uoowc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'nerdesin acep

seni çok özledim

ürkek bir adamdım

sana bakarken

ellerin ellerimde

kristal bardak kadar narindi

nerdesin şimdi

senin yerin hala boş

dürümleri yapmak için

haydar usta bekliyor

kahveleri vermek için

o güzel ve tatlı kız tetikde

gelişinle hayat canlanacak

gidişinle şehrim boşalacak

ne haydar nede güzel kız...

tadı kalmayacak hiçbirşeyin..

Sen Gidince..

(23.01.2003)', 'nerdesin acep seni çok özledim ürkek bir adamdım sana bakarken ellerin ellerimde kristal bardak kadar narindi nerdesin şimdi senin yerin hal...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-gidince-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ve Ben', 'sen-ve-ben-mahir-okan-kahraman-rben7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen dünyanın ötesinde parlak bi yıldız 

Ben sönmüş bi göktaşı

Sen bahar serinliğinde yağan yağmur

Ben suya hasret çorak bi toprak

Sen hatıralırım 

Ben umutların detayı

Sen yıllardır açamadığım kalbimin anahtarı

Ben bi çilingir ustası

Sen memleketine hasret çeken sürgün

Ben mapusda sana hasret bi tutsak

Sen benim onurum

Sen benim sveincim 

Sen sen....sen benim herşeyim

1999    Kars', 'Sen dünyanın ötesinde parlak bi yıldız  Ben sönmüş bi göktaşı Sen bahar serinliğinde yağan yağmur Ben suya hasret çorak bi toprak Sen hatıra...', ARRAY['Türk Edebiyatı','Şiir','Mahir Okan Kahraman']::text[], 8.5, '{"poet":"Mahir Okan Kahraman","poet_slug":"mahir-okan-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-ve-ben-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönülçelen', 'gonulcelen-fazli-cinar-g6o3d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çekilinerek söylenemeyen sözlerde gizlidir

En güzeli ve en safı tek yönlü sevdaların

Belki bir bölü ikisi çocuksuluktan

Belki olgunlaşmanın

Can sıkıcı gözetiminde

Utancın aydınlattığı kirli yolda

Sabaha kadar

Ama gece yanlısı

Pişmanlığın pişmanlık kusan eşliğinde

Çaresizlikle beraberken

Yapılamayan şeyler

Yalnızlığımla başbaşa

Sana nazır

Teklik kıvamında

Yanına sensizlik sıkılmış

Boş kağıt misali

Herşey olmaya hazır

Karşılıksız bir aşk üzerine yazılmış bu şiir

En gerçek ve en acıtan sevdadır

Benim yaşadığım

Ve tek bildik tanığıdır aynı zamanda

Faili meçhul sevdalarımın

Ki henüz failde sevdadan meçhul

                                                                      ukumi''ye

(c)   Bu şiirin her türlü telif hakkı şairin kendisine ve / veya temsilcilerine aittir.', 'Çekilinerek söylenemeyen sözlerde gizlidir En güzeli ve en safı tek yönlü sevdaların Belki bir bölü ikisi çocuksuluktan Belki olgunlaşmanın ...', ARRAY['Türk Edebiyatı','Şiir','Fazlı Çınar']::text[], 8.5, '{"poet":"Fazlı Çınar","poet_slug":"fazli-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gonulcelen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-muhsin-halis-a1i50', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu bin ikinci gece

Şehrazat ayinlerinin ardından

Bütün masallarım bitti

Senin alkışla dinlediğin

Fakat ey aşk aşikar sen göründün

Sırrına erince gerçeğin

Ben seni kazandım

Heyhat! Sen kazandın', 'Bu bin ikinci gece Şehrazat ayinlerinin ardından Bütün masallarım bitti Senin alkışla dinlediğin Fakat ey aşk aşikar sen göründün Sırrına er...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Halis']::text[], 8.5, '{"poet":"Muhsin Halis","poet_slug":"muhsin-halis","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-129-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karadeniz Kıyısında', 'karadeniz-kiyisinda-tuncay-emrem-x99xq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kollarımı açsam

Uçsam

Bir kartal gibi

Karadenize doğru..

Ufuklar var karşımda geniş, 

Ufuklar çepçevre..

Bitsin artık  bu bekleyiş, 

Bitsin artık bu susuzluğum.

Ben böyle her akşam hasretle dolu, 

Bekleyecek miyim 

Sahillerinde Karadenizin? 

Alın beni, 

Sarın beni, serin sular.

Rüzgârlar mıdır, 

Dalgalar mıdır götürecek? 

Yağmurlar mıdır- sağnak sağnak-

Ümitler midir, 

Mevsimler midir? ..

Karadenizin fırtınalarına kapılsam, 

Karadenizin koynunda kaybolsam..

Kuşlar gider gönlüm gibi, 

Gemiler gider, 

Güneşler gider..

Ben kalırım..

Ben kalırım sanma sakın! 

Sıradağlar yürüyecek neredeyse karadenize..

Beni de alın, 

Beni de alın..

Bir sabah sökerken şafak, 

Yerimden doğrulacağım..

Esatiri bir dev gibi, 

Mavi sulara basarak, 

Ağır ağır, 

Ufka doğru gideceğim, 

Sonsuzluğu içeceğim...

Evet bu, 

Muhakkak!', 'Kollarımı açsam Uçsam Bir kartal gibi Karadenize doğru.. Ufuklar var karşımda geniş,  Ufuklar çepçevre.. Bitsin artık  bu bekleyiş,  Bitsin ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Emrem']::text[], 8.5, '{"poet":"Tuncay Emrem","poet_slug":"tuncay-emrem","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/karadeniz-kiyisinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost', 'dost-muhsin-halis-hiql0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir güzîde duadır seherin serininde, 

İntizârım tiretir üşüyen ellerimi.

Ey Sübhânım gönlümün en nâdide yerinde

Büyüte durdum, ki duy sevdamı kederimi

Bu âlem gözlerimde görünmez bir örtüdür

Ve bu âlem zihnimde susmayan gürültüdür

Bir beraat diliyor rahmetinden ellerim

Kapında perişanım, katında derbederim.

Cânan desem gönlümde yankılanır adın yar! 

Bir şafak aydınlığı sunarsın gözlerime.

Senden başka âhımı, feryadımı kim duyar, 

Kim döker, senden başka, suyu denizlerime..

Senin için her seher bir uyanık kulunum

Şanına mülteci bir bağrı yanık kulunum.

Bütün cevr-û cefayı bildim sensin yaratan

Senden uzağa atıp sonra seni aratan.

Her gece benimledir mehtap, deniz yıldızlar..

Sana el açar hergün tüm bâhtiyar yalnızlar.

Âlemin gündüzünden seni okur Kitabım

Bir derviş edasında susuzluktan bî-tàbım.

Rahmetin süzgecinden süzülmüş bir yağmur sun, 

Yıkılsın metal zevkler, bitiversin inkîsar.

Sen büyük sahraları diriltecek yağmursun

Bir âlem sende biter, bin âlem sende başlar.

Bir med zamanı baktım gurûba uzun, uzun.

Faniliğim titredi heybetinden sonsuzun

En sevgili, en lâtif, en güzîdesin Ey Dost

Bilmemki bu âlemin neresindesin Ey Dost.

Gitme! Kal! Diyebilsem, yerinde dursa zaman.

Beni avuçlarında şanına sunsa zaman

Álemi çepe çevre kuşatan gecelerden

Şûlesi sızar günün, dualarımca berrak

Yalvarışım hıçkırır, fikrim boğulur terden.

Sonra, üşür dileğim, titrerim yaprak yaprak.

Duygumun göklerinde duydum Rahman’ım  seni

Gönlümü bir efsûna saldı aklıma düşen.

Hurma yapraklarına nakşedilen sesini

Okur; dudaklar nasır.. Okur; gönüller gülşen

Ne varsa senden yana bu âlemde gördüğüm; 

Ve ayrılık.. Ve gurbet.. Yolumda düğüm düğüm.

Mademki senden geldi azizdir bu ayrılık

Dua döker gözlerim toprağa ılık ılık.

Durup seni dinlerim muzdarip denizlerden.

Sana gelmek isterim şu garip denizlerden.

Bana ümit bahşeden tatlı sesindi Ey Dost.

Bir çocuk heyecanı ruhuma sindi Ey Dost.

Ne güzel hilkâtinin alnıma yaktığı nûr

Kuraklığıma yağmur yalnız sende bulunur.

Melûl gözlerim yalnız sana hasretten yandı

Gönlüm gayrî sevdaya ne düştü, ne bağlandı.

Yağmur damlalarını dinledim bildim ey Hak

Bildim sensin hakikat, sensin Mahbub-u Mutlak

Râbıtamın müntehâ ufkundaki Çalab’sın

En müstesnâ âhenkle âlemi düzen Râb’sın

Ağlarım şu bitmeyen firâkın derininde

Anlamaya takâtim yetmezcesine Ak’sın

Sevdanı kanar güneş her sabah serininde

Sonsuz aczimle bildim, Sen Kadir-i Mutlak’sın', 'Bir güzîde duadır seherin serininde,  İntizârım tiretir üşüyen ellerimi. Ey Sübhânım gönlümün en nâdide yerinde Büyüte durdum, ki duy sevdam...', ARRAY['Türk Edebiyatı','Şiir','Muhsin Halis']::text[], 8.5, '{"poet":"Muhsin Halis","poet_slug":"muhsin-halis","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/dost-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askere Gidiş', 'askere-gidis-tuncay-emrem-o8wes', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bahar kıyıları sislidir, bekliyor yazı.

Yeşeren bahçelerde uyanışın hazzı, 

Rüzgârda bir okşayış, vadesi vuslatın..

Bir derin sükunete varmış gibi deniz, 

İstanbulu böyle bir günde terketmekteyiz.

Kalanlara evlerinin kadrini anlatın..

Çiçekli dalların ardında tül perdeler, 

Benim gibi gidenlere neler söylemekteler..

Elveda ey sevgili, mahzun bakışlı kadın.!

                                   Hahdarpaşa 1959', 'Bahar kıyıları sislidir, bekliyor yazı. Yeşeren bahçelerde uyanışın hazzı,  Rüzgârda bir okşayış, vadesi vuslatın.. Bir derin sükunete varmı...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Emrem']::text[], 8.5, '{"poet":"Tuncay Emrem","poet_slug":"tuncay-emrem","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/askere-gidis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanlızlık', 'yanlizlik-tuncay-emrem-ap87t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yanlızlık aksimi gördüğüm kuyu, 

Çevremde insanlar, mumdan heykeller.! 

Sarıl yorganına, yıllarca uyu..

Aklında kalmasın, ne zaman, ne yer.! 

Bir ömür tükettin böyle yollarda.

Nedir aradığın, bu kaçış kimden? 

Tohumu savurdun boşa rüzgârda, 

Hepsinden bir orman yeşertecekken..

Fırtınalar sürüklüyor yorgun gemiyi.

Ufukta ne liman, ne de fener var.

Eğer bir gün sahile varırsa iyi..

Şimdi yalnız duyulan, azgın dalgalar...

                                             Stuttgart  1972', 'Yanlızlık aksimi gördüğüm kuyu,  Çevremde insanlar, mumdan heykeller.!  Sarıl yorganına, yıllarca uyu.. Aklında kalmasın, ne zaman, ne yer.!...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Emrem']::text[], 8.5, '{"poet":"Tuncay Emrem","poet_slug":"tuncay-emrem","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yanlizlik-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karantina', 'karantina-ali-kalayci-cre5u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Anonim hüzünlerini infaz gecelerinin

himaye hakkın devletleştirildi.

Umutlarından uzaklaştırıldın

kuru ekmek, kuru sevda tüketicilerinin 

Dağlarından yar dudağına

cop ve panzer zoruyla

olanca şerrin, olanca mahzunluğunla

yasaklandın.

Mührüne el koydular 

Varın eğlenin gün sizin gayrı

sermaye borsalarıyla bakışık

yıldız tabirleri, öncü iftiralar.

      

Oysa hiç yüz vemedin

çıldırtan utkusuna kavgaların

Kaç mayıstır 

yangılı yerlerinde denenen eczalara

tahammüllüydün

ve ürpertmiş değildin

çalımlı fotoğraflarını kırantaların.

Şehrin imtiyazlı duvarlarında

kalaşinkof biçiminde onaylanan adın, 

çiğ ışıklarla pusturulmuş bulvarlarda  

namuslu sloganlar yüklenerek 

yürüyen insanları zapt etmek için      

hızla çoğaltılırken istihbarat raporlarında

sen en tarafsız ifadenle                    

bekledin / sadece bekledin

eyvahlanarak korsan hayatlarına            

ölen kardeşlerinin 

Bitti. her şey bitti artık

bitti maviş belemirlerle arandaki kontrat       

ne hainliğin kaldı

ne çırpıcılığın

bitti koşturmaca

hükümsüzdür artık eşkıyalığın  

baban açlıktan ölse de

kinlenmeye yetkisizsin

paşa topraklarında boylanan sümbülelere

tütün ve tuz etmez çarşılarda selamın

şanın dillendiğiyle kalır mütevazı türkülerde.

1986', 'Anonim hüzünlerini infaz gecelerinin himaye hakkın devletleştirildi. Umutlarından uzaklaştırıldın kuru ekmek, kuru sevda tüketicilerinin  Da...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalaycı']::text[], 8.5, '{"poet":"Ali Kalaycı","poet_slug":"ali-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/karantina-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gök Kubbe Altındaki Ebedi Ser-i Hoş', 'sen-gok-kubbe-altindaki-ebedi-ser-i-hos-sukru-yildiz-m0riw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eflatun yarime

Canıma bir cem sun ey saki

Senden başka yok ki bu dünyada baki

Sen gök kubbe altındaki ebedi ser-i hoş

Ben senin bedeninde lal olmuş sarhoş

Nice ah çekerim her gece ben

Dili ateşten özge yar elinden

Bir buse versin diye ela gözünden

Kaç gün devirdim bilir misin ömrümden

Nefsine sığmaz gözlerden yaşlar dökülür

Her haberde gül diken olur, eflatun görülür

O ne bahtiyar andır ki onda örülür

Onsuz geçen anlar ölüm olur, görünür

Gözleri, gözlerime yay olur, oku dokunur ahu zar olur

Bu bedendeki can onu görünce gider, canan olur

Ol kafesteki bülbül susar, matemime yar olur

Cennetin ırmakları akmaz, deyü yol dar olur.

Ben giderim o gelir, hayat bir daha çözülür, can canan olur

Bedenime dokunan onun teni, derdime derman olur

Görmez isem bir gün, derdim azar,  azman olur

Gülünce gönlümdeki ateş dansa durmuş eflatun olur', 'Eflatun yarime Canıma bir cem sun ey saki Senden başka yok ki bu dünyada baki Sen gök kubbe altındaki ebedi ser-i hoş Ben senin bedeninde la...', ARRAY['Türk Edebiyatı','Şiir','Şükrü Yıldız']::text[], 8.5, '{"poet":"Şükrü Yıldız","poet_slug":"sukru-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-gok-kubbe-altindaki-ebedi-ser-i-hos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mülâkat', 'mul-kat-muhtesem-oksel-svucr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllar boyu okursun, 

Adam olacağım diye.

Sonunda, adam olursun.

Onca kitap devirirsin.

Yazarsın, çizersin.

Günü gelir, mezun olursun.

Mezun olmasına olursun da, 

Yetmez derler.

Zira, vatan hizmet bekler.

Asker olursun, 

Aylar geçer.

Terhis olursun.

Şimdi erkek oldun derler.

Ama, işsiz erkek olursun.

Dayanırsın bir işletmenin kapısına

Ya da devlet kapısına

İş ararsın.

Dur bakalım! olmaz derler.

Sırayla değil, sınavla.

Öyle mi? dersin.

Girersin yazılı sınava.

Birinciliği kazanırsın, 

Açık ara farkla.

Tamam mı? dersin, 

Bitmedi, derler.

Çağırırlar seni mülâkata.

Az buçuk biriktirdiğin

Cebindeki tüm parayı, 

Yatırırsın bir kat kumaşa.

İki dirhem, bir çekirdek, 

Gezinirsin markalı takımlarla.

Mülâkat günü gelir, 

Toplanır adaylar bir odada.

Şans, oldukça yüksek.

Dört aday arasından, 

Üç aday seçilecek.

Solumdaki aday, tam bir afet.

İsmini hatırlayamadım, ancak, 

Biz ona diyelim “bayan güzel bacak”

Yavrum giymişsen o eteği, 

Çekiştirmene ne gerek? 

Allah’ım bana acı

Dayanmaz buna yürek.

Sağımdaki aday, yakışıklı mı yakışıklı

Hani kızlar der ya, ay bebek! 

Mütebessim bakıyor, 

Çok belli, arkadaş heyecanlı.

Attım elimi yüzüme, 

Benimkisi çok sert hatlı.

Onun bir yanındaki, pek bir sıradan.

Ama, galiba torpilli.

Yoksa heyet üyelerinin

Göz tikleri, 

Götürecek işi sonunda, anlaşılan.

İsmi üzerinde, mülâkat bu.

İzler soru, soruyu.

Cevaplarsın hepsini.

Mutludur için.

Bozmamalı kalbini.

Bu işin hakkı, birincinin.

Derken, mülâkat biter.

Geçer günler, geceler.

Beklersin gelmez, 

Ne bir ses, ne bir haber.

Yapı hâliyle sabırsız, 

Dayanamazsın, ararsın, 

Maalesef olmadı derler.

Hem niye ararsın? 

Diye fırça çekerler.

Aramıyorsak biz, 

Belli ki kaybetmişsin, 

Bana bak ulan şerefsiz! 

Keyfin yerinde, 

Denk her bir yanın.

O koltuğa kurulmuşsun, 

Kendini adam mı sandın! 

Kapatırsın telefonu.

Bakarsın aynaya, 

Ayna bakar sana.

Düşünürsün, 

Elde olan, malzeme bu. 

Kaderimiz midir acaba? 

Kazanıp cephede, 

Masada kaybetmek.

Şekilsiz bacaklarda mı sorun? 

Eğer mülâkatı kaybettiysek.

Gelin de bu işe bir çare bulun.

Yoksa bu yaştan sonra, 

Eğilimleri mi değiştirsek?', 'Yıllar boyu okursun,  Adam olacağım diye. Sonunda, adam olursun. Onca kitap devirirsin. Yazarsın, çizersin. Günü gelir, mezun olursun. Mezun...', ARRAY['Türk Edebiyatı','Şiir','Muhteşem Oksel']::text[], 8.5, '{"poet":"Muhteşem Oksel","poet_slug":"muhtesem-oksel","theme":"Türk Şiiri","is_hero":false,"total_lines":89,"source_url":"https://www.antoloji.com/mulakat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklı Saat', 'sakli-saat-seyit-piran-rco58', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir  takvim  yaprağıydım, vaktinden  önce  koparılmış

üstümde temmuz yazıyordu, dışarısı tipi, dışarısı kar-kış

kolay

değildi

elbet

enel

hak

diyen

yolculuğa

sığınmak

en olmadık yerde taşıyordu içimdeki dalgın ırmak

çilemin  son dersinde, pirim benden kan istiyordu

girdim

aşkın

kapısından

içeri

kan

isti

yordu

gözlerimi

kapadım dergahımı, sesimi kamçıladım, düşümü inkar kıldım

çocuklarını unutup cellatlarla sevişen bu  dünyadan sıkıldım.', 'bir  takvim  yaprağıydım, vaktinden  önce  koparılmış üstümde temmuz yazıyordu, dışarısı tipi, dışarısı kar-kış kolay değildi elbet enel hak...', ARRAY['Türk Edebiyatı','Şiir','Seyit Piran']::text[], 8.5, '{"poet":"Seyit Piran","poet_slug":"seyit-piran","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sakli-saat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimizdeki Matkap', 'i-cimizdeki-matkap-seyit-piran-ezxmw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '.I.

Alt tarafı hayat’la gelip anlattım sırlarımı, 

Yol gösterdim bir rüzgarın saçlarına, kıvrımına, 

Presten yeni çıkmıştı insanların sesleri, zangırtıları

Alt tarafı insan’la gelip anlattım anladıklarımı.

Bir düş yol gösterdi gelirken, bir gece tütün...

İçimde bir matkap ki kan kıvamındaydı büsbütün

Asyalı bir griden doğdum, soluğum Avesta, düşlerim RA

Ama sen olmayınca düşüyorum işte, mektuplara, yollara.

Hangi durak bir öncekinden iyi, bir sonraki kadar

Soncu’yu tarif ediyorlar beni nerde görseler

Hangi suçu gerektirir bu murdar dünyadan sürgünlük

Sözüm hangi çadırdan, gözlerim kaç küsür günlük

.II.

Dağlanmış tay resimleri olurdu, kıpırtısızdı sirenler

Okçular tedbirli ve belirsiz, okçular dumandaydılar

Trenler ateş içindeydi, çok yazıklı, puslu trenler

Alt tarafı hayat’la yüzyüzeydi, tehlikeliydi gidenler

Neydik ki düzeni bozulmuş sevdalı adamlardan başka

Bir kenti bulantısı ve uğultuyla yine de kadınlarıyla

Yani katlanmış mendil numarası yapan kadınlarıyla

Bırakıp başbaşa katılırdık  sarsıntılı bir davaya.

.III.

Ben bu bünyeyle neleri bekledim, neler bekledi beni

Beynimde çapa yapıcıları her gece  bam güm

İçimde bir matkap, yağsız, görülmedi güldüğüm

Bu nazlı gıcırtı, bu saten, neleri bekledim ben.

Limon ağaçları eksildi sesimden, karardı muskam

Aynı yerden düştük, gül ve Koçgiri belirdi göğsümde

Kanıma karıştı ruhum, kıvılcımları gördüm bir an

Matkabın ucu kırıldı, anladım, yüreğimdi sınanan.', '.I. Alt tarafı hayat’la gelip anlattım sırlarımı,  Yol gösterdim bir rüzgarın saçlarına, kıvrımına,  Presten yeni çıkmıştı insanların sesler...', ARRAY['Türk Edebiyatı','Şiir','Seyit Piran']::text[], 8.5, '{"poet":"Seyit Piran","poet_slug":"seyit-piran","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/icimizdeki-matkap-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmak', 'olmak-birol-akbaba-4e0nb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'aşıka sormuşlar, 

ey aşık! gül mü olmak isterdin bülbül mü? 

aşık demiş; 

gül olsam gönül ararım açmak için

bülbül olsam dal ararım konmak için

ben hem gülüm hem bülbül

gönül de benim dal da benim

gül bulurum gönül olurum

dal bulurum bülbül olurum', 'aşıka sormuşlar,  ey aşık! gül mü olmak isterdin bülbül mü?  aşık demiş;  gül olsam gönül ararım açmak için bülbül olsam dal ararım konmak i...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/olmak-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-birol-akbaba-v93bp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'dediler sevgiyle yandı tutuştu

ömrünce sevgiyle söyledi konuştu 

görünce aşıkını deloldu karıştı

ney söyledi nefes oldu yatıştı

çalsın kudüm vursun davul dengine

deli gönül düştü ıssız engine

seherde öten garip bülbüle

ney söyledi nefes oldu yatıştı

su oldu dereler boyu çağladı

can sende canan dedi ağladı

senden ayrı yüreğini dağladı

ney söyledi nefes oldu yatıştı', 'dediler sevgiyle yandı tutuştu ömrünce sevgiyle söyledi konuştu  görünce aşıkını deloldu karıştı ney söyledi nefes oldu yatıştı çalsın kudüm...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-130-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ABİME', 'abi-me-i-kbal-senturk-91r72', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kaza haberi geldiğinde annemler sofradaymış, 

öylece bırakıp yollara koyulmuşlar

sofralarımız artık hep yarım 

ne yapsak doymuyor karnımız

bana geldiklerinde uyuyordum

o gün yarılandı uykularım, 

artık eskisi gibi uyku girmiyor 

gözlerime

bir hüzün yerleşti, 

en sevinçli anımızda cıkıveriyor saklandığı yerden

bir yanımız hüzün oldu bizim

gizlice bir anlaşma yaptık, kim ağlarsa o gün

diğerleri susturuyor onu

bayramlarda yas ilan ettik

kimse bilmiyor aramızda yaptık bunları

yıl başlarını hiç sorma.......

senin dargın ayrıldıklarını affetmiyoruz

gidişinden sonra annemin tikleri başladı

bilirsin benden çok severdi seni

babam hala inanamıyor öldüğüne 

bu halleri korkutuyor beni

çocuklarınsa kendi kanına düşman oldular

ben aldırmıyorum, 

 yeter ki ben yaşadığım sürece bükülmesin boyunları

evine gidemez oldum, 

sanki cıkıverecekmişsin gibi

gülüşün geliyor aklıma, 

dayanmıyor yüreğim

olurda gidersem oralara, 

bir bahanne bulup doyasıya ağlıyorum 

sen gittin herşey yarım kaldı, 

ne yapsak tamamlanmıyor artık

bakma gülüp oynadığımıza, 

kanadımız kırık bizim, 

dünya gülse

eskisi gibi 

gülmüyor GÖZLERİMİZ', 'kaza haberi geldiğinde annemler sofradaymış,  öylece bırakıp yollara koyulmuşlar sofralarımız artık hep yarım  ne yapsak doymuyor karnımız b...', ARRAY['Türk Edebiyatı','Şiir','İkbal Şentürk']::text[], 8.5, '{"poet":"İkbal Şentürk","poet_slug":"i-kbal-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/abime-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir ben bir sen', 'bir-ben-bir-sen-birol-akbaba-9abzv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir gürgen yaprağı düştü dalından

sonbaharın tam ortasına

bir ben gördüm bir de  yıldız

bir damla düştü buluttan

kirpiğimin en ucuna

bir ben gördüm

bir de burnumun ucunda sen', 'bir gürgen yaprağı düştü dalından sonbaharın tam ortasına bir ben gördüm bir de  yıldız bir damla düştü buluttan kirpiğimin en ucuna bir ben...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-ben-bir-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkıp gelsen bir nisan akşamı', 'cikip-gelsen-bir-nisan-aksami-birol-akbaba-dkgsh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çıkıp gelsen bir nisan akşamı

çıkıp gelsen diyorum.

hiç beklemediğim bir anda

beklenmedik zamanda.

içimi seninle ısıttığım

seni yaşadığım o anda

tam zamanında

çıkıp gelsen diyorum

üşümüş ellerin avuçlarımda

ıslak saçların ve sen bahar tazeliğinde

alabildiğine güzelliğinle

çıkıp gelsen diyorum.

konuşmalıyız saatler boyubelki günlerce

aşk, aşk olmuyor sen olmayınca

gözümde ışık içimde nefes yok

çıkıp gelsen diyorum ansızın

ellerim duaya durmalı kalbim seni aleme duyurmalı

ilahlar anlamalı halimden sevgimi melekler kutsamalı

çıkıp gelsen diyorum bir akşam ansızın

yalnızlığın  acısını beraberce almalıyız zamandan

sözü bırak kalbin kalbimde olsun

seninle yaşayan canım al senin olsun

gözlerim gözlerini dinlesin

ruhum sevginle titresin

çıkıp gelsen diyorum 

bir nisan akşamı ansızın çıkıp gelsen

ötesi yok', 'çıkıp gelsen bir nisan akşamı çıkıp gelsen diyorum. hiç beklemediğim bir anda beklenmedik zamanda. içimi seninle ısıttığım seni yaşadığım o ...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/cikip-gelsen-bir-nisan-aksami-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dil sana bağlanalı', 'dil-sana-baglanali-birol-akbaba-perfg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dil sana bağlanalı 

oldu mecnun misali

gönül bir kuş oldu 

uçtu rüzgar misali

sende buldu dermanı 

coştu sular misali

vuslatı bekledi yandı 

yandı kerem misali', 'dil sana bağlanalı  oldu mecnun misali gönül bir kuş oldu  uçtu rüzgar misali sende buldu dermanı  coştu sular misali vuslatı bekledi yandı ...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dil-sana-baglanali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günaydın', 'gunaydin-birol-akbaba-5etuz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'çiğ yağmış çimenlerin mutluluğunu al, 

çiçeğe sevinen yaprağın sevincini, 

bülbül dosluğu yaşayan gülün kokusunu, 

papatyaların, gelinciklerin şarkılarını, 

sesimi, nefesimi, sevgimi, aşkımı al

günün aydın, yüreğin sevgi olsun', 'çiğ yağmış çimenlerin mutluluğunu al,  çiçeğe sevinen yaprağın sevincini,  bülbül dosluğu yaşayan gülün kokusunu,  papatyaların, gelincikler...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gunaydin-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gök-nur', 'gok-nur-birol-akbaba-ytuxo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ben sonsuzluğun şiiriyim

adım sevgi ile başlar

sevgi ile ısınır gönüller

gönüllerde bülbüller

hep seni söyler

ben sonsuzluğun şiiriyim

sözlerindir beni yaratan.

ben rüyadayım, ışığı sensin

sevginle coştum akıyorum

okyanus sensin.

İçimdeki çocukla barıştım, 

Sevdiği sensin.

Bir buse perisi oldum, 

İlhamı sensin.', 'ben sonsuzluğun şiiriyim adım sevgi ile başlar sevgi ile ısınır gönüller gönüllerde bülbüller hep seni söyler ben sonsuzluğun şiiriyim sözle...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gok-nur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ilk ben sevdim seni', 'ilk-ben-sevdim-seni-birol-akbaba-f66hp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ilk ben sevdim seni

ilk ben yazdım adını kalbime

savrulan küller gibi

uçacak sandığım düşlerim

gelişinle alevlendi gönlünce

ilk ben sevdim seni

ilk ben attım tohumunu sevginin

sonra sen yağdın üstüme

yağmurlarınla yeşerttin

ilk ben sevdim seni

sonra sen doğdun sabahlarıma

tamamlandı düşlerim

sonra; sonra ilk sevmenin azlığını gördüm

ilk ben sevdim seni

yollarını gözleyen ilk ben oldum

daha gün doğmadan 

son yıldızla başlayan özlemim

sesinle oldu, tükenmez sevincim

ilk ben sevdim senisonra sen beni

biteceğini bile bile rüyanın

anmak için sevgileri, sevinçleri

daldım içine bu eşsiz hülyanın

ilk ben sevdim seni

sonra sevdik birbirimizi

gönülden attık da gamı kederi

kalbe dolan huzuru

sende bulduk canımın gök nuru', 'ilk ben sevdim seni ilk ben yazdım adını kalbime savrulan küller gibi uçacak sandığım düşlerim gelişinle alevlendi gönlünce ilk ben sevdim s...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ilk-ben-sevdim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Düşünü Yaraladı', 'su-dusunu-yaraladi-seyit-piran-ubi8y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Su düşünü yaraladı, tamamlandı evrim

Sonunda bir mahur kırgınlığı olup çıktık

Dindiğimiz görülmedi, bu fırtına yıldızdan mı

Susuzluğumuz kanmasın diye, 

yeni çöller aramaya gittiysek, esinti de seraptır

Yine de esenlikler diliyorum saçlarına

Oda müziği çelişsin diye kendini kanatıyor bıçak

Bilirim havada viyolonsel sesi kanatsızsa, 

Kan ve su viran bir şarkıya başlayacak.

Wagner yada Şivan Perwer dinlenmeli bu saatte

Yalancıdır şahitliğim gözümden anlar gece

Parmak izimi alın “gitmek”le başladım şiire.

Solo keder çalıyor piyano, koro gözyaşı

Bilinçaltına itilen yol enstrümantal

Hayat sonat, gülmek konçerto, taş duvarlar opera

Taksim taksim ediliyor düşlerim, etsinler

Geçilen keman taksimi yitirdi ifadesini

İstanbul hükümlü, ben Taksim, o Pera

Zamanı gelince diyordun, 

Yetmez mi uçurumdan dinlediğimiz faslın bedeli

Hadi kopup gidelim bu soysuz kentlerden.

Gör işte kanayıp duruyor karanfilimiz gülümüz

Şimdi engin denizlere açılmak kurtarır bizi

Toprağı satanlara sermaye olmasın ölümüz

Suya inecek son vahiy, kim bilir bu kelamı

Beni dinsiz eden mavidir, mavzer sesidir.

Yitip gitsin sözcükler yeter bir dost selamı

Flütlere haber salınsın başlıyor resital

Dokuz milimetre çapında bir mermi, sorgu, sual

Resimlerde zikir ve kaos, kırbaçlanıyor tuval

Su düşünü yaraladı, tamamlandı evrim

Tam bağımsız bir ölüm istiyorum kendime

Yakama bir ilayda, sesime meneviş bir ırmak

Sonrası malum kırılmak, kırılmak, kırılmak..

Tangoyla giderim gidersem, beyaz giyerim sonra

Tanımlansın bu uzaklık, ben Fizan, o Pera', 'Su düşünü yaraladı, tamamlandı evrim Sonunda bir mahur kırgınlığı olup çıktık Dindiğimiz görülmedi, bu fırtına yıldızdan mı Susuzluğumuz kan...', ARRAY['Türk Edebiyatı','Şiir','Seyit Piran']::text[], 8.5, '{"poet":"Seyit Piran","poet_slug":"seyit-piran","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/su-dusunu-yaraladi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim Kare As Ruhum Beşbenzemez', 'kalbim-kare-as-ruhum-besbenzemez-seyit-piran-of7jk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kumral bir kumardayım, ömrüme blöf yapmaktayım

Anaforlar takıyorum gramofona sahici sesler için

Şimdi kıyıcılar vaktidir üç kart istiyorum yarama

Aklım kalıcı olsa da sıfırı tüketmek aşktır yine

Halka başvurmalıyım sonunda, pişmanım yasalara

İhtimal ki “isyan” koyacağım oğlumun ismini, 

“İs, yan! ” derse şair, “isyannn” derse savaşçı olur.

Benim harman yerim hangi kundaklamalara konudur

Hangi istasyondadır “gitme, dur” dediklerimiz, 

Artık sevgilimle kömür ocaklarında buluşuyorum

İşte diyorum sahici yüzler istiyordun, 

Gördün ya yerin altında sahte değil renklerimiz

Vazgeç bu tütsüden, bu deprem muhabirliğinden

Hepimiz dünya denilen göçüğün altında değil miyiz

Yüzüm belirince dalgınlığına bağışlanıyorum güzün

Paslı sesler çıkıyor ufaladığım yapraklardan

Her akşam şiirlerime akıyor yol yorgunu bir tren

Zaman diye esmer bir saat beşe akıyorum ben

Ne kötü, burda kuşlar gökdelenleri dağ sanıyor

Artık son sevinme tarihi geçiyor yaşadığım kentin

Puslu olanla uğurlanıyorum, yolum külle karşılanıyor

Kumral bir kumardayım, ömrüme blöf yapmaktayım

Çok yazıklı sokaklarla soğutuyorum tenimi, yansımayla...

Saçlarımı adamak için yeni gurbetler arıyorum, 

Sızım çöle meyilli kendimi rüzgarımla karıyorum, 

Şimdi yeni bir bahane gerek bana kabarıyor hesabım

Bitti rölans, varoluş nedenime rest çekiliyor son kez

Hangisi kaybeder, kalbim kare as, ruhum beşbenzemez', 'Kumral bir kumardayım, ömrüme blöf yapmaktayım Anaforlar takıyorum gramofona sahici sesler için Şimdi kıyıcılar vaktidir üç kart istiyorum y...', ARRAY['Türk Edebiyatı','Şiir','Seyit Piran']::text[], 8.5, '{"poet":"Seyit Piran","poet_slug":"seyit-piran","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kalbim-kare-as-ruhum-besbenzemez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim', 'kim-birol-akbaba-pkzal', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sabah rüzgarına sordum seni

dedi ulaşamam o sevgi

martılara sordum sesini

dediler o çığlık çığlık sevgi

pınarlara sordum berrak bakışını

dediler o taşmış çoskulu sevgi

bulutlara sordum akışını

dediler o sağnak, sağnak sevgi

aynalara sordum

dediler o akseden sevgi

yunus’a, mevlana ya sordum cevherini

dediler o tanrı sevgisi, sevgilisi', 'sabah rüzgarına sordum seni dedi ulaşamam o sevgi martılara sordum sesini dediler o çığlık çığlık sevgi pınarlara sordum berrak bakışını ded...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Susmak', 'susmak-melih-coskun-r18hd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Susmak

Daha da susmak 

Her gün biraz daha fazla susmak, 

Ezilmek

Daha da ezilmek

Her gün biraz daha fazla ezilmek, 

İnadına biraz daha fazla susmak

Yalnızdım 

Bağırıyordum 

Sesim bir yalnızlık türküsü gibi çınlıyordu dağlarda

Kimseler duymadı bu türküyü

Adı sadece yalnızlıktı haykırışın

Tüm inandıkların 

Tarih kitaplarında kalmıştır bugün

Genç bir kızın üzerinde

Amerikan bayraklı bir T-shirt

Senin ekip biçtiğin topraklardan

Uçak kaldırıyor şimdi 

Bir zamanlar denize döktüklerin

Daha rahat uyuyordur artık 

Bir karış toprağın için can verenler bugün

Ve gururu hiç eksilmesin

Bir madalya edasıyla taşısınlar tarih boyu

Bizi böyle susturup

Üç haftada adam edenler 

Onlar öğretti sana 

Bütün damarların boşalsa dahi  susmayı

Bir dilin vardı senin bir zamanlar

Bir yüreğin vardı

Onlar unutturdular sana 

Düşünebilmenin erdemini

Bugün susuyorsun inadına

Sen sustukça 

Her gün daha da çok

Sen sustukça inadına

Daha da üşüşecekler üstüne 

Beynini sökecekler yerinden 

Boşaltacaklar damarlarındaki kanı

Söyleyecek son sözün bile olmayacak bu hayatta

Noktanı, virgülünü, soru işaretlerini alıp gidecekler

Uyandığında bir gün bu derin uykudan pişmanlıkla

Bakmışsın ki

Düşünecek ve konuşacak hiçbir organın kalmamıştır 

Sana ait olan...

20 Kasım 2002

00: 08', 'Susmak Daha da susmak  Her gün biraz daha fazla susmak,  Ezilmek Daha da ezilmek Her gün biraz daha fazla ezilmek,  İnadına biraz daha fazla...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/susmak-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne güzel', 'ne-guzel-birol-akbaba-gdz2s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ne güzel şiirin sesi olabilmek

sesi şiir olmak

sevgiyi şiire taşımak

şiire sevgiyi yazmak

ne güzel yüreği şiir

şiiri yürek olmak

ne güzel dostu yürekte bulmak

yürekle dost olmak', 'ne güzel şiirin sesi olabilmek sesi şiir olmak sevgiyi şiire taşımak şiire sevgiyi yazmak ne güzel yüreği şiir şiiri yürek olmak ne güzel do...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ne-guzel-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Ateş Yaktık Sadece', 'biz-ates-yaktik-sadece-melih-coskun-whyc0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '(Bu zulüm, 

Korkunun ta kendisidir aslında

Ve bakışlarının sertliği kadar korkaktır onlar.

Korktukları kadar zalim.)

Zulüm: 

Korkunun diğer adı, 

Bundandır kurşunlanması tertemiz 

Ve namus timsali gecelerin, 

Bundandır yakılışı kitapların, 

Bundandır Filistin askısı, 

Davul gibi şişmiş, tuzda yürütülmüş ayak, 

Bundadır patlayan bir bombayla 

Dört yana  savrulan et parçaları, 

Ve bundandır çapraz ateş, 

Bu yarınsızlık, 

Bu sevgisizlik, 

Ve kara bıyıklar altında saklı olan nefret

Eskisi gibi sıcaktır hala

Susun dediler bize 

Susun yoksa...

Susun dediler bize

Susmadık ve kan kusmadık asla...

Biz ateş yaktık sadece

Isınmak ve aydınlanmak için

Kurt ve çakal sürüleriydi bunlar

Kanlıydı dişleri

Yaklaşamadılar ateşe

Bakamadılar aydınlığa 

Ve kanlıydı dişleri 

Gözlerinden okunan korku 

Bin yıllıktı 

Ve bin yıldır yanıyordu bu ateş

Ve onlar bin yıldır korkuyorlardı bu ateşten

Susmadık işte

Susmadık ve kan kusmadık asla

Korkmadık

Etrafı saran kurt sürülerinden

Biz ateş yaktık sadece

Korku düşmesin diye yarına...

22 Aralık 2002

22: 51', '(Bu zulüm,  Korkunun ta kendisidir aslında Ve bakışlarının sertliği kadar korkaktır onlar. Korktukları kadar zalim.) Zulüm:  Korkunun diğer ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/biz-ates-yaktik-sadece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin', 'neredesin-birol-akbaba-ziz6e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ay ışığı parlağım

yıldız saltanatım

gök nuru aydınlığım

rüzgar özgürlüğüm

nehirler taşkınım

okyanus dalgalarım

canım cananım

neredesin

kelebek sadeliğim

peri  fısıltım

derviş selamım

tanrı ilhamım

bahar tazeliğim

çiçek kokum

sözümün özü sevdiğim

neredesin', 'ay ışığı parlağım yıldız saltanatım gök nuru aydınlığım rüzgar özgürlüğüm nehirler taşkınım okyanus dalgalarım canım cananım neredesin keleb...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neredesin-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmecikli Kutucuk', 'bilmecikli-kutucuk-ates-can-whpw7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir kutucuk buldum dün gece 

düşler sokağında, büyükce 

içinde ikimizin yaşanmamış anıları

içinde sorulmamış soruların yanıtları

içinde hayal dolusu mutluluk

içinde umudun iri kanatları

bir kutucuk buldum dün gece

düşler sokağında, büyükce

içinde sen, ben

içinde bir yol bir bahçe

içinde bir de bilmece

''pişirmece yakmaca

yüreğine dökmece? ''', 'bir kutucuk buldum dün gece  düşler sokağında, büyükce  içinde ikimizin yaşanmamış anıları içinde sorulmamış soruların yanıtları içinde haya...', ARRAY['Türk Edebiyatı','Şiir','Ateş Can']::text[], 8.5, '{"poet":"Ateş Can","poet_slug":"ates-can","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bilmecikli-kutucuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O sensin', 'o-sensin-birol-akbaba-hnthh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'o sensin! asırlar boyu beklediğim

tüm yaşamlarım boyu ardığımsın

yaşadıklarım sana varmak için

çağrılarımda hep sen vardın

zaman hassas dengesini şaşmadan

seninle buluşturmak için beni

bu zamana kurdu saatlerini

işte geldin o beklenen aydınlık an.

o sensin! 

asırlar boyu beklediğim.

gök, yağmurlarını gelişine sakladı

bahar, tohumlarını sana vardırmak için

direndi fırtına ya, bora ya sel\''e, 

rüzgar, kokunu saklamak üzere sustu

aşk, sen gelene kadar dolandı durdu

ve ruh yeniden doğmak için

seni bekledi sordu sordu..

o sensin! asırlar boyu beklediğim

aydınlık yüz

hoş geldin', 'o sensin! asırlar boyu beklediğim tüm yaşamlarım boyu ardığımsın yaşadıklarım sana varmak için çağrılarımda hep sen vardın zaman hassas deng...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/o-sensin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arta Kalan', 'arta-kalan-i-smail-korkmaz-8ut9c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gülüşün açan bir tomurcuktu 

beni bahar akşamlarına götüren 

Güneşin batışına doğru bir tekne gezintisi 

.............................kızıl bulutlar arasından. 

Ballanmış vişne tadında şimdi 

..............................o günlerden arta kalan. 

.....................................çocuksu ve garipsi. 

Eylül 2000-Münih', 'Gülüşün açan bir tomurcuktu  beni bahar akşamlarına götüren  Güneşin batışına doğru bir tekne gezintisi  .............................kızıl ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Korkmaz']::text[], 8.5, '{"poet":"İsmail Korkmaz","poet_slug":"i-smail-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/arta-kalan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elma Ağacı', 'elma-agaci-oguzkan-bolukbasi-n2xh6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir kokulu elma ağacıydı

altında aşkımı söylediğim yapraklarına

adetti

dilekler asılırdı dallarına

dallar uğuldardı

alır giderdi bir derinden aaaah

şarkılar tünerdi ağaca

kuşlar misali

elmalar inadına sevda kokardı

siz sevdanın kokusunu bilir misiniz

acı lezzeti iştah açar

hayatı bir dikişte içmek istersiniz

hayat bir dikişte sizi bitirir

herkesin öyle bir öyküsü vardır

her öykü bir gurbet türküsüdür

can dayanmaz aslında

can o elma ağacının altında çıkar

başlangıcını unuttuğumuz anılardır şimdi dileklerde asılı duran

bir'' dönülmez akşamın ufkudur''

yüzümüze vuran

yaşamayı tam anladığımız yerde

kimdir bizi çağıran', 'bir kokulu elma ağacıydı altında aşkımı söylediğim yapraklarına adetti dilekler asılırdı dallarına dallar uğuldardı alır giderdi bir derinde...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/elma-agaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çekildi Dünyanın Pimi', 'cekildi-dunyanin-pimi-huseyin-karaca-cs1b7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nefesim yetmedi yarıda bıraktım koşuyu

Ben küçüktüm yenildim bir türlü iflah olmadım

Oyundan hep çıkardılar boyum kısaydı benim

Güçsüzdüm ve çelimsizdim hiç itiraz etmedim

Sokağa bırakılmış bir ev kedisi gibi

içim dolup geliyor tedirgin ve şaşkınım

Şimdi sekerek yürüyorum parmak ucumda

Oysa kavramalıydı ayaklarım toprağı

Dağılmış bir düş gibi kalakaldım ortada

Çaylak bir oyuncuyum yordam bilmez, acemi

Ben şimdi ne yaparım bir başıma sokakta

Öğretmediler bana dünyanın gizlerini

Şaştım kaldım bu işe hiçbir şey anlamadım

Yazıyorum buraya çekildi dünyanın pimi

Ortalık karışıyor az kaldı kıyamete

Başıma bir iş gelmeden gelse beklenen gemi.', 'Nefesim yetmedi yarıda bıraktım koşuyu Ben küçüktüm yenildim bir türlü iflah olmadım Oyundan hep çıkardılar boyum kısaydı benim Güçsüzdüm ve...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Karaca']::text[], 8.5, '{"poet":"Hüseyin Karaca","poet_slug":"huseyin-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cekildi-dunyanin-pimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Oldu Can?', 'ne-oldu-can-sair-kayahan-cmc3g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen canımsın zulmetme kalbime

Gel bir görsen acırsın halime

Ah gözünden düşmüşüm ben niye

Gel gecikme bu ahir ömrümde

Gel gün gelir ağlarsın kabrimde

Ah gözünden düşmüşüm ben niye

Ne oldu can ne oldu onca yaşananlar

Ne oldu can şimdi nerdesin kimlerlesin

Hani senin cananın bendim

Ne oldu can ayrılmazdın bir an yanımdan

Ne oldu can bensiz bir yerlere gitmezdin

Şimdi esen yellerde misin

Ben herşeyimi sana verdim

Yollarına canımı serdim

Öyle bir sevdi ki bu kalbim

Unutmaz artık bir an seni

Öyle bir sevdi ki bu kalbim

Yaşatmaz artık sevdan beni

Ne oldu can sen evimin pembe gülüydün

Ne oldu can şimdi başka evlerdeymişsin

Duydum ki unutmuşsun beni

Öyle mi Can?', 'Sen canımsın zulmetme kalbime Gel bir görsen acırsın halime Ah gözünden düşmüşüm ben niye Gel gecikme bu ahir ömrümde Gel gün gelir ağlarsın...', ARRAY['Türk Edebiyatı','Şiir','Şair Kayahan']::text[], 8.5, '{"poet":"Şair Kayahan","poet_slug":"sair-kayahan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ne-oldu-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehir Kuşatması', 'sehir-kusatmasi-huseyin-karaca-ppdw0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '''bu şehir değil evim

                                                            bu şehir benim neyim''

iki dağ arasına gerilmiş bir ip gibi

şehrin caddeleri iki yanı uçurum

herkes ortadayken oynanan bir saklambaç

sokaklar oyunun karanlık dehlizleri

işte buymuş yaşamak dedikleri sarkaç

şehir bir kuytu yer arz üzre peydahlanan

hayat cinnet onda ölüme iliklenmiş

ben böyle kaçarken aynalardan kendime

bir zaptiye olup peşime düşer hayat

gizli kelepçeyle bağlar beni kendine

bütün günahlarıyla zindana döner şehir

sarhoş olmuş zaman bu çağın beşiğinde

şehrin vitrinleri bakışlardan kirlenmiş

adımım kaybolur içinde adımların

yüzüm tanınmaz olur sesim kaybolur

ben ölür, uzanır altında lambaların.', '''bu şehir değil evim                                                             bu şehir benim neyim'' iki dağ arasına gerilmiş bir ip gibi ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Karaca']::text[], 8.5, '{"poet":"Hüseyin Karaca","poet_slug":"huseyin-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sehir-kusatmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erken Boşalan Şiir', 'erken-bosalan-siir-reha-basogul-d97yb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Siz hiç gördünüz mü

bir akrebin

vaktinden önce kendini soktuğunu

ya da dişi kurdun

doğurganlığını tutkusuna kanıt olarak sunduğunu? 

hiçbir ağaç

kök salma duygularını bastırmış mıdır 

üstünden geçen uçağın

yaprak zarını sersemletişinde

veya üst komşusunun bir fincan kahve hatrı

mâni olabilir mi

azgın martının kanatlarını erkeğine sürtmesine? 

kimse tahammül edebilir mi

şehrin  göbeğinde

doğal seçimin kulağını yalayan

ve göbeğini emen erkeğe

sokak arasındaki köpeğe ettiği gibi? 

bana sorulabilir mi şimdi

insanlardan gayrı

Ay''daki kahve falına bakarak

niye üç vakte kadar

tulum içinde beklerim peynirimi

ya da burada gürleşir

ve vaktini bilir horozun sesi? 

çünkü çatlatarak şehrin göbeğini

akarsu yatağında

ve tavuğun coşkusuyla dile gelir

üstelik doğanın bozulmamış rahminde

sevişmeden önce aşılır

ve yazılır erken boşalan şiir

oysa ki

bir erkek belki affedebilir

vaktinden önce

kadının içine erkenden boşalmasını

ama ya şiir

şiir aşabilir mi bunu

rahmine girilmeden

ve soyunabilir mi

duygularını içine dökmeden

hem de kendisinden gayrı? 

dikkat çekicidir ki; 

bu yüzden tarihi zehir 

doğa yasalarının çıplaklığına tabidir

asla onu tatmin etmez

ve elenir erken boşalan şiir', 'Siz hiç gördünüz mü bir akrebin vaktinden önce kendini soktuğunu ya da dişi kurdun doğurganlığını tutkusuna kanıt olarak sunduğunu?  hiçbir ...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/erken-bosalan-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkılmadım', 'yikilmadim-erdogan-ciray-eazjv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tüm Vefasızlara

Kilit vurdum kalbime

Kimseyi sevmeyecek

Ferman yazdım elime

Kimseye değmeyecek

Koca ömür geçse de

Hiç yüzüm gülmeyecek

Her gün böyle ölsem de

Kimseler bilmeyecek

Ben yabancı değilim

Sefalete yokluğa

Neden boyun eyeyim

Kadere uşaklığa

Bakma saçlarımdaki

O bembeyaz aklığa

Zamanla alışırım

Senin gibi alçaklığa

Ne fırtınalar esti

Yine de yıkılmadım

Bir gün terk edilsem de

Sevmekten sıkılmadım

Küsmedim hayatıma

İçkiye takılmadım

Belki terkedildim ya

Gönülden atılmadım

Eylül 1985/İSTANBUL', 'Tüm Vefasızlara Kilit vurdum kalbime Kimseyi sevmeyecek Ferman yazdım elime Kimseye değmeyecek Koca ömür geçse de Hiç yüzüm gülmeyecek Her g...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çıray']::text[], 8.5, '{"poet":"Erdoğan Çıray","poet_slug":"erdogan-ciray","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yikilmadim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Şimdi Asker', 'o-simdi-asker-ugur-erbil-qgcm6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Oda Gitti Şimdi Asker

Şimdi Uzak Yerlerde Uzak İllerde

Vatan Borcu Dediler Onu da aldılar asker

Şuan nöbetteymiş aldım ondan da haber

Elinde sigarası düşüncesinde sevdiği

Efkarlıymış çok özlemiş

Anasını, babasını birde vefasız sevdiğini

Hala çıkartamamıştır aklından onu

O şimdi düşünceli, üzgün asker', 'Oda Gitti Şimdi Asker Şimdi Uzak Yerlerde Uzak İllerde Vatan Borcu Dediler Onu da aldılar asker Şuan nöbetteymiş aldım ondan da haber Elinde...', ARRAY['Türk Edebiyatı','Şiir','Uğur Erbil']::text[], 8.5, '{"poet":"Uğur Erbil","poet_slug":"ugur-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/o-simdi-asker-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Hayat', 'aci-hayat-sair-khan-qyo9j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tıpkı bir köşeye atılmış bir çamaşır gibiyim bu dünya da

Kullanılmış yırtılmış paspal artık toz bezi bile olmayacak bir parça

Aşkların derin acısı hayattaki  tatları yerle bir oluyor

Artık bu yaşam bitsin diye dua ederken boşalan yaşların bile anlamı yok

Artık gitmeliyim ama teneşirde beni paklayacak olur mu 

ondan bile endişelenecek kadar yalnızım

bu kütük gövdeyi toprakla buluşturacak arkasından iyi bilirdik diyecek kadar bile dostum yok

bana son seferimde çıkmadan yola telkin edecek imam efendi bile olur mu bilmem 

hayat hep böyle mi olacaktı be anne; 

senin sıcak koynundan böyle soğuk karanlıklarla mı dost olacaktım

soğuk çelik dayanmış şakağıma bu kadar yakınlık sevgimi besleyecektim

uzayıp giden yollar benim kaderim mi olacaktı

güllerle gülistanlarla kurulan hayaller bir çöp denizi mi çıkacaktı

yok be yok anne hayat senin kadife sesli ninnilerinde söylediğin gibi değil

sadece bostancı danaları değil insanlar insanları kovalıyor

yok annem bu mermi şakağıma bir nişan gibi saplanan bu bakır parça benim en güzel dostum

ayın doğduğu anlar bile bu kadar mı çekilmez gelecekti insana

sisli puslu havalarda bir köşe başında sızmak mı olacak benim bahtım

bağrıma bir yumruk çökerken tepeden tırnağa üzerimde geçen kor ateş mi beni yakacaktı

sevgiliye saklayacağım aşka doyuracağım diye beslediğim bu duygular

 kör bir bıçak mı olacaktı annem

kar yağarken gecelere beyazın saflığı bana kararmış bir hayat gibi mi gelecekti

yalvarışların haykırışların gökyüzüne ulaştığı dağların bile taşıyamayacağı bu yükü

sırtıma taşıyacak gücü nasıl bulacaktım be annem

hoşça kal annem hoşça kal bilinmeyende beni bekleyen sevgili ben artık martılarla, 

gökyüzünün maviliklerine ufuğun kesiştiği yere yelken açıyorum', 'Tıpkı bir köşeye atılmış bir çamaşır gibiyim bu dünya da Kullanılmış yırtılmış paspal artık toz bezi bile olmayacak bir parça Aşkların derin...', ARRAY['Türk Edebiyatı','Şiir','Şair Khan']::text[], 8.5, '{"poet":"Şair Khan","poet_slug":"sair-khan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/aci-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamam', 'anlatamam-ali-safak-bali-rcg45', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne olur ısrar etme, 

anlatamam sana aşkımı, 

Ne kadar çabalasam, 

söz yetmez, beceremem...

Kelimeler bilmezken kendi anlamını, 

ben ne yüklerim, 

ne taşınır kim bilir sana...

Bir kabuğa bağlandığını 

nasıl söylerim? 

Nasıl anlatabilirim 

bir ölünün sonsuz aşkını? 

Ama belki, 

durup bir an bakabilsen 

derinlerine okyanus mavisi gözlerin ve 

dalıp gitsen bir an dipsiz denizine sevginin

anlardın...

Ama nafile…

Ne benim gözlerim mavi, 

ne sen yüzme biliyorsun…', 'Ne olur ısrar etme,  anlatamam sana aşkımı,  Ne kadar çabalasam,  söz yetmez, beceremem... Kelimeler bilmezken kendi anlamını,  ben ne yükle...', ARRAY['Türk Edebiyatı','Şiir','Ali Şafak Balı']::text[], 8.5, '{"poet":"Ali Şafak Balı","poet_slug":"ali-safak-bali","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/anlatamam-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzulara Doyulmaz', 'arzulara-doyulmaz-erdogan-ciray-8tiud', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'El sözüne uyulmaz

Arzulara doyulmaz

Gurbette sevgililer

Boynu bükük koyulmaz

Artık ne aşk ne gurur

Gerçekler acı vurur

Hayalin pişman üzgün

Öyle karşımda durur

Hatıralar silinmez

Ağlayana gülünmez

Hayat çıkmaz bir sokak

Tekrar geri dönülmez 

Ağustos 1989  İZMİR/Uzunada', 'El sözüne uyulmaz Arzulara doyulmaz Gurbette sevgililer Boynu bükük koyulmaz Artık ne aşk ne gurur Gerçekler acı vurur Hayalin pişman üzgün ...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çıray']::text[], 8.5, '{"poet":"Erdoğan Çıray","poet_slug":"erdogan-ciray","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/arzulara-doyulmaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımın Destanının Adı Gonca - 4', 'askimin-destaninin-adi-gonca-4-i-brahim-cagri-saglik-gvw1o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Belli ki bir zamandı, yaşanmalıydı

Ayrı ayrı geçen o koskoca günler

Değerler elbette anlaşılmalıydı

Birlikte geçecekse artık ömürler

Kader derim ben ona, bizi bağladı

Haftalar sonra bir kez daha görüştük

Bilirim ikimizinde içi ağladı

Hangi sebeplerden ki ayrı düşmüştük

Bir asır gibi uzun gelen ayrılık

Anlık bir buluşma ile sona erdi

Unutamam, bakışındaki tatlılık

Bana taptaze umut, bit kuvvet verdi

Şimdi bakınca dönüp geçmişimize

Seni neden sevdiğimi anlıyorum

Nazar değmesin, bakmasınlar hiç bize

Ben bu aşkı sonsuzluğa saklıyorum

24-Ocak-2003', 'Belli ki bir zamandı, yaşanmalıydı Ayrı ayrı geçen o koskoca günler Değerler elbette anlaşılmalıydı Birlikte geçecekse artık ömürler Kader d...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çağrı Sağlık']::text[], 8.5, '{"poet":"İbrahim Çağrı Sağlık","poet_slug":"i-brahim-cagri-saglik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/askimin-destaninin-adi-gonca-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Sevgiden Ne Anlarsın', 'sen-sevgiden-ne-anlarsin-ugur-erbil-qlxet', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkı sevgiyi senin sanırsın

Sen aşktan sevgiden ne anlarsın

Allah versin cezanı gözlerinde yaş kalmasın

Vefasız, sevdiğim benim

Nasılda inanmıştım o sahte olan sevgine

Nasılda inanmıştım o kahpe gözlerine

Anladım senden bana hayır yok artık

Bende istemiyorum git, git artık

Bumuydu çok sevişin, aşık oluşun

Bumuydu güvencin tapışın bana

Sende alçak çıktın, vefasız çıktın

Beni kalbimden yaraladın git

Git artık ne olur bırak beni yalnızlığa

Ben ağlarım acıyan olmasa da göz yaşlarıma

Alışırım belki bu söz verip de gidişine

Artık düşünmüyorum senin aşkını da sevgini de', 'Aşkı sevgiyi senin sanırsın Sen aşktan sevgiden ne anlarsın Allah versin cezanı gözlerinde yaş kalmasın Vefasız, sevdiğim benim Nasılda inan...', ARRAY['Türk Edebiyatı','Şiir','Uğur Erbil']::text[], 8.5, '{"poet":"Uğur Erbil","poet_slug":"ugur-erbil","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-sevgiden-ne-anlarsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-sinan-altuntas-bo4qf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen umudumun tek kaynağı 

Bence aşkın ta kendisisin

Sen dertlerimin en güzeli

Aşkıma doğan güneşsin

Sen içimdeki dünya

Benimle yaşayıp yaşatansın

Sen aşkın en güzelini aşkla veren

Sen meleksin sen herşeysin

Sen bahçedeki bir çiçek

Sen bahardanda güzelsin

Sen hayatsın sen ömürsün 

Sen zamansız ve mekansız her yerdesin

Sen sevgiden ve aşktan öte

Sen haddimden de güzelsin

Sen her duyguma düşünce

Sen her an benimlesin 

Sen benim dünyamsın', 'Sen umudumun tek kaynağı  Bence aşkın ta kendisisin Sen dertlerimin en güzeli Aşkıma doğan güneşsin Sen içimdeki dünya Benimle yaşayıp yaşat...', ARRAY['Türk Edebiyatı','Şiir','Sinan Altuntaş']::text[], 8.5, '{"poet":"Sinan Altuntaş","poet_slug":"sinan-altuntas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-211-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtirafımın Realistliği', 'i-tirafimin-realistligi-sinan-altuntas-78qmp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevmek suç olsa

Çıkarsız, 

İnfazla yargılanırdım...

Sevmek günah olsa

Kuşkusuz, 

Cehennemi boylardım...

Sevmek suç değil, 

Sevmek günah değil, 

Seviyorum seni elimde değil

Deli dolu bir gönlüm var bende değil

Her anımla sevdim seni

Diğer günlerden farklı değil...', 'Sevmek suç olsa Çıkarsız,  İnfazla yargılanırdım... Sevmek günah olsa Kuşkusuz,  Cehennemi boylardım... Sevmek suç değil,  Sevmek günah deği...', ARRAY['Türk Edebiyatı','Şiir','Sinan Altuntaş']::text[], 8.5, '{"poet":"Sinan Altuntaş","poet_slug":"sinan-altuntas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/itirafimin-realistligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karınca Duası', 'karinca-duasi-i-hsan-uncuoglu-t4xls', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karınca Duası

Ekranlara kokar çıkar

Arsız gazcı bir yazar

Önü Arkası hep günahlı 

Aşağılık alçak dolandırıcı 

Herzaman Palavracı olsun adı, 

*

Her sözün kısaca yalancısı

Çifte Atmasyondur bu atarabası, 

*

Evlere şenlik nasıl olur böyle selamet

İnsan kiri pislik bin cahil bin cehalet

Pak yerine yılan dilli kumar oynar köçek

Zehir zemberek cahilden gelir her musibet

Arkasından saçma çıkar bekle binbir felaket, 

***

Allahtan keramet olurmu millete olan bir hıyanet

Lekesiz yerde zehir yılan dilli kimi oynar köçek

Oynatana zillerle oynayan oynatılan olursa eşşek

Kara sağır körelmiş uşak esir kalır her memleketin

Aydını alçalmış aşağılıktır anlamaz kopsa da kıyamet, 

***

/Allah kerameti bilinir yapılan her hıyanet

Aydını sağır kördür anlamaz kopsa da kıyamet

Pak yerde yılan dilli kimi kumar oynar köçek

Aydınlık karanlığa dönerse her bir memlekette

Zehir zemberekli cahillerden gelir çok musibet

Arkasından halile saçılır binbir felaket hıyanet! , /', 'Karınca Duası Ekranlara kokar çıkar Arsız gazcı bir yazar Önü Arkası hep günahlı  Aşağılık alçak dolandırıcı  Herzaman Palavracı olsun adı, ...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/karinca-duasi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalmak mı Gıtmekmı', 'kalmak-mi-gitmekmi-erkan-gul-b9nna', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gozyasların hapsetti hürriyetimi, 

 Caresızlıgımıle bagladın beni, 

 Korkmak  COZUM  degil.

 Ama olmek ıstıyorum, 

 Seninle beraber.', 'Gozyasların hapsetti hürriyetimi,   Caresızlıgımıle bagladın beni,   Korkmak  COZUM  degil.  Ama olmek ıstıyorum,   Seninle beraber....', ARRAY['Türk Edebiyatı','Şiir','Erkan Gül']::text[], 8.5, '{"poet":"Erkan Gül","poet_slug":"erkan-gul","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kalmak-mi-gitmekmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevda Türküsü', 'sevda-turkusu-sinan-altuntas-gk9sd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sevda türküsüdür 

Dilimde yarım kalan

Bahara hasret çiçek gibi

bekledim seni...

Bir sır oldu sen ve senden kalanlar

Suya hasret toprak gibi 

Özledim seni...

Özlemekmiş; 

Her hasretin arkasından çekilen çile

Sevmekmiş; 

Bir ümidin peşinden koşup

Dalıp gidilen hayale

Her hasretin arkasında 

Bir ümidin bin nazı var

Bir sevda türküsü

Fısıldaşır dilimde...', 'Bir sevda türküsüdür  Dilimde yarım kalan Bahara hasret çiçek gibi bekledim seni... Bir sır oldu sen ve senden kalanlar Suya hasret toprak g...', ARRAY['Türk Edebiyatı','Şiir','Sinan Altuntaş']::text[], 8.5, '{"poet":"Sinan Altuntaş","poet_slug":"sinan-altuntas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevda-turkusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin Aynasında', 'gunesin-aynasinda-fikret-kizilok-1gg6p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneşin aynasında ben

Bende bir düş

Düşte bir çocuk, çocukta yol

Yolda toz, tozda avuç, avuçta kader

Kaderde sen, güneşte akşam oluyor

Ben düşünürken 

Düşüncemin çiçeğindesin

Yedi iklim dört mevsimdesin

Canımın yongalarında

gölge gibi hep peşimdesin

Kırmızının kuytularında, 

yeşilin uykularında, 

karanfilin kokularında

şebnem olur gider gözlerin 

Arkamı dönsem önümde

İstemesem de içimde

Çocuğun umutlarında

Kiminin korkularında 

Güneşin aynasında ben

Bende bir düş

Düşte bir çocuk, çocukta yol

Yolda toz, tozda avuç, avuçta kader

Kaderde sen, güneşte akşam oluyor

Ben düşünürken 

Düşüncemin çiçeğindesin

Yedi iklim dört mevsimdesin

Canımın yongalarında

Gölge gibi hep peşimdesin

Kırmızının kuytularında, 

Yeşilin uykularında, 

Karanfilin kokularında, 

Şebnem olur gider gözlerin 

Kalemin yasaklarında, 

Çalışan parmaklarında, 

Ve ağaran saçlarında

Tutsak olmuş bir düşüncesin

Bil bakalım sen nesin 

Güneşin aynasında biz

Bizde bir düş

Düşte bir çocuk, çocukta yol

Yolda toz, tozda avuç, avuçta kader

Kaderde sen, güneşte akşam oluyor

Ben düşünürken...

Ben düşünürken', 'Güneşin aynasında ben Bende bir düş Düşte bir çocuk, çocukta yol Yolda toz, tozda avuç, avuçta kader Kaderde sen, güneşte akşam oluyor Ben d...', ARRAY['Türk Edebiyatı','Şiir','Fikret Kızılok']::text[], 8.5, '{"poet":"Fikret Kızılok","poet_slug":"fikret-kizilok","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/gunesin-aynasinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Değilsin', 'benim-degilsin-sinan-altuntas-fcmaz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen elin kadını benim değilsin

Sen gönlümün harcı tacı değilsin

Daha başlamadan vazgeçelim  bu sevda dan

Sen alnıma yazılan kader değilsin

Ne zalim düzenimiz varmış tanrım

Uzak bir düş gibi kavuşmamız imkansız

Bir varmış bir yokmuş diyelim

Masallarda kalsın gizli yaramız

Farzet ki olmayacak hayale daldık

Farzet ki tatlı bir rüyadan uyandık

Olmayacak duadan hayır beklenmez

Farzet ki birbirimizi hiç tanımadık', 'Sen elin kadını benim değilsin Sen gönlümün harcı tacı değilsin Daha başlamadan vazgeçelim  bu sevda dan Sen alnıma yazılan kader değilsin N...', ARRAY['Türk Edebiyatı','Şiir','Sinan Altuntaş']::text[], 8.5, '{"poet":"Sinan Altuntaş","poet_slug":"sinan-altuntas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/benim-degilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınanam', 'kadinanam-tayfun-unal-s1ey0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Annem ne güzel bir kadın

Başörtüsü ile seccadesi ile

Annem ne güzel bir kadın

Şefkatli sesi ile...

Annem ne güzel bir kadın

Patates soyarken soğan doğrarken

Annem ne güzel bir kadın

Başucumda ağlarken...

Annem ne güzel bir kadın

Yan cebimin söküğünde

Annem ne güzel bir kadın

İğnede iplikte düğümde...

Annem ne güzel bir kadın

Eline kına yakar

Annem ne güzel bir kadın

Anne gibi kokar anne gibi bakar...', 'Annem ne güzel bir kadın Başörtüsü ile seccadesi ile Annem ne güzel bir kadın Şefkatli sesi ile... Annem ne güzel bir kadın Patates soyarken...', ARRAY['Türk Edebiyatı','Şiir','Tayfun Ünal']::text[], 8.5, '{"poet":"Tayfun Ünal","poet_slug":"tayfun-unal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kadinanam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanar Kağıtların Toprak Kokan Elleri', 'kanar-kagitlarin-toprak-kokan-elleri-alper-akdeniz-motvs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'kanar kağıtların toprak kokan elleri

uzandım toprağa sırtıma dikenler battı

çıplaktım, bir o kadar da günahsız

ay da usulca uzandı yanıma

yağmalanmış bir kadının silueti belirdi

bana seslendi, ''hey sen, yalnız adam''

soyundu, bekledim

o soyundu ben üşüdüm

                        -tam sevişecektik

kayboldu, kendisinden sakladı kadınlığını

                        -ben en çok sonralar öğrendim

hey kadınım; 

izin ver, şaraba banayım dudaklarımı

güneş perdeyi zorlarken

                    ve başın dizimdeyken susmayı unuttum

                                                                -seviş benimle

hey kadınım; 

dört tren geçti, kuşlar giyindi gün ışıyor 

zaman takmış koluna çıngırağını sallamakta

ırmaklar bakire denizlere çoktan kavuştu

sesler boğulacak birazdan, kaybolacaksın

giden en çok ben olurum

her şey sona doğru gitmiyor mu zaten? 

şiirlerin sonu gelmez, bir yerleri eksik kalır

kanar kağıtların toprak kokan elleri

hissediyor musun tenim tenine batıyor? 

salkım saçak sürgün veriyor çocuklarım bedenine

ütüsüz sabahlarda gözlerimin mahmurluğusun sen

seni uzun uzadı ya yazdım, kalem sustu.

duvara çizdiğim resminin öpülesi tortuları arda kalan', 'kanar kağıtların toprak kokan elleri uzandım toprağa sırtıma dikenler battı çıplaktım, bir o kadar da günahsız ay da usulca uzandı yanıma ya...', ARRAY['Türk Edebiyatı','Şiir','Alper Akdeniz']::text[], 8.5, '{"poet":"Alper Akdeniz","poet_slug":"alper-akdeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kanar-kagitlarin-toprak-kokan-elleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gizli Sevda', 'gizli-sevda-mahir-kurt-35552', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Lacivert karşımda, beyaz yanımda

Herşey dilimin ucunda

Elimde sigara, paketim onda

Çakmağım bende, ben sende.

Lacivert, dil ve sigara

Herşey çok basit aslında.

Çocuklar saklanbaç oynar, 

Bazıları büyür gizli sever

Saklanan sevgi olur.

Oyundaki ebe arar arar durur

Aradığı sen değilsin başka birini bulur

Sen bunu bilirsin, oyun uzar durur.

Sonra başka bir yerde aynı oyun oynanır

Bu nedense hep böyle olur.

Sen istersin o aşkın olsun, o lur oyundaki ebe

Saklanmak istersin aşkının yüreğine

Yürekte saklı başka biri

Oyunu öğrendin oynarsın artık ezbere.', 'Lacivert karşımda, beyaz yanımda Herşey dilimin ucunda Elimde sigara, paketim onda Çakmağım bende, ben sende. Lacivert, dil ve sigara Herşey...', ARRAY['Türk Edebiyatı','Şiir','Mahir Kurt']::text[], 8.5, '{"poet":"Mahir Kurt","poet_slug":"mahir-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gizli-sevda-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Kuyu', 'kor-kuyu-melek-midikoglu-clt04', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir taş attım kuyuya

Yankı sustu, acıttı

Issızlığın ortasında 

Bana ses gerek, bağır! 

Bir can yaktım kuytuda

Kör kuyuyla yan dibe

Kalabalığın içinde 

Bana ten gerek, vur...

Sarı sahilde, 

Aşk ölmekmiş nafile

Ağlamak yetmedi

Merhem gerek, sür

...

Neolursun! ?', 'Bir taş attım kuyuya Yankı sustu, acıttı Issızlığın ortasında  Bana ses gerek, bağır!  Bir can yaktım kuytuda Kör kuyuyla yan dibe Kalabalığ...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kor-kuyu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nişanlı Kız', 'nisanli-kiz-tuncay-emrem-3k914', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün gördüm onu, nişanlanıvermiş.

Elini gösterdi bana, anladım! 

Dün gördüm onu, mahzun,  perişan..

Giyinişinde, hallerinde bir boş veriş..

Kulağım tanırdı ayak seslerini.

Gözlerim çok uzaktan seçerdi, 

Ondan bir renk, bir şekil sade! 

Boşuna beklemişim pencerelerde...

Nasıl alışmışım, nasıl sevmişim..

Nasıl kaçardı önümden, alımlı, memnun..

Geçen zaman fırsatları almış elimden! 

Bomboş yollarını hala beklerim..

                                                  Beşiktaş  1955', 'Dün gördüm onu, nişanlanıvermiş. Elini gösterdi bana, anladım!  Dün gördüm onu, mahzun,  perişan.. Giyinişinde, hallerinde bir boş veriş.. K...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Emrem']::text[], 8.5, '{"poet":"Tuncay Emrem","poet_slug":"tuncay-emrem","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/nisanli-kiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Aşk', 'i-lk-ask-tuncay-emrem-0kmnl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Rüzgârlar başladı yine, 

Kapıldı ümitlerim

Sarı yapraklar gibi 

Hazan seline..

Sevgilim! 

Bakışların sabahlardan daha aydınlık! 

Neden ellerin çaresiz böyle? 

Sesin, titrek, ılık

Neden ellerin çaresiz böyle? 

Dudaklarında bir şey vardı söylemediğin..

Ve sana anlatamadığım benim de.

Bırak, bakışlarımız konuşsun artık..

Tasa etmem sıcak ve küçük elin, 

Olmasa da elimde.

Yeter bakışlarımız konuşsun artık..', 'Rüzgârlar başladı yine,  Kapıldı ümitlerim Sarı yapraklar gibi  Hazan seline.. Sevgilim!  Bakışların sabahlardan daha aydınlık!  Neden eller...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Emrem']::text[], 8.5, '{"poet":"Tuncay Emrem","poet_slug":"tuncay-emrem","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ilk-ask-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derin', 'derin-eray-gunay-mdjue', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yerin altı çok derin 

Seni de alır

Beni de', 'Yerin altı çok derin  Seni de alır Beni de...', ARRAY['Türk Edebiyatı','Şiir','Eray Günay']::text[], 8.5, '{"poet":"Eray Günay","poet_slug":"eray-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/derin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belirsizlik', 'belirsizlik-tuncay-emrem-k40b4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hasretimiz uzak yerlere mi aitdir, 

yaşadığımızdan! .

Gitmesin bu şarkı ve ahenk, 

kulağımdan.

İstediğimiz başka şeyler mi var, 

hayatın ötesinde? 

Ve kaybettiklerimiz, 

geçmişte..? 

İnce, ılık bir sestir, 

duyulur, beni çağıran..

Ve sonra bir korku gibi, 

Allah bakar uzaklardan..

Birbiri sıra günler, 

birşeyler götürür bana dair..

Erir, kaybolur, tenha

gaiplerin koynunda..', 'Hasretimiz uzak yerlere mi aitdir,  yaşadığımızdan! . Gitmesin bu şarkı ve ahenk,  kulağımdan. İstediğimiz başka şeyler mi var,  hayatın öte...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Emrem']::text[], 8.5, '{"poet":"Tuncay Emrem","poet_slug":"tuncay-emrem","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/belirsizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Cansın Yüreğimde', 'bir-cansin-yuregimde-salih-ozalasan-yib0w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir cansın yüreğimde, canımdan öte

Sevgiler sonsuz, seninki sevgiden öte

Aşiyan sensin, bana saraydan öte

Benim için hayat, mahsun gözlerinde

İstemem kimse sevmesin aramasın beni

Bir sana hasret var benim gönlümde

Bülbülüm nar’ına yanmış gönül serseri

Benim için dinmeyen nağme, senin tatlı sözlerinde

Bir baharsın ömrümde, mevsimden öte

Güllerin yediveren, sense gülden öte

Yürekler cennet, seninki cennetten öte

Benim için cennet, yer almak senin yüreğinde

İstemem dört mevsim, farklıdır her biri

Cennet bahçesinde baharsın benim yüreğimde

Gönül gözüm hep sana bakar deme serseri

Bana hayat veren Güneş, gizli senin gözlerinde

Y.Tar 03-01-2003 Saat 15,45', 'Bir cansın yüreğimde, canımdan öte Sevgiler sonsuz, seninki sevgiden öte Aşiyan sensin, bana saraydan öte Benim için hayat, mahsun gözlerind...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-cansin-yuregimde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-i-rfan-cebeci-yq07v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana söyleyemediğim; 

Kendime anlattıklarım

Bir yudum su, çöl susuzluğunda

Dudaklarımda kelimeler

Seni Seviyorum...', 'Sana söyleyemediğim;  Kendime anlattıklarım Bir yudum su, çöl susuzluğunda Dudaklarımda kelimeler Seni Seviyorum......', ARRAY['Türk Edebiyatı','Şiir','İrfan Cebeci']::text[], 8.5, '{"poet":"İrfan Cebeci","poet_slug":"i-rfan-cebeci","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seni-seviyorum-112-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykuda Dans', 'uykuda-dans-melek-midikoglu-uxztj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ay sen ne tatlı şeysin Rakkase

Dün gece

Uykuda dans ettin delice

Elvis Presley sesi eşliğinde

Ah yalnız alev Rakkase

Eşin olsaydı bir eşin

Yerdi seni Yemen''de

Ay sen ne tatlı şeysin Rakkase

Dün gece

Uyumadın da

Dans ettin gizlice

Ah Rakkase

Delice...', 'Ay sen ne tatlı şeysin Rakkase Dün gece Uykuda dans ettin delice Elvis Presley sesi eşliğinde Ah yalnız alev Rakkase Eşin olsaydı bir eşin Y...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/uykuda-dans-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evet Demek', 'evet-demek-bayram-tunca-3bja6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Evet demek, neleri neleri kabul etmek

Hatta kefensiz gömleği baştan giymek

Hayatın çeşitli cilvelerini kabullenmek

Bu yolda, ölmek var, ama yok dönmek

Kolay mı sanıyorsun, sen evet demeyi

Eğer evet diyebildiysen, kutlarım seni

Çünkü, evet demek, büyük cesaret işi

Bu aht-ı peymanı imzalayanlar iki kişi 

Biri erkek, diğeri dişi ne mutlu onlara

Yerdeki ve göktekiler alkışlıyor onlara

Deste deste türküler bestelenir onlara

Resul, Cennet bile vaat emekte onlara

O ümmetimin çokluyla övünürüm diyor

Helal dairesi de keyfe kafidir deniliyor

Bayram da, övgüye lâyık olmak istiyor

Ama hayat şartları iki de bile zorluyor

B. Tunca/13.01.2003-13.01

Dip Not: 

Evlilik kötü olsaydı, hiç Nebimiz evlenir miydi

Hem ümmetimin çokluyla övünürüm der miydi

B. Tunca/13.01.2003-13.01', 'Evet demek, neleri neleri kabul etmek Hatta kefensiz gömleği baştan giymek Hayatın çeşitli cilvelerini kabullenmek Bu yolda, ölmek var, ama ...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/evet-demek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlam', 'anlam-cenk-boluk-wj5kc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir anlam arıyorum

Yalan söyleyen gözbebeklerinde

Küçücük, minicik bir anlam arıyorum

Bulamıyorum.

Ufacık bir umut yetecek bana

Sıradan ve basit bir sebep arıyorum

Ellerinin sıcaklığında üşüyor ellerim.

Seni bir türlü sevemiyorum.

Bir anlam arıyorum

Önemsiz bir ayrıntı belki

Dudaklarını seyrediyorum

Sen giderek anlamsızlaşıyorsun.', 'Bir anlam arıyorum Yalan söyleyen gözbebeklerinde Küçücük, minicik bir anlam arıyorum Bulamıyorum. Ufacık bir umut yetecek bana Sıradan ve b...', ARRAY['Türk Edebiyatı','Şiir','Cenk Bölük']::text[], 8.5, '{"poet":"Cenk Bölük","poet_slug":"cenk-boluk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/anlam-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumartesi Sabahları', 'cumartesi-sabahlari-cenk-boluk-lxhla', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Cumartesi sabahları

Omlet yapardım

Sen konuşurdun

Abuk subuk.

Cumartesi sabahları

Erkenden kalkardım

Bir sigara yakıp

Seni seyrederdim uzaktan.

Cumartesi sabahları

Bira içerdim kahvaltıda

Küfür ederdin

Ağız dolusu gülerdim.

Seni görmeyişimin

Bu dördüncü yılında

Her gün değil

Ama

Her Cumartesi sabahında

Gözümde tütüyorsun', 'Cumartesi sabahları Omlet yapardım Sen konuşurdun Abuk subuk. Cumartesi sabahları Erkenden kalkardım Bir sigara yakıp Seni seyrederdim uzakt...', ARRAY['Türk Edebiyatı','Şiir','Cenk Bölük']::text[], 8.5, '{"poet":"Cenk Bölük","poet_slug":"cenk-boluk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/cumartesi-sabahlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Kolaylaşıyor', 'yasamak-kolaylasiyor-sair-lacivert-kku83', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Herşey kendiliğinden çözülüyor sanki

Sen iyiyken.

Üzmüyor yaşananlar.

Herşeye, herkese gücüm yetiyor.

İyi ol, nolur.

Sen iyiyken yaşamak kolaylaşıyor.', 'Herşey kendiliğinden çözülüyor sanki Sen iyiyken. Üzmüyor yaşananlar. Herşeye, herkese gücüm yetiyor. İyi ol, nolur. Sen iyiyken yaşamak kol...', ARRAY['Türk Edebiyatı','Şiir','Şair Lacivert']::text[], 8.5, '{"poet":"Şair Lacivert","poet_slug":"sair-lacivert","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yasamak-kolaylasiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evli ve Çocuklu', 'evli-ve-cocuklu-cenk-boluk-o01oq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Soyadından dolayı

Ünlü biriymiş

Gibi

Davranırlardı ona

Oysa

Hiç öyle değildi

Başka bir

Şehirde yaşıyor

Şimdi

Ve evli

Ama hiç değişmemiş

Hala

Hayatın anlamını

Bulabilmek

Tek derdi

Arada sırada

Çok içip

Kafayı bulduğunda

Arıyor

Konuşuyoruz

Havadan sudan

O başka bir

Şehirde yaşıyor

Şimdi

Ama hala

Kendine

Acı çektirmeye

Bayılıyor

Bu her

Halinden

Belli', 'Soyadından dolayı Ünlü biriymiş Gibi Davranırlardı ona Oysa Hiç öyle değildi Başka bir Şehirde yaşıyor Şimdi Ve evli Ama hiç değişmemiş Hala...', ARRAY['Türk Edebiyatı','Şiir','Cenk Bölük']::text[], 8.5, '{"poet":"Cenk Bölük","poet_slug":"cenk-boluk","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/evli-ve-cocuklu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahvaltı Masasında Konuşulanlar', 'kahvalti-masasinda-konusulanlar-cenk-boluk-l2d2g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni bu sabah beklemiyordum

Ama hoşgeldin

Ben de tam 

Çayı demlemiştim

Otur 

Beraber

Kahvaltı edelim

Sanıyorum

Bana önemli

Birşeyler söyleceksin.

Vişne reçeli var bak

Sen seversin.

Ne? 

Evlenecek misin? 

Hani şu çocukla

Benimle olmak için

Terkettiğin.

Ekmek bayat biraz

İstersen kızartabilirim.

Hala beni mi

Seviyorsun? 

Aslında

Teşekkür ederim

Ama

Bekar kalmayı

Tercih ederim

Çünkü

Şu sıralar

Bir nevi

Ruhsal tatildeyim

Efendim? 

Allah belamı mı

versin benim? 

Anlıyorum

Çok gerginsin

Vişne reçeli

Yemeyeceğine

Emin misin? 

Dur gitme

Hemen

Bari bir çay içseydin...', 'Seni bu sabah beklemiyordum Ama hoşgeldin Ben de tam  Çayı demlemiştim Otur  Beraber Kahvaltı edelim Sanıyorum Bana önemli Birşeyler söylece...', ARRAY['Türk Edebiyatı','Şiir','Cenk Bölük']::text[], 8.5, '{"poet":"Cenk Bölük","poet_slug":"cenk-boluk","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/kahvalti-masasinda-konusulanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme', 'gitme-sair-taylanbatu-mze3m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'şimdi sen gideceksin burdan buiyi                                                                                                  ayağında camur olacak bu da güzel                                                                                                 sade ölümlülerin   anlacağıdille edeceksin vedanı                                                                                              bu da anlaşılr                                                                            fakat gülüm ne kadar istersen iste bastıramassın                içinden gelen tanrı sesini', 'şimdi sen gideceksin burdan buiyi                                                                                                  ayağında ...', ARRAY['Türk Edebiyatı','Şiir','Şair Taylanbatu']::text[], 8.5, '{"poet":"Şair Taylanbatu","poet_slug":"sair-taylanbatu","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/gitme-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Oldun', 'ayrilik-oldun-emine-porta-fcclc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen mutluluktun, 

Hiç bitmeyecek sandığım, 

Sen küçük bir hece ile

Umuda kısalan....

Sen donuk bir bakışınla 

Umutsuzluğa uzayan.....

Şimdi ise sonu olmayan, 

Ayrılık oldun.....

                            7 OCAK 2003 Anarkali', 'Sen mutluluktun,  Hiç bitmeyecek sandığım,  Sen küçük bir hece ile Umuda kısalan.... Sen donuk bir bakışınla  Umutsuzluğa uzayan..... Şimdi ...', ARRAY['Türk Edebiyatı','Şiir','Emine Porta']::text[], 8.5, '{"poet":"Emine Porta","poet_slug":"emine-porta","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ayrilik-oldun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Yoksun', 'yine-yoksun-mehmet-uzun-x48ey', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben o bilinen şair ve yazar mehmet uzun değilim. Aynı adı taşıyan başka biri.   Bu şiirin ana teması sevgiliye duyulan hasret.', 'Ben o bilinen şair ve yazar mehmet uzun değilim. Aynı adı taşıyan başka biri.   Bu şiirin ana teması sevgiliye duyulan hasret....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Uzun']::text[], 8.5, '{"poet":"Mehmet Uzun","poet_slug":"mehmet-uzun","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/yine-yoksun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Kez', 'son-kez-emine-porta-jtjas', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dün son kez ağladım

Biten aşkımız için.

Yaşananlar çok güzeldi, 

Gecenin büyüsünü, 

Günışığının sevincini, 

Senin kollarında öğrenmek, 

Çok güzeldi.

Yanlış diyorlar  bence doğruydu, 

Seni çeyrek saatlerde sevmek zorda olsa mutluydum, 

İçimden doyasıya çığlık atmak geliyor, 

Oysa ben sustum, 

Vazgeçemem sanırdım  sevdandan, 

Vazgeçtim

Ama Unutamadım..

      	       26 Ekim 2001  ANARKALİ', 'Dün son kez ağladım Biten aşkımız için. Yaşananlar çok güzeldi,  Gecenin büyüsünü,  Günışığının sevincini,  Senin kollarında öğrenmek,  Çok ...', ARRAY['Türk Edebiyatı','Şiir','Emine Porta']::text[], 8.5, '{"poet":"Emine Porta","poet_slug":"emine-porta","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/son-kez-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sabah', 'bu-sabah-emine-porta-m8m8v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu sabah

aniden, 

kapını calmak geldi icimden.

once inanmaz bakıslarla bakar

sonra, sıkı sıkı sarılırdın.

gel derdin

yatalım, 

sana sarılarak uyumak istiyorum

sonrası malum! ! 

kim uyur.... 

		28 Eylül 2001  ANARKALİ', 'Bu sabah aniden,  kapını calmak geldi icimden. once inanmaz bakıslarla bakar sonra, sıkı sıkı sarılırdın. gel derdin yatalım,  sana sarılara...', ARRAY['Türk Edebiyatı','Şiir','Emine Porta']::text[], 8.5, '{"poet":"Emine Porta","poet_slug":"emine-porta","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bu-sabah-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkuyorum', 'korkuyorum-emine-porta-d1z7f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'korkuyorum, 

geç kalmaktan korkuyorum.

oysa, 

aşkı şimdi yaşamalıyız.

biliyorum, 

her geçen gün seni benden uzaklaştırıyor.

korkuyorum, 

sana ve aşka geç kalmaktan korkuyorum.

biliyorum, 

seni kaybedeceğim.

Ve benim için zaman geç olacak...

	25 Eylül	ANARKALİ', 'korkuyorum,  geç kalmaktan korkuyorum. oysa,  aşkı şimdi yaşamalıyız. biliyorum,  her geçen gün seni benden uzaklaştırıyor. korkuyorum,  san...', ARRAY['Türk Edebiyatı','Şiir','Emine Porta']::text[], 8.5, '{"poet":"Emine Porta","poet_slug":"emine-porta","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/korkuyorum-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Seveceğim', 'hep-sevecegim-emine-porta-8bfl3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerinin ışıltısını unutmak üzereyim

Teninin kokusunu da

Ve ellerinin sıcaklığını

Dudaklarının sertliğini

Saçlarının kıvırcığını da

Ama asla vazgeçmeyeceğim

Seni sevmekten

Belki de ümit etmek ve beklemekten

Asla vazgeçmeyeceğim.

Seni hep seveceğim....

            6 Aralık  2001    ANARKALİ', 'Gözlerinin ışıltısını unutmak üzereyim Teninin kokusunu da Ve ellerinin sıcaklığını Dudaklarının sertliğini Saçlarının kıvırcığını da Ama as...', ARRAY['Türk Edebiyatı','Şiir','Emine Porta']::text[], 8.5, '{"poet":"Emine Porta","poet_slug":"emine-porta","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hep-sevecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşündüm', 'seni-dusundum-emine-porta-zrirq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilmeni istedim, 

Hasretinle dolu bir gündü.

Bugün en çok seni düşündüm, 

Çalıştım, bir sürü iş yaptım, 

Ama en çok  seni düşündüm..

Seni niye bu kadar çok özlediğimi düşündüm

Senin beni düşünüp düşünmediğini, 

Özleyip özlemediğini düşündüm

Varlığın hala huzurum

Ben sadece seni düşündüm, 

Ve bunu bilmeni istedim....

       6 Aralık 2001      ANARKALİ', 'Bilmeni istedim,  Hasretinle dolu bir gündü. Bugün en çok seni düşündüm,  Çalıştım, bir sürü iş yaptım,  Ama en çok  seni düşündüm.. Seni ni...', ARRAY['Türk Edebiyatı','Şiir','Emine Porta']::text[], 8.5, '{"poet":"Emine Porta","poet_slug":"emine-porta","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-dusundum-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlatıyor', 'aglatiyor-emine-porta-d9ici', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne istiyorum biliyor musun? 

Bir gün sana bir mail yollamak istiyorum

Başlığı günaydınım olan, 

İçinde sadece tek bir

Evet tek bir kelime

Kocaman harflerle “VAZGEÇTİM” yazan

Bir mail yollamak istiyorum..

Seni Sevmekten, 

Beklemekten, 

Özlemekten, 

Umut etmekten, 

Hayalinle yaşamaktan, 

Yorulduğumu, 

Vazgeçtiğimi anlatacak

Tek bir kelime  yazacağım.

Ve sana bu maili yollamak düşüncesi bile

Beni ağlatıyor....

			20 Aralık 2001  ANARKALİ', 'Ne istiyorum biliyor musun?  Bir gün sana bir mail yollamak istiyorum Başlığı günaydınım olan,  İçinde sadece tek bir Evet tek bir kelime Ko...', ARRAY['Türk Edebiyatı','Şiir','Emine Porta']::text[], 8.5, '{"poet":"Emine Porta","poet_slug":"emine-porta","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/aglatiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılar', 'anilar-emine-porta-4b1ue', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hepsi benim anılarım

Her birinde ayrı tad

Ayrı lezzet bulduğum

Benim güzel anılarım

Bazı gün heyecan, 

Bazı gün korku, 

Kaçamak saatlerdeki

Özlem dolu buluşmalar

Üsküdar  Kızkulesi

Çınaraltı sabahları

Erdek akşamları

Her birinde ayrı tad

Ayrı lezzet bulduğum

Benim güzel anılarım.

Bu güzel anılar için

Teşekkürler Kıvırcığım.

			

11 Ocak 2002  ANARKALİ', 'Hepsi benim anılarım Her birinde ayrı tad Ayrı lezzet bulduğum Benim güzel anılarım Bazı gün heyecan,  Bazı gün korku,  Kaçamak saatlerdeki ...', ARRAY['Türk Edebiyatı','Şiir','Emine Porta']::text[], 8.5, '{"poet":"Emine Porta","poet_slug":"emine-porta","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/anilar-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarih Unutmadı Seni', 'tarih-unutmadi-seni-oktay-avci-7mvnw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yenilmek denmez ona

Yok olmak

Unutulmak da

Sakladılar seni

Üstünü örttüler

Gün doğmadan

Güneşin içinde kayboldun

Şimdi arasalar

İsmin gööklerde yazılı

Nüfus kütüğünde soyadın

Resmin duvarlarında sevdiklerinin

Sen devrimin sayfalarına geçtin

Belki gerçek adın değildi

Kod adın

Tarih unutmadı seni

İkinci adınla da olsa hatırladı', 'Yenilmek denmez ona Yok olmak Unutulmak da Sakladılar seni Üstünü örttüler Gün doğmadan Güneşin içinde kayboldun Şimdi arasalar İsmin göökle...', ARRAY['Türk Edebiyatı','Şiir','Oktay Avcı']::text[], 8.5, '{"poet":"Oktay Avcı","poet_slug":"oktay-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tarih-unutmadi-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamın Sesi', 'yasamin-sesi-oktay-avci-7cxva', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biri bağır bağır bağırıyor

Bu ses insanlardan

Analardan geliyor

Onlar sağır

Onlar sağır

Kime bağırıyorlar', 'Biri bağır bağır bağırıyor Bu ses insanlardan Analardan geliyor Onlar sağır Onlar sağır Kime bağırıyorlar...', ARRAY['Türk Edebiyatı','Şiir','Oktay Avcı']::text[], 8.5, '{"poet":"Oktay Avcı","poet_slug":"oktay-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yasamin-sesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hint Kınası', 'hint-kinasi-ender-guncelik-tvijv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey sevgili kader! 

Yaptığın reva mı? 

Neden böyle yaparsın yaşayan aşıklara? 

Niçin engeller koyarsın yollara? 

Her zaman niye ağlatırsın bizi, niye gülmeyi haram tutarsın? 

Yaşamın tadı sevmek, sevilmekte kaymaklı kadayıfı, 

Niye o kadayıfı bize hiç tattırmazsın? 

Hep zalimlere verirsin gülücükleri, 

Deli gibi seven yürekler açtır aşklara, susamıştır

Az da olsa sevilmeyi beklerler

Ve ben de bekliyorum bak hala 

Gözlerim hep yolda 

O gelecek diye bekliyorum, 

Bilsem de gelmeyeceğini

Allah büyüktür diyorum

Herkesi o yaratmadı mı? 

Gülen yüzleri insanın hamuruna o katmadı mı? Diye geçiriyorum aklımdan, 

Ama niye, niye ağlatırsın sen bizi, kader denen şeytan

Biraz ara ver artık, verme gözyaşlarını gözlerimize, 

En azından ufak bir tebessümü hoş gör yüzümüze

Biliyorum biz yaratılırken, mutluluk haram diye damga yemişiz yüreğimize, 

Biraz umut kalmıştı kalbimde, bu ayrılık onu da bitirecek

Benim mezarım başka bir kentte, ziyaretleri bekleyecek.

Ve sen kader, işte o zaman gülersin arkamdan

Vasiyetim olsun dostlara

Alsınlar dolabımdan senin için hint kınası.', 'Ey sevgili kader!  Yaptığın reva mı?  Neden böyle yaparsın yaşayan aşıklara?  Niçin engeller koyarsın yollara?  Her zaman niye ağlatırsın bi...', ARRAY['Türk Edebiyatı','Şiir','Ender Günçelik']::text[], 8.5, '{"poet":"Ender Günçelik","poet_slug":"ender-guncelik","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hint-kinasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KANDİL', 'kandi-l-ahmet-kurt-c5ieg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hüznünü kenarda askıya alıp, 

Dudağına gülücük tak da öyle gel.

Hayatın içinden neşeyi alıp, 

Çirkine müstehzi bak da öyle gel.

Zor olan değil mi huzur verecek, 

Karamsar duyguya göğüs gerecek

Gülen gözleriyle selam verecek, 

Boynuna buketler tak da öyle gel.

Uzat ellerini, sevda buluştur, 

Soğuyan yüreğe dokun tutuştur, 

Cihanı saracak hava oluştur, 

Gözlerinde kandil yak da öyle gel.', 'Hüznünü kenarda askıya alıp,  Dudağına gülücük tak da öyle gel. Hayatın içinden neşeyi alıp,  Çirkine müstehzi bak da öyle gel. Zor olan değ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kandil-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Işık ve Deniz', 'isik-ve-deniz-murat-tali-8lke1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gökyüzü aydınlığıyla başlarken zamana

güne yansıyan Işık 

gecenin karanlığından sonra 

farkedildi

böylece gün ışıkla doğdu

ve yaşam ışıkla başladı

sevgi doğdu ışıktan

ağaçlar yeşerdi

dereler çağladı ve 

nehirlere

döndü

nehirler bir toprağa bir ışığa bir geceye katılarak

karıştı en sonunda denize

deniz içinde sevgiyi

deniz içinde korumayı

deniz içinde ışığı tuttu

binlerce yaşam deniz''le başladı

ve deniz ışıkla besledi

yaşamın o en karanlık çağlarını

binlerce oğul geldi dünyaya

Mert''lik adına

yaşama katılmak adına

ve insan olmak adına

Işık Deniz''e Deniz Mert''liğe katıldı

yaşam dengelendi

sevgi 

ve çığlık ile', 'Gökyüzü aydınlığıyla başlarken zamana güne yansıyan Işık  gecenin karanlığından sonra  farkedildi böylece gün ışıkla doğdu ve yaşam ışıkla b...', ARRAY['Türk Edebiyatı','Şiir','Murat Tali']::text[], 8.5, '{"poet":"Murat Tali","poet_slug":"murat-tali","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/isik-ve-deniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Kurusu Gözlerin', 'gul-kurusu-gozlerin-cemal-kilinc-ez4i1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gül kuyusu gözlerin

Âşıklar öreni

Ne saklanır yer altı hacminde

Yağma olmuşsa kovanım

Haramiler saldırmış

Bahçem tarumar

Bülbül bekleye dursun

Taş dolmuş 

gül kurumuş 

gözlerin', 'Gül kuyusu gözlerin Âşıklar öreni Ne saklanır yer altı hacminde Yağma olmuşsa kovanım Haramiler saldırmış Bahçem tarumar Bülbül bekleye durs...', ARRAY['Türk Edebiyatı','Şiir','Cemal Kılınç']::text[], 8.5, '{"poet":"Cemal Kılınç","poet_slug":"cemal-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gul-kurusu-gozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Poinsettia', 'poinsettia-altug-can-aldanmaz-5p075', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kurumuş toprak misali gönlüme

Billur bir su damlası gibi girdin

Rüyalarda teselli bulan gönlüme 

Masallar diyarından bir demet gül getirdin

Elbet bir gün bitecek bu rüya

Dudağımda tek hece, elimde bu gül kalacak

Ayaklarımın altından kayacak belki de dünya

Hayaller gerçeklerin karanlığında boğulacak', 'Kurumuş toprak misali gönlüme Billur bir su damlası gibi girdin Rüyalarda teselli bulan gönlüme  Masallar diyarından bir demet gül getirdin ...', ARRAY['Türk Edebiyatı','Şiir','Altuğ Can Aldanmaz']::text[], 8.5, '{"poet":"Altuğ Can Aldanmaz","poet_slug":"altug-can-aldanmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/poinsettia-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirin Vaktine Mezmur', 'siirin-vaktine-mezmur-fikret-demirag-ll1l7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-boşlukta gezinen en eski ozan sesidir-

Bir şiir akarken damarlarında vaktin

ve sular uyurken yataklarında

ve rüzgâr geçerken ılgınlardan

biraz mezmur biraz mesih sesiyim

toprağın üstüne su gibi sızan

yaralı bir lirin sevda şarkısıyım

otlar kımıldanırken ovasında şafağın

ben yukarda parlak sabah yıldızıyım

bir şiir akarken damarlarında vaktin

Bir kadın çay koyarken gazocağına

bir çocuk ekmeğini banarken bala

bir asker soğuk gece nöbetinden

dönüp düş-kadınını alırken kucağına

ben yukarlarda dünya izleyicisiyim

ve sular kımıldanırken yataklarında

ve insanlar uyanırken yataklarında

bir şiir akarken damarlarında vaktin

Ve narin bir ağaç açarken dallarını şafağa

sabahın koyunlarına kaval sesiyim

ince keçi çıngırakları yayılırken ovaya

“ve rızıklar ve kısmetler dağıtılırken”

ve şiirler patlarken damarlarımda

ve sesimin kapaklarını açarken yüreğim

Hayat’ın dünyaya ilk fısıltısıyım

bir şiir akarken damarlarında vaktin

                                           (Lefkoşa,20.11.1986)', '-boşlukta gezinen en eski ozan sesidir- Bir şiir akarken damarlarında vaktin ve sular uyurken yataklarında ve rüzgâr geçerken ılgınlardan bi...', ARRAY['Türk Edebiyatı','Şiir','Fikret Demirağ']::text[], 8.5, '{"poet":"Fikret Demirağ","poet_slug":"fikret-demirag","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/siirin-vaktine-mezmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ara Şarkılar ve Tabletler', 'ara-sarkilar-ve-tabletler-fikret-demirag-9ibpk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Cypri! 1 Sezenler az değil, ki tohumumuz sana ekildi ; 

      toprağına bıraktı ‘bir rüzgâr’, ve vaki oldu ki

      burda yeşerdik! Burda doldu başaklarımız, burda

      üredi ‘melezlenerek’ tanelerimiz! 

      Cypri! Çekirdeğimiz ilk senin toprağına sokuldu; 

      burda budandık, aşılandık toprağının ilâhileriyle

                                        üzüme, aşka, zeytine ve şiire! 

      Bizim ‘apokalips’imiz sensin: Dünyevi kıyametimiz; 

      Yol soran yok değil başka bir ülkeye, 

                                                 yol soran çoook, 

      ama değil mi ki köklerimiz sende, ve nereye gitsek                   

      kökümüzde bir tutam toprak götüreceğiz senden, 

      öyleyse başaklarından sorsunlar bizi, 

                                      yeşil ve kehribar tanelerinden-

      Çürürsek kendi kabuğumuz içinde kıvrılarak çürürüz; 

      böyle olur ‘apokalips’imiz. Gerek yok ki

                                                           ‘İthaka’ şarkısına! 

(Ey sen, ki güneşli bir buğday tanesi gibi

                                          düştüğün bu toprakta

     akıp giden zamanlarla, ince sularla

     yeşerdin ve boy attın, başaklanıp tane tuttun, 

     ve gün gelip vakt erişince, yüreğinin de

     bu tensel güzellikler, aşklar, ihanetler toprağına

                     kendi tanelerini dökeceğini bildin

     ve ülkene ağıtçı ve türkücü yazıldın-

     Öğren: İsa mesihten elli yaprakdökümü sonra

                                        elli çiçekaçımı sonra

     nasıl daldırmıştı o ‘yasak’ düşünce

     bu toprağa ilk kılcal köklerini

                          ürkek ve belirsiz bir ışık gibi-

     Düşün: Bu küçük anne toprak, dölyatağında

     seni de besleyip -tane tut diye-

                                            büyütmedi mi? 

    Öyleyse öğren artık. Öğrenmelisin: 

                                           Yola çıkan söz

                                           yolda kalmaz…

    Ve dün kaldığın yerden sürdür şarkını-) 

       

1: Kıbrıs’ın en eski haritalardaki adı.', 'Cypri! 1 Sezenler az değil, ki tohumumuz sana ekildi ;        toprağına bıraktı ‘bir rüzgâr’, ve vaki oldu ki       burda yeşerdik! Burda do...', ARRAY['Türk Edebiyatı','Şiir','Fikret Demirağ']::text[], 8.5, '{"poet":"Fikret Demirağ","poet_slug":"fikret-demirag","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/ara-sarkilar-ve-tabletler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amaçsız Sancılara Karşı', 'amacsiz-sancilara-karsi-nihat-ozyilmaz-j4bum', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir sevdanın gölgesinde su

ve düşünsel yargılarda sen

göçmen kuşlarcasına yalnız ve beraber

yaprağın ardına gizlenir gider rüzgâr

zamansız yılkıların sağrısı, kulağı

ve dörtnalı ardında yanılgılar

sokak aralarına, kapılara, duvarlara

ve bohçacı kadınların nalınlarına kadar

aykırı bir günlük gibi güneyden kuzeye

                                   kuzeyden güneye

kendini adımlar, kendi durur / koşar

her taşın altında bir çığırtkan: 

''herkesin bir hikâyesi var! ''

kimseler görmemiş gibidir ama

pencerelerde kuşlar hem yok hem var

olur olmaz arası aynaların sırrında

tanıklık sabır gibi ne yok ne var

1995', 'bir sevdanın gölgesinde su ve düşünsel yargılarda sen göçmen kuşlarcasına yalnız ve beraber yaprağın ardına gizlenir gider rüzgâr zamansız y...', ARRAY['Türk Edebiyatı','Şiir','Nihat Özyılmaz']::text[], 8.5, '{"poet":"Nihat Özyılmaz","poet_slug":"nihat-ozyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/amacsiz-sancilara-karsi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı Şeyi, Ve Aynı Şeyi', 'ayni-seyi-ve-ayni-seyi-yasin-bolat-6mnw1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çırılçıplak soyuyorum 

Kendimin kendini 

Hazır tutmuşken cigaralığım 

Acele ziftlenmeye koyulucam; 

Çıplaklığımda 

Başımda suçlu bir istikrar 

Gizli bir acının izinde ölmeyerek 

Tekrar, ve tekrar 

Bir yarısı gecenin 

Yine kimin kaçıp giden bu ses! 

Tam burada tutan ne beni 

Kanlı gözlerimin dibinde 

Bölünmüş uykularımı vuruyorum 

En büyük pervasızlıklarımla hatırlamıştım 

Her defasında, 

Her yenilikle eskilere bıraktığım beni 

Yine biraz beni çalıyorum şimdi 

İçimde unutkan bir hırsızla 

Hiç yaşamamış mıydım oysa 

Aynı şeyi, ve aynı şeyi 

Çok eskilerden boşluğuma seçtiğim 

Vefalı bir alışkanlık bu 

Beni çıplaklığımda 

Uykumu sabaha kucaklayan 

17.01.2003', 'Çırılçıplak soyuyorum  Kendimin kendini  Hazır tutmuşken cigaralığım  Acele ziftlenmeye koyulucam;  Çıplaklığımda  Başımda suçlu bir istikra...', ARRAY['Türk Edebiyatı','Şiir','Yasin Bolat']::text[], 8.5, '{"poet":"Yasin Bolat","poet_slug":"yasin-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ayni-seyi-ve-ayni-seyi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fal', 'fal-muhtesem-oksel-1r6c9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Eh be falcı kadın! 

Vallahi içimi kararttın.

Kırk yılın başında

Bir acı kahve içtik.

Tesadüf sana rastladık ya, 

Bir fal baktıralım dedik.

İnsan, güzel şeyler söyler.

Yunuslardan, kuşlardan bahseder, 

Deve yükü kervanlardan.

İnsan anlatır, gidilecek yollardan.

Nerede kaldı kısmetler? 

Beni bekleyen taze gelinler? 

Eğer falıma bakacaksan, 

Dayanabilirim en fazla, 

Olsa olsa yürek kabartısına.

Yok efendim, 

Büyük sıkıntı yaşayacakmışım.

Resmen dumura uğrayacakmışım.

Sonrası bir haber gelecekmiş, 

Kuş misali rahatlayacakmışım.

Eh be falcı kadın! 

Saatine denk gelmiş, 

O kahrolası dediklerin.

Çıktı bir bir tüm söylediklerin.

Büyük bir sıkıntı yaşadım, inan.

Ancak geçti onca zaman, 

Hâla bir haber yok kayıp cüzdanımdan.', 'Eh be falcı kadın!  Vallahi içimi kararttın. Kırk yılın başında Bir acı kahve içtik. Tesadüf sana rastladık ya,  Bir fal baktıralım dedik. İ...', ARRAY['Türk Edebiyatı','Şiir','Muhteşem Oksel']::text[], 8.5, '{"poet":"Muhteşem Oksel","poet_slug":"muhtesem-oksel","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/fal-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Özgürlük Ne Tutsaklık', 'ne-ozgurluk-ne-tutsaklik-yasin-bolat-cmlks', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İhanet sezgilerimi çoğu zaman güçlendiriyordu gülüşlerin 

Kuşkular ve acılar ortasında seni düşüne duruyordum 

Belki de gerçekleri koynuna almış yalanlarının arasında 

Kim bilir nasıldı o hiç bilmediğim görünüşlerin 

Ne saklı oldun ne aşikă r 

Tuzaklaşmış bedeninin masum yüzlü gizleriyle 

Cümlelerinde noktaların yaşayamadığı ifadeler var 

Sayfaları açılan zihnimin köşelerinde 

Manalarının yorgun düşmüş ayak izlerinde 

Hep başlangıçlarını bulamadığım sonlar 

Ne yalan oluyorsun ne gerçek 

Uzayan satırların tehditkă r gözlerinde 

Sen karanlığa düşen yıldırımlardan değilsin 

Düğümlenmiş tutsak bakışlar var gözlerinde 

Yaşamın gizleri girdaplarla dolu gecelerinde 

Kendini aramaya çıkacakmış gibisin 

Ne şikar gibisin ne de bir avcı 

Bir av gibi kaçmıyor, avcılar gibi yakalamıyorsun 

O karanlığa tutunmuş yüreğin kayalardan da sert 

Öldürüyorsun şefkati en ummadığım anlarda 

Diplerinde yaşıyorsun acıların zamansız 

Ve bakışların bakışlarımdan daha mert 

Ne gaddarlaşıyor ne de acıyorsun 

Som soğuk bir beden keşfediyorum 

Sevgiyle sarıldığın zamanlarda 

Yıllanmıştır artık uzaklara dalan gözlerinin yamacı 

Bir kitaptın hep kapağında suskunca yaşadığım 

Seni bulamadığım 

Ve yok edemediğim bütün zamanlar 

Şimdi hatıra tadında hepsi; yani acı 

Ne çok senden kaçtım ne de sana koştum 

Sana koştum tutsak kaldı özgürlüğüm 

Senden kaçtım özgür kaldı tutsaklığım 

09.06.2000', 'İhanet sezgilerimi çoğu zaman güçlendiriyordu gülüşlerin  Kuşkular ve acılar ortasında seni düşüne duruyordum  Belki de gerçekleri koynuna a...', ARRAY['Türk Edebiyatı','Şiir','Yasin Bolat']::text[], 8.5, '{"poet":"Yasin Bolat","poet_slug":"yasin-bolat","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ne-ozgurluk-ne-tutsaklik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağır Aksak', 'agir-aksak-huseyin-karaca-5myx6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ağır aksak akan

yaşlı bir ırmak gibi

dayanmış bastonuna ayak sürüyor hayat

uzatmalar oynanıyor yaşamak sahnesinde

bizi yutar bu umman

	eğer canı isterse

Nasıl taşırdı dünya ölümler olmasaydı

ölümler olmasaydı bu kadar yükü

yol buraya kadar sabır taşı çatladı

deniz birleşecek şimdi

yer ve gök birleşecek

	hiçbir umut kalmadı

İstersen canını tak dişlerine

heybende ölüm taşı istersen

hesabım iyi değil bir de sen toplayıver

kaç eder bir ömre ölüm eklersen', 'Ağır aksak akan yaşlı bir ırmak gibi dayanmış bastonuna ayak sürüyor hayat uzatmalar oynanıyor yaşamak sahnesinde bizi yutar bu umman 	eğer ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Karaca']::text[], 8.5, '{"poet":"Hüseyin Karaca","poet_slug":"huseyin-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/agir-aksak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmiyorum Artık Bu Şehri', 'sevmiyorum-artik-bu-sehri-melih-coskun-d4lk1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dar geliyor artık bu şehir bana

Dar geliyor insanları

Dar geliyor yürekleri

Burada evlerin ışıkları 

Vurmuyor deniz kıyısına

Karşı kıyı sonsuz bir karanlık sanki

Deniz kaybetmiş ruhunu

Burada martılar duygusuz, ruhsuz

Bu denizin dalgaları acımasız

İnsanları gibi, 

İstanbul’um 

Ağlardı martıların biz ağlayınca

Deniz ağlardı 

Ağlardı boğaz içi

Gülerdi adaların gülünce

Derin kırıklar ortasındaki

Yüreği kırık insanların şehri 

İstanbul

Derin fay kırıkları yüreğinin ortasında

O kırıklar sende değil insanlarında aslında

Bekliyor o büyük sarsıntıyı her gün

Erimiş yaşadığım şehir cehennem sıcaklarında

Yürekleri erimiş insanlarının

Boşalmış göğüs kafesleri

Bu yitik şehir 

Artık bir sürgün gibi geliyor bana

Bende yitiyorum onunla günden güne

Ve ben İstanbul’u özlüyorum 

Umutlarımın tükendiği bu yerde... 

6 Kasım 2002

22: 50', 'Dar geliyor artık bu şehir bana Dar geliyor insanları Dar geliyor yürekleri Burada evlerin ışıkları  Vurmuyor deniz kıyısına Karşı kıyı sons...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sevmiyorum-artik-bu-sehri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HÜZÜN ÇİÇEKLERİ', 'huzun-ci-cekleri-ahmet-kurt-uyvfr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Açtım gözlerimi, 

Kimi zaman hava, 

Kimi zaman topraktım.

Rüzgar oldum bazen, 

Ruhlara aktım.

Filizlendim, yeşerdim, 

Ağaçta sallanan yapraktım...

Açtım gözlerimi, 

Baktım, baktım...

Bulut oldum gökte, 

Şimşek olup çaktım, 

Su olup aktım, 

Bazen da yalvaran dudaktım, 

Toprağı deşen eldim, 

Tırnaktım, 

Ve bir gün toprağa, 

Hüzün çiçekleri olarak aktım...', 'Açtım gözlerimi,  Kimi zaman hava,  Kimi zaman topraktım. Rüzgar oldum bazen,  Ruhlara aktım. Filizlendim, yeşerdim,  Ağaçta sallanan yaprak...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/huzun-cicekleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf', 'i-tiraf-huseyin-karaca-uty6b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ah ne yazık

Yamalı bohçalardan dökülen zaman gibi

ömrüm...

Geriye baktığımda

dökülen zamanları görürüm yıllarda

Yüreğime çaldığım maya tutmadı henüz

Ah ne yazık

ne yazık ki bana

kazımaktayım dibini zamanın

oysa kazınmaktayım farkında olmadan

akıp giden zamandan

fırdönen bu dünyadan

Yüreğimde bir cehennem var yine

ve bedenim

bir harabe

savaş meydanlarından kalan

Ah, ne yazık...

Ruhumuz süzgecinden geçmedi ömrüm.', 'Ah ne yazık Yamalı bohçalardan dökülen zaman gibi ömrüm... Geriye baktığımda dökülen zamanları görürüm yıllarda Yüreğime çaldığım maya tutma...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Karaca']::text[], 8.5, '{"poet":"Hüseyin Karaca","poet_slug":"huseyin-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/itiraf-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik', 'yitik-huseyin-karaca-lofew', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu şehrin ışıkları hiç sönmedi

Başka diyarlardaydı uykular

şehrin gözüne uyku girmedi

Caddelerde hayat mı akıyordu

Solgun ışıkları kaldırım direklerinin

insan denilen bedenler gösteriyordu

Savaşın mazlum çocuklarıydı onlar

Hayattan yaka silken

ve farkında olmadan 

ruhlarını düşüren

Ruhumuz güneş yüzü görmedi

/her nefeste Azrail’i çektik içimize/

oysa mum ışığı da yeterdi

Aynaların hiçbir inandırıcılığı kalmadı artık

‘Yaşamak ağrısı’ndan

gölgeler de terketti peşimizi.', 'Bu şehrin ışıkları hiç sönmedi Başka diyarlardaydı uykular şehrin gözüne uyku girmedi Caddelerde hayat mı akıyordu Solgun ışıkları kaldırım ...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Karaca']::text[], 8.5, '{"poet":"Hüseyin Karaca","poet_slug":"huseyin-karaca","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yitik-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin!', 'nerdesin-bulent-yildiz-bhn78', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nerdesin! 

Rüyalarıma hükmeden güzel, 

Çağırsam gelir misin? 

Akşamlarımın ılık samyeli

Kaldır artık gözlerindeki buğulu perdeyi, 

Gir akşamları yalnızlığımın koynuna; 

Ve aşk çıldırsın bir kızıl gecede, 

Ve ben kor olup yanayım

Dudakların kalsın kan içinde

Ve sen; 

Ve sen sevdiğini söyle

Ben günah şarkılar söylerken.', 'Nerdesin!  Rüyalarıma hükmeden güzel,  Çağırsam gelir misin?  Akşamlarımın ılık samyeli Kaldır artık gözlerindeki buğulu perdeyi,  Gir akşam...', ARRAY['Türk Edebiyatı','Şiir','Bülent Yıldız']::text[], 8.5, '{"poet":"Bülent Yıldız","poet_slug":"bulent-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/nerdesin-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsafsız', 'i-nsafsiz-ender-guncelik-k89ue', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Merhaba 

Merhaba ile başlayan bir şiir

Bu şiir aslında bir hayal ürünü

Bir gün gidecek olsam buradan

Senin arkamdan düşüncelerini sığdıracağın laf topluluğu

Bilirim sende şiir yazma gibi bir kabiliyet yok

Gerçi şiir kabiliyetle değil 

Kalpteki duygularla yazılır

Duygusuzsun kısacası

Şu an yanımda yoksun ama 

Konuşturacağım seni aşağıdaki mısralarda 

Benim gidişime bir hatıra bırakacağım

Senin ağzından çıkacağını tahmin ettiğim dizlerle

Eğer gidecek olsam şunları yazardın, buruşmuş, eski bir kağıt üstüne

“Duydum gidiyormuşsun, 

Korkma unutmam seni

Unutmam diye söz verdim ya 

Aslında hiç sözümde durmadım ama

Kusuruma bakma, sende çok aptaldın be

İki lafa kandın hemen 

Bende gözlerimle çok iyi oynadım aşkı

Ama kalbimi aralayıp bakmadın hiçbir zaman

Eğer uzanıpda bir göz atsaydın içeri

Görecektin oranın başkasına ait olduğunu

Sen hayatımda bir eğlenceydin

Küçüktün sen, bir oyuncak gibi ellerimde oynadığım

Ufak bir oyuncak

Sevilmeye hasret olduğunu nerden bilirdim

Nasıl tahmin ederdim bu kadar bağlanacağını bana...

Ama umurumda dahi değilsin

Sen sadece görmeye alışık olduğum biriydin

At gözlüğü takmış, bana delicesine bağlanmış biri

Şimdi gidiyormuşsun, ne duruyorsun ki çık ve git

Kapıdan çıktığın an siman bile kalmayacak gözümde

Hiç de üzülmeyeceğim senin için, 

Ya sen, kalbinde götüreceksin beni

Her gittiğin yere platonik aşkını da taşıyacaksın”

Ve bu satırları tamamlayınca

El sallarsın belki bana 

Ama arkanı döndüğünde bir kahkaha atarsın 

Kurtuldum diye uçarsın

Çünkü sen, sen dünyanın en insafsız insanısın....', 'Merhaba  Merhaba ile başlayan bir şiir Bu şiir aslında bir hayal ürünü Bir gün gidecek olsam buradan Senin arkamdan düşüncelerini sığdıracağ...', ARRAY['Türk Edebiyatı','Şiir','Ender Günçelik']::text[], 8.5, '{"poet":"Ender Günçelik","poet_slug":"ender-guncelik","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/insafsiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşman Başına', 'dusman-basina-hande-caner-600f5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir dert ki bu

devası yok.

bir dert ki bu

şifası yok.

Dakikalar bir hışım

saniyeler bakışım gibi

kirpiklerimden

uzaklara kaçtılar.

Zaman zaman içinde, 

Kalbur saman içinde imiş

gibi geçti günler

canı kurban seçti günler

bu zaman birimleri

meyer ne kadar açmış.

Günler 

hayırsız olup

saatler hırsız olup

maymuncuk saniyelerle

vade birimi zaman

mutluluğumu aldı

zevklerimi çaldı

dimdik fidan

bir gövde

eğildi ve alçaldı

Saniyeler, 

dakikalar, 

saatler günler

içimde ki seni, 

acımadan

yalayıp yuttular.

Adına zaman denen

ve hiç durmadan dönen

dünyanın dolanışı, 

gece gündüz, güneşi

ha babam tur edişi, 

durak bilmez, 

dert dinlemez

koşaaaaar, gider yıllarca

bu bi çare ruhum, 

yaşaaaaar gider yıllarca.

Günler çar çabuk geçer

öyle çabuk geçer ki, 

insan oğlu sevabını, 

daha fazla günahını, 

öyle ekeeer, 

öyle biceeer ki

bakmışsın ki şıp diye 

gelivermiş hasat

işte orada tükenir

hayat

heyhaaaaat.

Ardından ağlayanlarla

çabucak unutulur

eğlence günlerinin

giysisini fırçalar

bir dert ki, bu fermanı yok

bir dert ki, bu dermanı yok

bir dert ki, durdurulamaz

bir dert ki bu, 

düşmaaan başına

bu dert bastı

tam,yedinici yılına

pimp myspace', 'Bir dert ki bu devası yok. bir dert ki bu şifası yok. Dakikalar bir hışım saniyeler bakışım gibi kirpiklerimden uzaklara kaçtılar. Zaman zam...', ARRAY['Türk Edebiyatı','Şiir','Hande Caner']::text[], 8.5, '{"poet":"Hande Caner","poet_slug":"hande-caner","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/dusman-basina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Tehlike', 'tek-tehlike-mehmet-i-mal-688ag', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayat tamamiyle bir tiyatro

Yaşam tamamiyle bir rol

Bizler tamamiyle birer oyuncuyuz

ve

yazılan senaryoyu oynuyoruz

Tek Tehlike, 

Doğaçlamalar...', 'Hayat tamamiyle bir tiyatro Yaşam tamamiyle bir rol Bizler tamamiyle birer oyuncuyuz ve yazılan senaryoyu oynuyoruz Tek Tehlike,  Doğaçlamal...', ARRAY['Türk Edebiyatı','Şiir','Mehmet İmal']::text[], 8.5, '{"poet":"Mehmet İmal","poet_slug":"mehmet-i-mal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/tek-tehlike-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebebim Sendin', 'sebebim-sendin-mehmet-i-mal-81zyy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kıvılcım misali düştün içime

Oysa ben

Eski, ahçap bir ev edasıyla bekliyordum seni.

Yangınımın tek sebebi sendin...', 'Bir kıvılcım misali düştün içime Oysa ben Eski, ahçap bir ev edasıyla bekliyordum seni. Yangınımın tek sebebi sendin......', ARRAY['Türk Edebiyatı','Şiir','Mehmet İmal']::text[], 8.5, '{"poet":"Mehmet İmal","poet_slug":"mehmet-i-mal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sebebim-sendin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su', 'su-mehmet-i-mal-bzqgj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne bir gülü sevmiştim ben 

Nede bir papatyayı

Ama yinede sevdiğim bir çiçekti

Anlatamadığım emsalsiz bir çiçek

Tek isteğim

DİBİNE DÖKÜLEN SU OLMAKTI...', 'Ne bir gülü sevmiştim ben  Nede bir papatyayı Ama yinede sevdiğim bir çiçekti Anlatamadığım emsalsiz bir çiçek Tek isteğim DİBİNE DÖKÜLEN SU...', ARRAY['Türk Edebiyatı','Şiir','Mehmet İmal']::text[], 8.5, '{"poet":"Mehmet İmal","poet_slug":"mehmet-i-mal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/su-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl ki', 'nasil-ki-mehmet-i-mal-3rek7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gelecek elini uzattıkça bana

Ben inatla geçmişte benden kaçırdığın elini tutmaya çalışıyorum.

Seni severek yaşlanıyoryum

Nasıl ki seni severek öleceksem! ! !', 'Gelecek elini uzattıkça bana Ben inatla geçmişte benden kaçırdığın elini tutmaya çalışıyorum. Seni severek yaşlanıyoryum Nasıl ki seni sever...', ARRAY['Türk Edebiyatı','Şiir','Mehmet İmal']::text[], 8.5, '{"poet":"Mehmet İmal","poet_slug":"mehmet-i-mal","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nasil-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıpranmış Anıtlara Taş', 'yipranmis-anitlara-tas-baki-ayhan-t-8q6nc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yıpranmış anıtlara taş taşıyanım

baharı kıştan ayıracağım keskin çizgilerle

yeniden yapacağım tarihi, yangınlar gibi

yaklaştıracağım güzle esrimeyi birbirine

ateşe kısık gözlerle bakacağım

ağır bir sis olacağım anıtın gölgesinde

ateş: parçalanmış bakışı yıpranmış anıtların

zamana sıçrayan kıvılcımın köşesine gizlenip

kör noktalarda hiçliği bulacağım

böyle kesildiği anlaşılacak ince damarların

yıpranmanın tarihi bu, geçmişten geleceğe

kesilen ağaç gibi devrilmenin tarihi

herkesin birbirine durmadan yenildiği

savrulmanın tarihi, boşluklarda kalmanın

tavanaralarında yangınlar başlatmanın! 

yıpranmış zamanlara ateş taşıyanım', 'yıpranmış anıtlara taş taşıyanım baharı kıştan ayıracağım keskin çizgilerle yeniden yapacağım tarihi, yangınlar gibi yaklaştıracağım güzle e...', ARRAY['Türk Edebiyatı','Şiir','Baki Ayhan T.']::text[], 8.5, '{"poet":"Baki Ayhan T.","poet_slug":"baki-ayhan-t","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yipranmis-anitlara-tas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskiden Aşktı', 'eskiden-askti-mehmet-i-mal-3be8y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Eskiden aşk vardı tüm cümlelerimde

Sevgi, mutluluk vardı herbirinin özünde.

Tek bir cümleyle anlatabiliyordum kendimi

Artık cümlelerim yok

Artık paragraflarla bile anlatamıyorum kendimi.

Anlattığım her paragraf bir gün gelecek diye başlıyor

Ama o bir gün asla gelmiyor, gelmiyecek belkide.

Umutlrımla yaşıyorum artık

Hayatım umutlarımın üstünde.

Umutlarımda sönüyor zamanla

Umutlarım, 

umutsuzluğun çukurunda çırpınırken, 

bense kocaman bir boşlukta salınıyorum sanki, 

çaresiz ve mutsuzca

Bir eskiden vardı bir de şimdi

Eskiden kahkahaydı, şidi gözyaşı

Eskiden gururdu, şimdi hayal kırıklığı

Eskiden gerçekti, şidi bir rüya

Eskiden aşktı, şimdi....

Şimdi ise ne olduğunu bile bilmiyorum.......', 'Eskiden aşk vardı tüm cümlelerimde Sevgi, mutluluk vardı herbirinin özünde. Tek bir cümleyle anlatabiliyordum kendimi Artık cümlelerim yok A...', ARRAY['Türk Edebiyatı','Şiir','Mehmet İmal']::text[], 8.5, '{"poet":"Mehmet İmal","poet_slug":"mehmet-i-mal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/eskiden-askti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düğüm', 'dugum-sair-lolan-iyaau', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Vücudum düğüm düğüm

Gittiğin gün son düğüm

Bir başkadır her çözdüğüm

Seninki başka kara gözlüm

İki dünya var hep bende

Biri sensin biri alemde

Biri yazdığım her kalemde

Diğeri saklı gözlerinde

Olmayışın ansızın karşımda

Yanmışlık dudaklarımda

Ve ellerin akşamlarımda

Ölen tebessüm yanaklarımda

Vücudum düğüm düğüm

Gittiğin gün son düğüm

Bir başkadır her çözdüğüm

Seninki başka kara gözlüm', 'Vücudum düğüm düğüm Gittiğin gün son düğüm Bir başkadır her çözdüğüm Seninki başka kara gözlüm İki dünya var hep bende Biri sensin biri alem...', ARRAY['Türk Edebiyatı','Şiir','Şair Lolan']::text[], 8.5, '{"poet":"Şair Lolan","poet_slug":"sair-lolan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dugum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ram Adam', 'ram-adam-hizir-azakli-ihrjz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '“Bre embesil, bre dunkof! 

“anayasa ilerde, 

onu geri itemezsin itemez, 

suçluları bırakıp ta 

suçsuzları  zindanlarda tutamazsın tutamaz..”

bir an

bir az

HUKUK

ve adaletten

yeteneğin var ise, 

ve var ise yüreğin 

ve kalmışsa hala alnında bir damla ar

                                  çatlamamışsa damar.! 

…oku da

…bak.

 sekiz sütuna 

                büyük puntolarla: 

                                           tek başlık var: 

yüz iki milyar dolar

-	SOYULDUK...

“değil birkaç, 

                   değil  beş on

                  yüz iki bin kere

                      milyooon! 

                         dolar”

“ % 50’miz aç

ölü derilerimiz çatlak.” 

                “…hele çocuklarımız...”                         

 “ete, ekmeğe, kitaba 

                       ve de umuda muhtaç...”

sekiz sütuna tek başlık var: 

Yüz iki  milyar dolar...

                           soyulduk...

“102 milyar doları sofraya koysak, 

Çevirsek ete, ekmeğe, şaraba salataya”

40 milyon  adam - 40 yıl yer içer

“40 milyon kediye de artar ekmekten, etten.”

“…hele çocuklarımız…”

“Şişman adamın keyfi gıcırında mı? ” 

Yaprak salınsa ülkede;                        

                          o, sahibini tanır 

Yüz iki milyar dolar bu!        

                               insan olan utanır be utanır…

“Onun yağlı dostları, 

                   gıdığı sarkmış dostları, 

                         eli şampanyalı, 

başı külahlı,  beli silahlı dostları.”

                                  - bilemezler mi? 

- hepsinin de bire bir haberi vardır.          

                   

biri de o, 

sırası gelen: 

halkçı geçinen 

ram adam.

Şapkalı Adam,             

                                   Ah! ..  bir bilebilsen…

              iki kere 

                            yaş geldi iki gözümden; 

(-Dokuz yüz  yetmiş dört Kızılay Korteji’ndeyken.                            

                              “- ne ezilen ne ezen...”                        

                     ...yürüyorduk  karanlığın üstüne.

                         ete, ekmeğe, kitaba doymak için) 

                                      sevinçten...                      

Ben, 

bir de  bugün yaş-

                          landım.

                           yetmiş dörtte dökülen, 

                           umut göz yaşlarıma...

Söndü heyecanımız, 

                  azaldı verim, 

                   azaldı gelir, 

                 sustu makineler

                    çalışanımız

                   … evinde

                işten çıkarıldılar

                    sefil olduk

yüz iki milyar dolar

                 ...soyulduk.



“Bre embesil, bre dunkof: 

“anayasa ilerde, 

Onu geri itemezsin itemez.

suçluları bırakıp ta 

suçsuzları  zindanlarda tutamazsın tutamaz..”

her an 

bir az       

              çıkarıp ta öne beynini, 

kusabilirsin beynindekilerini, 

      doksan derece ful referans eğilip 

patlatabilirsin ellerini.

yetmez...

para etmez.. 

              “itlerini öne itip

               karanlıkta yol kesen kartelin” 

               köşe tetikçileri gibi,          

çekemezsen tetik, 

vermezler sana.                        

                ye – dir – mez – ler! ...

	anlasana! 

sen! 

çağdaş geçinen

                ram  adam, 

              çöken, çürüyen adam  

baş uşşak olmak için  yürüyen adam,        

   … bir damla dahi kalmışsa alnında ar, 

                      ve hala çatlamamışsa  damar

yorum

yapmıyorum.

torunlarının topraklarında

toplar

damar gibi

emperyalist işgal var! 

Uyansana! 

“Bir bak, zaman ve mekan nasıl kuşatılmışız; 

“Belli ki, en tepeden en dibe atılmışız…”', '“Bre embesil, bre dunkof!  “anayasa ilerde,  onu geri itemezsin itemez,  suçluları bırakıp ta  suçsuzları  zindanlarda tutamazsın tutamaz..”...', ARRAY['Türk Edebiyatı','Şiir','Hızır Azaklı']::text[], 8.5, '{"poet":"Hızır Azaklı","poet_slug":"hizir-azakli","theme":"Türk Şiiri","is_hero":false,"total_lines":113,"source_url":"https://www.antoloji.com/ram-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ram Adam 2', 'ram-adam-2-hizir-azakli-hrttc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '-ram adam 2

Eeeyt! 

yettiniz be! 

          yetti be! 

tüketti gücünü

     on beş telli sıcak sigortam.

           çat-

                 layacak.

                   atıyor yayım

anlatayım: 

            uzaktan geliyorum.

       tutup rüzgârları yelesinden, 

           beyaz köpüklü bulutları 

             önüne kataraktan, 

bir coşkunun süvarisi, 

bir coşkunun isyanı, 

son mesajıyla 

             halktan geliyorum … 

şefkati 

       ve erdemi 

                 ve adaleti

kucaklayaraktan geliyorum.



yorum

yapmıyorum

“sayılar tohumlarıdır umudumuzun avucunda

10 yıl 54 milyon ölü

49 milyon sakat

ölülerle sakatların memleketi, ”

ölü ve sakat bırakanlara

sadakat göstermeni, 

                         seni

                ve de çürümeni       

ibretle izliyor, ve anlamaya çalışıyorum.

bir zavallı vesilesin, 

    kim bilir? belki de  tam yerindesin, 

Sen ki, 

evrenin bileşkesi

                      mini evren; 

evrensel manifestoyu 

                            bilen 

     ve en iyi yorumlayabilendin…

bileydin

halifeydin...

 “Çoktan aldık haberi, 

bir kâse yoğurda bir kara fare gibi, 

                düştüğün günden beri...”

çıkarını, 

çıkarın için

arını 

yarınlarını 

              satarak

karını  

ve de çocuklarını  önüne katarak

                  tükendin…

sen, 

şimdi,         

         çağdaş geçinen

           beynini yiyen, 

         efendisinin ipinde

                      zinde 

                 yürüyen adam: 

           çöken, çürüyen adam,

                  ram adam! 

bilesin ki, 

bil ki; 

bilmeyenler de bilsin ki, 

 “- ve asra yemin olsun ki: ”

Baş Uşşak 

          olmak için bile

sıranın gerisinin de gerisindesin.', '-ram adam 2 Eeeyt!  yettiniz be!            yetti be!  tüketti gücünü      on beş telli sıcak sigortam.            çat-                  lay...', ARRAY['Türk Edebiyatı','Şiir','Hızır Azaklı']::text[], 8.5, '{"poet":"Hızır Azaklı","poet_slug":"hizir-azakli","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/ram-adam-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlüyorum', 'ozluyorum-halil-girgin-dpjvr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben İçim yanarken güneşi özlüyorum.

Şöyle Kavurmalı, tenimi yakmalı

Hani başımı kaldıramamalıyım yukarıya

Terler anlımdan oluk oluk akmalı

Köyümü özlüyorum Şehrin en işlek caddesinde

Sessiz sakin küçük köyümü

Gürültüsüz, insansız, sorunsuz köyümü

Şehrin en işlek caddesinde ben

yanlızlığı istiyorum.

Ben beni özlüyorum beni

Eski bende yaşamak vardı 

Ben beni özlüyorum eski beni

Ağlamak vardı, gülmek vardı.', 'Ben İçim yanarken güneşi özlüyorum. Şöyle Kavurmalı, tenimi yakmalı Hani başımı kaldıramamalıyım yukarıya Terler anlımdan oluk oluk akmalı K...', ARRAY['Türk Edebiyatı','Şiir','Halil Girgin']::text[], 8.5, '{"poet":"Halil Girgin","poet_slug":"halil-girgin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ozluyorum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Ve İstanbullu', 'i-stanbul-ve-i-stanbullu-seckin-i-nceel-bkn7o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu gece hiç bitmesin istiyorum

Severken seni delicesine

Sabah olsun istemiyorum

Doğacak günün rengini

O gizemli güzelliğini görmek istemiyorum

İçin yanarken hasretle 

Gitme kal diyemiyorum

Sevdiğimi söyleyemiyorum

Acıyor, isyan ediyorum kendime 

Ve şafak bütün gizliliyle söküyor

Yeniden sabah oluyor güneş doğuyor

Beni o soğuk yanlızlığıma itiyor

SEN GİDİYORSUN! ! ! ! ! ! ! ! ! ! ! 

Gidiyorsun bırakıyorsun beni

İçindeki memleket hasretini söndürmeye gidiyorsun

Benim içime ise yar hasretini kelepçeliyorsun

Gitme diyemiyorum susuyorum

İçindeki İstanbul hasreti uzaklaştırıyor seni

Lanet okuyorum artık İstanbul''a 

Gitme diyorum ayrılanların şehrine 

Ama sen gidiyorsun seni sevdiğimi duymadan

Sevdiğimi bilmeden ve hissetmeden gidiyorsun

Ben ise küsüp hayata lanet okuyorum İstanbul''a 

Artık her sabah olduğunda otogara

Akşam ise evinin  önüne gidiyorum

Ne otobüs geliyor ne ışık yanıyor evde

Her yer karanlık içinde aynı kalbim gibi

Seni her düşündüğümde kalbim nurlanıyor

Seni daha bir çok seviyorum yeniden seviyorum seni

Artık her  aklıma geldğinde isyan ediyorum, 

Kendime kaderime ve lanet okuyorum  İstanbul''a

Artık istanbul''u sevmiyorum ama İSTANBULLU''dan vazgeçemiyorum... 

         26 Ocak 2003 Pazar', 'Bu gece hiç bitmesin istiyorum Severken seni delicesine Sabah olsun istemiyorum Doğacak günün rengini O gizemli güzelliğini görmek istemiyor...', ARRAY['Türk Edebiyatı','Şiir','Seckin İnceel']::text[], 8.5, '{"poet":"Seckin İnceel","poet_slug":"seckin-i-nceel","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/istanbul-ve-istanbullu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Gözlüm', 'kara-gozlum-erdogan-ciray-m4mr7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kucağında kitapları

Aşktan yana hesapları

Kıvrılmış bir gül yaprağı

Taze ıslak dudakları

İlk aşkımsın liselimsin

Kalbimdeki özelimsin

Vazgeçemem kara gözlüm

Sen dünyalar güzelimsin

Kemirilmiş tırnakları

Kalem tutar parmakları

Hafif allık sürmüş mü ne

Pembe pembe yanakları', 'Kucağında kitapları Aşktan yana hesapları Kıvrılmış bir gül yaprağı Taze ıslak dudakları İlk aşkımsın liselimsin Kalbimdeki özelimsin Vazgeç...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çıray']::text[], 8.5, '{"poet":"Erdoğan Çıray","poet_slug":"erdogan-ciray","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kara-gozlum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar', 'bahar-ender-altinisik-7xwgw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'açan her çiçekle

yeni bir aşk başlar

aşk mevsimidir bahar

kimi  yaşar yaşadıkça insan

kimi de güz gelmeden solar', 'açan her çiçekle yeni bir aşk başlar aşk mevsimidir bahar kimi  yaşar yaşadıkça insan kimi de güz gelmeden solar...', ARRAY['Türk Edebiyatı','Şiir','Ender Altınışık']::text[], 8.5, '{"poet":"Ender Altınışık","poet_slug":"ender-altinisik","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bahar-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kiracı', 'kiraci-erdogan-ciray-9vtf3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Evli misin diye sorma

Seni seven beni yorma

Evli bekâr ne fark eder

Tut elimi öyle durma

Evli değil kiracıyım

Kız derdinin ilacıyım

Yaktı beni kül eyledi

Gözlerinden davacıyım

Evli isem kalbim yok mu

Bu sevda da bana çok mu

Yüreğimi deldi geçti

Bakışların kurşun ok mu', 'Evli misin diye sorma Seni seven beni yorma Evli bekâr ne fark eder Tut elimi öyle durma Evli değil kiracıyım Kız derdinin ilacıyım Yaktı be...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çıray']::text[], 8.5, '{"poet":"Erdoğan Çıray","poet_slug":"erdogan-ciray","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kiraci-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Sürgünü', 'ask-surgunu-erdogan-ciray-67q0o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kapıldım aşk rüzgârına

Rastlamadım bir kârına

Öldürecek bu dert beni

Umudum yok hiç yarına

Canım dedim candan oldum

Gülüm dedim yazdan soldum

Bir zalime gönül verdim

Genç yaşımda dertle doldum

Öyle bir hâl bir gündeyim

Tuşa geldim ben dündeyim

''Aşk Sürgünü'' oldu adım

Sürmene''de sürgündeyim', 'Kapıldım aşk rüzgârına Rastlamadım bir kârına Öldürecek bu dert beni Umudum yok hiç yarına Canım dedim candan oldum Gülüm dedim yazdan soldu...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çıray']::text[], 8.5, '{"poet":"Erdoğan Çıray","poet_slug":"erdogan-ciray","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-surgunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ecem', 'ecem-erdogan-ciray-ufvst', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yanağında benine

O ipeksi tenine

Öylesine düşkünüm

Sıcacık bedenine

Hasret kokan gecemsin

Şiirimsin hecemsin

Vazgeçemem ben senden

Erişilmez ecemsin

Çok özledim sesini

O ılık nefesini

İçimdeki yangının

Söndürsen hevesini', 'Yanağında benine O ipeksi tenine Öylesine düşkünüm Sıcacık bedenine Hasret kokan gecemsin Şiirimsin hecemsin Vazgeçemem ben senden Erişilmez...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çıray']::text[], 8.5, '{"poet":"Erdoğan Çıray","poet_slug":"erdogan-ciray","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ecem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaçlar', 'agaclar-fulden-sogut-az0j5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağaçlar bir neşedir, 

Bütün meyveleri taşır.

Elma, ayva, armut dallarını çok severiz, 

Toplar toplar yeriz.

Çocuklar çok sever, 

Bu güzel meyveleri.

Büyüklerde sever elbette, 

Bu güzel meyveleri.', 'Ağaçlar bir neşedir,  Bütün meyveleri taşır. Elma, ayva, armut dallarını çok severiz,  Toplar toplar yeriz. Çocuklar çok sever,  Bu güzel me...', ARRAY['Türk Edebiyatı','Şiir','Fulden Söğüt']::text[], 8.5, '{"poet":"Fulden Söğüt","poet_slug":"fulden-sogut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/agaclar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Geldiğinde,', 'sen-geldiginde-mine-ozdemirtas-aimuf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Geldiğin de / ki, gelirsen  söz verdiğin gibi; 

Yıldırımları bulacaksın gözlerimde / Hazırla kendini.

Bir anda, bastığın yer kayacak.

Alevlerimin tam ortasına düşeceksin /cehennem çukuru gibi.

Ellerimi tuttuğunda ise / Hiç bırakmayacaksın bir daha.

İçimden bir başka ben  uzanacak sana, sarsılacaksın.

Bilmem kaçıncı kuvvetinde var oluşunun, 

Çarpılıp çoğalacaksın Sonsuz kere /   ve soluk soluğa.

Dudaklarımla buluştuğunda dudakların; / kıyamet kopacak.

Sen, sen olmaktan çıkacaksın, / karışacaksın soluklarıma.

O andan sonra  / kendine ait bir adın olmayacak.

Ellerin olmayacak, / gözlerin, dudakların olmayacak artık.

Damıtılmış bir su gibi akacaksın hiç durmadan.

Ve... yorgun  / düşeceksin kollarıma.

Sonra.../sonrası ise / hiçbir zaman

Hiçbir zaman......... yazılamayacak satırlara.

Sadece yaşanacak. / Bir daha. / Bir daha

Bir daha /..........................................', 'Geldiğin de / ki, gelirsen  söz verdiğin gibi;  Yıldırımları bulacaksın gözlerimde / Hazırla kendini. Bir anda, bastığın yer kayacak. Alevle...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/sen-geldiginde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok', 'yok-ozan-arif-emh18', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu dava tertemiz bu dava tektir, 

Bu davada leke, benek olmak yok. 

Ülkücü dediğin çelik demektir, 

Uzamak, kısalmak sünek olmak yok. 

Neşemiz, tasamız kederimiz bir, 

Biz Nesl-i Asım''ız kaderimiz bir, 

Teşkilat, doktrin liderimiz bir, 

Kıvırmak, yamulmak, dönek olmak yok. 

Konulduğu kaptan sızanlar gibi, 

Yaptığını yıkıp bozanlar gibi, 

Kucaktan kucağa gezenler gibi, 

Herkesin öptüğü yanak olmak yok. 

Onun bunun ağzı ile öpülüp, 

Nefis için bunca hizmet tepilip, 

Arı olma sevdasına kapılıp, 

Mikrop saçan sivri sinek olmak yok. 

Lideri nerede Ülkücü orda, 

Arif de sizinle aynı kararda, 

Davamıza kurban, koç olmak var da, 

Sütünü deviren inek olmak yok.', 'Bu dava tertemiz bu dava tektir,  Bu davada leke, benek olmak yok.  Ülkücü dediğin çelik demektir,  Uzamak, kısalmak sünek olmak yok.  Neşem...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yok-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pülümür''de Bugün', 'pulumur-de-bugun-mehmet-bor-hc9ay', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir başka olmuyordu aşk, 

bugün Pülümür''de.

Feryatlar yükseliyordu, 

gökyüzüne.

Bir başka ağlıyordu, 

Pülümür''de Çocuklar.

Bir başka olmuyordu aşk, 

bugün Pülümür''de.

Çaresizlik, ihmalkarlık, aymazlık

çarpıyordu gözlerimize.

Bir başka yalvarıyordu, 

Pülümür''de yetişkinler.

Bir başka olmuyordu aşk, 

bugün Pülümür''de.

Her taraf harap, viran

aranılan kimse bulunamıyor.

Acılarla, doğa şartları

bir başka esir almış.

Kendi, kendine çabalıyordu

Pülümür''de insanlar.

27.01.2003

(geçmiş olsun)', 'Bir başka olmuyordu aşk,  bugün Pülümür''de. Feryatlar yükseliyordu,  gökyüzüne. Bir başka ağlıyordu,  Pülümür''de Çocuklar. Bir başka olmuyor...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bor']::text[], 8.5, '{"poet":"Mehmet Bor","poet_slug":"mehmet-bor","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/pulumur-de-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-mutluhan-kurt-0akjo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir şelalenin dibine saklanmış

yıkık bir kenti ağladım sabahları sana...

gülerek yürüdüğüm yollar vardı orda

şimdi fahişelere verdim o yolları

gözlerin yanıyor

gözlerin kanıyor

kapat gözlerini

bak, fahişeler de ağlıyor sana...

geceleri çıkma bu kentin kaldırımlarına

gözyaşlarıma basarsın anlamadan

perişanım seni görmeyeli

bu perişan halimle beni kanatma

sonra sen de dayanamazsın bu acıya

çıkma geceleri bu kente

pencerende ağla bak çöpçüler de ağlıyor sana...

ve sabah ve ayaz ve soğuk

tütünün sesi kulaklarımda

martıları içiyorum ağır ağır

senin gözlerinde en derin uykuların mahmurluğu

sakın uyanma

bak martılar da ağlıyor sana...

yüreğimin en kuytu yerlerine yağmur düşüyor

ıslanıyorsun

güvertesi kırılmaya yüz tutmuş bir gemide

dalgalarla boğuşan kaptan gibiyim

herkes terk ediyor seni

ben terketmiyorum

kapat şemsiyeni

bak yağmurlar da ağlıyor sana...

hatırlayacaksın gülerken utanan bir kız vardı

ömrünün fotoğraflarında

birde delikanlı

yüreği sevdaya atan

gün geçtikçe azalan ümitlerinle 

fotoğraflarda eskiyor

bak kız da ağlıyor sana...

sana yaralarımdan bir demet yapıp yolluyorum

giz''imde sakladığım acıları

ve uykusuz sabahların öksüzlüğünü

hala gücün yetiyorsa derin ayrılıklara

aç kapını, göreceksin beni

bak ben de ağlıyorum sana...

mayıs 2000 (istanbul)', 'bir şelalenin dibine saklanmış yıkık bir kenti ağladım sabahları sana... gülerek yürüdüğüm yollar vardı orda şimdi fahişelere verdim o yolla...', ARRAY['Türk Edebiyatı','Şiir','Mutluhan Kurt']::text[], 8.5, '{"poet":"Mutluhan Kurt","poet_slug":"mutluhan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/sana-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Karanfil', 'yalniz-karanfil-mavi-kalem-vei77', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ve sen nazlı çiçek

Sen dünya güzeli 

Bırakıp gitmelerin üzerine yazıldı

En büyük aşk şarkıları (şiirleri) 

Ve bırakıp gitmen üzerine yazıldı kara sevdam

Sen nazlı çiçek

Sen karanfilim

Yine yalnızım

Biliyorum sende benim gibi

Katran kara gecelerdesin

Biliyorum bir elinde kahven gözlerin dalmış uzaklara

Ve yine biliyorumki küçücük pencerenden

Kayıp giden yıldızlara bakıyorsun benim gibi

Dost''um

Can yoldaşım

Yalnızlığa uzanan yollarımın

Bir garip yolcusu

Seni sevdim ben

Sonbahar''ımda açan bir çicek gibi

Zamansız doğan bir güneş gibi

Bu şehrin üzerine çöken yağmur kokusu gibi

Seni sevdim ben

Katran kara gecelerde gözlerime doğan bir ışık gibi

Yeri geldi bir şiir gibi seni

Bir arkadaş

Belki bir yolcu gibi sevdim

Hayat yolunda

Birde karanfili sever gibi  sevdim

Yine yalnızım 

Senin gibi karanfilim

Çok kereler yeniden başlamak istedim hayata

Sanki sen yokmuş gibi

Sanki seni tanımamış gibi

Ama aldığım her nefeste taş gibi oturdun gönlüme

Elime aldığım her sigarada seni yaktım sanki

Birde sigaramın dumanında hayal etmeye çalıştığım

Senin o güzel hayalinin bir görünüp bir kaybolduğu

Seni yazdım şiir diye

Ve yine sen aktın gözlerimden

Olmadı yapamadım

Katran kara gecelerde bir günü bile

Seni düşünmeden uyuyamadım

Seni anmadığım gündüzüm olmadı

Çalan her telefonu sen sanarak açtım

Ben senin sesini duymak istedim her seferinde

Ve her telefonda bir acı oturdu içime

Bin kara saplı hançer gönlüme

Yalnızım karanfilim

Ben yine yalnızım amansız gecelerde

Katran kara gecelerde

Yalnızlığımla yarışıyorum

Senin hayalinle savaşıyorum

Ve her seferinde daha bir yenik çıkıyorum bu savaştan

Ve yine her seferinde sen galip geliyorsun', 'Ve sen nazlı çiçek Sen dünya güzeli  Bırakıp gitmelerin üzerine yazıldı En büyük aşk şarkıları (şiirleri)  Ve bırakıp gitmen üzerine yazıldı...', ARRAY['Türk Edebiyatı','Şiir','Mavi Kalem']::text[], 8.5, '{"poet":"Mavi Kalem","poet_slug":"mavi-kalem","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/yalniz-karanfil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen', 'bazen-omer-sevim-djn05', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben bende değilim bazen

Yüreğimin esiriyim

Kalbim bana asidir bazen

Gözlerim dalar düşlerdeyim

Bazen

Bir uçurumun kenarındayım

Bazen

Karanlık bir sokakta yolumu kaybetmişim

Gül yapğrağına düşmüş çiğ damlasıyım bazen

Bazende gülün dalında bir diken

Ben bende değilim bazen

Tuna gibi akarım bilinmeze doğru

Bazende bir girdap olurum

Tüm dertleri içine çeken

Ben bende değilim bazen

Bir sel misali şuursuzca akarım

Bazende bir kasırga olur

Etrafımı yakıp yıkarım', 'Ben bende değilim bazen Yüreğimin esiriyim Kalbim bana asidir bazen Gözlerim dalar düşlerdeyim Bazen Bir uçurumun kenarındayım Bazen Karanlı...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevim']::text[], 8.5, '{"poet":"Ömer Sevim","poet_slug":"omer-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bazen-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esra can', 'esra-can-omer-sevim-kmhvy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey kendini kaybetmiş insan

Sanmaki sefan sürecek

Razımıdır hiç düşündünmü senden rahman

An gelir seninde göç vaktin gelecek

Ne zaman geleceği bilinmezdir ölümün

Uyan artık dünle aynı olmasın bu günün

Rahmana yakın ol odur senin tek dostun', 'Ey kendini kaybetmiş insan Sanmaki sefan sürecek Razımıdır hiç düşündünmü senden rahman An gelir seninde göç vaktin gelecek Ne zaman geleceğ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevim']::text[], 8.5, '{"poet":"Ömer Sevim","poet_slug":"omer-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/esra-can-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NE SICAK! ! !', 'ne-sicak-altug-ozgun-eazm3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sıcak, yine sıcak...

Ne de severdim çocukluğumda yakındığım sıcağı.

Baharı özlemle bekler, yazı kucaklardım.

Sıcağı, serinle yaşardım.

Kirazı dalında, dondurmayı külahında severdim.

Geceler çabucak bitsin, 

Güneş gözüme hemen girsin isterdim.

Şimdi köşe bucak kaçıyorum, 

Çocukluğumda sevdiğim şu sıcaktan.

Sıcak, ne sıcak...

Deniz göğe, gök denize eriyor.

Bedenim toprağa eriyor.

Yaşamım yarılanırken, diğer yarısı nereye akıp gidiyor? 

Sıcak, yine sıcak...

Duaya mı çıkmak gerek yağmur için.

Kutuba mı gitmeli serin için.

Nerede poyrazın uğultusu? 

Gecenin ürperten ayazı...

Serini arıyorum.

Her sey eriyorken, sıcak kalbinde serinliği arıyorum.', 'Sıcak, yine sıcak... Ne de severdim çocukluğumda yakındığım sıcağı. Baharı özlemle bekler, yazı kucaklardım. Sıcağı, serinle yaşardım. Kiraz...', ARRAY['Türk Edebiyatı','Şiir','Altuğ Özgün']::text[], 8.5, '{"poet":"Altuğ Özgün","poet_slug":"altug-ozgun","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ne-sicak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇİÇEKLİ DAĞ SOKAĞI', 'ci-cekli-dag-sokagi-altug-ozgun-miw2y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Heybeli’nin heybetli, küçük kaldırım taşları, 

Aralarında yeşil canları, 

Boyunları bükük, taşıyorlar nice aşkları.

Seyredenler kıskanıyor, anı yaşayanları.

Tanıklık ediyor; bezgin çınar, ahşap kapı, oynaşan mandallar

Ve pencereler ardındaki saklı dünyalar.

Basamak basamak tırmanan; kenetlenen gözler, birleşen eller, 

Susayanlara cömertçe sunar taş koltukları.

Heybeli’nin heybetli, küçük kaldırım taşları, 

Aralarında yeşil canları, 

Umutlara bekçilik eder konakları.

Belkide gezgin sevdalıları, 

Yakıştırıverir dağlaşan basamaklara, 

Uçuşan çiçek karları.

Oluverir Heybeli’nin Çiçekli Dağ Sokağı.', 'Heybeli’nin heybetli, küçük kaldırım taşları,  Aralarında yeşil canları,  Boyunları bükük, taşıyorlar nice aşkları. Seyredenler kıskanıyor, ...', ARRAY['Türk Edebiyatı','Şiir','Altuğ Özgün']::text[], 8.5, '{"poet":"Altuğ Özgün","poet_slug":"altug-ozgun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cicekli-dag-sokagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öncesi', 'oncesi-i-srafil-yildizkan-nj6gm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Alımlı bir çiçek, 

-Ya da; 

Ay olsan 

Güneş olsan; 

Seherde öten bülbül 

Dikensiz bir gül 

ilkbahar bile olsan. 

Sen; 

Sen olmadıktan sonra 

Ne anlamı kalır ki 

Bütün bunların? .. 

Seni, dağlar da yaban gülü 

Harman da dane dane 

Başak gibi; 

Yüreğimde ki ısı 

Ana yüreğinde ki ateş, 

Şafak gibi, 

Can gibi sevmiştim... 

Sen, sen olmaktan, 

Vazgeçmeden önce...', 'Alımlı bir çiçek,  -Ya da;  Ay olsan  Güneş olsan;  Seherde öten bülbül  Dikensiz bir gül  ilkbahar bile olsan.  Sen;  Sen olmadıktan sonra ...', ARRAY['Türk Edebiyatı','Şiir','İsrafil Yıldızkan']::text[], 8.5, '{"poet":"İsrafil Yıldızkan","poet_slug":"i-srafil-yildizkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oncesi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DÖRT DURAK NOKTASI', 'dort-durak-noktasi-altug-ozgun-gseqd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Saat 10’un buçuğu.

30 sene öncesinde başlamış yolculuğuna, 

Ahşap, demir karışımı yolcu vapuru.

Her hafta sonu yolcularını toplar.

Ellerinden tutar götürür, 

Marmara’nın minik adalarına.

Amaçları ve istekleri farklı olsa da, 

Doğanın çağrısına uyar beton hapishanelerin, 

Sessiz sakinleri.

Belki de sese kavuşmaktır, çağrıya cevap verişleri.

Dört durak noktası bekler onları.

Dördü de birbirine benzer, dördü de birbirinden farklı.

Rehbersiz başlar gezgin turları.

Nokta nokta bellidir kavuşma kavşakları.

Seyirlik manzaraları arasına karışır kuş cıvıltıları.

Rüzgarın hırpaladığı iğne yapraklı çam ağaçları.

Dinleyebilenlere sunar bedelsiz notaları.

Ve siz de şanslıysanız, 

Sevdiğinizle duyabilirsiniz; 

Doğanın melodisine eşlik eden fülüt enstrumanını.

Aşkı yaşayanlar, doğaya aşık olur o anda.

Zaman hükmünü kaybeder; 

Kuru bir kayanın yaşlı gövdesinde, 

Yeşil çamın mağrur gölgesinde, 

Kahvenin yeşil, yeşilin mavi; 

Işığın yedi rengiyle buluştuğu her noktada.

Durağan saatler akışkanlığa kavuşunca, 

Ahşap, demir karışımı yolcu vapuru, 

Öbek öbek toplar sessiz sakinleri, 

Randevulaştığı  dört durak noktasından.

Dördü de birbirine benzer, dördü de birbirinden farklı.

Dönüş buruk ve acı.

Yanınızda sizinle atan ortak bir kalp de varsa, 

Bilin ki gelmiştir ses çıkarmak zamanı.', 'Saat 10’un buçuğu. 30 sene öncesinde başlamış yolculuğuna,  Ahşap, demir karışımı yolcu vapuru. Her hafta sonu yolcularını toplar. Ellerinde...', ARRAY['Türk Edebiyatı','Şiir','Altuğ Özgün']::text[], 8.5, '{"poet":"Altuğ Özgün","poet_slug":"altug-ozgun","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/dort-durak-noktasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İle An', 'i-le-an-i-hsan-i-lkin-dsi8p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'akşamdır

alkışlar

gecenin şah damarını

sükûn içinde

kahve fincanı

bir ucundan

bahardır

çay faslıyla başlar

uykusuz düşler

ile an

sessiz ışıklı bir ağız

gizlice götürür geceyi

dile gelen her ağacın dalında

ötüşür kuşlar

titrek ve kırılgan sesleriyle

geçti gece ile an

kararlı kalın bıyıklı ırak

meydan okunmaz adıyla

şüphesiz şüphe gerek

alkışlar

gecenin şah damarını 

sükûn içinde

geceyi dolduran karanlık 

				12.01.2003', 'akşamdır alkışlar gecenin şah damarını sükûn içinde kahve fincanı bir ucundan bahardır çay faslıyla başlar uykusuz düşler ile an sessiz ışık...', ARRAY['Türk Edebiyatı','Şiir','İhsan İlkin']::text[], 8.5, '{"poet":"İhsan İlkin","poet_slug":"i-hsan-i-lkin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ile-an-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Apartman', 'apartman-melih-cevdet-anday-xgm67', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dün iki katliydi, 

Bugün üç katli

Derken

Dört katli, bes katli, alti katli

Yükseliyor efendim yükseliyor, 

Memleket yükseliyor', 'Dün iki katliydi,  Bugün üç katli Derken Dört katli, bes katli, alti katli Yükseliyor efendim yükseliyor,  Memleket yükseliyor...', ARRAY['Türk Edebiyatı','Şiir','Melih Cevdet Anday']::text[], 8.5, '{"poet":"Melih Cevdet Anday","poet_slug":"melih-cevdet-anday","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/apartman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbim Yolcu Bağdat', 'kalbim-yolcu-bagdat-i-hsan-i-lkin-fj86t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çiçeğin duruşunda

Yağmurun dalışında yeryüzüne 

Saçlarının siyahında sonsuz

Yollara çağrılır kalbim

Kuytusunda sesimin kalbim

Koşar bir kuş gibi evrenin

Omuzlarında

Şenliktir yangın yerinde bahar

Bu adamlar da bu savaşlar da şaşkın

Kalbim

Çöl burada biter mi

Bağdat mı, gemiler geçer mi

Aşkın bildik tatları var mı

Yürekleri sevgiye vuran çocukların 

Gözleri yolcu kalbim

Bağdat’ta gün doğar mı

Kuşları ötüşen parklarda mı

Çocuklarını gözü yaşlı çağıran anneler

Kimin kesesine kalır

Sınırları kanla çizilmiş Bağdat

Roket sesleriyle geçer üstümüzden 

Yağmur yüklü bulutlar

Sayılı gün tez gelir

Yorulmazsın kalbim bu aşkın kırbacından

Patlasa bağrında bombası hıncın

Gözlerimin ormanında oturur

Savaşa katlanıp, durmayan kalbim

Ateş saçılıyor gözlerinden

Oysa denizin sevgisini yaşamalıydı

Ortasında dünyanın kalbim

Kapandık ölümün eşiğine

Toprağı kazdık sevgi ektik

Yalnızca siz yaşayın dedik

Ölüm bize, bombalar bize

Alın bir tutam kalbimi

Ban artık Bağdat’ım

Bağdat’ım

		

        		19.01.2003', 'Bir çiçeğin duruşunda Yağmurun dalışında yeryüzüne  Saçlarının siyahında sonsuz Yollara çağrılır kalbim Kuytusunda sesimin kalbim Koşar bir ...', ARRAY['Türk Edebiyatı','Şiir','İhsan İlkin']::text[], 8.5, '{"poet":"İhsan İlkin","poet_slug":"i-hsan-i-lkin","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/kalbim-yolcu-bagdat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Sevda', 'kara-sevda-guner-kaymak-ho62w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kara sevdadır bu yakar adamı

Unutturur annen ile babanı

Andırırsın davar güden çobanı

Gezersin dağlarda bir deli gibi

Uğruna yandığın bakmaz yüzüne

Ateş salar yüreğine özüne

Dünya malı görülmez ki gözüne 

Dolaşır gezersin budala gibi

Uykun gelmez geceleri yataman

Çıkarıp kalbinden söküp ataman

Yemin etme sen sözünü tutaman

Sözünde durmayan sahtekar gibi

Bu sevdaki ne yiğitler bitirdi

Aldı Aslı''yı Kerem''ide götürdü

Güner buna yenilikler getirdi

Hiç vurdum duymazdan bir arsız gibi

Ozan Güner Kaymak', 'Kara sevdadır bu yakar adamı Unutturur annen ile babanı Andırırsın davar güden çobanı Gezersin dağlarda bir deli gibi Uğruna yandığın bakmaz...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kara-sevda-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başardın', 'basardin-neslihan-ayakta-ukuma', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gökyüzüne adımı yazsam 

    Sesimi duyar mısın? ...

       Sana olan sevgimi tükettin ya, 

       Helal sana başkaları! 

       Kalbimi kırdın ya, 

       Böldün ya binbir parçaya, 

       Sana ait bir şeyler

       Bende kaldı sanki...

                         (19.08.98)', 'Gökyüzüne adımı yazsam      Sesimi duyar mısın? ...        Sana olan sevgimi tükettin ya,         Helal sana başkaları!         Kalbimi kırd...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/basardin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelecekte', 'gelecekte-neslihan-ayakta-vahf3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gün, 

Evet bir gün diyorum.

Sesimi, duygularımı, şiirlerimi

Duyurabiilsem yeni ufka

Ne dersiniz arkamdan acaba? 

O günlerde de sizi arasam 

Yüzünüz olur mu benimle konuşmaya? 

İşim gücüm hepsi bu farkındayım...

Hayatın boş olduğunu siz göremediniz diye

Suçlamaya hakkınız yok ki beni! 

Belki erken olgunlaştım

Belki de sadece saçmalıyorum...

Ama doğruyu gösteremezsiniz yine bana! 

O yüzden duyar gibiyim...

Oysa ne burnum havada

Ne de gözlerim ama...

                       (26.05.98)', 'Bir gün,  Evet bir gün diyorum. Sesimi, duygularımı, şiirlerimi Duyurabiilsem yeni ufka Ne dersiniz arkamdan acaba?  O günlerde de sizi aras...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gelecekte-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaş Mutluluk Getirecek', 'savas-mutluluk-getirecek-muhtesem-oksel-bfm9l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir bomba, bazen mutluluktur, 

Tam tepelerinde patladığında, 

Top oynayan çocukların.

Bir sevgi seli olur, 

Bacaklar, kollar koptuğunda, 

Mis gibi kokusu gelir kanın.

Patlayan mermisiyle şifa bulur, 

Cayır cayır yandığında, 

Kaçamayan hastalar, roketatarın.

Acılar bir arya olur.

Çığlıklar olur, bir senfoni.

Elbette yeşerecektir demokrasi, 

Ortadoğu’nun kara bağrında, 

Mermi yağmuru altında.

İnsan yıkımlarla, ölümle huzur bulur.

Önemli değil, ölsün tüm askerler.

Gururdur, ölüm haberi geldiğinde.

Aldırmaz onları sevenler, bekleyenler.

Ne güzel ölecek Hasan’lar, Marya’lar, 

Ayşe’ler, Coni’ler.

Alkışlayacak kurtarıcıları, 

Hayatta kalanlar, kalmayı başaranlar, 

Yaşadıklarına hayat denirse eğer.

Kutsayacak duaları, 

Çocuğu açlıktan ölen bir annenin, 

Asil kurtarıcıları.

Kıyımlara şükredecek, 

Arabasına koyarken benzin, 

Okyanuslar ötesindeki bir Amerikalı.

Ya da alkışlanacak mahalli kahramanlar, 

Kovuldu diye yabancılar, 

Yok olmuşluğun resminde.

“Ey bu gezegende yaşayanlar! 

Savaş mutluluk getirecek.

İnsanların yüzü gülecek.

Umut, savaşla büyüyecek.

Kan, kanla temizlenecek”

Diye anlatıyor kurtarıcılar

Ve aynı fikirde mahalli kahramanlar.

Yaşasın Ares’in torunları! 

Sizin modanız geçti artık

Çiçek çocukları.

Ey bu gezegende yaşayanlar! 

Bilmem siz bunlara inandınız mı? 

Benim pek aklım yatmadı.

Kimse düşünmüyor, yaşanmamış hayatları.

Kaldırın başınızı bakın yıldızlara.

Boşuna hayal etmeyin yıldızları.

Söylenen her şey aptallık, 

Bakın yazıyorum buraya, 

Yıldızlara ulaşacak kadar, 

Yaşamayacak insanlık.', 'Bir bomba, bazen mutluluktur,  Tam tepelerinde patladığında,  Top oynayan çocukların. Bir sevgi seli olur,  Bacaklar, kollar koptuğunda,  Mi...', ARRAY['Türk Edebiyatı','Şiir','Muhteşem Oksel']::text[], 8.5, '{"poet":"Muhteşem Oksel","poet_slug":"muhtesem-oksel","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/savas-mutluluk-getirecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geliyorum', 'geliyorum-neslihan-ayakta-ias8z', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İsterim son kez olmasını

Yüzünü görmeyi, 

Ağlarken gülmeni, 

Zorla yalan söylemeni.

	

Biliyordum bir tanem gideceğini...

Bana yalan söylemeseydin

Son kez seni öpebilseydim

Tutsaydım ellerini, koklasaydım tenini.

Başkası var demeseydin

Şimdi beraber olabilirdik.

Niye yalan söyledin anlayamıyorum! 

Dayanamıyorum artık, ben de geliyorum...

(11.96)', 'İsterim son kez olmasını Yüzünü görmeyi,  Ağlarken gülmeni,  Zorla yalan söylemeni. 	 Biliyordum bir tanem gideceğini... Bana yalan söylemes...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/geliyorum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Antlasma', 'antlasma-neslihan-ayakta-y2ra0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Böylece oyurmuş şiir yazıyorum, 

Oturmakla gelecek olmaz biliyorum.

Ama ne hayaller var insanın aklında! 

Düşüncelerimiz, hayallerimiz, gerçekler.

Korkuyorum hayat senden, korkuyorum...

Ama ayakta kalacağım söz veriyorum! 

Yenebilirim gerçekleri, ulaşacağım...

Zirve! 

Hepimizin istediği de bu değil mi zaten...

Zirveye ulaşmak ve ben buyum işte demek.

Kendini kanıtlayıp hayatla barış imzalamak.

Bir gün seninde buraya imza atacağına inanıyorum! 

Ben görevimi şimdi yapıyorum...

(02.04.98)', 'Böylece oyurmuş şiir yazıyorum,  Oturmakla gelecek olmaz biliyorum. Ama ne hayaller var insanın aklında!  Düşüncelerimiz, hayallerimiz, gerç...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/antlasma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Zaman', 'her-zaman-neslihan-ayakta-ppxim', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağlamak istiyorum doyasıya

Ama yapamıyorum

Seni istiyorum

Ama bir türlü yanına gelemiyorum

Dört duvar arasında 

Sanki yağmurlar işliyor içime

Üstüme üstüme yağıyorlar adeta 

Üşüyorum, üstümde bir karabulut

Sen yoksun yine

Her zamanki gibi

Kağıt, kalem, ikimizin şarkısı

Ve her zaman ben, seni bekliyorum

Artık yazamıyorum, 

Kalem elimden düşüyor

Sanırım bu saatte herkes uyuyor.

Hep seni düşünüyorum! ...

Seninle olan anılarımı geri istiyorum

İçimden hep neden diyorum

Ama eski gücüme kavuştum

Ne olursa olsun; üstümde bir karabulut

Bu karabulut hep anılarımda olacak

Ondan kaybettiklerimi aldım

Ama ne var ki 

Kalbim her zaman onda kalacak.

(16.07.1997)', 'Ağlamak istiyorum doyasıya Ama yapamıyorum Seni istiyorum Ama bir türlü yanına gelemiyorum Dört duvar arasında  Sanki yağmurlar işliyor içim...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/her-zaman-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olgunluk Yolu', 'olgunluk-yolu-neslihan-ayakta-69laf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Etrafımı kara duvarlar sardı yine, 

Herkes bana bir şey sormak istiyor.

Neden bilmiyorum, 

Kör bir karanlık çoktü yine heryere, 

Çıkamıyorum, kaçamıyorum hiçbirşeyden.

Her seferinde gerçeklerle karşılaşıyorum

Ve günden güne daha çok korkuyorum

Aynı zamanda da olgunlaşıyorum.

Belki olgunlaşınca insan gerçeklerden daha çok korkuyor.

Çünkü gerçekleri öğrenip geleceği tahmin edebiliyor.

Ben olgunlaşmak istemiyordum.

Gerçeklerle yüzleşmekti, 

Onlardan korkmak değildi benim geleceğim

Gerçekler yüzünü bana her gösterişinde

Ben kaçıyordum.

Belki de içimdeki çocuktu! 

Beni kaçırıyordu ve olgunlaşmaktan uzaklaştırıyordu

Ama çok üzgünüm sanırım ben de olgunlaştım

Hem de etrafımdakilerden çok erken! 

Şimdi at gözlükleri takmış

Sadece dünyanın iyi yönlerini gören, 

Heryeri toz pembe zanneden biri değilim.

Ne yazık ki bende bazı gerçeklerle karşılaştım.

Şimdi ben belki bir olgun oldum

Belki de sadece bir karamsar! ...

(12.08.1997)', 'Etrafımı kara duvarlar sardı yine,  Herkes bana bir şey sormak istiyor. Neden bilmiyorum,  Kör bir karanlık çoktü yine heryere,  Çıkamıyorum...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/olgunluk-yolu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesafe', 'mesafe-neslihan-ayakta-aw6vg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çizgi çekemiyorum hiçbir şeye

Olmuyor, yapamıyorum işte.

Kadermiş deyip geçemiyorum, 

İşin hep ince yanlarını işliyorum.

Şimdi kapılar açıldı, 

Mutluyum...

Geçmişe dönüp bakınca

Hem üzülüyor hem de yanlıştı diyorum.

Bu günleri aşıp geriye baktığımda

Yine mutlu olacağım.

Mutluluk ilerde bir yerde beni bekliyordu.

Yaklaştığımı hissetmek bile 

Beni yeterince mutlu ediyor...

(28.09.1998)', 'Çizgi çekemiyorum hiçbir şeye Olmuyor, yapamıyorum işte. Kadermiş deyip geçemiyorum,  İşin hep ince yanlarını işliyorum. Şimdi kapılar açıld...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/mesafe-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acılı Aşk', 'acili-ask-neslihan-ayakta-hsjgp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben bir aşk kadınıyım.

Her gün her gün aşık olmak isterim.

Doyamam ben aşık olmaya.

Ben aşık oldukça acı çekerim.

Aynı şekilde o acıyla mutluluğu hissederim

Bir anlamda ben

Sanırım sizin mazoşist dediklerinizdenim

Acıyla yaşamaya alışmışım, aşksız duramam

Biri beni sevince dayanamam, kaçarım

Mutlu olmayı kaldıramam! ...

Aşk olmayınca alışılmıştır hayat

Ama aşkla anlamsızlıkların üstüne giderim

Bu beni belki karmaşaya sokar

Ama ben bulmaca çözmeyi de severim...

(17.10.1998)', 'Ben bir aşk kadınıyım. Her gün her gün aşık olmak isterim. Doyamam ben aşık olmaya. Ben aşık oldukça acı çekerim. Aynı şekilde o acıyla mutl...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/acili-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ilk Aşk', 'ilk-ask-neslihan-ayakta-zwh4e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilmem ki nedir bu, 

İlk aşk mısın benim için? 

Bilemiyorum sen nesin.

Güzel duygular tadıyoruz beraber, 

Güzel anlar yakalıyoruz.

Hapsediyoruz onları hafızamıza.

Bir çok kez aramıza girmeye çalışsalarda

Aldılar alacaklarını ve alırlar da...

Dayak yedim senin için ablamdan, 

Parasız kaldım telefon faturalarından.

Kafamda mantıklı şey kalmadı inan.

Sana olan duygularımı ben anlasam, 

Sana da anlatırım emin olmalısın.

Korkuyorum ayrılıktan, 

Seni kaybetmekten, sensiz kalmaktan.

Utanıyorum bazense...

Korkuyorum seni kırmaktan.

Bu bitse bile bir gün, 

Hafızam elvermez unutmaya.

Çünkü sen ilksin, 

Ne de olsa başlangıçsın bu hayatta! ...

(26.10.1998)', 'Bilmem ki nedir bu,  İlk aşk mısın benim için?  Bilemiyorum sen nesin. Güzel duygular tadıyoruz beraber,  Güzel anlar yakalıyoruz. Hapsediyo...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ilk-ask-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gercekler Ayni', 'gercekler-ayni-neslihan-ayakta-uexwz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana birşey olursa, 

Dayanamaz yüreğim.

Görmek istemiyorum artık 

Ne bir son

Ne de bir başlangıç.

Herşeyin bir sonu var, 

Nekadar acı.

Anlatamam kalbimdeki sızıyı.

Şu dünyada ne asla var 

Ne de daima

Anlayamıyorum gerçekleri.

İnsanlar uzak, 

Keder kapıda...

Ne şairler geçti şu dünyadan

Hep farklı yıllarda, 

Farklı çağlarda...

Hayat aynı acı hayat, 

Gerçekler aynı acı gerçekler.

(26.10.1998)', 'Sana birşey olursa,  Dayanamaz yüreğim. Görmek istemiyorum artık  Ne bir son Ne de bir başlangıç. Herşeyin bir sonu var,  Nekadar acı. Anlat...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gercekler-ayni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Coz', 'coz-neslihan-ayakta-fdziu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölünce de güzelsin, 

Ölünce daha da güzelsin! 

Ölünce dertsizsin, 

Ölünce gerçeksin! 

(26.10.1998)', 'Ölünce de güzelsin,  Ölünce daha da güzelsin!  Ölünce dertsizsin,  Ölünce gerçeksin!  (26.10.1998)...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/coz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle', 'seninle-neslihan-ayakta-xb9hg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Donuklaştırıyor bedenimi

O buz gibi bakışın

Sıcaklığını hissetmek istiyorum

Ölümsüzlüğünle.

Duymak, görmek istemiyorum sonunu, 

Hadi anla beni biraz.

(28.10.1998)', 'Donuklaştırıyor bedenimi O buz gibi bakışın Sıcaklığını hissetmek istiyorum Ölümsüzlüğünle. Duymak, görmek istemiyorum sonunu,  Hadi anla be...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/seninle-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimdeki Işık', 'i-cimdeki-isik-neslihan-ayakta-7ybb2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yıldız parladı mı hiç sana

Sanki seni anlıyormuşcasına

Gözlerini kapatınca hissedebildin mi hiç; 

Gökyüzüne bir şimşek yayıldığında

Ay ışığını bir çırpıda! 

Gün gelir anlayabilirsin.

Ozaman görmez gözlerin

Kalbindir seni yöneten

Yeryüzü uçsuz bucaksız olur, 

Sevmeye, sevilmeye doyamazsın

Bir an bile heyecansız yaşayamazsın! 

	(18.07.1999)', 'Bir yıldız parladı mı hiç sana Sanki seni anlıyormuşcasına Gözlerini kapatınca hissedebildin mi hiç;  Gökyüzüne bir şimşek yayıldığında Ay ı...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/icimdeki-isik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gulumseyen Bakisin', 'gulumseyen-bakisin-neslihan-ayakta-g147i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sendin gözlerimden düşmeyen

Ama neden gülüşün bende kaldı! 

Silinmeyen bir leke kalbimde senin gülüşün

Sözlerinse heryerde yankılanır oldu.

Ama isyankar bakışların, 

Kıskançlık gülüşlerin, 

O çekip gidişlerin başka şeylerde de bulunuyor

Gülümseyen gözlerin sadece benimmiş

Öyle duydum ellerden; 

Bir bana bakmışsın o şekil.

Bende de kaldı ya sızısı zaten...

Besbelli ki bir yanlışlık var! 

(10.08.1999)', 'Sendin gözlerimden düşmeyen Ama neden gülüşün bende kaldı!  Silinmeyen bir leke kalbimde senin gülüşün Sözlerinse heryerde yankılanır oldu. ...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gulumseyen-bakisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Kez', 'son-kez-neslihan-ayakta-aeodo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Olasılıklar ve yorulmuş bir beden, 

Usanmışım artık oyunlardan.

Ama yine de herşey bir rayda gitmeli 

Varım için yolu takip etmeliyim.

Yoksa yine eski ben, eski masallar

Yine rüyalar ve deniz, 

Bir de gökyüzündeki yıldızlar olur herhalde, 

Şans bir kez geçer ele 

Düşünüp hareket etmeliyim! 

(10.08.99)', 'Olasılıklar ve yorulmuş bir beden,  Usanmışım artık oyunlardan. Ama yine de herşey bir rayda gitmeli  Varım için yolu takip etmeliyim. Yoksa...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/son-kez-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynilar Ayni, Ayni Olanlar Farkli', 'aynilar-ayni-ayni-olanlar-farkli-neslihan-ayakta-0qxa7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine günler daralmış 

Yine başladığım nokta önümde 

Ama değişen çok şey olmuş be! 

Yine de ben aynı benmişim.

Kimseler mi, sorma geçenleri.

Yaşananlar amaç dolu

Sonuçları nelerdir bilinmez.

İnsandan insana, 

Günden güne değişen bu sonuç seli 

İnsanları değiştiriyor

Ve herkes içine kapanıyor.

Aslında kelimeler tükeniyor! 

Kimse, kimse bilemiyor geçenleri.

Ben amaçlarımı kaybetmekten korkuyorum

Değişikliklere alıştım

İyiyi bulacağımı biliyorum.

Ne de olsa yaşamak zorunda değil miyim? 

Zorluklara dayanmak değil mi, makbul olan? 

Yine de kapansa defterler

Anlam anlamını yitirse ve 

Ve herkesin anlamı aynı oluverse.

Ama şimdi ise; 

Güvensizlik ortalıkta kol gezmekte, 

Diyarlar çoğalmış! 

Bilseler herşey aynı...

Değişen sadece mekanlar, 

Değişen sadece biraz biziz, 

Biraz yüreğimiz, 

Biraz da herşey! 

(09.09.99)', 'Yine günler daralmış  Yine başladığım nokta önümde  Ama değişen çok şey olmuş be!  Yine de ben aynı benmişim. Kimseler mi, sorma geçenleri. ...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/aynilar-ayni-ayni-olanlar-farkli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiyle Göç Başkadır O An', 'sevgiyle-goc-baskadir-o-an-neslihan-ayakta-oqctu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgiye dair birşeyler arıyor gönlüm

İçimde hissetmek istiyorum elbette ki 

Kaçarken korkulardan

Çarpıverirsin kalbini! 

Düşersin sevginin o yalancı ağına.

Sevilensindir, sevmeye çabalayan, 

Kendini kandıran

Ve aynı zamanda da kalbi kırılansındır.

Sevgisiz ölmekten korkarsın! 

Herkes yalnız ölür

Ama en azından kalbinde biriyle ölmek bir başkadır o an

Gönlüme çare bulunsa, 

Hayalleri gerçekleştirebilecek

Noterdan tasdiknamem olsa! 

Ama biliyorum, 

Ne yazık ki biliyorum ki nafile.

Sevgiye yol oluvermiş bir anda, 

Baka kalmışsın saate bir an...

İşte o an; 

Son nefesini vermek acı gelmez sana! 

Mutlulukları yaşayamadığını bilsende

Mutlu ölürsün...

Kalbinde biriyle göçüp gidersin

Bilinmez uçsuz bucaksız o diyara! 

(22.09.99)', 'Sevgiye dair birşeyler arıyor gönlüm İçimde hissetmek istiyorum elbette ki  Kaçarken korkulardan Çarpıverirsin kalbini!  Düşersin sevginin o...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevgiyle-goc-baskadir-o-an-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasa', 'yasa-neslihan-ayakta-irm47', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölmekle eş değerse ölünenler

Yaşamaya değer bulmak gerekir.

Ağacımı kestilerse benim 

Yeni dallar yaratmak benim içimdedir.

Saçlarım dalgalanır, 

Renkler anlamsızlaşır.

İşte ben ne yapacağımı bilemem...

Kollarımda izler kaldıysa

Ufak bir hileyle kapatırım.

Girer çıkarım yollara

Çünkü çıkılması gerekenler de vardır.

Dualar ederim, yalvarırım

Çoğu zaman da tutamam gözyaşlarımı.

Ama hikayeler tükenseydi

İnsanlığın anlamsızlığı ebedileşirdi.

Belki de kati şeyler...

Bırak karışma da sadece yaşa! 

Benim için değil, 

Ben dedim diye hiç değil.

Kendin için, sen istediğin için yaşa

(01.11.99)', 'Ölmekle eş değerse ölünenler Yaşamaya değer bulmak gerekir. Ağacımı kestilerse benim  Yeni dallar yaratmak benim içimdedir. Saçlarım dalgala...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yasa-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlam', 'anlam-neslihan-ayakta-764gb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne anladığın önemli değil; 

Zaten anlamlar anlamsızdır! 

Anlamaya çalışma hiçbir şeyi...

Çalışmadan anladığın; 

Asıl anlaman gerekendir.

	(02.11.99)', 'Ne anladığın önemli değil;  Zaten anlamlar anlamsızdır!  Anlamaya çalışma hiçbir şeyi... Çalışmadan anladığın;  Asıl anlaman gerekendir. 	(0...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/anlam-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonuç', 'sonuc-neslihan-ayakta-vasvy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çekilirim, 

Dağların ardına saklanıveririm. 

İzlerim herşeyi; 

Seni ve hayatı izler gülerim.

Göller oluşur gözyaşlarından, 

Renkleri soldurursun o zaman.

Gülmezsin her zamanki gibi, güldürürsün.

Şualar iner gözlerine, 

Güneşe gerek duymazsın, 

Çiçeklere bakar	

Tohumları özleyiverirsin.

Gerçekleri görüp okyanuslar yaratırsın, 

Ben de gülerim! 

Gözyaşlarında yüzüp

Güzelliklerle dansederim! 

(02.11.99)', 'Çekilirim,  Dağların ardına saklanıveririm.  İzlerim herşeyi;  Seni ve hayatı izler gülerim. Göller oluşur gözyaşlarından,  Renkleri solduru...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sonuc-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ihtiyac', 'ihtiyac-neslihan-ayakta-x48jx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kaygı ile durağa gidemem; 

Tatlı dile bak bir! ...

Korkumu al benden

Bedenimi çekiver.

Kollarımda, kalbimde acı var...

Al ne olur sevgimi, 

Al ne olur tüm benliğimi.

Şevke neden olmaz kederli sevgi! 

Al sevgimi, al kederimi, 

Bul hadi neşeyi bul zevki. 

Yol ver geçeyim, 

Yol ver bulayım, 

Sen ki yol ver yaşayayım! ...

(02.11.99)', 'Kaygı ile durağa gidemem;  Tatlı dile bak bir! ... Korkumu al benden Bedenimi çekiver. Kollarımda, kalbimde acı var... Al ne olur sevgimi,  ...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ihtiyac-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirik Gizli', 'kirik-gizli-neslihan-ayakta-4q0ei', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Konuşmaya çalıştım o akşam

Ama herşey yüreğimde saklıydı.

Her zamanki gibi söyleyemiyordu sözlerim, 

Gözlerime baksaydı anlayacaktı! 

Herkes anlardı; 

Ama herkes kaçırdı gözlerini.

Ben anlayamıyordum onlara göre

Aslında anlaşılmayan bendim.

Ve kalbi bir kez daha kırılan! 

Onu ilk kez belki de kıran bendim

Ama ben her seferinde kırılıyordum.

Çünkü olmayan doğruları arıyordum

Olmayacak yerlerde...

(06.11.99)', 'Konuşmaya çalıştım o akşam Ama herşey yüreğimde saklıydı. Her zamanki gibi söyleyemiyordu sözlerim,  Gözlerime baksaydı anlayacaktı!  Herkes...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kirik-gizli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyhude', 'beyhude-neslihan-ayakta-991xc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensiz kalmış sayfalar! 

Sokaklarda sesin kalmış, 

Gözlerin sadece uzaklardaymış! 

Anlamaz ki eller aşikar olayı...

Tefsir edilemez kalp sızısı, 

Mukaddere boyun eymek beyhude.

Bitmek bilmez bu menhüs sızı! 

(23.11.99)', 'Sensiz kalmış sayfalar!  Sokaklarda sesin kalmış,  Gözlerin sadece uzaklardaymış!  Anlamaz ki eller aşikar olayı... Tefsir edilemez kalp sız...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beyhude-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cocuk Buyudu', 'cocuk-buyudu-neslihan-ayakta-uzecy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir kalp tutuyordu ellerinde çocuk...

Sıkmaya korkuyordu

Ama ölesiye seviyordu.

Çocuk kalbi sardı

Ve bir çığlık duyuldu! 

Kalp yere düştü, parçalanmıştı...

Gözyaşları sel olup gitti

Ama nafile oyun bitmişti! 

Çocuk olmaktan sıkılmıştı, 

Büyümeye karar verdi

Ama sevgiden nefret etti! ...

(09.01.00)', 'Bir kalp tutuyordu ellerinde çocuk... Sıkmaya korkuyordu Ama ölesiye seviyordu. Çocuk kalbi sardı Ve bir çığlık duyuldu!  Kalp yere düştü, p...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cocuk-buyudu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gunahlar', 'gunahlar-neslihan-ayakta-d1uiq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bilinmez hiç kırılanlar! 

Gözlerimden ateşler geçer, 

Susamışımdır birşeylere, 

Anlayamaz o günahkar...

Saatler sayar yerinde, 

Koyu maviye bürünmüşümdür.

Beklerim gökyüzünde

Ama yıldızlardan göremem.

Öylesi çoktur ki yıldız, 

Gözlerimi alır sevgi.

Ve ay ışığına bakar ağlarım; 

Gözyaşlarım sel olur gider! 

Ve bir sevgilidir 

Benim gözyaşımla yıkanan.

Mutlu hisseder kendini, 

Gözyaşlarım sevgidendir! ...

(19.01.00)', 'Bilinmez hiç kırılanlar!  Gözlerimden ateşler geçer,  Susamışımdır birşeylere,  Anlayamaz o günahkar... Saatler sayar yerinde,  Koyu maviye ...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gunahlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Pazar', 'bugun-pazar-erdal-alga-fmafa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bugün Pazar

Güneşle ilk defa tanışıyor değilim

Nazım’lık bir durum yok yani

Ne hapishane ne de evrensel bir ülkü

Sıradan bir gün işte

Mesaiden kaçanlar için değerli

Çalışmayı seven için sıkıntılı

Yoğun çalışan için dinlencelik.

Bugün Pazar

Hayırlı pazarlar diyen yok

Bütün hayırlar cumada toplanmış sanki

Bizi pazartesiye götüren suçlu

Tembelliğin temsili uykucu

Hiçbir isme konmayan

Temizlik günü işte

Ancak bir mahpusun karısına yazdığı

Bir mektupta pazarlayabildiği.

Bugün Pazar

Temizlik günü işte

Dinlenebileceğim için mutluyum

Ama nerde

Kirliler birikmiş, yıkanması gerek

Elbiselere varıncaya kadar

Neleri var

Kalp kirlenmiş bir defa

Yıkanması gerek

Çamaşır suyu kullanmalı

Rengi cırtlak kırmızı, aşksı

Sosyalist bir çağrışım

Kanlı mı kansız mı söylevinde, kanlı

Temizlenmeli o yüzden

Çamaşır suyuyla beyazlaştı

Kırmızıya biraz masum bulaştı

Aşk kendini şaştı

Masuma az buz aşk bulaştı

Ortaya pembe çıktı, sadece sevgi

Pembe panjurlu evin sadece panjurları.

Bugün Pazar

Temizlik günü işte

Beynim temizlenmeli

Bütün öğretmenlerime kızgınım

Hepsine küfürler yağdırmalı

Sitemler dolusu mektuplar yazmalı her birine

Ve göndermeli

Ki çeksinler bana yaptıklarının cezasını.

Hep doğruyu öğrettiler

Eğri yolda şarampolden uçtum

Hep dürüstlüğü öğrettiler

Pinokyo kurtlar arasında

Kırmızı başlıklı kız kaldım

Hep onuru öğrettiler, yalakalığı men edip

Yalakalar asansöre hep önce bindi

Hep sevgiyi öğrettiler

Yürekle oynayanlara madara oldum

Mustafa Kemal’i öğrettiler

Özgün dirayetli bir lider olmayı

Ülkenin geleceği olmayı

Hiçleştirmelere maruz kaldım

Bugün Pazar

Temizlik şart

Çamaşır suyuyla yıkanmalı beynim

Ki unutsun öğrendiği bütün değerleri.', 'Bugün Pazar Güneşle ilk defa tanışıyor değilim Nazım’lık bir durum yok yani Ne hapishane ne de evrensel bir ülkü Sıradan bir gün işte Mesaid...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/bugun-pazar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farkliydik', 'farkliydik-neslihan-ayakta-6qheo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Durgun sularda seni gördüm

Ve bir şelalede kendimi...

Bir sevda masalıydı bizimki, 

Masum gençliğin hayalleriydi! 

Uçabilmek istiyordum, 

Sense kaybetme korkusuyla yaşıyordun.

Yine de maviliğimle mutluydum; 

Deniz ya da gökyüzüydü benim için.

Farklı olmamız sorun değildi...

Ellerimizde avuç dolusu sevgi

Umursamıyordum geleceğimizi.

Günler geçiyor, mevsimler çoğalıyordu! 

Ve biz büyüdük...

Gerisi iyilik, sağlık! 

(25.03.00)', 'Durgun sularda seni gördüm Ve bir şelalede kendimi... Bir sevda masalıydı bizimki,  Masum gençliğin hayalleriydi!  Uçabilmek istiyordum,  Se...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/farkliydik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'intikam', 'intikam-neslihan-ayakta-1s2mx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Müzikler var kulaklarımda.

Sevgiler her yerde kokuyor...

Ama intikam zamanı geldi! 

Her kar tanesinde beni an ve yan.

Gözlerinden ben geçeyim, 

Bir an bile senden eksik kalmayayım.

Ellerinde geriye kalan saç tellerim olsun

Ve ağla, ağla doyasıya! 

Hep beni söylesin dudakların, 

Dualardan eksik kalmayasın.

Tenimi özleyip yanasın, 

Kokuma hasret kalasın.

Başkalarını duymak değil

Duymak bile istemesin bedenin.

Hasretten kor olasın, 

Ölene dek sadık kalasın.

İhanet diline dolanırsa

Aşkından kudurasın.

Başkalarını anarsan

Dudakların parçalansın.

Bedenin sadece beni arzulasın, 

Gözlerin hep beni arasın.

Ellerinde çiçeklerle beni arayasın

Gözyaşlarınla yaşayasın.

Damarlarından adım aksın, 

Hücrelerine ulaşan ben olayım.

Kıskandırsın başkalarını sevgin, 

Bensizlikten deliresin! 

(24.01.00)', 'Müzikler var kulaklarımda. Sevgiler her yerde kokuyor... Ama intikam zamanı geldi!  Her kar tanesinde beni an ve yan. Gözlerinden ben geçeyi...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/intikam-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür Yolcusu', 'omur-yolcusu-erdal-alga-in8ui', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözden yaş düştü yüreğe

Yağmur damlalarıysa yere

Toprak kokusu burnumda

Ölümden korkmak yok, ömür yolcusu.

Ne badireler atlattık

Yoksullukta açlığı tattık

Acılardı nefese katık

Yaşamdan korkmak yok, ömür yolcusu.

Boş boş bakan gözler gördüm

Mala tapan özler gördüm

Yürekte hep közler gördüm

Yansak da tükenmek yok, ömür yolcusu.

Kendimi hep aşkı gözler gördüm

Mutluluğu özler gördüm

Yalan sözler, kem gözler gördüm

Mücadeleden kaçmak yok, ömür yolcusu.

Bu devirde yürekler yılık

Karadeniz’de gemilerim batık

Kafamın tepesi atık

Sineye çekmek yok, ömür yolcusu.', 'Gözden yaş düştü yüreğe Yağmur damlalarıysa yere Toprak kokusu burnumda Ölümden korkmak yok, ömür yolcusu. Ne badireler atlattık Yoksullukta...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/omur-yolcusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Calinirsa', 'calinirsa-neslihan-ayakta-8g9yi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Belki görülür korkusuyla

Dökemiyorum sevgimi satırlara.

Ağlıyorum umutsuzca

Ama ortada ne han var ne de kervan.

Sanki çalınacak satırlarım, 

Sanki sevgimi alacaklar ellerine! 

Vermiştim bir kez, bu defa olmaz.

Korkuyorum çalınacak satırlarım diye...

Neden yok ki yanımda, 	

Kahretsin neden hep onunla? 

Hayallerinde o var biliyorum

Ama ben bir umutla yaşıyorum, 

Hala yanında bekliyorum.

Sayfalara dağıtsamda sevgimi; 

Azalıp beni rahatlatacağı yere

Çoğalıyor günden güne...

Satırdan satıra çoğalıyor

Ve bu benliğim beni yiyip bitiriyor.

Yeter artık Tanrım

Acı çekmekten bıktım...

Neden seni seviyorum ki sanki, 

Ne geçecek elime gözyaşımdan başka, 

Ne amacım var ki seninle olmaktan öte? 

Neden seviyorum ki seni sanki, 

Sen olmaktan başka, 

Sen olmaktan öte...                                                                          (22.04.99)', 'Belki görülür korkusuyla Dökemiyorum sevgimi satırlara. Ağlıyorum umutsuzca Ama ortada ne han var ne de kervan. Sanki çalınacak satırlarım, ...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/calinirsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmaz', 'olmaz-i-hsan-uncuoglu-8e0yd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Beşpara etmez 

ciğeri 

Hiç takmaz Milleti

Takla atmak  kolay mı

Ol maz böyle gazeteci

Su sabundan Ekran 

Hop oynar kaç bayan 

Aziz Millete yok Haber 

Sorumlular nerde gezer 

Kulların hükümeti 

Sendeleme sevimli

Sende bul bir Emmi 

Yönet yap Geleceği 

Doldur boş cebini

Karga dili gagası

Karınca bed Duası

Bir Hıyanet sulfatası 

Alnında yok haya''sı

Sat Milletin Anasını! , 

Aşağılık alçak dolandırıcı 

Ekranlara kokarca gibi çıkar

Duyguları sağır uzun kulaklı

Düşmandan yanadır moral bozar, 

*

Arsız gazeteci lüks bir yazar

Cebi için bakmaz millet satar

Önü arkası kirli hain günahlı

Herzaman Palavracıdır onun adı, 

*

Her sözünde kısaca budala  yalancı

Milletine çifte atar 302 çöp arabası,', 'Beşpara etmez  ciğeri  Hiç takmaz Milleti Takla atmak  kolay mı Ol maz böyle gazeteci Su sabundan Ekran  Hop oynar kaç bayan  Aziz Millete y...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/olmaz-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Bittim', 'ben-bittim-ensar-aktas-iqdvo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mevsim bahardı

Kardelenler süslemişti karları

Rengarenk çiçekler açmıştı

Şenlendirmişti kuru dalları

Gözlerin değmişti gözlerime

Aşk düşmüştü küflenmiş yüreğime

Şimdi mevsim sonbahar

Başaklar boyun eğdi, sarardı

Bir bir düştü yapraklar

Güller yalnız bıraktı çalıları

Seni kopardı dalımdan ayrılıklar

Sen gittin, aşk bitti, ben bittim

Rotterdam,25.12.2002', 'Mevsim bahardı Kardelenler süslemişti karları Rengarenk çiçekler açmıştı Şenlendirmişti kuru dalları Gözlerin değmişti gözlerime Aşk düşmüşt...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ben-bittim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş, Sevda ve Yalnız Aşk', 'dus-sevda-ve-yalniz-ask-ali-rodi-ozkan-hxtud', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimliksiz yalnızlıkların acıyan yüzüdür 

Apansız gelen her sevda

Düş ile sevdanın oyunudur gerçeğe

Rengini yitirmesidir yağmurun

ille de yakmasıdır gözlerinin ateşi

Yel ile tozan savruluşların adıdır

Ekmek gibi aşk gibi

Kabullenişlerin yazgısıdır kör kuyular

Irkı olmayan aşklardır gülleri solduran ve 

Lal bir çoçuğun gözlerinde çığlıktır seni sevmek 

Irmak olup akmaktır yüzünün deltasında 

Çaresiz büyümektir her sevda, zamanı varken 

                                         Aşk gibi ölüm gibi...', 'Kimliksiz yalnızlıkların acıyan yüzüdür  Apansız gelen her sevda Düş ile sevdanın oyunudur gerçeğe Rengini yitirmesidir yağmurun ille de yak...', ARRAY['Türk Edebiyatı','Şiir','Ali Rodi Özkan']::text[], 8.5, '{"poet":"Ali Rodi Özkan","poet_slug":"ali-rodi-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/dus-sevda-ve-yalniz-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rotterdam Neden Ağlıyor', 'rotterdam-neden-agliyor-ensar-aktas-29h29', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Niye bu karamsarlık, bu hüzün yine

Niçin kara bulutlar gölge gibi düştü üzerine

Neden ıslandı gözleri koskoca şehrin

Rotterdam neden ağlıyor yine

Şu ihtişamlı çift minare mi

Bulutları delip ağlatan

Yoksa şu görkemli gökdelenler mi

Bilmiyorum, ama bu kasvet içimi dağlıyor

Kes artık ağlamayı çocuklar gibi

Koskoca şehre yakışmıyor, ağlamak benim hakkım

Bırak ta ben ağlayayım

Boğarsa bir beni boğar sel olan gözyaşlarım

Ağlarsa bir kişi ağlar ardımdan

Binlerce yürek kan ağlar sen boğulursan

Rotterdam, bu halin herkesi kahrediyor

Böyle hüzünlü böyle loş bir akşam üstüydü

Sevdiğimi vapura bindirişim

Sen ağlıyordun, ben ağlıyordum, o gidiyordu

Aklım onunla gidiyordu, ben yetim kalıyordum

O yüzden yüreğim parçalanıyor

Her ağlama faslında

Buna artık kalbim dayanmıyor

Yeter artık, Rotterdam neden ağlıyor

Rotterdam/Woerden,10.01.2003', 'Niye bu karamsarlık, bu hüzün yine Niçin kara bulutlar gölge gibi düştü üzerine Neden ıslandı gözleri koskoca şehrin Rotterdam neden ağlıyor...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/rotterdam-neden-agliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgililer Günü', 'sevgililer-gunu-ensar-aktas-kl5x6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu ilk ve son sevgililer günü sensiz geçirdiğim

Oysa ben seni sevgi kelimesinin manasını aşarcasına sevmiştim

Ve kalplerimiz bir daha ayrı çarpmayacak, 

Gözlerimiz bir daha mahreme bakmayacak diye bilmiştim

Gidişin kalbime düşüşünden daha yakıcı oldu

Ve son sevgililer gününde bana verdiğin gül vazoda sararıp soldu

‘Bu gül solarsa bilki sana olan sevgimde soldu’ demiştin

Bende sana; ‘o zaman bu yürekte solar’ demiştim

Ve çok suni teneffüsler yaptım yüreğimi kurtardım, ama

Nasip bu son sevgililer gününeymiş solgun çiçeğim

Yüreğim sensizliği, bense artık bu yüreği taşıyamıyorum

Oysa sonsuza dek seni sevip, seni bekleyebilirdim

Bensiz geçen ilk sevgililer günün kutlu olsun bebeğim

Son darbeyi sen vurdun, ama olsun sana kızmıyorum

Son nefesimde de ‘seni seviyorum’ diyerek gidiyorum

Rotterdam,24.12.2002', 'Bu ilk ve son sevgililer günü sensiz geçirdiğim Oysa ben seni sevgi kelimesinin manasını aşarcasına sevmiştim Ve kalplerimiz bir daha ayrı ç...', ARRAY['Türk Edebiyatı','Şiir','Ensar Aktaş']::text[], 8.5, '{"poet":"Ensar Aktaş","poet_slug":"ensar-aktas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgililer-gunu-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sana Anlattım Seninle', 'seni-sana-anlattim-seninle-melih-coskun-frkpm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni sana anlattım seninle

Seni sana anlattım bensiz zamanlarda

Sen çizerken kendini ak kağıtlara

Ben yoktum sokaklarında şehrin

Kırgındın, 

Üzgündün, 

Öfkeliydin, 

Umutsuz değildin fakat

Yorgundun, 

Susamıştın, 

Acıkmıştın, 

Beter hırpalanmıştın kuytularda, 

Bir tas su veremedim sana 

Bir somun ekmek veremedim 

Saramadım durmadan kanayan yaralarını, 

Göremedim seni meydanlarda

Yürürken sokaklarda, 

Bağırırken tenhalarında şehrin, 

Süremedim yüzüme dalgalanan bayrağını, 

Ben yalnız seni sana anlattım senin güzel sesinle

Seni anlattım sana bensiz zamanlarda, 

Düşüşünü anlattım, 

Hiç girmediğim o çıkmaz sokaklarda.

Seni anlattım; 

Haykırışını gökyüzüne

Korkusuz gözlerini, 

Ben seni anlattım sana sonsuzluğunla

Kavgamız kadar güzel gözlerini senin, 

Seni sana anlattım umudunla, 

Yarını...

13 Aralık 2002

22: 26', 'Seni sana anlattım seninle Seni sana anlattım bensiz zamanlarda Sen çizerken kendini ak kağıtlara Ben yoktum sokaklarında şehrin Kırgındın, ...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/seni-sana-anlattim-seninle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müsabaka', 'musabaka-gokcen-duran-lo0dg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlk yarı

Deniz,  uykuda  ve  suskun

Balık, gezgin ve tedirgin

Martı, aç  ve  telaşlı

İkinci  yarı

Deniz,  besledi  balığı

Balık,  martıyı

Martı,  manzarayı

Kanatları  ve  sesiyle

Sonuç

Deniz,  yorgun

Balık,  varoluşçu

Martı,  nihilist', 'İlk yarı Deniz,  uykuda  ve  suskun Balık, gezgin ve tedirgin Martı, aç  ve  telaşlı İkinci  yarı Deniz,  besledi  balığı Balık,  martıyı Ma...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/musabaka-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarsıldık', 'sarsildik-melih-coskun-0irzf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sarsıldık

Derin yarıklar böldü 

En derin uykularımızı

Çıldırdı dünya

Yeryüzü öfkesini kustu

Atmak istercesine hepimizi üzerinden

Düştük yere 

Beton bloklar altında kaldı bedenimiz

Ağlayamadık 

Sustuk

Sadece sustuk

Baktık 

Yıkılan beton blokların altına

Ses soluk çıkmıyordu

Enkaz altında kalmak mı

Yoksa dışarıda olmak mı 

Hangisi daha zor bu gece

Yukarda kalanlar 

Asıl ölen onlardır bu gece

İnsanca yaşamak istediler

Olmadı

Bari insanca ölelim dediler bir gün

İnsanca ölmek bile zordu bu diyarlarda

Bir ılık su değildir 

Ezilmiş bedenime döktükleri

Su değil 

Bembeyaz kireçtir bedenimdeki

Toprak olmak istedik biz sadece 

Toprak

Beton değil

Dostlar sevgiyle indirsinler istedik 

O ebedi çukura

Bir dozer kepçesi değil

Biz insanca ölmek istedik sadece

Yaşayamadığımız gibi insanca...

13 Kasım 2002

01: 53', 'Sarsıldık Derin yarıklar böldü  En derin uykularımızı Çıldırdı dünya Yeryüzü öfkesini kustu Atmak istercesine hepimizi üzerinden Düştük yere...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sarsildik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anı Yaşmalıyız', 'ani-yasmaliyiz-gokcen-duran-1jbgz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mutluluğun   geçmişte  kaldığını  sanırız

Sürekli  geçmişe  dönük  yaşamamız  bundandır

En  güzel  anıları

Geçmişin  tozlu  sayfalarında  aramamız  bundandır

Oysa  geçmişteki  mutluluklar   yıldızlar  kadar  uzaktır  bize

Mutluluk,  mutsuzluğa  inat

İçinde  bulunduğumuz  anda  saklıdır...

Geçmiş  ile  gelecek  arasında

Cennettir  bulunduğumuz  an

Yaşayacaklarımız,  yaşadıklarımıza  inat

Tüm  açıklığıyla  önümüzde  durur

Yaşanacaklar  en  güzel anda  yaşanır

Özgürce,  telaşsızca, kaygısızca...

Anı  yaşamıyorsak

Gelecek  kaygısını  da  yanımıza  alarak

Günü  geçmişin  zindanında  yaşarız

Sonsuza  kadar...', 'Mutluluğun   geçmişte  kaldığını  sanırız Sürekli  geçmişe  dönük  yaşamamız  bundandır En  güzel  anıları Geçmişin  tozlu  sayfalarında  ar...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ani-yasmaliyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Feyiz Irmağı', 'feyiz-irmagi-hasan-sen-a5ryp', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rehberimiz’dir  Muhammed  Mustafa

Mürşidimiz ise  Haydar Ali  Mürteza

Severiz  Ehli Beyti, canımız  feda

Ehli Beyt’dir  bizim  feyiz  ırmağı

Vacip  der  sevmeyi  İmam  Hanefi

Şafi ise farz der Ehli Beyti sevmeyi

Bilmemki  ne der  Maliki  Hambeli

Ehli Beyt’dir  bizim  feyiz  ırmağı

Rasulün sevgili kızı’dır Ali’nin  yari

Hasan ile Hüseyin’dir onun çiğer paresi

Yakar Fatıma ana’mın feryadı heryeri

Ehli Beyt’dir  bizim  feyiz  ırmağı

Hasan-i Mücteba’dır beşinci Halife

Bırakmadı Ebu Yezid ona bir sene bile

İkinci’dir  Oniki  İmam’in içinde

Ehli Beyt’dir  bizim  feyiz  ırmağı

Hüseyin-i  Kerbela’dır yürekleri yakan

Susuz  kaldı  çölde  uzun  bir  zaman

Tarihde  odur  susuz  şehid  olan

Ehli Beyt’dir  bizim  feyiz  ırmağı

                                                                   

Yazmayalım  Oniki  İmamların ismini

Sonra  uzun  olur  bu  yazdığımız yazı

Belki  usanır  okuyanların  bazıları

Ehli Beyt’dir  bizim  feyiz  ırmağı

Tarikatımız Kadiri  erenler  yolu

Kolumuz Hüseyni Ehli Beyt kolu

Pirimiz  Geylani  nurludur  yolu

Ehli Beyt’dir  bizim  feyiz  ırmağı

                                                                   

Oniki  Tarikatın  manevi hükümdarı

Pir’e gider cezbe ve sülük yolları

Geylani’dir şerif ve seyyid’lerin başı

Ehli Beyt’dir  bizim  feyiz  ırmağı

Şeyhimiz Hak Halili kızı Bacı Sultan

Onlardan almıştır himmeti Halil Arcan

Şimdi ise  şeyhlerde  postda  oturan

Ehli Beyt’dir  bizim  feyiz  ırmağı   

                                                                 

Yanıyor  kardeş  içim  yanıyor

Bizi  gören  Alevi-Bektaşi sanıyor

Alevisi  Sunnisi bunu böyle  yazıyor

Ehli Beyt’dir  bizim  feyiz  ırmağı

Haydi  kardeş  gel artık bırak inadı

Hasan der Nakşi  Kadiri  herbiri  aynı

Yapma arasında  büyük küçük ayırımı

Ehli Beyt’dir  bizim  feyiz  ırmağı    

Deme kardeş bunu nasıl yazdın böyle

İçimde’ki aşk ateşi geldi kaleme

Beğenmezsen eğer söyleme kalsın sende

Ehli Beyt’dir  bizim  feyiz  ırmağı', 'Rehberimiz’dir  Muhammed  Mustafa Mürşidimiz ise  Haydar Ali  Mürteza Severiz  Ehli Beyti, canımız  feda Ehli Beyt’dir  bizim  feyiz  ırmağı...', ARRAY['Türk Edebiyatı','Şiir','Hasan Sen']::text[], 8.5, '{"poet":"Hasan Sen","poet_slug":"hasan-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/feyiz-irmagi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Halleri', 'askin-halleri-gokcen-duran-7gl5a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben seni aşkın bütün halleriyle sevdim

Seninle yaşadım aşkın her halini

Ben seni yalın halle sevdim

Bütün doğallığıyla sende yaşadım aşkı

Ben seni aşkın i haliyle sevdim

“Seni seviyorum” dediğim andaki

i sesinin ateşiyle sevdim.

Ben seni aşkın e haliyle sevdim

“Sana aşığım dediğim zaman ki, 

a sesinin sana yönelişiyle sevdim.

Ben seni aşkın de haliyle sevdim

“Sende yaktım gemileri” sözündeki

de nin kararlılığıyla sevdim.

Ben seni aşkın den haliyle sevdim

Beni sana bağlayan ile ’nin 

Bağlayıcılıyla sevdim.

Ben seni aşkın bütün halleriyle sevdim

Aşk bütün hallerini sende gösteriyordu.

Aşk, yalınlıktı

Aşkı, yaşıyordum

Aşka, tutkuluydum

Aşkta, uçuyordum

Aşktan, çok şey öğrendim

Aşkla, komşu oldum yıldızlara', 'Ben seni aşkın bütün halleriyle sevdim Seninle yaşadım aşkın her halini Ben seni yalın halle sevdim Bütün doğallığıyla sende yaşadım aşkı Be...', ARRAY['Türk Edebiyatı','Şiir','Gökçen Duran']::text[], 8.5, '{"poet":"Gökçen Duran","poet_slug":"gokcen-duran","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/askin-halleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A-saf Kardeşim, Giderler', 'a-saf-kardesim-giderler-erdal-alga-s9lut', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Özdemirim aa-safım benim, a-saf kardeşim

Gitmeyecek sandın değil mi, giderler

Hem öyle bir giderler ki…

Anasını bile satarlar sevginin, anasını

Kale bile almadan seni giderler.

Ey şair müsvetteleri

Senin gibi benim gibi

Ne bilsinler sevmeyi

Çeker giderler gelmemek üzere bir daha

Geçer gider günler aynen

Hep geçer gelir sevgi haneme karnede

Kalmam yakın bu dertten

Ben kalırım, onlar giderler.

Giderler Asaf giderler

Bir bilinmezliğe belki

Denizde bir damla misali

Gözden bir damla gider

Ardından bir başkası

Seller gider

Katıp içine umutlarımı

Hasar kalır geride

Ben kalırım

Selle gider her şey

Sela veriri bir müezzin

Salla gider içimde biri

Salla gider Asaf salla gider! 

Sallamam hayat anca gider.

Afet bölgesinin geleni olmaz

Talanı zaten vardır

Ardından da yalan gelir

Bir politikacı boy gösterir

Gider ve bir daha nah gelir

Baykuşlar gelir oraya

Bayan kuşlar gelmez, yarin gelmez

Ve bir gün

Yeni yapılan binalar antik olur

İşte o zaman bir de, arkeologlar gelir.

Dalgalar gider gelir

Aklım gider gelir

Sevdiklerimiz gider gelmez

İki gider bir gelirde; zarardayızdır

İki gider gelmezde; batakta

İşte kalbin iflas öyküsü

İcra memurları kapıda

Giderler Asaf giderler

Ha Lavinia ha nokta nokta

Adını bile ansam içimde ağrılar, ağırlıklar

Giderler Asaf giderler

Onlara ne bir ceket

Ne şair bir yürek yeter.', 'Özdemirim aa-safım benim, a-saf kardeşim Gitmeyecek sandın değil mi, giderler Hem öyle bir giderler ki… Anasını bile satarlar sevginin, anas...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/a-saf-kardesim-giderler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay-R-ılık3', 'ay-r-ilik3-erdal-alga-oe2xd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ay! R-ılık R-ılık esiyor rüzgar

Ay, R-ılık R-ılık düşürüyor yüzüme ışınlarını

-R’de düğümleniyor bu şiirin ayrılık yanı

Sert-sessiz bir öfke oluşuyor içimde, -R’ye karşı

Bir an gelip belki haykıracak

Alfabenin 8 ünlüsüne öykünerek.', 'Ay! R-ılık R-ılık esiyor rüzgar Ay, R-ılık R-ılık düşürüyor yüzüme ışınlarını -R’de düğümleniyor bu şiirin ayrılık yanı Sert-sessiz bir öfke...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ay-r-ilik3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Alıp Gitsen Başını', 'simdi-alip-gitsen-basini-melih-coskun-c42ln', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi alıp gitsen başını 

Uzak ve kimsesiz şehirlere

Başını sokacak bir kavga bulamazsın

Bugün kavganın değil 

Kavgasızlığının günüdür

Biz değiştik 

Değişti gökyüzü 

Ve değişti acı yüzlü çocuklar

Akşam olur 

Sokaklarda 

Yitirilmiş bir kavganın

Yetim kalmış çocukları 

Bayrağının renkleri solgun

Kırlarda kaybolmuş ayak izleri

Değiştik, 

Hürriyet sözcüğü bile 

Yeşil kağıtlardaki Amerikalının yüzü kadar

Heyecanlandırmıyor artık bizi

Biz değiştik 

Aşkın tanımı da değişti

Eskiden kavgada bir yürek diyorduk 

Yalansız ve tertemiz bir yürek

Ölünen, öldürülen, dağları aştıran, zindanlarda yatılan

Şimdi yaşanan ışıltılı ve satılmış gecelerinde metropollerin

Değişmeyen bir şey varsa hayatında

Oda yüreğinin en derin köşesinde 

Yıllanmış bir şarap edasıyla sakladığın 

Ve kimselere göstermediğimiz hüznündür.

Alıp başını çekip gitsen 

Uzak ve kimsesiz şehirlere

Başını sokacak bir kavga bile bulamazsın 

Kavgan bitmiştir 

Acı yüzlü çocukların çekip gitmiştir çoktan

Ve bu kavgadan sana

Yıllanmış bir hüzün kalmıştır sadece...

21 Aralık 2002

19: 07', 'Şimdi alıp gitsen başını  Uzak ve kimsesiz şehirlere Başını sokacak bir kavga bulamazsın Bugün kavganın değil  Kavgasızlığının günüdür Biz d...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/simdi-alip-gitsen-basini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürüyoruz Hayatı Adımlarımızı Saymadan', 'yuruyoruz-hayati-adimlarimizi-saymadan-melih-coskun-bxn4c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yürüyoruz hayatı adımlarımızı saymadan

Yaşanılandan geriye ne kaldığına aldırmadan

Yürüyorum dışarıda çelik gibi bir ayaz

Delip geçiyor göğsümü

Buharlaşarak çıkıyor ağzımdan şiirler

Mühim olan adımlarını saymak değildi bu hayatta

Mühim olan nasıl yürüdüğündür bu yolda

Sana yürüme diyenin zorbalığına inat yürüyebilmektir...

21 Aralık 2002

00: 57', 'Yürüyoruz hayatı adımlarımızı saymadan Yaşanılandan geriye ne kaldığına aldırmadan Yürüyorum dışarıda çelik gibi bir ayaz Delip geçiyor göğs...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yuruyoruz-hayati-adimlarimizi-saymadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özetlenmiş Bir Gençlik', 'ozetlenmis-bir-genclik-melih-coskun-cbdd5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'I.

Uçurum diplerinde bekle beni

Kanının Kızılırmağ’ı kızıllaştırdığı yerde

Geleceğim akşam çökmeden 

Gözyaşının yağmura karıştığı yerde bekle beni...

II.

Erkenden toprak olursa bu tükenmez umudun

Toprak utanmaz mı topraklığından

Gencecik bedeninden

Seni düşüren namlu utanır  çeliğinden

O çelik ki emekle terle yoğrulan

O toprak ki kanını döktüğün

Ekmeğini yediğin,  dövüştüğün

Vurulup düştüğün gün

Anlarsın umutta tükenir bir gün...

III.

İsyan dolu türküler okurcasına 

Geçiyorum caddelerinden şehrin

Altımda son model bir yalnızlık 

Sen ki yeni çağın cesur ve aşık genci

Ütopya’ nı  çoktan kuşatmışlar senin

IV.

3 milimetre bir cam ardından bakıyorum dünyaya

Hiçbir eskisi gibi görünmüyor artık bana

Kaldırımlarda karamsarlık

Küpeli kulakları ve jöleli saçlarıyla

Aşkları ağlatılar züppe burjuva çocukları caddelerde

Dikilir durursun fakültenin önünde

Şu sözler takılır kalır aklına

“aç olduğun kadar sosyalistsin

ve zengin olduğun kadar kapitalist”

Dönek bir kurşundur inanç

Kendi silahından çıkan kurşunla vurulursun

Kafanda giderek belirginleşen bir yanıt

Yine o kendi bacağından asılan koyun hikayesi

Ve hürriyet 

Hani günümüzde sadece paran olduğu kadar sahip olduğun

Ve adalet 

Güçlü olduğun kadar sana işleyen

Kurtuluş: 

Eskiden bir halk derdik

İnsanlık derdik

Şimdi patronların şişman ve terli avuçları arasında yitirdiğimiz

Gözümün önünde miyop bir dünya

Bulanık her taraf

Ben mi böyle görüyorum 

Yoksa

Her şey bozuldu mu bu kadar

Değiştik diyoruz 

Değişen sadece biziz oysa

Zaman yine aynı zaman

Kurt, kuş yine o aynı kurt kuş

Düşman yine aynı düşman

Kanlı kanatlarıyla yine dolaşmakta

Yurdumun semalarında

V.

Aciz olduğun kadar müttefik olursun bugün kanlı bir katile

Kredi notu kadar hürdür yurdun

Ve çaresizliğin parandaki sıfırlar kadardır bugün

Can satarsın bugün, 

Namus satarsın, 

Bir şirket bütçesinde küçük bir gider kalemidir günlerin

Günlerin bir niyet mektubu

Amerikan doları

Günlerin dişlerini sıkarak geçen

Günlerin isyandan uzak ve aşksız

VI.

Sana sesleniyorum 

İki ihtilali arasından yurdumun

Mart’tan sesleniyorum

Eylül’den sesleniyorum işitiyor musun? 

Dilimde otuz yıllık şarkılarla

Yüreğimde bir heyecanla haykırıyorum kavgamı

VII.

Uzadıkça uzuyor bu bitmez tükenmez aldanmışlık

Sessizlik; 

Kanserli hücrelerin vücudu sarışı gibi

Yürüdükçe yürüyor vücudumda

Gülüşüm ne olur sende terk etme beni 

VIII.

Şimdi bu hadım edilmiş beyinlerimizle

Kim savunur artık emeğini ellerinin

Sopalı, kanlı elleriyle

Dipolitize etmişler gençliğimizi

Bizi duygusuzlaştırmışlar

İnandırmışlar susmanın erdem olduğuna

IX.

Etrafında binlerce meraklı göz

Her biri sanki beyninin içine bakmakta

Hayat denen bu hayvanat bahçesinin korkulukları ardında

Daha ne kadar sürecek bu seyir

Daha ne kadar sürecek bu yalnızlık

Bir anlayan çıksa, çıkartıp yüreğimi yerinden 

Bölerdim ikiye hiç düşünmeden

X.

Otomobillerin camları ardında çok daha farklı bir dünya

Gölgeden çok daha farklı güneş ışığı

Aşk farklı yalnızlıktan 

Açlık farklı tokluktan

Farklı değil fakat kazanmak yada kaybetmek bu kavgada

Bu sonlu dünyada kavgayı kazanmak değildi önemli olan

Önemli olan hak bildiğim yolda savaştım diyebilmekti elbette...

XI.

Elli bir ekran televizyonlarda

Elleri kirli, suratları maskeli adamlar masa başlarında oturur

Konu malum: 

Birimizin birin üçünü aldığı

Ve birimizin üçün birini aldığı düzenin geleceği

Ve doların tüm yeşillerden baskın yeşili

Değişir ilanları gazetelerin: 

(Tepkisiz bir toplumdan ikinci el satılık vatan) 

Büyür kalbimizde delik 

Büyüdükçe bir İncirlik olur

Amerikan toprağı olur yurdumda 

Uçak benzini dolar akciğerlerimize

Nefesimiz kesilir

Gözümüz takılıp kalır 

Tepemizde uçuşan şu yırtıcı kuş sürüsüne

XII.

Kahvelerde masaların yeşil çuhalarında 

Dirseklerini parçalayan 

Sigara dumanlarının sisi altında kaybolmuş bir gençlik

Yarınsız aşklar

Sahte yüzler 

Sahte gülümseler

Sahteleşmiş bir dünya

Yalan her şey

Konuşulan ne varsa

Denize atılan taş yalan

Bakışların koskoca bir yalan 

Hep diyordun ya kendi kendine

“Hayatta hiçbir şey ve hiç kimse için

böylesine köpekleşmeye değmez”

Çünkü böyle yaşadıkça 

Unutursun insan olduğunu bir gün.

Ömür dediğimiz hikaye

Onuru elden bırakmayacak kadar kısa

Ve sen bir köpek olamayacak kadar insansın...

Sevdan vasıfsız bir emek misali piç edilmiştir

İnadına sevmişsindir dünyayı 

Seveni ve sevmeyeniyle 

Hayat sevecek kadar güzel 

Sevdan hayat kadar...

Vazgeçmek sevdadan 

Şüphesiz en büyüğüdür ihanetin

Bir müebbet mahkumu ne kadar vazgeçebilirse

Özgürlük sevdasından

Sende o kadar vazgeçebilirsin sevmekten

Bugün sevdan bir paçavra gibi atılsa da bir kuytuya 

Alın teri; üzerine dolma kalemle yazılmış bir şirket çeki

Üzerine kara çalarlar emeğinin

Herkes  yabancı olur

Herkesin bakışları boş

Sana düşen bir kapı önü yalnızlığıdır sadece

Sana söz veriyorum 

Şakaklardan akan kan

Söz veriyorum alın terim

İçimizde kalan insanlığın son kırıntısıyla

Yüreğimizin hiç el değmemiş ak yanıyla 

Söz veriyorum 

Uykusuz gece yarılarım

Yürüyerek eskittiğim cadde

Okulu ve ışığı dağlar ardında bırakılmış köylü çocuğu

Sana söz veriyorum

Söz veriyorum

Emeği, 

Mayasında vefa ve isyan ile yoğrulmuş insanoğlunun 

Ellerinde yücelteceğiz

Ey yarın sana söz veriyorum...

(Ben bir gençlik demiştim, bir vatan oldu şiirim. Okul yolunda beş yüz metreyi yürürken aklımdan geçenleri yazmak istemiştim sadece. Yol uzadı sınır boylarına vardı nerdeyse. Bu hikaye kanatılmış gençliğimizin kısa bir özetidir. M.C)    

25 Aralık 2002

00: 08', 'I. Uçurum diplerinde bekle beni Kanının Kızılırmağ’ı kızıllaştırdığı yerde Geleceğim akşam çökmeden  Gözyaşının yağmura karıştığı yerde bekl...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":172,"source_url":"https://www.antoloji.com/ozetlenmis-bir-genclik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerine Bakmak', 'gozlerine-bakmak-ebru-gecer-9pwsx', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerinin bir anlamı vardı yüreğimde

Baktığımda gözlerini değil yüreğini görürdüm.

Senin gözlerine bakmak sevdiğim eski bir şarkıyı yeniden içimde hissetmek gibiydi.

Yalnızken pencereden bakınca sevgiyi aramaktı

Bir omuz aradığında ya da bir sevda şarkısı mırıldandığında gözlerinde dalıp uyumaktı sessizce...

Soğuk odada uyandığında bir sıcaklık farketmekti aniden...

Sevdiğini haykırmak isterken susmaktı nedensizce...

Sarılmayı arzularken elinden kayıp gitmesine izin   vermekti zamansızca...

Ve senin gözlerine bakmak; haykırmaktı seni seviyorum diye...', 'Gözlerinin bir anlamı vardı yüreğimde Baktığımda gözlerini değil yüreğini görürdüm. Senin gözlerine bakmak sevdiğim eski bir şarkıyı yeniden...', ARRAY['Türk Edebiyatı','Şiir','Ebru Geçer']::text[], 8.5, '{"poet":"Ebru Geçer","poet_slug":"ebru-gecer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gozlerine-bakmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Aşk', 'eski-ask-yasin-ates-ly7x7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben eski zaman aşıklarındanım.

Geceleri uyku girmez gözlerime.

Bir başıma yıldızları gözlerim ben...

Yıldızları gözlerinden, güneşi yüreğinden, 

Gülleri kokusundan, kuşları sesinden dolayı

severim sevgilinin.

Ben eski zaman aşıklarındanım.

Gözlerimi gözlerine, tebessümümü yüreğine, 

Yüreğimi avuçlarına bırakır, 

Busemi yanağına kondururum sevgilinin.

Ben eski zaman aşıklarındanım.

Gül yaprağı kadar hassas bir yüreğim, 

Ellerine dokundukça titreyen ellerim, 

Baktıkça gözlerine, parlayan gözlerim var sevgilinin.

Ben eski zaman aşıklarındanım.

Kaşlarını, gözlerini.pamuk ellerini, 

En çok da, yüreğini severim sevgilinin.

                            (05.08.2002)', 'Ben eski zaman aşıklarındanım. Geceleri uyku girmez gözlerime. Bir başıma yıldızları gözlerim ben... Yıldızları gözlerinden, güneşi yüreğind...', ARRAY['Türk Edebiyatı','Şiir','Yasin Ateş']::text[], 8.5, '{"poet":"Yasin Ateş","poet_slug":"yasin-ates","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/eski-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Kıza', 'deli-kiza-ozgur-hasan-21hos', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'beni güneş herzaman yakar..

ama herzaman soğuktur yüreğim...

sen bir delisin belkide kendi tabirinle

denizin kenarında duran kum tanesi kıvamında

her an o çekici maviliğe aldanıp dalgayla gidecek kadar

en saf haliyle...

dahada delisin belkide

herkesi kendin görüp

kendinle kumar oynuyacak kadar hemde...

ama o kadar sıcak geliyorsun ki inan

sanki kalbimin en deli yerinden kopmuş deli bir parçam kadar

hem delisin hemde bi o kadarda yakınsın bana...

belkide tahminimden öte bir delisin deli kız

yani bensin bir bakıma...

bizans bir bakıma istanbul, istanbul bir bakıma bizans

ben hep görürüm seni, deli parçamı...

ama sen beni hiç göremezsin 

kimbilir aslada göremiyceksin belki...

beni güneş her zaman yakar

ama herzaman soğuktur yüreğim...

aynanın arkasındaki gerçek ben

kalbimin en deli yeri...

nedendir bilmiyorum ama

seviyorum seni......', 'beni güneş herzaman yakar.. ama herzaman soğuktur yüreğim... sen bir delisin belkide kendi tabirinle denizin kenarında duran kum tanesi kıva...', ARRAY['Türk Edebiyatı','Şiir','Özgür Hasan']::text[], 8.5, '{"poet":"Özgür Hasan","poet_slug":"ozgur-hasan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/deli-kiza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ülkem İçin', 'ulkem-i-cin-ozgur-hasan-r6hvk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kitaplarda yazdığı gibi değilmiş ülkem

değişmiş...

tapılası doğrularımız bitmiş

ya da kim vurduya gitmiş..

kalmamış ülkesi içim çalışan

kalmamış aydın hayaller kuran

o yüce değerler yavaş yavaş yok olmuş

çıkar kavgası içine girmiş insanlar

menfaatler başkaldırmış mertlik bozulmuş..

hiçde kitaplarda anlattıkları gibi değilmiş

para olmuş en büyük sevgili

farketmez kim bulmuş yada ilk kim görmüş

hani ölmüsüzdü ya..yalan

aşk çoktan ölmüş..

ayrılmış ülkenin yolları Atayla

o yüce adamın bahsettiği herşey başa gelmiş

unutulmuş Atanın emirleri

düşülmüş hıyanetler, dalaletler içine 

sistem çökmüş düzen bozulmuş

acaba ''dur'' diyen hiç mi yokmuş? ! ? .....

ey beni dinleyen arkadaş sana sesleniyorum..

eğer sende varsan ve sende ''dur'' diyebiliyorsan

haydi durma sende katıl bize..

seninle de birlik olalım 

eski düzeni yıkıp yenisini kuralım

ülkemizi aydın düzeye çıkaralım

işte o zaman kitaplarda yazılanlar yerini bulur

ve Ata mezarında rahat uyur...', 'kitaplarda yazdığı gibi değilmiş ülkem değişmiş... tapılası doğrularımız bitmiş ya da kim vurduya gitmiş.. kalmamış ülkesi içim çalışan kalm...', ARRAY['Türk Edebiyatı','Şiir','Özgür Hasan']::text[], 8.5, '{"poet":"Özgür Hasan","poet_slug":"ozgur-hasan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ulkem-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmalı Olmalı Nasıl Olmalı', 'olmali-olmali-nasil-olmali-ozgur-hasan-vb53d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir kayanın düşüşü

bir çiçğim görünüşü gib olmalı sevgili

yani narin bir peri gibi durmalı

fakat dağıtırcasına hırsla vurmalı

her aldatıldığında...

vücut hatları kadınsı

yüzü sevimli saf kalbi çocuksu

bakışları çapkın olmalı

kutsal bir melek gibi görünmeli

ama iç çamaşırı giymemeli...

dışardeyken hanımhanımcık durmalı

yataktayken azgın bir fahişe olmalı 

onunlayken kendimi rüyada sanmalıyım

onun birtek ve sadece benim için olduğuna inanmalıym

en azından beni kandıracak kadar zeki olmalı

beyninde nice şeytanlıklar dönmeli 

iyi palavralar atıp beni aşka mahkum etmeli', 'bir kayanın düşüşü bir çiçğim görünüşü gib olmalı sevgili yani narin bir peri gibi durmalı fakat dağıtırcasına hırsla vurmalı her aldatıldığ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Hasan']::text[], 8.5, '{"poet":"Özgür Hasan","poet_slug":"ozgur-hasan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/olmali-olmali-nasil-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sen Yapan', 'seni-sen-yapan-ozgur-hasan-1y1h7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bazı zamanlar olur dönmek istersin maziye

yakalamak kaçan fırsatları

yapmamak yapılan hataları

veya değiştirmek bazı kararları

doğru olmaz bunlar...

kararlarındır sana ait olan

kaçan fırsatlardır gözyaşları

ve yapılan hatalardadır yaşam

işte bunlardır seni sen yapan', 'bazı zamanlar olur dönmek istersin maziye yakalamak kaçan fırsatları yapmamak yapılan hataları veya değiştirmek bazı kararları doğru olmaz b...', ARRAY['Türk Edebiyatı','Şiir','Özgür Hasan']::text[], 8.5, '{"poet":"Özgür Hasan","poet_slug":"ozgur-hasan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-sen-yapan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlıyorum', 'hatirliyorum-ozgur-hasan-71o8d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hatırlıyorum...

sen vardın

gözlerime bakışın

alımlı yürüyüşün

meleksi sesin

narin ellerin vardı

neşeli gülüşün

vede ateşli öpüşün vardı

sen vardın..

çiçeklerle konuşurdun

bunu da hatırlıyorum

şarkılar söylerdin onlara 

içli, dokunaklı

ama çoğu zaman neşeli..

hatta hatırlıyorum daha çok maviyi severdin

acaba bu yüzden mi gökler mavidir? 

ve sırf bu yüzden mi melekler göklerdedir? 

ve sen vardın..

yıldızları izlerdik akşamları 

ezgiler mırıldanırdık bilmediğimiz şarkılardan..

hiç duymadığın hikayeler anlatırdım sana

hiç görmediğim yerlerden kalan

sonra soğuk bir akşam rüzgarı eserdi 

üşümemek için daha bir sokulurdun bana

hatırladımda ben o rüzgarı da çok severdim..

sen vardın..daha çok

acaba sen hangi çiçek kokardın

yada hangi çiçek sen gibi kokardı

bak bunu hatırlamıyorum..

daha çok temmuz akşamlarını hatırlıyorum senle olan

vede o tutkulu geceleri

gelip saçlarına konan yakıcı yakamozları bide..

ama artık sen yoksun..

uzun zaman alışamadı kalbim yokluğuna

günlerce beraber olduğumuz yerleri dolaştım

senle yaşadığım bütün o güzel duyguları aradım

anlamsız acılar duydum-nerden geldiğini bilmediğim-

anlamsız siluetler gördüm; sanki çoğu sana benziyordu

küfretti tüm organlarım benliğime...

sanırım giderken benide götürdün yanlışlıkla, bilmeden

şimdi boşuna uğraşıyorum aslında

boşuna kandırıyorum kendimi

gerçekte; ne ben eski ben olabildim

nede seni unutabildim...', 'hatırlıyorum... sen vardın gözlerime bakışın alımlı yürüyüşün meleksi sesin narin ellerin vardı neşeli gülüşün vede ateşli öpüşün vardı sen ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Hasan']::text[], 8.5, '{"poet":"Özgür Hasan","poet_slug":"ozgur-hasan","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/hatirliyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözbebeklerin Vardı', 'gozbebeklerin-vardi-ozgur-hasan-eso0o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gözbebeklerin vardı gitmeden önce...

ne yapacağımı bilemezdim görünce

yakılmış bir kağıt gibi erirdi yüreğim

klasiktir hep böyle olur sevince..

her bakışımda farklı bir çiçek olurdun

bazen gül bazen papatya..bazende manolya

seni her kestiğimde yeni bir çiçek

sanırım bu yüzden hep deli doluydun...

anlamsız bir coşku yaşarda bahar..bilmezdi

seninle beraber kışta çiçekler açar

seninle güzde ağaçlar yeşerir 

ve kuşlar senle yağmurda uçar...

gözbebeklerin vardı ya hani..

kedi yavruları gibi oynardı

baştan sona tüm organlarım...

hatırladıkça sarhoş beynim seni

gözbebeklerin vardı..ve ben korkardım

korkardım bu ateşin ansızın sönmesinden

ama ateş yavaş yavaş söndü..gün ve gün

ne eser kaldı senden nede gözbebeklerinden..

gözbebeklerin söndü ve...gittin

nasıl gelebilmiştin ve neden gittin

hiçbir zaman anlayamadı bunu yüreğim..

bilmiyordu, sende herkes gibiydin...', 'gözbebeklerin vardı gitmeden önce... ne yapacağımı bilemezdim görünce yakılmış bir kağıt gibi erirdi yüreğim klasiktir hep böyle olur sevinc...', ARRAY['Türk Edebiyatı','Şiir','Özgür Hasan']::text[], 8.5, '{"poet":"Özgür Hasan","poet_slug":"ozgur-hasan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gozbebeklerin-vardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerden Bileyim', 'nerden-bileyim-ebru-gecer-wh83m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevmek özlemle başlar dediler inanmadım

Nerden bileyim ömür boyu özleyeceğimi...

Sana sevgimi söylemek isterdim

Nerden bileyim hiç dönmeyeceğini...

Yalnızlık çabuk atlatılır sanırdım

Nerden bileyim sensiz bu kadar zor olduğunu...

Hemen sabah olsun isterdim

Nerden bileyim uyanınca seni göremeyeceğimi...

Sevgilim olmanı isterdim

Nerden bileyim senin gönlünün benden geçtiğini...', 'Sevmek özlemle başlar dediler inanmadım Nerden bileyim ömür boyu özleyeceğimi... Sana sevgimi söylemek isterdim Nerden bileyim hiç dönmeyece...', ARRAY['Türk Edebiyatı','Şiir','Ebru Geçer']::text[], 8.5, '{"poet":"Ebru Geçer","poet_slug":"ebru-gecer","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/nerden-bileyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-ebru-gecer-tejed', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalnızlığı tanımla dediler

Anlatmaya başladım yokluğunu...

Gecelerin ne kadar uzun

Sabahların nasıl karanlık olduğunu...

Kapıdan girecek bir gölgenin eksikliğini

Pencereden vuracak tek bir ışığın yokluğunu 

Issız hayatta daha ne olsun derken

Karşımda seni görmek isterdim

Yalnızlığım sona ersin 

Yeniden hayat başlasın diye...', 'Yalnızlığı tanımla dediler Anlatmaya başladım yokluğunu... Gecelerin ne kadar uzun Sabahların nasıl karanlık olduğunu... Kapıdan girecek bir...', ARRAY['Türk Edebiyatı','Şiir','Ebru Geçer']::text[], 8.5, '{"poet":"Ebru Geçer","poet_slug":"ebru-gecer","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yalnizligim-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Olur', 'gun-olur-elyase-i-skender-ca7au', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gun olur gece dolanir

gozlerinde sevdanin

gun olur bir cicek solar sararir

bakislarinda olumu tadar bir insan

nefreti gorur gozlerinde	

gun olur kelime katarina siir der bir deli

yuz akilli cozemez bu esrarli heceyi

bir dilek tutmak icin bahane arar insan...

bulamaz!', 'gun olur gece dolanir gozlerinde sevdanin gun olur bir cicek solar sararir bakislarinda olumu tadar bir insan nefreti gorur gozlerinde	 gun ...', ARRAY['Türk Edebiyatı','Şiir','Elyase İskender']::text[], 8.5, '{"poet":"Elyase İskender","poet_slug":"elyase-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gun-olur-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '4luk', '4luk-elyase-i-skender-eapty', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'saclarinin renginde olmasa 

inan guesi kirletmem

bana gozlerini animsatmasa

bil ki yesili hic sevmem', 'saclarinin renginde olmasa  inan guesi kirletmem bana gozlerini animsatmasa bil ki yesili hic sevmem...', ARRAY['Türk Edebiyatı','Şiir','Elyase İskender']::text[], 8.5, '{"poet":"Elyase İskender","poet_slug":"elyase-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/4luk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kumrular Uğramaz Oldular I', 'kumrular-ugramaz-oldular-i-elyase-i-skender-gklsx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kumrular ugramaz oldular

odamin penceresine

o cok sevdigim guller

gulmez oldu yuzume	

bilirim bir gun dogacak batidan

ve hersey bitecek

bilirim bir baska goz deyecek gozlerine

tum  renkleri solacak yasamin

bir baska el dokunacak saclarina

ve umit tukenecek yuregimde

ve o caglayan nehir kuruyacak

ve bir baskasi fisildayacak sevgi sozcuklerini kulagina

ve benim nutkum tutulacak

lal olacak sevgim', 'kumrular ugramaz oldular odamin penceresine o cok sevdigim guller gulmez oldu yuzume	 bilirim bir gun dogacak batidan ve hersey bitecek bili...', ARRAY['Türk Edebiyatı','Şiir','Elyase İskender']::text[], 8.5, '{"poet":"Elyase İskender","poet_slug":"elyase-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kumrular-ugramaz-oldular-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'kimse bilir', 'kimse-bilir-elyase-i-skender-tbiae', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'oyle bir dert var ki bende

ne kimse bilir ne de ben

nerde bir isik gorsem

ben sonerim umutlarima

bir kanat cirpis gorsem gercege

ben vurulur duserim hayallerimin ustune

oyle bir dert var ki bende

ne kimse bilir ne de sen

nerde dogarken gunesi izlesem

batarim mazimin ustune

ve nerde bir gul gorsem 

ben solarim bir yasam ustune

oyle bir dert var ki bende

ne kimse bilir ne de o

oyle bir dert var ki bende

ne kimse bilir ne de sorar ne diye

sadece aciyan gozler gorurum bilirler herseyi

birde aynanin diger yaninda ki goruntum bilir

ve tadar zehrini hergun usandigim

ve binlerce kez tovbe ettigim yasam dedikleri derdin...', 'oyle bir dert var ki bende ne kimse bilir ne de ben nerde bir isik gorsem ben sonerim umutlarima bir kanat cirpis gorsem gercege ben vurulur...', ARRAY['Türk Edebiyatı','Şiir','Elyase İskender']::text[], 8.5, '{"poet":"Elyase İskender","poet_slug":"elyase-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kimse-bilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-elyase-i-skender-ceu1y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sensiz buralarda

artik hicbirsey eskisi gibi olmuycak

her pazartesi sabahi bir guvercin konmuycak

odamin  cigden islanmis penceresine

ve biliyorum sensiz 

yuregimde ki o kucuk cocuk olecek

kuruycak goz pinarim

hayallerimin pembe pancurlu evi yanacak

yani sensiz buralarda hicbir sey eskisi gibi olmayacak

geceler daha zalim kesilecek

gunduzlerse issiz

sabahlari dogan gunes/*(belki dogmayacak ama dogarsa if and only if)  */

suzulmuyecek odama izinsiz

yani her dogan gun olume dogacak

ve her gece yasamima perde cekecegim...', 'sensiz buralarda artik hicbirsey eskisi gibi olmuycak her pazartesi sabahi bir guvercin konmuycak odamin  cigden islanmis penceresine ve bil...', ARRAY['Türk Edebiyatı','Şiir','Elyase İskender']::text[], 8.5, '{"poet":"Elyase İskender","poet_slug":"elyase-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sensiz-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Başlangıç Bir Bitişmiş...', 'her-baslangic-bir-bitismis-elyase-i-skender-ca5k3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'umudun bittigi yerde baslarmis yasam

ve her ayrilik olum getirmezmis ardindan

gozler yarina bakamazmis karardiginda

ve sozler gelecege dair olamazmis cumle aralarinda

ve hayat umudun yittigi yerde baslarmis

her baslangic bir bitismis...', 'umudun bittigi yerde baslarmis yasam ve her ayrilik olum getirmezmis ardindan gozler yarina bakamazmis karardiginda ve sozler gelecege dair ...', ARRAY['Türk Edebiyatı','Şiir','Elyase İskender']::text[], 8.5, '{"poet":"Elyase İskender","poet_slug":"elyase-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/her-baslangic-bir-bitismis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnanamıyorum', 'i-nanamiyorum-i-kbal-senturk-c37p8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen 36 yaşında 

aklımda hiç ölüm yok

dalgamı geçiyor bu insanlar? 

acilin odalarını bir bir dolaşıyorum

her kapı bir umut, 

burdadır diyorum

sedyeler boş

sen yoksun

sormak istiyorum seni

sesim kısılmış, 

adın çıkmıyor dudaklarımdan

git gide azalıyor umutlarım

güçüm azalıyor

korkuyorum

acılın kapısında bir polis

en cok ona kızıyorum

dikleniyorum, ama nafile

öyle zavallıyım ki, 

kimse bir şey söylemiyor

kapıda çocuklarının annesi

eşin.......

umutlanıyorum, 

sakın görünüyorlar

sıradan birşey söyler gibi 

abin öldü diyor.....

donup kalıyorum, 

dünyam alt-üst oluyor

ben kıpırdıyamıyorum

arkasından bir cığlık yükseliyor içimde

haykıramıyorum

seni görmek istiyorum

kilitli o soğuk oda,  kapıları yumrukluyorum

biri gelip açıyor kapıları, 

başına gidip yalvarıyorum

ben geldim kalk ne olur diyorum

öldüğüne inanmıyor içim

benim geldiğimi duymadın diye

daha fazla ağlıyor, 

aralıksız yalvarıyorum

yanıt vermiyorsun

ben annemlere ne derim diyorum, 

suç işlemişiz gibi korkuyorum

onlar gelene kadar, bu kötü rüyanın bitmesini istiyorum

sessizliğin devam ediyor

ilk kez aldırmıyorsun bana 

içimdeki cığlık büyüyor

inanamıyorum

ağlıyorum...........', 'sen 36 yaşında  aklımda hiç ölüm yok dalgamı geçiyor bu insanlar?  acilin odalarını bir bir dolaşıyorum her kapı bir umut,  burdadır diyorum...', ARRAY['Türk Edebiyatı','Şiir','İkbal Şentürk']::text[], 8.5, '{"poet":"İkbal Şentürk","poet_slug":"i-kbal-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/inanamiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapında Bir Şair', 'kapinda-bir-sair-okan-savci-0egvj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bildigin sehirde degilim artık

kendime yeni bir gurbet buldum 

bir yanımda ask bir yanımda yalnızlık

yabancı kaldırımlarda sabahlıyorum...

bu sehirde geceler pusludur biraz

bu sehirde ayrılıktan baska birsey yok..

gece oldu mu yagmur baslar hemen 

günesli sabahlar desen bir var bir yok...

çok uzagımda kaldın..hayalim yetmez sana 

ister sabret yokluguma ister küfret

bir kere kaybettim ya seni.. 

istesen de dönenem! bu gurbet baska gurbet...

mektup yollama adressiz biriyim simdi

yerimi yurdumu kimseler bilmez

gece çökünce odana sen balkona çık

kapında bir sair... ya görünür ya görünmez

__', 'bildigin sehirde degilim artık kendime yeni bir gurbet buldum  bir yanımda ask bir yanımda yalnızlık yabancı kaldırımlarda sabahlıyorum... b...', ARRAY['Türk Edebiyatı','Şiir','Okan Savcı']::text[], 8.5, '{"poet":"Okan Savcı","poet_slug":"okan-savci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kapinda-bir-sair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmem', 'bilmem-elyase-i-skender-kutg4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sert sigaralar iciyordum

zehirli ve insani yilan gibi sokan

sinsi laflar dinliyordum

hic tanimadigim kimselerden

her sabah ter icinde uyaniyordum

gordugum kabusun kor talihinde

ve dusuyordum geceden zifiri gunduze

gunesin her dogusunda ben batiyordum..

usuyordum...

sonra penceremden disari bakiyordum

mevsim sonbahar

dokulen yapraklari sayiyordum

yitmis umutlarla beraber

ben de yitiyordum..

bitiyordum...', 'sert sigaralar iciyordum zehirli ve insani yilan gibi sokan sinsi laflar dinliyordum hic tanimadigim kimselerden her sabah ter icinde uyaniy...', ARRAY['Türk Edebiyatı','Şiir','Elyase İskender']::text[], 8.5, '{"poet":"Elyase İskender","poet_slug":"elyase-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bilmem-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çicekler Oluyordu', 'cicekler-oluyordu-elyase-i-skender-t4wln', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'o aynada ki soluk yuzlu

insan aksi benden baskasi degildi

gozlerimin altinda ki cizgiler

ne dun ki uzuntulerden

ne de yarinin korkusundandi

odamda ki cicekler oluyordu

ben yasiyordum, 

saniyordum!', 'o aynada ki soluk yuzlu insan aksi benden baskasi degildi gozlerimin altinda ki cizgiler ne dun ki uzuntulerden ne de yarinin korkusundandi ...', ARRAY['Türk Edebiyatı','Şiir','Elyase İskender']::text[], 8.5, '{"poet":"Elyase İskender","poet_slug":"elyase-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cicekler-oluyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dun', 'dun-elyase-i-skender-s6t5a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir yarali kus gordum

gonlume benziyordu

olum kokuyordu buram buram

gozlerinde parlaklik soluyordu

tuyleri yagmurdan islanmis

o koca yurekli kus hizli hizli soluyordu

sozler yine yalan

gunlerden sali

bir olu guvercin donuk gozlerle bana bakiyor

sozler yine yalan

dun yine o yalanciyi gordum otobus duraginda

saclari darmadagindi sonbahar ruzgarinda

yine yureklerle oynuyordu

yine yalan bi yasam vaad ediyordu

dun bir olu gordum

ayna karsisindaydi

bosbos bakiyordu olmayan aksine

her olu gibi 33 yasindaydi

ama oldugunun farkindaydi her olunun aksine

dun yasami tuttum avuclarimda

titrek ve sariydi

gozlerine baktim donuk ve yasli

aglamanin bu kadar iclisini ilk defa goruyordum

masmavi gozleri gencti ama bakislari yasli...', 'bir yarali kus gordum gonlume benziyordu olum kokuyordu buram buram gozlerinde parlaklik soluyordu tuyleri yagmurdan islanmis o koca yurekli...', ARRAY['Türk Edebiyatı','Şiir','Elyase İskender']::text[], 8.5, '{"poet":"Elyase İskender","poet_slug":"elyase-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dun-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana ait', 'sana-ait-elyase-i-skender-z0202', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sonbahardan kalma sozler dokulur dilimden

gozlerinden kalma bir mavilik

icime isler

umutlarimi yine baharlar susler

saclarin en sari anidir yasamin

gozlerinden dokulen yaslar

en icli sarkisidir

nefesin en sert sigaradan daha fazla tat verir

sesin karadenizim gibi; dalgalarini cekerken

birbirine carptirdigi deniz kabuklarinin 

sakirtisi kadar kararsiz

titrek ama huzurlu

bakislarinsa olum kadar soguk

carptigi yer buz tutar', 'sonbahardan kalma sozler dokulur dilimden gozlerinden kalma bir mavilik icime isler umutlarimi yine baharlar susler saclarin en sari anidir ...', ARRAY['Türk Edebiyatı','Şiir','Elyase İskender']::text[], 8.5, '{"poet":"Elyase İskender","poet_slug":"elyase-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sana-ait-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ask Dediğin', 'ask-dedigin-elyase-i-skender-oiqhf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ask dedigin cocukca olmali

boncuk boncuk bakmali gozune insanin

yani yalan olmamali hicbir yerinde

ask dedigin sessiz yasanmali

kimseyle paylasilmamali

soylenen sevgi sozcukleri

ask dedigin gece yasanmali karanliklarda

kimse gormemeli cunki

baska bir goz deyipte bozmamali buyuyu

ask dedigin yavas yasanmali

israf edilmemeli bir kirintisi bile

bir omur boyunca dilinde tadi kalmali

ask dedigin bitsede.. yureginde adi kalmali...', 'ask dedigin cocukca olmali boncuk boncuk bakmali gozune insanin yani yalan olmamali hicbir yerinde ask dedigin sessiz yasanmali kimseyle pay...', ARRAY['Türk Edebiyatı','Şiir','Elyase İskender']::text[], 8.5, '{"poet":"Elyase İskender","poet_slug":"elyase-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ask-dedigin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kilitli Umutlar', 'kilitli-umutlar-elyase-i-skender-hgtez', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 've pencerimin kenarina bir yalniz kumru konar

her gece kasimpatilar biter bahcemde

son sari gul de solar

sen uzaklardasin duymazsin

bir baykus otup durur simdi gecelerimde..

yagmur beklerken kar duser saclarima

umutlarim yittigi yerde kilitli

sen ellerini bir hice deydirdigin zamandan beri

tum hicler ben oldum	

bakislarim anlamsiz aglamakli

ve her bakisin ardinda

bir yagmur sakli

sonunda beklenen oldu yagmur yagdi ben yagdim

damla damla eriyen bedenim yagdi

ve sacma sozler geride kaldi

geride kaldi ben dedigim hersey

artik sakincali dusunceler var

sakincali senaryolar yaziyorum.

ben mahkumuydum askinin

sen kalemi kirdin!', 've pencerimin kenarina bir yalniz kumru konar her gece kasimpatilar biter bahcemde son sari gul de solar sen uzaklardasin duymazsin bir bayk...', ARRAY['Türk Edebiyatı','Şiir','Elyase İskender']::text[], 8.5, '{"poet":"Elyase İskender","poet_slug":"elyase-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kilitli-umutlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'iKiNDI BAHARI', 'ikindi-bahari-sadik-demirtas-wfhql', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ikindi bahari

Gec gelen yolcu

Busem kivilcimlar

Ölücesine

Urganlar salinmis 

Nezaret benim

Gözümün icinde aglasan, deniz

Ben de toprak gibi

Serin ve sessiz.

Dinleniyorum

Belki de sizce...

     12 Ekim 1992

      Kadiköy-istanbul', 'ikindi bahari Gec gelen yolcu Busem kivilcimlar Ölücesine Urganlar salinmis  Nezaret benim Gözümün icinde aglasan, deniz Ben de toprak gibi ...', ARRAY['Türk Edebiyatı','Şiir','Sadık Demirtaş']::text[], 8.5, '{"poet":"Sadık Demirtaş","poet_slug":"sadik-demirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ikindi-bahari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Buldum', 'seni-buldum-alaettin-isik-h755l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni buldum yerde gökte ararken

Suyu arayan bir yaralı gibi, 

Ay bulutu gökte sararken

Ben karanlıklarda aradım seni.

Ben ben idim senden öte

Arar mıydın beni böyle

Bir sözün bin melodiyi söyler

Bilmezdim aşkı hiç de böyle.

Mutluyum gururluyum seninle

Bir şarkı söylüyorum dinle

Seni buldum ben ben oldum

Yaşarım bu dünyada yalnız seninle.', 'Seni buldum yerde gökte ararken Suyu arayan bir yaralı gibi,  Ay bulutu gökte sararken Ben karanlıklarda aradım seni. Ben ben idim senden öt...', ARRAY['Türk Edebiyatı','Şiir','Alaettin Işık']::text[], 8.5, '{"poet":"Alaettin Işık","poet_slug":"alaettin-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-buldum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsan', 'i-nsan-sair-lolan-pom8k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne aramasını biliyor insan

Ne araması gerekeni

Dinlemeden hayatı ruhundan

Tutup atıyor  kendini

Dönüp geri gelen uçurumlardan', 'Ne aramasını biliyor insan Ne araması gerekeni Dinlemeden hayatı ruhundan Tutup atıyor  kendini Dönüp geri gelen uçurumlardan...', ARRAY['Türk Edebiyatı','Şiir','Şair Lolan']::text[], 8.5, '{"poet":"Şair Lolan","poet_slug":"sair-lolan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/insan-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garcia', 'garcia-muzaffer-gezer-wcxv2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Franco''nun askerleri dizdi kurşuna beni

Bir çingene sardı yaralarımı

Öğütülmüş yıldız parçalarını

Yastık yaptı başıma

O iri göğüslerini sunarken dudaklarıma

Kalçalarını sürterken bacaklarıma

Haberi geldi Garcia''nın

Sabah dizilmiş kurşuna

Ankara Mamak''ta

Yüreği parçalanmış Fadime kadın''ın', 'Franco''nun askerleri dizdi kurşuna beni Bir çingene sardı yaralarımı Öğütülmüş yıldız parçalarını Yastık yaptı başıma O iri göğüslerini suna...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/garcia-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'hoşçakal', 'hoscakal-muzaffer-gezer-5y9np', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Küçük bir gül dalıydım

Rüzgarlar savurdu ordan oraya

Bazen bir mavzer mermisi gibi

Deli divane

Bazen de bir aşığın tutkusu gibi ölümcül

Kimi zaman ağladım zamansız

Kimi zaman

Hummaya yakalanmış hasta gibi devasız

Ben ki siyah saçlarında dert

Kömür rengi gözlerinde

Bir grizu patlaması gibi acımasız

Ne olduğumu

Nerden gelip 

Nereye gittiğimi bilmeyen

Garip

Kimsesiz

Ve çaresiz bir yosun yeşiliydim

Oysa şimdi tanrılar hükmetti artık yoksun sen

Şimdi sen

Perdeleri inmiş bir oyunun

Son repliği kadar duygulu

Bir tirat kadar uzun

Oysa bir bakış kadar kısa

Gelip geçtin hayatımdan

Hoşçakal gülüm

Ben sevdan içinde

Sevdam sende

Sen İstanbul''da kal

Hoşçakal nazlı gülüm

Hoşçakal.....', 'Küçük bir gül dalıydım Rüzgarlar savurdu ordan oraya Bazen bir mavzer mermisi gibi Deli divane Bazen de bir aşığın tutkusu gibi ölümcül Kimi...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/hoscakal-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-muzaffer-gezer-5zi26', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hasret koydum adını hasretim sana

Üşüyorum tut elimi uzağım bahara

Ekmek gibi tütün gibi tütüyorsun gözlerimde

Acıktım sana

Yaprak sarı kar dizimde

Sen gelsen bahar gelse

Bahar gelse kavgama

Sevdalarda tutsağım mahkumum sana

Şiirlerde ölmüşüm şarkım var şafağa

Bak yüreğim haykırıyor sevdiğini şarkılarda

Vurgunum sana

Hücrem küçük, gün uzakta

Sen doğsan güneş doğsa

Güneş doğsa zindana

Sen gelsen bahar gelse

Bahar gelse kavgama', 'Hasret koydum adını hasretim sana Üşüyorum tut elimi uzağım bahara Ekmek gibi tütün gibi tütüyorsun gözlerimde Acıktım sana Yaprak sarı kar ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hasret-92-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yusuf', 'yusuf-muzaffer-gezer-9asy1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen günsün hücremde

açken susuzken umut

ve sevda ve emek

haydi yusuf direniş gerek

gençtin yollara düştün

sevdalı gönlüme düştün

ihanete düşmeden yusuf

kavgada düştün

bayrak oldun ellerimizde

göğsümüzün sol köşesinde

soğuk su serptik ateşe

ve YUSUF ERİŞTİ güneşe', 'Sen günsün hücremde açken susuzken umut ve sevda ve emek haydi yusuf direniş gerek gençtin yollara düştün sevdalı gönlüme düştün ihanete düş...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yusuf-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçinden oku YASAKTIR', 'i-cinden-oku-yasaktir-muzaffer-gezer-w6egz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yasak üstüne kurulmuş dünya, yıkmak yasak

Doğmak sevmek büyümek 

Ve özgürce ölmek yasak

Şarkılarla yürümek bir sabah vakti

Alabildiğine özgür dolaşmak

Sevmak

Sevilemk

Özlemek yasak

Yasaktı çiçeklerin açması

Çocukların koşması

Ve güneşin doğması

Yasaktı elele tutuşmak

Umutla yaşamak

Umutsuz yaşamak

Şiir yazmak yasak, Pir Sultan''ım nerede

Sevmeyeceksin insanları

Kemiklerin sızlar mı bilmem

Dağlar delen Ferhat

''Kitap yazın'' dedi beyin biri

''Lakin dokunmasın bize, kabus gördürmesin''

''Koşun'' dedi beyin biri

''Lakin güneşe değil, ölüme koşun''

''Yaşayın'' dedi beyin biri

''Lakin yaşatmayı düşünmeyin''

''Düşünün'' dedi beyin biri

''Ama bizi nasıl yıkacağınızı değil''

Tüm bu özgürlüklerle biz

Koyundan farkı olmayan biz

Hani '' deryayı bilmeyen balıklar gibi'' biz

Biz olduğumuzun farkınfda olmayan biz

Ve kafamızda Demoklesin kılıcı gibi

Koca bir yasak

Ve yasaktı ve yasaktı ve yasaktı

Diyorlar ki adam öldür nezaketlen

Yasak değil

Zina yap nezaketlen yasak değil

Yasakmış sevmek sadakat, oh ne güzel

Kırmışlar güvercinin kanadını uçmasın diye

Uçacak

Öldürmüşler bebeği doğmasın diye

Doğacak

Alnının ortasında kızıl bir karanfil açacak

Ve...

Yasaklayacak tüm yasakları

Yasaklayacak yıkacak bir birİ', 'Yasak üstüne kurulmuş dünya, yıkmak yasak Doğmak sevmek büyümek  Ve özgürce ölmek yasak Şarkılarla yürümek bir sabah vakti Alabildiğine özgü...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/icinden-oku-yasaktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babama', 'babama-muzaffer-gezer-s1ilb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzat ellerini baba öpmek istiyorum

Geçmişten aldığın mirası

Yarınlara borcunu paylaşmak istiyorum

Gel otur yanıma ısın

Anlat bana

Kara kışta sabahın köründe

İncecik bir gömlekle işe gitmeyi

Pencere camında saç taramayı

Bir baş soğanla bir tutam tuzun öyküsünü anlat

Seni senle yaşamak istiyorum

Bir ip parçasını sllayarak elinde

Dünün İstanbul pazarlarını anlat

Bıyık burup göz kırparak

Tavlamaya kalktığın Gültepe''nin gülünü

Anamı anlat bana

Sevdanı anlat

Saçın ağarmış alnın kırışmış gönlün benle genç

Alıp seni yanıma dünyaya göstermek istiyorum

Yiğidin oğlu yiğit olur dercesine meydan okumak

Ve seninle baba

Yorgun bir gecenin ardından

Eylem dolu sabahlara koşmak

Kuşların kanadında uçmak istiyorum

Senden aldığımı oğluma bırakıp

Dostlarla helallaşıp

Karanlığına esaretin

Ve kurşunlarına faşizmin

Meydan okumak istiyorum

Uzat ellerini baba

O mübarek ellerini öpmek istiyorum', 'Uzat ellerini baba öpmek istiyorum Geçmişten aldığın mirası Yarınlara borcunu paylaşmak istiyorum Gel otur yanıma ısın Anlat bana Kara kışta...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/babama-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirim Seni', 'bilirim-seni-muzaffer-gezer-zq322', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilirim seni

Ağlarsın Filistin''li çocukla

Zılgıtlara karışır sesin

Kürt kadınıyla ateş yakarsın

Gözlerin ışıtır karalığını

Kara Afrika''nın

Ellerin büyür

Doyar Somali''li beb

Bir akşam Mozart dinlersin

Viyana kucaklar seni

Bir milis ateşinle yakar molotofu

Selam vermeden geçmezsin 

Yirmisekizinci caddedeki zenci dilenciye

Bilirim seni

Abidin senin resmini çizememişti

Aragon''la şarap

Nazım''la rakı içip oynamayı severdin

Bilirim seni

Büyürsün her geçen gün

Ben sevdikçe seni

Sen dünyayı

Bilirim

Ve severim seni

İnsanlar 

Direndikçe ve Sevdikçe büyürmüş

Hep büyü', 'Bilirim seni Ağlarsın Filistin''li çocukla Zılgıtlara karışır sesin Kürt kadınıyla ateş yakarsın Gözlerin ışıtır karalığını Kara Afrika''nın E...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bilirim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir eylem dönüşü', 'bir-eylem-donusu-muzaffer-gezer-2ap2b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün de ölmedim gülüm

Bugün de ölmedim

Öylesine güçlüydü ki hasretin

Diş geçiremedi ölüm

Sımsıcak bir gülüş özledim

Etrafımı çeviren namlulardan

Yüzüme savrulan kurşunlardan

Kirpiklerin saplandı yüreğime

Özledim

Gözlerinden samanyoluna uzandım

Dudakların billur bir kadeh

Kan bulaştı dudaklarıma

Göğüslerinin altında ezilirken vücudum

Yırttı sırtımı tırnakların

Seviştim

Yollar sana çevrili ben yollara

Sevdikçe büyüdüm

Direndikçe büyüdüm

Bugün de ölmedim gülüm

Bugün de  ölmedim

Öylesine güçlüydü ki hasretin

Diş geçiremezdi ölüm

Döndüm', 'Bugün de ölmedim gülüm Bugün de ölmedim Öylesine güçlüydü ki hasretin Diş geçiremedi ölüm Sımsıcak bir gülüş özledim Etrafımı çeviren namlul...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bir-eylem-donusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmeyenlere', 'bilmeyenlere-muzaffer-gezer-oqouz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Büyüdüğünü hissetmiyor musun

Yürüyen çocukları görmüyor musun

Haklı olan kazanır bilmiyor musun

Direne direne büyüyoruz

Sevdalar yasaktır bize

Tutsaklık zulüm içinde

Hasretliği çeke çeke

Biz sevdikçe büyüyoruz', 'Büyüdüğünü hissetmiyor musun Yürüyen çocukları görmüyor musun Haklı olan kazanır bilmiyor musun Direne direne büyüyoruz Sevdalar yasaktır bi...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bilmeyenlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşkencede', 'i-skencede-muzaffer-gezer-gepgm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gökkuşağından  bir sevgi aldım gönlüme

Yıldızlardan bir fahişeyi koynuma

Hiç söylenmemiş şarkıları söyledim günbatımına

Bulutları yastık yapıp başıma göklerde uyudum

Sonra birileri gelip kaldırdılar

Rüyamın en tatlı yerinde

Soğukluğunu duydum ensemde bir demir parçasının

Sıcaklığını düşündüm anne

Sırtıma vurulan her darbede

Darbe üstüne darbe yiyip

Yıkılmayan babam girdi düşüme

Gücüme güç katıldı

Sonra bütün olanlara rağmen

Umudumda sakladığım bir baş soğanı

Gözyaşıma bana bana

Kurumuş ekmeklerin eşliğinde yedim hücremde

Ne zamandır göremediğim oğlumu hissetim yanımda

Bir militen gibi kararlı ama terkedilmiş

''Baba kalk konuşalım'' der gibiydi 

Göstererek iğrençliği

''Baba kalk oynayalım'' der gibiydi

Göstererek denizi

Sahile vurmuş yengeçleri

İstiridye kabuklarını yıldızları

Bilmem ne radyosunda çalarken Vivaldi''nin bir eseri

Tan atarken kucaklaştık dalgalarla

Tüfekleri çatmadık

Ateş yanmıyordu

Bai yamaç da değildi kamp kurduğumuz

Kimbilir 

Belki tüfeğimiz de hiç olmadı

Öyleyse neydik biz, kimdik

Kim olmaya çalışıyorduk

Sanki ertesi gün hemen ertesi gün

Ulaşacaktık hedefe

Omuz omuza türkülerini söylerken kardeşliğin

Sonra tekrar geldi adamlar uyandırdılar beni

Uykuda bile düşünmene izin yoktu geçmişi

Elinde jop olan

''Kalk ulan orospu çocuğu'' derken

Anam geldi aklıma eli nasırlı kınalı yiğit anam

Okula giderken en son gördüğüm gün

''Allah zihin açıklığı versin oğul''

Sesi çınlar gibi oldu duvarlarında

Ürktü zorbalar

Çırılçıplak soydular şimdi beni

İki kablo var adamın elinde

Şimdi onunla beraberim bir çay bahçesinde

Elelyim sokaklar bizim

Slogan atarcasına haykırıyoruz sevgimizi

Sonra yatağa uzanıyoruz

Birleşiyor dudaklar

Bizden öte

Bizden istekli bedenimiz

Delicesine bir şehvet bu aşktan öte

Vücudum inliyor bir büyük hazla

Haz acıya bıraktı yerini

Jop tepeme indikçe

''Konuş ulan itoğluit'' diyor mavi gözlü adam

Öğretmenime benziyor

Hani bir coğrafyacı vardı ya

Ne çok severdi beni

''Konuşsana oğlum''

Vapur sesleri kapladı ortalığı

İstanbul cıvıl cıvıl

İnsanlar koşuşuyor üniversiteler boşalıyor

İşte ben de oradayım bak, siyah pantalonlu

Yanımdaki arkadaş Hukuk''tan

''Konuş ulan kimlerle ilişkidesin''

Unutmalıyım arkadaşlarımı

Hatta kendimi

Ben hiç oldum mu

Yıllardır yaşayan ben miydim

Bir daha çıkabilecek miyim dışarı

Sıcak bir çayla simit yiyebilecek miyim

Oğlumla top oynayabilecek miyim

Şiir yazıp sevebilecek miyim

Bir bayram namazına daha gidebilecek miyim babamla

Dönüşte

Mahallenin çocukları öpecekler mi ellerimi

Onlara bir gün evvel hazırladığım bahşişleri

Verebilecek miyim

Bir kurban bayramı daha 

Yaşayabilecek miyim İstanbul''da

Adamın elinde ince bir şiş yüzüme sürüyor

Elindeki demirin ateşimi yüzümü yakan çaresizlik mi

Bir kova su daha döküldü başıma titriyorum

Bir piknik dönüşü nasıl yakalanmıştık yağmura

Babam annem karım oğlum kardeşlerim

Sırılsıklam olmuştuk

Ne güzel gündü ama

Sonra o en içten halimizle

O en güzel halimizle

Kaçıp herkesten gizli karımla

Sevişmemiş miydik yağmurun altında

Erkekliğini bastır oğlum diren

''Sokuyum mu lan bunu pezevenk''

''Bırak keselim erkekliğini hergelenin'' dedi

Elinde jop olana

Kırdı meşrubat şişesini camını aldı eline

Evin karşısındaki boş arsada

Şişeler sıralı boş bir duvarda

Taş atarak

Şişe kırmaca oynamaz mıydık

Elma şekerine

Pamuk şekerine

Şekerlere

Birden Nazım geldi aklıma

''Çocuklar öldürülmesin şeker de yiyebilsinler''

Şeker yiyebilecek miyim acaba

Oğlum yiyebilecek mi

Bırak özgürce bir kuru ekmek daha yiyebilecek miyim

Karnım acıktı yine

Yoksa

Yoksa

Yoksa

Hayır

Sevdada da

Kavgada da

Tereddüt etmek ihanettir

Asla......diren

Baktım kurtuluş yok hayallerden

Bu kahrolası işkenceden

Umudumda sakladığım bir baş soğanı

Gözyaşıma bana bana

Kurumuş ekmeklerin eşliğinde

Yedim hücremde

Merak etme İstiklal savaşı gazisi Osman amca

Merak etmeyin dostlarım

Merak etme Ustabaşı Mehmet, küçük Süleyman

Merak etme Gavur Ali

Arabacı Yunus

Emekçi Erdal merak etme

Sevgili öğretmenin Refika Hanım

Bana direnişi öğreten

Şehit yuvası ülkem merak etme

Ödün vermeden sır vermeden işkencecilere

Direneceğim

Tek bir söz çıkmayacak ağzımdan

Yaşasın Özgürlük

Yaşasın Direniş''ten başka...', 'Gökkuşağından  bir sevgi aldım gönlüme Yıldızlardan bir fahişeyi koynuma Hiç söylenmemiş şarkıları söyledim günbatımına Bulutları yastık yap...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":141,"source_url":"https://www.antoloji.com/iskencede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavgada düşenlere', 'kavgada-dusenlere-muzaffer-gezer-68qia', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçim yanıyor canına yandığım

Sanki bir volkan kaynamakta şuracığımda

Her düşen kan damlacığında

Filizlenmekte bende bir şeyler bilenmekte

Kavga kavga türkü söylemekte dilim

Farkında olmadan halaylar çekmekteyim

Bir ucu Malatya''da bir ucu Gültepe''de

Kimi zaman grevde kimi zaman direnişte

Bir elim denizde bir elim güneşte

Biliyorum

Bir gidildi mi bin gelinir bizde

Üzülmüyorum

Bakma sen benim gözlerimin

Dolu dolu olduğuna

İhanet etmişler bana ağlıyorlar

Kimbilir

Beliki de sevinç gözyaşları bunlar

Yiğidin ölümü de yiğitçe olur

Yiğitliğin geliyor aklıma

Isırıyorum dudaklarımı

Ve haykırıyorum

Yaşasın ölüm

Ölüm özgürlük içinse', 'İçim yanıyor canına yandığım Sanki bir volkan kaynamakta şuracığımda Her düşen kan damlacığında Filizlenmekte bende bir şeyler bilenmekte Ka...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kavgada-dusenlere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen İstanbul''dun', 'sen-i-stanbul-dun-muzaffer-gezer-fxae0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yakacağım İstanbul''u

Hiç bir aşığı barındırmasın koynunda

Elele gezen gençler

Parklarda kulağı ezanda olan yaşlılar

Görmek istemiyorum

Vapurlar çalışmasın artık

İki kıta arasında

Çaylar satılmasın güvertelerde

Simitler atılmasın martılara

Güvercinlere yem

Yeni Camii önünde

''Abilerim ablalarım'' diye

Sızlanmasın dilenciler

Ara sokaklarda

Birbirine yaslanmış cumbalı evler

Sessizliğe yaslansın yıkılsın

Süleymaniye''yi bombalayacağım

O haşmetli yapı

Dönüşsün haşmetli bir taş yığınağına

Yakacağım yıkacağım İstanbul''u

Kahpe bir fahişe gibi

Aralamasın bacaklarını

Ben istanbul''a doluydum

İstanbul sensiz boş

Saplayacağım hançeri parçalayacağım

Göğsünün tam ortasını', 'Yakacağım İstanbul''u Hiç bir aşığı barındırmasın koynunda Elele gezen gençler Parklarda kulağı ezanda olan yaşlılar Görmek istemiyorum Vapur...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sen-istanbul-dun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba bilinmez', 'merhaba-bilinmez-muzaffer-gezer-s3bu7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yirmiyedi bahar gördüm yirmiyedi sevda

Yolun sonunda bekleyen azrail gibi

Yirmiyedi sonbahara çıktı gençliğim

Çocuktum uzaktan bakan uçurtmalara

Gençken de çocuk kaldım

Yaşatılmayan çocukluklarda

Sevgilere uzaktan baktım

Köşebaşında pusuya yatmış ihanet

Ardımdan saplanan dost hançerleri gördüm

Genç genç kızlar

Feleğin çemberinden geçmiş kadınlar sevdim

danslar ettim sabahlara dek

İri memeli İtalyanın koynunda

Menekşe gözlü Fransız''dan aşkı öğrendim

Falakaya yatıran polis

''Şiir böyle yazılır'' dedi

Koştururken şişmiş ayaklarımın üstünde

Patlayıncaya kadar şişeler boşalttım

Kustum bir ağacın altına

Kinimi kustum

Kustum öfkemi

Korsanlarda kavga

Yüreklerde sevda

Olabildim mi acaba

Mahkemeler gördüm darbeler

Sabaha karşı üçbuçuklarda uyandıran askerler

Çekilen tırnaklar, cereyanlar böldü uykumu

İddianameler, yargılar

Yargısız infazlarda canveren dostlar gördüm

Acısıyla tatlısıyla

Yirmiyedi bahar gördüm yirmiyedi sevda

Yirmiyedi hançer yadim

Merhaba yirmisekiz yaşım

Yirmisekizinci hançer

Merhaba', 'Yirmiyedi bahar gördüm yirmiyedi sevda Yolun sonunda bekleyen azrail gibi Yirmiyedi sonbahara çıktı gençliğim Çocuktum uzaktan bakan uçurtma...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/merhaba-bilinmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük', 'ozgurluk-muzaffer-gezer-n22u5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kararır gökyüzü boşalır bulutlar

Sen çıkarsın dağların ardından

Güneş olursun

Kapanınca kapısı hücremin

Kemirirken bileğimi zincirler

Sen gülersin taşların arasından

Umut olursun

Dudağımda senin türkün

Ellerimde kızıl karanfil

Derinliğinde gözlerimin bir güvercin

Sen bana yoldaş olursun

Anadolu''nun bir köşesinde

Bir köyde

Ya da yıkık dökük

Yakılmış bir mezrada

Eli kınalı bir ananın elinde

Dertle yoğrulmuş

Gözyaşıyla açılmış yufkanın yanıklığında

Sen kokarsın

Nehirlerin çığlığı çığlığıma karışır

Rüzgarlar fırtınalar kızgınlığıma

Yanardağ olurum

Yanarım kükrerim

Ateşimde sen tütersin', 'Kararır gökyüzü boşalır bulutlar Sen çıkarsın dağların ardından Güneş olursun Kapanınca kapısı hücremin Kemirirken bileğimi zincirler Sen gü...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ozgurluk-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk umuttur', 'ask-umuttur-muzaffer-gezer-obk1k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''AŞK'' vardı bir zamanlar

Kenarda köşede kalmış

Eski bir İstanbul''un

Siyah-beyaz fotoğrafında...

Bir istiridye kabuğunun altında

Bıyıkları terlememiş delikanlıların

Bacakları erkeksi kıllarla örtülü genç kızların

Umudunda saklı '' AŞK'' vardı bir zamanlar

Hücresinde duvara yaslanmış

''Senede bir gün'' ü mırıldanan mahkumda

Bıçak gibi

Toprağı yarıp giren

İçinde oynaşan çocukların gölgeleriyle

Nehirlerde derelerde

Ve ulaşıldığında zirveye

Okyanuslarda

''AŞK'' vardı bir zamanlar

Bir güvercin ağzında zeytin dalı

Kanadının altında bir kurşun yarası

''Aşk umuttur'' dedi...

''Aşk hala var''............', '''AŞK'' vardı bir zamanlar Kenarda köşede kalmış Eski bir İstanbul''un Siyah-beyaz fotoğrafında... Bir istiridye kabuğunun altında Bıyıkları te...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ask-umuttur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben İstanbul''dum', 'ben-i-stanbul-dum-muzaffer-gezer-2bmwo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yok oluyor bu şehir her akşam

Güneş kaybolurken ufuktan

Bu mevsim hangi mevsim

Bu kaçan kaçıncı zaman

Güneşimdin ışığımdın canımdın

Karardın

Karardı bu yürek 

Bu kent ağladı

Ne Boğaz eski Boğaz''dır

Ne bu şehir İstanbul

Ömrümden yıllarım aktı umarsız

Gece aynı gece

Soğuk ve ıssız

Çamlıca yaslanmış Süleymaniye''ye

Ortaköy suskun

Üsküdar ağlar

Bu mevsim hangi mevsim

Bu kaçan kaçıncı zaman

Güneşimdin ışığımdın canımdın

Karardın

Karardı bu yürek 

Bu kent ağladı

Ne Boğaz eski Boğaz''dır

Ne bu şehir İstanbul...', 'Yok oluyor bu şehir her akşam Güneş kaybolurken ufuktan Bu mevsim hangi mevsim Bu kaçan kaçıncı zaman Güneşimdin ışığımdın canımdın Karardın...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-istanbul-dum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İç Hesaplaşma', 'i-c-hesaplasma-muzaffer-gezer-1ocwk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İç hesaplaşma yaşıyor vücudum

Gittiğin günden beri

Ayaklarım kaçarken sevdadan kaypakça

Beynimse kavgada

Ellerim sallanırken geçmişime

Gözlerim ihanet etmekte erkekliğime

Ağlamakta

İhtilallerin en kanlısı yaşanmakta

Gözbebeklerimde umut idam edilmekte', 'İç hesaplaşma yaşıyor vücudum Gittiğin günden beri Ayaklarım kaçarken sevdadan kaypakça Beynimse kavgada Ellerim sallanırken geçmişime Gözle...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ic-hesaplasma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Firari', 'firari-muzaffer-gezer-yxkum', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elveda sevgilim

Yolcu yolunda gerek gitmeliyim

Birazdan sabah olacak

Aydınlığa karışacak gökteki yıldızlar

Yeni bir güne bırakırken yerini

Yeni olaylara gebe saatlere

Çekip gidecek gece

Artık ben de bir yıldız gibi kayarak

Kaçmalıyım evrenin derinliklerine

Ama inan sevdiceğim

İnan bana

Bir sabah geleceğim

Bugünkünün aksine

Bulutların ardına saklanmadan

Elimi kolumu sallaya sallaya

Dikileceğim kapına

Işık içeceğiz

Ve sonra

Bekareti bozulmamış gecenin koynunda

Dalacağız derin bir uykuya', 'Elveda sevgilim Yolcu yolunda gerek gitmeliyim Birazdan sabah olacak Aydınlığa karışacak gökteki yıldızlar Yeni bir güne bırakırken yerini Y...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/firari-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Biz', 'artik-biz-muzaffer-gezer-815l8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çılgınca bir aşk bu, delice sevda

Korkuyor

Ağlıyor

Seviyorum

Bir anne masal edasıyla çocuğuna

Aşkımızı anlatmakta duyuyorum

Uzaktan 

Vapur ve martı seslerine karışarak

Geliyor şarkımız

Sessiz sessiz

Yarını yok biliyorum

Kararmış sevdanın ufku ümitsiz

Ne Leyla ne Mecnun

Ne Kerem ne Aslı

Ne Ferhat ne Şirin

Artık BİZ

Yalnızlığın verdiği bir öfke 

Umutsuzluğun son çırpınışı mıdır bu bilinmez

Bilinmez yarınlara doğru ilerlerken

Geçmişin karanlığı ile

Geleceğin belirsizliği arasında savrulan bedenim

Kafesini parçalamış  bir kuş gibi

Kanat çırparken sana

Hala çaresiz hala ümitsiz

Ne Leyla ne Mecnun

Ne Kerem ne Aslı

Ne Ferhat ne Şirin

Artık BİZ', 'Çılgınca bir aşk bu, delice sevda Korkuyor Ağlıyor Seviyorum Bir anne masal edasıyla çocuğuna Aşkımızı anlatmakta duyuyorum Uzaktan  Vapur v...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/artik-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamadım', 'unutamadim-muzaffer-gezer-8ta7z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kederler katmer katmer

Yollar arşın arşın oldu bu akşam

Yıldızlar parlamaz

Deniz kıpırdamaz

Gözler bile ağlamaz oldu

Ruhumdan süzülen sis birikintisi

Alnımdan akan tere

Dudaklarıma bulaşmış şaraba karıştı

Bu akşam sevgilim

Bu akşam

Ne varsa yeryüzünde ve gökyüzünde

Bana seni hatırlatmak için yarıştı

Unutamadım', 'Kederler katmer katmer Yollar arşın arşın oldu bu akşam Yıldızlar parlamaz Deniz kıpırdamaz Gözler bile ağlamaz oldu Ruhumdan süzülen sis bi...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/unutamadim-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niçin', 'nicin-muzaffer-gezer-l5hte', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yolcusuz gemi gibi

Yol aldım kuytulardan

Dört yanı parçalayan o azgın dalgalardan

Kaçıyorum gülüm

Senden, kendimden, sevdadan

Vardığım en son liman sen olsan canım benim

Isıtsan ellerinle kavursan ateş gibi

Uyutsan dizlerinde okşasan annem gibi

Sen bedeninle koca bir çınar

Ve gözlerinle küçük

Ürkek ve bebek

Bense bir ayyaşın şişesindeki son damla

Gerillanın son mermisi

Bir idamlığın ürpertisiyim

Nedir bu anlamsızlık

Nedir bu alıp veremediğim kendimle

İnsanlarla

Tanrıyla

Kitaplarla, kitapsızlarla

Ve sevda

Niçin yasaktır bana', 'Yolcusuz gemi gibi Yol aldım kuytulardan Dört yanı parçalayan o azgın dalgalardan Kaçıyorum gülüm Senden, kendimden, sevdadan Vardığım en so...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/nicin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son ders', 'son-ders-muzaffer-gezer-c9ljp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerinden öğrendim ben sevgiyi

Ana şefkatini aratmayan sıcaklığını

Dudaklarınla özgürlüğü

Öfkeyi

Kavgayı

Yani

Yaşamayı güzelim

..

..

Arkanı dönüp gittiğinde

En son dersimi verdin

Ölümü öğrettin bana

Benim sevgili öğretmenim', 'Gözlerinden öğrendim ben sevgiyi Ana şefkatini aratmayan sıcaklığını Dudaklarınla özgürlüğü Öfkeyi Kavgayı Yani Yaşamayı güzelim .. .. Arkan...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/son-ders-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamadığım', 'anlatamadigim-muzaffer-gezer-hogka', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birşeyler oldu bana

Anlatamadığım

Bir sır gibi yüreğimde sakladığım

Bir sarhoşun ağız kokusu  kadar acı 

Acılarla dolu bir türkü

Türkü söyleyen köylü kızı gibi ürkek

Birşeyler oldu bana

Kimbilir kim yatırıldı yine tezgahlara

Tabutluklara

Cereyanlara

Falakalara

Zaman zaman direniş

Kimi zaman çözülme

An gelir gurur

Kahrolası ihanet, pişmanlık

İtirafçının listesinde ben

Bende itiraf edilemeyen sevdalar

Birşeyler oldu bana

Anlatamadığım

Bir sır gibi yüreğimde sakladığım', 'Birşeyler oldu bana Anlatamadığım Bir sır gibi yüreğimde sakladığım Bir sarhoşun ağız kokusu  kadar acı  Acılarla dolu bir türkü Türkü söyle...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anlatamadigim-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttum Unutturamadıklarını', 'unuttum-unutturamadiklarini-muzaffer-gezer-sggkg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Unuttum güneşin nasıl göründüğünü

Yıllar var görmedim

Unuttum

Bebelerin nasıl güldüğünü

Yine öyle şen şakrak mısın bebek

Yine sarı beyaz mı papatyalar

Kondulardan boşalıp emekçiler

Dolduruyor mu atölyeleri tersaneleri

Elleri yüzleri kara

Gelecekleri aydınlık

Küçük boyacı çocuklar

Kaplıyor mu otobüs duraklarını

Sırtında çuvalı ile eskici

Yırtıyor mu sessizliğini sokağımın

Unuttum güneşin nasıl göründüğünü

Galata köprüsünden

Galata Köprüsü yerinde mi

İstanbul

O işveli gavurdan dönme fahişe

Hala güzel mi', 'Unuttum güneşin nasıl göründüğünü Yıllar var görmedim Unuttum Bebelerin nasıl güldüğünü Yine öyle şen şakrak mısın bebek Yine sarı beyaz mı ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/unuttum-unutturamadiklarini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm mü', 'olum-mu-muzaffer-gezer-9wlvu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir türküdür ölüm

Daha beşikteyken söylenen başucunda

ne kadar benzer birbirine

Kundak yapılan patiskayla

Vücuduna sarılan bez parçası

Gözlerini yumup öldüğünde

Ölümü özlemek

Ne yılmaktır direnişten

Ne de yaşamdan korkmak

Ölümü içine sindire sindire

Çekmektir yaşamak', 'Bir türküdür ölüm Daha beşikteyken söylenen başucunda ne kadar benzer birbirine Kundak yapılan patiskayla Vücuduna sarılan bez parçası Gözle...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/olum-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol Ayrımı', 'yol-ayrimi-muzaffer-gezer-wg2wp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İki yol var önünde

Ya teslimiyet ya direniş

Ya bir köle gibi payandası olursun

Kan emicinin

Yada kızıl bir güneş gibi

Yırtarsın karanlığı

Ya çöplüğüne atılırsın tarihin

Yada sen yazarsın tarihi

DİRENİRSİN...', 'İki yol var önünde Ya teslimiyet ya direniş Ya bir köle gibi payandası olursun Kan emicinin Yada kızıl bir güneş gibi Yırtarsın karanlığı Ya...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yol-ayrimi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek zorlu iştir', 'sevmek-zorlu-istir-muzaffer-gezer-5asgl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmek zorlu iştir 

Yaman iştir anlayacağın.

Öyle oyuna gelmez

Şakadan anlamaz

Bir bilinmez bilmecedir yani

Oldu mu adam gibi olmalı

İşin kolayına kaçmadan

Cilalamadan boyamadan

Ama yiğitçe ama delice

Sınırsız ve kuralsız

Barikatlara karşı mert

Kahpeliklere amansız

Oldu mu Allahsız olmalı

Tüm kutsal kitapları yakmalı

Ve öyle büyük ki

Tanrı önünde secde durmalı

Sevmek zorlu iştir

Alabildiğince emek

Mangal gibi yürek

Ve yürekte isyan ister

Kenar mahallelerde büyümüştür

Anlamaz aristokrat ağızlardan

Ama soyludur

Babadan hırsız

Anadan evliya

Doğuştan ölümsüzdür

Bıçkın delikanlıdır sokak kavgalarında

Masum bir kız edasında

Dolaşır düşlerini sevişmelerin

Kayıptır gazete ilanlarında

Hükümsüzdür

Sevmek zorlu iştir

Yudum yudum içmeli

Ne zemzem ne kadehte şarap

Zehir de olsa düşünmeden içmeli

Akıl felsefe ide

Din dogma inanç

Bırakıp dünyaya her şeyi

Yarin göğsünde kendinden geçmeli

Sevmek zorlu iştir

Zoru sevmeli önce yani

Sonrası geliyor ardından

...

Sensizlik de zor be gülüm

Alışamadım yokluğuna

Zora gelemedim

Aşkı

Yine beceremedim', 'Sevmek zorlu iştir  Yaman iştir anlayacağın. Öyle oyuna gelmez Şakadan anlamaz Bir bilinmez bilmecedir yani Oldu mu adam gibi olmalı İşin ko...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/sevmek-zorlu-istir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldin', 'hosgeldin-muzaffer-gezer-5z58o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Önce düşümde gördüm seni 

Bir gece vaktiydi.

Melekler tutup getirmişlerdi 

Bir elinden Cebrail tutuyordu

Öbüründen Kutsal Meryem

O sabah bütün kiliselerde senden sözediliyordu

Senin gelişin muştulanıyordu 

Bir ilahi barış 

Filizlenip boy atıyordu

Kurt kuzuya ceylan avcıya yanaşır oldu

Hoş o gün cuma da değildi ama

Bütün hutbelerde adın okundu

Çıktım baktım gökyüzüne

Güneşle ay yanyanaydı

Yıldızlarda yakamozlarla

Herkeste bir sevinç, bir telaş

Bir bayram havası

O geliyor diyorlardı

Sonra aşıkların kralı çağırdı beni

bana bak dedi

Kulağını aç iyi dinle

Gözünü aç bekle

Sana aşkların en güzelini verdik

Dinlerin en ulusunu

Sana rabbi verdik

Birden bir ışık sağanağıyla yırtıldı kapım

Önce güneş girdi içeri

Sonra bulutlar, rüzgar

Yıldızlar ve yakamozlar

Yaralarım sarıldı

Binlerce yıl görmeyen

Gözlerim açıldı

Güneş gözlerimde

Başım bulutlara yükseldi

Yürek rüzgarlarla kanatlandı

Ellerinde yıldız

Saçlarında yakamoz, 

Gelen sendin

Hoşgeldin...

                  18 ekim 2000', 'Önce düşümde gördüm seni  Bir gece vaktiydi. Melekler tutup getirmişlerdi  Bir elinden Cebrail tutuyordu Öbüründen Kutsal Meryem O sabah büt...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/hosgeldin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Gülümsemelerdi', 'kucuk-gulumsemelerdi-muzaffer-gezer-droe1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Küçük gülümsemelerdi üzerimize yağan

Kurşun grisi akşamlarında İstanbul’un

Ve damağımızda

İki bisküvi arasında sıkıştırılmış lokumun tadı

Henüz kirletilmemişti düşler

Düşlerde henüz sansür yoktu

Ve bedavaydı 

Çamurlu sokaklarda düşüp dizini kanatmak

Yandan çarklı bir vapur geçerdi evimizin üzerinden

Babam yandan çarklı içerdi kahveyi

Çarkın nasıl döndüğünü bilmezdim

Ve aşk

Siyah beyaz filmlerde

Abilerle ablaların dudaklarının değmesiydi birbirine

SON yazmadan hemen önce

Perşembe gecelerinin 

Radyo tiyatrosu kokan saatleri

Karışırdı sobanın üstünde kavrulan

Çift bıçak atılmış kestaneye

Sokaktan bağırarak geçen gazeteci çocuk

Bozacı amca

Elinde çıngırağı ile yoğurtçu

Bahçemizde bir horoz iki tavuk

Derme çatma bir kümes

Ve nedense bile bile

Her gece zehirli elmayı yiyen Pamuk Prenses

Özgür düşleri vardı çocukluğumun

Altımda beyaz yeleli bir at

Düşman kovalardım

Bizim sokağa gelen

Aşağı sokağın çocuklarını

Ve nedense sonunda

Hep beni öperdi komşunun kızı

Ağzı yediği şekerden yapış yapış

Erik imsi memeleri

Sanırım en güzel hazdı

İlk erkekliğin mastürbasyon geceleri

Küçük gülümsemelerdi üzerimize yağan

Kurşun grisi zamanlarda

Bayram sabahlarında İstanbul’un

Yarım yamalak alınan abdestler

Babanın yanında acemice kılınan namaz sonrası

Akşama dek süren el öpmeler

Küçük gülümsemelerdi üzerimize yağan

Büyük düşler taşıyan küçücük yüreğimize 

Acımasızca çarpan

Çocuk dünyamızda ne nefret ne de aşk vardı

Nefret; çişimizeydi

Olur olmaz yerde gelir diye

Aşk; elma şekerine

Bir de beyaz perdeye yansıyan hayali sevgiliye

İhanetle tanışmamıştık 

İnsana özgü o çılgınlığı

Yani korkuyu tatmamıştık

Küçük gülümsemelerdi üzerimize yağan

Henüz kurşunla karşılaşmamıştık

Kurşun grisi günler boyu İstanbul’da

Ve damağımızda

Tuzlu fıstık, kırmızı şarap tadı, yavan ekmek

Bilmem kaç volt cereyan askı falaka

Büyüdük

Ve bedavaydı

Dilediğince ağlayıp

Kim bilir ölmek...

Küçük gülümsemelerdi

Küçük gülümsemeler

Küçük gülümseme

Küçük gülümse

Küçük gülüm

Küçük 

Küçüğüm...', 'Küçük gülümsemelerdi üzerimize yağan Kurşun grisi akşamlarında İstanbul’un Ve damağımızda İki bisküvi arasında sıkıştırılmış lokumun tadı He...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/kucuk-gulumsemelerdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç', 'agac-elif-sebnem-akal-a3buw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Devrilmemeye yeminli 

Asırlık ağaç gibi mi

Gördü gözleriniz beni? 

Haykıran 

Öfkeli 

Asi

Sözlerim mi siperledi 

Aslında çok ince, narin

Ruhumun hapsedildiği 

Yaralı kalpli gövdemi? 

İnsan kızıyım ben insan

Ne evliya, ne hükümran

Başı yüksek, yukarıda 

Dalı eğik, tutunana

Cesur ama mütevazı

Bir deli ağaç misali 

İnsan kızıyım

İnsanım

Tutunurken dallarıma

Fazla eğip kıranlara 

Öfkeli değil 

Kırgınım...

23.01.2003', 'Devrilmemeye yeminli  Asırlık ağaç gibi mi Gördü gözleriniz beni?  Haykıran  Öfkeli  Asi Sözlerim mi siperledi  Aslında çok ince, narin Ruhu...', ARRAY['Türk Edebiyatı','Şiir','Elif Şebnem Akal']::text[], 8.5, '{"poet":"Elif Şebnem Akal","poet_slug":"elif-sebnem-akal","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/agac-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ALACAĞIM OLSUN', 'alacagim-olsun-arzu-bagriacik-slvpe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SENDE BAZEN YAPAR MISIN? 

YORGANIN ALTINDAN İNATLA ÇIKMAMAYI

TELEVİZYONUN SADECE AÇIK OLDUĞU 

VE DÜNYADAN KOPMAYI AMAÇLAMAYI.

TÜM HIZINLA KOŞAR MISISN GEÇMİŞE? 

TAKILI KALIR MISIN, 

ANİ FRENLE BİR NOKTADA? 

BULMUŞSUNDUR İÇİNİ KEMİRENİ

SENİ YAVAŞ YAVAŞ BİTİRENİ.

ÇIKIŞINI YAŞADIĞIN ZAMANLARI TUTABİLİR MİSİN

VE DEĞİŞTİREBİLİR MİSİN? 

SANMIYORUM YAĞMURU İLİKLERİNDE HİSSETTİĞİNİ

KALDIRIMLARI ADIMLARKEN

RUHUNU ISLAH ETTİĞİNİ

İNEBİLDİĞİNCE GEÇMİŞE İNİP

VOLKAN OLUP PATLAMAYI, 

KORKMADAN BAĞIRMAYI

GÜLMEYİ VE HATTA AĞLAMAYI...

AYNI ANDA HEPSİNİ YAŞAMAYI.



 

BAK DUYUYOR MUSUN SESİ? 

KORKUYORUM.

O ANDA TAŞLARIN HEPSİNİ

AVUCUMA SIĞDIRMAYI

VAR KUVVETİMLE BULUTLARA FIRLATMAYI

NE ÇOK İSTİYORUM...

İŞTE BAK HERYERİ SARMIŞLAR

RENKLERİDE SOĞUK

YILDIZIMI KAPAMIŞLAR

YOKSUN 

BİR BAKIŞLIK ALACAĞIN OLSUN.

VİRANEMDE YİNE IŞIK YOK

AŞIM DAHA BİR DÜĞÜMLENİYOR, YUTAMIYORUM

HAY LANET OLASI ODA SPREYİDE BİTMİŞ

OYSA SABAH YENİDEN DOĞMUŞTUM

KİLİTLERKEN KAPIMI, 

DAHA BİR YAVAŞLAMIŞTIM.

BURKUK YÜREĞİMLE 

ELVADAYI ÇEKMİŞTİM.

BAŞLARKEN GECEME

HESAPLAMAMIŞTIM KOKUNU

VE YİNE HESAPLAMAMIŞIM

RUHUMUN IŞILDAYIŞINI

AFFET 

BUNU ATLAMIŞIM; 

SİNSİ BİR YILAN OLUŞUNU...

MASAMDA KIRMIZI ŞARAP

BOŞ KADEHLE TOKUŞMAKTAYIM

BİZE DİYE YUDUMLARKEN

BİR YANDAN MÜZİKLE YANMAKTAYIM

KORKTUĞUN SON ÖPÜCÜĞÜ

YANAĞINA KONDURMANIN İSYANINI

GÖZLERİMDEKİ ÇIĞLIĞIMLA

DUYURMAKTAYIM.

UZUN OLMUŞ SESSİZLİĞİM FARKINDAYIM.



 

BU GECE DAHA BİR FERYATLIYIM

KAN KUSUYORUM KİNİMLE

NASIL YAPARSIN BUNU

NASIL GİDERSİN BULUTLARA? 

HANİ BİR MERDİVEN OLSA

ÇIKACAĞIM YANINA.

UNUTULMAMAK ADINA

DİKECEĞİM BEDENİMİ KARŞINA.

RUHUMU AVUTMAM

DARDA KALDIĞIMDAN

SEN BANA ALDIRMA

BU GİDİŞLE UZAMAZ

ŞAKAĞIMDA PATLAMA...

DURMA GEL

BİEDE AŞAĞIDAN BAK BURALARA

SİGARA DAĞLAMAZSA CİĞERİNİ

İÇKİ YAKMAZSA MİDENİ

HANİ SIRF YAŞAM ADINA

BÖLERKEN EKMEĞİNİ, 

ATARKEN BEDENİNİ YATAĞA...

GETİRİRSEN AKLINA

PERDEYİ ARALA.

ILIK BAKARSAN YILDIZLARA

GRİLER SARMIŞSA HER YANI

UMUDUN SÖNERSE ANİDEN, 

LANET ETMEYE BAŞLAMA

YOKSAM SAKLAN KARANLIĞA...

CAN; 

EN PARLAĞI BENİM UNUTMA

GÖZ KIRPAMIYORSA SANA

SAKIN BAŞKA YERE BAKMA

SAKLA YARINA 

ALACAĞIM OLSUN

GEÇMİŞİN HATIRINA....

01-2003-ANKARA', 'SENDE BAZEN YAPAR MISIN?  YORGANIN ALTINDAN İNATLA ÇIKMAMAYI TELEVİZYONUN SADECE AÇIK OLDUĞU  VE DÜNYADAN KOPMAYI AMAÇLAMAYI. TÜM HIZINLA KO...', ARRAY['Türk Edebiyatı','Şiir','Arzu Bağrıaçık']::text[], 8.5, '{"poet":"Arzu Bağrıaçık","poet_slug":"arzu-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":89,"source_url":"https://www.antoloji.com/alacagim-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakub''a Döndüm', 'yakub-a-dondum-yakup-caglayan-ybkdy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevda dedikleri bumu bilmem amma

Kederi kendime yol ettim sanki

Bu ciğer yarası sönermi bilmem amma

Ayakta gezen ölüye döndüm sanki

Dostlar beni kınamayın sakın ne olur

sizinde başınıza geçsin bak neler olur

Kimseye verme bu derdi Allahım ne olur

Yaraları kurtlanmış Eyyub''a döndüm sanki

İlacı yok bu derdi veren ALLAH''a şükür tabi

Eyyub''a verdiğin sabrı bana da ver yarabbi

Bu sır dolu ten birgün toprak olur tabi

Ağlayarak kör olan Yakub''a döndüm sanki', 'Sevda dedikleri bumu bilmem amma Kederi kendime yol ettim sanki Bu ciğer yarası sönermi bilmem amma Ayakta gezen ölüye döndüm sanki Dostlar ...', ARRAY['Türk Edebiyatı','Şiir','Yakup Çağlayan']::text[], 8.5, '{"poet":"Yakup Çağlayan","poet_slug":"yakup-caglayan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yakub-a-dondum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öz Gazeli', 'oz-gazeli-eymen-erdem-akca-x6y1n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dualarla bezenmiş seherlerin ay yüzü

Bağışlar Merhametlim kan ağlayan öksüzü

Süzüldükçe gözünden pişmanlık damlaları

Aydınlanır dünyası, ferah bulur gündüzü

Çekiverir yüzünden kederli bulutları

Sessizliğin bağrında saklayan özümüzü

Açıldıkça âlemin dilinde " Gül " ezgisi

Duyurur semâlarda özgürlük türkümüzü

Süt beyaz arzularla çınlayan yüreğimde

Eksilir hüzünlerin dağ dağ olmuş pürüzü

Kabartır bin gururla kuruyan toprakları

Yağmur-vari sevginin hikmet çağlayan sözü

Yansıyor çehrelere ümidin ışıkları

Kavisler çizer durur yeislerin Hürmüzü

Volkan gibi patlar şu âlemin çekirdeği

Filiz verir demâdem vurarak mührümüzü

Çevirir yücelere, öteler ötesine

Bir noktada boğulan gönüller gözümüzü

Dinsin hafakanları hakikat sevdasına

Bağırlarına bassın nur yolu sözümüzü', 'Dualarla bezenmiş seherlerin ay yüzü Bağışlar Merhametlim kan ağlayan öksüzü Süzüldükçe gözünden pişmanlık damlaları Aydınlanır dünyası, fer...', ARRAY['Türk Edebiyatı','Şiir','Eymen Erdem Akça']::text[], 8.5, '{"poet":"Eymen Erdem Akça","poet_slug":"eymen-erdem-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oz-gazeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Eller', 'bu-eller-eymen-erdem-akca-6fu4q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Benim mi ki bu eller buruşmuş yaprak gibi

Damarları görünür titreyen bileğimin

Sürgünü yaşıyorum ömrümün baharından

Feryadı duyulmuyor kahr olan yüreğimin

Çimenler de sapsarı yüzümün rengindeler

Bilmezler sonbaharın fırtınalı kışını

Gözlerim ötelere uzanan engindeler

Alırlar martıların çığlıklı bağışını

Saçılır içimdeki dehlizlere ağılar

Yığılır küme küme üstüme kara duman

Seher vakti düşüyor saçıma kırağılar

Belli bellirsiz anda katlime çıktı ferman

Kesilir hayalleri kan ağlayan gecenin

Biçilen ekinlerin eyvahını kim duyar

Dağılır umutları ebed aşklı hecenin

Kim bu körpe bedenin günahlarını yuyar

Çekil önümden gece gündüzün aşığıyım

Güzellik beliriyor gündüzün gelmesiyle

Karanlık diyarların umudu, ışığıyım

Gökten kudret helvası yağar nur çeşmesiyle

                                Erdem AKÇA- Kayseri', 'Benim mi ki bu eller buruşmuş yaprak gibi Damarları görünür titreyen bileğimin Sürgünü yaşıyorum ömrümün baharından Feryadı duyulmuyor kahr ...', ARRAY['Türk Edebiyatı','Şiir','Eymen Erdem Akça']::text[], 8.5, '{"poet":"Eymen Erdem Akça","poet_slug":"eymen-erdem-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bu-eller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye Çattın Kaşlarını', 'niye-cattin-kaslarini-neset-ertas-kihkb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Niye çattın kaşlarını 

 Bilmiyom yar suçlarımı

Ben ölürsem saçlarını

 Yolma gayrı yolma leyli leyli yar

Ben yandım aşkın narına 

 Meyletmem dünya malına

Ben ölürsem mezarıma 

 Gelme gayrı gelme leyli leyli yar

Bir garibim düştüm dile

 Gerçeklerde olmaz hile

Zalimler elinden bile

 Alma gayrı alma leyli leyli yar', 'Niye çattın kaşlarını   Bilmiyom yar suçlarımı Ben ölürsem saçlarını  Yolma gayrı yolma leyli leyli yar Ben yandım aşkın narına   Meyletmem ...', ARRAY['Türk Edebiyatı','Şiir','Neşet Ertaş']::text[], 8.5, '{"poet":"Neşet Ertaş","poet_slug":"neset-ertas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/niye-cattin-kaslarini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annemin Duaları', 'annemin-dualari-eymen-erdem-akca-qu7sy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Geçmiş günler hüzünle karşımda duruyorlar

Gözlerinden süzülen yaşlar beni yakıyor

Neden bizi böyle hor koyup gittin diyorlar

Uzanamam sizlere zaman beni sıkıyor

Ellerim dolanıyor boşluğun yüreğinde

Sözlerim sizi anar kırılgan bir edayla

Gitmeyin... durun... durun gözlerimin önünde! 

Sükut kaplar geceyi... gecem dolu kavgayla 

Özleminiz içimde tıpkı bir yağmur gibi

Çisil çisil yağanda dalarım uzaklara

Özlem keder savaşı harap eder bu kalbi

O günlerin hasreti yansıyor sabahlara

Tutun şu bahtsız eli boşluklarda kalmasın

Sığıntısı olmuşum odama vuran hüznün

Bırakılıp köşede yalnızlığa dalmasın

Saçılsın yüreğime huzuru geçmiş ömrün

Gözlerim takıldı bak göz kırpan yıldızlara

Söz geçiremem an''a akıp gider son hızla

Bir düğün merasimi şu koşturan kızlara

Saksımda duran gülün açılması bin nazla

Annemin hayalidir gözlerime fer veren

Ruhuma şefkatların en sıcağı dolarken

Sevgi çiçekleridir hüzünleri gideren

Süzülen damlalarla gözbebeği gülerken

Uzat nurdan elini öpeyim sonsuz hazla

Duyayım en katıksız sevgi çağlayanını

Kapanıp ayağına ağlayayım niyazla

Öpüver son bir defa yüzümün her yanını

Dudağından duyayım ''melek oğlum'' sözünü

Avutayım kendimi kirlenmedim ben diye

Çevir öteye doğru ışıl ışıl yüzünü

El salla gözyaşınla... yavruna son hediye

Çekiliyor perdeler... herkes dalar içine

Kondurur pişmanlığı yüreğime bir beste

Karşımda minik bir kız güller takar saçına

Bir bülbül ızdırapla öter durur kafeste

Vazomda boynu bükük bir demet papatyam var

Bakmıyorlar yüzüme... bu kadar hakirim ben

Günahlarla kanına girilmiş bin hülyam var

Bir çiçekten merhamet bekleyen fakirim ben 

Tablolar duruyorlar karşımda öyle cansız

Beni atar uzağa altımdan kayan kilim

Bir dua duyuyorum yan odamdan amansız

'' Allahım! Tut elimi! Sensiz ben var değilim ''

Fırtınalar kopuyor çizgi çizgi yüzümde

Gözlerim alev gibi delecek aynaları

Bir ''keşke'' sözü döner tütün kokan ağzımda

Başım avuçlarımda avlıyor duaları

Bir ömrün pişmanlığı nasıl yansır çehreye

Nasıl duyuyor insan acıtan gerçekliği

Pencereden bakarken sessiz akan dereye

Kesiliyor ruhumun sebepsiz son çığlığı

Dökülüyor karşımda kurumuş gül yaprağı

Acaba pişman mıdır geçirdiği günlere

Yıkılır ne hislerle ve ağlatır toprağı

Ey acımasız mevsim, mühür vur ölenlere! 

Kahr olur pişmanlıkla ömrümün her bir an''ı

Görüyorum bu yolun nereye gittiğini

Çaresizce eğilen başım dinler zamanı

İzlerim perde perde bu filmin bittiğini

Bir ışık, bir kıvılcım arar telaşla kalbim

Ölümü öldürecek biri yok mu alemde? 

Yok mu beni görecek, koruyacak Sahibim? 

Bin helecan içinde ruhum yanar elemde

Dualar duyuyorum her varlıktan yükselen

Ben de açtım elimi, kaldırdım annem gibi

Dilim tutuldu! Annem... duvarı delip gelen

Baktı...'' Melek oğlum! '' de! Ey bu yerler Sahibi! 

'' Sana sığınıyorum, dehalet ediyorum ''

'' Bu dünya çöllerinde bizi yalnız bırakma ''

'' Gönlümde bir meşale yandı, Anne '' diyorum

Bu günahkar oğlunu hiç duasız bırakma

Annemin şefkatiyle aydınlanan dünyamda

Sonsuzluğu verenin varlığı yerleşiyor

Selam dolu huzurla nurlar dolan rüyamda

Ebediyetin yolu yolumla birleşiyor

                             Kayseri', 'Geçmiş günler hüzünle karşımda duruyorlar Gözlerinden süzülen yaşlar beni yakıyor Neden bizi böyle hor koyup gittin diyorlar Uzanamam sizler...', ARRAY['Türk Edebiyatı','Şiir','Eymen Erdem Akça']::text[], 8.5, '{"poet":"Eymen Erdem Akça","poet_slug":"eymen-erdem-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/annemin-dualari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Allahın Resulü(A.S.M.)', 'ey-allahin-resulu-a-s-m-eymen-erdem-akca-zyl2p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sebeb-i halk u âlem Sensin yâ Resûlallah

Mahbûb-u Levh u Kalem Sensin yâ Resûlallah

Müşriklere bin elem Sensin yâ Resûlallah

Müminlere bir alem Sensin yâ Resûlallah 

Sana müştâk ve meftûn hasretinle yananlar

Alev alev kalbiyle Seni şevkle ananlar

O mücella çehrene bakıp da nurlananlar

Müzeyyen hayalini görerek uyananlar 

Ferîd-i kevn ü zaman Sensin yâ Resûlallah

Derd-i derûna derman Sensin yâ Resûlallah

Fakîre servet-sâmân Sensin yâ Resûlallah

Hakka reh-nümâ ferman Sensin yâ Resûlallah

Gönüllerin miftâhı, sığınılan sûru sen

Yüzyıllardır beklenen, özlenen huzûru sen

On dört asır dünyayı aydınlatan nûru sen

İnleyen vicdanların bitmeyen sürûru sen

Levlâke''nin sultânı Sensin yâ Resûlallah

Dertlilerin dermânı Sensin yâ Resûlallah

Kurbiyet kahramânı Sensin yâ Resûlallah

İnsanlığın emânı Sensin yâ Resûlallah 

Nûrunla aydınlanan geleceğim nûr dolu

Gösterdiğin çizgi ki, ebediyetin yolu

Hakka giden bir kula seher hâristân gülü

Sen güllerin şâhısın Hakkın eşsiz bülbülü

Hakikatler meftûnu Sensin yâ Resûlallah

Yaratılış mâcunu Sensin yâ Resûlallah

Ümmetinin cünûnu Sensin yâ Resûlallah

Aşkların en zebûnu Sensin yâ Resûlallah

Münevver bir meşale müşa''şa kandilsin Sen

Hakikat yolcusuna müstakim sebilsin Sen

Hakikati haykıran en müstesna dilsin Sen

Kabilleşen beşeri uyaran Hâbil''sin Sen

Ahyâru''l-Muhammedîn Sensin yâ Resûlallah

Pîşuvası beşerin Sensin yâ Resûlallah

Gönüllerde tek zerrîn Sensin yâ Resûlallah

Serzâkir-i seferîn Sensin yâ Resûlallah 

Gel gönüller sultânı özleminden eridik

Hazan estikçe esti günden güne çürüdük

Bir nazlı seher vakti sana doğru yürüdük

Senin eşsiz sevgini kalbimize bürüdük 

Gönüllerin sabâhı Sensin yâ Resûlallah

Müminlerin eyvâhı Sensin yâ Resûlallah

Beşerin intibâhı Sensin yâ Resûlallah

Kalblerin hubb-u câhı Sensin yâ Resûlallah 

Ne mesrûr yüreğimiz Seni şevkle anarken

Ne mahzûn yüreğimiz aşkla par par yanarken

Münkesir hayallerle etrafında dönerken

Cisimler Senden uzak, ruhlar Sana kanarken 

Habîb-i Rabbü''l- A''lâ Sensin yâ Resûlallah

Kimsesizlere sılâ Sensin yâ Resûlallah

Kalplerimize cilâ Sensin yâ Resûlallah

Hüsn-ü mücerred dilâ Sensin yâ Resûlallah 

Sûretin ve sîretin öyle güzel ey Habib

O tertemiz pak elin bütün dertlere tabib

Celalli bir cemalsin Rauf-Rahim muharrib

Yalpalayan bizlere nâdir-i hilkat hatib 

Hayallerin neşvesi Sensin yâ Resûlallah

Gönüllerin Hû sesi Sensin yâ Resûlallah

Âşıkların nefesi Sensin yâ Resûlallah

Yaratılış nüvesi Sensin yâ Resûlallah 

Susuzluğumuz Sana... yağ artık Rahmet-i Hak

Yağ ki derman kalmadı gönüllerimiz kurak

Yağmazsan ey Sevgili, bil ki olmuşuz helak

Bir ümmet-i merhûne Sana müştak ey Ap Ak 

Mücella çehrelerde Sensin yâ Resûlallah

Bîçare gönüllerde Sensin yâ Resûlallah

Nur saçan seherlerde Sensin yâ Resûlallah

Hakkı diyen dillerde Sensin yâ Resûlallah 

Seni övmek ne mümkün ey muattar Sevgili

Seni bilmek ne mümkün ey esen Sabâ yeli

Hasretliğin kül etti Sen bu elden gideli

Uzat artık bir kere öpelim nurdan eli 

Gariplerin velisi Sensin yâ Resûlallah

Hakikatin âlisi Sensin yâ Resûlallah

Sözlerin en gâlisi Sensin yâ Resûlallah

Ümmetin sevgilisi Sensin yâ Resûlallah

                              İstanbul', 'Sebeb-i halk u âlem Sensin yâ Resûlallah Mahbûb-u Levh u Kalem Sensin yâ Resûlallah Müşriklere bin elem Sensin yâ Resûlallah Müminlere bir a...', ARRAY['Türk Edebiyatı','Şiir','Eymen Erdem Akça']::text[], 8.5, '{"poet":"Eymen Erdem Akça","poet_slug":"eymen-erdem-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/ey-allahin-resulu-a-s-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakıcı Bakışlar', 'yakici-bakislar-eymen-erdem-akca-u4hzr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'HASRET ÇEKMEYEN VAR MI? ! ! ! 

Yakıcı bakışlarla bakma öyle yüzüme

Ben senin '' Ol! '' dediğin ''garip''lerden değilim

Hasret dolu olsa da yalan girmez sözüme

Çatlayan topraklara işte bundan meyilim

     

Sessiz, sakin ve mahzun durup inler karşımda

Çiçeklerle kaynayan mahşer yeri bu bahçe

Bir melek busesini yaşayan şu na''şımda

Ötelerden dokunmuş hasretlik kaneviçe

Sözlerimden yayılır gül kokusu aleme

Dilimden düşürmedim Gül Sultanın adını

Bir kaside yazdım ki alınmamış kaleme

Ve tattım sevdaların en ulvice tadını

Dermansız bedenime can geldi gül dedikçe

Kuruyan yüreğimde ummanlar çalkalandı

Yar dedikçe  ağladım o bana gül dedikçe

Nurdan helezonlarla yüreğim halkalandı

Sevindim çocuk gibi kalbim avucundayken

Titreyen sema gibi ben de kendimden geçtim

Bir sonsuza dökülen çavlanın ucundayken

Ötelere yol aldım ve dünyadan vazgeçtim

Tütsü gibi yayıldı rayihası her yere

Mükedder yüreğime huzurları serptikçe

Ve dağıldı bir nur ki ağlayan seherlere

İncinen yüreğime eyvahlarım değdikçe

Tutuşan ocaklardan fırlayan kıvılcımlar

Seni arar her yerde sönmek kaderleriyle

Ufka doğru uzanan yollardaki kıvrımlar

Seni sorar yolcuya bitmez kederleriyle

Ne muallasın ey yar sonsuz gecemin düşü

Sana doğru gitmeyen ahları ben neyleyim

Sensin sürgün diyarı bu dünyanın gülüşü

Sensiz ben bu alemi söyle söyle neyleyim

Nice asır oldu yar gurbetini yaşadık

Daha ne kadar sürer yıkılası bu devir

Sensizliğin yükünü bir ar gibi taşıdık

O mücella çehreni bir kere bize çevir

Gönlümüze tek neşe ruhumuza sürursun

Nurunla aydınlanan gül devrini özledik 

Sen bu vahşetzar yerde sığınılan tek sursun

Ayağının tozuna yüz sürüp yar gözledik

Dergahına kapanıp yüreğimi kanatmak

Ve senin özleminle mest olmak istiyorum

Rahmetinle şenlenen nur denizinde batmak

Seni seven her şeye dost olmak istiyorum

Tutulup bırakılan güvercinler sevinci

Beni sana anlatan mektuplardan yayılan

Adındır dilimizden ruha nakşolan inci

Bir ruhum var ki baygın nefesinle ayılan

Derman ol gönlümüze müstesna kurbetinle 

Karanlık dünyamıza inci mercan saçılsın

Ve bizi bizden alan derbeder gurbetinle

Kötülükler yok olsun zulmün başı biçilsin

Tutku dolu anların tükenişi sende hep

Neden öyle uzakta duruyorsun Sevgili

Sana visalle yanan ümmetinden bu talep

Sensin öte kokulu devirlerin kandili

                           Kayseri', 'HASRET ÇEKMEYEN VAR MI? ! ! !  Yakıcı bakışlarla bakma öyle yüzüme Ben senin '' Ol! '' dediğin ''garip''lerden değilim Hasret dolu olsa da yalan...', ARRAY['Türk Edebiyatı','Şiir','Eymen Erdem Akça']::text[], 8.5, '{"poet":"Eymen Erdem Akça","poet_slug":"eymen-erdem-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/yakici-bakislar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-eymen-erdem-akca-2cw5j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'SEN

Serazat hislerimin gül kokulu nuru sen

Müteellim günlerin bihemta huzuru sen

Çirkeflerden bulaşan karanlıkları delen

Sermedi hakikatin mest eden buhuru sen

Revaih-i tayyibe yayılır seherlere

Nur edalı seherin nurun ala nuru sen

Müştakın öyle çok ki ey güzeller güzeli

Sonsuzluğa uzanan yolların nühuru sen

Müjdelerle nur saçan o müstesna günlerin

İnleyip nalan olan bilinmez menşuru sen

Mübtelayım, meftunum, serazat serseriyim

Şu fikirsiz başımın mubassır şuuru sen

Cevelanlar koşuşur pörsüyen yüreğime

Elemlerle alude günümün süruru sen

Münkesir ahvalimle mecnununum ah Leyli

Dayanılmaz anların sığınılan suru sen

Gayrıyı terk eyleyip sana geldim Sevgili

Fakirlere hazine zeliller gururu sen

El-aman deyip geldim dergahına ey Canan

Tecellinle nurlanan kalbimin zuhuru sen

Tükenilen anlarda var''ın firar ettiği

Gufran tüten çehrenle gafurlar gafuru sen

Süeda güruhuna saadetler bahşeden

Şakirlerin andığı meşkurlar meşkuru sen

Unutulan kalplerden yükselen figanların

Ulaştığı son merci meçhuller meşhuru sen

         - Kayseri', 'SEN Serazat hislerimin gül kokulu nuru sen Müteellim günlerin bihemta huzuru sen Çirkeflerden bulaşan karanlıkları delen Sermedi hakikatin m...', ARRAY['Türk Edebiyatı','Şiir','Eymen Erdem Akça']::text[], 8.5, '{"poet":"Eymen Erdem Akça","poet_slug":"eymen-erdem-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sen-213-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen-2', 'sen-2-eymen-erdem-akca-xtxu5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kilitlenmiş kalplerin müstesna miftahı sen

Karanlık gecelerin beklenen sabahı sen

Hasaretle geçilen muzlim leyl ü neharın

Ahlarıyla alude devrinin misbahı sen

Sıkışan zamanlarda daralmış gönüllerin

Arşa doğru yükselen çevrilmeyen ahı sen

Şerha şerha yarılmış kanayan gönüllerin

Nurlar saçan güneşi yol gösteren mahı sen

Sana müptela ve meftun kan ağlayan gözlerin

Ebedlere uzanan yevmi intibahı sen

O mübarek ravzanda uyuyorsun Sevgili

Gönüllerin sultanı, sultanların şahı sen

Sana özlemle geçen günlerimi sayamam

Özlemimi sen anlat gönüller fettahı sen

Sana uzanan yollar sende bitirir menzil

O''na doğru yol alan ibadının rahı sen

Sen gibi gelmedi hiç gelmez daha Sevgili

Mustarip uşşakının süruru, ferahı sen

Şenlendir dünyamızı öylesine bunaldık

Çilelerin bittiği günlerin ferahı sen

Kapının kölesiyiz ey sultanlar Sultanı

O''na yalvarıp duran kulların eyvahı sen

Sensiz geçen günlerin çilesi ne çok ağır

Yıkılası dünyanın ziyası, evvahı sen

Sen gittin aramızdan huzur yüzü görmedik

Fecirleri gözlenen dünyanın felahı sen

Sana hasretle dolu gönüllere bir kez bak

Kararan dünyamızın kaybolan salahı sen

O''nu andıkça yanan gönüllerin rehberi

Kullarının içinde O''na en agahı sen

Ey mücella çehreli gül kokulu Sevgili

Varlığın virdi  '' La ilahe illallah ''ı sen

                     -Kayseri', 'Kilitlenmiş kalplerin müstesna miftahı sen Karanlık gecelerin beklenen sabahı sen Hasaretle geçilen muzlim leyl ü neharın Ahlarıyla alude de...', ARRAY['Türk Edebiyatı','Şiir','Eymen Erdem Akça']::text[], 8.5, '{"poet":"Eymen Erdem Akça","poet_slug":"eymen-erdem-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sen-2-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutamadım', 'unutamadim-ayhan-uygun-6dffi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğimden seni silemesemde

Aklımdan çıkaramasamda

Gözümdeki yaşları durdursamda

Seni hala unutamadım.

Unutmak için

Söz versemde kendime

Her seferinde sözümü tutamadım

Seni hala unutamadım.

Sevmek bir gün

Unutmak bir ömür

Bir ömür geçsede son sözüm

Ben seni hala unutamadım.', 'Yüreğimden seni silemesemde Aklımdan çıkaramasamda Gözümdeki yaşları durdursamda Seni hala unutamadım. Unutmak için Söz versemde kendime Her...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Uygun']::text[], 8.5, '{"poet":"Ayhan Uygun","poet_slug":"ayhan-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutamadim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üryan Elbise', 'uryan-elbise-abdulkadir-karaman-r8k9x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir çıplak bakıştı örtündüğüm elbise

çıkarmamak üzere giyindiğim! ..

Bir üryan yürek kaldı sızlayan içimde.

Bir yıldız kayması şavkıması 

kadar sürdü sevindiğim! ..

Gözlerim guruplar mahkumu, 

canım umutlar özürlüsüydü.

Olmak için, çok uğraştım, kendimde…

Bir rüyâ görüntüsü gözlerin

kâbuslarında her gece…

gül alevlerinin özlemiyle yandı yüreğim! ..

Ve gözlerim yanardağ lavları selinde üşüdü! ..

Beynimi aralıksız kundaklayan bilmece.

Mâlum, girdaplarında sözlerin, 

inlediğim ince ince.

Bu güneşin kaçıncı ihaneti geceye

ve gecenin kaçıncı yangısı? 

Ökselenmişken yıldızlar

sevgi siluetinde sevince.

Susamış bir yüreğin

- İşi zor yüreğin! ..

yeniden gölgede içi sızlar! ..

Değişmez zamanın döngüsü

ve gözyaşları akar kendiliğince! ..

Alevlenir yeniden

elemden dehlizlerde

Ümitlerine ıraksamış bir sevdânın çıngısı! ..

Sönerken ölü ışıklar gibi

direnci tükenmiş gözlerde! ..

27.01.03', 'Bir çıplak bakıştı örtündüğüm elbise çıkarmamak üzere giyindiğim! .. Bir üryan yürek kaldı sızlayan içimde. Bir yıldız kayması şavkıması  ka...', ARRAY['Türk Edebiyatı','Şiir','Abdulkadir Karaman']::text[], 8.5, '{"poet":"Abdulkadir Karaman","poet_slug":"abdulkadir-karaman","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/uryan-elbise-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle ve Sensiz', 'seninle-ve-sensiz-ayhan-uygun-h40jk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dört mevsim gibi yaşıyorum seni, 

Senle geçen günlerde, 

Yüreğim bir bahar misali

Bir çiçek gibi açıyor

Sensiz geçen günlerde

Bir yaprak gibi soluyor.

Seninle geçen günler, 

Sıcak bir yaz günü gibi

İçimi ısıtıyor.

Ama sensiz geçen günler, 

Soğuk bir kış günü gibi

Beni mahvediyor.', 'Dört mevsim gibi yaşıyorum seni,  Senle geçen günlerde,  Yüreğim bir bahar misali Bir çiçek gibi açıyor Sensiz geçen günlerde Bir yaprak gib...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Uygun']::text[], 8.5, '{"poet":"Ayhan Uygun","poet_slug":"ayhan-uygun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seninle-ve-sensiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeterki Sen Sev Beni!', 'yeterki-sen-sev-beni-sercan-sengel-rioqt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Anlatabilsem sana kendimi! 

Hep yalan, hep yanlış anlamasan.

Yüreğimde kan kokulu sevgiler olsa 

Kabuslarını saklasam rüyalarında.

Ekmek olsam, su olsam, 

Senin için bir ihtiyaç olsam, 

Bıkmasam, usanmasam, yorulmasam, 

Sonbaharda yapraklar gibi sararsam

Olsun! 

Ama hep yanımda ol! 

Beni hiç istemesen

Yalvarsam sana gecelerce, 

Öpsem, okşasam

Göz yaşlarımla ıslanmış resimlerini

Karşımda olsan elimi uzatsam sana

Dokunamasam! İçimde bir burukluk olsa! 

Olsun! 

Ama hep yüreğinde sıcak tut beni! 

Sana yürümek istesem

Buna gücüm kalmasa 

Düşsem, ağlasam, kalksam, 

Denesem tekrar

Her defasında başarısız olsam! 

Olsun! 

Yeterki sen sev beni! 

Bir yağmur damlası olsam 

Düşsem avuçlarına, incitmesem seni

Sadece ürpersen! 

Kurusam avuçlarında.yok olsam

Dönmesem tekrar hayata

Olsun! 

Yeterki sen unutma beni!', 'Anlatabilsem sana kendimi!  Hep yalan, hep yanlış anlamasan. Yüreğimde kan kokulu sevgiler olsa  Kabuslarını saklasam rüyalarında. Ekmek ols...', ARRAY['Türk Edebiyatı','Şiir','Sercan Şengel']::text[], 8.5, '{"poet":"Sercan Şengel","poet_slug":"sercan-sengel","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/yeterki-sen-sev-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-sercan-sengel-qjups', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen hasret olacaksın, 

Ben umut.

Bütün yanlızlık oyunlarını

Oynayacağız beraber.

Sen özleteceksin, 

Ben özleyeceğim.

Sen ağlatacaksın, 

Ben ağlayacağım, 

Gözlerimde iki damla yaş.

Sen olumsuzluklar prensesi

Bense kahraman! 

Yine bir oyun

Yeni bir sahne

Sen aldatıyorsun! 

Ben aldanıyorum!', 'Sen hasret olacaksın,  Ben umut. Bütün yanlızlık oyunlarını Oynayacağız beraber. Sen özleteceksin,  Ben özleyeceğim. Sen ağlatacaksın,  Ben ...', ARRAY['Türk Edebiyatı','Şiir','Sercan Şengel']::text[], 8.5, '{"poet":"Sercan Şengel","poet_slug":"sercan-sengel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/umut-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Sen', 'ya-sen-alibey-cakir-w9c72', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karanlığın içinde yoldaş olurken yine zalim gecelere 

Bedenim, 

Bir hasretlik türküsü söylemeye başlıyor dudaklarım. 

Alıp başımı gidesim geliyor aahhh 

Bilmediğim yerlere...hiç gitmediğim kentlere.. 

Gözlerim seni arıyor ufuklarda, 

Kısık gözlerim yıldızları arıyor tek tek. 

Bilipte bilmek istemediğim gerçeklerle yüzleşiyorum 

Kendi başıma. 

Sorguluyorum geçmişi 

Şimdi olamadığım yerlerde olabilmenin hasretiyle 

yanıyorum. 

Ya sen. 

Sen de yanıyormusun?', 'Karanlığın içinde yoldaş olurken yine zalim gecelere  Bedenim,  Bir hasretlik türküsü söylemeye başlıyor dudaklarım.  Alıp başımı gidesim ge...', ARRAY['Türk Edebiyatı','Şiir','Alibey Çakır']::text[], 8.5, '{"poet":"Alibey Çakır","poet_slug":"alibey-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ya-sen-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş Böcekleri', 'ates-bocekleri-alibey-cakir-2puga', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ateş Böcekleri''ne

Hiç bitmeyecekmiş gibi uzun bir gece var önümde

Gecenin yorgunluğu olabildiğine çöküyor insanın üzerine

Ve bir de gecenin sessizliği

Bir hüzün belirmeye başlıyor yüzümde

Hiç konuşmadan sessizliğe dalıyorum

Başka yerlere gidiyorum sessizlikle beraber

Kısa kısa süren yolculuklar yapıyorum

Bir hayalden, başka bir hayale...

Dalıp gidiyorum taa uzaklara

Olmadık hayaller kuruyorum

Taa ki Ateş Böcekleri ötünceye kadar...

Birden ötmeye başlayınca ürperiyorum istemesemde

Ateş Böcekleri; Yıkıyor hayallerimi...

Ateş Böcekleri; Geri getiriyor gerçekleri...

Ateş Böcekleri; Tıpkı Gerçekler gibi......', 'Ateş Böcekleri''ne Hiç bitmeyecekmiş gibi uzun bir gece var önümde Gecenin yorgunluğu olabildiğine çöküyor insanın üzerine Ve bir de gecenin ...', ARRAY['Türk Edebiyatı','Şiir','Alibey Çakır']::text[], 8.5, '{"poet":"Alibey Çakır","poet_slug":"alibey-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ates-bocekleri-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temsildir', 'temsildir-tebuk-zorakar-296d8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'törenin yeri, 

arşın sana ferşin bana durduğu bir

Şarkılar yetişir dallarında

güldüğünün. Kime söyledinse 

kelimeden yalın cümleni, yüklemi söyler oldu en sesli.

kaybedecek olan

dahi sen

o ve 

hepiniz ve de, gölgenin içindekiler

ancak bir ışığın verdiği

karanlığa ayak bastınız

hiçliğinkine değil.

Gölgedir sizin karanlığınız.

bir yanıldın, bin yanılgıya hamildi ki o

yanıldın sen dahi

yanılgın sen sahi, senin ben bildiğin yani

oysa ki sana benim tanımlarım çevreydi, 

ona ve.', 'törenin yeri,  arşın sana ferşin bana durduğu bir Şarkılar yetişir dallarında güldüğünün. Kime söyledinse  kelimeden yalın cümleni, yüklemi ...', ARRAY['Türk Edebiyatı','Şiir','Tebuk Zorakar']::text[], 8.5, '{"poet":"Tebuk Zorakar","poet_slug":"tebuk-zorakar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/temsildir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün', 'bugun-sedat-sozen-hpq1o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne mutlu gündür, bugün, 

Asık suratlara gülümsemenin, 

Nasırlaşmış kalplere saf bir sevginin, 

Çorak topraklara hoş bir çiçeğin, 

Geldiği gündür, bugün, 

Ne mutlu gündür, bugün, 

Karanlıklar içine bir nur yüzlünün, 

Sahte bakışlara bir yeşil gözlünün, 

Bu çirkin dünyaya güzeller güzelinin, 

Geldiği gündür, bugün, 

Doğum Günün Kutlu Olsun, 

Güzel Kız...', 'Ne mutlu gündür, bugün,  Asık suratlara gülümsemenin,  Nasırlaşmış kalplere saf bir sevginin,  Çorak topraklara hoş bir çiçeğin,  Geldiği gü...', ARRAY['Türk Edebiyatı','Şiir','Sedat Sözen']::text[], 8.5, '{"poet":"Sedat Sözen","poet_slug":"sedat-sozen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bugun-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mektup', 'mektup-sedat-sozen-l8k66', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Merhaba Güzel Kız, 

Çok uzun zaman oldu, 

Biliyorum, 

Umarım iyisindir, 

Bunu Allah''tan diliyorum.

Bu kadar zaman sonra, 

Nedir bu mektup diye sorma

Kızma, üzme bu garibi, 

Hatamı yüzüme vurma.

Sanma ki yeni hatırladım, 

Ben seni hiç unutmadım ki, 

İstedim, 

Aklımdan silmek istedim, 

Belki de biz diye bir şey kalmadığını, 

Artık böyle bir aşkın olmadığını, 

Bilmek istedim, 

Ama olmadı, 

Kalbime geçmedi sözüm.

Uzaktan uzağa, 

Hiç okumaya fırsat bulamadığın, 

Hangi duygularla yazıldığını bilemediğin, 

Şiirler yazdım.

Beni yanlış anlama sakın, 

Amacım hayatına karışmak değil, 

Güzel anılarla aklımdasın, 

Senden isteğim, yalnızca bunu bil, 

Mektubun gelse de sonu, 

Şiirlerin gelmeyecek, 

Her daim yazacağım, 

O güzel resmini, 

Başucuma asacağım, 

Bana gülmek haram olmuş, 

Bari senin gülsün yüzün, 

Allah''a emanet ol, 

Bu sana en son sözüm.', 'Merhaba Güzel Kız,  Çok uzun zaman oldu,  Biliyorum,  Umarım iyisindir,  Bunu Allah''tan diliyorum. Bu kadar zaman sonra,  Nedir bu mektup di...', ARRAY['Türk Edebiyatı','Şiir','Sedat Sözen']::text[], 8.5, '{"poet":"Sedat Sözen","poet_slug":"sedat-sozen","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/mektup-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Satılık Gönül', 'satilik-gonul-sedat-sozen-s45fq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nice sevda çukurlarında, 

Boğazımıza kadar çamura battık biz. 

O güzel yüze hasret, 

Elde resim, akılda sevdalı, 

Kapayıp gözleri, rüyaya yattık biz.

Bile bile, acıya inat, 

Bu sıradan hayatı ateşe attık biz.

Ve bu evvelden boş, 

Lakin şimdi taşan gönlü, 

Bir çift güzel göze, 

Bir alımlı bakışa, 

Bir hoş gülüşe sattık biz.', 'Nice sevda çukurlarında,  Boğazımıza kadar çamura battık biz.  O güzel yüze hasret,  Elde resim, akılda sevdalı,  Kapayıp gözleri, rüyaya ya...', ARRAY['Türk Edebiyatı','Şiir','Sedat Sözen']::text[], 8.5, '{"poet":"Sedat Sözen","poet_slug":"sedat-sozen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/satilik-gonul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Güzel Yaş', 'en-guzel-yas-tarkan-mert-c96j3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne ağıtlar okunmuş 

Ne sevgiler dökülmüş dudaklardan

Gün kıymeti bilememişiz dostum

Sevdiğin yanındaysa bir el atımlık

Ne güzel işte

Güzeli düşün sadece

Nice güneşler batmakta şu anda

Yaşamayı düşün

Bir ırmak gibi denize akan

Su gibi pırıl

Mutlu ol

En güzel yaştasın sen', 'Ne ağıtlar okunmuş  Ne sevgiler dökülmüş dudaklardan Gün kıymeti bilememişiz dostum Sevdiğin yanındaysa bir el atımlık Ne güzel işte Güzeli ...', ARRAY['Türk Edebiyatı','Şiir','Tarkan Mert']::text[], 8.5, '{"poet":"Tarkan Mert","poet_slug":"tarkan-mert","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/en-guzel-yas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel yaş', 'guzel-yas-tarkan-mert-4uqkk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne ağıtlar okunmuş 

Ne sevgiler dökülmüş dudaklardan

Gün kıymeti bilememişiz dostum

Sevdiğin yanındaysa bir el atımlık

Ne güzel işte

Güzeli düşün sadece

Nice güneşler batmakta şu anda

Yaşamayı düşün

Bir ırmak gibi denize akan

Su gibi pırıl

Mutlu ol

En güzel yaştasın sen', 'Ne ağıtlar okunmuş  Ne sevgiler dökülmüş dudaklardan Gün kıymeti bilememişiz dostum Sevdiğin yanındaysa bir el atımlık Ne güzel işte Güzeli ...', ARRAY['Türk Edebiyatı','Şiir','Tarkan Mert']::text[], 8.5, '{"poet":"Tarkan Mert","poet_slug":"tarkan-mert","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/guzel-yas-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zorlu Bekleyiş', 'zorlu-bekleyis-tuna-taslik-n6bwj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'seni unutmayı kolaymı sandın

 unutamadım

 her gece kendimle savaştım

 seni düşünmeyeceyim diye

 unutacağım diye

 sonra sen hep karanlıkların içinden gelirdin

 birdenbire

 habersızce

 sessizce

 git diyemezdim

 aslında kalda diyemezdim

 bilirdim

 o sen değildin hayalindi

 her gece gelir

 halime bakıp çekip giderdi

 arkasından dur diyemezdim gitme diyemezdim

 çekip`, çekip giderdi

 hani geldiği gibi

 birdenbire

 habersizce

 sessizce', 'seni unutmayı kolaymı sandın  unutamadım  her gece kendimle savaştım  seni düşünmeyeceyim diye  unutacağım diye  sonra sen hep karanlıkların...', ARRAY['Türk Edebiyatı','Şiir','Tuna Taşlık']::text[], 8.5, '{"poet":"Tuna Taşlık","poet_slug":"tuna-taslik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zorlu-bekleyis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Yüzlüme', 'gul-yuzlume-ahmet-sami-42em4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'iffetin bir pula gittiği yerde

ben seni ferhatın gözünde sevdim

sadakat sözünün bittiği yerde

ben seni mecnunun izinde sevdim

şehvetin sevdayı sildiği yerde

ihanetin yüze güldüğü yerde

sevginin doğmadan öldüğü yerde

ben seni veyselin sazında sevdim

tomurcuk güllerin solduğu yerde

nefretin hükümran olduğu yerde

umudun yığılıp kaldığı yerde

ben seni şefkatin dizinde sevdim

güzelin çirkine kandığı yerde

baykuşun çiçeğe konduğu yerde

her daim sevenin yandığı yerde

ben seni yüreğin közünde sevdim

şairin şiire küstüğü yerde

vuslat şarkısının sustuğu yerde

yalan rüzgarının estiği yerde

ben seni yunusun sözünde sevdim', 'iffetin bir pula gittiği yerde ben seni ferhatın gözünde sevdim sadakat sözünün bittiği yerde ben seni mecnunun izinde sevdim şehvetin sevda...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sami']::text[], 8.5, '{"poet":"Ahmet Sami","poet_slug":"ahmet-sami","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gul-yuzlume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bundan Böyle Ben Varım', 'bundan-boyle-ben-varim-bahar-temmuz-9zq9l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aç kapını ben geldim.

Bundan böyle ben varım, 

Bırakıp gitmedim hiç.

Uzun yıllar tükettim, 

Senden sevginden ayrı.

Sırtımda taşıdım hep

Yaşanmayan yılları.

Sen benim ilk aşkımdın

Son aşkım olacaksın.

Aç kapını ben geldim, 

Bundan böyle ben varım.

Hasretin yıllar boyu

Yiyip bitirdi beni

Ben hep yalan yaşadım

Gittiğim günden beri.

Seni tekrar bulmuşken, 

Yine yitirmek olmaz.

Aç kapını ben geldim, 

Bundan böyle ben varım.

Sen hep benimleydin ya

Ben senden uzaklar da

Başka hayatlar kurduk, 

Hep başka kucaklar da

Şimdi başladığım yere döndüm

Aç kapını ben geldim, 

Bundan böyle ben varım.', 'Aç kapını ben geldim. Bundan böyle ben varım,  Bırakıp gitmedim hiç. Uzun yıllar tükettim,  Senden sevginden ayrı. Sırtımda taşıdım hep Yaşa...', ARRAY['Türk Edebiyatı','Şiir','Bahar Temmuz']::text[], 8.5, '{"poet":"Bahar Temmuz","poet_slug":"bahar-temmuz","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bundan-boyle-ben-varim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüm', 'gulum-erkon-aydin-p6cxk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bana, seni sevdi deseler inanmam; sen söylemedin ki be gülüm

Sana hiç vazgeçmedi, taptı, uğruna savaştı deseler inanmazsın ki; hiç

sormadın be gülüm

Ben sensizliğin acısını çektim seni çok sevdim be gülüm

Sen bensizliği anlamadın, üzülmedin, süzülmedin bencilsin; 

Yaşamadın ki gülüm...

Aldattı deyip beni sana ispiyonladılarsa;  inan; 

Sensiz kalmak hele yalnız kalmak zor gülüm

Sevmişsen, ayrılmışsan ayrılık insana kor gülüm

Benim gözüm severken, mutluyken umutsuzca kör gülüm

Ayrılık acısı sevgili, tek taraflı çok zor be gülüm...

Allahtan istediği  senli hayattı gönlümün

Benim sana vereceğim bir canımdır be gülüm

Gülüm dedim anlamadın, içim oldu kördüğüm

Ya senli olacak hayat, ya da sensiz yaşanmayacak

Önemsiz sensiz ömrüm

Duyuyor musun? GÜLÜM...', 'Bana, seni sevdi deseler inanmam; sen söylemedin ki be gülüm Sana hiç vazgeçmedi, taptı, uğruna savaştı deseler inanmazsın ki; hiç sormadın ...', ARRAY['Türk Edebiyatı','Şiir','Erkon Aydın']::text[], 8.5, '{"poet":"Erkon Aydın","poet_slug":"erkon-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gulum-45-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhi', 'ruhi-ahmet-sami-f1pr5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gece yine sarhoşladı be ruhi

oysa eskiden

biz içer 

biz çakırkeyif dolaşırdık orta yerde

bilmiyorum

zaman mı bozuldu

şarabı mı bozdular

ne uyku tutuyor ne sızıyorum

bir kalecik''e

bir bağlarına 

bir salkımın karasına kızıyorum

gece yine sarhoşladı be ruhi

muhabbetin suyu çıktı iyice

olmadık yerden vuruyor

olmadık defterleri açıyor sayfa sayfa

bir ondan bahsediyor

bir daha ondan

''yok be'' diyorum 

''satıh üstü bir esintiydi geçti gitti tepelerin ardına''

inanmıyor be ruhi

ben kanıyorum ayık kafa kendime

gece kanmıyor

gece yine sarhoşladı be ruhi

yani izin versem beni sana takacak

utanmasa

adını hatırlasa rumen kızının

biraz da bir şeyler bilse

kırdıracak iki civanı birbirine

gece yine sarhoşladı be ruhi

abuk sabuk

ipe sapa gelmez laflar ediyor

hani beyaz rus kızına kağıt açtığımız gün

kupa kızı sana düştüğünde

ve hatta bütün kızlar bana küstüğünde 

sağlammış işçiliğin

üç gün açsak kağıdı nafileymiş

beyaz rus kızının karşımda durması bile

hileymiş

gece yine sarhoşladı be ruhi

sıkıysa çık diyor dışarı

sıkıysa boy göster alemde civanlığını bilelim

ne dersin be ruhi

yine mi gaza gelelim

yine omuzumuzda ceket

basık topuklularla sükutu mu bölelim

yok be ruhi

geceyi alttan alsam gerekir

usuldan sızmasını beklesem diyorum

amma olmuyor

dikleniyor musubet

o dikleniyor ben siniyorum

ne sustan anlıyor ne durdan

öyle üstüme üstüme geliyor ki

sabaha bir leş alırlar buradan

vurmasına vururum da inceden

ya sabır diyorum

ya sabır

kör şeytan git

git ulan 

git bul allahından

gece yine sarhoşladı be ruhi

bir camdan sarkıyor

bir ''dönülmez akşamın ufku''na takıyor kafayı

arada bir diz vuruyor zemine

neyleyim be ruhi

boynum bükük yemine

boynum bükük sarıp da içmediğim

o içme dedi diye

dişlerimin arasında çiğnediğim

tütün üstüne ettiğim yemine

boynum bükük be ruhi

yoksa ben gecenin çeker miyim kahrını

eyvallahım mı olur iki kadeh atmışa

bel bükülse yaş dayansa yetmişe

eyvallahım mı olur be ruhi

altını üstüne getirmez miyim bu şehrin

vakti dar etmez miyim geceye

ve  çıkıp karanlıklara bir daha dönmeksizin

içmez miyim düşene kadar ızdırabın suyundan

gece yine sarhoşladı be ruhi

gel al şunu başımdan

yoksa fitne fesat edecek

ya elimde kalacak

ya beni öldürecek

çok gecikme be ruhi

çok gecikme', 'gece yine sarhoşladı be ruhi oysa eskiden biz içer  biz çakırkeyif dolaşırdık orta yerde bilmiyorum zaman mı bozuldu şarabı mı bozdular ne u...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Sami']::text[], 8.5, '{"poet":"Ahmet Sami","poet_slug":"ahmet-sami","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/ruhi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizlik Korkusu', 'sensizlik-korkusu-erkon-aydin-e5hyw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Olurda bir ilkbahar günü

Senin aşkınla atan şu kalbim

Durursa eğer, 

Teneşir tahtasındaki çıplak vücuduma

Sıcak ellerinle bir kez dokun

Gelinlikten sonraki ilk bembeyaz giydirilen

Kefene sarılı vücudum

Yatılırsa musalla taşına

Okunursa ardımdan dualar

Sakın ağlama...

Seninle mutlu olduğum günleri düşün.

Benim seni, senin beni

Mutlu ettiğimiz günleri...

Ve sakın ağlama.

Bir kez daha kefende sarılı vücuduma dokun

Ve öp beni.

Toprak altına girmeden son kez öp beni.

Ve üstüme toprak atılmadan ilkbaharda açan bir çiçek at

Sonra düşün biran düşün

Beni nasıl mutlu ettiğini

              ve bana neler için kızdığını

Sakın ağlama.

Her sene öldüğüm gün bana gel

İnan sana olan SEVGİmle mezarımdaki o çiçek

Hep açacak.

Ve bana sadece

Seni seviyorum de

HALA SENİ SEVİYORUM.', 'Olurda bir ilkbahar günü Senin aşkınla atan şu kalbim Durursa eğer,  Teneşir tahtasındaki çıplak vücuduma Sıcak ellerinle bir kez dokun Geli...', ARRAY['Türk Edebiyatı','Şiir','Erkon Aydın']::text[], 8.5, '{"poet":"Erkon Aydın","poet_slug":"erkon-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sensizlik-korkusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tetik', 'tetik-cumhur-turan-yn9wr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir haber 

okyanusun kıyısından

dalgalar

dev gibi dalgalar

bir sahil şehrini yuttu

uykusunda

bir düşünce

binlerce çiçek açtı

bir sabah

gün doğumunda

hasadına koştu milyonlar

yalın ayak

misli görülmemiş sevinç çığlıklarında

bir ses

ya da bakış

kısacık

sevda türküsü yazdırdı

en olmaz anlarında yaşamın

bir mucit

bağırdı hamamında Eski Yunan''ın

elinde tas

üstü çıplak

fırladı sokağa

buldum buldum narasında

sırala

sıralayabildiğin kadar

o kadar çoktular

bir nokta

küçük

mini minicik

bir ayrıntı hepsinde

tetik

tetikleme

tetik üzre bir yığın çeşitleme

şifre sözcük

TETİK', 'bir haber  okyanusun kıyısından dalgalar dev gibi dalgalar bir sahil şehrini yuttu uykusunda bir düşünce binlerce çiçek açtı bir sabah gün d...', ARRAY['Türk Edebiyatı','Şiir','Cumhur Turan']::text[], 8.5, '{"poet":"Cumhur Turan","poet_slug":"cumhur-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/tetik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlayan Yağmur', 'aglayan-yagmur-erkon-aydin-60koi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen hic aglayan yagmur gordunmu? 

Sakin aglayam yagmur olurmu diye sorma

Dusun bir yagmur tanesini, 

buluttan kurtulmus, olabildigince ozgur ve mutlu, 

hayallerinde can verecegi fidanlar, 

guller, kelebekler, papatyalar

hic bir sey yapamazsa bile bir agacin

yapraklarinda dans etmenin mutlulugu.

Ya da dusun bir yagmur tanesini, 

tutunacak bir agac, bir dal bile yok

oksiyacak cimen bile

Dikene bile razi, diken bile yok

Ciplak bir yamacin tepesine dusmus, 

toza topraga karismis, nereye yuvarlandigi mechul

nehirlere, denizlere tasidigi topragami aglasin

yoksa buluttan ayrildigina.', 'Sen hic aglayan yagmur gordunmu?  Sakin aglayam yagmur olurmu diye sorma Dusun bir yagmur tanesini,  buluttan kurtulmus, olabildigince ozgur...', ARRAY['Türk Edebiyatı','Şiir','Erkon Aydın']::text[], 8.5, '{"poet":"Erkon Aydın","poet_slug":"erkon-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aglayan-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olur', 'ne-olur-erkon-aydin-xufyg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzak durma bana ne olur 

Sensiz olamıyorum 

İçimde öyle garip hisler varki 

Duyuyorum anlatamıyorum 

Anla beni ne olur

Boş yere değil bu göz yaşlarım 

Seni karşımda görünce 

Güzel gözlerine vurulmuşum 

Öyle bakıpta gülme ne olur 

Alay etme benimle

Sana en değerli varlığım olan 

Karşılıksız sevgimi sunuyorum 

Haydi uzat ellerini ne olur 

Bak karşılıksız yalvarıyorum', 'Uzak durma bana ne olur  Sensiz olamıyorum  İçimde öyle garip hisler varki  Duyuyorum anlatamıyorum  Anla beni ne olur Boş yere değil bu göz...', ARRAY['Türk Edebiyatı','Şiir','Erkon Aydın']::text[], 8.5, '{"poet":"Erkon Aydın","poet_slug":"erkon-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ne-olur-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Seveceksin', 'boyle-seveceksin-erkon-aydin-5m5co', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlık dostum olcaksa

Yanlızlık arkadaşımolacaksa 

Sana dualarla ellerim uzanacaksa 

Böyle seveceksen sevme beni

El içinde utançtan boğulacaksam 

Uzanmış ellerim boş kalacaksa 

Düşlerim hep hayal olacaksa 

Böyle seveceksen sevme beni

Düşeceksem dilden dile İteceksen elden ele

Binbir yalvarma yemin ile

Seveceksen sevme beni

Arzularım düğümlenecekse 

Hep masun bakacaksa gözlerim 

Boş kalacaksa sonsuza kadar ellerim

Böyle seveceksen SEVME beni', 'Karanlık dostum olcaksa Yanlızlık arkadaşımolacaksa  Sana dualarla ellerim uzanacaksa  Böyle seveceksen sevme beni El içinde utançtan boğula...', ARRAY['Türk Edebiyatı','Şiir','Erkon Aydın']::text[], 8.5, '{"poet":"Erkon Aydın","poet_slug":"erkon-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/boyle-seveceksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsterdim', 'i-sterdim-erkon-aydin-lipc2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yasama hevesim hiç kalmadi 

Temeli bozuk su dünyada 

Savurma gönlüme ask atesini 

Yanacak kadar zaten yanmisim 

Ekmek istemem su istemem 

Varsa bir yudum sevgini ver 

Saraylarda yasatmani istemem 

Beni gönlünde yasatman yeter 

Sevgi dalinda bir gül olmak isterdim 

Beni koklayip beni sarmani isterdim 

Hep seninle olup seninle yasamak 

Kollarinda ölüp gitmek isterdim 

En issiz gecelerde seni söylemek 

En derin mavilerde seni özlemek

En güzel sarkilarla seni süslemek 

Ressam olup seni çizmek isterdim', 'Yasama hevesim hiç kalmadi  Temeli bozuk su dünyada  Savurma gönlüme ask atesini  Yanacak kadar zaten yanmisim  Ekmek istemem su istemem  Va...', ARRAY['Türk Edebiyatı','Şiir','Erkon Aydın']::text[], 8.5, '{"poet":"Erkon Aydın","poet_slug":"erkon-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/isterdim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Olan Sevgimden', 'sana-olan-sevgimden-erkon-aydin-wipu5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Buz kesildi yüreğim sana olan sevgimden 

Titriyor bak bedenim sana olan sevgimden 

Hüzün bulvarında kalbim sana olan sevgimden 

Ama var olan bir şey var oda sana olan sevgim 

Benliğimde kaybettim sana olan sevgimden 

Kendimi unuttum sana olan sevgimden 

Unuttum güneşin doğuşunu sana olan sevgimden 

Ayın o hüzünlü karanlığını tanıdım sana olan sevgimden 

Şiir lerimi unuttum sana olan sevgimden 

Sözlerimi unuttum sana olan sevgimden 

Kısacası ben beni unuttum sana olan sevgimden 

Ama bir seni bir seni unutamadım 

Buda benim yer yüzündeki unumak istemediğim tek varlık', 'Buz kesildi yüreğim sana olan sevgimden  Titriyor bak bedenim sana olan sevgimden  Hüzün bulvarında kalbim sana olan sevgimden  Ama var olan...', ARRAY['Türk Edebiyatı','Şiir','Erkon Aydın']::text[], 8.5, '{"poet":"Erkon Aydın","poet_slug":"erkon-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sana-olan-sevgimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum Seni', 'bekliyorum-seni-erkon-aydin-lzz18', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gecenin karanlığında

istanbulda ayaz bir gece 

yine yanlızım yine üzgün 

bilmiyorum allahın takdiri 

yanlızlık benimle bütünleşti sanki 

bekliyorum iyi günleri 

gelecekten ümitle bahsediyorum

korkuyorum aslında 

gercekten yanlız kalmaktan 

ellerimde bir el olsun

kalbimde bir sevgi 

etkileyen bir aşk olsun 

ömürboyu süren bir mutluluk 

ümitleniyorum bir an geliyor

sonra hüzünleniyorum ansızın

yanlızlık üstüme çöküyor 

işte o an yaşamım duruyor ansızın

bilmiyorum korkuyorum 

bu durumdan hiç çıkmayacakmışım gibi 

ürperiyorum gecenin soğuğunda 

benim kaderimde hep varmış gibi 

bekliyorum artık 

kalbimi açtım sana 

gel artık bana 

sevgi denizinde birlikte boğulalım 

kim olduğunu biliyorum 

benimle ne olduğun önemli 

sen gel gönlümü paylaşayım 

sevgimin esiri ol gel artık', 'Gecenin karanlığında istanbulda ayaz bir gece  yine yanlızım yine üzgün  bilmiyorum allahın takdiri  yanlızlık benimle bütünleşti sanki  bek...', ARRAY['Türk Edebiyatı','Şiir','Erkon Aydın']::text[], 8.5, '{"poet":"Erkon Aydın","poet_slug":"erkon-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bekliyorum-seni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuk', 'cocuk-arzu-dincer-kkcx6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Pencereden süzülüp gelen gün ışığı, 

Nur gibi doğuyor gülümseyen uykusuna.

Pırıl pırıl sim gibi okşuyor melek yüzünü, 

Gözleri huzura açılacağını bilmenin güzelliğinde, 

Dudakları her an şen kahkahalara hazırlıklı...

Ne güzel uyuyorsun çocuk.

Ne güzel...

Pencerende muştuya hazır kuşlar bekliyor, 

Senin için ötmeye hazır horozlar...

Ağaçlar senin için semaya açılmış, 

Gökyüzünün perdelerini açıyor...

Senin için yağan yağmur, 

Gökkuşağını çıkarıp cebinden 

Süslüyor  rüyalarını..

Ne güzel uyuyorsun çocuk', 'Pencereden süzülüp gelen gün ışığı,  Nur gibi doğuyor gülümseyen uykusuna. Pırıl pırıl sim gibi okşuyor melek yüzünü,  Gözleri huzura açılac...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cocuk-34-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstenç', 'i-stenc-mehmet-tor-kq0yt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Karanlık uzaklıklaran 

aydınlık hatıralarmı

yüreğime şavkı vuran

kör etsek dünyayı

yaratsak kuralsızlığın krallarını

yrtsak karanlığı

içine düşsek samanyolu şavklarının

şu

      kısa

               yangın 

yaşamda

İstençler 

Bir hülya tınısımı

Düşmü gördüm? 

(Temmuz-2002) 

tınıcı nerde.', 'Karanlık uzaklıklaran  aydınlık hatıralarmı yüreğime şavkı vuran kör etsek dünyayı yaratsak kuralsızlığın krallarını yrtsak karanlığı içine ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tor']::text[], 8.5, '{"poet":"Mehmet Tor","poet_slug":"mehmet-tor","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istenc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizligin Sesi', 'sessizligin-sesi-c-hid-saf-8mb98', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sesinin yalnizliginda ipissiz sokaklara girerim

Uzakliginda senin, her sokak kalaba, bense tekim

Gözündeki tebessümü görmeseydim keske o zaman

Askinin inkisafi sarmis beni bir ufak lahza, bir an

Lebindeki kaynayan selalede islanmadan gittimdi 

Iraginda buldum ben, sende peydâ olan beni

Hayata zulmet icinde bakarken nûru yok sanirdim

Su dünyada askin tekmili var, bense bende yarim

Defnettigim hazzima mestûr derken ben yaninda

Kalbinin mahreminden fiskirdim yeniden dünyaya

Sensiz bir ân gecirmek ne müskildir, bilemezsin

Izdirabin dostlugunu bilirdim evvelden sensizligin

Bilmiyorum sen sen diye kavruldugum sen, sen misin? 

Cevab almak degil murat, sualleri bunlar hayâletin

Sensiz ben bir hazan rüzgarinda degisen bir renk

Gencligimin sokaginda dudaklarimda yâr bir pelesenk

Bir siroko, bir imbat saclarimi yelpazelendirmekte

Nedir bu duydugum uhrevî türküler tüm esintilerde

Bâzen bogazimda bir hickirik sesi oluyorsun hüznünle

Her sabah kalkinca binbir hafakanla gözümün önüne

Gelip duruyorsun konusmadan, bakiyor ve gülüyorsun

Tebessümünde dalgalar var, bense icinde yesil bir yosun

Istiyâkimi anlasam keske, ararim herdem nâmelerde

Kâh hüzzamda bulurum seni, kâh ferahfezâ bestelerde

Sensizligin hediyesi, bir uykusuzluk sarkisindayim

Magmum sokaklarda bir basima söyler söyler aglarim

Köpüklü dalgalarin icine dalmak isterim tutup elini

Ne beter bir hayattir ki ben sahillerde kimsenin kimsesi

Kalbimi serh edem, bir mizrabtir, calar kalbinin tanburunu

Gönlümün meclisinde gül yüzünün sevkinle ederim hûsû

Yalnizlik ah yalnizlik, uzlet nedir, yârsizlik ne demek

Yâre yâr muhabbeti, cesm-i pinarindan âb-i ask icmek gerek

Ey Mevlâ, yüzümdeki astara mukayyid ol lütûfen

Senden daha fazla sevmiyorum Onu, sevemiyorum hakiykaten

Gönlüm reklerinin alâimisemâsiyla yanip kavruluyor

Ask-i Eflatuniyyen beni o lahza benden aliyor

Muhabbet-i âlân ile yâ hayy, yârâni hubblandir artik

Nefreti, husumeti beden-i fânimizden izninle attik

Gönlümün tepelerinde gezen hayâletin handesini göreyim

Görmeden ölürsem yazik, gönlüm bensiz kalir, sensiz neyim

Sevk ile sebnemin yagmur zerreleri gurûbtan bulutlar

Sensin ey yâr, benim gurûbumun tûlû rengi ufuklar..

''Ver onu bana ya rab hayirla ve hakca

Onu senden az severim benden cokca''', 'Sesinin yalnizliginda ipissiz sokaklara girerim Uzakliginda senin, her sokak kalaba, bense tekim Gözündeki tebessümü görmeseydim keske o zam...', ARRAY['Türk Edebiyatı','Şiir','Câhid Safâ']::text[], 8.5, '{"poet":"Câhid Safâ","poet_slug":"c-hid-saf","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/sessizligin-sesi-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pelerinli Kadin', 'pelerinli-kadin-c-hid-saf-kt6wy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'köşeden bir kadın geçmişti karanlıkta sessiz ve sükûn o akşam

siyah pelerinini savurdu rüzgarda, rûhuna râm

gözlerinde  senelerin verdiği mâtem ve hüzün

bir romanin metni olan bu hüzünlü yüzün

içerisinde mahpus bir kalb atar her dem yeknesak

tüm cem''iyyet hükümlerini ardısıra bırakarak

sanki gecenin karanlığında nûrâni bir şelâle gizliydi

birçok kederin güzelliğini saklardı o derin gözleri

hayata ve iştiyâk duyduğu her hissî ve kalbî delâletlere

güneşin geceye diktiği duvar gibi çekti seddi tüm hıyanetlere

ne fırtınalar ne arz alâmetleri akar baktığı yere kusarak

âfetler peydâh olur, zelzeleler, şimşekler iner hep susarak

her adımında firarî bir isyan çığlığı mevcuddu

firardan sonraki insanî değil afedî bir vücuddu

suratına çarpan her yağmur zerresinde bir adım atarak cesaretle

adım adım tükenen zamanın buğusundan kaçıyordu sükûnetle

rûhî ve cem''iyyet mes’elelerini fikretmiş melekesinde bu kadın

bir kadın şûhaniyyetiyle değil, peygamber ismetindeydi zamanın

caddelerin ve sokakların tâklı, ışıklı manzaralarında

servilerle dolu mezarlık karanlığını hayâl ediyordu bu arada

cem’iyyetin idraksiz reddettiği aşkın ve iştiyâkın vahdetini

birbirlerine sûitefehhüm ile merbût, idraksız tesniye, zannederlerdi

tüm rûhî hercümerçlere isyan ile yürüyordu caddede

Mecnûn''u beklemeden, Mecnûn''a gidiyordu tüm iffetiyle

cem''iyyetin hasretle beklediği, cehl ile unuttuğu bu kelimeyi

ağzını doldurarak haykırmak istiyordu, ifşa ederek kendini

nedir bu memâta gark olmuş iffet kelimesindeki sır

maatteessüf,  rûh cem''iyyete, cem''iyyet nâmusa sağır

ferdenferd senelerdeberi mâlum feryâd-ı fîganı fehmederdi

değirmenlere saldıran tecessüsünü ilan ise vazifesiydi

ziyân oluşunu görmesi, müennes köleliğinin sırrında saklar

ne emeller ki ziyâsından vazgeçip, hain maksatları paklar

II

ebeveyninin elinde oyuncakken tüm kader ve kaza

siyah pelerinini savurduğu o meş''um sokakta

reşitliğin verdiği mâkus hürlüğü hissetti o ân

ne büyük bir mahkûmiyyet bu, ne büyük bir zan

nice ademoğlu, hür sanırlarken kendilerini ilelebed

farkına varamadılar, bu hürriyyet değil, mahkûmiyyet müebbed

bir rûhun üç buudda mahpus sıkışıp daraldığını bilselerdi

âk-u pâk rahmetin görürlerdi üzerlerine yağdırdığı çirkefi

pis ve âdi sancıyı anlarlardı, ne denli dehşet, ne denli vahşet

rûhu bir fırsatta bırakmak isterlerdi, bedene çekip set

tüm tahayyüllerin önüne set çeken o korkunç hakîkat

görünende değil de rüyâdaki hakîkattedir şatafat

her adımında anlayamadığı bir hürriyyet ile içi doluyordu

neydi bu hürriyyetten kaçarken bulduğu hürriyyet diye soruyordu

köleliğin verdiği efendilik hissiyle kendini sanırken efendi

efendilikteki köleliğin haşmetiyle köleliğe rücû etti

ne efendilik ne de kölelik taleb etmişti kimseden o oysa

zindanda hür olmak istiyordu, bir âmânın elinde âsâ

ruhun her türlü şahsiyyetsiz sergüzeştinden gına gelmişti

nûr ile doldurmayı arzu ederken katran ile doldu hep sepeti

bir an tereddüd geçirdi, var mıyım ben, yok mu yoksa

kaderin çirkef oyunu mu bu, bana mı her cilve revâ

ben de beşerim, diyordu, hudutsuz ruhun lisaniyle

hudutları, setleri kim çekti bu zifirî gecede

ne zaman ruhumla sükût etsem sırtımdan bıçaklar beni

çıkar beni buradan, sensin benim kukla gardiyanım derdi

muhabbet ile ruhun cem''iyyette râbıtasına baktım hayatım boyunca

rûhumu cem''iyyetten ağyan eden bedenimi gördüm soyununca

bir kin ile baktım ben ayaktan başıma kadar bana

cem''iyyetin ferdini gördüm, ferdimin cem''ini bulunca aynada

siyah pelerinimi giydimdi işte o ân, dedi

çıplak geldi bu dünyaya, çıplak gideceğini zannetti

bu zanla mutâbık olduklarını görerek o zaman

rûhuyla ayrılacaktı o gece, şimşek, fırtına, boran

tüm cem''iyyetten bîhaber, Hakk''ın rûhiyle cem'' olsun talebi

o gece tabiatın tüm âfetlerine karşı galebe ilan etti

köşeden siyah peleriniyle geçtiği o akşam çeşminde

bir damla kırmızı şebnem belirmişti, bedeninin hükmünde

son telakkisiydi bu iffetli rûhun cem''iyyete mâtem tutturan kadının

cem''iyyet haber alınca hercümerç oldu bu izzetinefis kurbanının

yok olduğunu duyduklarında terennûm ettiler hep bir ağızdan matemle

o diri cerîhadan kan yağdı tüm gece arştan arza metânetle 

...

bazısı fehmeder, ne kadar sürç-i lîsan olsa da, iste o âkil

kimi de şahsını âkil zanneder, işte  o da câhil...', 'köşeden bir kadın geçmişti karanlıkta sessiz ve sükûn o akşam siyah pelerinini savurdu rüzgarda, rûhuna râm gözlerinde  senelerin verdiği mâ...', ARRAY['Türk Edebiyatı','Şiir','Câhid Safâ']::text[], 8.5, '{"poet":"Câhid Safâ","poet_slug":"c-hid-saf","theme":"Türk Şiiri","is_hero":false,"total_lines":78,"source_url":"https://www.antoloji.com/pelerinli-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İpilti', 'i-pilti-mehmet-tor-ogr8m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yürek olmuş bir bilinmez

tanısı olmayan 

kuş kanadı ipiltisi

rüzğar olmuş kanadına

kızılcık düşleri

salınır durur

yaşamın kuytu umarsızlığıyla

Ah! sonu olmayan sığıntı yürek

kızıl atların toynaklarında

örs olmuş topraklardan

baharla fışkıran çimen kokusumu; 

seni rüzğarında savuran

Yoksa

ekin başaklarında esen bahar yelimi

salıntını kırnaplayan

Neden ipildersin? 

Neden? 

(Temmuz_2002)', 'Yürek olmuş bir bilinmez tanısı olmayan  kuş kanadı ipiltisi rüzğar olmuş kanadına kızılcık düşleri salınır durur yaşamın kuytu umarsızlığıy...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tor']::text[], 8.5, '{"poet":"Mehmet Tor","poet_slug":"mehmet-tor","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ipilti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırılma noktası', 'kirilma-noktasi-mehmet-tor-r8svn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Görecekliğimin tozlaştığı bir an

güneşin ısıttığı 

kızgın kumların ısısını

çalmaya başlayan

lacivert karanlıklarda

Ak köpüklü dalga kırılmalarının 

karşısında diz çöküp

kapatsam gözlerimi

Torosların dalgalı dalarından

bir kekik kokusu duymsarım

Bir yanda dağ gibi dalgalar 

bir yanda dalga gibi dağlar

yaşam

kırılmalar ve kıvrımlarla

(eylül 2002)', 'Görecekliğimin tozlaştığı bir an güneşin ısıttığı  kızgın kumların ısısını çalmaya başlayan lacivert karanlıklarda Ak köpüklü dalga kırılmal...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tor']::text[], 8.5, '{"poet":"Mehmet Tor","poet_slug":"mehmet-tor","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kirilma-noktasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş', 'dus-mehmet-tor-jqicy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çıksam dalgalı dağlara

haykırsam düşümü

yakın

         uzaklardan

                            tutan

olurmu? 

Acaba', 'Çıksam dalgalı dağlara haykırsam düşümü yakın          uzaklardan                             tutan olurmu?  Acaba...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Tor']::text[], 8.5, '{"poet":"Mehmet Tor","poet_slug":"mehmet-tor","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/dus-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçma', 'sacma-kutyan-cire-bfqoh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Selam olsun! 

Gidiyorum bu dünyadan

Arkama bile bakmadan

Bakacak ne var ki zaten

Benim için üzülecek ya da

Kayboluşuma sevinecek.

Sahi ölmek kaybolmak mıdır? 

Sonsuzluk diyarında.

Kaybolmak iyidir

Hesap soranın olmaz

Hesap vereninde

Ama 

Birde kaybolmamışsam

Ozaman ölmüşüm demektir

Saçmaladığım dünyada

Tıpkı şimdi olduğu gibi', 'Selam olsun!  Gidiyorum bu dünyadan Arkama bile bakmadan Bakacak ne var ki zaten Benim için üzülecek ya da Kayboluşuma sevinecek. Sahi ölmek...', ARRAY['Türk Edebiyatı','Şiir','Kutyan Çire']::text[], 8.5, '{"poet":"Kutyan Çire","poet_slug":"kutyan-cire","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sacma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamana Bıraktım', 'zamana-biraktim-kaan-karatac-bsee9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saçlarını okşadığım ellerim 

Titrek bu günlerde, 

Sana sarıldığım kollarım, 

Dermansız. 

Ölüyor vücudum Sensizliğin ertesinde 

Duygularım kurşun yemiş 

Delik Deşik 

Yıllar nasılda akıp gitti 

Duruldum, Yaşlandım artık 

Bıraktım duygularımın adaletine kendimi 

sorguyu, cezayı zamana bıraktım 

Hasretin dinmiyor, 

Sevda yollarında yalnızım. 

Bir bebe misali, 

Unutkanım, Kararsızım 

Salıncakları görüyorum 

Bebekliğim mi, gençliğim mi? 

Umutlarımı arıyorum 

Yalan mıydı, sevdiğim mi? 

Saçlarım Bembeyaz 

Başını yasladığın göğsüm 

Daralgan bugün. 

Aklım anılarda kalmış 

Yüreğim alıngan bu gün 

Ahh Kahrolası yıllar 

Nasıl da akıp gittin 

Kavuşmak sevdasına 

günleri bir bir çekerken 

Bizi hasrete tutsak ettin 

Bıraktım, Bıraktım 

Duygularımın adaletine kendimi 

Sorguyu, cezayı Zamana bıraktım.', 'Saçlarını okşadığım ellerim  Titrek bu günlerde,  Sana sarıldığım kollarım,  Dermansız.  Ölüyor vücudum Sensizliğin ertesinde  Duygularım ku...', ARRAY['Türk Edebiyatı','Şiir','Kaan Karataç']::text[], 8.5, '{"poet":"Kaan Karataç","poet_slug":"kaan-karatac","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/zamana-biraktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Söz', 'son-soz-ender-altinisik-95szc', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Puslu bir gecenin içinden

bak gökyüzüne

uzat ellerini hayallerine

Her lacivert gecenin ardında

aydınılık bir yarın vardır

ve her yarın 

bizi günahlarımızdan arındırır

Gayret et yeter ki; çabala

mutlaka ulaşacaksın 

o güneşli sabaha

Ve ulaştığında yarına

dön bir bak içinden geçtiğin karanlığa

gecenin konukları 

yani ay ve yıldızlar

sana gülümsüyor olacaklar

ve en çok

o gece parlayacaklar', 'Puslu bir gecenin içinden bak gökyüzüne uzat ellerini hayallerine Her lacivert gecenin ardında aydınılık bir yarın vardır ve her yarın  bizi...', ARRAY['Türk Edebiyatı','Şiir','Ender Altınışık']::text[], 8.5, '{"poet":"Ender Altınışık","poet_slug":"ender-altinisik","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/son-soz-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Uzak', 'benden-uzak-yusuf-kaya-qn616', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şimdi başka birini seviyormuşsun, 

Bunu başkasından öğrendim, hayırlı olsun

Gündüzün gecen mutlu 

Geleceğin umutla dolsun 

Hadi yolun açık ben den uzak olsun.', 'Şimdi başka birini seviyormuşsun,  Bunu başkasından öğrendim, hayırlı olsun Gündüzün gecen mutlu  Geleceğin umutla dolsun  Hadi yolun açık b...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kaya']::text[], 8.5, '{"poet":"Yusuf Kaya","poet_slug":"yusuf-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/benden-uzak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Kalbim', 'kirik-kalbim-yusuf-kaya-0y49o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölüm çare olsa çoktan ölürdüm

Mezarıma gelsen gözyaşını isterim

Onu bunu bilmem yine de severim 

Başka aşk istemem seni isterim ben

Mekanım cennet olsa huriler istemem 

İlle de sen derim, başka birini bilmem

İstemem para pul, ille de sen derim

Bu gün öleceğimi ve öleceğini bilsem yinede seni severim seni ben 

Sen den kalan hatıra bir kırık kalbim, bir kırık aynan', 'Ölüm çare olsa çoktan ölürdüm Mezarıma gelsen gözyaşını isterim Onu bunu bilmem yine de severim  Başka aşk istemem seni isterim ben Mekanım ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kaya']::text[], 8.5, '{"poet":"Yusuf Kaya","poet_slug":"yusuf-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kirik-kalbim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-mahmut-sacli-t4ieq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tütün ektim çiçeksiz saksıya, 

Hüzün ufaladım avuçlarıma

Birsürü...

Kaç kere öldüm, 

Kaç kere doğdum

Kimbilir? 

Yamyassı uzandım toprağa, 

Yamyassı dünyaya güldüm.

Fuşya yanağından doyasıya, 

Öptüm öptüm...', 'Tütün ektim çiçeksiz saksıya,  Hüzün ufaladım avuçlarıma Birsürü... Kaç kere öldüm,  Kaç kere doğdum Kimbilir?  Yamyassı uzandım toprağa,  Y...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Saçlı']::text[], 8.5, '{"poet":"Mahmut Saçlı","poet_slug":"mahmut-sacli","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yoksun-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhtacım Sana', 'muhtacim-sana-yusuf-kaya-aiite', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ansızın böyle aşk olur mu söyle

Birden  kapı çalıp girdin kalbime

Davetsiz misafir misali 

Hazır olmadan aşk olur mu söyle

Aklım almıyor bu sevdayı

Nasıl tutuldum ben sana

Ne arıyor, ne soruyorsun 

Halim nedir bilmiyorsun

Sensiz geçen gündüz gece istemiyorum ben

Bir su gibi, bir güneş gibi, bir gece gibi muhtacım sana.', 'Ansızın böyle aşk olur mu söyle Birden  kapı çalıp girdin kalbime Davetsiz misafir misali  Hazır olmadan aşk olur mu söyle Aklım almıyor bu ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kaya']::text[], 8.5, '{"poet":"Yusuf Kaya","poet_slug":"yusuf-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/muhtacim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden', 'yeniden-yusuf-kaya-1v3x7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yeniden seve bilir miyim

Sana gönül vere bilir miyim

Bilmiyorum

Gidiyorum uzaklardan uzaklara

Yeniden başlamalımı bu sevdanın ateşi

Yakıyor ruhumu tenimi bedenimi.', 'Yeniden seve bilir miyim Sana gönül vere bilir miyim Bilmiyorum Gidiyorum uzaklardan uzaklara Yeniden başlamalımı bu sevdanın ateşi Yakıyor ...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kaya']::text[], 8.5, '{"poet":"Yusuf Kaya","poet_slug":"yusuf-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yeniden-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Miş''li Geçmiş Şiir', 'mis-li-gecmis-siir-sarper-savaskul-zwoa3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şairler şairlerden esinlenirlermiş

Diğer sanatçılar gibi kendi hayatlarını bestelerlermiş

Kanadı kırık, zemheride kıvranan kargalar

Dört yapraklı yonca bulan zengin olurmuş

Evvel zaman içinde kalbur kalbur saman içinde iğne ararlarmış

Büyü kitabını kaybeden yalancılar

Devrilmiş bir hayattan artakalan tek şey devrik cümlelermiş

Onlar söylenmesi gereken duygularmış

Bazı şairler bu duyguları hayatları boyunca beklerlermiş

Bu devrik cümlelerde hayatın anlamını bulurlarmış

Sonrada kimseye söyleyemeden ölürlermiş

Devrik cümleler ardından koşan atlılarmış

Benim rüyama giren vızıltı yazdan kalmaymış

Yazdan kalma bir sinekmiş

Sinekler karınca yemezmiş

Yem toplayan karıncaların üzerlerinden atlılar geçermiş

Atlar karıncalanırlarmış

Sonraları atlı karınca diye bir şey çıkmış

Karıncalar masumiyeti atlara yüklemiş

Ve bütün masum duyguları çalıp kaçmış

Ardında yalan sevdadan başka hiçbir şey bırakmamış

Masumiyet yok olmuş

Ama karıncaları sevmeyen birkaç atlı varmış

Onlar masumiyetlerini saklamış

Atların o sert bakışlı efendileri şairmiş

Masumiyet yanlıştır belki en güzel duyguları belirtmeye

Unutmamalıdır ki insan, güzellik masumiyetle başlarmış...

(20/03/2001)', 'Şairler şairlerden esinlenirlermiş Diğer sanatçılar gibi kendi hayatlarını bestelerlermiş Kanadı kırık, zemheride kıvranan kargalar Dört yap...', ARRAY['Türk Edebiyatı','Şiir','Sarper Savaşkul']::text[], 8.5, '{"poet":"Sarper Savaşkul","poet_slug":"sarper-savaskul","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/mis-li-gecmis-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şairin Gözüyle', 'bir-sairin-gozuyle-malkocoglu-sivasli-u7fsd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir şairin gözüyle bakmak istedim sana; 

Varlığınla gark olmak sahilde deniz gibi...

Yeryüzünde bulunmak seninle hep yanyana, 

Yokluğundan ürpermek soluk bir beniz gibi...

(ankara/1993)

 Malkoçoğlu (sivaslı)', 'Bir şairin gözüyle bakmak istedim sana;  Varlığınla gark olmak sahilde deniz gibi... Yeryüzünde bulunmak seninle hep yanyana,  Yokluğundan ü...', ARRAY['Türk Edebiyatı','Şiir','Malkoçoğlu (sivaslı)']::text[], 8.5, '{"poet":"Malkoçoğlu (sivaslı)","poet_slug":"malkocoglu-sivasli","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-sairin-gozuyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanıdık Yağmurlar', 'tanidik-yagmurlar-canan-demir-t72bc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir eylül sabahı, 

Benden sevgimizden kaçtın.

Hadi beni sevmedin bunu 

İstanbul’a nasıl yaptın? 

Gittin, kayıtsız kalamadı bu şehir hasretine, 

Bu yıl İstanbul’da sonbaharı sen başlattın..

Gidişin öylesine olası, öylesine beklenmedik, 

Terkedilmişliği O’na ilk sen yaşattın! ..

Hasret çeken tek şehir İstanbul’dur demiştik, 

Her yağmurda ağladığına sen de tanıktın..

..

İçin başka belde rüzgarıyla dolduğu anda, 

Şehrimde tanıdık yağmurlar başladı..

Hasretini pay etti, yükledi damlalara, 

İstanbul gidişinle bin yaş daha yaşlandı..

..

Bu giden son değil, son değil bu şehre kıyan, 

Yazık ki bu kez sensin İstanbul’u ağlatan..

Bi düşünsene; koca bir şehir ağlıyor yokluğuna! 

Bu eylül sabahı, 

Yağmur senin yüzünden yağıyor İstanbul’da..', 'Bir eylül sabahı,  Benden sevgimizden kaçtın. Hadi beni sevmedin bunu  İstanbul’a nasıl yaptın?  Gittin, kayıtsız kalamadı bu şehir hasretin...', ARRAY['Türk Edebiyatı','Şiir','Canan Demir']::text[], 8.5, '{"poet":"Canan Demir","poet_slug":"canan-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/tanidik-yagmurlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Kırgınlığım Sana', 'i-lk-kirginligim-sana-canan-demir-8vynj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ilk kırgınlığım sana

ve her şey bu kırgınlığın bi uzantısı biliyorum

ne zaman gücensem bi simaya

ben aslında bi kez daha sana güceniyorum

yine de düşman olamıyorum hatırana

sevgin cemre cemre büyüyor içimde

engel olamıyorum..', 'ilk kırgınlığım sana ve her şey bu kırgınlığın bi uzantısı biliyorum ne zaman gücensem bi simaya ben aslında bi kez daha sana güceniyorum yi...', ARRAY['Türk Edebiyatı','Şiir','Canan Demir']::text[], 8.5, '{"poet":"Canan Demir","poet_slug":"canan-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ilk-kirginligim-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aldanma', 'aldanma-canan-demir-xaoy6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hasret fon olur insanın hayatına, 

Bir kez düşerse yüreğine, kurtulamazsın bir daha..

...

Gün gelir sular durulur

Bir sessizliktir bir huzurdur çöker etrafa.

(Sana dost tavsiyesi “O demlere aldanma!) 

Bil ki  yakındır kabaracaktır gözyaşı kuyusu

Tam çekilecekken gözlerindeki gölgeler, 

Tam şekillenecekken yüzünde bir tebessüm, 

Yine bulanıverir yüreğinin özsuyu..

..

Ve anlarsın ki; 

Hiç eksilmemiş acın; 

Sadece hal değiştirmiş amansız sancın..', 'Hasret fon olur insanın hayatına,  Bir kez düşerse yüreğine, kurtulamazsın bir daha.. ... Gün gelir sular durulur Bir sessizliktir bir huzur...', ARRAY['Türk Edebiyatı','Şiir','Canan Demir']::text[], 8.5, '{"poet":"Canan Demir","poet_slug":"canan-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/aldanma-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdaya', 'sevdaya-bunyamin-cakil-q9uag', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akarsuların çarptığı yalçın kayalar gibi 

göğüs gerdim sevdaya 

önce bir sel vurdu kurdugum engele 

sonra yalnız 

gönül verdim sevdaya 

alacakaranlıkta tek başıma yürüdüm uçurumlarda 

birden irkilip 

ipekten halılar serdim sevdaya 

kimsesiz gökyüzünde uçurdum uçurtmamı 

kimseler görmeyince 

salıverdim sevdaya 

kaybettim benligimi 

geçtim aynalar karşısına 

gördüm yalansız kendimi 

bu halimle tıpatıp 

benzedim ben sevdaya 

kursunların arasında kaldı 

hiçkimse acımadan 

kursuna dızdı seni 

ama ben bu cansız bedeni 

siper ettim sevdaya 

herkes kovdu yurdundan 

kimse almadı seni 

kapımı tıklatınca 

kalbimde bir sırça köşk 

bina ettim sevdaya 

ellerimi ovuşturdum 

ısınmak için 

seni bir köşede donmuş görünce 

dayanamadım 

içimdeki kor ateşi 

döküverdim sevdaya 

bir çöle kaydı ayaklarım 

her vaha bir serab çıktı

susuzluktan ölecekken 

kanıverdim sevdaya 

bitmek bilmez kaynaklardan yudumladım sevdayı 

ardı sıra daglar boyu 

izledim seni 

bir derenin karşısında görünce 

bitiverdim sevdaya 

kelimeler bir bir 

heceler hazır kıta 

hiçbirsey düsünmezken 

senin sevdan hakkında 

hüzün dolu bir şiir yaziverdim sevdaya 

dag baslarında 

sarp kayalarda biten dag çiçekleri 

birde gönül bahçemde dogan kardelenleri 

gözümü kırpmadan 

hepsini deriverdim sevdaya 

duygularim vardı 

saklayıp gizledigim 

kimseye demedigim 

demekten çekindigim 

diyemezsin deyince 

deyiverdim sevdaya 

kapadım gözlerimi 

gömüldüm karanlığa 

farkedince aydınlıgı 

kendimi gömüverdim sevdaya 

ve dilim tutuldu seni görünce 

yüregim titredi 

ugruna kimse ölmeyince 

ölüverdim sevdaya 

birde baktım ki 

tüm insanlar ölmüs 

topraklar selam durmus 

kalan son gücümle 

elimdeki ab-ı hayatı 

serpiverdim sevdaya..', 'Akarsuların çarptığı yalçın kayalar gibi  göğüs gerdim sevdaya  önce bir sel vurdu kurdugum engele  sonra yalnız  gönül verdim sevdaya  alac...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Çakıl']::text[], 8.5, '{"poet":"Bünyamin Çakıl","poet_slug":"bunyamin-cakil","theme":"Türk Şiiri","is_hero":false,"total_lines":71,"source_url":"https://www.antoloji.com/sevdaya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gün', 'o-gun-bunyamin-cakil-8m5d8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gün dogdu, günes açti, birgece sona erdi 

karanligin elleri gözlerimde eridi 

hayatin agirligi gövdemi yere serdi 

adami batirmakmis batakliklarin derdi 

geceleri düsünürken yamaçlarin ardini 

bir cennet hurisini, birde dünya kadini 

sana eslik edecek bir dost aradigini 

sormazlarki bilsinler, bilseler sorarlardi 

duygularim saklidir bulamaz kimse onu 

gözyaslarim akarsa, üzülmüs oldugumu 

anlamazsin bulari, ben gizlice aglarim 

yürek merdivenimi gözlerime dayarim', 'gün dogdu, günes açti, birgece sona erdi  karanligin elleri gözlerimde eridi  hayatin agirligi gövdemi yere serdi  adami batirmakmis batakli...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Çakıl']::text[], 8.5, '{"poet":"Bünyamin Çakıl","poet_slug":"bunyamin-cakil","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/o-gun-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'At Sırtında', 'at-sirtinda-reha-basogul-6bc31', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'At sırtında 

         kaçırırsın

alnına ak balık düşmüş kızını

         bir ıslıkla 

Rüzgar Tanrıçalarından

         edersin al aşağı

sürgün rüyalarını

         eteklerinde taş taşıyan

bir bilgenin öpülecek

         sakalı gibi

karlı Kaf Dağı''ndan

         kaparsın ruhunun sancağını

gökyüzünün sisli ummanlarına çıkarak, çırılçıplak

         fırlarsın yayından 

sarsmak için unutulmuş renklerin yamaçlarını

         çiğnersin humuslu tarlalarında

çehrene sıçramış çamurlu toprağı

         kurumuş akıncıbeyi unvanınla

dalarsın Kızılçam Ormanlarına

         kışlatılmış arı kovanları arasından

koşarsın dörtnala 

         eline dolaşmış testeremsi yelelerin ucuyla

döndürünce kafasını

         ayaklarına kapanacak menekşe alacası

eğilerek selamını alır

         gözüne kaçan mor boyası

serserilik eder bir atmacayla 

         gri gölün kenarında

yarışırsın atbaşı 

         kulağında havayı mahmuzlayan kanatların marşı

sıcaktır daha 

         kaçışan ördeklerin sudaki perdeli ayak damgası

kadife renkli gölgesiyle 

         bacası tüten almaşık duvarlı dağ evine karşı

ciğerinde birikir

         kekremsi havası

çıkartır seni baştan

         kokan balığın bir anlık alın yazısı rüyası 

At Sırtında', 'At sırtında           kaçırırsın alnına ak balık düşmüş kızını          bir ıslıkla  Rüzgar Tanrıçalarından          edersin al aşağı sürgün...', ARRAY['Türk Edebiyatı','Şiir','Reha Başoğul']::text[], 8.5, '{"poet":"Reha Başoğul","poet_slug":"reha-basogul","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/at-sirtinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olamaz', 'olamaz-zafer-keskin-eeqwr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neydiki gunahim bu son eserde, 

Nerede ugruna oldugum nerde, 

Omrunu sorgusuz onune serde, 

Odulu yalnizlik olsun, olurmu? 

Bahtina yazsinda kara yaziyi, 

Yanina biraksin derdi, siziyi, 

Inkar edip gitsin koca maziyi, 

Gonlune hasreti dussun, olurmu? 

Gidisiyle beni cikmaza soktu, 

Beynime zamansiz bir mermi sikti, 

Zor ile yaptigim mabedi yikti, 

Hesabi gonlume ciksin olurmu? 

Bir sevdag yolunda yillarca yandim, 

Ugrumada sevecek  olecek sandim, 

Umitler hayaller bosmus anladim, 

Alayci tavirla baksin olurmu?', 'Neydiki gunahim bu son eserde,  Nerede ugruna oldugum nerde,  Omrunu sorgusuz onune serde,  Odulu yalnizlik olsun, olurmu?  Bahtina yazsinda...', ARRAY['Türk Edebiyatı','Şiir','Zafer Keskin']::text[], 8.5, '{"poet":"Zafer Keskin","poet_slug":"zafer-keskin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olamaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara', 'ankara-firat-utkan-7yix4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ankara''da bakır olsaydım

İşlenmemiş bir güğüm

Ulus''ta bir dükkanda

Köhnemiş eski bir dükkanda

Pirinç Han''ın yanıbaşında dursaydım

Bir değersiz antika

Olsaydım

Belki beni Ankara bilirdin

Sen Ankara aşığısın

Keşke beni bilseydin.', 'Ankara''da bakır olsaydım İşlenmemiş bir güğüm Ulus''ta bir dükkanda Köhnemiş eski bir dükkanda Pirinç Han''ın yanıbaşında dursaydım Bir değers...', ARRAY['Türk Edebiyatı','Şiir','Fırat Utkan']::text[], 8.5, '{"poet":"Fırat Utkan","poet_slug":"firat-utkan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ankara-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dokunamam Yine Sana', 'dokunamam-yine-sana-i-smail-korkmaz-kubr4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sevginin adını umut koydum 

sevdanın adını özlem 

sensizliğe savaş dedim 

......................hasret dedim 

........................ulaş dedim 

deniz koydum yüreğimdeki coşkunun adını 

bariş dedim yüreğimdeki çocuğa 

''her türlüsünü tattım acıların ayrılıkların'' 

.....................................alışamadım 

Yüzlerce şiir yazdım da 

şiirlerimdeki sevgiyi hiç yaşayamadım 

milyonlar bana hep uzaktı şehir denilen delikte 

bu yüzden belkide suskunluğum dargınlığım 

toroslardan caniklerden munzurlardan 

ılık akşam rüzgarları eser 

ve usulca iner ovaya yüreği sevdalı 

kızılırmak kan akar can alır fırat 

ağıtlar ve türküler yankılanır anadolumda 

cemre derim bahar ceren sinem dilek 

yılmaz derim mahir taylan nazım hüseyin 

kınalı saçlarınla sen düşersin aklıma 

adını koyamam dokunamam yine sana. 

5 Ekim 2000-Münih', 'sevginin adını umut koydum  sevdanın adını özlem  sensizliğe savaş dedim  ......................hasret dedim  ........................ulaş d...', ARRAY['Türk Edebiyatı','Şiir','İsmail Korkmaz']::text[], 8.5, '{"poet":"İsmail Korkmaz","poet_slug":"i-smail-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/dokunamam-yine-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni', 'beni-emin-boz-udja5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'sevgin yüce dağlar kadar büyükse

yüreğinin ateşiyle yak beni

dermanıma erişmeden ölürsem

azraile yetişmeden vur beni 

ellerimi uzatırsam sana ben

ateş gibi volkan gibi bil beni

tutuşursan söndürecek çare var

nehir gibi deniz gibi gör beni 

dağ başında seslenirsem sana ben

esen yelden kasırgadan duy beni

el açıpta mecnun gibi yalvarsam

leyla gibi aslı gibi sev beni 

gurbet elde kaybolursam yalınız

bir sefile dilenciye sor beni

öldüğümü duyar isen bir zaman

toprak oldum mezarlıkta gör beni 

İSBN: 975-93080-0-2

YAZ AŞKLARI', 'sevgin yüce dağlar kadar büyükse yüreğinin ateşiyle yak beni dermanıma erişmeden ölürsem azraile yetişmeden vur beni  ellerimi uzatırsam san...', ARRAY['Türk Edebiyatı','Şiir','Emin Boz']::text[], 8.5, '{"poet":"Emin Boz","poet_slug":"emin-boz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/beni-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TARİFSİZ', 'tari-fsi-z-ahmet-kurt-jbrqd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Duygular tarifsiz, hisler belirsiz, 

Başı duman duman dağlar gibiyim.

Gökyüzünde bulut, bir silik umut, 

Bardaktan boşanan yağmur gibiyim.

Yoğrulan bedenim, karlar içinde, 

Ruhum anlatılmaz hisler içinde, 

Bir yol arıyorum nasıl, niçinde, 

Teknede karılan hamur gibiyim.

Ne sevince doydum, ne de üzüldüm, 

Kimi gün bir köşede büzüldüm, 

Kimi gün hayallerde süzüldüm, 

Kanadı yolunmuş kuşlar gibiyim.

Sen önce ruhunla, kendinle barış, 

Kainatı tanı, gez karış karış, 

Ömrümce bitmedi bu büyük yarış, 

Şimdi bir diyarda yadlar gibiyim.

Kendi nefesime hasreti duydum, 

Koskoca bir ömrü önüme koydum, 

Bastığım yerleri bilmeden oydum, 

Tarifi olmayan tadlar gibiyim.

Kurdoğluyum, perişanım bu günde, 

Gerçeklerle yaşıyorum düşümde, 

Öyle bir hatıra, koşar peşimde, 

Henüz konulmamış adlar gibiyim.', 'Duygular tarifsiz, hisler belirsiz,  Başı duman duman dağlar gibiyim. Gökyüzünde bulut, bir silik umut,  Bardaktan boşanan yağmur gibiyim. Y...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tarifsiz-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ünvan', 'unvan-turgay-akbulut-pyp92', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dört onluk bitirdik hayatımızdan 

Dört yıldız verdi oğlum Volkan

Ellisinde beş yıldızlı olacakmışız

Hayatımızda aldığımız tek ünvan

Oda Allahtan....', 'Dört onluk bitirdik hayatımızdan  Dört yıldız verdi oğlum Volkan Ellisinde beş yıldızlı olacakmışız Hayatımızda aldığımız tek ünvan Oda Alla...', ARRAY['Türk Edebiyatı','Şiir','Turgay Akbulut']::text[], 8.5, '{"poet":"Turgay Akbulut","poet_slug":"turgay-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/unvan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akiyor Goz Yasim Dost Veysel Diye', 'akiyor-goz-yasim-dost-veysel-diye-guner-kaymak-8tc3g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Atasozu gibi sozleri vardi

Koskocaman dunya ona cok dardi

Veyselden ayrilmak olumden zordu

Akiyor gozyasim dost veysel diye

Cok eser birakti yurtan gocerken

Yitirdi gozunu zalim cicekten

Halk aniyor onu cani yurekten

Akiyor gozyasim dost veysel diye

Gece gunduz hic serimden gitmiyor

Virane baglarda bulbul otmuyor

Veyselin anisi dilden bitmiyor

Akiyor gozyasim dost veysel diye

Toprak diye diye yandi tutustu

En sonunda gercek dosta kavustu

Genc yaslarda kader ile bogustu

Akiyor goz yasim dost veysel diye

Veyselin yolundan ben ayrilamam

Her asigim diyeni asik sanmam

Babam olse dahi bu kadar yanmam

Akiyor gozyasim dost veysel diye

Asik Guner derki sozlerim bitmez

Veyselin hayali gozumden gitmez

Oyle ozan dunyaya daha gelmez

Akiyor gozyasim dost veysel diye

www.yaylacik.com', 'Atasozu gibi sozleri vardi Koskocaman dunya ona cok dardi Veyselden ayrilmak olumden zordu Akiyor gozyasim dost veysel diye Cok eser birakti...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/akiyor-goz-yasim-dost-veysel-diye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O'' na Adsız Şiir', 'o-na-adsiz-siir-emre-gumusdogan-9lq2p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gözlerini günceme düştüğümden bu yana

sol kaburgamın altında çürüyor sevdan

varoşlara benziyor - sensiz - yüzüm

sözcüklerle sevişiyorum

sürüyor şiirle zinam...

düşlerime giriyor kıldan ince zamanlarda

şarkılara nakarat boynun

- karakalem çalışılmış

ıssız bir koy gibi uzaklarda -

ceviz sandıklarda saklanmış

güvercin güzelliğin

çiğdem çiçekleri ve toy sekişin...

soruyorum tutunduğum açmazlarda

çoğalttığımız ne / neleri tükettik...

nedir parmaklarımızdan ağan

siyah bir nokta gibi

eksilten bizi bizden

sevdanın çağla diriliğinden

diş izimizi esirgeyen...

gözlerini günceme düştüğümden bu yana

varoşlara benziyor - sensiz - yüzüm

teneke çamur sülfür

ve dilimde küfür...', 'gözlerini günceme düştüğümden bu yana sol kaburgamın altında çürüyor sevdan varoşlara benziyor - sensiz - yüzüm sözcüklerle sevişiyorum sürü...', ARRAY['Türk Edebiyatı','Şiir','Emre Gümüşdoğan']::text[], 8.5, '{"poet":"Emre Gümüşdoğan","poet_slug":"emre-gumusdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/o-na-adsiz-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-ebru-gecer-1dixa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sessizlik sürgün olmuş karanlık geceye

Ümitler hayallerini arıyor çaresizce...

Uzaktan uzağa seni özlediğimi hissederken, 

Bilemezdim ağlamayacağım derken ağlayacağımı...

Bir pembelik kaplardı rüyalarımı

Seni görürdüm pembeliklerin içinden

İçimi endişe kaplardı

Ya gerçekteki gibi çekip gidersen...

Beni burada böylece terk edersen...

Korkardım kelimelerin sahipsiz kalmasından

Düşüncelerimin yanlış adreste son bulmasından

Sevgimin değerinin anlaşılmamasından

Korkardım incilmekten, acı çekmekten 

Suların sesine kapılıp, seni arzularken...

Sessizce düşünüp, kendimi avuturken

Tekrar geriye dönmeyeceğine emin olurken

Elimde değil sevgilim özledim seni', 'Sessizlik sürgün olmuş karanlık geceye Ümitler hayallerini arıyor çaresizce... Uzaktan uzağa seni özlediğimi hissederken,  Bilemezdim ağlama...', ARRAY['Türk Edebiyatı','Şiir','Ebru Geçer']::text[], 8.5, '{"poet":"Ebru Geçer","poet_slug":"ebru-gecer","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ozledim-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savasa Hayir', 'savasa-hayir-neslihan-ayakta-imnjv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bebegini kollarina alamayacak analar, 

Sevdigine kavusamayacak asiklar! 

Kanlar dokulecek, 

Kapanmayacak yaralar…

Gozu yasli oksuz cocuklar, 

Ac, susuz, sogukta yetimler

Teknolojinin getirdigi bunlar mi olacakti? 

Biraz kalp ve beyin klonlamali profosorler! 

Tanri gozlerimizi acmali, 

Yuregimize isiklar sacmali! 

Ve bir kez daha agliyor, haykirmak istiyorum; 

Sesimiz olmali... SAVASA HAYIR! 

(27.01.03)', 'Bebegini kollarina alamayacak analar,  Sevdigine kavusamayacak asiklar!  Kanlar dokulecek,  Kapanmayacak yaralar… Gozu yasli oksuz cocuklar,...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/savasa-hayir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Ister', 'seni-ister-neslihan-ayakta-wwhfh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yuregim zorlar gogus kafesimi

Kanatlarini germek, ucmak ister

Rahatla desemde dinlemez beni

Sana gelmek, dokunmak ister! 

(23.04.02)', 'Yuregim zorlar gogus kafesimi Kanatlarini germek, ucmak ister Rahatla desemde dinlemez beni Sana gelmek, dokunmak ister!  (23.04.02)...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seni-ister-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretligimsin', 'hasretligimsin-neslihan-ayakta-8o9nb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nereye gideyim yar

Nereye sigdirayim sevgimi

Gocmen kuslara soyledim hasretimi

Memlekete ugrar mi yollari

Sicaklar tez dusun topragima

(23.04.02)', 'Nereye gideyim yar Nereye sigdirayim sevgimi Gocmen kuslara soyledim hasretimi Memlekete ugrar mi yollari Sicaklar tez dusun topragima (23.0...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hasretligimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yok Yarim', 'yok-yarim-neslihan-ayakta-juxw4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nedendir bu aci sordun mu yuregine

Gozlerine sordun mu nedendir bu islaklik

Yarin yoklugu mu kalabaklikta yalnizligi kilan 

Yoksa ulasmanin zor oldugu kisinin mi ruyasindasin

Oyle aciyor ki yuregim an gelip

Uzaktaki hayale inandim

Cok yandi canim

Yok iste biliyorsun yok

Uzaklik varsa vuslat sadece hayallerdeyse

O yar yoktur, yok! ! ! ! 

Kirilacak bir hayali mi istersin, 

Yoksa sapasaglam gercekleri mi? 

07.08.02', 'Nedendir bu aci sordun mu yuregine Gozlerine sordun mu nedendir bu islaklik Yarin yoklugu mu kalabaklikta yalnizligi kilan  Yoksa ulasmanin ...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yok-yarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdigim Var Benim', 'sevdigim-var-benim-neslihan-ayakta-dgmer', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yelkenlerim vardır benim, 

Hiç istediğim limana 

Sürüklemezler beni! 

Kanatlarım vardır benim, 

Rüzgarın üstüne üstüne giderler! 

Hayallerim vardır benim, 

Her yeri sevgiyle donatırlar! 

Sevdiğim var benim...

                 (30.06.00)', 'Yelkenlerim vardır benim,  Hiç istediğim limana  Sürüklemezler beni!  Kanatlarım vardır benim,  Rüzgarın üstüne üstüne giderler!  Hayallerim...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevdigim-var-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgililer Gunu', 'sevgililer-gunu-neslihan-ayakta-94pjs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İşte bu gün o gün, 

Bu günde o ana, 

O anda ona ulaşabilirsin.

Tek yapman gereken

Telefon açman ve onu istemen.

Emin ol ki

O bu anı telefonun yanında bekliyor

Ve ağzından o iki kelimenin

Teker teker çıkmasını.

               (14.02.96)', 'İşte bu gün o gün,  Bu günde o ana,  O anda ona ulaşabilirsin. Tek yapman gereken Telefon açman ve onu istemen. Emin ol ki O bu anı telefonu...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevgililer-gunu-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Iste Askin', 'iste-askin-neslihan-ayakta-diyj3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gün gelir o aşkın, 

Devamlı kavga edersin.

Aman dersin, 

''Tohumuna para mı verdim! ''.

Beş gün geçer aradan ağlarsın, 

Ne olduğunu sende anlayamazsın.

Aşk mı yoksa rüya mı bu? 

Her an kulağın telefondadır

Ama onda numaran bile yoktur.

Sen yinede ümit edersin

Ve telefonun yanında beklersin.

Aklından; ''Birinden bulur elbet! ''diye geçer.

Ama nerde, 

Beyaz atına binmiş

Uçmuş ve gitmiş...

                     (03.96)', 'Bir gün gelir o aşkın,  Devamlı kavga edersin. Aman dersin,  ''Tohumuna para mı verdim! ''. Beş gün geçer aradan ağlarsın,  Ne olduğunu sende ...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/iste-askin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gec Kalmis Olacaksin', 'gec-kalmis-olacaksin-neslihan-ayakta-08ziy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün geri dönmemi isteyeceksin, 

Seni seven birini arayacaksın.

Ama çok geç kalmış olacaksın...

Kırdığın kalpleri onarmaya çalışıp

Onlarda bendeki sabrı arayacaksın.

Sevgi, senin kalbinde yanmaya başlayacak.

Yalnızlık içini kemirecek.

Aşkından kalbin param parça olacak, 

Gözlerindeki ışık sönecek

Ve beni arayacaksın...

Ne kadar ararsan ara beni bende bile bulamayacaksın! 

Bu sevgiyi bu sefer sen yalnız yaşatacaksın, 

Dört duvar arasında kendine acıyacaksın.

Belki de kendini küçülterek yalvaracaksın

Ve arkamdan çok ağlayacaksın.

Ama çok, gerçekten de çok geç kalmış olacaksın...

                                    (11.97)', 'Bir gün geri dönmemi isteyeceksin,  Seni seven birini arayacaksın. Ama çok geç kalmış olacaksın... Kırdığın kalpleri onarmaya çalışıp Onlard...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gec-kalmis-olacaksin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-neslihan-ayakta-p9fsi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Günler çabuk geçsin, 

Geleceğimi istiyorum derken

Ömür yavaşça kayıyor elimizden.

Günler yavaş gibi gözükürken

Aylar çabuk geçiyor takvimden.

Sonumu düşünürken

Unutup gidiyorum bu günlerin değerini.

Kaçamak gibi gözükürken ölüm, 

Yaşamak daha kolay görünüyor bir an.

Hayatın değerini unutmak çok kolay, 

Yaşamak daha da kolay ama zalim(?) ...

Ölüm çekici görünürken

Saatler alıp başını gidiyor.

Yiyecek, giyecek bazense neşeli dakikalar tükeniyor.

Bir ansa gözyaşları tükenip

Sonumuzu istiyoruz anlamsızca.

Oysa kapatırken gözlerimizi

Anlıyoruz bu hayatın değerini.

Uyumak güzel görünürken bir an

Anlıyoruz ki fazla uyumak da yoruyor insanı.

Gülmek kolay görünürken

Bir an mimikler çekilemiyor, 

Gülmek o zaman ne kadar da zorlaşıyor.

Unuturum derken bir an, 	

İnsan hafızasının varlığını hatırlıyor.

Bu da geçer derken

Anlıyoruz ki ne geçerse geçsin, 

Aslında herşey beynimizde bitiyor...

                     (01.06.98)', 'Günler çabuk geçsin,  Geleceğimi istiyorum derken Ömür yavaşça kayıyor elimizden. Günler yavaş gibi gözükürken Aylar çabuk geçiyor takvimden...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/zaman-55-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Jeton', 'jeton-neslihan-ayakta-ui6y5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni özledim, 

Bana bakışlarını, ellerinin sıcaklığını, 

Konuşmanda ki sevecenliği...

İnsan sonradan anlıyor bazı şeyleri; 

Anlayamadım beni sevdiğini...

Belki biraz pişmanım şimdi

Ama iş işten çoktan geçti...

Şimdi yoksun yanımda, 

Bana öğütler veremiyorsun.

Ne olursa olsun

Bana destek olamıyorsun.

Yollarımızı açan benim biliyorum, 

Hatalarımı affet diyemiyorum.

Aramızda yollar, dağlar, denizler var, biliyorum.

Hep bir ümitle beklesem de, 

Bazen beni unuttu diyorum! 

Düşünüyorum o günleri, o anları, 

Anlayamadım o zaman değerlerini...

Şimdilerde jeton düştü.

Oysa ki senin teknolojin gelişmişti; 

Sen kart kullanıyordun! 

Ah bu jetonlar yok mu...

Bu kadar geç düşmeseler bir de, 

Belki de böyle yanmazdım işte! 

                      (06.09.98)', 'Seni özledim,  Bana bakışlarını, ellerinin sıcaklığını,  Konuşmanda ki sevecenliği... İnsan sonradan anlıyor bazı şeyleri;  Anlayamadım beni...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/jeton-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben de Istemedim', 'ben-de-istemedim-neslihan-ayakta-kf55z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kapatırım gözlerimi, 

Dalarım hayallere.

Ararım her yerde, 

Nerdesin diye.

Giderken belki hiç düşünmedin

Geri döneceğini.

Ağlattığın zaman farketmedin

Gözyaşlarımın dinmeyeceğini.

Pişmansın şimdi, 

Karşımda ağlıyorsun.

İnan çok geç kaldın, 

Yalnızlık şimdi senin arkadaşın.

Böyle bir hayatı ben de istemedim! 

Artık yanında olmayacağım...

Özlem duyma sakın o güzel yıllara, 

Kendini hazırla bensiz anlara.

                   (05.96)', 'Kapatırım gözlerimi,  Dalarım hayallere. Ararım her yerde,  Nerdesin diye. Giderken belki hiç düşünmedin Geri döneceğini. Ağlattığın zaman f...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-de-istemedim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahretsin', 'kahretsin-neslihan-ayakta-pmasr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senden kalan tek şey

Anılar ve sözlerin oldu.

Şimdi başka kollarda arıyorum, aynı sevgiyi...

Aynı sıcaklığı bulabilir miyim ki? 

O sözleri duyabilir miyim, o kadar içten, 

O kadar sıcak ve gerçek? 

Yine dönüp dolaşıp soruyorum kendime, 

Yakalayamıyorum ki hiçbir şeyi...

Kovalamak kolay sanki, 

Kovalanmak ne güzel! 

Anlayamadım hiçbir şeyin değerini...

Mutluluk bulunamazmış başkalarında

Bunu yeni öğreniyorum, 

Küçüklüğüme ver abisi! 

Emindim senden, güveniyordum

Ama sorguya çekmem gereken bendim.

Geç cevapladım soruları...

Sınıfta kalma şansım bile yoktu, 

Okuldan atılmıştım.

Buralara gelmeye can atıyordum, 

Ayrılığı unutmuştum oysa ki! 

Unutmuştum ve kahretsin, 

Buralarda bıraktığım gibi değildi ki...

                    (06.09.98)', 'Senden kalan tek şey Anılar ve sözlerin oldu. Şimdi başka kollarda arıyorum, aynı sevgiyi... Aynı sıcaklığı bulabilir miyim ki?  O sözleri d...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kahretsin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkarim', 'korkarim-neslihan-ayakta-h4az5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kapalı pencereler ardından

Görmek isterim seni bazen.

Canım çeker teninin kokusunu, 

Dağılır bulutlar tepemden.

Telefon uzaklaştırır seni benden, 

Hayalin daha güzel.

Senin peşine düşemem

Hep kaçarsın benden.

Sana açılamam, korkarım

Güler geçersin sen...

Kapalı kapılar ardından

Ulaşmak isterim sana bazen.

Özlerim hep sesinin tonunu, 

Kanatlanır her şey birden.

Sensin hep aramıza giren, 

Hayalin daha güzel.

Senin peşine düşemem

Hep kaçarsın benden.

Sana açılamam, korkarım

Güler geçersin sen...

                       (06.07.98)', 'Kapalı pencereler ardından Görmek isterim seni bazen. Canım çeker teninin kokusunu,  Dağılır bulutlar tepemden. Telefon uzaklaştırır seni be...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/korkarim-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ozgur Bir Kus Gibi', 'ozgur-bir-kus-gibi-neslihan-ayakta-b304q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bıraktım kalbimi bir kuş gibi

Uçuyor goklerde, mutlu ve özgür.

Onu kırabilecek ya da incitebilecek

Hiç kimse yok, o hep neşeli.

Yalnızlıklara mahkum değil artık, 

İnsanların sorunlarıyla iç içe değil.

Sorunlar karşısında ne yapacağını 

Düşünmüyor ve kimseyi incitemiyor.

Üzülemez hiçbir acıya, 

Ağlayamaz içten içe zorluklara.

Kapanamaz kendi haline, 

Cevap vermez hiç kimseye.

İsterse göklere açılır

Dertlere rüzgarla güler, 

Bulutlarla konuşur

Ve onlarla hayallere dalar.

Artık o özgür

İnsanların esiri değil.

Mutlu ve neşeli

Bir odada mahkum değil.

                  (12.96)', 'Bıraktım kalbimi bir kuş gibi Uçuyor goklerde, mutlu ve özgür. Onu kırabilecek ya da incitebilecek Hiç kimse yok, o hep neşeli. Yalnızlıklar...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ozgur-bir-kus-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affetmeyecegim', 'affetmeyecegim-neslihan-ayakta-ct4p4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gittiğin gün affetmeyeceğim dedim.

Sen giderken ben gözyaşlarımı sildim.

Sen güldün bense seviyorum dedim.

Arkanı dödün bana, ne kadar yalvarsamda.

Bir gün gelecek ki ben seni yalvartacağım.

Yine de gülerek affetmeyeceğim, 

İçim ne kadr kan ağlasa da.

Arkamı dönüp gideceğim, ne kadar ağlasanda.

                        (05.96)', 'Gittiğin gün affetmeyeceğim dedim. Sen giderken ben gözyaşlarımı sildim. Sen güldün bense seviyorum dedim. Arkanı dödün bana, ne kadar yalva...', ARRAY['Türk Edebiyatı','Şiir','Neslihan Ayakta']::text[], 8.5, '{"poet":"Neslihan Ayakta","poet_slug":"neslihan-ayakta","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/affetmeyecegim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmadım', 'unutmadim-nusret-tokat-q2uma', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ayrılık....

Anlam taşımayan bir kuvvet hissediyorum, 

Sana Telaşlandığımda, yada her elini tuttuğumda, 

Her bakışında bir mazi açılıyor sınırsız.

Kapanışı geliyor, Bir günün, Diğer güne başlamasında.

Ben Sana bakıyorum sen bana..', 'ayrılık.... Anlam taşımayan bir kuvvet hissediyorum,  Sana Telaşlandığımda, yada her elini tuttuğumda,  Her bakışında bir mazi açılıyor sını...', ARRAY['Türk Edebiyatı','Şiir','Nusret Tokat']::text[], 8.5, '{"poet":"Nusret Tokat","poet_slug":"nusret-tokat","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/unutmadim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizce', 'denizce-erol-nacar-dpceu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Doğduğumda

Yunus balığının derisine sarmış

Kundak diye

Babam beni

Mavicem.

Süt yerine

Levrek kanı içmişim, 

Kofananın etini emmişim

Meme yerine.

Dalga dalga kollarında

Ninnilerce dinlemişim sesini

Su beşiğimde

Saçlarından tutmuşum

Gün doğumundan esen lodos yelini.

Mavicem, 

Delicem...

Göğsünde

Bir hayal gibi dolanırken

Son balıklar, 

Motorlar kanatırken

Bereketli karnını, 

Limanlara taşırlarken

Etini, 

Kanını...

Ölü sularında

Parçalanırken ay! ...

Kılıç balığının sırtındaki zıpkın gibi

Taşıdım kendi cenazemi.

Yakamozlar yerine

Çığlıkların

Sardığında derimi.

Gözlerimde

Orkinosun gözyaşlarına dokunursun, 

Ağlarda parçalanan

Yunus dişlerimle

Isırdığımda ellerimi! ...

Yatağım, 

Köpükler döşeli yastığımsın

Mavicem

Anacığım, 

Rüzgâr saçlı kadınımsın! 

Yeri göğü alt üst eden fırtınalarında, 

Köpük köpük titreyen dalgalarında

Alabilsem, 

Alabilsem yerimi

Ve

Tamamlasam seferimi

Mavicem!', 'Doğduğumda Yunus balığının derisine sarmış Kundak diye Babam beni Mavicem. Süt yerine Levrek kanı içmişim,  Kofananın etini emmişim Meme yer...', ARRAY['Türk Edebiyatı','Şiir','Erol Nacar']::text[], 8.5, '{"poet":"Erol Nacar","poet_slug":"erol-nacar","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/denizce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'tesadüf değil', 'tesaduf-degil-i-kbal-senturk-ggooo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'saatlerce oturup 

havadan sudan konuşmamız

konuşurken gözlerinden kaçışım

en kötü anımda sana gelişim

tesadüf değil', 'saatlerce oturup  havadan sudan konuşmamız konuşurken gözlerinden kaçışım en kötü anımda sana gelişim tesadüf değil...', ARRAY['Türk Edebiyatı','Şiir','İkbal Şentürk']::text[], 8.5, '{"poet":"İkbal Şentürk","poet_slug":"i-kbal-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tesaduf-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peri', 'peri-birol-akbaba-noe2p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir peri aranıyor 

nefesi can, sesi çağlayan.

bir peri aranıyor

gönüle dost, aleme nişan.

bir peri aranıyor

dukunuşu kutsal, öpüşü tanrısal

bir peri aranıyor 

bana bende ki beni anlatan', 'bir peri aranıyor  nefesi can, sesi çağlayan. bir peri aranıyor gönüle dost, aleme nişan. bir peri aranıyor dukunuşu kutsal, öpüşü tanrısal ...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/peri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peri busesi', 'peri-busesi-birol-akbaba-obc5l', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sabah bir fısıltı ile uyandım.

sordum, 

dediler o peri.

dedim yanağımda ki iz.

dediler o busesi', 'sabah bir fısıltı ile uyandım. sordum,  dediler o peri. dedim yanağımda ki iz. dediler o busesi...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/peri-busesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hata Yapmayı Seviyorum', 'hata-yapmayi-seviyorum-melih-coskun-3r4kc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hata yapmayı seviyorum

İnsan olduğumu anımsatıyor bana her seferinde

Seviyorum acıyı mutluluğu sevdiğim kadar

Acılarda bizim içindir bu dünyada

En az mutluluklar kadar

Seviyorum gerekli gereksiz bütün heyecanları

Yüreğimin çarptığını anımsatıyor bana 

Her defasında.

Paylaşılan bütün mavilerini seviyorum hayatın

Düşmanlarım sizi seviyorum

Mücadeleyi öğrettiğiniz için bana

Dik durmayı öğrettiniz haksızlıklar karşısında, 

Seviyorum karanlığı

Değerli kıldığı için sürekli aydınlıkları, 

Sevmeyen her kim kaldıysa bu dünyada

Hepinizi seviyorum

Sevmeyi öğrenirsiniz diye bir gün...

15 Kasım 2002

18: 40', 'Hata yapmayı seviyorum İnsan olduğumu anımsatıyor bana her seferinde Seviyorum acıyı mutluluğu sevdiğim kadar Acılarda bizim içindir bu düny...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hata-yapmayi-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen yoksun sıcağını arıyorum', 'sen-yoksun-sicagini-ariyorum-birol-akbaba-rv5u5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen yoksun sıcağını arıyorum

sesin yankılanıyor odam da

kokun sinmiş 

dokunduğun eşyalara, masa ya

ellerinin izi var çaldığın plakta 

sen yoksun sıcağını arıyorum 

bir tel saç bırakmışsın koltukta 

bir de gülümseyen resmin var

onlarla beraberiz onlar senden bir iz

sen yoksun sıcağını arıyorum', 'sen yoksun sıcağını arıyorum sesin yankılanıyor odam da kokun sinmiş  dokunduğun eşyalara, masa ya ellerinin izi var çaldığın plakta  sen yo...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-yoksun-sicagini-ariyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ki İnsansın', 'sen-ki-i-nsansin-melih-coskun-158gb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen ki insansın 

Yaratılmanın en uç noktası

En muhteşem 

Ve en korkunç yanısın

Sen ki insansın 

Tanrı’nın yeryüzüne yansımasısın yani

Olamazsın bu kadar kötü yürekli

Bu kadar adaletsiz 

Sen ki insansın 

Topraktan yaratıldı senin kalbin

Taştan demirden değil

Sen ki insansın 

Harcında isyan ve gözyaşı

En tehlikelisisin düşüncenin

Merhametle  zulmün arasındaki 

İnce çizgide yürümektesin

Elindeki çelik canavar değil asıl kan kusturan

Ona yön veren parmakların 

O beynin sahibisin sen.

Sen ki insansın 

Karaya boyansa da kalbinin her yanı

Beyaz bir yer kalmıştır mutlaka 

Dünyaya ayıracak 

Çünkü sen bir insansın hala...

30 Aralık 2002

01: 34', 'Sen ki insansın  Yaratılmanın en uç noktası En muhteşem  Ve en korkunç yanısın Sen ki insansın  Tanrı’nın yeryüzüne yansımasısın yani Olamaz...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sen-ki-insansin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni seviyorum', 'seni-seviyorum-birol-akbaba-mpx82', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ellerinin kokusu var

içime sinmiş yaşıyorum, 

gözlerinin rengi 

gözüme değmiş görüyorum, 

titrek kalbinin atışları

yüreğim de duyuyorum

seni çok seviyorum.', 'ellerinin kokusu var içime sinmiş yaşıyorum,  gözlerinin rengi  gözüme değmiş görüyorum,  titrek kalbinin atışları yüreğim de duyuyorum seni...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/seni-seviyorum-113-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevginin gücü', 'sevginin-gucu-birol-akbaba-yojrb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gittim kocaman bir kayanın yanına

eğildim sevdiğimi söyledim çatladı

kuru bir ağacın altına oturdum 

sevdiğimi söyledim

yeşil oldu, çiçek oldu', 'gittim kocaman bir kayanın yanına eğildim sevdiğimi söyledim çatladı kuru bir ağacın altına oturdum  sevdiğimi söyledim yeşil oldu, çiçek ol...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevginin-gucu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarin gözleri', 'yarin-gozleri-birol-akbaba-dp14b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'yarin gözleri zeytin, 

yarin gözleri dalgın, 

yarin gözleri sevgi, 

yarin gözleri arzu, 

yarin gözleri özlem, 

yarin gözleri gözde yürek 

yarin gözleri yürekten bakıyor, 

yarin gözleri yürekler yakıyor.', 'yarin gözleri zeytin,  yarin gözleri dalgın,  yarin gözleri sevgi,  yarin gözleri arzu,  yarin gözleri özlem,  yarin gözleri gözde yürek  ya...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yarin-gozleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeniden doğmak için', 'yeniden-dogmak-icin-birol-akbaba-0q700', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'uykuyu yollayıp 

gecenin karanlığına

gönül aydınlığında 

yüzünle yüzleşmek için

esir olmadan 

yanlızlığın sinsi tuzağına

hazırım sevmeye 

yeniden doğmak için', 'uykuyu yollayıp  gecenin karanlığına gönül aydınlığında  yüzünle yüzleşmek için esir olmadan  yanlızlığın sinsi tuzağına hazırım sevmeye  ye...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yeniden-dogmak-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-birol-akbaba-ef8os', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gönülden diledim sevdiğimi söyledim

adını ezberledim dalım yaprağım çiçegim

ellerimde ellerin gözlerimde gözlerin

hadi gel özledim sensin benim sevdiceğim

sana her bakışımda yüreğimden yanışımda 

ismini her anışımda sensin benim tek dileğim

ellerimde ellerin gözlerimde gözlerin

hadi gel özledim sensin benim sevdiceğim', 'gönülden diledim sevdiğimi söyledim adını ezberledim dalım yaprağım çiçegim ellerimde ellerin gözlerimde gözlerin hadi gel özledim sensin be...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ozlem-91-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Öleceksem.', 'bir-gun-oleceksem-cengiz-yazici-hwwfh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir gün öleceksem...

Ki ben asla ölmeyeceğim.

Kimse politika yapmasın, 

Cenazeme katılmayın.

Bana ayak yapmayın, 

Hepinizin ne mal olduğunu

Biliyorum.

Her ne kadar şu an

konuşamazsamda.

Alayınızdan alacaklıyım.

Vijdanınızı rahatlatamayacaksınız.

Beni kandırdınız, belki kullandınız, 

Sattınız, hatta harcadınız, 

Kendinizi nasıl aldatacaksınız? 

Bir kezde ben kazık atacağım, 

Son kez olsun ben kazanacağım, 

İki elim yakanızda bilesiniz, 

Hakkım helal değildir sizlere...

Ben o kutsal yerde, 

Alayınızdan hakkımı...

Kuzu kuzu alacağım.', 'Bir gün öleceksem... Ki ben asla ölmeyeceğim. Kimse politika yapmasın,  Cenazeme katılmayın. Bana ayak yapmayın,  Hepinizin ne mal olduğunu ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-gun-oleceksem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neylerim Ben Yeni Bir Yılı.', 'neylerim-ben-yeni-bir-yili-cengiz-yazici-fc1qu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yine aynı tas, aynı hamam olacaksa, 

Tekel, rakımdan bir yudum daha çalacaksa, 

Kısa Maltepe''m birazdaha kısalacaksa, 

Neylerim ben yeni bir yılı.

Onca çamlar yine devrilecekse, 

Üzerine pamuk karlar yağdırılacaksa, 

Su yokken içmeye, Şişeler devrilecekse, 

Neylerim ben yeni bir yılı.

Onca babam varken bir daha olacaksa, 

Analar sadece doğurmakla kalacaksa, 

Yine onların hatırı sorulacaksa, 

Neylerim ben yeni bir yılı.

Baronlar para ile oynayacaksa, 

Petrol uğruna bir devlet yok olacaksa, 

Birileri bunu ayakta alkışlayacaksa

Neylerim ben yeni bir yılı.

Çözülemeyenler yine faili meçhul olacaksa, 

Değişemeyenler eğer hiç değişmeyecekse, 

Serseri kurşunlar, yine beyinleri öldürecekse, 

Neylerim ben yeni bir yılı.

Yine yalanlar havalarda uçuşacaksa, 

Çiğ köfteler tavanlara yapışacaksa, 

Seçtiklerim çocukça konuşacaksa, 

Ve bu millet yine bunları yutacaksa, 

Neylerim ben yeni bir yılı.', 'Yine aynı tas, aynı hamam olacaksa,  Tekel, rakımdan bir yudum daha çalacaksa,  Kısa Maltepe''m birazdaha kısalacaksa,  Neylerim ben yeni bir...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/neylerim-ben-yeni-bir-yili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selvi', 'selvi-birol-akbaba-mctrj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'gri bulutlar sarmış göğü

neredesin selvi

bir tutam yıldızdın önceleri

toprağın üstünde 

yorgun yapraklar gibisin

gri bulutlar sarmış göğü 

neredesin selvi 

bir tutam yağmurdun önceleri

nehirler üzerinde sal lar gibisin

gri bulutlar sarmış göğü

neredesin selvi

bir tane idin önceleri

başak oldun doldurdun ovaları

gri bulutlar sarmış göğü

bendesin selvi', 'gri bulutlar sarmış göğü neredesin selvi bir tutam yıldızdın önceleri toprağın üstünde  yorgun yapraklar gibisin gri bulutlar sarmış göğü  n...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/selvi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dondurma', 'dondurma-cengiz-yazici-1uboy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen benim dondurma külahımsın, 

Bense o külahta bir dondurmayım.

İster sütlü ister kakaolu, 

İstersen meyve tadındayım.

Soğuk durduğuma bakma benim, 

Yala beni, em beni, dudaklarınla öp beni, 

Dayanamam sıcaklığına, 

Çek içine, erit beni bitir beni', 'Sen benim dondurma külahımsın,  Bense o külahta bir dondurmayım. İster sütlü ister kakaolu,  İstersen meyve tadındayım. Soğuk durduğuma bakm...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dondurma-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu hayat senin', 'bu-hayat-senin-birol-akbaba-7uwrv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sessiz usul usul gel şiiişt! 

ceylan gibi ölçülü, dikkatli olmalısın

av olmak istemiyorsan hayata

sakin, dikkatli ve hazır durmalısın

adımlarını sayma istersen

planda yapma geleceğe dair belirsiz

heyecanını, sevgini hapsetme içine

pazarlıklı, koşulcu, çıkarcı, yargılayıcı olma

sevilmekten beklediğin gibi olsun sevgin

benzetme kendini bir başkasına

sen, sen olmalısın kopyası olmayan

rüzgarı, kırları, dağları, kuşları 

dalgaları yaşamak istiyorsan dolu dolu

özgür olmalısın alabildiğine özgür

kısıtlamalardan, tutsaklıklardan

arınmalısın bağımlılıklardan

sahiplenmeden kendiliğinden olmalı sevgin 

adı sevgi kendi sevgi olmayan sevgilerin, 

gerçeğe götürmeyen düşlerin olmasın

sessiz usul usul gel bu hayat senin

yüreğinle yaşamalı yüreğinle sevmelisin

tekrarı yok yaşadığın anın bil

gülü onurlandırdığında nazlı bülbül

güneş doğmasa da açar gonca gül

zamanı meydana getiren anlardır

gelecek korkusu ile ertelediğin kim

geriye dönüp baktığımızda şöyle bir

yüzümüzde sevinç, yüreğimizde sevgi olmalı

sevgi olmayan tüm yürekleri unutmalı

sessiz usul usul gel sakin

damakta yaşanan şarap tadında

telaşsız doya doya olmalı sevgin

büyüse de yılların çocuk kalsın gözlerin

şiişt sessiz usul usul gel bu hayat senin', 'sessiz usul usul gel şiiişt!  ceylan gibi ölçülü, dikkatli olmalısın av olmak istemiyorsan hayata sakin, dikkatli ve hazır durmalısın adımla...', ARRAY['Türk Edebiyatı','Şiir','Birol Akbaba']::text[], 8.5, '{"poet":"Birol Akbaba","poet_slug":"birol-akbaba","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bu-hayat-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Özgürüm', 'ben-ozgurum-erdogan-ciray-bmbp5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yıllar sonra

Dün akşam

İlk defa içtim

O hayırsızın şerefine

Meğer ne çok özlemişim

Özgür benliğimi

O haylaz günlerimi

Aramıyorum artık

Onunla geçen, dünlerimi

Kadehlerin kokusuyla değiştim

Teninin kokusunu

Hasret yangınlarında yaktım

Eski resimleri

Bir alışkanlık olsa gerek 

Yine fal tuttum

Sigaramın dumanından

Dilim sürçtü

Adını andım yine

Hüzzam bir şarkı mırıldandım

O günlere salan

Bir kez daha anladım ki

Aşk koca bir yalan

Bir şarkılık hüzündü

Geriye kalan', 'Yıllar sonra Dün akşam İlk defa içtim O hayırsızın şerefine Meğer ne çok özlemişim Özgür benliğimi O haylaz günlerimi Aramıyorum artık Onunl...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çıray']::text[], 8.5, '{"poet":"Erdoğan Çıray","poet_slug":"erdogan-ciray","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-ozgurum-serbest-calisma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben hiç büyümedim ki', 'ben-hic-buyumedim-ki-erol-sen-w2933', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Annemi kaybedince anladım 

Ben hala küçük bir çocuğum gönlümce

Ağlanacak günümde ağladım ben utanmadan

Sevgime ağladım kaybettiğimde

Yaşarken anlamamıştım sevdiğimi kaybetmeyi

Aylar geçti hala seviyorum gönlümde

Sana ziyaretimde güller getirdim rengarenk

Ogün bayramdı ama ben ağlıyordum

Toprağın üstüne yaydım o güzel gülleri

Yapabilecek başka birşeyim yoktu

Olamazdı olmayacaktı 

Sana keşkelerim oldu annem

Dilerim mekanın cennet olmuştur

Ben hala en küçük oğlun

Fırtınalar dolu gönlünde

Yerin hep kalbimde senden öğrendiğim....

29.01.03', 'Annemi kaybedince anladım  Ben hala küçük bir çocuğum gönlümce Ağlanacak günümde ağladım ben utanmadan Sevgime ağladım kaybettiğimde Yaşarke...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-hic-buyumedim-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçime Dönük', 'i-cime-donuk-altug-ozgun-z23wq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yalnızım bu evren içinde.

Yalnızım kendi içimde.

Bekliyorum bozulsun diye.

Bir avuç kum avuçlarımda.

Özgür bırakıyorum rüzgarda.

Bütün yönlere savrulsunlar diye.

Belki ruhumu da alıp götürürler, 

Ulaşamadığım her yere.

Yalnızım bu evren içinde.

Yalnızım kendi içimde.

Bir avuç su avuçlarımda.

Özgür bırakıyorum çatlamış, kurak toprağa.

Süzüp alıyor toprak içine, 

Belki ruhumu da alıp götürür, umuyorum...

Ulaşamadığım en derinlere.

Bir avuç sevgi avuçlarımda.

Sadece tutuyorum, birileri gelip çalsın diye.

Gözlerim saatimde, özgür bırakıyorum zamanı.

Belki bu yalnızlık biter diye.', 'Yalnızım bu evren içinde. Yalnızım kendi içimde. Bekliyorum bozulsun diye. Bir avuç kum avuçlarımda. Özgür bırakıyorum rüzgarda. Bütün yönle...', ARRAY['Türk Edebiyatı','Şiir','Altuğ Özgün']::text[], 8.5, '{"poet":"Altuğ Özgün","poet_slug":"altug-ozgun","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/icime-donuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Falım Çıkmış', 'falim-cikmis-altug-ozgun-xyvr3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüzüklü ellerde yapıldı kahvem.

Yudumlarken içtim fallarımı.

Acı mıydı, orta mıydı, ortasını bulamadım.

Üç vakte kadar yol göründü.

Yolun sonunu göremedim.

Yüzüklü ellerden bakıldı falıma.

Üç vakte kadar mutluluk göründü.

Mutluluk muydu yoksa rüyamı anlayamadım.

Yüzüklü elleri tuttum, falları bıraktım.', 'Yüzüklü ellerde yapıldı kahvem. Yudumlarken içtim fallarımı. Acı mıydı, orta mıydı, ortasını bulamadım. Üç vakte kadar yol göründü. Yolun so...', ARRAY['Türk Edebiyatı','Şiir','Altuğ Özgün']::text[], 8.5, '{"poet":"Altuğ Özgün","poet_slug":"altug-ozgun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/falim-cikmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlıyorum Deme Bana', 'anliyorum-deme-bana-yasar-kemal-seckin-j7de3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anlıyorum deme bana

Anlayabilir misin hissettiklerimi

Bakabilir misin hayata benim gözlerimden

Sığdırabilir misin otuziki seneyi beş dakikaya

Çözebilir misin beynimin gizemini

Silebilir misin unutmak istediklerimi

Senin için yanlış olan değer yargılarımı 

Değiştirebilir misin anlayacağın şekilde

Bir gülüşün kıymetini bilebilir misin

Sevgilimin dudaklarındaki

Ruhumda kopan fırtınaları

Canlandırabilir misin hayalinde

Yaşayabilir misin aynı acı ve üzüntülerimi

Delice düşlerimi sorgulayabilir misin içinde

Boşuna anlıyorum deme bana

İçiçe yaşadığım bunca seneye rağmen

Kendimi ben bile anlayamadım daha', 'Anlıyorum deme bana Anlayabilir misin hissettiklerimi Bakabilir misin hayata benim gözlerimden Sığdırabilir misin otuziki seneyi beş dakikay...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Kemal Seçkin']::text[], 8.5, '{"poet":"Yaşar Kemal Seçkin","poet_slug":"yasar-kemal-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/anliyorum-deme-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Batan Günün Ardından', 'batan-gunun-ardindan-yasar-kemal-seckin-1bemz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine bir gün batıyor uzak ufuklarımda

Yine deli atıyor kanım damarlarımda

Özlemin büyümekte karanlıkla beraber

Duymak istiyor kalbim sevgiliden bir haber

Gitmiyor hayalimden geceden taşan yüzün

Hatırımdan çıkmıyor o hüzünlü gülüşün

Hasret ufuğa doğru uzaklaşan bir gemi

Belli değil rotası taşıyor bir gizemi

Senden ayrı olunca zamanım hiç geçmiyor

Kalbim uzaklarımda, senden başka seçmiyor

Aramıza koymuşsun yollar ve derin dağlar

Ulaşamayan kalbim sadece sana ağlar', 'Yine bir gün batıyor uzak ufuklarımda Yine deli atıyor kanım damarlarımda Özlemin büyümekte karanlıkla beraber Duymak istiyor kalbim sevgili...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Kemal Seçkin']::text[], 8.5, '{"poet":"Yaşar Kemal Seçkin","poet_slug":"yasar-kemal-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/batan-gunun-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlamak', 'aglamak-yasar-kemal-seckin-s0jt2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İlk bakışta anladım

Gülen bakışının sönüklüğünden

Belli ki gözlerin sevgisinden davacı

Üzüntünü içine atma

Bir dosta açılmaktır ilacı

Aşk nedir sanıyorsun

Bir karşılıklı duygular savaşı

Kazanamayacağını düşünüp zayıfım deme 

Bazen en etkili silahındır gözyaşı

Ağla utanma..

Kafanda taşıyıp büyüteceğine dertlerini

Gözyaşında taşı', 'İlk bakışta anladım Gülen bakışının sönüklüğünden Belli ki gözlerin sevgisinden davacı Üzüntünü içine atma Bir dosta açılmaktır ilacı Aşk ne...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Kemal Seçkin']::text[], 8.5, '{"poet":"Yaşar Kemal Seçkin","poet_slug":"yasar-kemal-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aglamak-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleyemediğim', 'soyleyemedigim-yasar-kemal-seckin-hl0g1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen ki alımlı peri kızı çok şanslısın

Doğarken güzelliğini sana vermiş sabah yıldızın

Güzelliğini her gün aynada görüyorken sen

Sadece seninle olduğum anlarda ''görüyorum'' ben

Seninleyken canlı ve renklidir benim dünyam

Sebepsiz değil inan sana böyle hayran olmam

Bir göl gibi durgun olan hayatımda

Alımlı bir şekilde süzülen bir kuğusun sen

Usta bir heykeltraşın elinden çıkmış

Eşsiz bir tanrısal heykelsin

Bugünün bitmesini istemiyorum

Çünkü hayatımdan çıkmak üzeresin

Ve ben dalından kopmuş bir yaprak gibiyim

Seninle yaşadığım o güzel günlere dönmek isteyen

Hatıralarla yaşanmayacağını bile bile

Ama hatıralarımda bile sen 

Bugün sensiz yaşayacağım bütün sevinçlerden daha güzelsin

Küçük bir çocuk olmak istiyorum

Çocuk gibi nazlanmak ''ben onu istiyorum''

Ama biliyorum ki bu imkansız

Gözümde biriken yaşlara müsaade etmek gibi

Ve bugün korktuğum başıma gelecek biliyorum

Sana söyleyebileceğim son birşey var birtanem

Seni seviyorum', 'Sen ki alımlı peri kızı çok şanslısın Doğarken güzelliğini sana vermiş sabah yıldızın Güzelliğini her gün aynada görüyorken sen Sadece senin...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Kemal Seçkin']::text[], 8.5, '{"poet":"Yaşar Kemal Seçkin","poet_slug":"yasar-kemal-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/soyleyemedigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Hicran Yarım Kalmalı', 'bu-hicran-yarim-kalmali-levent-yilmaz-2yacp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben böyle bir acı istemiyorum, 

Yolun başında, 

Çıkmazlar içindeki tek sığınağımın, 

Ellerimden kaymasını kabul edemiyorum.

Gerçek yaşamın ilk perdesinde, 

Arzularımın ecesini yok saymak, 

Yirmi yaş öncesi acemiliklerimin, 

Bir tekrarı sanki...

Yaşamak, yanılmaksa eğer çoğu kez, 

O, doğruda kalmalı, 

Alacalı düşlerden çıkıp

Benim gerçeğimde, 

Benim yanımda olmalı; 

Bu hicran yarım kalmalı...', 'Ben böyle bir acı istemiyorum,  Yolun başında,  Çıkmazlar içindeki tek sığınağımın,  Ellerimden kaymasını kabul edemiyorum. Gerçek yaşamın i...', ARRAY['Türk Edebiyatı','Şiir','Levent Yılmaz']::text[], 8.5, '{"poet":"Levent Yılmaz","poet_slug":"levent-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bu-hicran-yarim-kalmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bulut Ağlıyordu', 'bir-bulut-agliyordu-yasar-kemal-seckin-ikir6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hüzünlüydüm

Bitmeyen bir dert taşıyan yüreğimle

Doğacak olan güneşi bekliyordum o tepenin üzerinde

Senelerin ağırlığı binerken çökmüş omuzlarıma

Muhtaçtım çöllerin o ıssız sonsuzluğuna

Kırdaki çiçekler gibi zenginlik varken çevremde

Sonsuz bir yalnızlık çekiyordum çaresiz yüreğimde

Yoktu bir başkası çevrem ne kadar dolarsa dolsun

İstiyordum sadece o, yalnızca o benim olsun 

O farklıydı, o candı, güneşti benim için

Tek çareydi soğumuş kalbimi ısıtmak için

O ateşti, yakacaktı beni, bilecektim

Ben pervaneydim. Gerekirse yolunda ölecektim

Olmadı, yapamadım kalbimin isteğini

Acım kalbimi dağlıyordu

İlerde; 

Doğmak üzere olan kızılla kaplı şafakta

Bir bulut ağlıyordu.', 'Hüzünlüydüm Bitmeyen bir dert taşıyan yüreğimle Doğacak olan güneşi bekliyordum o tepenin üzerinde Senelerin ağırlığı binerken çökmüş omuzla...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Kemal Seçkin']::text[], 8.5, '{"poet":"Yaşar Kemal Seçkin","poet_slug":"yasar-kemal-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-bulut-agliyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pişman Etme', 'pisman-etme-levent-yilmaz-at239', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben neden bu kadar

Çok sevdim? 

Bozkır kokulu, 

Yaban gülüm benim.

Neden dikenlerimi, 

Yok saydım senin? 

Ben, ben olalı, belki de

Gülleri hep dikensiz belledim! 

Nedâmet damlıyor, 

Yüreğimin en canlı yerinden; 

Mızrap olmuş diken, 

Uyutmuyor geceleri.

Beyaz yüzün, 

Kahve gözün, 

Sevda makamlı şarkıyken bana, 

Şimşekten ok oldular rûyalarımda.

Sevdamın ovalarında açacak

Bir pembe gül iken, 

Kâbusum olma benim! 

Yağmurlu gecelerin aynasında, 

İlkbahar sıkıntım kalma benim! 

Beni, 

Bu kadar çok sevdiğime

Pişman etme, sevdiğim!', 'Ben neden bu kadar Çok sevdim?  Bozkır kokulu,  Yaban gülüm benim. Neden dikenlerimi,  Yok saydım senin?  Ben, ben olalı, belki de Gülleri h...', ARRAY['Türk Edebiyatı','Şiir','Levent Yılmaz']::text[], 8.5, '{"poet":"Levent Yılmaz","poet_slug":"levent-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/pisman-etme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşündüğüm Anlar', 'seni-dusundugum-anlar-yasar-kemal-seckin-6tamc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gerçek yaşam seninle geçirdiğim anlardır

En mutsuz bitişlerim sensiz olan sonlardır

Seni düşünürken sevginin gücünü hissederim

Seninleyken azalır her zaman kederlerim

Sadece sensiz anlarda üşütür geceler beni

Sensizken hissederim güllerin dikenini

Yokluğunda sarar beni sensizliğin çemberi

Ruhumu esir eder, arttırır kederleri

Beni ağlatan sensiz gerçekleşen sonlardır

Benim için mutluluk senle olduğum anlardır', 'Gerçek yaşam seninle geçirdiğim anlardır En mutsuz bitişlerim sensiz olan sonlardır Seni düşünürken sevginin gücünü hissederim Seninleyken a...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Kemal Seçkin']::text[], 8.5, '{"poet":"Yaşar Kemal Seçkin","poet_slug":"yasar-kemal-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seni-dusundugum-anlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyanınca Seni Görmek', 'uyaninca-seni-gormek-yasar-kemal-seckin-kpk0l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yorgun değildim inan gözlerimi kaparken

Senin hakkındaki tüm düşünceler çok özel

Uzakta ve ulaşılmaz sanırken seni her an

Yanımdasın. Uyanınca seni görmek ne güzel

Taştan bir kalple bile sevebilirsin inan

Duygularım sevgi değil, sevgiden daha özel

Gecelerin korkutmuyor, karanlıkla başlayan

Kabuslardan uyanınca seni görmek ne güzel

Uzak olma ne olur seni çok seviyorum

Aşkım tek senin için, sadece sana özel

Hayalin yetmez ama bunu hep söylüyorum

Hayallerden uyanınca seni görmek ne güzel', 'Yorgun değildim inan gözlerimi kaparken Senin hakkındaki tüm düşünceler çok özel Uzakta ve ulaşılmaz sanırken seni her an Yanımdasın. Uyanın...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Kemal Seçkin']::text[], 8.5, '{"poet":"Yaşar Kemal Seçkin","poet_slug":"yasar-kemal-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/uyaninca-seni-gormek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstediğim', 'i-stedigim-yasar-kemal-seckin-3r1gj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Rüzgar olmak istiyorum sana dokunmak için

Güneş olmak istiyorum seni ısıtmak için

Ateş olmak istiyorum kalbini yakmak için

Aynan olmak istiyorum hep sana bakmak için

Hüzün olmak istiyorum başka aşkların için

Yazın olmak istiyorum soğuk kışların için

Kalbin olmak istiyorum sevgini bulmak için

Aşkın olmak istiyorum hep senle olmak için', 'Rüzgar olmak istiyorum sana dokunmak için Güneş olmak istiyorum seni ısıtmak için Ateş olmak istiyorum kalbini yakmak için Aynan olmak istiy...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Kemal Seçkin']::text[], 8.5, '{"poet":"Yaşar Kemal Seçkin","poet_slug":"yasar-kemal-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/istedigim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peri Masalı', 'peri-masali-yasar-kemal-seckin-kpzcu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ruhum özgür kalmalı

Arınmalı dünyevi dertlerinden

Rüzgarı hissetmeliyim tenimde

Oksijen yakmalı ciğerlerimi

Uçmalıyım uçsuz bucaksız göklere

Kanatlarıma vuran güneşin okşayan sıcaklığı

Sonsuzluk ayaklarımın altında

İpekten işlenmiş güzel bir halı

Sen kollarımda

İşte benim için peri masalı', 'Ruhum özgür kalmalı Arınmalı dünyevi dertlerinden Rüzgarı hissetmeliyim tenimde Oksijen yakmalı ciğerlerimi Uçmalıyım uçsuz bucaksız göklere...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Kemal Seçkin']::text[], 8.5, '{"poet":"Yaşar Kemal Seçkin","poet_slug":"yasar-kemal-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/peri-masali-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidişin', 'gidisin-onder-omur-6x47v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin yokluğunda sevinirken büyüme hızıma

Nerden bilecektim

Bir gün talep enflasyonuna takılacağımı.

Ama olsun, beni bilirsin

Ne maliyetleri düşürebildim

Ne de azalan verimler kanununu yenebildim.

Fakirliğin fasit dairesinde dolanırken, 

Bir azgelişmiş ülkenin

Emek yoğun teknolojisinde buldum kendimi.

Devalüe edilmişken bütün duygular

Bu cari açık neden

Bütün çaresizlikleri ithal ettin giderken

Ve sermaye kaçışlarına göz yumdun

Likidite sıkışıklığı yaşanırken.', 'Senin yokluğunda sevinirken büyüme hızıma Nerden bilecektim Bir gün talep enflasyonuna takılacağımı. Ama olsun, beni bilirsin Ne maliyetleri...', ARRAY['Türk Edebiyatı','Şiir','Önder Ömür']::text[], 8.5, '{"poet":"Önder Ömür","poet_slug":"onder-omur","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gidisin-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yokken', 'sen-yokken-yasar-kemal-seckin-dw6ia', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine hüzün birikti gözlerin gerisinde

Yine geceler gözüktü kalbinin içerisinde

Karanlığım sen oldun, sen ki hep ulaşılmaz

Öyle engeller koydun ki aramıza,  aşılmaz

Sevgin kalbimi yakarken ayrı olmak çok acı

Gülümseyen gözlerindir her derdimin ilacı

O ilaç ki her zaman bir tek bana uzakta

Kalbim düşmüş sevgine, amansız bir tuzakta

Sensizlik zorlaşıyor sevgim her gün büyürken

Hayatım kararıyor seni uzak görürken

Sözlerim bitiyorken şunu bil istiyorum

Sensiz yaşamam imkansız, seni çok seviyorum', 'Yine hüzün birikti gözlerin gerisinde Yine geceler gözüktü kalbinin içerisinde Karanlığım sen oldun, sen ki hep ulaşılmaz Öyle engeller koyd...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Kemal Seçkin']::text[], 8.5, '{"poet":"Yaşar Kemal Seçkin","poet_slug":"yasar-kemal-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-yokken-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimde ki Vurgun', 'yuregimde-ki-vurgun-erol-sen-mug4s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Deniz vurgunları öldürür yürekleri

Ya sevda vurgunları 

İz bırakır neden se vurup geçer öldürmez

Acı çekmek için ıstırap duymak için

Düşlerin ölü doğması gibi

Yaşamın ölüm boşluğuna bakan

Yaşamın düzen döngüsünü bozan

Hayatın yaşanmışına boş bakan

Anlaşılmaz istekler büyüten

Geç kalan sevdalar

Yaşamın evrensel döngüsüne bakan

Ama görmeyen.......

29.01.03', 'Deniz vurgunları öldürür yürekleri Ya sevda vurgunları  İz bırakır neden se vurup geçer öldürmez Acı çekmek için ıstırap duymak için Düşleri...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yuregimde-ki-vurgun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçların', 'saclarin-onder-omur-1ej80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artan oranlı vergi tarifesi gibiydi saçların, 

Her okşayışımda saçını

Vergi dilimi biraz daha artıyordu...', 'Artan oranlı vergi tarifesi gibiydi saçların,  Her okşayışımda saçını Vergi dilimi biraz daha artıyordu......', ARRAY['Türk Edebiyatı','Şiir','Önder Ömür']::text[], 8.5, '{"poet":"Önder Ömür","poet_slug":"onder-omur","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/saclarin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara', 'ankara-demirhan-ozdemir-1cign', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yarım kalan bir sevdanın hayali

Böler uykumu olur olmaz 

Sinmişim utangacım

Yeni yetme bıçkınlığım

Ankarada kaldırımlar soğuk

Zamanda utangaç kendince 

Sen karanfil oluyorsun her sabah

Okul çocuklarının ellerinde

Az ilerde eski ankara garı

Bir adam uykulu elleri soğuk

Titrek dudaklarımda bir gurbet türküsü

Benimse ellerim ceplerimde 

Taze bir güvercin ölüsü

Katıksız umutlarım kayboluyor

Sen karanfil oluyorsun her sabah

Ankara karanfil kokuyor

İçimi kaplıyor ısırgan otu

Çıkmaz sokakların çıkmazı

Sebebsiz yolculukların yolcusu

Yitiyorun ankaranın bir köşesinde

Bu kentin bütün çıkmazları seni soluyor

Sen karanfil oluyorsun her sabah

Ankara karanfil kokuyor', 'Yarım kalan bir sevdanın hayali Böler uykumu olur olmaz  Sinmişim utangacım Yeni yetme bıçkınlığım Ankarada kaldırımlar soğuk Zamanda utanga...', ARRAY['Türk Edebiyatı','Şiir','Demirhan Özdemir']::text[], 8.5, '{"poet":"Demirhan Özdemir","poet_slug":"demirhan-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ankara-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sol Gözün Atıyor Yada Kalbin Seyiriyor', 'sol-gozun-atiyor-yada-kalbin-seyiriyor-dogu-cankaya-mk2ac', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sol gözün atıyor yada kalbin seyiriyor

çocuğum ben ve sınıfta kalıyorum

sahi kaçıncı elementtin

kaçıncı elementtiniz siz.. neden söylemediniz

Okuldan kaçardım, sokağında yatardım

tilkiydim

pencerenden mavi alev damlatırdın

bilirdin beni, beslerdin

çocuğun kadar kolay öğrenirdim ama dilim dönmezdi ağzımda

dönmezdi benden sana sözcükler

gülerdin, büyü olurdu.

Titrerdim, korkudan kuş, ceylan, fare

kitlenirdim

çocugun kadar sızardım bacaklarının arasına

ama süt benden sana akardı

iksirime böcek gibi bulanır

dağlanırdın.

Sakındığım kirpiğin ne zaman değdi topuğuma

ki, aldırmazlık dev kanatlarıyla

karanlığım

karanlıktayım', 'Sol gözün atıyor yada kalbin seyiriyor çocuğum ben ve sınıfta kalıyorum sahi kaçıncı elementtin kaçıncı elementtiniz siz.. neden söylemedini...', ARRAY['Türk Edebiyatı','Şiir','Doğu Çankaya']::text[], 8.5, '{"poet":"Doğu Çankaya","poet_slug":"dogu-cankaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sol-gozun-atiyor-yada-kalbin-seyiriyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küskün Kalbe', 'kuskun-kalbe-yasar-kemal-seckin-o1eks', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güneşim doğmuyorken ıssız uzun gecelerde

Işığım olmuştu adın kafiyesiz hecelerde

Yıldızlar kadar uzak çöl çiçeği kadar yanlız

Sensizliğin ölümümdü. Bıçak gibi insafsız

Bir kelepçeydi sevgin, uğruna ölmeye değerdi

İnan sevgim karşısında dağlar boyun eğerdi

Karşılıksızdı sevgim hiç bir şey beklemedim

Sevmendi tek isteğim, bire bin eklemedim

Hala aynı hedefim; inatla sadece sen

Ne kadar sevinirdim bana bir gülümsesen

Hiç boşuna somurtma derdini biliyorum

İstesem de bırakamam, seni çok seviyorum', 'Güneşim doğmuyorken ıssız uzun gecelerde Işığım olmuştu adın kafiyesiz hecelerde Yıldızlar kadar uzak çöl çiçeği kadar yanlız Sensizliğin öl...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Kemal Seçkin']::text[], 8.5, '{"poet":"Yaşar Kemal Seçkin","poet_slug":"yasar-kemal-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kuskun-kalbe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecikerek Aranan, Aranıp Sessizce', 'gecikerek-aranan-aranip-sessizce-dogu-cankaya-sjf0j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gecikerek aranan, aranıp sessizce

konuşamadan kapanan

         soruları biriktirip, zamanın da

          hatırlayamadan, sessizce kapanan telefondan sonra

geldiğin güne kadar ağladım

                                  ağladım içime yazarak.

Siyah kan biriktirdim boğazımda

         etimi büktüm, morarttım, kulaklarımı çımlattığında.

Kan kardeşim

        tülünü açar gibi araladım güzel yazılarını

            senden bahsettim, bir tutam saçını

                                           bir damla kanını istedim

        tevazu ile paylaştım özlemini

         seni anlattım, kanını

 derin ve kokusuz kanını yazdım sırtıma

yyuvarlandım, sürülendim, sürüklendim.

Susadım su içtim

          geldiğin güne kadar içtim

acıktım, memeni aradım, 

          dokunarak, dokuyarak 

                                            karnımı doyurdum.

            Sordum,      

            geldiğin güne kadar kendime

neden ağlıyorsun boşluğa

                                         boşuboşuna..', 'Gecikerek aranan, aranıp sessizce konuşamadan kapanan          soruları biriktirip, zamanın da           hatırlayamadan, sessizce kapanan te...', ARRAY['Türk Edebiyatı','Şiir','Doğu Çankaya']::text[], 8.5, '{"poet":"Doğu Çankaya","poet_slug":"dogu-cankaya","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gecikerek-aranan-aranip-sessizce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansız Aşk', 'i-mkansiz-ask-sair-melissu-jnu2u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bütün kırmızı güller taklit için açıyorlar güzel gülüşünü...

Ve yıldızlar, denizlerin soğuk dalgalarından çok, 

sıcak gamzelerine düşmeye hevesliler yakamoz olmak için...

Saçlarını tarayabilme telaşında rüzgar...

Güneş kıskanıyor seni; 

evrenin ışık kaynağı olma tekeline son verdiğin için...

Baharın rengarenk çiçekleri, ve güzel kokusu ve içlere ferahlık veren havası sadece ama sadece senin güzelliğine bir özenti, inan...

Ve Sevgili ben; 

Ne kırmızı bir gülüm seni taklide çalışabilen ve ne asla bir yıldızım ki düşeyim gamzelerine yakamoz olayım...

Belki zaman zaman saçlarını taramak hevesine kapıldım 

rüzgardan daha ziyade...

Ama asla bu onuru bana vermek zorunda olduğunu  düşünmedim.

D ü ş ü n e m e d i m... 

Ve güneş gibi kıskanmadım seni...

Ben sadece ay olmak istedim ışığından faydalanabilmek için...

Kıskandımsa ay`ı kıskandım sadece...

Ve senin ışık verdiklerini...

Sevgili ben görmeye doyamadığım, doyasıya göremediğim senin yerine baharı da koymaya çalışmadım.

Baharın güzelliğinin sana eşdeğer olabileceğine inanmadım.

Ümitsizce gelmeni beklediğim günlerin sonunda, 

seni özlemenin ve beklemenin bana verilmiş bir hak olup olmadığını düşündüm sadece...

Evet baharı özleyebilirdim belki, 

Ama seni özleyebilme iznim var mıydı? ...

B i l m i y o r u m...

Ama sevgili; 

Ne bir kırmızı gül ve ne de bir yıldız olmasam da...

S E N İ S E V İ Y O R U M.

Ve yüreğimi isyana kaptırıp senden izin almadan ve sürekli; 

S E N İ Ö Z L Ü Y O R U M...', 'Bütün kırmızı güller taklit için açıyorlar güzel gülüşünü... Ve yıldızlar, denizlerin soğuk dalgalarından çok,  sıcak gamzelerine düşmeye he...', ARRAY['Türk Edebiyatı','Şiir','Şair Melissu']::text[], 8.5, '{"poet":"Şair Melissu","poet_slug":"sair-melissu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/imkansiz-ask-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzüntü Lacivert Sestir Aklımda Yer Etmiş', 'uzuntu-lacivert-sestir-aklimda-yer-etmis-dogu-cankaya-9ot02', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Üzüntü lacivert sestir aklımda yer etmiş

    mühürlenmiş donmuş onüç emir

kristal bir ses parçalanmış gitmiş aklımdan

                                                       sanki lacivert müzik

 artık sanatım mırıldandıgım buzul parçaları gibi nemli

   kırılıp düşüyor zaman parçacıkları

     usul usul yaklaşıyor kutuplar.

Kıyamet lacivert rengi ile aklımda

  sağlamasını yaptığım melek hesapları

    kendimide katsam hep bir eksik.

Şu köşeden dönüp git

  kurtul bu sera etkisinden

    bitsin artık cebindeki leblebiler

    bitsin artık onları yıldız yapma hezeyanın.

Bırak herşeyi şimdi

çık git bu labirentten

                                  kızının hayali de yeter

                                  gerçekten var olduğun dokunuşu da yeter.

Ağladığın boşluk hala lacivertse

gözyaşındandır, sayılamayacak kadar büyük

                           boğulamayacağın kadar da hafif', 'Üzüntü lacivert sestir aklımda yer etmiş     mühürlenmiş donmuş onüç emir kristal bir ses parçalanmış gitmiş aklımdan                       ...', ARRAY['Türk Edebiyatı','Şiir','Doğu Çankaya']::text[], 8.5, '{"poet":"Doğu Çankaya","poet_slug":"dogu-cankaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/uzuntu-lacivert-sestir-aklimda-yer-etmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatımın Anlamı Sen', 'hayatimin-anlami-sen-yasar-kemal-seckin-mecdp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Daha seni görünce kalbim yedi bir vurgun

Amansız fırtınalar senin yanında durgun

Uğraştırma, deli gönlüm aldığı yoldan yorgun

Gör sen beni, inan ki görmenin zararı yok

Sadece sen varsın, ki hayatımın anlamı

Vücudumun ihtiyacı, damarlarımın kanı

Gir şu kalbin içine seven bir kalbi tanı

Hisset beni, inan ki hislerin zararı yok

Yokluğun ölüm gibi varlığındır ilacı

Seni seven kalbime ne olur biraz acı

Unutma sensin her zaman benim başımın tacı

Sev sen beni, inan ki sevmenin zararı yok', 'Daha seni görünce kalbim yedi bir vurgun Amansız fırtınalar senin yanında durgun Uğraştırma, deli gönlüm aldığı yoldan yorgun Gör sen beni, ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Kemal Seçkin']::text[], 8.5, '{"poet":"Yaşar Kemal Seçkin","poet_slug":"yasar-kemal-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hayatimin-anlami-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Adına', 'sevgi-adina-sair-melissu-38atk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen hayatıma girmeden önce zaman geçmek bilmezdi.

Bugünü zorla yaşar, yarını düşünmek bile istemezdim.

Çünkü bilirdim ki yine sabahım güneşsiz olacaktı.

Her yaşadığım mutluluğun ardından, ağlamaktı payıma düşen.

Sanki yaşadığım mutluluklar geçici olmaya mahkum, gözlerimde sürekli ağlamaya yeminliydi.

Hep yarım kaldı sevgilerim bunca zaman. 

Ne ömürlük sevdim, ne de bir ömür sevildim.

Yaşadığım her eksik sevgide, uzaklaştım gerçek sevgilerden.

Artık gözlerim bakışlardan uzak, 

Ellerim dokunmaya ürkek, 

Yüreğimse tekrar sevemeyecek kadar yaralıydı.

Gönlüme kilidi vurmuştum çoktan.

Ölümü bekleyen hastalar gibi, yalnızlığa vermiştim kendimi.

Yaşadığım zoraki akşamların sonunda çıkmıştın karşıma.

Yüzün o kadar temiz o kadar huzur vericiydi ki, gönlümün kilidini kırıp atmamak mümkün değildi.

Yalan da olsa duyguların, kanmak istedim.

Anlık da olsa yaşayacağım mutluluk, hazırdım senin için gözyaşı dökmeye.

İhtiyacım vardı, yalan da olsa sevilmeye.

Yüreğimde büyüttüğüm korkularla başladım bu sevdaya.

Niyetim bu korkuları yok edip benim sana, senin de bana aşık olmandı.

Gerçek sevgiyi sende bulup, bu sevgiyi sadece seninle paylaşmak adınaydı.

Yalanlarla dolu bu dünyada, tek gerçeğim olmalıydın benim.

İçinde bulunduğum bu karamsarlığın sonunda, ışığım ilan etmeliydim seni.

Kalbimin sevgiye olan düşmanlığı, sana duyacağım büyük sevgiye bırakmalıydı yerini.

Zaman yanında su gibi akmalı, seni göreceğim başka bir zamanı heyecanla beklemeliydim.

Senin bana duyacağın sevgide büyük olmalıydı elbette.

Beni gördüğün zaman ellerin titremeli, ayrı bir heyecan hissetmeliydin.

Senin için mutluluğun adı; benimle eşit olmalıydı.

Gözlerime her baktığında, tekrar aşık olmalıydın bana.

İsmim söylendiği an, bana duyduğun sevgi gözlerinden okunmalıydı.

Öyle büyük bir sevgi yaşamalıydık ki, 

Azrail bile bizi ayıramamalıydı.

Şu an uğruna ölecek kadar sevdiğim ve uğruna ölecek kadar sevenimsin.

Zoraki yaşadığım günler, seninleyken bitmesini asla istemediğim günler olmuştu.

Seviyordum işte seni çıkarsızca ve seviliyordum artık karşılık beklenmeden.

Sen yokken tek dostum olan yalnızlık, seni kıskanıp terk etmişti beni.

Artık hayata güzel gözlerle bakıyor, seninle yaşadığım mutluluğun tadını çıkarıyorum.

Yalanlardan uzak dünyamda, sadece seninle yaşıyorum.

Gözlerim sana öyle mühürlenmiş ki, inan başkasına sana baktığım gözlerle bakamıyorum.

Kalbim sevginle öyle dolu ki, senden başkasını sevemiyorum.

Sana sesleniyorum ey sevgili! 

Ben seni bir günlük değil.

Ben seni yalanlarla değil.

Ben seni unutmak için değil, bir ömür boyu sevilmek umuduyla seviyorum.

Hadi durma! 

Eğer sevgimin büyüklüğüne inanıyorsan; sarıl bana ve sende beni sevdiğini haykır bütün dünyaya...', 'Sen hayatıma girmeden önce zaman geçmek bilmezdi. Bugünü zorla yaşar, yarını düşünmek bile istemezdim. Çünkü bilirdim ki yine sabahım güneşs...', ARRAY['Türk Edebiyatı','Şiir','Şair Melissu']::text[], 8.5, '{"poet":"Şair Melissu","poet_slug":"sair-melissu","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/sevgi-adina-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanatıncaya kadar kanatlarını', 'kanatincaya-kadar-kanatlarini-dogu-cankaya-96v2d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kanatıncaya kadar kanatlarını

  deliğinin kanatlarını

ağzının arzu kanatlarını

sırtında kaşınan iki noktayı birleştiren kanatlarını

çırp, çırpın, çarp, çürüt

ama kanatma, kapatma.

Kullandığım dil, hani beğendiğin

ata yadigarı

bin suların altında sararan

saray duvarlarının içine gizlenen

bin kilitlerle engellenen

 delişmen ve deliren şehzadelerden yadigar.

Kullandığım dil hani sarsakça ama ne istediğini bildiğin

ucunda biber gibi kibirini de taşıyan

o dehlizlerini ıslattığında, elmas parıldar

elma parıldar, gözü parıldar yılanın.. –işte o

Kanatıncaya kadar kanatlarını yaladığım

birdenbire kuzeye kırdığım dümenin sırtı gibi

sırtındaki o iki noktanın kabuk bağlaması

zamanın, yine geçmesi zamanın.

Bükülüp eğildiğinde, kırılma acısına dayanamadığında

bükülüp eğildiğinde zaman..

ta ki kendiliğinden kanar kanatların

içine girer gibi eğildiğinde zaman..', 'Kanatıncaya kadar kanatlarını   deliğinin kanatlarını ağzının arzu kanatlarını sırtında kaşınan iki noktayı birleştiren kanatlarını çırp, çı...', ARRAY['Türk Edebiyatı','Şiir','Doğu Çankaya']::text[], 8.5, '{"poet":"Doğu Çankaya","poet_slug":"dogu-cankaya","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kanatincaya-kadar-kanatlarini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgenin Üzerine Gölgemi Koydum, u yüzden kızdın biliyorum', 'golgenin-uzerine-golgemi-koydum-u-yuzden-kizdin-biliyorum-dogu-cankaya-37iwi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gölgenin üzerine gölgemi koydum, bu yüzden kızdın biliyorum

      böyle daha karanlık olduğunu bende anlıyorum

    Gölgenin üzerine gölgemi koydum diye kızdın biliyorum

                                                              anlıyorum üstelik

                                               böyle daha karanlık olduğunu

             ve günün daha açmadan bittiğini

              hayallerinin bittiğini, 

               doğunun şehirlerinin

                doğunun geçitlerinin

                 doğunun masallarının

                  doğunun denizlerinin

               

                   merkezde, 

               en merkezde, ben merkezde  olduğunu 

               anlıyorum, karanlık oldugunu biliyorum

  Sen

     bunları bilmeyen, bilmediğini bilmeyen sen

     gölgesini tartan, ölçen

     gölgesini süsleyen sen

     gölgesini oynayan, gölgesiyle oynayan sen

     gölge oyunu sanat değildir, 

       çünkü yoktur gölgenin merkezi.

                                     Ben merkezi.', 'Gölgenin üzerine gölgemi koydum, bu yüzden kızdın biliyorum       böyle daha karanlık olduğunu bende anlıyorum     Gölgenin üzerine gölgemi ...', ARRAY['Türk Edebiyatı','Şiir','Doğu Çankaya']::text[], 8.5, '{"poet":"Doğu Çankaya","poet_slug":"dogu-cankaya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/golgenin-uzerine-golgemi-koydum-u-yuzden-kizdin-biliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-yasar-kemal-seckin-352zj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Düşlerim uzak ufuklarda

Dalgın ve içine kapanmış beynim

Yıldızları görmüyor gözlerim

Ne soğuk balkonumun taşları

Ne rüzgar dokunuyor bana

Üşüme sınırını çoktan aşmışım

Ruhumun soğukluğuyla kıyaslanamaz vücudum

Düşüncelerimde yine sen

Sevgimi üzüntümle birleştiren

Acılarımı, üzüntülerimi ve seni

Bir damlaya sığdırıyorum

Yanağımdan süzülen bir damla yaşa

Kopup düşüyor bedenimi terkederek

Islatıyor balkon taşlarını

Ağlamıyorum. Hayır

Gözlerimden süzülen sensin

Balkonum olduğundan büyük gözüküyor

Sense küçücük bir noktacık

Sonra son bir veda anlamı taşıyan bakışımla

Balkonu yalnız bırakıyorum gözyaşımla', 'Düşlerim uzak ufuklarda Dalgın ve içine kapanmış beynim Yıldızları görmüyor gözlerim Ne soğuk balkonumun taşları Ne rüzgar dokunuyor bana Üş...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Kemal Seçkin']::text[], 8.5, '{"poet":"Yaşar Kemal Seçkin","poet_slug":"yasar-kemal-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gece-63-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Seviyorum ki...', 'oyle-seviyorum-ki-sair-melissu-ndjdt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karşımdasın. Elimi uzatıp dokunabiliyorum sana.

Ne büyük mutluluk bu... Gördüğüm en güzel şeysin.

Senden öte tanımladığım başka hiçbir şey yok.

Her şey senin adınla anılıyor benim dünyamda. Bütün çiçekler sen, bütün yıldızlar sen... Bir sanat eserisin, bakmaya doyamadığım. Allah''ın bana armağanısın ve artıyor her geçen gün sana hayranlığım. Yüzünde kuşlar, gözlerinde hayatın ta kendisi var. Öyle gerçeksin ki... Gözümü açıyorum sen, kapıyorum sen... Hiç bitmeyen bir  serüven sanki..

Günümün en tatlı anı, uykumun en tatlı rüyası... Seni soluyorum, havadasın. Seni kokluyorum, doğadasın.

Hele şimdi sonbaharsın. Ya da sonsuz bahar.

Seni yaşıyorum, canımdasın. Canımsın... Sarılsam sana, bin yıl geçse, bir an bile ayrılmasak... Ten tene, yürek yüreğe sonsuz baharın en aşk dolu iki yaprağı olsak... Ağaç ağaç gezip, yeşersek, açsak.

Yere düşsek, kalksak... Seni bilsem, bir tek seni.

Seni görsem, bir tek seni. Sesin sarhoş etse beni...

Öyle içimdesin ki... Bir saniye iste benden sensiz geçirdiğim, veremem. Sensiz geçecekse geçmesin zaman, istemem. Seninle yeniden doğdum, yeniden doğuşun kanıtıyım ben. Senden önce geçen zamanı, sana ulaşmak için yürüyerek geçirmişim, kimmişim bilememişim. Şimdi başımı çevirip geriye bakmıyorum bile. O yol yüründü ve bitti, artık seninle yürünecek bambaşka bir yol var önümde. Yorgunluk nedir bilmeyeceğim, hiç şikayet etmeyeceğim ve bir tek adım bile tökezlemeyeceğim uzun, aşk dolu bir yok...Öyle aklımdasın ki...Ah, sensiz kalmıyor muyum bazen yıkasım geliyor gördüğüm bütün duvarları.

Ardında seni bulurum sanıyorum. Ne ayrı koyduysa bizi, zaman ya da yollar, bir kalemde silesim geliyor.

Sana dokunmamı engelleyen ne varsa, bir kadehi yere çarpıp tuzla buz eder gibi parçalamak istiyorum. İsyanım taşıyor, kendi öfkemden korkuyorum. Ve kavuşmak...Bunu düşünmek içimde kırılmış bütün aynaları tamir ediyor. Mavi bir yağmur başlıyor, ıslanıyorum. Maviye boyanıyorum. Öyle özlüyorum ki... Sen ol, hep ol, benimle ol, bende ol...

Sendeyim ben, yüreğimi koydum yüreğinin üzerine.

Aşk bu, başka isim arama. Hem de en koyu, en deli, en tutkulu... Öğreneceğim çok şey var sana dair. Bilmediğim çok şey var. Ama bir şeyi öyle iyi biliyorum ki... Seni öyle çok seviyorum ki...', 'Karşımdasın. Elimi uzatıp dokunabiliyorum sana. Ne büyük mutluluk bu... Gördüğüm en güzel şeysin. Senden öte tanımladığım başka hiçbir şey y...', ARRAY['Türk Edebiyatı','Şiir','Şair Melissu']::text[], 8.5, '{"poet":"Şair Melissu","poet_slug":"sair-melissu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/oyle-seviyorum-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'S ı k ı l d ı m', 's-i-k-i-l-d-i-m-erol-sen-isn8b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bitmez isteklerden sıkıldım	

Bütün beklentilerden gerildim	

Ben özgür olmak istiyorum	

Ben özgürlüğümü seviyorum	

	

Seviyorsam kendimce sevmek 	

İstiyorsam erol ca istemek	

Sevişirken kendimce sevmek	

Yapacaksam erol ca yapmak	

	

Sınırsızlık istiyorum uçarcasına	

Hayatımın zaten sınırları var	

Yaşantımın sıkıntıları bitmez	

Neden sözünü duymak istemiyorum	

	

Yaşam düzenimi bozmak isteyenlerden	

Kendini ön plana çıkaranlardan	

Tabuları olanlardan	

S I K I L D I M....	

	

Annesinin sözünden çıkmayanlardan	

Arkadaşlarınca yönlendirilenlerden	

Maddiyatçılardan	

S I K I L D I M....	

	

Ben ben ben diyenlerden  sıkıldım

Gönlümce yaşamak istiyorum	

Sıkıntılarıma çare olmak	

Dertlerime derman olmak	

	

Sevgime dağlar delmek	

Aşkıma nedensiz kızmak	

Naralar atmak ıistiyorum	

Düşüncelerden kurtulmak	

	

Ama EROL  ca	

	

29.01.03', 'Bitmez isteklerden sıkıldım	 Bütün beklentilerden gerildim	 Ben özgür olmak istiyorum	 Ben özgürlüğümü seviyorum	 	 Seviyorsam kendimce sevm...', ARRAY['Türk Edebiyatı','Şiir','Erol Şen']::text[], 8.5, '{"poet":"Erol Şen","poet_slug":"erol-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/s-i-k-i-l-d-i-m-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstiklal Caddesinde', 'i-stiklal-caddesinde-yasar-kemal-seckin-axxfa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dalmıştım. Gidiyordum ellerim ceplerimde

Bir hayale rastladım İstiklal Caddesi''nde

Bir hayal, ki yıllarca kalbimi dağlamıştı

Deli gönlüm çok akşam hep ona ağlamıştı

İradem miydi bilmem beni uzaklaştıran

Gülümsememi dondurup kalbimi taşlaştıran

Uzattığı sıcak eli bir an boşlukta kaldı

İçimdeki fırtınalar işte o an uyandı

Gülümsedi, ki o gülüş sadece ona hastı

Etkisini biliyordu, beni derinden sarstı

Gözlerinin ateşi hiç mi hiç değişmemişti

Deli gönlüm peşine boşuna düşmemişti

Hiç bir şey anlamadım söylediği sözlerden

Gözlerimi kaçırmıştım o kor gibi gözlerden

Sonra geç kaldım dedim sesim hayli yavaştı

Oysa hiç işim yoktu, dilim benle savaştı

Yola koyuldum ama gittiğim yeri bilmeden 

Gözümde biriken ufacık bir damlayı silmeden

Evimdeyken bile hayali karşımdan gitmemişti

Bitti sanmam nafileydi, aşkım hiç bitmemişti', 'Dalmıştım. Gidiyordum ellerim ceplerimde Bir hayale rastladım İstiklal Caddesi''nde Bir hayal, ki yıllarca kalbimi dağlamıştı Deli gönlüm çok...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Kemal Seçkin']::text[], 8.5, '{"poet":"Yaşar Kemal Seçkin","poet_slug":"yasar-kemal-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/istiklal-caddesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Özledim Seni..', 'cok-ozledim-seni-sair-melissu-hq811', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kış günlerinde mısır patlatıp sadece birbirimize sarılıp oturmak için seyrettiğimiz abuk Amerikan filmlerini

Bana ''prensesim'' deyip burnumu sıkmanı

Geceleri beni uyutmak için anlattığın küçük masalları

Geç saatlerde eve geldiğimde kokusu sokaklara dağılan, üşenmeden yemek kitaplarından bakarak 

pişirdiğin leziz yemekleri 

Tasarımlarıma çay dökmeni

Son sigaranı benimle paylaşırken homurdanmanı

Balkonda içtiğimiz sabah çaylarını

Seninle yalnız kalmak istediğimde ''dış kapının anahtarını yine kaybetmişim, tüh içerde kilitli kaldık'' numaralarımı ve ardından senin o ilginç mimiklerinle söylediğin ''şımarık şey'' lafını

Kalabalık arkadaş topluluklarımızda odanın en uzak köşelerindeyken ellerinle kalbinin ne kadar 

hızlı attığını anlatmaya çalıştığın anları

Evimize yaklaşırken geriye doğru saymanı, kendini güç bela koltuğuna attığında koltuğun ayağını kırmanı

''Çok çok prensesim, hem de çoook çok'' demeni

Pijamalarını kaldırdığın yeri sürekli unutmanı

Her makyaj yaptığımda illa bir kusur bulmanı

Çoraplarımdan kukla yapmanı

Bana hissettirmeden fotoğraflarımı çekmeni ve onları tab ettirdikten sonra yastığımın altına bırakmanı

''Biz'' kavramını bana açıklamanı

Birlikte badana yapıp evimizi temizlemeyi

Odamızdaki dolaplara, çekmecelere, kıyafetlerimin arasına sakladığın sevgi sözcükleriyle dolu küçük not kağıtlarını

Üzüldüğüm, mutsuz olduğum anlarda dizlerine yatıp ağlamayı, beni neşelendirmek için türlü şaklabanlıklar yapmanı ve her zaman beni mutlu etmeyi başarabilmeni

Saçlarımı taramanı, 

Traş köpüğünü saç şekillendirici köpükle karıştırmanı

Saçlarını tararken kendine övgüler yağdırmanı

Kravatını bağlarken bana sımsıkı sarılıp defalarca burnumu öpmeni

Küçük tartışmalarımızda yatağa oturup o masum tavrınla ayıcığımızı kucağına alarak beni şikayet etmeni

İnsanlara duyduğun saygıyı, 

Çay fincanıma sigaranın külünü silkelemeni, 

Tavlada hep bana yenilmeni, 

Kulağıma fısıldadığın sözleri, 

Her sabah giyeceğin kıyafetleri hazırlamayı, 

Kazandığın her davandan sonra ''Aklımda olmasan kazanamazdım'' demeni

Annemle saatlerce süren telefon konuşmalarımızı kıskanmanı

Odamızı beyaz güllerle donatmanı

Derslerimi anlayabilmek için sorduğun komik soruları

Saçlarını yıkamayı, 

Sınav öncelerinde arkadaşlarımla ders çalışırken bize çay servisi yapmanı

Resimlerimi çizmeni, 

Yastığa dökülen saç tellerimi bir zarfta saklayarak yanında taşımanı

Babama karşı abartılı hoş sözler söylemeni

Sadece gözlerimizle konuştuğumuz zamanları

Beni, benden fazla düşünmeni, 

Elektronik aletleri tamir ederken sigortaları attırdığın zamanlardaki yarı şaşkın yarı suçlu ifadeni 

Fincanlarımızın üstüne ismimizi yazmanı

Temizliğe düşkünlüğünü, 

Hastalandığım zamanlarda etrafımda pervane olmanı ''minik bebeğime uf olmuş'' demeni, 

Paylaşmaya ihtiyaç duyduğum mutlu mutsuz her anımda seni yanı başımda bulabilmeyi

Pırıltısının yüzüne yansıdığı kalbini, 

Pembe dizileri seyrederken televizyonun sesini kapatıp dublaj yapmanı, 

Ellerinle çiçekler çizmeni, 

Seni seyretmeyi, 

Evimizden son kez çıkarken ''Bir hafta çok zor geçecek ama geçecek prensesim'' dediğin anı...

Her şeyinle seni, her şeyiyle bizi..., 

Çok özledim birtanem..', 'Kış günlerinde mısır patlatıp sadece birbirimize sarılıp oturmak için seyrettiğimiz abuk Amerikan filmlerini Bana ''prensesim'' deyip burnumu ...', ARRAY['Türk Edebiyatı','Şiir','Şair Melissu']::text[], 8.5, '{"poet":"Şair Melissu","poet_slug":"sair-melissu","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/cok-ozledim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tatilde', 'tatilde-yasar-kemal-seckin-kgxgp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşüncelerimi emanetçiye bıraktım

İstanbul''dan uzaklaşıp tatile çıktım

Şehrin boğucu kokusunun yerine

Çiçeklerin saflığını kokladım

Berrak bir gökyüzü sildi kalbimin bulutlarını

Gece bir yorgan gibi çökerken

Yıldızlar ısıttı içimi

Bir elim yağda bir elim balda der gibi

Bir elime huzuru aldım

Bir elime neşeyi

Çıplak ayakla koştum kumlarda

Sıcak kumlar ayaklarımı yakarken

Ayakkabı aramadım

Müzik yerine dalgaların sesini dinledim

Küçük bir derede ben balıkları seyrettim

Onlar da beni

Boyumdan büyük ekinlerin içinde kayboldum

Sıkı bir yağmurdan sonra

Üstümün ıslanmasına aldırmadan

Çimenlerde yuvarlandım

Yağmurdan sonraki toprağın kokusunu içime çektim

İşte bir tatili böyle tükettim', 'Düşüncelerimi emanetçiye bıraktım İstanbul''dan uzaklaşıp tatile çıktım Şehrin boğucu kokusunun yerine Çiçeklerin saflığını kokladım Berrak b...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Kemal Seçkin']::text[], 8.5, '{"poet":"Yaşar Kemal Seçkin","poet_slug":"yasar-kemal-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/tatilde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurda Kaybettiklerimize', 'yagmurda-kaybettiklerimize-yasar-kemal-seckin-bipix', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmur yağıyor şehrimin sokaklarına

Camlarıma vuran küçük damlaların sesi

Belirsiz bir yönden gelen rüzgarın sesine karışıyor

Gözlerim yerdeki bir noktaya takılı

Damlacıklarla beslenen küçük bir su birikintisi

Kulaklarımda annemin ninnisini hatırlatan yağmurun sesi..

Küçük damlalar gücünden emin

Yokuş aşağı akan dereler oluşturuyor

Bir nuh tufanı yaratmak ister gibi

Birleşip kükreyen öfkeli bulutlar mağrur

Kimini evsiz, kimini annesiz, babasız, kardeşsiz

Bırakmak ister gibi yükleniyor şehrime

Sizin suçunuz der gibi

Yağmurun şiddetiyle son yaprakları kopuyor

Sonbaharı yaşayan ağacımın dallarının

Her yaprak yaşamdan kopan bir can gibi

Yağmurlarda kaybettiğimiz..

Saçma sapan nedenlerle kaybettiğimiz canları düşündükçe

Gözlerim yaşarıyor

Kazanmamız gereken bir savaşı kaybettiğimiz için

Bir kaşık su! ya canları verdiğimiz için

Koluma kara bir bez parçası bağlıyorum

Yağmur bize gülerken ben size ağlıyorum', 'Yağmur yağıyor şehrimin sokaklarına Camlarıma vuran küçük damlaların sesi Belirsiz bir yönden gelen rüzgarın sesine karışıyor Gözlerim yerde...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Kemal Seçkin']::text[], 8.5, '{"poet":"Yaşar Kemal Seçkin","poet_slug":"yasar-kemal-seckin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yagmurda-kaybettiklerimize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağladım', 'agladim-nizamettin-sakin-9tw9s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağladım dün gece

İçin için ağladım

Üstlerine yağacak 

Bombaları beklerken

Yavrusuna verecek 

Bir damlacık sütü yok

Çaresizlik içinde

Çırpınan o anneyi

Düşündüm irkildim

Onun için ağladım

Annesinin kucağında

Şefkat bekleyen çocuk

Bir gece ansızın

Bombalarla ölecek

Düşündüm irkildim

Onun için ağladım

Gün yüzünü görmeden

Koparılan çiçeğe

Menekşeye sünbüle

Karanfile ağladım

Ben de çaresiz mefluç

Ağlanacak halime

Hıçkırarak ağladım', 'Ağladım dün gece İçin için ağladım Üstlerine yağacak  Bombaları beklerken Yavrusuna verecek  Bir damlacık sütü yok Çaresizlik içinde Çırpına...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Sakin']::text[], 8.5, '{"poet":"Nizamettin Sakin","poet_slug":"nizamettin-sakin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/agladim-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hey Arkadaş Sağol! ...', 'hey-arkadas-sagol-tuba-karacan-4j1yk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tam zamanında bitirdin aşkımızı biliyor musun? 

Tam da zirvesindeyken sana olan sevgimin 

Ve helakını hazırlarken kendi kendimin 

Bana yapmış olduğun son iyilikse, 

Kahrettiğin benliğimde oluşan yeni bir duygu; 

Şairliğim...', 'Tam zamanında bitirdin aşkımızı biliyor musun?  Tam da zirvesindeyken sana olan sevgimin  Ve helakını hazırlarken kendi kendimin  Bana yapmı...', ARRAY['Türk Edebiyatı','Şiir','Tuba Karacan']::text[], 8.5, '{"poet":"Tuba Karacan","poet_slug":"tuba-karacan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hey-arkadas-sagol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'IZDIRAP', 'izdirap-nizamettin-sakin-abgvf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Izdırap tümüyle işledi

Can bize ait değil artık

Geceler boyu ızdıdabın

Sabah sonu diye umardık

Biten her gecenin ardından

Hergün bin dert ile uyandık

Gözlerimiz uykusuz yorgun

Şekva değil ama usandık

O''na tevekkül  ve sabırla

Ancak bu kadar dayandık

O''ndan geldi deyip derdimiz

Şifayı da ona inandık', 'Izdırap tümüyle işledi Can bize ait değil artık Geceler boyu ızdıdabın Sabah sonu diye umardık Biten her gecenin ardından Hergün bin dert il...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Sakin']::text[], 8.5, '{"poet":"Nizamettin Sakin","poet_slug":"nizamettin-sakin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/izdirap-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'FİTNE', 'fi-tne-nizamettin-sakin-pw4sw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir vakitler kölesi vardı efendinin

Fakat fitnesi meşhurdu kölenin

Satıp kurtulmak istedi fitneci köleden 

Satmış olarak çıktı o bir alışverişden

Satar iken meşhur fitnesini söylemişti

Buna da alıcı efendi gülüvermişti

Ne çıkar canım şunun fitnesinden

Ateş olsa başka yakmaz kendisinden

Dedi de götürdü köleyi evine

İki ay kilit vurdu köle sanki diline

Allah rızası için mı susuvermişti

Ama iki ayda ona çok gelivermişti

Artık sabredemedi kaynattı fitmeyi

Gitti kandırdı masume hanımefendiyi

Kocanız başkasıyla evlenecek hanımım

Düşündükçe sizin için yanarım

Kölenizim sizi kurtarmak isterim dertten

Bana üç kıl lazım efendinin çenesinden

İşte çare şu usturayı alda sakla sen

Zamanı gelince işaret edeyim sana ben

Efendi eve geldi hiçbir şeyden habersiz

Köle ona da koştu; öleceksiniz

Efendim hanım sizin için tuzak hazırlar

Size zarar verecek efendim muzırlar

Hem size ne kadar dığruyu söylesem de ben

Köle sen bir fitnecisin, dersin buna rağmen

Ama gerçeği bilmek istersen bir dene bak

Hanım hazırlandı ki sizi boğazlayacak

Efendi denemek için yatağa uzandı

İşte o fitne anı görülecek zamandı

Horultular gelince uyuyan efendiden

Hanıma usulca işaret oldu köleden

Keskin ustura ışıldıyordu ışıl ışıl

Az sonra kanlar dökülecekti şırıl şırıl

Hanım uzatmıştı ki usturayı boğaza

Fakat zavallıcık kendi düştü tuzağa

Efendi fırladı aldı elinden bıçağı

Orada kesilecek olan halen sağdı

Bütün fitneyi mahalleye o yaydı

Koşturdu anlattı olan biteni kaynına

Onlarda geldi girdiler eniştenin  kanına

Efendinin çevresi akrabası da geldiler

Mahalleyi tuttular kann seline verdiler

Fitneci köle fitneyle bakın neler yaptı

Yedi mahalleyi yuvayı kana ulattı

Fitnesiyle koca dünyasını feda etti

Hem de ebedi sürecek olan ahireti

 Ta başta hata laubeli efendideydi

Fitneci köleyi istihzayla alıverdi

Hisse alın bu kıssadan bakın da

Tedbirinizi alın işin başında', 'Bir vakitler kölesi vardı efendinin Fakat fitnesi meşhurdu kölenin Satıp kurtulmak istedi fitneci köleden  Satmış olarak çıktı o bir alışver...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Sakin']::text[], 8.5, '{"poet":"Nizamettin Sakin","poet_slug":"nizamettin-sakin","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/fitne-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Ve Sen Giderken...', 'eylul-ve-sen-giderken-tuba-karacan-yzezj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen gidiyorsun...

İplik iplik yağmurlar gidiyor ardından...

Karanlık gölgeler, uzun uzadıya kaldırımlar gidiyor...

Bir şehir kalıyor, bir ben bakıyorum ardın sıra...

Bir ağaçtan bir yaprak düşüyor

Gökyüzünden bir yıldız kayıveriyor sonra...

Yaşanmış son hatıra dönünce sessiz köşeden

Aşk değil biliyorum senden kalan ne varsa

Şafak çoktan sökmüş, uyku yitirilmiş

Meğer güneş doğmuş, yağmur da dinmiş 

Elimde kalan sade ıslak bir gülmüş 

Eylül''müş...', 'Sen gidiyorsun... İplik iplik yağmurlar gidiyor ardından... Karanlık gölgeler, uzun uzadıya kaldırımlar gidiyor... Bir şehir kalıyor, bir be...', ARRAY['Türk Edebiyatı','Şiir','Tuba Karacan']::text[], 8.5, '{"poet":"Tuba Karacan","poet_slug":"tuba-karacan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eylul-ve-sen-giderken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladım', 'anladim-i-syan-toprak-mokws', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiç düşünmemiştim

Bu kadar kolay olacağını

Seni öldürmenin

Aklımın ucundan geçmezdi

Gelinlik yerine ak kefene bürüneceğin.

Şimdi ağlıyorum

Ve anlıyorum 

Sevginin gücünü

Nasılda nefrete döndüğünü

Ve bu kadar sevmenin

Adamı katil edebildiğini

Cenazene çelenk gönderdim

Tabutunun altına girdim

Seni omuzumda taşıdım

Üzerine bir kürek toprakta ben attım

Ağladım

Ve anladım

Bu kadar sevmenin 

Adamı katil edebildiğini', 'Hiç düşünmemiştim Bu kadar kolay olacağını Seni öldürmenin Aklımın ucundan geçmezdi Gelinlik yerine ak kefene bürüneceğin. Şimdi ağlıyorum V...', ARRAY['Türk Edebiyatı','Şiir','İsyan Toprak']::text[], 8.5, '{"poet":"İsyan Toprak","poet_slug":"i-syan-toprak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/anladim-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Tılsımı', 'askin-tilsimi-yasemin-senyurt-pzb9c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Midyelerin içindeydi tılsım

Tek başımaydım

Babamın sigarasından otlanıp

Tek bir şarkıyı

Sabaha kadar başa sarmıştım

İçimi acıtanlara inat

Tanın ağarmasındaydı tılsım

Tılsımını aradığım hayatta

Kalkıp bir insana sevdalanmıştım

Tek başımatdım

Ve tılsımın insanda değil

Sevdalanmakta olduğunu

Tek başımalığımda anlamıştım', 'Midyelerin içindeydi tılsım Tek başımaydım Babamın sigarasından otlanıp Tek bir şarkıyı Sabaha kadar başa sarmıştım İçimi acıtanlara inat Ta...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Şenyurt']::text[], 8.5, '{"poet":"Yasemin Şenyurt","poet_slug":"yasemin-senyurt","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/askin-tilsimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-bahar-temmuz-xn1pt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sabah, 

Apansız çalacağım kapını.

Bıraktığımız yerden başlayacağız; 

Hiç ayrılmamış gibi.

Hesabı sorulmayacak

Geçen yılların.

Biliyorum ki, 

Seni sevdiğim sürece

Sende beni sevdin.

Önemi yok ağaran saçların

Bileceğiz ki, 

Yaşanacak  bir ömür var

Önümüzde 

Birlikte!', 'Bir sabah,  Apansız çalacağım kapını. Bıraktığımız yerden başlayacağız;  Hiç ayrılmamış gibi. Hesabı sorulmayacak Geçen yılların. Biliyorum ...', ARRAY['Türk Edebiyatı','Şiir','Bahar Temmuz']::text[], 8.5, '{"poet":"Bahar Temmuz","poet_slug":"bahar-temmuz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hayal-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ben Kaldım', 'bir-ben-kaldim-aziz-ozkoc-eztm4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir ben kaldım gecenin ayazında, 

Sokaklar uykusunun son çeyreğinde.

Aşıklar rüyaların kimsesizliğinde

Atarken son voltalarını, 

Ben gözüm açık bekleyeceğim

Rüzgarın derin adımlarını..

Ben içerken de böyleydim; 

Koparamazdım yıldızları göklerden

Ayı indiremezdim gözbebeklerinden

Sadece dibi delik kadehlerin, 

Anlam yüklü mısraları ilgilendirirdi beni

Ben severken de böyleydim; 

Oturur bir yorgan dibinde, 

Kalbimi sererdim ulu orta

Ağlardım kanayan gözyaşlarıma.

Anlatamazdım gönlümden geçenleri

Sadece haykırırdım ayrılığı seçenleri

        Bir ben kaldım gecenin ayazında, 

        Sokaklar uykusunun son çeyreğinde..', 'Bir ben kaldım gecenin ayazında,  Sokaklar uykusunun son çeyreğinde. Aşıklar rüyaların kimsesizliğinde Atarken son voltalarını,  Ben gözüm a...', ARRAY['Türk Edebiyatı','Şiir','Aziz Özkoç']::text[], 8.5, '{"poet":"Aziz Özkoç","poet_slug":"aziz-ozkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-ben-kaldim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelsen...', 'gelsen-melek-midikoglu-h92hf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gelsen de olur

gelmesen de

yansıdığında 

denizlerdeki 

güneş örtüsü misali

dayanılmaz bir 

renk cümbüşü

deli eder kalbimi

işte sen! 

bir kuşun kanadında

yeşillikler kokusunda

ateş böceğinin musikisinde

ve ateşindesin

sen heryerdesin

gelsen de olur

gelmesen de

Ama gel

Balyoz balyoz gel 

Bir ömür al bir ömür ver

Seni sevmişim ölürcesine

Bakışların yüzüme işlercesine

Dolu dolu gel

Boş boş gel

Ama gel

Seni sevmişim ağlarcasına

Yüreğimi dağlarcasına

Bıçakla gel

Silahla gel

Ama gel

Gözlerim bir daha görsün

Bir ömre bedel', 'gelsen de olur gelmesen de yansıdığında  denizlerdeki  güneş örtüsü misali dayanılmaz bir  renk cümbüşü deli eder kalbimi işte sen!  bir kuş...', ARRAY['Türk Edebiyatı','Şiir','Melek Mıdıkoğlu']::text[], 8.5, '{"poet":"Melek Mıdıkoğlu","poet_slug":"melek-midikoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gelsen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanatçı', 'sanatci-naime-erlacin-i3lqk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yazının uyumunda

biçimin soyutunda

dizelerde renklerde

dilerse ezgilerde

insana varandır sanatçı

aydınlıkta karanlıkta

inanılmaz duyarlılıkta

bir tuhaf doğurganlıkta

ulaşılmaz son tanıkta

insanı sorandır sanatçı

koyu kara bilinçlerde

bilinç ötesi deyişlerde

tinsel ince erinçlerde

bireysel gizleyişlerde

insanı kurandır sanatçı

hep yükümlü sorumlu

az çekingen davacı

dövüşken ve kavgacı

ödün vermez savaşçı

kendini yorandır sanatçı...', 'yazının uyumunda biçimin soyutunda dizelerde renklerde dilerse ezgilerde insana varandır sanatçı aydınlıkta karanlıkta inanılmaz duyarlılıkt...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sanatci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Düğünüm', 'olum-dugunum-ata-bicakci-osgpe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anlatamadım ki aşkı güzele

Bıraktım kendimi şiire, gazele, 

Yıldızlara bakarım eriten kederle

O gidiyorken yaban ele

Anlatamadım ki sana aşkımı türküm

Zevktir bana aşkından ölüm

Sen giderken uzaklara gülüm

Sevginle ben ölürüm, 

İşte bu benim düğünüm.

Ben seni, beni sevesin diye sevmedim.

Ben seni, benim olasın diye sevmedim.

Ben seni, ele gitmeyesin diye sevmedim.

Ben seni, kitap sonunda ölesin diye sevmedim.

Ben seni, bastığın toprağa kurban olayım diye sevdim

Ben seni, ismini anarken  öleyim diye sevdim.

Ben seni, beni yak, beni yık, öldür diye sevdim.

Aşkından ah ettiğimde depremler olsun diye, 

Beni gördüğünde gülünce baharlar gelsin diye, 

Gözyaşlarımdan nehirler oluşsun

Bulutlar gözyaşımla dolsun diye, 

Toprağa dökülen rahmet gözyaşım olsun diye sevdim. 

Gerçekten aşkı tadanlar; kavuşamayanlar, 

Ne mecnun bulmuş leylayı, ne de aslı keremi, 

Ölüm hepsinin vuslatı, 

Onlara göklerde ağladı.

Ben leylayı kıskandırmak için seni sevdim.

Mecnun gibi kavuşmamak için seni sevdim

Seni sevmeye yol bulamadığım için 

Yeni yollar açmak için 

Kerem gibi dağlar deleyim diye seni sevdim.

Bana ilham kaynağı olda şiirler yazayım diye değil, 

Kitaplar yazayım sen türküm ol diye değil.

Gözünün değdiği nesnelere can vereyim diye sevdim

Gülüşünle güllere can ol diye sevdim

Gül bahçende gülünü alamasamda kokunu alayım diye sevdim

Gözyaşlarında yer gök senle ağlasın diye  sevdim.

Alem sevda görsün, aşkı öğrensin diye sevdim, 

Ben seni gül gördüm, güzel olduğun için sevdim.



Güpgüzel sevgiliye ulaşmada basamak 

Mutluluk bende aşkınla ağlamak

Adını anarken dilim, kalbim yanarak

Hakka ulaştırmada basamak ol diye seni sevdim.

Beklemedim zerre kadar zevk

Muradım sana aşktır tek.

Seni bir defa görmek dünyalara değdi

Daha bir daha görmesem de gam eylemem artık

Beni sevsen sevmesen ne çıkar

Seni gönderene sonsuz şükran akar

Sen beni sev diye, ben seni sevmedim

Benim ol, benle öl, diye seni sevmedim

İsmini anarken kalbim çatlasın diye sevdim

Ben seni, gece sabaha mecbur olsun diye sevdim

Ben seni aşkla ölmek nasibim olsun diye sevdim

Ben seni beni hakka uçur diye sevdim

Ben seni, güzeli, aşkı, şiiri, türküyü, ölümü sevdim.', 'Anlatamadım ki aşkı güzele Bıraktım kendimi şiire, gazele,  Yıldızlara bakarım eriten kederle O gidiyorken yaban ele Anlatamadım ki sana aşk...', ARRAY['Türk Edebiyatı','Şiir','Ata Bıçakcı']::text[], 8.5, '{"poet":"Ata Bıçakcı","poet_slug":"ata-bicakci","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/olum-dugunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Aydın', 'ask-aydin-ata-bicakci-d5r7z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün aydın, can aydın, ay aydın.

Hele can özüm beni bir anlayaydın.

Sokakta görünce bir tebessümle bakaydın

İşte o gün, gün aydın sevdam gün aydın.

Merhaba deyip halimi hatırımı soraydın

Kıy canıma, can aydın sevdam can aydın.

Rüyamda gül yüzüne bakaydım

İşte o gece, ay aydın sevdam ay aydın 

Beni sensizliğe bırakaydın

Cehennemlerde yakaydın sevdam yakaydın

Elin ellerinde elin kalaydın

O demde yıkaydın sevdam yıkaydın.

Aşk yarama merhem arayaydın

Mezarımın başında duraydın sevdam duraydın

Ellerinden bir defa tutaydım

Zamanıdır, vuraydın sevdam vuraydın

Ölmüşe ölüm yolunu soraydın

Bahardır gül aydın sevdam gül aydın

Bir ah çekip kainata kafa tutaydım

Sana uzanan elleri kıraydım sevdam kıraydım

Yağmur olup dünyayı sulayaydım

Aşkının ateşiyle kuruyaydım sevdam kuruyaydım

Aşkıma cevap verdiğini duyaydım

Kainatı birbirine kataydım sevdam kataydım

Aşk pazarında ruhumu sataydım

İki dirheme beni alaydın sevdam alaydın

İki günlük dünyada kölen olaydım

Kral benim ruh aydın sevdam ruh aydın

Gözündeki yaşlara ben ağlayaydım

Yaşaman için ölenin olaydım

Dokunduğun bir nesne

Aşkına beste olaydım.

Kokladığın bir kırmızı gül

Coştuğun bir türkü olaydım.

Gözyaşında damla.

yüzünde tebessüm olaydım.

Hele can özüm aşk kafesine beni koyaydın

Sana satılmış ruh olaydım.

Ey ciğerparem sevdiğim, 

Bana bir gel sana kurban olaydım.

Bana bir tüy ver sevgili…

Seni cennetlere uçuran kuş olaydım.

Seni sevene can

Sevmeyene kabus olaydım.

Gel ruhuma dökül en güzel gül.

Asırlara  aşkınla uçuş olaydım.

Hayatımın en güzel baharında

Aşkınla kuruyan olaydım.

Gel sevdiğim ne olur gitme.

Gelişinle artık bende hür olaydım.', 'Gün aydın, can aydın, ay aydın. Hele can özüm beni bir anlayaydın. Sokakta görünce bir tebessümle bakaydın İşte o gün, gün aydın sevdam gün ...', ARRAY['Türk Edebiyatı','Şiir','Ata Bıçakcı']::text[], 8.5, '{"poet":"Ata Bıçakcı","poet_slug":"ata-bicakci","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/ask-aydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığın Kapıları', 'yalnizligin-kapilari-muammer-hacioglu-zrcx6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlk şiirimi gözlerin için yazdım

Bir Haliç vapurunun buğulu camlarına

Çocuklar gibi sevdim seni, bekledim

Kimi gün adını bir çivi gibi çaktım ıslığıma

Kimi gün küçücük ellerimle yalnızlığın kapılarını taşladım

Senin yüzünden yedim ilk yumruğu

Şaraba, sigaraya senin yüzünden başladım.

Sen bir yapraktın benim ağacımda, kopardılar

Mavi kazaklı çocuk daha güzel ıslıklar çaldı sana

Büyük caddelerde büyük hayaller kurdunuz

Sonra bir tren çok uzaklara götürdü sizi

Beni yüreğimden vurdunuz.

Şimdi ben caddelerde, sokaklarda, köprülerde

Serseri bir rüzgar gibi yalnız ve umutsuz

Sensizliğin resmini çiziyorum kaldırımlara

Durup durup bulutlanıyor gözlerim

Sabırsız damlalar titiriyor kirpik uçlarımda

Gidip bir meyhaneye yıkıyorum kendimi

Birkaç bardak kırıyorum avuçlarımda

Bu korkunç yalnızlığı sen yıktın omuzlarıma

Sen kopardın beni insanlardan

Şimdi dalıp dalıp gidiyorsa gözlerim uzaklara

Bakışlarımda nöbet nöbet karanlıklar duruyorsa

Ve içimde dayanılmaz bir sızı

Mutluluğun en büyüğünü duyabilirsin artık

Düşürdün  kaldırımlara göklerdeki yıldızı', 'İlk şiirimi gözlerin için yazdım Bir Haliç vapurunun buğulu camlarına Çocuklar gibi sevdim seni, bekledim Kimi gün adını bir çivi gibi çaktı...', ARRAY['Türk Edebiyatı','Şiir','Muammer Hacıoğlu']::text[], 8.5, '{"poet":"Muammer Hacıoğlu","poet_slug":"muammer-hacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yalnizligin-kapilari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçici Ayrılık Benimkisi', 'gecici-ayrilik-benimkisi-ali-serttas-ycu3d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geçici ayrılık benimkisi, 

İlk yaz çiçeğine gebeyim.

Ağıtlar yakma adıma, 

Ben ölmedim ölmeyeceğim.

Kinle, nefretle anma adımı, 

Seni sevdim hep seveceğim.

Geçici ayrılık benimkisi, 

Güz yağmurları dinince geleceğim.

Goncalar açınca döneceğim.

Geçici ayrılık benimkisi.', 'Geçici ayrılık benimkisi,  İlk yaz çiçeğine gebeyim. Ağıtlar yakma adıma,  Ben ölmedim ölmeyeceğim. Kinle, nefretle anma adımı,  Seni sevdim...', ARRAY['Türk Edebiyatı','Şiir','Ali Serttaş']::text[], 8.5, '{"poet":"Ali Serttaş","poet_slug":"ali-serttas","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gecici-ayrilik-benimkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Yarim', 'deli-yarim-utku-eser-duszl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çoban Yıldızım

Kabına Sığmazım

Yağızım

Nazlı Çiçeğim

Dizimin Dibinde 

Oturan Uslu Çocuğum

Çağlayanım

Canım

Balım

Sonsuzum

Daha İçimdeki Bozkırları 

Bölüşeceğiz Seninle', 'Çoban Yıldızım Kabına Sığmazım Yağızım Nazlı Çiçeğim Dizimin Dibinde  Oturan Uslu Çocuğum Çağlayanım Canım Balım Sonsuzum Daha İçimdeki Bozk...', ARRAY['Türk Edebiyatı','Şiir','Utku Eser']::text[], 8.5, '{"poet":"Utku Eser","poet_slug":"utku-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/deli-yarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-utku-eser-csc2t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen içime sığmayan

Bir güneş

Sen geçit vermeyen 

Çıkmaz sokak

Sen çagların simgesi

Sen yanlızlıgın imgesi

Sen bir tarih

Sen nihavent

Sen namus belası

Sen zalim

Sen haylaz

Uykusu kaçıyor insanın

Seni göremiyince

Ve sen...', 'Sen içime sığmayan Bir güneş Sen geçit vermeyen  Çıkmaz sokak Sen çagların simgesi Sen yanlızlıgın imgesi Sen bir tarih Sen nihavent Sen nam...', ARRAY['Türk Edebiyatı','Şiir','Utku Eser']::text[], 8.5, '{"poet":"Utku Eser","poet_slug":"utku-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sen-214-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun', 'yoksun-utku-eser-m49eg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu benım hihayem, 

Bu benim yanlızlıgım

Bu benim karanlıgım

Işıktan yoksun

Bu kapısız duvar çıkışı olmayan

Bubenim kalbim

Uçsuz bucaksız Sevgi ormanı

Sessiz...!', 'Bu benım hihayem,  Bu benim yanlızlıgım Bu benim karanlıgım Işıktan yoksun Bu kapısız duvar çıkışı olmayan Bubenim kalbim Uçsuz bucaksız Sev...', ARRAY['Türk Edebiyatı','Şiir','Utku Eser']::text[], 8.5, '{"poet":"Utku Eser","poet_slug":"utku-eser","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yoksun-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koca çınar', 'koca-cinar-omer-sevim-gzg84', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir perşembe gününün şafağında

Beyaza bürünmüş minareden

Bir sela sesi yankılandı

Köyümün semalarında

Bir koca çınar devrilmişti

O nur yatağında

Oda kapattı hüzün defterini

Ardından bir sürü hatıra bırakarak

Oda gitti ebediyete doğru

Ardından bir fırtına kopartarak

Sanki

Yeryüzü kıskanıyordu onu

Beyaza bürünmüştü dağ, taş

Toprağı tercih etti bize

Şimdi yalnız topraktır ona arkadaş

O''ndan geldik yine ona döneceğiz

Sanma sen ey dede burda sefa süreceğiz

Ama bu gün ama yarın mutlak yanına geleceğiz

Yanına gelene dek sözlerinle ey dede

bazen güleceğiz bazen hüzünleneceğiz

Seni toprağa verirken

Usul usul kar yağıyordu semadan

Biz yüreği yaralı ayrılırken mezardan

Şefaat diliyordu dudaklarımız

O serveri cihandan', 'Bir perşembe gününün şafağında Beyaza bürünmüş minareden Bir sela sesi yankılandı Köyümün semalarında Bir koca çınar devrilmişti O nur yatağ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevim']::text[], 8.5, '{"poet":"Ömer Sevim","poet_slug":"omer-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/koca-cinar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk', 'mutluluk-ustun-dokmen-jyogl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yol çıkınca her sabah, 

Bulutlara selâm ver.

Taşlara, kuşlara, 

Atlara, otlara 

İnsanlara selâm ver.

Ne görürsen selâm ver.

Sonra cebinden çıkarıp aynanı, 

Bir selâm da kendine ver.

Hatırın kalmasın el gün yanında.

Bu dünyâda sen de varsın

Üleştir dostluğunu varlığa

Bir kısmı da seni sarsın', 'Yol çıkınca her sabah,  Bulutlara selâm ver. Taşlara, kuşlara,  Atlara, otlara  İnsanlara selâm ver. Ne görürsen selâm ver. Sonra cebinden ç...', ARRAY['Türk Edebiyatı','Şiir','Üstün Dökmen']::text[], 8.5, '{"poet":"Üstün Dökmen","poet_slug":"ustun-dokmen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/mutluluk-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol', 'yol-zeynep-s-dauja', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yolumuz ayrı biliyorum

Ben çıkmaz bir sokakta, 

Sen ise yalanların ortasında.

Sıkışıp kalmışsın orada

Yazık! 

Görebiliyorum...

Kaçıyorsun benden, 

Umut verip sonra da

Umutsuzluğu aşılıyorsun

Ve yollarımız ayrılıyor.

Sana bir yol seç diyorum

Sen bensiz yolu seçiyorsun

Ve ben gidiyorum.', 'Yolumuz ayrı biliyorum Ben çıkmaz bir sokakta,  Sen ise yalanların ortasında. Sıkışıp kalmışsın orada Yazık!  Görebiliyorum... Kaçıyorsun be...', ARRAY['Türk Edebiyatı','Şiir','Zeynep S']::text[], 8.5, '{"poet":"Zeynep S","poet_slug":"zeynep-s","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yol-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın', 'kadin-selim-tuncbilek-hshtr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yorgun ve ıslak gecelerin günahı

Tüm güzelliklerin kölesi kadın, 

Gökyüzüne yükselen basamaklar

Ellerimle ördüğüm piramitler senin, 

Senin Tüm acılar, hazlar ve çırpınışlar.

Işık ışık, cadde cadde aydınlıklar

Beyazın maviyle soylu cümbüşü, 

Grift, alınmlı, deniz dalgası gözler

Titrek bir ud teli ruhun

Pür telaş, pür melal cemalin.

Işığın gecede suyu öpüşü gibi, 

Ne güzel öpüyor topuğunu saçlar, 

Ürkek ceylanlar misali peşime gel diyor

Bu sonsuz, bu ince çizgi, 

Tüm güzellikleri tutsak ediyor.', 'Yorgun ve ıslak gecelerin günahı Tüm güzelliklerin kölesi kadın,  Gökyüzüne yükselen basamaklar Ellerimle ördüğüm piramitler senin,  Senin T...', ARRAY['Türk Edebiyatı','Şiir','Selim Tunçbilek']::text[], 8.5, '{"poet":"Selim Tunçbilek","poet_slug":"selim-tuncbilek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kadin-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavrum Şiir', 'yavrum-siir-selim-tuncbilek-0i3mv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Saf, beyaz okşayışları 

Sıcak yüreğimde duyduğum.

Okyanus dalgalarıyla büyüyen istek; 

Uykuda çocuk gülümsemesi...

Güzel dilberin kıskançlığı, 

Şuh bakışlarının.

Van Gogh misali 

yavrum şiir

Bu kadar çok sevişin beni

başımdan edecek.

Yavrum şiir

Sen adamı öldürürsün.', 'Saf, beyaz okşayışları  Sıcak yüreğimde duyduğum. Okyanus dalgalarıyla büyüyen istek;  Uykuda çocuk gülümsemesi... Güzel dilberin kıskançlığ...', ARRAY['Türk Edebiyatı','Şiir','Selim Tunçbilek']::text[], 8.5, '{"poet":"Selim Tunçbilek","poet_slug":"selim-tuncbilek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yavrum-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüznün Pencereleri', 'huznun-pencereleri-erdal-alga-kzqg9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hüznün pencereleri

Bazı denize bakar bazı dağa

Benim hüznüm bile nemli

Bodrum katlarında kalmış gibi.

Hüznüm benim 

Hasta bir çocuk

Fakir bir ailenin çocuğu

Çözümü var hastalığın ama

Para yok ki ne fayda.

Hüznüm penceresiz benim

Ne güneş görür

Ne bir eş

Bordum katlarında, fareli.

Hüznümün pencereleri 

Kırıktır kışta

Kar taneleri dolar içime

İçim üşür

Kalbim donar, sevgi de.

Hüznümün pencereleri kırıktır

Sen bir kedi

Giriverirsin o kırıktan içeri

Şöminem yoktur, kıvrılacak yanı başına.

Gene de girersin, sokulursun koynuma

Hoş olan da bu ya! 

Seni sevdiğime şükürler olsun.', 'Hüznün pencereleri Bazı denize bakar bazı dağa Benim hüznüm bile nemli Bodrum katlarında kalmış gibi. Hüznüm benim  Hasta bir çocuk Fakir bi...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/huznun-pencereleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır', 'kir-erdal-alga-cvkys', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kır evime gel bekliyorum

Gençliğimde ara ara  geldim buraya

Çekip- bir kulübeyi –çevirdim eve

Bekledim gelirsin diye, gelmedin

Bahar geldi, gözlerin.

 

Kır evime gel bekliyorum

Kır zincirlerini kalbinin

Kır, salına salına gel

Şimdi kır evinde bir adam kır saçlarla

Grevde, omuz vermiş kalbin eylemine

Kırdığı- yok döktüğü gözyaşı

Kırsalıma gel bekliyorum.

 

Kır evime gel bekliyorum

Çiçekler açıyor baharın

Yağmur yağıyor, gözün

Kır ağrılar düşüyor gönlüme

Dolu dolu düşüyor dolular bomboş evime

Soğuk vurmuş gönlüme ah! 

Ürün vermez hem vallah hem billah.

 

Kır evime gel bekliyorum

Kiralık katil zaman 

Kır alık katil kemiklerimi

İşkenceyi bu sefil bedenden esirgemem

Her zaman belli olmuyor kaybeden

Kral sanıldım uzunca bir süre

Üstelik kraliçem,  sen yokken

Kör sevime gel bekliyorum.

 

Kır evime gel bekleniyorsun

Kır-salıma gel, salım bekliyor.', 'Kır evime gel bekliyorum Gençliğimde ara ara  geldim buraya Çekip- bir kulübeyi –çevirdim eve Bekledim gelirsin diye, gelmedin Bahar geldi, ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otsun Sen', 'otsun-sen-erdal-alga-5s1w3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ot geldin ot gideceksin

Basitlikle ölüp, öldüreceksin

Bilmem kaç yüreğin katilisin

Beni vurdun ya 

Bende milyon yürek

Sevgisizliğinle, seri cinayetsin

 

Ot  geldin otluğa devam

Ne olurdu odunsu olsan

Bir gövden olurdu, dirençli

Dalların olurdu, saracak kolların

Yaprağın olurdu, klorofil yaşam

Meyven olurdu, adı aşk olan

 

Ot geldin ot gideceksin

Rüzgar nereden eserse o yöne

Sevgisizlik esiyor bak 

Hıyanet ve de yozluk

Kasırgada denize düşen candır yaşam

Sen otsusun, yaşamı kurtaramazsın

 

Otsun sen

Yemyeşil bir ot

Bir ineğin yediği

İneğin sütünden anneye geçen

Bir annenin göğsünden seviyesizlik olarak bebeğe

Zehirli bir otsun sen

 

Otsun sen

Yüreğimdeki od’un yakamadığı

Bukalemunlar devrinde 

Bukalemun olamasan da 

Yer ve yataklıkla sabit

Suçsun sen.', 'Ot geldin ot gideceksin Basitlikle ölüp, öldüreceksin Bilmem kaç yüreğin katilisin Beni vurdun ya  Bende milyon yürek Sevgisizliğinle, seri ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/otsun-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Psikolog', 'psikolog-erdal-alga-44hkq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ala-bora olmasından korkuyorum hayatımın, 

Duyuramazsam sevgimi kalbinin kulakçıklarına.

Bir kulak-burun-boğaz uzmanıdır zaman

Kalbinin aksak ritmine hüküm getiren

Korkma gözden kaçırmadım.

 

Polyanna öldü dedim bir psikoloğa, 

Saniyelik olayları saatlik yaparak anlattım

Dökülüvermişti bir kaç yaprak, 

Aklına gelivermişti güzün ürettiği hüzün, 

Ve birden geçti hasta koltuğuna.', 'Ala-bora olmasından korkuyorum hayatımın,  Duyuramazsam sevgimi kalbinin kulakçıklarına. Bir kulak-burun-boğaz uzmanıdır zaman Kalbinin aksa...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/psikolog-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış', 'kis-erdal-alga-uadhe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Soğuk bir geceyi koynuma almışım

Kış işte, bir Ankara kişi.

Duman bir haber gönderiyorum sevgiliye, 

Her soluyuşunda kalbim.

Bihaber olmalı o halimden, 

Yoksa yoksa anlamaz mı Kızılderili töresinden? 

 

Soğuk bir geceyi koynuma almışım

Üşüyor delikanlı yüreğim, derdi malum

Uyumasın diye çabalıyorum

Küfürler ediyorum küfürler üstüne

Körüklüyorum isyanını kalbimin, alev alev.

Donar kalır korkusu var içimde.

 

Soğuk bir geceyi koynuma almışım

Son otobüsü de kaçırdım işte.

Sevgilinin hayali binip gitti aniden.

Benimse elim mahkum sabaha, 

Soykırımdan kurtulan son Kızılderili gibiyim şimdi

Tekrar kurayım desem kabilemi

En fazla melez bir benzerliktir yenisi.', 'Soğuk bir geceyi koynuma almışım Kış işte, bir Ankara kişi. Duman bir haber gönderiyorum sevgiliye,  Her soluyuşunda kalbim. Bihaber olmalı ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kis-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Grizu', 'grizu-erdal-alga-mnjgd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalp grizum patlamasında

Yaralandı birçok sevecen işçi

Aşk yoluna, umut yoluna

Maden çöktü, 

Göçük altında kaldı

İçimizdeki cevher.', 'Kalp grizum patlamasında Yaralandı birçok sevecen işçi Aşk yoluna, umut yoluna Maden çöktü,  Göçük altında kaldı İçimizdeki cevher....', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/grizu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saçların', 'saclarin-bayram-karaali-9mli9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayallerime gömdüğümde gece çığlıkları kadar işkencede, 

Upuzun yalardı boynumu rayihalarıyla sımsıcak karartılı

Dolanırdı bedenime  yağmurlu bulutlar gibi ağlamaklı

Son nefese taşıyacak kaybetmeden yalımlarını 

Uzun hep uzun olmalı  gecelerime katil olsada saçların

Yaman bir dağ sisidir gözlerindeki ağlamaklı

 Hüznüne taşıyan fırtınaları dindirmedimmi

 Sakın dokunma  hep uzun yalımıyla uzun olsun Saçların........', 'Hayallerime gömdüğümde gece çığlıkları kadar işkencede,  Upuzun yalardı boynumu rayihalarıyla sımsıcak karartılı Dolanırdı bedenime  yağmurl...', ARRAY['Türk Edebiyatı','Şiir','Bayram Karaali']::text[], 8.5, '{"poet":"Bayram Karaali","poet_slug":"bayram-karaali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/saclarin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Komşunun Kızı', 'komsunun-kizi-erdal-alga-fblw0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Komşunun kızını seviyorum

Hiç kimseye söylemeden

Biliyorum çünkü

Sevmek, nihayetinde sevişmeye gidecek

Ve sevişmek, ayıp kabul edilir bizim oralarda.

Komşunun kızını seviyorum

Kendime bile söylemeden

Ayıp ediyorum galiba

Konu aşksa kendime

Konu hevesse komşuya.

Komşunun kızını seviyorum

Komşu beni seviyor aslında

Kızını sevdiğimi bilmeden

Komşu bir bilse

Konu komşuya rezil olacağız vallahi.', 'Komşunun kızını seviyorum Hiç kimseye söylemeden Biliyorum çünkü Sevmek, nihayetinde sevişmeye gidecek Ve sevişmek, ayıp kabul edilir bizim ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/komsunun-kizi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Matematik', 'matematik-erdal-alga-6jy4h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artık sen X hanım

Koordinat düzleminde

Ben Y, Sen X

Kesişim kümemiz sıfır

Ben Y bey, 

Sensiz nasıl tanımlanırım.

Bende candın, canımdın

Oldun X hanım

Öbür yarım

Yamalak kaldın

Artık hanımlar içinde

Herhangi bir hanımsın.

Ancak bir matematikçi anlar beni

Böler, çarpar, toplar, çıkarır

Kalan sensizlik

Elde var sensizlik

Toplam ve çıkan sensizlik

İki bilinmeyenli

Bir denklemdir aşkım.', 'Artık sen X hanım Koordinat düzleminde Ben Y, Sen X Kesişim kümemiz sıfır Ben Y bey,  Sensiz nasıl tanımlanırım. Bende candın, canımdın Oldu...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/matematik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masalar Kuruluyor Hep', 'masalar-kuruluyor-hep-erdal-alga-h9m7v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Masalar kuruluyor hep

Rakı masası mesela

Yanında meze

Biraz da duman

Yaşıyoruz ölesiye.

Masalar kuruluyor hep

İflas masası mesela

Oturacak yer bile yok

El konmuş hayatımıza

Yaşıyoruz ölesiye.

Masalar kuruluyor

Sevgililer kafesinde

Kafesinde yüreğim

Yalnızlık ötüyor kendi dilinde

Yaşıyorum öylesine.

Masalar kuruluyor hep

Garson bile uğramıyor

Yalnızlık oturmuş karşımda

Konuşup gülüyor kendince

Yaşıyorum öylesine.

Masalar kuruluyor hep

Ben yokum artık bu masada

Tasalarımı aldım yanıma

Husalarla bıraktım hayatı

Gidiyorum öylesine.', 'Masalar kuruluyor hep Rakı masası mesela Yanında meze Biraz da duman Yaşıyoruz ölesiye. Masalar kuruluyor hep İflas masası mesela Oturacak y...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/masalar-kuruluyor-hep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Götür Buradan', 'gotur-buradan-erdal-alga-m29rk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Al beni

Götür buralardan

Yüreğin olduğu yerlere.

Gösteriş düşkünü kadınlar

Ya erkekler çok mu farklı

Nasıl işliyor bu feleğin çarkı

Döne döne döndü başım

Döne döne yüreğim bulandı.

Al beni

Götür buralardan

Yüreğin soluduğu yerlere.

Kirlilik her yanda

Önce çevrede vardı

Sonra içine duyguları aldı

Ardından düşünceleri

İçim fena bunaldı.

Al beni

Götür buralardan

Yüreğin kaldığı yerlere.

Gidecek bir yer kalmamış

İdeal ülkeler ütopya

İdeal bir yaşam ve yürek de.

Ütopyalarında yaşayanlar

Uykularından uyandı.

Al beni

Götür buralardan

Yüreğin yandığı yerlere.

Nasıl aydınlatırsa ışık

Gecenin karanlığını

İşte öyle aydınlatır

Yandığında yürek

Yaşamı ve yarınları.

Al beni

Götür buralardan

Yüreğin olduğu yerlere.', 'Al beni Götür buralardan Yüreğin olduğu yerlere. Gösteriş düşkünü kadınlar Ya erkekler çok mu farklı Nasıl işliyor bu feleğin çarkı Döne dön...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gotur-buradan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mi?', 'mi-erdal-alga-dxapn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir hastahane koridorunu beklemedeyim, 

Etraf insanlarla dolu.

İçimde de bir ses, ürpertili, sıkılgan, acılı, 

Gittiğini bilse de sevgilinin, 

Bilse de dönmeyeceğini bir daha, 

Ünler durur umudu, 

Milyonda birlik umudu.

Birlik tarafında bile sevinç vardır çığlıklı, 

Duyulması mühim değil bu sesin, 

İçten gelir, içtenlikle hissedilir, 

Gösterir kendini yaşamak diye, 

Bir de gülücükler varsa deste deste, 

İşte her şey olması gerektiği gibi.', 'Bir hastahane koridorunu beklemedeyim,  Etraf insanlarla dolu. İçimde de bir ses, ürpertili, sıkılgan, acılı,  Gittiğini bilse de sevgilinin...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/mi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-kamil-kaya-8nkf6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'siyah pelerinli gecelerde yürüyorum

gece, kasvet ve hüzündür bulutlarımdan süzülen

yokluğunla her sabah ufuklarda soluyorum

hayalindir beni her onulmazda avutan

serseri bir avareyim şimdi kaktüslerin bağrında

bülbülden hüzünlü nağmeler dinliyorum

nabzına siyah dokunmamış bir çocuk saflığında

yağız gecelerin koynunda gölgemi arıyorum

korkuyorum benliğimi saran yokluk ıstırabından 

karanfiller düşman bana, kırmızıyı öldürüyorum

yeşil bir çığlıktır dudaklarımdan dökülen

gönül bahçemden bütün gülleri kovuyorum.', 'siyah pelerinli gecelerde yürüyorum gece, kasvet ve hüzündür bulutlarımdan süzülen yokluğunla her sabah ufuklarda soluyorum hayalindir beni ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Kaya']::text[], 8.5, '{"poet":"Kamil Kaya","poet_slug":"kamil-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/isyan-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğlum Umut', 'oglum-umut-erdal-alga-4k59u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Oğlumun adını Umut koydum

Geleceğe sığdırabilsin diye tüm güzellikleri

Artık ben inanamıyorum

Oğlum sen inan bari.

Kırık dökük kalplerden

Sevgi üremez oğul

Yaşam yarım yamalaklarla

Bütün kalamaz oğul.

Oğlum baba nasihatidir

Kimseye güvenilecek devir değil

Ama güven sevgidendir, saygıdandır

Sev, say yaşamı oğul.

Oğlum benim 

Doğamadın  gitti bir türlü

Henüz annen bile yok

Hiç var olmasan da ismin Umut’tur.

Oğlum bana umuttur

Oğlum ne olur unuttur

Tüm yozluklarını yaşamın

Adın senin ondan Umut’tur.', 'Oğlumun adını Umut koydum Geleceğe sığdırabilsin diye tüm güzellikleri Artık ben inanamıyorum Oğlum sen inan bari. Kırık dökük kalplerden Se...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oglum-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muhasar Medeniyet', 'muhasar-medeniyet-erdal-alga-s8djm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ya al, alacaksan doğru

Ya alma, kalsın ırak.

Yavan yavan işlerin 

Ülkesi olmuş ülkem

Gösteriş ve tüketimin

Kölesidir insan, sürüngen.

Yerel bir düğüne gitsem

Kadın kadına dans edilir

Dans iki cinsin ahengidir

Bu cinslik nerden ileri gelir.

Ya al, alacaksan doğru

Ya alma, kalsın ırak.

Bu ülke benim

Bu yürek benim

Vay haline

İstila edenlerin

Yoz kültürler içinde

İnsanlarım yoz

Yap-boz oyunuysa hayat

Bizimkisi sürekli boz.

Cehaletin böylesi görülmemiştir

Kültürsüzlük ancak bu kadar yüceltilir

Kafada yapılan araştırmalarda

Beynin yerinde beyin görülmemiştir.

Nerde yanlış varsa o alınır

Nerdeyse doğrular yanlıştan utanır

Hep dalkavuklukla yol alınır

Böyle varılsa varılsa

Mu-hasar medeniyet seviyesine varılır.', 'Ya al, alacaksan doğru Ya alma, kalsın ırak. Yavan yavan işlerin  Ülkesi olmuş ülkem Gösteriş ve tüketimin Kölesidir insan, sürüngen. Yerel ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/muhasar-medeniyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selvi Canım', 'selvi-canim-erhan-guleryuz-z8e69', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sormadım hiçkimseye, 

''şimdi nerdedir? '' diye

ismini söyletmedim ben 

dost sohbetinde

kızmadım kızamadım

suçlu bendim belki de

sadece seni çok çok sevdim

hepsi bu..

vurdu günbatımı aşkımızı, 

zordu kalbimizin ilk sızısı, 

sordu ay ışığı şarkımızı, 

''BİTMEDİ'' dedim -selvicanım-', 'sormadım hiçkimseye,  ''şimdi nerdedir? '' diye ismini söyletmedim ben  dost sohbetinde kızmadım kızamadım suçlu bendim belki de sadece seni ç...', ARRAY['Türk Edebiyatı','Şiir','Erhan Güleryüz']::text[], 8.5, '{"poet":"Erhan Güleryüz","poet_slug":"erhan-guleryuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/selvi-canim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Medcezir Hayali', 'medcezir-hayali-i-rem-levent-bdpzs', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir medcezir hayalindeyim, 

Kumdan dalgaları yüreğimin, 

Gidiyor geliyor, gidiyor gelemiyor.

Ayışığına tutkun düşlerim, 

Sarsılıyor gidip geri gelmeyenlerle.

Eski, kendini baş taçı yapıyor, 

Bugünün kanlı ellerinde.

Oyuncaklarım, başı kopuk bebeklerim, 

Düğme burunlu ayıcıklarım...

Şimdi onlar benimle oynuyor, 

Beni oynuyor o küçük kız.

Yatağın altındaki canavarlar, 

Tam da yanı başında, elini tutuyor.

Bir medcezir hayalindeyim ben, 

Çarşambadayım, 

Perşembe döndürüyor başımı, 

Yürüyor üzerime titreyen gölgesiyle.

Bir de cuması var bunun! 

Ne var ki bunda bu kadar abartılacak? 

Altıüstü bir kırık akşamüstü kokusu, 

Sadece bir medcezir hayali bu.

Bir uykusuzun şiiri gibi, 

Bir geceyarısı çekilişi, 

Bir sabahkörü geri gelişi gibi.

Aynı kötü kalpli perşembelerin, 

Aynı paha biçilmez kalpsizin gidişi, 

Gidişi ve geri gelişi yırtarak düşlerimi...

Bir medcezir hayalindeyim, 

Denizyıldızları kadar ona teslim, 

Kum taneleri kadar onun...', 'Bir medcezir hayalindeyim,  Kumdan dalgaları yüreğimin,  Gidiyor geliyor, gidiyor gelemiyor. Ayışığına tutkun düşlerim,  Sarsılıyor gidip ge...', ARRAY['Türk Edebiyatı','Şiir','İrem Levent']::text[], 8.5, '{"poet":"İrem Levent","poet_slug":"i-rem-levent","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/medcezir-hayali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Var', 'olum-var-erdal-alga-wno8y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yürek vermeli insan

Yürek verdiyse biri ona

Bilmeli en sonunda

Ölüm var, ölüm gülüm.

Bir gün tükenir nefesler

Tüm lezzetler ve nefisler

Bilinmeli bir son var

Ölüm var, ölüm gülüm.

Boşa geçiyor hayatlar

Boşa geçtikçe bayatlar

Sevgisizlik unutulsun

Ölüm var, sonunda ölüm.

Bazı bazı dardayım

Bazı zorunluluklarla, bazı zordayım

Sev artık Allah aşkına

Ölüm var, sonunda ölüm.

Ölümden korkan mı var

Seve seve ölür, sevilen insan.

İşte benim de derdim bu ya

Saramadan seni, göçmek bu dünyadan.', 'Yürek vermeli insan Yürek verdiyse biri ona Bilmeli en sonunda Ölüm var, ölüm gülüm. Bir gün tükenir nefesler Tüm lezzetler ve nefisler Bili...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olum-var-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Çok Ne Yaralar', 'en-cok-ne-yaralar-melih-coskun-kky53', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'En çok ne yaralar seni

Sevmediklerin mi yoksa seni sevmeyenler mi

Hayır, 

Düşmanın kalleşliğidir asıl 

Ayakta tutan 

Seni ve inancı...

Ya sevdiklerin

Onlardır 

Bir bakışıyla paramparça eden yüreğini

Onlardır açan hiç kapanmayan yaraları

Onlardır bir sözüyle 

Atan seni dipsiz kuyulara

Üzgünsen, 

Kırgınsan, 

Kendini itilmiş hissediyorsan bugün

Sevdiğin içindir 

Sevilmediğinden değil, 

Böyle sevdikçe insanları

Bir gün layığını bulacaktır sevgin...

02 Aralık 2002

00: 27', 'En çok ne yaralar seni Sevmediklerin mi yoksa seni sevmeyenler mi Hayır,  Düşmanın kalleşliğidir asıl  Ayakta tutan  Seni ve inancı... Ya se...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/en-cok-ne-yaralar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mabed', 'mabed-erdal-alga-jyf0q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Neresinden tutarsan tut sevgili, 

Kırık döküktür kalbimin her yeri.

Eğer kabul edersen sana düşen, 

İnşa etmektir tekrar sevginin mabedini.

 

Duygusuzlukla temasta olduktan sonra, 

Hangi duyguyu bulsan mikrop kapıyor, 

Kapat desem başkalarına duygularını, 

Bana yüzün surat, kalbin inat yapıyor.

 

Bilmem kalbim hala ne diye sevgiye tapıyor, 

Gözlerim sevgili diye hep gözlerine, boşluğa bakıyor.

O boşlukta sürekli hoşluk arıyor, 

Geride anı diye loşluk kalıyor.

 

Aklımı kaçırmak üzereyim, 

Ne tüneller kazdık be kalp hapishanesinden, 

Hepsi ayrı ayrı hiçliğe koşuyor.

Çanlar sensizlik vuruyor, 

Canı vuruyor cananım, canı vuruyor.

 

Ben toprakla buluşan bir zerreyim, 

Seller beni hep vuruyor

Senin için güller derme istemindeyim, 

Dikenler beni çepeçevre sarıyor', 'Neresinden tutarsan tut sevgili,  Kırık döküktür kalbimin her yeri. Eğer kabul edersen sana düşen,  İnşa etmektir tekrar sevginin mabedini. ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/mabed-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gelincik', 'sen-gelincik-erdal-alga-yqc31', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen gelincik, kırmızı

Ben sendeki kara

Kara bahtımı düşmüşüm

Yüreğin tarih sayfasına.

Sen gelincik, beyaz

Gelinliğin içinde

Düğün dernek kurulmuş

Gidiyorsun el oğluna.

Ne uğruna yaşanır sevda

Bilmeden yüreğin çarpışını

Yakışık alıyor mu gitmek

Kırmak var mıydı ha kitabımızda.

Soluyor tüm renkler

Sen gelinlik içinde

Gelinler içinde gelincik

Karardı bende bembeyaz dünya.', 'Sen gelincik, kırmızı Ben sendeki kara Kara bahtımı düşmüşüm Yüreğin tarih sayfasına. Sen gelincik, beyaz Gelinliğin içinde Düğün dernek kur...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-gelincik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşünüyorum, Ey Karanlıkların Bekçisi', 'dusunuyorum-ey-karanliklarin-bekcisi-melih-coskun-urj2u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düşünüyorum

Ey karanlıkların bekçisi

Ey eli sopalı zabit

Haydi engelle beni

Saldır üzerime 

Kuduz köpekler gibi

Parçala bedenimi.

Aklımdan hürriyet geçiyor şimdi

Vur kollarıma kelepçeyi

Esir et beni 

Meçhullere gönder beni

Kaybet beni oralarda

Düşünüyorum 

Bir gün sana atacağım tekmeyi

Hür yaşayacağımız günleri düşünüyorum

Yak bütün kitaplarımı

Sustur bütün çocuklarımı

Ağlat bütün anaları

Yine de düşünüyorum

Gerekirse çıkar beynimi yerinden

Sök kalbimi göğüs kafesimden

Düşünüyorum kalleşliğini

Sırtıma sapladığın bıçağı

Satılmış gözlerini

Bu beden fazladır senin satılmış beynine

Değiştirebilirsin zulmünle

Bütün fizyolojimi ancak

Bu değiştirmez 

Düşünmüş olduğum gerçeğini

Söyletebilirsin dilime 

Duymak istediklerini

Fakat aklımdan geçenleri değil asla

Bedenimi zaptedebilirsin

Ancak beynim yeşil bahçelerde 

Özgürlük oyunu oynayan çocuklarla beraberdir şimdi

Beynim uzak dağlardadır, 

Derin denizlerde, 

Bir sevgilinin gözlerindedir.

Beynim bugünde değil

Yarındadır... 

Ve sen yoksun 

Ne dünde

Ne de varolacaksın

Yarınlarda...

10 Kasım 2002

21: 02', 'Düşünüyorum Ey karanlıkların bekçisi Ey eli sopalı zabit Haydi engelle beni Saldır üzerime  Kuduz köpekler gibi Parçala bedenimi. Aklımdan h...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/dusunuyorum-ey-karanliklarin-bekcisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Ağaç', 'o-agac-erdal-alga-mtz9m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hatırlar mısın bilmem

Adını yazdığım o ağaç büyümüş

Ağaçla birlikte isminde

Hala kalp resimleri çizebiliyor elim

Elim pes etmedi yalan sevdalarda.

 

Hatırlar mısın sevdiğim o ağacı

Dolduruyor kadehine miyadı

İçiyor ve geniriyor acı acı

Geldi gibi yolun sonuna

Adını başka bir ağaca kazır mıyım bilmem.

 

Herşey büyüyor

Yeni bir fidan büyüyor

Kirlilik büyüyor

Elini uzatıyor biri sevi diye

Elinden kan geliyor

Dudaklarını uzatıyor 

Ardından vampir dişler geliyor

Yüreğini uzatıyor

Şehvet geliyor sevisiz sadakatsiz

Herşey üstüme geliyor

Herşey büyüyor sevdiğim

Bir sen küçülüyorsun gözümde

60’lık kel bir banknota sattın kendini.', 'Hatırlar mısın bilmem Adını yazdığım o ağaç büyümüş Ağaçla birlikte isminde Hala kalp resimleri çizebiliyor elim Elim pes etmedi yalan sevda...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/o-agac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vah Vah Ezilen Kadın!', 'vah-vah-ezilen-kadin-erdal-alga-7batj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vatan savunmasında 

Geçmez adın

Mehmet yer küfürü

Sızlamaz canın

Vah vah ezilen kadın.

Askerlikte eşitlik 

İstediğin görülmez

Vatan sadece erkeğin değildir ya

Bu görev yalnız  erkeğe verilmez

Vah vah ezilen kadın

16 ay 18 ay 

geçmez kolay

o hiyerarşiye katlanmak 

inan büyük olay

vah vah ezilen kadın

erkek askerdeyken 

o da evde askerlik yaparmış

sevgilisi, anası, bacısıymış ya Memedin

Allah aşkına insanı güldürmeyin

Vah vah ezilen kadın

Seçerken maçoları seçersin

Evde kuzu, mutfak kedisi

Dışarda vurdu mu oturtsun istersin

Tezatlarınla kendi kendini ezersin

Vah vah ezilen kadın

Mehmet silahıyla askerde

Tank topunu görünce aklı gidiyor

Sen mağazada, kuaförde

Elbiseyle, makyajla aklın gidiyor

Vallahi ne diyeyim

Ezilen hep sensin

Vah vah ezilen kadın.

Güvencen yoksa haklısın kadın

Hayatını kazanmak zordu da

Ondan mı evlilik birliğine imza attın

Doğru bu işlerde yok senin suçun

Vah vah ezilen kadın.

Az bacak gösteririsin

Ve birazcık dekolte

İki de kıvırtıp sırıttın mı

Hazırdır mevkin

Vah vah ezilen kadın.

Reis olamadın diye

İnadın inattır

Sonunda reis oldun ama

Reislik rahat değil

Aslında başa beladır

Anlarsın zamanla 

Vah vah ezilen kadın.

Canın çok tatlıdır

Her şeyi istersin

Bencilsin sevginde

Hep istersin istersin

Ama mücadeleye gelince iş

İstersin gene istersin

Ama bu kez kaçmayı

Vah vah ezilen kadın.

Eşitlik derdin varsa tümden iste

Vatan savunmasını da kat içine

Asker yolu beklemek kolaydır

Ama vatan için ölmek zor 

Deli Dumrul’luk bir olay

Ya sakat kalınca Memet

Eşinin bir başkasıyla gitmesi ne demek.

İyi düşün anlarsın beni

Vah vah ezilen kadın.

Erkek egemen dediğin sistem

Bilmez misin ki senin sistemin

Kukla erkekler 

Siz arkadan oynatıverin

Oğlunuzun elinin kiri 

Kızlarınızın namusu vardır

Oğlunuz değil midir size tapan

Her dediğinizi yapan

Suçluyu öyle aramayın uzakta

Bak orda duruyor aynanın karşısında.

Vah vah suçsuz, günahsız, ezilen kadın.', 'Vatan savunmasında  Geçmez adın Mehmet yer küfürü Sızlamaz canın Vah vah ezilen kadın. Askerlikte eşitlik  İstediğin görülmez Vatan sadece e...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/vah-vah-ezilen-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fısılda Kendine Sessizliğini', 'fisilda-kendine-sessizligini-melih-coskun-98ulw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Fısılda yine 

Kendi kendine sessizliğini

Sessizliğini ve sensizliğini...

Yalnızlığın sessizliğindir

Ve kimsesizliğin 

Söylenmiş tüm güzel sözler boş

Usulca bir kulağa fısıldanmadıktan sonra

Neye yarar o güzel  gözler gülmeyi beceremiyorsa 

Bu yürek ne işe yarar

Sevmeyi bilmiyorsa eğer...

Neyi anlatır bu şiir 

Bir anlayan olmadıkça

Sevmek nedir 

Sevilmedikten sonra

Bu beden ne işine yarar senin 

Beyninde fırtınalar kopmuyorsa

Korkuyorsan kavgaya girmekten, 

Bu dil neye yarar

Sevgini söyleyemiyorsan

Ve isyan edemiyorsan bağırarak bu yaşadıklarına

Yalnızsan 

Neye yarar dünyadaki altı milyar insan

Yapılacak iş bugün sadece: 

Yaşamak sadece inadına 

Sonunda ölüm olduğunu bilsen de 

Yine de sevmek 

Kan ağlasa da sol yanın... 

21 Aralık 2002

00: 38', 'Fısılda yine  Kendi kendine sessizliğini Sessizliğini ve sensizliğini... Yalnızlığın sessizliğindir Ve kimsesizliğin  Söylenmiş tüm güzel sö...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/fisilda-kendine-sessizligini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölür Yürek', 'olur-yurek-erdal-alga-ryqzx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Söner yangınlar zamanla

Yürek yangını bunlardan biridir

Benzin dökülmüş gibi

Kibrit çakılmış gibi

Bir anda tutuşur yürek.

Sonra yavaş yavaş tükenir

Yüreğin monekülleri

Oksijen, oksijensiz kalır

Karbondioksit dolar yürek

Oksijensiz yangın olmaz 

Söner yürek

Oksijensiz yaşam olmaz

Ölür yürek, ölür yürek.', 'Söner yangınlar zamanla Yürek yangını bunlardan biridir Benzin dökülmüş gibi Kibrit çakılmış gibi Bir anda tutuşur yürek. Sonra yavaş yavaş ...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olur-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özel Kadın Ceyda', 'ozel-kadin-ceyda-erdal-alga-ehpdr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen ne dersen de

Genelevdeki Ceyda

Senden yürekli çıktı

Sevebiliyorum diyebiliyor en azından

Hem de bedenlerin iğrençliğine rağmen

Unutmamış yüreğin bir ritmi olduğunu

İlahi tonunda çarpan.

Ne derlerse desinler

Genelevdeki Ceyda

Helalin var be senin

İnancını yitirmemişsin yaşama hala

Kalbin kana cana kattığına

Bazıları insanız diye geziniyor

Tüm mal varlıkları

İki göğüs bir de vajina

Beyin mi dedin

Hiç rastlamadım

Yürekleri mi

Tamamen Allah’lık

Ceyda, helalin var be senin

Hayatın genelevde

Haramlar içinde geçse de.

Sen ne dersen de

Genelevdeki Ceyda

Senden yürekli çıktı

Pek giyinmez

Bilir nasılsa soyunacak

Tüm mal varlığı ortada

Sadece yüreğini örter

Korumak için sevgiyi

Kemik ve et parçalarıyla.

Yüreği olduğu için

Özel kadın

Genelevdeki Ceyda.

Bacak arasında ahlakları kokan

Ahlak kumkumalarına

Sokrates’i öğretebilecek kadar

Bilge ve ahlaklıdır Ceyda.

Sen ne dersen de

Eller ne derse desin

Satılık ruhlu

Satılık kalpli

Bir çok yavan ahlaklı

Kadın arasında

Onurlu, yürekli kadın

Genelevdeki özel kadın Ceyda.', 'Sen ne dersen de Genelevdeki Ceyda Senden yürekli çıktı Sevebiliyorum diyebiliyor en azından Hem de bedenlerin iğrençliğine rağmen Unutmamış...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ozel-kadin-ceyda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlemeyi Özlüyorum', 'ozlemeyi-ozluyorum-erdal-alga-17i0i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özlemeyi özlüyorum bazen seni

Hissizlik sarınca çepeçevre

Ürpertici bir sis ya da duman gibi.

 

Özlemeyi seviyorum seni

Bir korkuya tutuluyorum

Mesafeler aradan kalkınca

Ya büyü bozulursa

Yerinde güzeldir yıldızlar

Ancak gölgeleri alınabilir ayak altına.

 

Özlemeyi seviyorum seni

Büyütmek için özlemi sevgiyi

Uzaklaştırıyorum yakınlığı

Güçleniyor hayalin anımda

Güzel, güldükçe daha güzel

Bekliyorum kavuşmayı, kavuşmaya küs.

 

Özlemeyi özlüyorum bazen seni

İhtiyar bir yorgunluk yıllar

Beyazlar sarmış sakallarımı, saçlarımı.', 'Özlemeyi özlüyorum bazen seni Hissizlik sarınca çepeçevre Ürpertici bir sis ya da duman gibi.   Özlemeyi seviyorum seni Bir korkuya tutuluyo...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ozlemeyi-ozluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kene', 'kene-erdal-alga-8gp79', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Birliktelik oluşur

Bir keneden

Bir de büyükbaş hayvandan

Kene sömürür kanını büyükbaş hayvanın

Büyükbaşsa kaçamaz ondan

Büyük ve güçlü görünür büyükbaş

Sömürülen O’dur oysa kene tarafından.

Evlilik bir birlikteliktir

Düşünün gerisini Aristo’ylan

Sonra karar verin

Kim kene kim büyükbaş hayvan.', 'Birliktelik oluşur Bir keneden Bir de büyükbaş hayvandan Kene sömürür kanını büyükbaş hayvanın Büyükbaşsa kaçamaz ondan Büyük ve güçlü görün...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelliğin Bir Sigaranın İlk Nefesidir', 'guzelligin-bir-sigaranin-i-lk-nefesidir-melih-coskun-31epy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güzelliğin 

Bir sigaranın ilk nefesi gibidir

Heyecanla çekersin içine 

Başı döndürür

Gittikçe tükenir 

Tükenir ve biter sonunda

Geriye sararan resimler kalır geçmişten

Resimlerin bile yaşlanır

Gülüşün eskir

Gün gelir 

Yaprağın yeşilini kıskanırsın

Çünkü sen çoktan sararmışsındır 

Denizdeki dalgayı kıskanırsın

Çoktan durulmuştur heyecanın

Resimlerde kalmıştır o gülümsemeler

Yalancı baharlarda yeşeren ağaçların 

İlk yağmurda dökülen çiçekleri gibidir güzelliğin

Bir çığın düşüşü gibidir zaman

Yaşanmamış ne varsa ardına takarak

Düşer büyük bir hızla bilinmeyenin boşluğuna...

23 Aralık 2002

00: 01', 'Güzelliğin  Bir sigaranın ilk nefesi gibidir Heyecanla çekersin içine  Başı döndürür Gittikçe tükenir  Tükenir ve biter sonunda Geriye sarar...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/guzelligin-bir-sigaranin-ilk-nefesidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevemedin', 'sevemedin-alim-vedat-suner-qqq8d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ağlamak neyi değiştirir ki

Son tren kalkmış artık

Sığamadın gönlüme

Özürler neye yarar ki

Sevemedin sende..! ! !', 'Ağlamak neyi değiştirir ki Son tren kalkmış artık Sığamadın gönlüme Özürler neye yarar ki Sevemedin sende..! ! !...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevemedin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Anlara', 'son-anlara-alim-vedat-suner-1pnw9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Durupda gözlerime bakma

Utanırda ağlayamam karşında

Susupda, dudaklarıma dalma

Korkarda konuşamam sonra', 'Durupda gözlerime bakma Utanırda ağlayamam karşında Susupda, dudaklarıma dalma Korkarda konuşamam sonra...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/son-anlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Sonra Başlıksız Şiirlerim', 'senden-sonra-basliksiz-siirlerim-alim-vedat-suner-0gbfs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'içimden geçen binlerce ses''e

tek sesle ortak olurdun

seni zor gün dostu bilirdim

neden şimdi yok oldun

gözlerimden anlardın halimi

bana sen destek olurdun

''ben hep seninleyim'' derdinde

şimdi nerelere kayboldun', 'içimden geçen binlerce ses''e tek sesle ortak olurdun seni zor gün dostu bilirdim neden şimdi yok oldun gözlerimden anlardın halimi bana sen ...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/senden-sonra-basliksiz-siirlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşkınsın', 'saskinsin-alim-vedat-suner-i5uau', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '''Geçmişi unutamıyorum''

diyerek kandırma kendini..

gelecekden korkarak

hayattan sakınma kendini...

ne umutlar ne hayaller biriktirdin

bir rüya''ya hapsetme kendini

uyan artık tatlı dilli gevezem

uyan derin uykulardan

kandırma içindeki sevgini

geçmişe hapsetme sevgiyle dolu yüreğini...', '''Geçmişi unutamıyorum'' diyerek kandırma kendini.. gelecekden korkarak hayattan sakınma kendini... ne umutlar ne hayaller biriktirdin bir rüy...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/saskinsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksa''lamak', 'yoksa-lamak-alim-vedat-suner-6ew2m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerimin önünden yitip giden senmiydin

Senmiydin yoksa

Yoksa şehir mi karardı da

Ben mi göremiyorum seni

Ellerimin üşümesine sebep

Ellerinin yokluğumuydu yoksa

Yoksa SENDEMİ bıraktın beni

Gönlün baharında...', 'Gözlerimin önünden yitip giden senmiydin Senmiydin yoksa Yoksa şehir mi karardı da Ben mi göremiyorum seni Ellerimin üşümesine sebep Ellerin...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yoksa-lamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hocam Nurten', 'hocam-nurten-alim-vedat-suner-i2gru', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'En kötü günümde yanımdasın

Güveniyor ve Destek çıkıyorsun

Güzel ve çok tatlısın

Eee.. nede olsa Nurten Hocasın

Seninle düşünmeyi seviyor

Yanlış ile doğruyu senle anlıyorum

Bu deli gönlü kimse uslandıramaz ama

Nede olsa sen Nurten Hocasın

İlk tanıdığımda sinir olmuştum

Büyük dostluklarda böyle başlarmış zaten

Sana ''kendini beğenmiş biri'' demiştim

Gerçekdende Hocam beğenilesi insanmış....

_____________________

Seninle zaman tanımsız

Seninle zaman doyumsuz

İyiki varsın hocam

İyiki seni tanıyorum Hocam

__________________

En tatlı Hocam''a

Nurten Hanım''a....', 'En kötü günümde yanımdasın Güveniyor ve Destek çıkıyorsun Güzel ve çok tatlısın Eee.. nede olsa Nurten Hocasın Seninle düşünmeyi seviyor Yan...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hocam-nurten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Ülkenin En iyileri', 'bu-ulkenin-en-iyileri-cengiz-yazici-w3wr3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mevsimlerin dengesi bozulmuş, 

Yaz baharda kar yağıyor. 

Garibim bademler şaşkın, 

Ocak ayında çiçek açıyor. 

Her kahve köşesi, birer ilim yuvası, 

Ahkam kesen kesene, 

Fetvalar, haşa oyuncak sanki, 

Havalarda uçuşuyor. 

Ter, bulgur olmuş Eminem''in, alnında, 

Tırpan sallıyor, Ağustos sıcağında 

Biri sırtında, beş ayı bitmiş bebesi karnında, 

Akşama, yapacak aşı yok, onu düşünüyor. 

Burda, buzdolabının adı salamuradır. 

Çamaşırlar derede, külle tokaçla yıkanır. 

Fırının adı gelmemiş, mikro dalgayı ne bilsinler. 

Soba burda, meşeyle çalışan ocakbaşıdır. 

Bir yanda teknoloji bozarken dengeleri, 

Öte yanda tırpan sallar birileri, 

Doğa ile teknoloji savaşı var sanki, 

Hani şimdi neredeler? 

Şinanayda ders çalışmış, ''''Ülkemin en iyileri''''.', 'Mevsimlerin dengesi bozulmuş,  Yaz baharda kar yağıyor.  Garibim bademler şaşkın,  Ocak ayında çiçek açıyor.  Her kahve köşesi, birer ilim y...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bu-ulkenin-en-iyileri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebişkom', 'bebiskom-cengiz-yazici-y4ca7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adını duvarlara yazdım, 

Kör karanlığın bir vaktinde.

Militan sanıldım yakalandım, 

Sadece boya ve fırça vardı elimde.

Sorgusuz sualsiz kelepçelendim, 

Yediğim copların, ilk onunu sayabildim.

Kim ne sordu, ben ne dedim bilmeden, 

Uzatılan evrakı imzalayıverdim.

Şimdi sorgu odasındayım, 

Bir başıma sorgulanıyorum.

Vallahi yalan bu onların deyimi, 

Aslında ben işkence altındayım.

Bir örgütüm varmış, ben kurmuşum, 

Doğruyu söylersem, kurtulurmuşum.

Öyleyse, itiraf ediyorum.Ben, militan bir liderim.

Ben, BEB'' eğimi İS'' tiyorum, KOM'' serim...', 'Adını duvarlara yazdım,  Kör karanlığın bir vaktinde. Militan sanıldım yakalandım,  Sadece boya ve fırça vardı elimde. Sorgusuz sualsiz kele...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bebiskom-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlarımla Sevişirim.', 'umutlarimla-sevisirim-cengiz-yazici-bhp8r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Umutlarımla sevişirim, 

Gecenin bir yarısı.

Ve hayalinin çığlıkları, 

Getirir beni kendime

Çok sonraları anlarım, 

Paslanmaya yüz tutmuş, 

Masa saatimin, kurduğum

03.45 Feryat figan sesidir.

Hayalinin çığlıkları.

Ne umutlarım anlar beni, 

Ne hayilinin çığlıkları.

Bilemezler.

Çünkü masumdur. Düşüncelerimin, 

Yoktur, günah tohumları...!', 'Umutlarımla sevişirim,  Gecenin bir yarısı. Ve hayalinin çığlıkları,  Getirir beni kendime Çok sonraları anlarım,  Paslanmaya yüz tutmuş,  M...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/umutlarimla-sevisirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Bu Gece Parlamıyordu.', 'o-bu-gece-parlamiyordu-cengiz-yazici-8dvcd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sensiz gecelerimde, 

''''Sen'''' dediğim, 

O, yıldızım, 

Bu gece baktım, 

Yerinde yoktu.

Hüzünle aradı gözlerim.

Sordum diğer yıldızlara, 

Buldum.

Sizin evin üzerinde duruyordu.

Kara bir haber mi var? 

Çünkü o, 

Bu gece parlamıyordu...', 'Sensiz gecelerimde,  ''''Sen'''' dediğim,  O, yıldızım,  Bu gece baktım,  Yerinde yoktu. Hüzünle aradı gözlerim. Sordum diğer yıldızlara,  Buldu...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/o-bu-gece-parlamiyordu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Gücümü.', 'ben-gucumu-cengiz-yazici-c26x4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu gün nefes alıyorsam, 

Bir nebze ayakta duruyorsam, 

Ve ben yaşamaya çalışıyorsam, 

Ben gücümü, maziden alıyorum.

Bir lokma ile doyuyorsam, 

Her an seni düşünüyorsam, 

Her yerde seni görüyorsam, 

Ben gücümü anılardan alıyorum.

Seni seviyorum diyorsam, 

Seninde sevdiğini biliyorsam, 

Ve ben bunları yazabiliyorsam, 

Ben gücümü Hakk''tan alıyorum.', 'Bu gün nefes alıyorsam,  Bir nebze ayakta duruyorsam,  Ve ben yaşamaya çalışıyorsam,  Ben gücümü, maziden alıyorum. Bir lokma ile doyuyorsam...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-gucumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sınır...Hayat...Onur', 'sinir-hayat-onur-sair-mavi-i7h03', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sınırsızsa da Hayat 

Onursuz değil Yaşamak...', 'Sınırsızsa da Hayat  Onursuz değil Yaşamak......', ARRAY['Türk Edebiyatı','Şiir','Şair Mavi']::text[], 8.5, '{"poet":"Şair Mavi","poet_slug":"sair-mavi","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/sinir-hayat-onur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nöbet Ertesi', 'nobet-ertesi-sair-mavi-vhecb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Nöbet kasılmaları 

Ya da kasılma nöbetleri 

Oysa hepimiz biliriz 

Nöbetler değildir beyinde hasar bırakan 

İstemsiz, önüne geçilemeyen 

Kasılmalardır beynin kanlanmasını bozan', 'Nöbet kasılmaları  Ya da kasılma nöbetleri  Oysa hepimiz biliriz  Nöbetler değildir beyinde hasar bırakan  İstemsiz, önüne geçilemeyen  Kası...', ARRAY['Türk Edebiyatı','Şiir','Şair Mavi']::text[], 8.5, '{"poet":"Şair Mavi","poet_slug":"sair-mavi","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/nobet-ertesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz...', 'biz-sair-mavi-2a0b4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biz.. 

Çoğul eki almış tekil şahıslardık 

Tek yapabildiğimiz tan vaktinin serin rüzgarında 

Titrek bir ışığın duvara yansıttığı gölgemizi taşlamaktı 

Nedensizce ama birlikte…', 'Biz..  Çoğul eki almış tekil şahıslardık  Tek yapabildiğimiz tan vaktinin serin rüzgarında  Titrek bir ışığın duvara yansıttığı gölgemizi ta...', ARRAY['Türk Edebiyatı','Şiir','Şair Mavi']::text[], 8.5, '{"poet":"Şair Mavi","poet_slug":"sair-mavi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/biz-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Veda Anı', 'bir-veda-ani-ozan-rari-c2ut5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşananlardan çok yaşanacaklar vardı...

Kısmet, hoşçakal sana yolun hep aydınlık gözlerin hiç yaşlı olmasın...

Sana büyüttüğüm aşkı ancak ben böyle bitirirdim...

(Rüa_12 Mart 2002)', 'Yaşananlardan çok yaşanacaklar vardı... Kısmet, hoşçakal sana yolun hep aydınlık gözlerin hiç yaşlı olmasın... Sana büyüttüğüm aşkı ancak be...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-veda-ani-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Profesyonelce Yaşanmalı Hayat', 'profesyonelce-yasanmali-hayat-sair-mavi-rczlo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Profesyonelce yaşanmalı hayat 

Sadece kendin olmalı. 

Başka kimse fikir yürütememeli yaşamına 

Bazen yok edebilmelisin insanları hayatında 

Hayatta kazanmaktır aslolan 

Ayakta kalmanın bedeli bu 

Ve… 

Amatörce yaşanmalı sevgi 

Onun için her şeyini verebileceğin… 

Onu her şeyden üstün tuttuğun yaşamından bile! 

Kaybettiklerini hiç hesaplamadığın 

Kazanmayı ise asla düşünmediğin 

Ruhunla bedeninle canınla yaşadığın. 

Profesyonelce yaşanan aşklar 

Ve… 

Amatörce yaşanan hayatlar… 

Aradığını bulamayan hep yıkılanlar 

Sevgisini yok sayıp 

Toplumu mutlu etmeye çalışanlar 

Öğretiniz nedir sizin? 

Topluma karışıp kendinizi yok etmek mi? 

Zaten herkesinde istediği bu değil mi? 

Çoğunluk haklımıdır yaşamında 

Yoksa bir tekil çoğunluğa söz geçirebilir mi? 

Sen profesyonelleşirken 

İçindeki çocuğu dinledin mi? 

Yükseklerde kanat açarken maviye 

Bir martı ağlıyor 

Göz yaşları masum çocukça… 

Çocuk ağlıyor 

Martı çok uzaklara kanat açmakta…', 'Profesyonelce yaşanmalı hayat  Sadece kendin olmalı.  Başka kimse fikir yürütememeli yaşamına  Bazen yok edebilmelisin insanları hayatında  ...', ARRAY['Türk Edebiyatı','Şiir','Şair Mavi']::text[], 8.5, '{"poet":"Şair Mavi","poet_slug":"sair-mavi","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/profesyonelce-yasanmali-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi-Hayal-Cehennem', 'mavi-hayal-cehennem-sair-mavi-dmrmk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayalsem! ben yaşamıyorsam gönlünde 

Beni kaybetmek çok kolay elbette 

Bana yüklediğin sevgi ben kaybolunca 

Kaybolacaksa durma yok et beni zihninde 

Zihninde küçüldükçe doğacağım içine 

Dönecek gerçek! bir sevgin varsa durma 

Hayaller bana göre değil ben buradayım 

Benim çabam cennet kurmak değil dünyada 

Ben kendi cehennemimin yan komşusuyla', 'Hayalsem! ben yaşamıyorsam gönlünde  Beni kaybetmek çok kolay elbette  Bana yüklediğin sevgi ben kaybolunca  Kaybolacaksa durma yok et beni ...', ARRAY['Türk Edebiyatı','Şiir','Şair Mavi']::text[], 8.5, '{"poet":"Şair Mavi","poet_slug":"sair-mavi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mavi-hayal-cehennem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Giderken', 'sen-giderken-ozan-rari-bykhr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biliyordum asla eskisi gibi olmayacağını, 

Farkındaydım bir anlık öfkenin kurbanı olduğunu! 

Utanıyordum kendimden böylesine vahşi olduğum için

Anlıyordum bana olan öfkeni yüzüme bakarken

Gözlerin sanki herşeyi mahfettin der gibiydi...

Yırtıp atmıştın bana verdiğin resmi, 

Hani şekiller içerisinde adım olan, 

Renklerle bezenmiş, 

Sonunda ise yeşil gözlü bir surat vardı seni simgeleyen

Ama ağlıyordu resimdeki kız, gözyaşları çizmişsin boncuk boncuk! 

Ben ise topladım parçaları senden sonra ve tekrar hayat verdim ağlayan yeşil gözlere

Gittin bir daha gelmemek üzere', 'Biliyordum asla eskisi gibi olmayacağını,  Farkındaydım bir anlık öfkenin kurbanı olduğunu!  Utanıyordum kendimden böylesine vahşi olduğum i...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-giderken-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam, Hırs ve Duyarsızlık Üzerine', 'yasam-hirs-ve-duyarsizlik-uzerine-sair-mavi-k3ynz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Küçük bir kelebeğin uçmak adına rüzgara verdiği savaşı gördünmü hiç? 

Ya da ateşi söndüren suyun cezvede kaynayıp buharlaşabildiğini 

Ya da hayata dokunmak adına harcanan çabanın sonuçsuzluğunu 

Ya da bir çocuğun hüzünlü umarsız ve safça harcadığı ama aslında kimseninde fazla umrunda olmayan kendini ispatlama gayretini 

Gördünmü hiç...! !', 'Küçük bir kelebeğin uçmak adına rüzgara verdiği savaşı gördünmü hiç?  Ya da ateşi söndüren suyun cezvede kaynayıp buharlaşabildiğini  Ya da ...', ARRAY['Türk Edebiyatı','Şiir','Şair Mavi']::text[], 8.5, '{"poet":"Şair Mavi","poet_slug":"sair-mavi","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yasam-hirs-ve-duyarsizlik-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki küçük Balık Olduk Bİz', 'i-ki-kucuk-balik-olduk-bi-z-ozan-rari-k7z05', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Binbir neşe ve heyecan içerisindeydik

Kimi gün dişi aşığın koynunda

Başka zaman erkek tarafındaydık

Tam kavuşturduk onları derken bıraktılar bizi

Şimdi yaşıyoruz ama velakin anlamsız kaldık...

Acaba bu nasıl son yarrabi! 

(Bebek-Böcek_2002)', 'Binbir neşe ve heyecan içerisindeydik Kimi gün dişi aşığın koynunda Başka zaman erkek tarafındaydık Tam kavuşturduk onları derken bıraktılar...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/iki-kucuk-balik-olduk-biz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eger', 'eger-selvi-celik-elh0d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kabullenmek cok zor.

Eger böylesine hasretle yasanirsa özlemler.

Sevdigin dostlar birgün görmezden gelirse, 

  en agir gününde acilari kaldiramadigini, 

Eger birgún yalniz ve caresiz karanlik bir odada, 

Sana bir fener tutan yoksa.

Avuclarindan yakalamadan kaybolursa mutluluklar.

Hic bir mana veremiyorsan bu dünyanin kurulusuna.

Ínsanlarin düzen bu diye, 

Ístenmeyen yasantilara devam etmesine,, 

Isyan ediyorsan...

Arasindan zamansiz bulunan dostlugu, 

Ve egerki solmayacak gülü kopara bildimse.

Degismem.

Bedelinde verilecek yeni bir hayat olsada...', 'Kabullenmek cok zor. Eger böylesine hasretle yasanirsa özlemler. Sevdigin dostlar birgün görmezden gelirse,    en agir gününde acilari kaldi...', ARRAY['Türk Edebiyatı','Şiir','Selvi Çelik']::text[], 8.5, '{"poet":"Selvi Çelik","poet_slug":"selvi-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/eger-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mor Gecelik', 'mor-gecelik-ozan-rari-trsn4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geçerdik hani mağazanın önünden, 

Bakıyordunya durup içini çekip, ah keşke diyordun...

Sonra olmuştu düş gerçek kavuşmuştun bir sevgili günde! 

Gözlerin ışıldıyordu, 

Ağzın kulaklarındaydı 

Nasıl da sabırsızdın onu üzerinde görmeye hatırla! 

Giydin onu belki en özel gecende

Ama nasip değilmiş deyip çıkarttın üzerinden koydun kenara

Simdilerde ne giyorsun bilemiyorum

Yalnız mor geceliğin sensiz yetim kaldı eminim...', 'Geçerdik hani mağazanın önünden,  Bakıyordunya durup içini çekip, ah keşke diyordun... Sonra olmuştu düş gerçek kavuşmuştun bir sevgili günd...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mor-gecelik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Seviyordun', 'beni-seviyordun-ozan-rari-35gts', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Herşeyin başlangıcıdır aşk; 

Yeni düşüncelere, yepyeni duygulara en güzel fırsattır...

Elinden tutuyorum, seninle yepyeni bir hayata doğru gidiyorum, 

Ve benim yanımda olduğunu biliyorum 

                             Seni Seviyorum

(Eski bir sevdanın küllerinden_Bilkent)', 'Herşeyin başlangıcıdır aşk;  Yeni düşüncelere, yepyeni duygulara en güzel fırsattır... Elinden tutuyorum, seninle yepyeni bir hayata doğru g...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/beni-seviyordun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkak Gemi', 'korkak-gemi-ugur-uludag-0ra30', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ya dost giderse bi gün

ya yalana dönerse yüzüm

korkak bir gemiye benzerse yüreğim bi gün

ya fırtınalar sararsa etrafımı

neye benzer o zaman emeklerim

boynum eğilir toprağa

kulaklarım sağır saza

göz yaşa teslim

elleri kelepçeli idama hazırlanır

yiğit dediğin gün gelir

en yakın arkadaşın 

soğuk bir mezar taşı olur bi gün

mermerden gülümsemesi

yanağında donar

ellerin ayaza teslim

depremler sararken vücudu

yüzler solarsa ya bi gün

bir çiçek bile uzatmaz yar bi gün

öpücükleri başka bir adama yol verir

anne sözü bir küslüktür artık

suratına bile tükürmez düşmanlar

bitmişsindir artık

yalan bi nota bestelenir

kirpiklerine gün gelir

bilirsin her şey yalan

her şey dolan

verdiğimiz sözler bir bir hatırlanır tabii

bir bir birer çivi gibi saplanır yüreğine

bu kadar mı kokuştuk diye

bu kadar mı soysuz olabilir sevgi diye

bu kadar mı be diye

ya ölürse sevgilin bi gün

her mevsim bir daha aşık olursun ona

unutuldu tabii ergenlik sivilceleri

unutuldu tabi her günün yeni bir gün olduğu

değişti tabi her şey

ne güneş eskisi gibi parlak, ne gözlerin

ne yürümeyi seviyorum artık, ne ellerini

nelere yok demedik ki vazgeçmeyelim senden

vazgeçmeyelim o güzel ensenden

neleri unutmadık ki

atlayalım ankarayı

söz sana

unutulacak hepsi bir gün

“umudum büyük, gücüm tam” da

ya çok istediğim halde

unutamazsam seni bir gün

ya unutamadan

ölürsem bir gün', 'ya dost giderse bi gün ya yalana dönerse yüzüm korkak bir gemiye benzerse yüreğim bi gün ya fırtınalar sararsa etrafımı neye benzer o zaman ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Uludağ']::text[], 8.5, '{"poet":"Uğur Uludağ","poet_slug":"ugur-uludag","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/korkak-gemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçarcasına...', 'ucarcasina-suat-oktay-pobyn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yaşam bir yolculuktur ya...

Öyle diyorum ben...

bir yolculuk bu! 

insanlar, hayvanlar, 

bitkiler ve düşlerle gerçekleri harmanlayıp

gidiyoruz, nereye gittiğimizi bilmeden..

yolun başı yada sonu...

yada mola verdiğimiz bir anı

ne kadar uzun, 

belki de kısa olursa olsun...

hem gerçek, hem de düş gibi sürsün, 

sürdüğün yaşamın dizginleri avucunda, 

sevdiklerin yüreğinde, 

yüreğin istediğin yerde 

kuş gibi özgür olsun! 

daldan dala, 

koldan kola, 

yada bir gönüldedir

verdiğin mola

sapmadan sağa, sola..

düşlerinin mavisi kadar

saf, temiz, hep özgür, 

hep uçarcasına..

30/ocak/03', 'yaşam bir yolculuktur ya... Öyle diyorum ben... bir yolculuk bu!  insanlar, hayvanlar,  bitkiler ve düşlerle gerçekleri harmanlayıp gidiyoru...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ucarcasina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bak Sen Şu Aşk''a', 'bak-sen-su-ask-a-dilek-ve-burhan-kardesler-7odko', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bak sen su ask''a 

bu gun kalbim tuhaf  hasta galiba.

bir garip sanci var tam ortasinda.

ne aci veriyor nede bir sifa, 

bu nasil hastalik bak sen su aska, 

gonulden gonule akip gidiyor, 

sozum ona deva  olyor, 

verdigim yalnizca mutluluk diyor, 

nasilda yalanci bak sen su aska, 

bir  tutku diyelimbu daha baska, 

ozlemde denemez sen gelde sasma.

hepisinden bir parca onda galiba, 

ne garip hastalik bak sen su aska,', 'Bak sen su ask''a  bu gun kalbim tuhaf  hasta galiba. bir garip sanci var tam ortasinda. ne aci veriyor nede bir sifa,  bu nasil hastalik bak...', ARRAY['Türk Edebiyatı','Şiir','Dilek Ve Burhan Kardeşler']::text[], 8.5, '{"poet":"Dilek Ve Burhan Kardeşler","poet_slug":"dilek-ve-burhan-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bak-sen-su-ask-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar Dallara Çıkmıyor', 'cocuklar-dallara-cikmiyor-oguzkan-bolukbasi-y86al', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çocuklar dallara çıkmıyor

ağaçlarda kuş sesleri kalmadı

bir orman kavgasında oysa ki

hayata tutunmak kaygısı

yaşamak

bir yağmur sonrasında toprak kokusu

deniz kıyısında yakamozlar

can üstü aşk değil artık

yaşamak diye biz çocuklara

ne anlamsız kavramlar bıraktık', 'çocuklar dallara çıkmıyor ağaçlarda kuş sesleri kalmadı bir orman kavgasında oysa ki hayata tutunmak kaygısı yaşamak bir yağmur sonrasında t...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cocuklar-dallara-cikmiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-serdar-acikgoz-srwz8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum diyebilmek, 

Hem o kadar kolay ve

Bir o kadar da zor ki

Anlatamam.

Anlatabilsem seni seviyorum, 

Diyebilmenin zevkini.

Hem de ağız dolusu, yürek dolusu, 

Seni seviyorum diyebilmenin.

Sevmek kolay gelirde insana

Sevdiğini söylemek nedense zor, 

Zor gelir insana, 

Seni seviyorum diyebilmek nedense zor.

Oysa; 

Hayat sevmekle başlar, 

Seni seviyorum diyebilmekle devam eder.

Yaşamak; 

Seni seviyorum diyebilmektir.

SENİ SEVİYORUM.', 'Seni seviyorum diyebilmek,  Hem o kadar kolay ve Bir o kadar da zor ki Anlatamam. Anlatabilsem seni seviyorum,  Diyebilmenin zevkini. Hem de...', ARRAY['Türk Edebiyatı','Şiir','Serdar Açıkgöz']::text[], 8.5, '{"poet":"Serdar Açıkgöz","poet_slug":"serdar-acikgoz","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/seni-seviyorum-114-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ecel Ben Fani', 'sen-ecel-ben-fani-ozan-rari-vglgv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir melek gibiydin başta bana, 

Huzur, mutluluk sevgi meleğimdin sen

Zaman geçti zalim oldun adeta ölüm meleği gibi, 

Sen azrailmişsin meğersem haberim yokmuş

Sanırım ölümü yendim, 

Nefes alıyorum baksana! 

Ben senin elindeydim

Şimdi sendeki beni öldürdün

Oysa bendeki ben yaşıyor hala! 

(23.01.2003_Konya)', 'Bir melek gibiydin başta bana,  Huzur, mutluluk sevgi meleğimdin sen Zaman geçti zalim oldun adeta ölüm meleği gibi,  Sen azrailmişsin meğer...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-ecel-ben-fani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Keşke', 'keske-ozan-rari-uhsm8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Keşke göz yummasaydım hatalarına! 

Keşke affetmeseydim seni defalarca! 

Yanıyorum dinlemediğin, anlamadığın sözlerime

Duymasaydım çirkin sözlerini, beni bağlamayan benzetmelerini

Ruhunun derinliklerini korkularını, acılarını

Bir sevdanın hüsranını kayboluşunu

Beni derbeder yapacak kadar bağlanmasaydım keşke! 

Sana katılıyorum pişmanım

Ama yanlışlarıma hatalarıma değil! 

Sana verdiğim emeğe yanıyorum

Keşke mutluluğu paylaşabilseydik seninle...

(2003-Konya)', 'Keşke göz yummasaydım hatalarına!  Keşke affetmeseydim seni defalarca!  Yanıyorum dinlemediğin, anlamadığın sözlerime Duymasaydım çirkin söz...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/keske-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Resim', 'son-resim-ozan-rari-p59ge', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu an elimde bakıyorum resmimize

Alkollü bir gülümseme var yüzümüzde

Senin en sevdiğin gömlek üzerimde, 

Sakalım dudaklarımı çevrelemiş

Üzerinde siyah kazak altında kot pantoolonun

Hele o gözlerindeki hayat dolu bakışlar, 

Ya gülümsemen, işte en çok o beni mest ediyor

Herşey yalan değilmiş demek! 

Kadehler duruyor önümüzde, içilmeyi bekliyorlar tıpkı yağmuru bekleyen ağaçlar gibi

Saçların kestane ihtişamında, nasıl olmasın ellerimle boyamıştım onları evimizde! 

Tek ben değildim hisseden fotoğraf makinesi bile anlamış mutlu olduğunu! 

Bitmek üzere olan bir sigara tablada sanki haber veriyor bir hayalin çöküşünü

Masa çok sade; sadece birkaç peçete ve hüzün rüzgarımız üstünde

Yaslanmışsın yanağını yanağıma, 

Sarmışım seni koynuma, 

Bitmeyecek bir sevda''nın anısına

Saklıyorum seni sakladığım gibi gönül zindanlarımda

Görmedin, göremedin sen bu resmi oysa, 

Unutulmuştu tıpkı senin beni unuttuğun gibi! 

Varsın sensizlik alınyazım olsun resmin emin ellerde küçüğüm..

(Ankara''da alelade bir bar''da çekilen resmin anısına_13.01.2002)', 'Şu an elimde bakıyorum resmimize Alkollü bir gülümseme var yüzümüzde Senin en sevdiğin gömlek üzerimde,  Sakalım dudaklarımı çevrelemiş Üzer...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/son-resim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Resim 2', 'son-resim-2-ozan-rari-xo1n6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Resimden önce iki yabancı, 

Çekilirken hayatımızın aşkı, 

Ondan sonra ise nefretin sebebiydik, 

Tanrım ne büyük çelişkiydi yaşananlar? 

(17 Kasım-30 Mayıs 2002  Bilkent/Ankara)', 'Resimden önce iki yabancı,  Çekilirken hayatımızın aşkı,  Ondan sonra ise nefretin sebebiydik,  Tanrım ne büyük çelişkiydi yaşananlar?  (17 ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/son-resim-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdaya Çevirdim Yüzümü', 'sevdaya-cevirdim-yuzumu-ahmet-kerem-kaban-6j0st', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Ak mürekkeple sevişen bir meleksin sen

Ve kara sözcüklerle de savaşan...

Savunmasızım aşkına karşı

Ve tabiiyim öpülesi kalbine

Sen de sev beni 

Öp kalbimi.''

Örselenmiş yaşamların

yarım bırakılmış sevdaların

üstüste avutulan gençlik çağlayanları

sana şiirler adıyorlar

seni arandığım akşam kuytuları

rüzgarın tokatlayan nefesiyle

yıkılan ve ben

kırılgan dizelerim

üşüyen ellerim

titreyen canımla

sana şiirlere gebe gecenin

buza kesmiş ayazı altında

vururken yüzüme

karasevdanın

burada öylece

her yanım gece

ağlamaklı ve şiir

en çıplak halimle

yüzümü sana çeviriyorum

sana...

sevdalanmaya.....', '''Ak mürekkeple sevişen bir meleksin sen Ve kara sözcüklerle de savaşan... Savunmasızım aşkına karşı Ve tabiiyim öpülesi kalbine Sen de sev b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kerem Kaban']::text[], 8.5, '{"poet":"Ahmet Kerem Kaban","poet_slug":"ahmet-kerem-kaban","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sevdaya-cevirdim-yuzumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çifte Kumrular', 'cifte-kumrular-hudayi-can-uoj9c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Erşah’a

Sesleriyle değişir gönlümün mevsimleri

Sesleriyle büyür baharım, yazım.

Arzu dolu bir iç geçiriş, 

Bir yakıcı nefes, “aah”ın resimleri…

Hür varlıklarıyla süzülürler de, 

	Altı yanımdan beni bürürlerde, 

		Kalmaz kararım.

O ki, odur niyazım, 

Muhteşem sanatkar

Iki fırça almış parmaklarının arasına

Ve küçük fırça darbeleri mavi tuvalde

Kahverengi fırça darbeleri, boz boz lekeler.

Kimse keyfinizi bozmasın, 

			Semtinize yaklaşmasın hatta tehlikeler

Kimse soğan çentmesin gününüze güzeranınıza

Kem gözler, şom ağızlar yaklaşamasın yanınıza

Ve birlikte kanat çırptığınız her anınıza

Bir mısra düşüreyim gönlümün mevsimlerinden

Bir deste gül atayım baharımdan yazımdan

Ama, aman hazer edin kem gözlerin ayazından

Her zaman sesinizle dolsun bahçelerim

Ki sesinizle değişir gönlümün mevsimleri

Sesinizle büyür baharım yazım', 'Erşah’a Sesleriyle değişir gönlümün mevsimleri Sesleriyle büyür baharım, yazım. Arzu dolu bir iç geçiriş,  Bir yakıcı nefes, “aah”ın resimle...', ARRAY['Türk Edebiyatı','Şiir','Hüdayi Can']::text[], 8.5, '{"poet":"Hüdayi Can","poet_slug":"hudayi-can","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cifte-kumrular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehmet’İn Anası', 'mehmet-i-n-anasi-hudayi-can-jyd3y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bütün Mehmetlere…

Mehmet’in başını okşadı anası, 

Alnından öptü.

Ana sevgisiyle dolmuştu

Bembeyaz gönlü.

Yıllar sonra; 

Vatan anamdır, dedi.

Savaştaydı

Bir serseri kurşun 

Başını yedi.

Alnından öptü

Mehmet’i anası

Topraktan dudaklarıyla; 

Sonra onu, 

Anasının kucağına verdiler.

Binlerce MEHMET

Vatan anamız dediler.

Onların omzunda yükseldi memleket.

Mehmetler döküldü, 

Çiçekler  toplandı demet demet.

Ve daha nice çiçekler toplanacak

Mehmetlerin ana sevgisiyle dolu yüreklerinden.', 'Bütün Mehmetlere… Mehmet’in başını okşadı anası,  Alnından öptü. Ana sevgisiyle dolmuştu Bembeyaz gönlü. Yıllar sonra;  Vatan anamdır, dedi....', ARRAY['Türk Edebiyatı','Şiir','Hüdayi Can']::text[], 8.5, '{"poet":"Hüdayi Can","poet_slug":"hudayi-can","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/mehmet-in-anasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur, Hüzün ve Nurettin', 'yagmur-huzun-ve-nurettin-hudayi-can-iyzob', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Nurettin Bal için

Rüzgarlar sıyırdı peçesini, hüzünlü yüzünden güzün

Yağmurlar yıkadı yüzümüzü

Uyardı güzümüzü, hüznümüzü

Hani Heraklit Efendi, hani iki defa yıkanılmazdı bir yağmurda 

Öyleyse ben neden

Ben neden yine o eski yağmurlara gittim 

Nurettinli zamanlar çoğaltır hayalimin yağmurlarını

Yağmurlar çoğaltır yalnızlığımı, büyütür hüzünlerimi

Yağmurlu otobüs pencerelerinden akarken sular ve arada ışıklar

Davetsiz misafirler gelir en kuytu köşelerinden kullanılmış günlerimin

Yağmurla yaldızlanır köyümün yeşilleri

Burnumda tüter toprak kokusu, bağ bozumu, güz...

Yağmurla yıkanır Yalvaç’ın asfaltları 

Sonra Beşiktaş-Kadıköy vapurları

Bilmem bilir misiniz, yağmur en güzel denize yağar.

Olacak şey miydi Nurettin

Nereden aklına esti bir “si-di” çıkarıp Dıranas dinletmek

“Ey unutuş” olmuş “Olvido”nun adı

Unutmak ne mümkün hele yağmur yağarken

Bulutlar yağmurlarını çiseleyip geçtiler kafamın en ıssız  yerlerine

Heraklit Efendi’ye inat tekrar ıslandım o eski yağmurlarda

Bulutlar ebrular gibidir oysa tekrarlanmaz

... Bulutlar yakışır en çok gülüşlerine, düşlerime

Ve en çok Tokar Bey’in atölyesinde

Bulutlar kendini tekrarlamaz

“Ey unutuş”, hatırlatır adına inat

Bulutsu hüzünler geçer yüreğimden

Yağmurların ninnisiyle büyür hüzünlerim

Yağmurlar yıkar, sular, yaldızlar, getirir o eski kullanılmış anları

Her damlada bir gökkuşağı saklıdır

Ve ben bir otobüste, bir takside

Yamurlu pencerelerden eski yağmurların siyah beyaz karelerini seyrederim

Yağmurlar çaldı bu gün kapımı

Ve Nurettin

Ve Nurettinli zamanlarda yağmurlu pencerelerden akan çınarlar

Nasıl hatırlamam o eski yağmurları

Nasıl unuturum Nurettin

‘si-di’den bir ses “Ey unutuş” dese de “Olvido”nun adına.

kasım,1998', 'Nurettin Bal için Rüzgarlar sıyırdı peçesini, hüzünlü yüzünden güzün Yağmurlar yıkadı yüzümüzü Uyardı güzümüzü, hüznümüzü Hani Heraklit Efen...', ARRAY['Türk Edebiyatı','Şiir','Hüdayi Can']::text[], 8.5, '{"poet":"Hüdayi Can","poet_slug":"hudayi-can","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/yagmur-huzun-ve-nurettin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ancak Aşk Sorsa Söylerdim', 'ancak-ask-sorsa-soylerdim-tebuk-zorakar-dujc7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'şimdi ağırdan alırım söylemeyi, ben şimdi

kaçmayım da ne edeyim? 

kim verir sana öyle boş bir sayfa, hadi

der mi biri en başından bir daha başla, 

bu kez başkayı seç de bildin o sana yaraşmadı yaramaz

olur mu ki bu, olmaz öyle ya

ben seni seçecektim, seçtim, belamı 

alacaktım başa, aşka onca hevesli giyindim

al işte gördün neymiş ve en kötüsü

ne değilmiş.

en son beni yordu diye bildim

bir zoru deyebildim, adını

ben ezbere bilirim kaç siyah giydin

yüzüne, kaç hale sardı göz çevreni, ben baktım

ben baktıkça yüzüne bildim, kaç haleydi

kaç oldu.

sana da zor olmasa, yaşanır bile olmazdı

bu kara soluk dizgesi

o günden bu bahtsızlığa dek uzanır

bu en sesli ağladımlara son verecek bir söz

biliyorum, bir '' veda'' gelsin, şöyle alsın da gitsin

hadi yaşanmışın külünü kaldırsın. Ben

rahatta şöyle sensiz, senli kavgalarsız

açayım çiçek böcek. olur mu ki bu

var mı böyle veda bize, payımıza düşer mi

bu aşka veda biçilmez, ya biz ölürüz.

saymayı biliyorum, masal sonlamayı

sonsuza kadar kim sayar, kim herşeyi bitirecek

bir sona dayatır masalı

bu hiç olmaz ya

o zaman, bırak beklemeyelim bir masal sonu

ben şimdiden yolu görüyorum

başka bir yolu, senin adımların duyulmaz bile 

başkamın civarında. Sen bırak ellerimi de, çek gözlerini de

ne eksilecek ki acıdan, ve acıya acıdan başka ne var daha

bende senden böyle büsbüyük bitane var

bende senden diye sevdiğim

ne çok şey ağlar, bana sen diye

seveceğim bişeyler kalır elbet, mahsus

düşmanı olsak herbirinin, kıysak varına bir bir

canıma kıyan, kastımdır vedaya cümlemde

canımı yakan, türküler şöyle ağırdan alır ya 

                                                ölümün demeyi, aşkın üstüne

o da bişey mi be! 

aşkına ilave  eder mi bir dirhem üstüne.

sözüm hey, ağlamaklı dur gayrı

gözüm hey, bakma uzağın seyrine

almasın sonra seni ölümün düşü

şüphesiz, 

ecelden önce gelecem yanına

ve korkularından uzun tutacağım elini. Ancak aşk 

sorsa söylerdim  bunu

hey dilim hey verdi sırrını.', 'şimdi ağırdan alırım söylemeyi, ben şimdi kaçmayım da ne edeyim?  kim verir sana öyle boş bir sayfa, hadi der mi biri en başından bir daha b...', ARRAY['Türk Edebiyatı','Şiir','Tebuk Zorakar']::text[], 8.5, '{"poet":"Tebuk Zorakar","poet_slug":"tebuk-zorakar","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/ancak-ask-sorsa-soylerdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiçelenim', 'sevgicelenim-cafer-tayyar-ozkan-kqkjr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dün gece dolaştım, Beyoğlu sokaklarında, 

Hep seni düşledim, hep seni andım, 

Dost diye sarıldığım mey kadehlerinde, 

Hep senden istediğim, erişilmez sevdandı ahtım.

Hep sen vardın yüreğimin derinliklerinde, 

Belki martılar seni hatırlatırlar sandım, 

Bazen Beşiktaş, bazen Üsküdar sahillerinde, 

Uzaklardaydım ama seni yüreğimde yaşadım.

Boğaziçi bile dindiremedi, büyük aşkımın kor ateşini, 

Kahrolası tabularınla kırıldı, kolum kanadım, 

Boğazın soğuk suları bile kesemedi, sıcak nefesini, 

Görmesem de son güzelliğini, sevdiğini bile duymadım.

Bu can nasıl dayansın sensizliğe SEVGİÇELENİM, 

Serde erkeklik var, gösteremem asla gözyaşımı, 

Gönül bahçeme solmayacak güllerimi ektim gül bebeğim, 

Belki göremeyeceksin, aşkımı yazdığım mezar taşımı.', 'Dün gece dolaştım, Beyoğlu sokaklarında,  Hep seni düşledim, hep seni andım,  Dost diye sarıldığım mey kadehlerinde,  Hep senden istediğim, ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgicelenim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-cafer-tayyar-ozkan-5yjhr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yazılardan aldım elektriğimi, sevgimi 

Bırak yansın, kahretme çırpınan yüreğimi 

Bir gün gelirde, eğer pişmanlık duyarsan 

Ziyaret edersin, başsağlığı için can evimi

Ne ekmek istedim; ne bir lokma katık 

Bir yudum sevgi ise olamazdı artık 

Bu kadar sitemin, nazın biter diyorsan 

Canın sağ olsun dersin, ver o zaman ılık ılık 

İnsanoğlu pek nankördür, değmez dünya malı 

İstediğim sadece bir gözdü, ama olsun hülyalı 

Senin için çoktur deyip, fazlasını vermiyorsan 

Ne olursa olsun,  ama insan, dürüst olmalı 

Ümitle derim ki aç sineni güzelliklere, korkma 

Gülümse insanlara ve hayata, sakın içine atma 

Yaşadıkların, yaşayacaklarına bırak yön versin 

Aldırma sakın, ey gönül değmez dünya aşkına...', 'Yazılardan aldım elektriğimi, sevgimi  Bırak yansın, kahretme çırpınan yüreğimi  Bir gün gelirde, eğer pişmanlık duyarsan  Ziyaret edersin, ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sitem-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanımda Ol Yeter', 'yanimda-ol-yeter-cafer-tayyar-ozkan-b8as6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Papatyalar açardı hep kalbimde

Gülsün yüzüm dedim, olmadı

Bir sen güldürdün kaderimde

Papatyam, seninle hiç solmadı 

Sevgimizi yaşayalım, asla bitmesin

Dünya döndükçe yanımda ol yeter

Kalbimizdeki heyecan meltemi dinmesin

Petunyam, aşkımız övgüye değer', 'Papatyalar açardı hep kalbimde Gülsün yüzüm dedim, olmadı Bir sen güldürdün kaderimde Papatyam, seninle hiç solmadı  Sevgimizi yaşayalım, as...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yanimda-ol-yeter-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanımda Yoktun', 'yanimda-yoktun-cafer-tayyar-ozkan-axtdh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yalvarışlarımı duy gönül gözlüm 

Sana olan sevgimdendir

Serzenişlerimi bil ey gönül sözlüm

İçimde kalan ukdemdendir

Bu sefer boğaza senin gözlerinle baktım ey sevgili

Suları daha bir maviydi

Ağaçları daha bir yeşildi

Yeşil olmasına ama

Sen yanımda yoktun

İçtiğim, yediğim, gördüklerim, renklerim 

Hep seninle değer buldu

Maral gözlerini

Kulaklarımı uğuldatan sözlerini hayal ettim bu gece

Düşledikçe boğazın güzelliği daha bir anlamlıydı

Sen yine yanımda yoktun

Boğazın kokusunu çektikçe

Sanki kokunu çekiyorum

İçime doldukça

Canıma can

Gözlerime fer geliyor sevginle

Seni her anışımda

Yüreğimde artçı depremler oluyor sanki, 

Depreşiyor arzularım, özlemlerim.

Ama yine sen yanımda yoktun bir tanem', 'Yalvarışlarımı duy gönül gözlüm  Sana olan sevgimdendir Serzenişlerimi bil ey gönül sözlüm İçimde kalan ukdemdendir Bu sefer boğaza senin gö...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yanimda-yoktun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'omur-dedigin', 'omur-dedigin-cafer-tayyar-ozkan-mz5o7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ömür dediğin su gibi coşkulu olmalı, 

Yarını düşleyerek bugünden yaşamalı, 

Sevgileri, tutkuları içinden alarak, 

İhanetle, ızdırabları silip atmalı.

Geçmişi yad ederek geleceğe bakmalı, 

Yaşanılası bu dünyaya anlam katmalı, 

Gülleri dikenleriyle sevip koklayarak, 

Sevgiyi, kıymeti bilenleri yaşatmalı.

Gönüller ufuktaki yarınları yazmalı, 

Nefesi tüketen zalime kurşun sıkmalı

Ateş düşen yerin kalp olduğunu bilerek, 

Binlerce defa düşünüp, bir kere sevmeli.

Hayat durdukça, duyulan özlemler sürmeli, 

Dudaklar sustukça, ağlayan gözler bilmeli, 

Acısı dinmeyen arzuya iç geçirerek, 

Aşk şerbetini hep yudumlayarak içmeli, 

İnsan sevdiğini kalp atışından anmalı, 

Canına can katarak özlemiyle kanmalı, 

Bugünü yaşarken, yarınları düşünerek, 

Varlığında değil, yokluğunda da yanmalı.', 'Ömür dediğin su gibi coşkulu olmalı,  Yarını düşleyerek bugünden yaşamalı,  Sevgileri, tutkuları içinden alarak,  İhanetle, ızdırabları sili...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/omur-dedigin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömre Bedel', 'omre-bedel-cafer-tayyar-ozkan-hvg22', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Varlığın benim için bir ömre bedel, 

Yokluğun ise yüreğim için zuldür.

Bir gün uzanırsa gönülden bir el, 

Sakın geri çevirme, onu daima güldür.

Hep seni arzular gönlüm, 

Bitse de bu uğurda ömrüm, 

Vermezsen eğer bana bedenini, 

O zaman çekerim, son nefesimi.', 'Varlığın benim için bir ömre bedel,  Yokluğun ise yüreğim için zuldür. Bir gün uzanırsa gönülden bir el,  Sakın geri çevirme, onu daima güld...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/omre-bedel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olaydın', 'olaydin-cafer-tayyar-ozkan-psue0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sıcacık nefes olaydın, 

Çekeydim içime doyasıya, 

Gireydin damarımdan, 

Kalbime gidilen yolun, 

Sadık yolcusu olaydın.

Gönül konuğu olaydın, 

Kalaydım kalbine yatasıya, 

Seveydin can evimden, 

Yüreğime ışık saçan, 

İnci tanesi olaydın.

Tatlı bir canan olaydın, 

Öpeydim ateşle yanasıya, 

Bileydin hislerimden, 

Günlerime hayat veren, 

Sevgi pınarı olaydın.

Seher meltemi olaydın, 

Alaydım göğsüme kanasıya, 

Yanaydın düşlerimden, 

Karanlığa kalem çeken, 

Gece meleği olaydın.

Buz gibi bade olaydın, 

İçeydim kendimden geçesiye, 

Akaydın gözlerimden, 

Ellerimden tutup giden, 

Canın yoldaşı olaydın.', 'Sıcacık nefes olaydın,  Çekeydim içime doyasıya,  Gireydin damarımdan,  Kalbime gidilen yolun,  Sadık yolcusu olaydın. Gönül konuğu olaydın,...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/olaydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Kadın', 'o-kadin-cafer-tayyar-ozkan-x8w7k', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir bahar yeli gibi akıp geçip gittin

Dönüp ardına bir defa bile bakmadan

Bir yaz ateşi gibi yakıp yıkıp gittin

Vefasız, küllerini bile savurmadan

Bu sevgi seli gün gelecek, bekliyorum

Düşünde bile seni inan boğacaktır

Bu sevda ateşi yakacak, diliyorum

Gönül bahçesinde ne varsa solacaktır

Uzanıp başını yastığa koyduğunda

Beni andığın yıldızlar başına yağsın

Yüreğimden içtiğin her yudum suyunda

Damarlarından şerbet değil, zehir aksın

Değmesin asla teninden zerre canıma

Ak düşmüş saçlarımla sana gittiğim gün

Bilmesin sevenlerin cümlesi mahıma

Sabır tasımla acısını içtiğim gün

Neylesin bu canım senin gibi cananı

Zalimlere bile taş çıkaran sevdanı

Verdiği her nefesi acılara boğdu

Unutmam bilirim o hercai kadını

Kaybolan hislerimi kim gelip açacak

Canan deyip canıma zincir takanlar mı...? 

Susayan dudağımı kimler sulayacak

Ölümsüz aşkı bir kalemde satanlar mı...?', 'Bir bahar yeli gibi akıp geçip gittin Dönüp ardına bir defa bile bakmadan Bir yaz ateşi gibi yakıp yıkıp gittin Vefasız, küllerini bile savu...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/o-kadin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Melekler Bile Özendi', 'melekler-bile-ozendi-cafer-tayyar-ozkan-xaexa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gonca gülüm soldu yüreğim sızlıyor

Defterde adeta kurumuş ağlıyor

Mazide kalan unutulmaz anılar

Beyaz sayfalarda simsiyah duruyor

Aşkım sana bir numara büyük geldi

Gönülleri fethetmek pek zor değildi

Düş kırıklarının denizinde kaldım

Göz yaşıma melekler bile özendi!', 'Gonca gülüm soldu yüreğim sızlıyor Defterde adeta kurumuş ağlıyor Mazide kalan unutulmaz anılar Beyaz sayfalarda simsiyah duruyor Aşkım sana...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/melekler-bile-ozendi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Muallaktayım', 'muallaktayim-cafer-tayyar-ozkan-dxl5v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşa, eğlen, gez, toz en güzel çağın

Günün birinde ardına bakmışsın

Saçların ağarmış, gözlerin çökmüş

Zamanın bir su gibi aktığını, 

Anlayamamışsın...

Kimler geldi kimler geçti dünyadan

Çekinme sevdiğini haykırmaktan

Sevmek güzeldir, sevilmekten gayrı

Yüreklerden süzülen sıcak demi, 

Kavrayamamışsın...', 'Yaşa, eğlen, gez, toz en güzel çağın Günün birinde ardına bakmışsın Saçların ağarmış, gözlerin çökmüş Zamanın bir su gibi aktığını,  Anlayam...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/muallaktayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Olmasın', 'neden-olmasin-cafer-tayyar-ozkan-gzoyb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sonbaharda yapraklar sararıp dökülürken, 

Bülbüller sevgi naralarını özlemle atarken, 

Sular meşk edecekleri kıvrımlı bir oyuk ararken, 

Sımsıcacık bir merhaba neden olmasın? 

Çiçekler artık bahara tekrar görüşelim derken, 

Yaz aşkları ayrılıklarına hüzünlenip dururken, 

Yağmur bulutları sevenlerin üzerine düşerken, 

Sımsıcacık bir selam neden olmasın? 

Sevda bahçelerinin gülü her gün solarken, 

Kalplerdeki sevinçler hüzünleri kovarken, 

Gönüller azgın bir çağlayan gibi coşarken, 

Sımsıcacık bir gülümseme neden olmasın? 

Mağrur bakışlı gözler içten sevgileri ararken, 

Kırmızı güller buluşmak için beyaz gülü beklerken, 

Yeşil gözler beyaz atlı prenslerinin yolunu gözlerken, 

Sımsıcacık bir öpücük neden olmasın? 

Bu alemde herkes bir yudum sevgi ararken, 

Sevilmeye muhtaç kalpler gerçek dostları isterken, 

Telefondaki ince ses hasret kaldığı mutluluğu ararken, 

Sevgi dolu kalplerden süzülen dizeler son mısraya dizilirken, 

Sımsıcacık bir dostluğa davet neden olmasın?', 'Sonbaharda yapraklar sararıp dökülürken,  Bülbüller sevgi naralarını özlemle atarken,  Sular meşk edecekleri kıvrımlı bir oyuk ararken,  Sım...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/neden-olmasin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte O Benim', 'i-ste-o-benim-cafer-tayyar-ozkan-3impi', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir gün gözlerinin önüne

Güzel bir söz düşerse 

Bilki onu gönderen 

İşte o benim

Hani kar taneleri uçuşurken

Aniden dudaklarına  dokunur

Ateşinden adeta mum gibi erir ya

İşte o benim

Yağmur damlaları vardır

Yağar sevgi saçar bereket saçar

Yaşam olur hayatlarda su gibi

İşte o benim

Izdırap dolu günlerin üstüne

Nur gibi parlayan

Yürekleri hoş tutan sevgi vardır 

İşte o benim

Her demde her anında

Yüreğinin azgın çırpınışında

Damarlarına dolan sımsıcak kan.

İşte o benim

Her karanlık gecenin sonunda

Tan yerini ağartan 

Gündüzü getiren güneş vardır ya

İşte o benim

Azgın dalgaları costuran

Engin denizleri kükreten

Kayaları döven o rüzgar

İşte o benim

Sessiz gecelerin sabahında

Sonsuz günlerin sonunda

Yıllanmış kalplere mutluluk veren

İşte o benim

Gözle görünmeyen bir şeydin

Düştün bir yere yeşerdin sevgiyle

Bu güzelliğin temelini oluşturan 

İşte o benim

Gözlerin ufka bakarken sürekli

Yalnız kaldığın zamanlarda

Beklersin daima beyaz atlıyı

İşte o benim

Yüreğinin içinde gezinen

Sana hayat veren güç veren

Damarlarında dolaşan demin

İşte o benim', 'Bir gün gözlerinin önüne Güzel bir söz düşerse  Bilki onu gönderen  İşte o benim Hani kar taneleri uçuşurken Aniden dudaklarına  dokunur Ate...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/iste-o-benim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep Seni Düşünüyorum', 'hep-seni-dusunuyorum-cafer-tayyar-ozkan-v6pju', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni düşünüyorum, ıssız gecelerimde

İstersen rüyalarıma gir yalnızlığımda

Ne olur bir teselli ver, sensizliğinde

Gözlerini görmezsem, o zaman kalbim duracak

Seninle olmak, seninle yaşamak çok hoştur

Fakat imkansızlıklar benim lisanımda yoktur

Ne yapsam bilmiyorum, çabalarım boştur

Sözünü duymazsam, o zaman kalbim duracak

İsterdim gök kubbeye değsin başım seninle..

İçim senin fakat naçiz bedenim nafile

Atamam seni, asla yok olmazsın gönlümde

Yüreğini alamazsam, o zaman kalbim duracak

Telefonun tellerinde ararım hep seni..

Gülen gözlerini görmesem de, olur bana teselli..

Sürecektir inan, yüreğimdeki bu sevgi seli..

Sesini duyamazsam, o zaman kalbim duracak..

Hiç bir şeye değişmem asla, saçının bir telini..

Kıskanırım, paylaşamam, vazgeçemem bitmez sevgini

Aç artık bana yüreğini, ereyim sonsuzluğa

Canıma can katmazsan, o zaman kalbim duracak..', 'Seni düşünüyorum, ıssız gecelerimde İstersen rüyalarıma gir yalnızlığımda Ne olur bir teselli ver, sensizliğinde Gözlerini görmezsem, o zama...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hep-seni-dusunuyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykırışım', 'haykirisim-cafer-tayyar-ozkan-1mzms', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin bir yarısında gözlerimi tavana dikip, 

Sebepsizce süzülerek acı göz yaşlarım akıyorsa, 

Başımdaki yastığım mermerden taş oluyorsa, 

Akan yaşları bilmelisin, 

Sana anlatamadığım duygularımdandır.

Güneşin kavurduğu anlarda boğazdan ufka bakıp, 

Manasızca düşlere dalıyor içim kan ağlıyorsa, 

Kalbim yerinden fırlayacakmış gibi çırpınıyorsa, 

O zaman hissetmelisin, 

Sensiz kaldığım anlarımdandır.

Martıların çığlıklarında bulduğum seslenişini sezip, 

Delicesine göğsümü açtığımda kokun geliyorsa, 

Gözlerim zaman zaman ta uzaklara takılıyorsa, 

Haykırışımı duymalısın, 

Kalbime özlemin dolduğundandır.

Gözlerim kapalı kollarımı açıp sesini sen bilip, 

Fütursuzca sarıldığımda ellerim bomboş kalıyorsa, 

Bir uğultuyla kulaklarım delirtircesine çınlıyorsa, 

Gözlerimi görmelisin, 

Seni yanımda sandığımdandır.

Zemheride dağlardaki karları gelinliğin sanıp, 

Ayaklarım o an çılgınca vuslata ermek istiyorsa, 

Kırmızı gülün dikenlerine ellerim aldırmıyorsa 

Düşlerimi sezmelisin, 

Defteri önümde bulduğumdandır.

Dolaşırken nisan yağmurlarıyla sırılsıklam ıslanıp, 

Bitmeyen tutkum baharda yeşerip coşmuyorsa, 

Seni sevdim diyenler derdime ilaç olmuyorsa, 

Sabrımı anlamalısın, 

Kahır mektubu yazdığımdandır.', 'Gecenin bir yarısında gözlerimi tavana dikip,  Sebepsizce süzülerek acı göz yaşlarım akıyorsa,  Başımdaki yastığım mermerden taş oluyorsa,  ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/haykirisim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatıran var', 'hatiran-var-cafer-tayyar-ozkan-7xvt9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güzel gözlerin düşlerimde duruyor

Tatlı sözlerin kulaklarımda çınlıyor

Canım dillerin beni benden alıyor

Unutmak kolay değil hatıran var

Yanımda olmasan da kalbimdesin

Sensizliği silsem de düşümdesin

Beni benden alsan da dilimdesin

Çözülmek kolay değil düğümün var

Bir nefeste bin defa içime çekiyorum

Bir kafeste dönercesine uçuyorum

Dağılan sayfalarda seni arıyorum

Bırakmak kolay değil yeminim var

Artık güllerin bile kokusu kalmadı

Sensizlikte sevgiler bile öksüz kaldı

Keşke derken kalplerde hep acı vardı

Dilemek kolay değil özlemim var

Kalplerdeki girdap gibi olmaktansa

Gerçeklere gem vurup solmaktansa

Kahır mektuplarını alıp okumaktansa

Yaşamak kolay değil kederim var', 'Güzel gözlerin düşlerimde duruyor Tatlı sözlerin kulaklarımda çınlıyor Canım dillerin beni benden alıyor Unutmak kolay değil hatıran var Yan...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hatiran-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerek', 'gerek-cafer-tayyar-ozkan-cupa0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğin kabarıp adeta kıpır kıpır olursa, 

Kalbindeki yarana aşk merhemimden gerek.

Uykuların kaçıp da yıldızları saydığın olursa, 

Yanıbaşında saçlarını okşayan ellerim gerek.

Özlemlerin artıp da hep yanında istersen, 

Dudaklarına dudaklarımın sıcaklığı gerek.

Sevgiden iştahın kesilip aç kalırsan, 

Ruhuna gönül bahçemden güller gerek.

Yastığa başını koyduğunda uykuların tutmazsa, 

Benimle sarmaş dolaş olacağın rüyalar gerek.

Gün gelirde özgürlüğünü hissedersen, 

Parmağına takacağım sihirli halka gerek, 

Gönül bahçende tekrar kırmızı güller açarsa, 

Beş kişinin toplandığı nikah masası gerek.

Mutluluktan birlikte bulutların üstünde uçarsan, 

Tanrının bahşedeceği bir can gerek, 

Saçlarının ağardığı, gözlerinin kapandığını görürsen, 

Üstünde hüvel baki yazan mermerden  bir mezar gerek.

Kalbinde hep güzellik iyilik olduğunu bilirsen, 

Tanrının bahşedeceği cennetin meyvesi gerek.', 'Yüreğin kabarıp adeta kıpır kıpır olursa,  Kalbindeki yarana aşk merhemimden gerek. Uykuların kaçıp da yıldızları saydığın olursa,  Yanıbaşı...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gerek-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gönül Uğruna', 'bir-gonul-ugruna-cafer-tayyar-ozkan-8yp0k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vurgunlar yedim ben aşk denizinde, 

Dağların ardından ah sesimi duydun 

Sürgün yaşarken kalbinin mahzeninde, 

Bir gönül uğruna yazan kalbimi sevdin 

Bugün yine seni çektim uzaktan içime 

Yüreğime kokunun dolduğunu hissettim 

Doldurmuştun boş olan sevgi haznemi 

Görebilme umutlarımı hep erteledim 

Sevmiştim bir kere inan ta yürekten

Mutluluğun resmini yaptığımı gördüm

Sevgimi yaşatmaya ant içtim gönülden

Sensizlikten sabır çektiğimi bildim

Güzel gözlerine vurgunum aşkını içtim

Saçlarına inci tanesi dizdiğimi anladım

Varlığınla hayat buldum geliverseydin

Kaderine mazide kalan ukdemi yazdım', 'Vurgunlar yedim ben aşk denizinde,  Dağların ardından ah sesimi duydun  Sürgün yaşarken kalbinin mahzeninde,  Bir gönül uğruna yazan kalbimi...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-gonul-ugruna-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilir misin?', 'bilir-misin-cafer-tayyar-ozkan-ijjqr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Damarlarımın duygulardan patlarcasına atışına, 

Bedenimi sarmalayan aşk ateşinin heyecanına, 

Sensizliğe mahkum yıldızlı gecenin karanlığına, 

Bu yürek nasıl dayanır bilir misin? 

En güzel rüyalarda seninle birlikte olacaksam, 

O anlamlı sevgiyi seninle birlikte duyacaksam, 

Maral gözlerinde istediğim dünyayı göreceksem, 

Bu yerler nasıl görünür bilir misin? 

Ne zaman gezsem, görürüm sarmaş dolaş aşıkları, 

Boynum bükük kalır, bugünden yaşarım yarınları, 

Ne kollarımı, ne koynumu dolduracak umutları, 

Bu beden nasıl avunur bilir misin?', 'Damarlarımın duygulardan patlarcasına atışına,  Bedenimi sarmalayan aşk ateşinin heyecanına,  Sensizliğe mahkum yıldızlı gecenin karanlığına...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilir-misin-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-cafer-tayyar-ozkan-hnypc', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk çok müthiş bir şey.

Benim için sevinç olan, 

Onun için acılar veren.

Bazen bir zümrütten daha değerli

Bazen de bir candan bile üstün

Aşk hiçbir yerde satılmaz

O yüreklerde hissedilir, yaşanır

Aşk öyle değerli bir şey ki.

Değeri parayla pulla ölçülmez

Hassas bir şeydir ama tartılmaz

Pazarlığa tabi olmayan bir şey

Satışa gelmez çünkü elle tutulmaz

Gözlerden yaşlar getirir görünmez

O gönüllerde filizlenir, düşlenir.

Aşk inan aptalca bir şey

Günlerce insana bir şey yedirtmez

Aylarca kalbine bir söz geçirtmez

Damarlara giren zehir gibi bir şey

Bazen tatlı bir acı verir kalbe

Bazen de uğur böceğiyle gelir

O çiçeklerde bilinir, özlenir.

Aşk biraz da çılgınca bir şey

Bazen canım bedenleri köprüden atlatır

Bazen de arabanın gaz pedalını kökletir

Mantığın zorlandığı kahır gibi bir şey

Zorlamaya gelmez çabuk kaybolur

Bir melek gelir çalarsa kalbini

O kara toprakta verilir, ödenir.', 'Aşk çok müthiş bir şey. Benim için sevinç olan,  Onun için acılar veren. Bazen bir zümrütten daha değerli Bazen de bir candan bile üstün Aşk...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ask-131-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Şerbetim', 'ask-serbetim-cafer-tayyar-ozkan-ejlj2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu dizeler bizi anlatsın

Yaşasın hep yaşatsın

Değil sana bu dizeler, 

Dizeleri döken yüreğim feda olsun

Sensiz geçecek günlerim inan solsun

Sana dar gelse bile engin yüreğim

Sen benim için önemlisin

Sen düşlerimde yaşadığımsın

Sen benim için çok değerlisin

Dilim ne söylerse söylesin

Bu yürek senin için atıyor bilesin

Öl de ölsün, sev de sevsin

Ama yeter ki yürekten sevsin

Yeter ki inansın, güvensin

Senden sadece beklentim

Gel beraber içelim aşk şerbetim', 'Bu dizeler bizi anlatsın Yaşasın hep yaşatsın Değil sana bu dizeler,  Dizeleri döken yüreğim feda olsun Sensiz geçecek günlerim inan solsun ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ask-serbetim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Hasreti', 'ask-hasreti-cafer-tayyar-ozkan-m73i6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hırçın masmavi denizde

Seni gördüm sokuldum yanına

Gönlüm çok sevdi düşünmeden yuttum 

Aldım kanayarak içime

Ey yüreği vefasız sevgili! 

Aşkın zokasını yutturdun bana

Balığın masumca oltayı, 

Azığım diyerek bir lokmada yediği gibi.

Nafile kaçışı olmuyor, 

Nereden bilsin bu gülüşü yaralının yüreğini, 

Bir tutam aşk hasretinin öldüreceğini.', 'Hırçın masmavi denizde Seni gördüm sokuldum yanına Gönlüm çok sevdi düşünmeden yuttum  Aldım kanayarak içime Ey yüreği vefasız sevgili!  Aşk...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ask-hasreti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ant İçtim Gönülden', 'ant-i-ctim-gonulden-cafer-tayyar-ozkan-y7t5z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bugün yine seni çektim içime 

Kokun sinmişti yüreğime 

Doldurmuştu boş olan sevgi haznemi 

Görebilme umudumu yitirsem de 

Sevmiştim bir kere gönülden 

Mutluluğu unutmuş olsam da 

Sevgini yaşatmaya ant içtim gönülden....', 'Bugün yine seni çektim içime  Kokun sinmişti yüreğime  Doldurmuştu boş olan sevgi haznemi  Görebilme umudumu yitirsem de  Sevmiştim bir kere...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ant-ictim-gonulden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlayacaksın', 'anlayacaksin-cafer-tayyar-ozkan-zdcge', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Parıltılı bir Başkent’in lacivert karanlığında, 

Aç pencereni bak göklere, çoban yıldızını göreceksin.

Sen tatlı bir uyku beklerken sıcak yatağında, 

Sana gönderdiğim aşk melekleriyle konuşacaksın.

Sevda şarkılarını ay ışığında mırıldandığında, 

Yıldızlardan sesinin bana döndüğünü hissedeceksin.

Gülistanıma ektiğim aşk tohumlarında, 

En güzel çiçeklerden taçlar bulacaksın.

Yokluğumda kan ter içinde  gördüğün her düşünde, 

Senin için yaptığım en güzel bestelerimi  duyacaksın.

Seni, beni, biz yapacak sır için elindeki çiçeğin tacından, 

Sabırla kopara kopara sonunda seviyor diyeceksin.

Sımsıcak bir tebessümle beklediğin her gününün, 

Ondört Şubat sevgililer günü olmasını isteyeceksin.

Seni seviyorum diyebilmenin hazzını yaşarken, 

Dikeni alınmış taze bir gül goncası bekleyeceksin.

Bir gün gelecek bekliyorum, diliyorum, sevgiçelenim, 

O zaman sevmekle acımak arasındaki farkı öğreneceksin.

Belki de sana olan büyük ve ölümsüz aşkımın manasını, 

Ak düşmüş saçlarınla, mezar taşıma bakıp anlayacaksın.', 'Parıltılı bir Başkent’in lacivert karanlığında,  Aç pencereni bak göklere, çoban yıldızını göreceksin. Sen tatlı bir uyku beklerken sıcak ya...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anlayacaksin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak', 'tutsak-i-rfan-cebeci-vuj2a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir kıvılcım yakmadan geceleri, 

Saklan düşlerden, kimse görmesin.

Cümlelere katmadan heceleri

Zincir vururum; kimse bilmesin.', 'Bir kıvılcım yakmadan geceleri,  Saklan düşlerden, kimse görmesin. Cümlelere katmadan heceleri Zincir vururum; kimse bilmesin....', ARRAY['Türk Edebiyatı','Şiir','İrfan Cebeci']::text[], 8.5, '{"poet":"İrfan Cebeci","poet_slug":"i-rfan-cebeci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/tutsak-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vade', 'vade-hikmet-szlemiolur-j14me', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'gitmek cok uzaklara

kendimle

bakmak kendime

ve egilmemek kimseye

kendime

ve el uzatmamak

icime ay girmekte

paramparca olmusum

denendiniz

ve vadeniz doldu', 'gitmek cok uzaklara kendimle bakmak kendime ve egilmemek kimseye kendime ve el uzatmamak icime ay girmekte paramparca olmusum denendiniz ve ...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Szlemiolur']::text[], 8.5, '{"poet":"Hikmet Szlemiolur","poet_slug":"hikmet-szlemiolur","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/vade-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan', 'vatan-hikmet-szlemiolur-hsgrt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sakaklarimda dag suyu

ve zeytinlikler

dinle

uguldayan zamani

kayalar, daglar

seni tuttuk 

kaz daglarinin basina koduk

yollara vurdugumuz sevgimizi

ruhumuzu paylastik

muhur vurdurtmasina', 'sakaklarimda dag suyu ve zeytinlikler dinle uguldayan zamani kayalar, daglar seni tuttuk  kaz daglarinin basina koduk yollara vurdugumuz sev...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Szlemiolur']::text[], 8.5, '{"poet":"Hikmet Szlemiolur","poet_slug":"hikmet-szlemiolur","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/vatan-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'An', 'an-hikmet-szlemiolur-5w5ww', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yakalamak zamani bir ucundan

ve dokunmak her dusen damlaya

zaman aglamakta, 

zaman yagmur ve seller gibi

donmek ve bitmek', 'yakalamak zamani bir ucundan ve dokunmak her dusen damlaya zaman aglamakta,  zaman yagmur ve seller gibi donmek ve bitmek...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Szlemiolur']::text[], 8.5, '{"poet":"Hikmet Szlemiolur","poet_slug":"hikmet-szlemiolur","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/an-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vurgun', 'vurgun-hikmet-szlemiolur-fvisf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ne zaman bir aci saplansa icime

aklima sen gelirsin

kapindan ciktigim an kavgaya

ardimdan 

vurdugun bakislarin onumde

  ve dokulup giden kara

      adam

   onumden

icime azrail korkusu, 

    adin gibi

adim gibi, sakallarim gibi

dokunsa kuzgun karasi

  mapuslar

olum solugu burnunda

	kan aglayan sarigi 

	 kara adamlar

disarda olen birisi var

	ellerinde kelepce

  disarda olumle dugun var

ve ben fislenmisim

ardimda dilsiz 

	 kor

  topal bir kurt

dondugumde 

calinan kapilar

 esiginde cikmalisin

saplamalisin yine o aciyi icime

	gulmelisin

kargiyi vurmalisin icime

burkulmali kalbim

	ta ki ciksin a l e v i

  suskun dudaklarimdan', 'ne zaman bir aci saplansa icime aklima sen gelirsin kapindan ciktigim an kavgaya ardimdan  vurdugun bakislarin onumde   ve dokulup giden kar...', ARRAY['Türk Edebiyatı','Şiir','Hikmet Szlemiolur']::text[], 8.5, '{"poet":"Hikmet Szlemiolur","poet_slug":"hikmet-szlemiolur","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/vurgun-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Eftelya', 'mavi-eftelya-eren-serbest-yamxm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen istemli sevgimin, son demiydin ela gözlüm.

Sen ki; diyarlar kadar ırak iken hasretine gebe komadın beni. 

Sen ki; hançerler giren sinemi tek dokunuşuyla saran, 

Sen; her gece düşlediğim pamuk yüzlü eftelyamdın benim. 

Seni gecelerce hıçkırıklarla uyandığım kabuslarda bırakamadım.

Peşinden gelmek istedim arşa, 

Huzurunda hakimin tazarruat ettim rüyalarımda, 

Olmadı affeyle ela gözlüm.

Bilmezdim kara toprağa düşenin böyle hasretle anılacağını; 

Bir gün onun bir anı değil sevginin ta kendisi olacağını, 

Böyle bir acıya na’ra larım dayanmıyor ne olur anla.

Ben sensiz yapamıyorum mavi eftelyam 

Bulutlar kadar hürdün, 

Guruba karşı oturup kızıl şafakla dertleşirken bulmuştum ya seni...

Yine oradayım.Söyle o art niyetli melaikeye 

Şafak kızıl kana bürünmeden aşkı teslim alamayacak hüzün...!', 'Sen istemli sevgimin, son demiydin ela gözlüm. Sen ki; diyarlar kadar ırak iken hasretine gebe komadın beni.  Sen ki; hançerler giren sinemi...', ARRAY['Türk Edebiyatı','Şiir','Eren Serbest']::text[], 8.5, '{"poet":"Eren Serbest","poet_slug":"eren-serbest","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mavi-eftelya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk Zamanı', 'mutluluk-zamani-sair-ciyak-hsvml', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dokunmayın çiçeklerime

Akan dereme zehirlerinizi boşaltmayın

Bırakın dönsün dünya

Başımın üstünden geçsin bembeyaz bulutlar

Döksün yağmurlarını çatlamış kızıl dudağa

Engel olmayın.....

Çiçekler dolsun her bir yanım 

Kıpkırmızı karanfiller....

Çavlan dökülsün başımdan

Aksın ırmağın yüreğine coşarak

Koşsun yol ayrımlarına

Dağılsın dört bir yana muştuyla....

Çığırsın mutluluğu, sevgiyi

Duyana duymayana....

Tıkamayın kulaklarınızı

Gözlerinizi kapamayın

Duyun gökyüzünde süzülen kuşun

Kanat sesini

Görün gök mavi sonsuzda

Apak umudu

Dinleyin soluklaşını daha derinden ki

Çırpsın kanatlarını daha yürekten.....

Geçirilen her an karşı rüzgarları yaratır

Unutma.......

Düşen her damla yaş yanaklarından

Soldurur yeni biten taze çiçeği

Uçsun umudum akarak mavide

Geçsin dağdan söğüt ağacından

Konsun yüreklerimizin dalına....', 'Dokunmayın çiçeklerime Akan dereme zehirlerinizi boşaltmayın Bırakın dönsün dünya Başımın üstünden geçsin bembeyaz bulutlar Döksün yağmurlar...', ARRAY['Türk Edebiyatı','Şiir','Şair Ciyak']::text[], 8.5, '{"poet":"Şair Ciyak","poet_slug":"sair-ciyak","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/mutluluk-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahçıvan', 'bahcivan-omer-sevim-etp2h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir sevdadır bahçıvan için gülü sulamak

Elleriyle okşarken

Ruhuyla konuşur güllerle

Ellerine batan dikenlerse

Gülün sevgi sözleridir onun için

Bahçıvan

Yüreği sevdalardan dertli

Bazen dalıyor derince

Uzaklara gözleri mıh gibi

Düşünüyor bahçıvan

Mevsimsiz tutulduğu sevdaları

Sevdalısını düşünüp uykusuz kaldığı geceleri

Düşünüyor bahçıvan

Yüreğinden kopan göz yaşlarını saklayarak

Korkuyordu bahçıvan

Sevdalısına hak ettiği sevgiyi verememekten

Kaçıyordu sevdadan bahçıvan

ızdırabını içine gömerek', 'Bir sevdadır bahçıvan için gülü sulamak Elleriyle okşarken Ruhuyla konuşur güllerle Ellerine batan dikenlerse Gülün sevgi sözleridir onun iç...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevim']::text[], 8.5, '{"poet":"Ömer Sevim","poet_slug":"omer-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bahcivan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-omer-sevim-5eay9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ruhul kabz meleği randevu almaz

Aniden zamansız geliverir

O da elçidir elçiye zeval olmaz

Görevinde sadıktır salise şaşırmaz

Ölüm yokluk değildir

İlahi adaletin tecellisidir

Ölüm ebediyyete açılan kapı

Kainatı yaratanın mucizesidir

Ölüm bazen ulaşılmaz kadar uzak

Çarpan kalp kadar yakındır bazen

Bir çoçuk gibi sevindirir bazen ölüm

Bazende ağıtların sesi semada yankılanır

Ölümden kaçış yoktur asla

Zamanla döner dolaşır

Gözler önünde hep aynı fasıla', 'Ruhul kabz meleği randevu almaz Aniden zamansız geliverir O da elçidir elçiye zeval olmaz Görevinde sadıktır salise şaşırmaz Ölüm yokluk değ...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevim']::text[], 8.5, '{"poet":"Ömer Sevim","poet_slug":"omer-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/olum-68-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölünceye Dek 2', 'olunceye-dek-2-yusuf-kaya-glytp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ilkbahar günü vermişim sana, 

İlk mektubumla bir beyaz çiçek, 

Hani söz vermiştin ey canım benim 

> diyordun ölünceye dek, 

O an oturmuştuk bir çam altına, 

Ayrılmayalım diye etmiştik dua, 

Yaşlı gözlerle yaslanıp sağ omzuma 

> diyordun ölünceye dek 

Vuslatın şerbetini o zaman içmiştik 

Ayrılmamaya yemin etmiştik 

Sevgimiz için bir gül dikmiştik 

> diyordum ölünceye dek 

Geçenlerde uğradım bence, kutsal mekana 

Eski hali kalmamış dönmüş virana 

Aşkımıza şait ağaç seni soruyor bana 

Cevap veremeyeceğim ölünceye dek 

Gördüm ki gülümüz solmuş 

Meğer gözyaşının sahtesi de olurmuş 

Öğrendim ki düğünün başkasıyla olmuş 

> diyorum ölünceye dek', 'Bir ilkbahar günü vermişim sana,  İlk mektubumla bir beyaz çiçek,  Hani söz vermiştin ey canım benim  > diyordun ölünceye dek,  O an oturmuş...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Kaya']::text[], 8.5, '{"poet":"Yusuf Kaya","poet_slug":"yusuf-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olunceye-dek-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayboluşu Seven Hainin Seyrelen Şiiri', 'kaybolusu-seven-hainin-seyrelen-siiri-ahmet-ozturk-nv5cu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elimin tersine doğru bir şiir seyreliyor

Muhakkak bir çare-i mutlak bulacak hain

İzlenecek solukların sıcak baskısıyla

Uzun ve deli karanlık bir gölgenin

Omuzlarımda ağırlığını görüyorum

Israrla seviyorum kayboluşu ve kazananları

Ama bu kaybedişi bile galibiyet gibi seviyorum

Muhakkak bir şifa-i derman bulacak hain

Bir şiir dar sokakta ıslanmış titriyor

Elimin tersine doğru seyreliyor

Kalem elime yürüyor, mürekkep kağıda

Elimin tersine doğru bir şiir seyreliyor

Israrla seviyorum kayboluşu ve kazananları

(19 ocak 2003) 

(01-22 etiler)', 'Elimin tersine doğru bir şiir seyreliyor Muhakkak bir çare-i mutlak bulacak hain İzlenecek solukların sıcak baskısıyla Uzun ve deli karanlık...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kaybolusu-seven-hainin-seyrelen-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle Olmak', 'seninle-olmak-akin-simsek-9g8bn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Doğan güneşe baktım

Seni andım

O güneşin sıcaklığında

Bu günün de başlangıcında

Soluduğum havada

Kalbimin derinliklerinde

Yalnızca sen vardın

Seninle güne başlamak

Bu hayatı yaşamak

Geleceği paylaşmak

Tek dileğim bu

Seninle olmak...', 'Doğan güneşe baktım Seni andım O güneşin sıcaklığında Bu günün de başlangıcında Soluduğum havada Kalbimin derinliklerinde Yalnızca sen vardı...', ARRAY['Türk Edebiyatı','Şiir','Akın Şimşek']::text[], 8.5, '{"poet":"Akın Şimşek","poet_slug":"akin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seninle-olmak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adımız Serseri, Kalbimiz Değil', 'adimiz-serseri-kalbimiz-degil-hakki-yalcin-9tkqr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bizdeki acıyı çekmeyen bilmez

Elimizde kadehler birgün eksilmez

Biz severiz bizi kimseler sevmez

Adımız serseri, kalbimiz değil

Dertlidir şarkılar dilimizdeki

Bir ömür çizgisi yüzümüzde ki

Yağmur değil yaştır gözümüzde ki

Adımız serseri, kalbimiz değil', 'Bizdeki acıyı çekmeyen bilmez Elimizde kadehler birgün eksilmez Biz severiz bizi kimseler sevmez Adımız serseri, kalbimiz değil Dertlidir şa...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Yalçın']::text[], 8.5, '{"poet":"Hakkı Yalçın","poet_slug":"hakki-yalcin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/adimiz-serseri-kalbimiz-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavan', 'yavan-ali-serttas-3e81v', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen ne yavansın

Yavanların kralısın

Ama nekadar yavan olsanda

SENİ SEVİYORUM

YAVANIM benim.', 'Sen ne yavansın Yavanların kralısın Ama nekadar yavan olsanda SENİ SEVİYORUM YAVANIM benim....', ARRAY['Türk Edebiyatı','Şiir','Ali Serttaş']::text[], 8.5, '{"poet":"Ali Serttaş","poet_slug":"ali-serttas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yavan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Final-Vize', 'final-vize-ali-serttas-gykap', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bende geçermişim

Finali, vizeyi...

Tek seni sevmezmişim

Benim işveli sevgilim..

Senden başka şu dünyada

Ne güzeller varmış

Hadi sana geçmiş olsun

Buraya kadarmış

Aşkımda sevgimde...', 'Bende geçermişim Finali, vizeyi... Tek seni sevmezmişim Benim işveli sevgilim.. Senden başka şu dünyada Ne güzeller varmış Hadi sana geçmiş ...', ARRAY['Türk Edebiyatı','Şiir','Ali Serttaş']::text[], 8.5, '{"poet":"Ali Serttaş","poet_slug":"ali-serttas","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/final-vize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kankurutan', 'kankurutan-ali-kalayci-4tz45', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ağlatmak ağzı kara şarkıların hüneri 

benimki öylesine sitem

eczaların çalımıyla zağlanmış yüreğimi,

nokta kadar bir sevdada sınamak.

gururunu çoktan kırdım kanağan gülüşlerimin.

evet hekimlere yasakladım acılarımı.

kalleşim, kundaklayıp gök gürültülerini

gecelerce yağmurları kınsız bıraktım

gecelerce acılarımın zangocuydu susmak.

ve hovarda bir çan sesi gecelerce

bir yerlerde ilan-ı aşk makamı

geceler, geceler, geceler kadar çınlak..

belki de mümkündü seviyorum diyebilmek.

hasretim ilk mektep çocuklarıyla yaşıt

sırtım zehir zemheri

ah benimki diyebilmeden sevmek..

1987', 'ağlatmak ağzı kara şarkıların hüneri  benimki öylesine sitem eczaların çalımıyla zağlanmış yüreğimi, nokta kadar bir sevdada sınamak. gururu...', ARRAY['Türk Edebiyatı','Şiir','Ali Kalaycı']::text[], 8.5, '{"poet":"Ali Kalaycı","poet_slug":"ali-kalayci","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kankurutan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çulsuz', 'culsuz-i-hsan-uncuoglu-l8jki', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ey Meclis duy deme kimene 

Milletinin sorunlarını sor dinle! 

Abla her deyişin müthiş bir adım 

Hayatta hep kara karanlık kaldım

Hiç sorulmadı halim geçti nice yıllar

İnan satır satır yüreğimi dağladın ağladım, 

*** 

Perişan yazık kördüğüm olmuş sorumlular 

Aralarda eller yaşadı yaptılar altın saraylar 

Rahatları kaçmasın dişim sıktım aman dedim 

Şimdiye kadar kimseye açılmadım söylemedim

Varoşlarda ayaz geceler o çatısız eski viranede 

Hep ağlar giderim beş pulla çulsuz kalan o kişi benim,', 'Ey Meclis duy deme kimene  Milletinin sorunlarını sor dinle!  Abla her deyişin müthiş bir adım  Hayatta hep kara karanlık kaldım Hiç sorulma...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/culsuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Kadarcık', 'sen-kadarcik-hasan-koca-2-3e05v', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ne istemiştik ne sanmıştık

ama bak ne oldu? 

sen uçsuzdun düşüncende

ben sahipsizdim kırda

sen kapkara aysızdın..

ben arsız! 

bu tanıdık seviçler niye bekler ki

tan ağaracak bebek git artık 

seni sığdırabilseybim

şu zavallı kalbime

onla çarpıp yüzüme sürseydim

logaritmanı isteyemedim

utandım! 

zavallı zaman

yaşlanıp uçup gidiyor

sagamadı hayvanları hiç

e kırsalı bilmez

türkü söylemez

yalan bilmez

gücenmez! 

pahalı alışkanlık

seni sevmek bilirim

yavaş yürümek yok

hırsına hırs koşacaksın

bağıracaksın 

kancık sevmelere inat 

taşıracaksın bendini

sagol da gel canım! 

yasakmış kural dışıymış de 

yine gel

bak kalimeler bile yavan sensiz

nesir anlamsız 

gel şiirime kelime olası

gel içerimin yangın yeri

gel canı cananım! 

bari sen kadarcık! 

30,01,2003  20,55', 'ne istemiştik ne sanmıştık ama bak ne oldu?  sen uçsuzdun düşüncende ben sahipsizdim kırda sen kapkara aysızdın.. ben arsız!  bu tanıdık sev...', ARRAY['Türk Edebiyatı','Şiir','Hasan Koca 2']::text[], 8.5, '{"poet":"Hasan Koca 2","poet_slug":"hasan-koca-2","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sen-kadarcik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Sessizdiki Gİdişin', 'oyle-sessizdiki-gi-disin-ensar-cevval-b3wf3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her sabah, rüyalarımızı anlatırdık, 

her sabah bir başka heyecanla..

Ben, seni..

Sen ise, ölümü., 

Kollarımız sıkı sıkı sarılıyken

gözbebeklerimden usulca kayıpta gittin.

Geceleri, usul usul gidişini gördüm

sokaklarda ayak seslerini..

Ben, sana tutkunken, 

ben, sana sevdalıyken 

seni, ölesiye sevmişken hesapsız

sen, sevmesen de olurdu.

Hiçbirşey koymadı bana

ölümle kaçışın, 

beni terkedişin kadar.

Ensar CEVVAL İstanbul', 'Her sabah, rüyalarımızı anlatırdık,  her sabah bir başka heyecanla.. Ben, seni.. Sen ise, ölümü.,  Kollarımız sıkı sıkı sarılıyken gözbebekl...', ARRAY['Türk Edebiyatı','Şiir','Ensar Cevval']::text[], 8.5, '{"poet":"Ensar Cevval","poet_slug":"ensar-cevval","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oyle-sessizdiki-gidisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇİVİLENMİŞ GÖZLERİM', 'ci-vi-lenmi-s-gozleri-m-ahmet-kurt-pm3vn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevda ağacının dallarında, 

Solgun ve bitkin, 

Tedirgin, ürkek, 

Çarmıhına 

Çivilenmiş gözlerim.

Yorgun gecelerin

Kör noktalarında buluşmuş

Bakışlarımız, özlemimiz, 

Amansız duygularla, 

Nokta nokta işlenmiş, 

Benliğimiz, 

Gökyüzünün apansız

Kayan yıldızlarına

Kör gecelerde, 

Çivilenmiş gözlerim...', 'Sevda ağacının dallarında,  Solgun ve bitkin,  Tedirgin, ürkek,  Çarmıhına  Çivilenmiş gözlerim. Yorgun gecelerin Kör noktalarında buluşmuş ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurt']::text[], 8.5, '{"poet":"Ahmet Kurt","poet_slug":"ahmet-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/civilenmis-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yanılıp Yakana Bakışımı Taktığında', 'yanilip-yakana-bakisimi-taktiginda-lale-muldur-6v1mg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'nedir senin yerin

şiir uzamımda benim

kurtulamadığım bir imge misin, 

duraksadığım bir dize

bir şiirde mi tutuklu kaldım ya da yüreğinde

az mı tanış ö
..........
..........', 'nedir senin yerin şiir uzamımda benim kurtulamadığım bir imge misin,  duraksadığım bir dize bir şiirde mi tutuklu kaldım ya da yüreğinde az ...', ARRAY['Türk Edebiyatı','Şiir','Lale Müldür']::text[], 8.5, '{"poet":"Lale Müldür","poet_slug":"lale-muldur","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yanilip-yakana-bakisimi-taktiginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-mur-der-2exr7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevebildiği derecede özgürdür insan, 

Sevebildiği derecede bahtiyar.

En umulmadık anda bile geçebiliyorsa dalgasını hayatla

Zaten aşmıştır o insan, olabildiğince özgürdür.

Birgün umudun kalmasa bile hayattan, 

Dön etrafına bak, silkin biraz.

Belki o zaman kendine gelirsin.

Belki o zaman yine sevebilirsin.

                      

(2002 yurtta)', 'Sevebildiği derecede özgürdür insan,  Sevebildiği derecede bahtiyar. En umulmadık anda bile geçebiliyorsa dalgasını hayatla Zaten aşmıştır o...', ARRAY['Türk Edebiyatı','Şiir','Mur Der']::text[], 8.5, '{"poet":"Mur Der","poet_slug":"mur-der","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hayat-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolcular', 'yolcular-muttalip-tas-oadcl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bizi ölüm diriltecek; can yakan 

	Azabını tadarak son doğumun

	Gideceğiz.. ya kuşlar gibi pür neşe

	Yahut yetim çocuklar gibi mahzun...

	

	Yaşıyoruz sandığımız günleri

	Yolculuk telaşı saracak belki

	Gideceğiz.. elveda diyemeden

	Görünmeden, göremeden kimseyi..

	

	Gaflet uykusundan kalkıp ansızın

	Kucağına düşeceğiz vuslatın

	Gideceğiz.. bilmeyen kalmayacak 

	Yalan olduğunu Yalan Dünyanın...

	

	Sağlar, sevine dursun halimize

	“Öldü” diyecekler ölüler, bize

	Gideceğiz.. neden, nasıl gerekmez

	Ölür mü karışsa damla denize? ! ...', 'Bizi ölüm diriltecek; can yakan  	Azabını tadarak son doğumun 	Gideceğiz.. ya kuşlar gibi pür neşe 	Yahut yetim çocuklar gibi mahzun... 	 	Y...', ARRAY['Türk Edebiyatı','Şiir','Muttalip Taş']::text[], 8.5, '{"poet":"Muttalip Taş","poet_slug":"muttalip-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yolcular-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-tulay-esat-meswr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sonbahari yasiyorum, 

Icimdeki son bahari..

Yaprak dökümü, 

Tilsim tilsim heybetli yagmurlar..

Bir veda anini hatirlar gibi, 

Sonbahari yasiyorum, 

Yüregim firtinanin dansina eslik ediyor.

Sonbahari yasiyorum, icimdeki son bahari! 

Sari lekeleri kurutuyorum bitiveren düslerimde, 

Ciplak dallarin küskünlügüyle küsüyorum; 

Sarilip sarilip öpüyorum gözlerini kül rengi günesin, 

Karisik sesler korkumu uyandiriyor.

Saatlerini sayiyorum, 

Saniyelerini ceyiz sandigimda sakliyorum.

Son bahar sona eriyor görüyorum..

Sonunda katiliyorum gidisine, 

Pesinden sürükleniyorum.

Bir firari gülüyor soguk gecede, 

Kahkahasi kulaklarimda cinliyor.

Yorgan dösek yatan Fatma baci

Kahrediyor sonbahara.

Akca gelin sevdigini yolcu ediyor, 

Tel tel oyalayip yazmasina...

Derin, koyu bir sessizlige dolduruyorum

Son sözlerini.

''Gene beklerim'' diyorum, 

Veda etmek yakismiyor son bahara.

Gelir mi bilmem...', 'Sonbahari yasiyorum,  Icimdeki son bahari.. Yaprak dökümü,  Tilsim tilsim heybetli yagmurlar.. Bir veda anini hatirlar gibi,  Sonbahari yasi...', ARRAY['Türk Edebiyatı','Şiir','Tülay Esat']::text[], 8.5, '{"poet":"Tülay Esat","poet_slug":"tulay-esat","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sonbahar-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allahım Neydi Günahım', 'allahim-neydi-gunahim-kayahan-acar-h1ma0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Allahım neydi günahım 

Günahım neydi Allahım 

Dualarımda yalvarmıştım 

Onla olmaktı isyanım 

Can yoldaşım 

Arkadaşım 

Kaderimdi 

Sen yazmıştın 

Ben nerde yanlış yaptım 

Bitti dünyam, ziyan oldum, ziyan 

Ah bir anlasam 

Nerede nerede nerede 

Ben nerde yanlış yaptım 

Nerede nerede nerede 

Ben nerde yanlış yaptım 

Allahım 

Mumlar yakmıştım 

Yalvarmıştım 

Sen yazmıştın, olabilirdi 

Olabilirdi olabilirdi 

Sevgi yeterdi, sen kâdirdin 

Allahım 

Ben nerde yanlış yaptım 

Allahım', 'Allahım neydi günahım  Günahım neydi Allahım  Dualarımda yalvarmıştım  Onla olmaktı isyanım  Can yoldaşım  Arkadaşım  Kaderimdi  Sen yazmışt...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/allahim-neydi-gunahim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anla Halimden', 'anla-halimden-kayahan-acar-jzkwp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir daha 

Bir daha gelmek olsa dünyaya 

Düşünmeden düşerdim yine yollarına 

Bir daha 

Bir daha gelmek olsa dünyaya 

Düşünmeden atılırım kollarına 

Çıkamam menzilinden 

Tutsağım esirim ben 

Anla halimden 

Günlerim sana kilitlenmiş 

Geceler sana düğümlenmiş 

Bu canım sana mühürlenmiş 

Çıkamam senin menzilinden 

Günlerim sana kilitlenmiş 

Geceler sana düğümlenmiş 

Ecelim sana mühürlenmiş 

Çıkamam senin menzilinden 

Çıkamam menzilinden 

Tutsağım esirim ben 

Anla halimden', 'Bir daha  Bir daha gelmek olsa dünyaya  Düşünmeden düşerdim yine yollarına  Bir daha  Bir daha gelmek olsa dünyaya  Düşünmeden atılırım koll...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anla-halimden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ARTIK AĞLAMAM LÂZIM', 'artik-aglamam-l-zim-kayahan-acar-648jh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnız günlerimden biri 

1997 İstanbul 

Hani her şeyi hisseden 

Hani benim yarımdın sen 

Yalan söyleyen de sen 

Kızıyorsam sevgimdendir 

Hep sevgimden 

Şimdi artık git istersen 

Sigaram içkim 

Bitkinim bitkin 

Kaç gündür oruçtayım 

Artık ağlamam lâzım 

Kaç gündür habersizim 

Adaletin bu mu senin 

Şimdi hepten git istersen 

Çok mu önemliydi sanki 

Yalnızca bir öfkeydi, öfkeydi 

Bırakıp gittin sen beni 

Merak eden bendim seni 

Halimi hiç sordun mu ki 

İşte sevgi, işte sevda 

Yağmur gibi sokaklarda 

Korkuyorum bu gidişle 

Sev dedin, sevdim işte 

İntikamsa aldın işte 

Korkuyorum bu gidişle sonum olacaksın 

Hadi canım, hadi sende 

Bu nasıl sevmekmiş böyle 

Şimdi sensiz gecelerde 

Acı veren bedenimle 

İşte, bir gece daha teslim oldu sabaha 

Ne kadar daha sensiz 

Şimdi burada yapayalnız 

Beni kime teslim ettin 

İstesem çok kısa da bulurdum seni 

İlk sekiz günü anlatamam 

Sağa dön yatamam 

Sola dön yatamam 

Aklımdan seni atamam 

Seni seviyorum 

Bu kadar konuştuğuma göre 

Çok şükür, bugün uyku var gözlerimde 

İstanbul''u bulutlar sarıyor, beni sardığı gibi 

İstanbul kararıyor gönlüm gibi 

Keşke burda olsaydın 

Yani şımarsaydın hattâ 

Onbir gün alargada 

Ve, onbir gün hiçbir olta atmadım tek bir balığa 

Oysa bilirsin çok severim tutmayı 

Tuta tuta tutulmayı öğrendim galiba 

Hani her şeyi hisseden 

Hani benim yarımdın sen 

Yalan söyleyen de sen 

Kızıyorsam sevgimdendir 

Hep sevgimden 

Şimdi artık git istersen 

Sigaram içkim 

Bitkinim bitkin 

Kaç gündür oruçtayım 

Artık ağlamam lâzım', 'Yalnız günlerimden biri  1997 İstanbul  Hani her şeyi hisseden  Hani benim yarımdın sen  Yalan söyleyen de sen  Kızıyorsam sevgimdendir  Hep...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/artik-aglamam-lazim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başı Boş Saatlerde', 'basi-bos-saatlerde-kayahan-acar-e1qpe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Başıboş saatlerde 

Alırım koynuma sevgilimi 

Başıboş saatlerde 

Çözülür ipleri dünyanın 

Başıboş saatlerde 

Kararır gözleri sevdanın 

Başıboş saatlerde 

Alırım koynuma sevgilimi 

Onsuz olmaz 

Çok alıştım 

Dayanamam 

Çok çalıştım 

Bir gün olmazsa 

Bir gün mutlaka', 'Başıboş saatlerde  Alırım koynuma sevgilimi  Başıboş saatlerde  Çözülür ipleri dünyanın  Başıboş saatlerde  Kararır gözleri sevdanın  Başıbo...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/basi-bos-saatlerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Anlamadın Ya', 'beni-anlamadin-ya-kayahan-acar-etwg8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'El ayak çekilince 

Sohbetler tükenince 

Dostlar eve gidince 

Bu geceler işkence 

Öper iki hece 

İsmi dudaklarım 

La-Fa-La-Sol 

La-Fa-La-Sol 

Sokakları kamçılıyor 

Rüzgârın sesi 

Gözlerim yanıyor 

Yağmur öncesi 

Her vesile ellerim 

Ellerini arıyor 

Her yanımı sarıyor 

O müthiş acıların 

Beni anlamadın ya 

Ben ona yanıyorum', 'El ayak çekilince  Sohbetler tükenince  Dostlar eve gidince  Bu geceler işkence  Öper iki hece  İsmi dudaklarım  La-Fa-La-Sol  La-Fa-La-Sol ...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/beni-anlamadin-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Garip Serçe', 'bir-garip-serce-kayahan-acar-k7vig', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çok sebebim vardı benim 

Çok kırıldım söylemedim 

Gözyaşımı göstermedim sana 

Çok sebebim oldu benim 

Kolay olsa ben giderdim 

Bu ne gitmek, bu nasıl sevda 

Yandı mı bu postaneler, yıkıldı mı yoksa 

Ne bir haber, ne merhaba 

Zindan bu dünya 

Uyutmuyor bu yaşananlar akşam olunca 

Sorma sorma sorma sorma 

Gül dalında bülbül değil, bir garip serçe 

Gül kokar dikenler batar, kaldım biçare 

Yandı mı bu postaneler, yıkıldı mı yoksa 

Ne bir haber, ne merhaba 

Zindan bu dünya 

Uyutmuyor bu yaşananlar akşam olunca 

Olmasaydı hatıralar, kahrolası yaşananlar 

Geceleyin deli eder beni 

Şu gözlerin olmasaydı, yüreğim taştan olsaydı 

Ne kolaydı unutması seni 

Yandı mı bu postaneler, yıkıldı mı yoksa 

Ne bir haber, ne merhaba 

Zindan bu dünya 

Uyutmuyor bu yaşananlar akşam olunca 

Sorma sorma sorma sorma 

Gül dalında bülbül değil bir garip serçe 

Gül kokar dikenler batar kaldım biçare 

Ne seninle ne de sensiz 

Olmuyor işte 

Yandı mı bu postaneler yıkıldı mı yoksa 

Ne bir haber ne merhaba 

Zindan bu dünya 

Uyutmuyor bu yaşananlar akşam olunca', 'Çok sebebim vardı benim  Çok kırıldım söylemedim  Gözyaşımı göstermedim sana  Çok sebebim oldu benim  Kolay olsa ben giderdim  Bu ne gitmek,...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/bir-garip-serce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esmer Günler', 'esmer-gunler-kayahan-acar-gcuw9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen beni bırakıp 

Böyle gitmezdin hiç 

Yapmazdın 

Ayları geçti ayrılık 

Sen delisin 

Yapma yapma 

Sen de mi 

Aklıma sığmıyor 

Sen de mi 

Sen misin her şeyi 

Silmekten bahseden 

Böyle gitmek var mıydı 

Demek yine bana hüsran 

Bana yine hasret var 

Yine bana esmer günler düştü 

Eyvah', 'Sen beni bırakıp  Böyle gitmezdin hiç  Yapmazdın  Ayları geçti ayrılık  Sen delisin  Yapma yapma  Sen de mi  Aklıma sığmıyor  Sen de mi  Sen...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/esmer-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çok Uzaklarda', 'cok-uzaklarda-kayahan-acar-zs9dg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Caddelerde rüzgâr 

Aklımda aşk var 

Geceyarısında 

Eski yağmurlar 

Şarkı söylüyorlar 

Sessiz usulca 

Özlediğim şimdi 

Çok uzaklarda 

Deli dolu günler 

Hayat güzeldi 

Kahkahalarıyla 

Günler geçerdi 

Ellerim uzanmaz 

Dokunamamki 

Özlediğim şimdi 

Çok uzaklarda 

O da özlüyormuş 

Benim bir tanem 

Çok üşüyormuş 

Ben olmayınca 

Öyle yazıyor 

Son mektubunda 

O da özlüyormuş 

Benim bir tanem 

Hep ağlıyormuş 

Ben olmayınca 

Öyle yazıyor 

Son mektubunda', 'Caddelerde rüzgâr  Aklımda aşk var  Geceyarısında  Eski yağmurlar  Şarkı söylüyorlar  Sessiz usulca  Özlediğim şimdi  Çok uzaklarda  Deli do...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/cok-uzaklarda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece Sen Daha Güzelsin', 'bu-gece-sen-daha-guzelsin-kayahan-acar-7jgiv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ay ışığında saçların 

Dalgalı denizler gibi 

Gece öyle güzel 

Öyle ki 

Sessiz 

Sakin 

Yalnız bizim 

Ve sen canım bu gece 

Daha güzelsin 

Dönüyor başım yine 

Yine başım dönüyor 

Güzelliğin bebeğim bu gece 

Beni sarhoş ediyor 

Ay ışığında gözlerin 

Parlayan yıldızlar gibi 

Gece öyle güzel 

Öyle ki 

Sessiz, sakin, yalnız bizim 

Ve sen canım bu gece 

Daha güzelsin', 'Ay ışığında saçların  Dalgalı denizler gibi  Gece öyle güzel  Öyle ki  Sessiz  Sakin  Yalnız bizim  Ve sen canım bu gece  Daha güzelsin  Dön...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bu-gece-sen-daha-guzelsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinin Hapsindeyim', 'gozlerinin-hapsindeyim-kayahan-acar-q8c61', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kaç gündür 

Hasretinle alevlenirken düşünceler 

Ben çılgın 

Ben yine gözlerinin hapsindeyim 

Ellerim yüzümde 

Susmuş dudaklarım 

İsyanlarda gönlüm 

Zaman gardiyandır 

Ah ben yine gözlerinin hapsindeyim 

Aman vermez hasretin 

Ay ay ay 

La la la 

İçimde martılar 

La la la 

Sen gözyaşlarımdasın 

La la la 

Akşam firarları 

La la la 

Sen gözyaşlarımdasın', 'Kaç gündür  Hasretinle alevlenirken düşünceler  Ben çılgın  Ben yine gözlerinin hapsindeyim  Ellerim yüzümde  Susmuş dudaklarım  İsyanlarda ...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gozlerinin-hapsindeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Odalarda Işıksızım', 'odalarda-isiksizim-kayahan-acar-9mpmc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Odalarda ışıksızım, katıksızım 

Viraneyim 

Seni sensiz duvarlara yazan benim 

Divaneyim 

Kanım aksın ki 

Terketmem seni 

Peşindeyim yar 

Ellerimsin gözlerimsin 

İnanmazsın yar 

Ben perişan 

Günlerim dar 

Anlamazsın yar 

Bir ömür bu zindanlarda 

Ellerimsin gözlerimsin 

Mahkûmum sana 

Davalı ben, davacı ben 

Yorgunum bu celselerden 

Dargınım sana 

Posta posta hatıralar 

Voltalarda yar 

Ben perişan, günlerim dar 

Anlamazsın yar', 'Odalarda ışıksızım, katıksızım  Viraneyim  Seni sensiz duvarlara yazan benim  Divaneyim  Kanım aksın ki  Terketmem seni  Peşindeyim yar  Ell...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/odalarda-isiksizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sarı Saçlarından Sen Suçlusun', 'sari-saclarindan-sen-suclusun-kayahan-acar-iat83', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adresim aynı 

Kaderim aynı 

Günlerim aynı 

Geceler aynı 

Sarı saçlım, hasretimsin sen 

Karadantel sokağında ben 

Kapımda akşam gülleri, mateminle tutuşurken 

Dumanım aynı 

Ateşim aynı 

Bulutlar aynı 

Gözyaşım aynı 

Sarı saçlım, hasretimsin sen 

Karadantel sokağında ben 

Kapımda akşam gülleri, mateminle tutuşurken 

Kankırmızı gözlerimden 

Sancıların gelip geçer 

Kim üzülür, kim bekler seni 

Ben tabii ki, ben birtanem 

Ter içinde 

İçim bileylenir 

Kankırmızı gözlerimden 

Sancıların gelip geçer 

Kim üşütür, kim yakar beni 

Sen tabii ki 

Sen birtanem 

Ter içinde 

İçim bileylenir 

Bu kaçıncı çalınışı kapımın 

Bu kaçıncı, sen değilsin başkası 

Peşimde mazinin ayak sesleri 

Nelerden vazgeçiyoruz bir düşünsene 

Kırık kalpler üstüne kuruyoruz birşey 

Bu kalleşlik, belki bana yakışmıyor ama 

Sarı saçlarından sen suçlusun', 'Adresim aynı  Kaderim aynı  Günlerim aynı  Geceler aynı  Sarı saçlım, hasretimsin sen  Karadantel sokağında ben  Kapımda akşam gülleri, mate...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/sari-saclarindan-sen-suclusun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yemin Ettim', 'yemin-ettim-kayahan-acar-7dheu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hüzün tünellerinde 

Soldum kederlerinde 

Cehennemde yansın bu dilim 

Bir yemin ettim ki, dönemem 

Seni versinler ellere 

Beni vursunlar 

Sana sevdanın yolları 

Bana kurşunlar 

Kıyametler kopuyor zavallı yüreğimde 

Tükendim, tükendim, tükendim artık 

Hiç mi özlemedin, hiç mi hakkım yok 

Bir ara, bir sor Allah aşkına', 'Hüzün tünellerinde  Soldum kederlerinde  Cehennemde yansın bu dilim  Bir yemin ettim ki, dönemem  Seni versinler ellere  Beni vursunlar  San...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yemin-ettim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçmem', 'vazgecmem-kayahan-acar-3kc1q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni çok, seni çok, seni çok sevdim 

Sana ben ömrümü canımı verdim 

Hain, zalim 

Beni bu sevda canımdan etse 

Dilim tutulsa, gözüm kör olsa 

Vazgeçmem yine de, vazgeçmem sevgili 

Vazgeçmem senden 

Beni bu sevda canımdan etse 

Dilim tutulsa, gözüm kör olsa 

Çok çektim elinden, dilinden sevgili 

Yine vazgeçmem 

Hayatta senden vazgeçmem 

Hayatta vazgeçmem senden 

Hain zalim', 'Seni çok, seni çok, seni çok sevdim  Sana ben ömrümü canımı verdim  Hain, zalim  Beni bu sevda canımdan etse  Dilim tutulsa, gözüm kör olsa ...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/vazgecmem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Senin Sevgin', 've-senin-sevgin-kayahan-acar-jabx9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir geçen yazın sonrası 

Sonbahar sancısı 

Nartanem 

İçimde bitmeyen aşkların 

Yarım kalan şarkısı 

Nartanem 

Güneşin ışıkları ısıtmıyor artık 

Geceler hergün daha uzuyor 

Nartanem 

Dışarda sonbahar 

Gönlümde sonbahar 

Göçüyor kuşlar 

Yanar ateşler dağlarda 

Nartanem 

Ve senin sevgin gönlümde 

La la la.. 

Bir geçen yazın sonrası 

Sonbahar sancısı 

Nartanem 

Dışarda sararan yaprakları 

Kovalıyor rüzgârlar 

Nartanem 

Ne zaman ne zaman 

Geleceksin sen 

Ne zaman kavuşmak sana 

Nartanem 

Dışarda sonbahar, gönlümde sonbahar 

Ne zaman ne zaman 

Ne zaman ne zaman 

Yanar ateşler dağlarda 

Nartanem 

Ve senin sevgin gönlümde 

Yanar ateşler 

Ve senin sevgin gönlümde 

La la la..', 'Bir geçen yazın sonrası  Sonbahar sancısı  Nartanem  İçimde bitmeyen aşkların  Yarım kalan şarkısı  Nartanem  Güneşin ışıkları ısıtmıyor art...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/ve-senin-sevgin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sırdaşım Yıldız', 'sirdasim-yildiz-knight-errant-3oelu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kereden bişey olmaz demişlerdi...

Unutursun, lise aşkı çabuk geçer

Bunlar mevsim gibidir, yaşanır biter

Diğer mevsime yaprakları kalır sadece

Onları da süpürürsün olur biter...

Dört mevsim gördü bu aşk kalbimde

Hepsinin yaprakları hala çöplükte

Süpürdüm hepsini, hepsini topladım

Fakat gücüm yetmedi...Onları atamadım...

Nasıl atarım onları? Nasıl atarım seni? 

Tüm yaşadıklarım sanki geçmemiş, hala yeni

Çam edasında benim sevgim, hep yemyeşil

Değişen sadece yapraklar, ama yeniden çıkarlar

Her andığımda içimi ezer kahverengi yapraklar

Bırakamam o anıları, bırakamam seni

Ölüm döşeğinde olsam düşünürüm gözlerini

Hayata bağlar beni o bembeyez tenin

Her saniyem geçiyor hepsi senin için

Bulurlarsa birgün beni ağlarken yalnız

İstediğim bir pabuç, bir yol ve dostum yıldız

Gökyüzünde olsam başka türlü sever miydim 

Yine böyle acı çeker, lanet olsun der miydim

Yalvarır mıydım yıldızlara beni de alın yanınıza diye

Hayır zaten orda olacağım, yukarıda, gökyüzünde

Ama önce toplanmalıyım, kaldırmalıyım başımı

Toplamadan bavulları, yemeliyim aşımı

Giydim pabuçlarımı, ve yoldayım  yalnız

Yoldaşım bir yol, sırdaşım yıldız

Dinler beni saatlerce, dinler şarkılarımı

Gerçi anlamaz beni, derdimi, kaygılarımı

Ama olsun, o benim sırdaşım, dostum

O yok şimdi yanımda ve ben hayata küstüm

Nefret ediyorum kapalı gecelerden

İçinde adının geçtiği hecelerden

Duymak istemiyorum artık tek bir ses

Sadece adımlarım, sadece bir nefes

Yürüyorum saatlerdir, hava kapalı

Çıkamam gökyüzüne, gece yolumu kapadı

Yolun sonu göründü, bir engin deniz

Senle ben, artık olamayız biz

Ve siz dostlarım uzun yol ve yıldız

Yol bitti zaten sen kaldın yalnız

Sırdaşımsın hep, öyle kal ne olur

İşte gerçek dostluk budur, dostluk budur

Sabahleyin gök mavi, deniz zaten hep mavi

Kalbimse paramparça, yalnız aşkların evi

Bir sabah daha ve yeni  gün başlıyor

Maviyi gören gözlerim yine, yine ağlıyor

Bir şarkı, bir renk, bir yol ve yıldız

Sevgi dolu şu gönlüm hala yalnız

Bitti gücüm, koyverdim kendimi

Sevinçlerim üzüntülerimi yendi mi? 

Tabi ki hayır, çünkü mutlu değilim

Aklım durdu, tutmuyor kolum, tutmuyor elim

Ama hala aşığım, bak atıyor kalbim

Ne olursa olsun eksilmez sevgim

Ben hala seviyorum ve atıyor kalbim

Tutmasın elim, kolum, dursada aklım, dursada kalbim

Ben seni yine de seveceğim...', 'Bir kereden bişey olmaz demişlerdi... Unutursun, lise aşkı çabuk geçer Bunlar mevsim gibidir, yaşanır biter Diğer mevsime yaprakları kalır s...', ARRAY['Türk Edebiyatı','Şiir','Knight Errant']::text[], 8.5, '{"poet":"Knight Errant","poet_slug":"knight-errant","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/sirdasim-yildiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-kayahan-acar-o0tir', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni seviyorum, seni seviyorum 

Seni seviyorum diye 

Senden önce kimseye 

Söylemedim dersem 

Yalan, yalan olur 

Hiç hesapsız, çılgınca seni seviyorum 

Bazen bir çocuğun karanlıktan korktuğu gibi 

Seni sevmekten korkuyorum 

Söylememem lâzım, biliyorum 

Susmuyor içim 

Seni seviyorum diyorum 

Canımın istediği 

İçimin titrediği 

Bu ilk defa, öncesi yok', 'Seni seviyorum, seni seviyorum  Seni seviyorum diye  Senden önce kimseye  Söylemedim dersem  Yalan, yalan olur  Hiç hesapsız, çılgınca seni ...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/seni-seviyorum-115-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Muhimsin', 'sen-muhimsin-kayahan-acar-toa3t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sardı yine sevgilerin 

Sardı beni yaz güneşin 

Bütün özlemler benim 

Sen mühimsin ben değil 

Sevgilim 

Ufak tefek yalanların 

Mühim değil, olur canım 

Sen mühimsin, sen benimsin 

Mahvolurum yokluğunda 

Ta içimde yangını yılların 

Sırdaşım ol, gel sarıl be canım 

Sen mühimsin 

Sen benim 

Ufak tefek yalanların 

Mühim değil, olur canım 

Sen mühimsin, sen benimsin 

Mahvolurum yokluğunda 

Ufak tefek 

Mühim değil 

Sen mühimsin, sen benimsin 

Mahvolurum yokluğunda', 'Sardı yine sevgilerin  Sardı beni yaz güneşin  Bütün özlemler benim  Sen mühimsin ben değil  Sevgilim  Ufak tefek yalanların  Mühim değil, o...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-muhimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahlar Uzak', 'sabahlar-uzak-kayahan-acar-36oai', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sabahlar uzak, bu sevda tuzak bana 

Çok zaman geçti, sabrım yok yarınlara 

Kaçıncı hasret, kaçıncı yalnızlığım, sigaramın ucunda 

Şimdi yanımda, yanımda olacaktın 

Bıraktın beni sevda yokuşlarında 

Kuşlar uçurdum, akşamdan sabahlara 

Sigaramın ucunda yanar hasretin 

Vurur canevimden, ellerime kelepçeler vurur 

Gel vefasız, gel vicdansız 

Çağırmazdım acil olmasa 

Gel insafsız, ah kitapsız 

Yanıyorum arzularınla 

Aynalarda gözyaşım var 

Ağladıkça yangın çıkar gözyaşlarımdan 

Gerçekten inanıp sevseydin beni 

Böyle sabahları bekler miydim hiç 

Çoktan yanımda olurdun, çoktan 

Gece üç beş nöbetlerine dikmezdin beni 

Sensiz kaldığım ilk günden beri 

İçimde bir umut vuslata dair 

Akşamları imzaladım gözyaşlarımla 

Seni aramıyor, seni sormuyorsam 

Bu senden vazgeçtim demek değildir 

Bir daha böyle sevecek olsam, bir kalemde silerdim seni 

Gel vefasız, gel vicdansız 

Çağırmazdım acil olmasa 

Gel insafsız, ah kitapsız 

Yanıyorum arzularınla 

Aynalarda gözyaşım var 

Ağladıkça yangın çıkar gözyaşlarımdan 

Aynalarda hatıralar 

Dayanamam, firar eder aklım başımdan', 'Sabahlar uzak, bu sevda tuzak bana  Çok zaman geçti, sabrım yok yarınlara  Kaçıncı hasret, kaçıncı yalnızlığım, sigaramın ucunda  Şimdi yanı...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sabahlar-uzak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden Olmasın', 'neden-olmasin-kayahan-acar-h4140', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Başlarken yeni güne 

Bir umut 

Bir umut içimizde 

Yaşamak 

Yaşamak gönlümüzce 

Bir ömür 

Bir ömür mutlulukla 

Neden olmasın 

Ha bugün ha yarın, oldu olacak 

Neden olmasın 

Çoktan yıkılırdık biz, çoktan 

Umut olmasa 

Ha bugün ha yarın, oldu olacak 

Kaç gün bitti 

Ha bugün ha yarın, oldu olacak 

Neden olmasın 

Neden olmasın 

Ha bugün ha yarın, oldu olacak 

Neden olmasın 

Ha bugün ha yarın, oldu olacak 

Neden olmasın 

Neden olmasın', 'Başlarken yeni güne  Bir umut  Bir umut içimizde  Yaşamak  Yaşamak gönlümüzce  Bir ömür  Bir ömür mutlulukla  Neden olmasın  Ha bugün ha yar...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/neden-olmasin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karasaplantım', 'karasaplantim-kayahan-acar-aqmrz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine yalnızım yine 

Yola çıkmış kervanlar içimde 

Ya kal ya da git 

Böyle kahretme yeter ki 

Karasaplantım 

Meftunum, aklımda yangınlar var 

Üzmesen, yormasan olmaz mı yar 

Yıllar ağlar her gece derdinle 

Çağlayanlar gönlümde, gel dinle 

Yine yalnızım yine 

Ne var beraber olsak seninle', 'Yine yalnızım yine  Yola çıkmış kervanlar içimde  Ya kal ya da git  Böyle kahretme yeter ki  Karasaplantım  Meftunum, aklımda yangınlar var ...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/karasaplantim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çılgınım', 'cilginim-kayahan-acar-spk1d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben deli 

Sen benden deli 

Yakarız gemileri 

Hiç düşünmeden 

Sen deli 

Ben senden deli 

Yaşarız geceleri 

Yıldızlar söner 

An olur canım çeker 

Tutuşur meşaleler 

Farketmez mesafeler 

Ah çılgınım ah 

An olur canım çeker 

Gözüm gözüne değer 

Aklımdan neler geçer 

Ah çılgınım', 'Ben deli  Sen benden deli  Yakarız gemileri  Hiç düşünmeden  Sen deli  Ben senden deli  Yaşarız geceleri  Yıldızlar söner  An olur canım çek...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cilginim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Anadolu Çocuğuyum', 'ben-anadolu-cocuguyum-kayahan-acar-c7pdh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben Anadolu çocuğuyum 

Biraz da deli dolu 

Kızdı mı dünyaya yakarca bakan 

Sevdi mi içinde ormanlar yanan 

Tek tabanca, yalansız çıkmış yıllardan 

Yılandan korkmam yalandan korktuğum kadar 

Benim bu aleme aklım ermiyor 

Ben Anadolu çocuğuyum 

Benimde senin gibi, onun gibi arzularım var 

Tırnakları kısa 

Katıksız kadın, katıksız ana 

Gözleri güleç, yüreği insan birini istiyorum 

Ben Anadolu çocuğuyum 

Bildiğin gibi 

Yüzümde derin siyah çizgiler 

Gözümde diken ve yaban otları 

Yayla rüzgârları geçer içimden 

Dikenli tellere takılır gönlüm 

Kan ağlar 

Anlatamam, ağlayamam 

Ben Anadolu çocuğuyum 

Böyle geldim dünyaya 

Pişman da değilim 

Başakları ellerimle büyütürüm ben 

Başaklar eğilir, ben eğilmem 

Ben Anadolu çocuğuyum 

Yolum sevgiden geçer 

Kimsenin hakkını yemedim ki ben', 'Ben Anadolu çocuğuyum  Biraz da deli dolu  Kızdı mı dünyaya yakarca bakan  Sevdi mi içinde ormanlar yanan  Tek tabanca, yalansız çıkmış yıll...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ben-anadolu-cocuguyum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Gülüm', 'bekle-gulum-kayahan-acar-fjqbr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bekle gülüm, hayat bir gün bize de güler 

Bir gün olur, sona erer bu kötü günler 

Bu dağlar 

Ve denizler 

Engel değil bizim için 

Bekle gülüm 

Hangi dağ daha yüksek bizim yüreğimizden 

Hangi deniz daha büyük bizim özlemimizden 

Kavuşmak tutkusuyla delirince bu gönlüm 

Duvarları deler gözlerim, seni görürüm 

İşte o an dağ bir karış, deniz bir adım gülüm 

O an 

Saçlarını dağıtan 

Rüzgâr değil 

Nefesimdir gülüm 

Hangi dağ daha yüksek bizim yüreğimizden 

Hangi deniz daha büyük bizim özlemimizden 

Özleminin yüreğini boğduğu bir gün 

Haykırmak gelirse içinden, haykır gülüm 

Dövsün sesin denizleri, dağlar dövsün 

Bu dağlar 

Ve denizler 

Engel değil 

Duyarım seni 

Haykır gülüm 

Hangi dağ daha yüksek bizim yüreğimizden 

Hangi deniz daha büyük bizim özlemimizden', 'Bekle gülüm, hayat bir gün bize de güler  Bir gün olur, sona erer bu kötü günler  Bu dağlar  Ve denizler  Engel değil bizim için  Bekle gülü...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bekle-gulum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küpesiz Deli', 'kupesiz-deli-suat-oktay-xx27t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eh vatik de çok geç oldu

Gitmeli artık

Kalmamalı buralarda

Ermeli uzaklara

Birileri gerçeği bilmeli

Huzur, ah huzur

kadı kızında bile bulunur

bir nebze kusur

Bakın bakın 

kaçıyor...

Hayır gidiyor

Hem kaçıyor, hem gidiyor...

Kulakları küpesiz deli, 

gidişinden belli! 

29/7/98', 'Eh vatik de çok geç oldu Gitmeli artık Kalmamalı buralarda Ermeli uzaklara Birileri gerçeği bilmeli Huzur, ah huzur kadı kızında bile bulunu...', ARRAY['Türk Edebiyatı','Şiir','Suat Oktay']::text[], 8.5, '{"poet":"Suat Oktay","poet_slug":"suat-oktay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/kupesiz-deli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yas', 'yas-tulay-esat-fzzlq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözlerin vardi büyülü gözlerin, 

Icim icim yudumlardin baktigin gözleri.

Her esisin taptazeydi, 

Her gülüsün yaz günesi..

Sinirsiz alevlerin sukün ettigi gecenin, 

Sabahiydi gittigin gün.

Gidis degil, bir kacisti

Kibarimsi ve nazik.

Yarim yaldizlar gülüsürken asirlik güneste, 

Bir mevta götürdüler cemberlenmis alayda..

Agit yakti, kara giydi sevdigin, 

Daglar kar tutmadi kac ay da, 

Caglayanlar bulanik akti.

BILDIR bu zamandi...daha dün gibi, 

Kimi gördü, kimi duydu da inanamadi.

Safak kör etti gözlerini, 

Öyle erdi sabaha.

Sagnak sagnak gözyaslari, 

Bosa süzüldü kara topraga.

Zaman yemine uymadi, bilakis

Günü gelince ihanet etti.

Durmadi denildigi gibi, 

Senin matemin de bitti.

BILDIR bu zamandi sevdigin, 

Karsi köye gelin gitti.', 'Gözlerin vardi büyülü gözlerin,  Icim icim yudumlardin baktigin gözleri. Her esisin taptazeydi,  Her gülüsün yaz günesi.. Sinirsiz alevlerin...', ARRAY['Türk Edebiyatı','Şiir','Tülay Esat']::text[], 8.5, '{"poet":"Tülay Esat","poet_slug":"tulay-esat","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yas-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkıma Hitaben', 'askima-hitaben-i-brahim-cagri-saglik-l102c', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Geceler boyu, dualadım onu

Gözyaşlarımla yıkadım yolunu

Bakışlarında, gönlümün odunu

Buldum da oldum, aşkına divane

Gülüşün ömrüm, hüznün idamımdır

Sensin tek aşkım, gerisi batıldır

Beklemekteydim, seni ne zamandır

Koştum da geldim, aşkına pervane

Dilimden adın düşmüyor inan ki

Allah''ım kılsın, bu sevgiyi baki

Sevebilmek o, ne büyük dava ki

Sevdim de verdim, kalbim sana hane

Ruhumun eşi, başımın tacısın

Sıcaklığınla, yuvamın harcısın

Gönül telime vuran mızrabımsın

Yeter ki sen çal, musiki bahane

Çağrı söyler de, duyar mı ki canan

Olabilir mi, böyle aşka kanan

Bir olsun yastık, ömür denen zaman

Gül Gonca''msın ya, ötesi şahane

31-01-2003', 'Geceler boyu, dualadım onu Gözyaşlarımla yıkadım yolunu Bakışlarında, gönlümün odunu Buldum da oldum, aşkına divane Gülüşün ömrüm, hüznün id...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Çağrı Sağlık']::text[], 8.5, '{"poet":"İbrahim Çağrı Sağlık","poet_slug":"i-brahim-cagri-saglik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/askima-hitaben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşanmayan Ne Varsa Fitilidir Umudun', 'yasanmayan-ne-varsa-fitilidir-umudun-melih-coskun-mukbm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'I.

Bir bilinmezi daha tükendi hayatın

Adımlar sıklaştı gözükünce diğer bilinmezlerin sınır kapısı

Bekliyor bizi yıllar elinde bir kamçılarıyla 

Yaşanan bir bilinmezde olsa 

Değmez mi yaşamaya

Bilinmeyen ne varsa fitilidir umudun

Ve ateş senin elindedir her zaman

II.

Bir fotoğraf duruyor önümde 

Çadır, toprak, çamur

Ve çocuk ve gözyaşı, 

Ve çakal gibi bir soğuk

Haince içeri sızan yağmur damlaları

Ve gitgide azalan bir dünya

Çocuğun ayaklarında 

Buza kesmiş bir yeryüzü

Gözlerinde hala kirletilmemiş dünya

Umut en çok çocuklara yakışıyor

Çocuklar; 

Zaman tüketemez onların beyinlerinde

Güzelliğe olan inancı

Onların gözlerinde inanç yeryüzü kadar 

O çocuklardır 

Savaştan dönmeyecek bir babayı

Yıllar boyu umutla bekleyen

Gece yarıları gökyüzünde güneşi arayan 

Onların rüyalarında gördükleri bugün

Elma şekeri, bebek, oyuncak araba değil

Bütün hayalleri

Kapısında oynayacağı bir ev, 

Enkaz altında kalmamış bir gelecek sadece

Onların yanaklarındaki gamzelerde çukurlaşan hayat

Çok şeyler anlatıyor bize 

Anladıkça zamanın acımasızlığını

Utanıyoruz içtiğimiz çorbadan

Soluduğumuz nefesten

Bakamıyoruz gözlerinin içine

Daralıyor dünya 

Daralıyor beynimiz

III.

Ve biz bu daralmış beyinlerimizle

Anlamakta zorlanıyoruz 

Mutluluk ile mutsuzluk arasındaki

Sevgi ve nefret arasındaki

Dostluk ile düşmanlık arasındaki 

Umut ile ölüm arasındaki çizginin inceliğini

Ha desen koptu kopacak bütün sınırlar

O anda karışacak her şey birbirine sanki bir anda

Dostun düşman olacak 

Sevgin nefret 

Ve umudun antitezi ölüm kaplayacak ortalığı...

01 Ocak 2003

01: 03', 'I. Bir bilinmezi daha tükendi hayatın Adımlar sıklaştı gözükünce diğer bilinmezlerin sınır kapısı Bekliyor bizi yıllar elinde bir kamçılarıy...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/yasanmayan-ne-varsa-fitilidir-umudun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatı Dökülen Yüzünde Unuttum..Buysa Ömrüm.', 'hayati-dokulen-yuzunde-unuttum-buysa-omrum-rabia-can-ulas-y9woz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hayatı dökülen yüzünde unuttum...buysa ömrüm, 

kırılan aynalarda utanmış gümüşün sırrında, 

bir tesbih sesinde james dean filminde, 

seni beklediğim heryerde yatılı hüzünlerde unuttum, 

oysa ben defalarca bana hayat diye sunulan şeyi tükürdüm

hemde içime, kimseye sıçramasın diye, 

içimi kirlettim her solukta, 

sen vardın ya hayatın saf özü, 

sana dokununca durlanacaktım, 

ve sen biliyordun ya biz hayatı temizlemeye çalışıyorduk

kendimize kusarak tüm zehrini....

ve gözlerimiz vardı, birbirine değdiğinde kıvılcımlar çıkaran, 

ne zaman ömrümüz yutsa zehri, 

bakışlarında sığındığımız sağaldığımız gözler..

onlar hiç bir sırra meczup değildi, 

bakar ve geçerdi namlunun çeliğini bile, 

yalansa nasıl aşardık pusuları kara namlulardan..

şimdi neyi unuttuk ki birbirimizde çözülmeyen denklemiz..

neyin iziki çok ayrı yaşamlarda her değdiğinde kanatan..

yağmurda bulut karda soğuk kılan bizi.

yoksa ben hayatla dolu bir namlu, 

sen sıkıp tükeneceğini hiç düşünmediğim mermimiydin..

gülümseyişlerden sekip kendi böğrüme unuttuğum, 

içsel bir kanama ömrümün her kıpırtısında yaralı, 

ve ağrıtan saklı bir vurulmak..

gizli bir intiharmıydın..

kronik bir ölüm ama akutta alacağını bırakmamış..

dedimya buysa ömrüm hayatı dökülen yüzünde unuttum, 

o en son gördüğüm resminde..

ben defalarca kusmuşken bana hayat diye sunulanı içime, 

kimseyi kirletmemek için..

sen hepsini yüzüne giymişte gelmiştin..

ben ondan hayatı dökülen yüzünde unuttum..

seni çok sevdiğimi haykıramadan..', 'hayatı dökülen yüzünde unuttum...buysa ömrüm,  kırılan aynalarda utanmış gümüşün sırrında,  bir tesbih sesinde james dean filminde,  seni be...', ARRAY['Türk Edebiyatı','Şiir','Rabia Can Ulaş']::text[], 8.5, '{"poet":"Rabia Can Ulaş","poet_slug":"rabia-can-ulas","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/hayati-dokulen-yuzunde-unuttum-buysa-omrum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düslerin İçinden', 'duslerin-i-cinden-tulay-esat-bg9q0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seslerin akisini duyuyor musun? 

Puslanan baksimi? ? 

Yaslanan bir resim gibi duvarima, 

Boyun bükmüs bir gelincik yollarima.

Ayri yollardan, 

Ayrilan yollara..

Henüz kesfedilmemis bicimsiz bir mehtap, 

Sinirsiz düslerin sahilinde.

Esasinda haykirmakta, 

Her sevda kendi dilinde.

Kirginligim sakinlesir, 

Ilham düsen kalemimde.

Ezberimde o hülyalarin ilk adimlari, 

Kulagimda uguldasir yanik bir agit, 

Sanki sen hic yasamadan, 

Yasayamadan ölmüssün.

HAYIR! 

ÖLME! 

Gülücükler cinlasin yine düslerinde! 

BIRAK, 

GITME! ..

Unut kanadinin kirikligini...

Sen tutmadin mi ellerimi, 

Ben göcecekken hani? 

Uzak illerin uzaktadir güzellikleri...

Ben kirik bir dalin misafir kusu, 

Sen yorgan almis üstüne.. düsün! 

Sen biraz da göge cevir gözlerini, 

Bir tanri var unutma ki, 

O mukadderdir! !', 'Seslerin akisini duyuyor musun?  Puslanan baksimi? ?  Yaslanan bir resim gibi duvarima,  Boyun bükmüs bir gelincik yollarima. Ayri yollardan...', ARRAY['Türk Edebiyatı','Şiir','Tülay Esat']::text[], 8.5, '{"poet":"Tülay Esat","poet_slug":"tulay-esat","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/duslerin-icinden-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '1 Yıl 1 Şiir', '1-yil-1-siir-mustafa-yavuzyilmaz-wbvnq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tekrar yaratabilmek için kendini

Hiç bilmediğin, hiç gitmediğin bir zamana naklettin kalbini

Tek bir hece dökülmeden ardına...

Tek bir ses; tek bir çığlık...

Sessiz ağıt...nefessiz gece...dilsiz ve dipsiz kuyu...sustun! 

Susmak en büyük savunmadır belki

Konuştuğun bütün kelimelerden bıkıp; anlaşılmaz

Yürüdüğün bütün yollardan bıkıp; geri dönülmez

Girdiğin bütün hayatlardan çıkıp; aslında hepsi senin...

Susmak en çok ağlamaya yakındır gibi

Gelse de aslında çare değildir dediğin

Her hatıradan kaçarak...

Kaçmak en masum isyandır belki

Kurtuluştur; attığın her adımın sonu yine sende bitecekse...

Bitecekse sürüklenmelerinden yorulup her kaldırım taşının altında aramak

Yaşatmaya çalıştığın her umudun ezikliği; ağırlığı altında

Yürümek; sokakların diline bir tek kendin anladığını düşünerek

Günleri unutarak...

Günleri acıtarak...

Yok saydığın bütün iç çekişlerinden çekinip; utangaç

Ayakların yine yere basmadan

Süzülüp çıktığın bütün kapılar, kim bilir ardına kadar açık kalmıştır; soğuk...

Uzun kış, taze bahar...

Bir şeylerin doğumu aynı zamanda bir şeylerin ölümüyse

Tekrar yaratabilmek için kendini; öldür beni!', 'Tekrar yaratabilmek için kendini Hiç bilmediğin, hiç gitmediğin bir zamana naklettin kalbini Tek bir hece dökülmeden ardına... Tek bir ses; ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yavuzyılmaz']::text[], 8.5, '{"poet":"Mustafa Yavuzyılmaz","poet_slug":"mustafa-yavuzyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/1-yil-1-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Bırakma', 'beni-birakma-sair-khan-axen1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İlk defa göz göze geldiğimiz ani hatırlıyor musun? 

Kaçamak bir buluşmasıydı bu gözlerimizin.

Seni istiyordum, biliyordun....

Bakışların duygulu, anlayışlıydı, özlemliydi zaman zaman.

İçimde yaktığın ateşi söndürmek istiyordum.

Ama o ateş gitgide büyüdü işte! Şimdi biraz da sen yan artık

Benim yanacak yerim kalmadı ki.İnanamıyorum, sen var mısın gerçekten? 

İnanamıyorum bir türlü. Tuttuğum ellerin mi? Öptüğüm dudakların mı? 

Kim bilir? Belki de yoksun, ben bir rüya görüyorum, biraz sonra uyanacağım.

Her şey ansızın silinecek. Ne saçların kalacak ortalıkta, ne de o gözlerin.

Yine kahredici yalnızlığıma döneceğim. Biraz daha yıkılmış, biraz daha sensiz.

O gün ilk defa seni gördüm. Düşün sen dünyaya geleli beri kaç yıl geçmiş aradan.

Düşün ne kadar özlemiştim seni? Öyleyse hiç gitme ne olur? 

Vereceğin her kedere razıyım. Acıların en büyüğünü sen tattır bana, 

Ama gitme ne olur? Dudaklarım kurumuştu, içim yanıyordu.

Suya hasret, kurumuş bir ot gibiydim. Yağmur olup yağdın üstüme, yeşerdim; Filizlendim.

Sonra güneş oldun, hayat verdin bana, koku verdin, renk verdin.

Şimdi bırakıp gidersen bir daha ama inan son defa yine kuruyacağım, 

Dağılıp toz olacağım anlıyor musun? Çünkü senden sonra kimse gelmeyecek, biliyorum.

Kimseler çalamayacak kapımı.Gidersen beni bana mahkum edeceksin, 

Keşke ölsem diyeceğim o zaman keşke ölsem! Ve inan öleceğim kesin öleceğim.

Simdi sendeyim, seninleyim, seni yaşıyorum. Beni bana bırakma! Senden bir parçayım artık, 

Belki de baştan başa sen oldum farkında değilsin.Beni bana bırakma! 

Sen olduğun için  sadece seninle olduğum için mutluyum.

İstersen sen beni sevme.Hiç ama hiç sevme. Ama bırakma beni ne olur? 

Beni benle bana bırakma! ! ! ! !', 'İlk defa göz göze geldiğimiz ani hatırlıyor musun?  Kaçamak bir buluşmasıydı bu gözlerimizin. Seni istiyordum, biliyordun.... Bakışların duy...', ARRAY['Türk Edebiyatı','Şiir','Şair Khan']::text[], 8.5, '{"poet":"Şair Khan","poet_slug":"sair-khan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/beni-birakma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Sesleniş', 'son-seslenis-sair-khan-l99rv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu son seslenişim sana, Kaç gündür yokluğunla baş başa gözlerim

 Kaç saattir ellerim hayaline dokunmakta, Gecelerim belki yarına diyen dualarla

 Binlerce yıldızlar kaysa, Ben hep seni dilesem 

 Ve sen güneşle doğsan odama Gamzeni sunsa deniz avucuma

 Gece gözlüm bu son haykırışım sana. Ben bıraktığın yerdeyim

 Saçlarımda kokusu var nefesinin Yanağımda dokunuşunun sıcaklığı

 Vücudumda dolaşmakta karanlıklar, Ben teninde sevdalı

 Sesim çıkmıyor artık, Kelimeler yetmiyor, Gözlerim kavuşmuyor kirpiklerine

 Ben düşemiyorum gözlerine, Rüzgar dağıtıyor sesimi, Hasretim uzağından geçmekte

 Ben deli divane esmer tenine, Marmara seni vuruyor sahillere

 Sarmaş dolaş yürümeliyiz Yağmur o günü yaşatmalı  Çisildemeli üstümüze

 Bir tanem...canım...bebeğim 

 Tenin düşmeli tenime.', 'Bu son seslenişim sana, Kaç gündür yokluğunla baş başa gözlerim  Kaç saattir ellerim hayaline dokunmakta, Gecelerim belki yarına diyen duala...', ARRAY['Türk Edebiyatı','Şiir','Şair Khan']::text[], 8.5, '{"poet":"Şair Khan","poet_slug":"sair-khan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/son-seslenis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben, de Unutmadım', 'ben-de-unutmadim-sair-khan-nasdk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyordum gideceğini.. 

Gelişinde kesif bir gidiş kokusu vardı.. 

Kapı açıldı, sen girdin.. 

Adımların gitmeye yeminli, 

Ne kadar yaklaşsan, o kadar sokuluyordu gidişin.. 

Gidişini de sineye çekerdim gözlerini görmeseydim.. 

Ama olmadı.. 

İlk narin bakışın perçinledi gözlerini yüreğime. 

Bir çift buğulu göze tutulmuştum, eriyordum.. 

Nafile, gitmek için gelmiştin belliydi.. 

Yüreğim gözlerine kenetli.. 

Topladın bütün bakışlarını kalkarken, 

Gözlerin bende kalsın diyemedim, 

Gittin.. 

Karalar bağladım gözlerinin karasına.. 

Gözlerinde çok ağladı kalbim, 

Göz yaşların gönlümün yaralı figanıydı, bilmedin.. 

Çok kanadı içim, 

Resmini bastım her seferinde, 

En çok gözlerindeki tebessümü aradım, 

Gözlerinden güzel güleni görmedim... 

Unutmadım.... 

Gözlerinde çok ağladı kalbim 

Ben, de unutmadım..........', 'Biliyordum gideceğini..  Gelişinde kesif bir gidiş kokusu vardı..  Kapı açıldı, sen girdin..  Adımların gitmeye yeminli,  Ne kadar yaklaşsan...', ARRAY['Türk Edebiyatı','Şiir','Şair Khan']::text[], 8.5, '{"poet":"Şair Khan","poet_slug":"sair-khan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ben-de-unutmadim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olduğun İçin', 'sen-oldugun-i-cin-sair-khan-3hljf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güzelliğin için değil, çünkü ben seni hiç görmedim... 

Ellerimi tutmanı değil, çünkü ben sana hiç dokunmadım... 

Gözlerine bakmayı değil, çünkü ben onlara hiç dalmadım... 

Ben senin beni sevmeni sevdim... 

Yüreğinde bana yer vermeni sevdim 

Benimle konuşurken, sesini nefesini sevdim 

Ağladığımda uzaktan tesellilerini sevdim 

Benim seni sevmemi sevdim... 

Sessizlikte kalp atışlarını sevdim 

Damarlarımda kan yerine dolaşmanı sevdim 

Düşlerde benim olmanı, senin olmamı sevdim... 

Gönülden sana bağlandığımı sevdim 

Gündüz ışığım, Gece karanlığım olmanı sevdim 

Alınyazım, Kaderim, Her şeyim olmanı sevdim 

Gözyaşım, Kederim, Hüznüm olmanı sevdim 

Tebessümlerimin, Gülmelerimin, Mutluluğumun sebebi olmanı sevdim 

Söylediğin sözleri değil, 

Onları bana söylemeni sevdim... 

Ben başlı başına seni SEN olduğun için sevdim... 

Benliğini, Duygularını, Hislerini sevdim 

Ve... 

Bu tarifsizliği, sevgime kelime bulamadığımı sevdim... 

SENİ SEVDİM...', 'Güzelliğin için değil, çünkü ben seni hiç görmedim...  Ellerimi tutmanı değil, çünkü ben sana hiç dokunmadım...  Gözlerine bakmayı değil, çü...', ARRAY['Türk Edebiyatı','Şiir','Şair Khan']::text[], 8.5, '{"poet":"Şair Khan","poet_slug":"sair-khan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sen-oldugun-icin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönya', 'donya-i-hsan-uncuoglu-3956d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünyada öylemi yaşarken İnsan

Ben iyi yaşayayım sen kötü

Hayalin böylemi geçerken İnsan

Ben Peri olsaydım sende öcü 

Hayatın bumu yaşarken İnsan

Kimi iyi yaşardı kimi kötü

Neyki o bir canlı 

Nasıl ne olurdu 

İnsan çoğalırdı 

Bir canlı bir ölü! ,', 'Dünyada öylemi yaşarken İnsan Ben iyi yaşayayım sen kötü Hayalin böylemi geçerken İnsan Ben Peri olsaydım sende öcü  Hayatın bumu yaşarken İ...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/donya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Pınarım', 'ask-pinarim-cafer-tayyar-ozkan-1kk52', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni dizelerimin hecesi olasın diye değil, 

Başıma taç, gönlüme ilaç diye sevdim.

Seni düşlerimin gülü olasın diye değil, 

Ömrümün son baharı, aşkı diye sevdim.

Seni sözlerimin manisi olasın diye değil, 

Gülistanımın eşsiz gülü diye sevdim.

Seni hislerimin perisi olasın diye değil, 

Gönlümün güzel prensesi diye sevdim.

Seni ellerin aşk çiçeği olasın diye değil, 

Günlerimin vefalı can dostu diye sevdim.

Seni bir damla suyum olasın diye değil, 

Vefalı akan aşk pınarım diye sevdim.', 'Seni dizelerimin hecesi olasın diye değil,  Başıma taç, gönlüme ilaç diye sevdim. Seni düşlerimin gülü olasın diye değil,  Ömrümün son bahar...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-pinarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayçiçeğim', 'aycicegim-cafer-tayyar-ozkan-wwtya', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüzünü gülün renginden, 

Kalbini gönlün sevgisinden, 

Gözünü bakışın şavkından, 

Tenini vuslatın zevkinden, 

Düşünü ufuğun fevkinden, 

Sözünü bildiğin mertinden, 

Geceni unutulmaz şarkından, 

Beni de ölümsüz aşkından, 

Mahrum etme, 

Ayçiçeğim.', 'Yüzünü gülün renginden,  Kalbini gönlün sevgisinden,  Gözünü bakışın şavkından,  Tenini vuslatın zevkinden,  Düşünü ufuğun fevkinden,  Sözün...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aycicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ömür Bitecek', 'bir-omur-bitecek-cafer-tayyar-ozkan-m8bvr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bembeyaz bir buluttum

Aşkının ateşinden soldum

Sen yaklaştıkça yanıma

Kar tanesi oldum savruldum

Sevmek güzel derdim

Sevginle murada erdim

Ellerini uzatsaydın bana

Asla geri çevirmezdim

Sensiz anlamsızdı dizelerim

Endamınla güzelleşti hecelerim

Sıyrıl tabularından gel artık

Yüreğimi sana vereyim

Ekmeğim yavandı sensiz

Olmayacak, biliyorum bensiz

Sevmek, sevilmekten güzeldir 

Bir ömür bitecek sevgisiz', 'Bembeyaz bir buluttum Aşkının ateşinden soldum Sen yaklaştıkça yanıma Kar tanesi oldum savruldum Sevmek güzel derdim Sevginle murada erdim E...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-omur-bitecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çobanlıktır', 'cobanliktir-cafer-tayyar-ozkan-67cty', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevda kedersiz misali çobanlıktır

Yüreği yürek yapan sevgi, 

Sevgiyi de sevgi yapan dalaktır

Kör olası gözler göremezse ilgi, 

İşte o zaman bunun adı ahmaklıktır', 'Sevda kedersiz misali çobanlıktır Yüreği yürek yapan sevgi,  Sevgiyi de sevgi yapan dalaktır Kör olası gözler göremezse ilgi,  İşte o zaman ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/cobanliktir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elbette', 'elbette-cafer-tayyar-ozkan-l3oe2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çıkmaz sokaktayım, 

Sıralanmış kaldırım taşlarını sayıyorum

Yağmur çiseliyor, kulağım çınlıyor ama yürüyorum

Akşama hüzün çöküyor, boynum bükük

Vakit çok geç değil, bize gel diyor özgürlük

Hakkım olan mutluluğu ben de istedim 

Beklemekle geçecek sensiz günlerim

Hadi gel de, artık dağılsın kalbindeki sisler

Uzaklarda da olsa avunur, büyüyen ümitler

Sanma sakın, seni sevmekte ayak diretiyorum

Elbette içim yanıyor, ben de seviyorum, seviyorum', 'Bir çıkmaz sokaktayım,  Sıralanmış kaldırım taşlarını sayıyorum Yağmur çiseliyor, kulağım çınlıyor ama yürüyorum Akşama hüzün çöküyor, boynu...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/elbette-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlenir misin?', 'evlenir-misin-cafer-tayyar-ozkan-hyw4q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerine baktığımda, 

Kendimi gördüm.

Sesini duyduğumda, 

Aşkını içtim.

Saçlarını okşadığımda, 

Sevdamı hissettim.

Ellerini tuttuğumda, 

Sıcaklığını tattım.

Yüreğini aldığımda, 

Canım benimle evlenir misin? 

Dedim.', 'Gözlerine baktığımda,  Kendimi gördüm. Sesini duyduğumda,  Aşkını içtim. Saçlarını okşadığımda,  Sevdamı hissettim. Ellerini tuttuğumda,  Sı...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/evlenir-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlilik', 'evlilik-cafer-tayyar-ozkan-4lfwz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilir misin sihirli bir dünyadır evlilik

Evliliktir iki insanı bir yapan hakikat

İki şey üzerine kurulmazsa evlilik bağı

Elbet biter bir gün edilmezse dikkat 

Birincisi ve en önemlisi saygıdır saygı

Yok olmuşsa evlilikte etsin o zaman eşler kaygı

Saygı bir çınar ağacın gövdesi gibidir

Kurursa güzellikler tamamen biter

İkinci ise sevgidir bazen çocuk bazen de bir çiçek 

Sevgi bir söğüdün yaprakları gibi, büyür sevince

Her bahar filizlenir güneşin sıcaklığını görünce

Tıpkı sevgililerin yüreklerinde oluşan sıcaklık gibi

Her bahar sevgi oluşur yenilenir kalpler

Ama saygısız asla güzel kokmaz çiçekler

Her ikisini de yüreğinde barındıran sevgililer

Bu dünyada bir çınar ağacı gibidirler...', 'Bilir misin sihirli bir dünyadır evlilik Evliliktir iki insanı bir yapan hakikat İki şey üzerine kurulmazsa evlilik bağı Elbet biter bir gün...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/evlilik-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül', 'eylul-cafer-tayyar-ozkan-q6ug5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben artık sonbaharı çok seviyorum.. 

Seviyorum ve sevenlerimle paylaşmak istiyorum..

Eylül güzel bir yazdan son kalan anlardır..

Bazıları için sıradan bir gün, 

Bazıları içinse hayatın bir dönüm noktası..

Bazıları için hayatı boyunca taşıyacağı bir isim..

Bazıları için mutlulukların yıldönümü..

Ama bazıları içinse mutlu, sımsıcak bir sarılış..

Sen hiç duygularının seni sardığı bir gün yaşadın mı? 

Sen hiç anlatmak isteyip de anlatamadığın güzelliklere sahip oldun mu? 

Sen hiç elindeki kartopunun erimesine engel olabildin mi? 

Sen hiç zamanı durdurmak istedin mi? 

Peki sen hiç sevgi bağlarının ağladığına şahit oldun mu? 

Evet sonbahar yaprakları gibi dökülen arzuların bittiğini bilir misin? 

Karmaşık duygulardır insana yön veren, 

Bazen üzüntülere boğan, bazen de yeşerten..

Sevgiler susadıkça kalplerde arar durur mütemadiyen..

Soran olmaz ki sevmeyi bilenlerden..

Kalp sızısı başka şeye benzemez, 

Sorma sevmeyi bilmeyenlerden.

Sen hiç eylül yapraklarının sararırken ki feryatlarını bilirmisin..

Denizde dalgalar vurur sürekli kayalara, bir sevgi tokadı gibi..

Sevda bulutları sürekli sevgi damlacıkları bırakır sevdiklerine..

Bazen kara sevdalı olur gümbürder durmadan kötülerin üzerine seller gibi..

Artık mevsim sonbahardır, sevgisiz kalplere karanlıktır kış mevsimi..

Gerçek dostlar bulunur mu diyerek avutur kalbini..

Öyle bahtsızlar vardır ki..

Bir sazın telinde, 

Bir yağmurun damlasında, 

Bir gülün renginde, 

Bir bülbülün nağmelerinde, 

Bir şiirin dizelerinde, 

Bir günün batışında, 

Bir gülümsemenin sonunda gerçek dostluğu ararlar sevdalar..

Bilir misiniz nadide elmaslar gibi, 

Yanı başınızdadır da farkına bile varmazlar..

Artık gelsin bahar diye feryat edenler..

Kalplerindeki baharın tadına varmayanlar..

Etrafında dost olduğunu sananlar..

Gönlündeki sevdayı içinde sızı diye taşıyanlar..

Ne kadar hüzünlü bir yaşamdır bu Allahım..

Kalbi olup da sevenlere sevmeye hakkın yoktur diyenler..

İşte asıl Eylülü bilmeyenler..

Kalbinde açan çiçeklerin farkında olmayanlar..

Onlardır işte..

Eylülsüzler..

Sevgisizler..

Bahtsızlar..', 'Ben artık sonbaharı çok seviyorum..  Seviyorum ve sevenlerimle paylaşmak istiyorum.. Eylül güzel bir yazdan son kalan anlardır.. Bazıları iç...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/eylul-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geç Olmadan', 'gec-olmadan-cafer-tayyar-ozkan-83pe4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen hiç bir kimseyi ölürcesine sevdin mi? 

Yüreğinin deniz gibi kabardığını

Duyguları anlatmak için dizelerin bile

Yetmediğini anlayacaksın aman geç olmadan

Derdini söylemez atarsın içine

Kahrolur yanarsın daima kendine

Sen sen ol sakın atma sakın

Dert etme boş ver dünyayı 

Olmasın hiç hüznün gamın..

Yüreğinin sesini daima dinle

Eğer söz dahi geçiremiyorsan

Paylaş konuş benimle.

Dostlar her zaman böyle zamanlarda

Olurlar her derde deva..', 'Sen hiç bir kimseyi ölürcesine sevdin mi?  Yüreğinin deniz gibi kabardığını Duyguları anlatmak için dizelerin bile Yetmediğini anlayacaksın ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gec-olmadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlümün Sultanı', 'gonlumun-sultani-cafer-tayyar-ozkan-mbf27', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğime kor ateş gibi düştün tatlı cadım 

Beni can evimden vurdun turna gibi yaralıyım 

Senden istediğim aslında bir çift gözdü ama 

Sen bana dünyaları verdin, tatlı sevgine duacıyım...', 'Yüreğime kor ateş gibi düştün tatlı cadım  Beni can evimden vurdun turna gibi yaralıyım  Senden istediğim aslında bir çift gözdü ama  Sen ba...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gonlumun-sultani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Pencerem', 'gonul-pencerem-cafer-tayyar-ozkan-0901h', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mevsimlerden yine bir bahar sabahı

Acılarımı, sevinçlerimi yaşadığım, 

Düşlerimi gördüğüm, hislerimi açtığım, 

Aşklarımı, sevdalarımı yazdığım yer burası.

Burası benim duygu dünyamın durağı.

Kah bir perde gibi inen yağmurları, 

Kah lapa lapa yağan karları, 

Yemyeşil ormanın kırlarla buluştuğu, 

Çamların göklere abanıp uzandığı, 

Rengini göklerden alan masmavi göl manzarası, 

Güneşin yakıcı ateşinden kavrulan dağlar, 

Burası benim duygularımın dünyaya açıldığı, 

Göz yaşlarımla mum çiçeğimi suladığım, 

Üzerinde buğusuyla sıcak çayımı yudumladığım, 

Tekel sigaramdan derin derin çektiğim, 

Yüreğimden coşkuyla akıp duran dizelerimi, 

Gönlümden bir çisenti olup dökülen, 

Beni benden alıp çok uzaklara götüren, 

Duygularımı beyaz sayfalara yazdığım, 

Ne taraftan bakarsam gerçekleri gördüğüm, 

Hayatın acı, tatlı yüzüyle buluştuğum, 

Gönül pencerem.

Kaç mevsim yaşadım anılarla ücra köşende; 

Bazen yüreği çırpınan bir serçeyle dertleştim

Bazen de bahardan bahara yuvasına gelen, 

Yavruları için çırpınan sığırcık kuşlarıyla.

Konuştum saatlerce, seni andım onlarla

Sana haber saldım, hislerime tercüman oldular, 

Dile gelmeyen hasretimi paylaştım, ağlaştım, 

Bahardan yaza, hep birlikteyim onlarla, 

Kim bilir kaç bahar daha dertleşeceğiz, 

Yuvaya girmek için verdiği uğraşlarla, 

Kaç mevsim bilinmez, içimdeki feryatlarla, 

Sanki bu pencere, benim yüreğimden bir parça

Keşke gönüller hep sizin gibi tertemiz olsalar, 

Yaşanılan acımasız, hercai hayatta, 

Bir gün gelecek özlediğim baharda, 

Getireceksiniz, bekliyorum, belki sisli bir sabahta, 

Yaralı yüreğimin özlediği gerçek sevdayı, 

Belki de ömrün son baharında, 

Sana düşlerimi gönderiyorum sığırcık kuşlarıyla, 

Bir gün görürsen benim dert arkadaşlarım, o kuşları, 

“Seni seviyorum” sözümü duyacaksın fısıltılarıyla

Pencerenden kalbime aksedecek sevda haykırışlarını, 

Gönül penceremden duyarım, sığırcık kuşlarıyla', 'Mevsimlerden yine bir bahar sabahı Acılarımı, sevinçlerimi yaşadığım,  Düşlerimi gördüğüm, hislerimi açtığım,  Aşklarımı, sevdalarımı yazdığ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/gonul-pencerem-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim Seni İstiyor', 'gozlerim-seni-i-stiyor-cafer-tayyar-ozkan-jxf2v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyor musun? 

Neyi mi? 

Her şeyinle güzelsin. 

Yüreğin kar kadar saf ve temiz 

Gönlün güneş gibi parlak, 

Can evin öyle bir misafirperver, 

Duyguların en mavi denizler gibi ferah, 

Hislerin hislerime tercüman, 

Dizelerin tebessüm veriyor adeta, 

Sen, sen diyor gözlerim, seni istiyor..

Biliyorum daha fazlasını veremezsin, 

Ama sen benim için çok özelsin...', 'Biliyor musun?  Neyi mi?  Her şeyinle güzelsin.  Yüreğin kar kadar saf ve temiz  Gönlün güneş gibi parlak,  Can evin öyle bir misafirperver,...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gozlerim-seni-istiyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hülya İle Emre', 'hulya-i-le-emre-cafer-tayyar-ozkan-38hql', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hicran yarası doğmasın, yüreklerimizde, 

Üzgün bakışlar olmasın, gözlerimizde, 

Lazımdır bu yüreğe sevgi, kalplerimizde, 

Yalnız sevda şarkıları söylensin, dillerimizde, 

Aşkımız sonsuza kadar yaşasın, bedenimizde.

İhanetlerdir, hep kapanmaz yaralar açan, 

Lakin sevdadır, kalbe derman saçan, 

Eremez asla mutluluğa, sevgiden kaçan.

Emirdir sözlerin, toprak olacak bedenime, 

Mazidedir sitemlerin, aşk dolacak yüreğime, 

Razıyım, sensizliği yok edecek şerbetime, 

Elinden tutup beyazlarla, seninle içmeye..', 'Hicran yarası doğmasın, yüreklerimizde,  Üzgün bakışlar olmasın, gözlerimizde,  Lazımdır bu yüreğe sevgi, kalplerimizde,  Yalnız sevda şarkı...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hulya-ile-emre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kusursuz Yargıcımsın', 'kusursuz-yargicimsin-cafer-tayyar-ozkan-r4kmj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benzersiz kalbinle sevgi ve saygıda kusursuz yargıcımsın

Kanına kan kattığın kuzucuklarına hep merhametlisin

İyi ki sen varsın, bilirim ince hislerin öğretmenisin

Nafile üzülürsün, bahar mevsimini emanetinle yaşarsın

Su gibi akıp duran duygulara bent oluyorum, taşacağız

Çok uzun yolun başı, bunu sevgi ve saygıyla taşıyacağız

Türkü gibi hislere tercüman, nağme olsun hep dualarda

Zihnin ve gönlün açık olsun sevgi pınarı anacığınla

Gelin çiçeği kadar güzel olsun yaşamın her nefesinde

Masum gözlerinden acı değil, sevinç gözyaşlarıyla

Tanrım bahtını açık, kalbini mutlu kılsın, ömür boyunca

Kaç yıl gelir geçer koçlar gibi, anasına cesaret veren

Derin düşleriyle yüreği adeta bir meltem gibi esen

Nadide bir geleceğin olsun, seveninle övgüye değen

Hasretler misali uzaklardan geleceğin günleri özleyerek

Nazardan koruyacaktır inan seni seven gönüllerden', 'Benzersiz kalbinle sevgi ve saygıda kusursuz yargıcımsın Kanına kan kattığın kuzucuklarına hep merhametlisin İyi ki sen varsın, bilirim ince...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kusursuz-yargicimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlem', 'ozlem-cafer-tayyar-ozkan-bwytc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayatın anlamı özlem, 

Kalpleri sevgiyle yakan duygu.

İçleri titretir, umutları yeşertir. 

Aşklara yelken açan da, 

İhanetlere sebep olan da, 

Karşı koyulmayan arzularla, 

Hırçın bir denize döndüren, 

Gündüzü karanlığa, 

Mutluluğu acılara boğup, 

Ölesiye içtiren de, 

Gurbetin toprağında çektiren de, 

Gem vurulmayan, 

Yine özlem.

Mevsim ne olursa olsun, 

Gönülde bahar çiçekleri açtıran.

Denizin sonsuz maviliğinde, 

Ufka çöken güneşin kızıllığında, 

Kır çiçeklerinin renginde, 

Dağların doruğundaki kardelenin ruhunda.

Onunla uzaklar yakın, 

Yürekler huzura mekan, 

Gönüller umuda yelken açar. 

“Özlem dolu kalpler”, 

Yoktur onlarda asla vefasızlık, 

Kanatları göçmen kuşları misali, 

Hasret denizlerini aşmaya, 

Tutkuları yenmeye amadedir.

Akıl ve göz hükmederse kalbe, 

O zaman vuslata erer tenlerde, 

Dudaktan kalbe giden yollarda, 

Onlar, toz pembe düşlerde, 

Bakmasını bilen gözlerde, 

Aşka susamış gönüllerde. 

Özlemler, 

Sevgiye sevgi katan, 

Aşka derman olan duygular, 

İhanet ve ızdırapların da en güzel çaresi, 

Sevgisizlik girdabındaki her nefesi, 

Kalplerin özlemleriyle, 

Buluştuğu yerde bekliyorum.', 'Hayatın anlamı özlem,  Kalpleri sevgiyle yakan duygu. İçleri titretir, umutları yeşertir.  Aşklara yelken açan da,  İhanetlere sebep olan da...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/ozlem-92-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabır Taşına', 'sabir-tasina-cafer-tayyar-ozkan-tf6p3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana adadım yanmış yüreğimi

Bayram olur seni bağrıma bastığım gün

Sakın hor görme aşkınla yanan kalbimi

Gel de gör, 

Seninle geçen her günü bayram bilen 

Deli divane olmuş, 

Sabır taşına dönmüş halimi', 'Sana adadım yanmış yüreğimi Bayram olur seni bağrıma bastığım gün Sakın hor görme aşkınla yanan kalbimi Gel de gör,  Seninle geçen her günü ...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sabir-tasina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ve Ben', 'sen-ve-ben-cafer-tayyar-ozkan-4t27p', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İçimde bir sen varsın bir de ben

Ama ne çare olamayız biz sen ve ben

Gönül tahtıma yine kondun, şanslısın

Damarımdaki kanım, gözümdeki yaşsın.', 'İçimde bir sen varsın bir de ben Ama ne çare olamayız biz sen ve ben Gönül tahtıma yine kondun, şanslısın Damarımdaki kanım, gözümdeki yaşsı...', ARRAY['Türk Edebiyatı','Şiir','Cafer Tayyar Özkan']::text[], 8.5, '{"poet":"Cafer Tayyar Özkan","poet_slug":"cafer-tayyar-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-ve-ben-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Berlin Türküsü', 'berlin-turkusu-selcuk-yilmaz-4u1ay', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Berlin'' de bir türkü sesi, 

Duyar mı bilinmez tutkuda özlemi, 

Bir Çınar altı köy kahvesinde, 

Memleketten uzak ötesi.

Lili Marlen türküsü  hep dillerde, 

Papyonlu Memet Berlin''de caddelerde, 

Anadolu''nun kahırlı ırak köy yolları, 

Erir gider  Almanya türküsünün içinde...

Selçuk Yılmaz 31.1.2003, İzmir', 'Berlin'' de bir türkü sesi,  Duyar mı bilinmez tutkuda özlemi,  Bir Çınar altı köy kahvesinde,  Memleketten uzak ötesi. Lili Marlen türküsü  ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Yılmaz']::text[], 8.5, '{"poet":"Selçuk Yılmaz","poet_slug":"selcuk-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/berlin-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Kalan Şiirler -5-', 'yarim-kalan-siirler-5-turgut-erdogan-j66ar', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey! ! ! 

Hüznü tomurcuk yarim…

Hiç görmez misin naçardır halim.

Oyy diyemem ki

Lâldir dilim.

Saçlarını sevemem ki

Kırıldı elim…

Alanya,31/01/2003', 'Ey! ! !  Hüznü tomurcuk yarim… Hiç görmez misin naçardır halim. Oyy diyemem ki Lâldir dilim. Saçlarını sevemem ki Kırıldı elim… Alanya,31/01...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yarim-kalan-siirler-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Kalan Şiirler -6-', 'yarim-kalan-siirler-6-turgut-erdogan-3gypl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yokluğunda…

Gözlerim kararıyor, 

Yüreğim daralıyor.

İçimdeki o küçük çocuk

Vurup sırtına heybesini, 

Alıp başını gidiyor, 

Yazılmamış öykülere…

Alanya,31/01/2003', 'Yokluğunda… Gözlerim kararıyor,  Yüreğim daralıyor. İçimdeki o küçük çocuk Vurup sırtına heybesini,  Alıp başını gidiyor,  Yazılmamış öyküle...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yarim-kalan-siirler-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkü Bitti', 'turku-bitti-turgut-erdogan-10uck', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '“En çocuk sesinin anımsadığımda şimdi

Sen çoktan bir bahar sabahıydın hiç uyanmadığım…

Onur CAYMAZ”

Öykülerde böyle yaşanmaz aşklar! 

Ansızın başlayıp tutkulu sürer.

Ve beklenen odur ki

Tüm öyküler mutlulukla biter.

Ansızın başlamıştı sevdamız, 

Çok kavuşamasa da ellerimiz, 

Bir diğerine demir atamasa da gözlerimiz, 

Her anı öykü misali yaşadı bedenlerimiz.

Öykünün sonlarıydı, 

Uzun ince bir yol idi, 

Gide gide derman bitti.

Apansız aşk tükendi, 

Perde kapandı, öykü bitti.

Bozlaklar söylenmez oldu yamaçlarda, 

Kol kırıldı, mızrap düştü, 

Türkü bitti…

Alanya,31/01/2003', '“En çocuk sesinin anımsadığımda şimdi Sen çoktan bir bahar sabahıydın hiç uyanmadığım… Onur CAYMAZ” Öykülerde böyle yaşanmaz aşklar!  Ansızı...', ARRAY['Türk Edebiyatı','Şiir','Turgut Erdoğan']::text[], 8.5, '{"poet":"Turgut Erdoğan","poet_slug":"turgut-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/turku-bitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanmaki', 'sanmaki-oguzhan-tas-w81au', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sanmaki unutur bu gönül seni, 

Sanmaki avutur hayalin beni, 

Düşündükçe canım sensizliği, 

Öldüresim gelir kendimi', 'Sanmaki unutur bu gönül seni,  Sanmaki avutur hayalin beni,  Düşündükçe canım sensizliği,  Öldüresim gelir kendimi...', ARRAY['Türk Edebiyatı','Şiir','Oğuzhan Taş']::text[], 8.5, '{"poet":"Oğuzhan Taş","poet_slug":"oguzhan-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sanmaki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HAYAL GİBİ', 'hayal-gi-bi-arzu-dincer-jmvuy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayal gibi bir aşktı yaşadıklarımız.

Kaç sabahı selamladık beraber, 

Kaç gün batımı idi izlediğimiz, 

Uyanmak istemediğimiz bir rüya’da, 

Biz’dik, yalnız dünyamızda yaşayan

Gitmediğimiz yerler, 

Sevgimizde can buldu, 

Görmediğimiz çiçekler, 

Gönüllerimizde açtı...

Hayal gibi bir aşktı yaşadığımız, 

Gökyüzüne kaç güvercin salmıştık, 

Dört bir yana, 

Ulaştırsın destanımızı diye, 

Gözlerimiz cevahir olduğunda, 

Kaç kez birbirimiz için vurmuştu..

Hayal gibi bir aşktı yaşadıklarımız

Gönül ezgilerini kaç kez söylemiştik, 

Söylediğimizi unutarak, 

Ve kaç kez haykırmıştık, 

Dağlara, tepelere

Seni seviyorum diye...

Hayal gibi bir aşktı yaşadıklarımız, 

Göbeği bengisuyuna atılmış...', 'Hayal gibi bir aşktı yaşadıklarımız. Kaç sabahı selamladık beraber,  Kaç gün batımı idi izlediğimiz,  Uyanmak istemediğimiz bir rüya’da,  Bi...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hayal-gibi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gonca gülüm', 'gonca-gulum-omer-sevim-60vfv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gonca gül gibidir sevdiğim

Gül gibi saf ve masum

Gül gibi anlamlı ve manalı

Gül gibi temiz, gül gibi narin

Bense bir çiğ damlasıyım yaprağında

Sessiz ve sakin

Gonca gül gibidir sevdiğim

Onurlu ve dikbaşlı fırtınaya karşı

Sevgi dolu ve şefkatlidir

Dalına konan bülbüle karşı

Gonca gül gibidir sevdiğim

Sevginin ifadesi yüreğimin sesidir

Toprağa can veren ab-ı hayattır

Sözlerimin tercümanı, yaşamamın sebebidir

Bir garip''YAŞAR''ım dünya denen hanede

Ey gonca gülüm koma sen beni dertten derde

Ver elini bitsin bu vuslat, kalksın şu perde

Canda sensin cananda sen

Uğur böceğinin sırtındaki benek gibi

Taşıyorum seni yüreğimin derinliklerinde...', 'Gonca gül gibidir sevdiğim Gül gibi saf ve masum Gül gibi anlamlı ve manalı Gül gibi temiz, gül gibi narin Bense bir çiğ damlasıyım yaprağın...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevim']::text[], 8.5, '{"poet":"Ömer Sevim","poet_slug":"omer-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gonca-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel', 'gel-adi-guzel-8a5xy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gel ey, benim gül kokan sevdam, 

Gel benim şiirim, vuslatım, hasretim, , , 

Gelde dindir bu gönül yarasını, 

Bak geçti geçiyor ilkbahar.

Gel, ey benim ilk ve son bestem, 

Gel ilk sözüm, ilk müziğim, nakaratım...

Gelde bitsin artık bu şarkı, 

Bak geldi geliyor sonbahar...', 'Gel ey, benim gül kokan sevdam,  Gel benim şiirim, vuslatım, hasretim, , ,  Gelde dindir bu gönül yarasını,  Bak geçti geçiyor ilkbahar. Gel...', ARRAY['Türk Edebiyatı','Şiir','Adı Güzel']::text[], 8.5, '{"poet":"Adı Güzel","poet_slug":"adi-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gel-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyusam...', 'uyusam-adi-guzel-1uahb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uyku esir alsa gözlerimi, 

Dalsam figanı efkarına...

Görsem nur cemalini, 

O anda hıçkırıklara boğulsam...', 'Uyku esir alsa gözlerimi,  Dalsam figanı efkarına... Görsem nur cemalini,  O anda hıçkırıklara boğulsam......', ARRAY['Türk Edebiyatı','Şiir','Adı Güzel']::text[], 8.5, '{"poet":"Adı Güzel","poet_slug":"adi-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/uyusam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çakır gözlüm', 'cakir-gozlum-omer-sevim-7p9tp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gündüzü kovan gecenin yarısındayım

Dalmışım fezanın sonsuzluğuna

Bir yıldız koptu semadan

Sen geldin aklıma 

Bir dilek tuttum çakır gözlüm

Hani derler ya 

Bülbülün yüz hikayesi varmış

Hepsi gül üstüne

Kalbimin tüm dilekleride

Hep senin üstüne çakır gözlüm

Dileğim

Seninle her an beraber olmaktı

Sevgi hamuruyla yoğrulmak

Aşkın şarabını yudumlamak seninle

Dileğim

Bir rüzgar olup

Esmektir seninle sonsuzluğa çakır gözlüm

Ben dileğimi tutarken çakır gözlüm

Bir ezan sesiyle titredi tüm benliğim

Ya rabbi o ne huzur verici bir ses

Hafifledim bir abdest aldım

Açtım ellerimi gecenin ve gündüzün hükümranına

Dilek, yerini duaya bırakmıştı

Dualarımda yine sen vardın çakır gözlüm', 'Gündüzü kovan gecenin yarısındayım Dalmışım fezanın sonsuzluğuna Bir yıldız koptu semadan Sen geldin aklıma  Bir dilek tuttum çakır gözlüm H...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevim']::text[], 8.5, '{"poet":"Ömer Sevim","poet_slug":"omer-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/cakir-gozlum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evim', 'evim-adi-guzel-s3pc1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Odamda cam kırıkları...

Duvarda resimsiz bir çerçeve...

Köşede boş bir dolap, 

Pencere ise perdeye hasret...

Badananın altında saklı yüzler...

Kapı çarpılmaktan eskimiş, 

Ahşap merdiven inlemekte...

Her yağmurda ağlayan...

Kırmızı kiremitli evim...', 'Odamda cam kırıkları... Duvarda resimsiz bir çerçeve... Köşede boş bir dolap,  Pencere ise perdeye hasret... Badananın altında saklı yüzler....', ARRAY['Türk Edebiyatı','Şiir','Adı Güzel']::text[], 8.5, '{"poet":"Adı Güzel","poet_slug":"adi-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/evim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut olmak', 'umut-olmak-tevfik-karinca-ui86x', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kuruttuğun bir gül olabilseydim

Kitabının arasında

Bakardın hiç değilse arada sırada

Bir umut olsaydım yüreğinde

Gerçekleşmesini beklediğin

yüreğinde kalırdım hiç olmazsa

Bir gözyaşı olabilseydim gözlerinde

akıttığın

Okşardım yüzünü ağladığında

Ben hiçbirşey olmaktan korkardım sende

Korktuğum geldi şimdi başıma', 'Kuruttuğun bir gül olabilseydim Kitabının arasında Bakardın hiç değilse arada sırada Bir umut olsaydım yüreğinde Gerçekleşmesini beklediğin ...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Karınca']::text[], 8.5, '{"poet":"Tevfik Karınca","poet_slug":"tevfik-karinca","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/umut-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdanın Türküsü', 'sevdanin-turkusu-adi-guzel-p6uz4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uzaklardan bir türkü sesi gelir...

Ama kulağımla değil, 

Yüreğimle dinlerim o sesi, 

Öylesine yumuşak ve derinden...

Acı çeken bir sevdalıyı anlatır, 

Tıpkı bütün türkülerin anlattığı gibi...

Ama bir fark var, 

Sevdalı sevdasını acıyla birleştirmiş, 

Belkide kader sanmıştır; 

Sevdasındaki acıyı bilinmez ki...

Belkide kader; 

Acısındaki Sevdadır...

Sevdalının.......', 'Uzaklardan bir türkü sesi gelir... Ama kulağımla değil,  Yüreğimle dinlerim o sesi,  Öylesine yumuşak ve derinden... Acı çeken bir sevdalıyı...', ARRAY['Türk Edebiyatı','Şiir','Adı Güzel']::text[], 8.5, '{"poet":"Adı Güzel","poet_slug":"adi-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevdanin-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılar...', 'anilar-adi-guzel-enmr2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bulutlar dolu dolu, 

Ağlamak ister gibi...

Güneş yüzünü göstermiyor, 

Saklanmak ister gibi...

Yalnızlık var gökyüzünde, 

Dokunsan ağlayacak gibi...

Bilmediğim bir anlam var, 

Bugün anılarda n'' var? ...', 'Bulutlar dolu dolu,  Ağlamak ister gibi... Güneş yüzünü göstermiyor,  Saklanmak ister gibi... Yalnızlık var gökyüzünde,  Dokunsan ağlayacak ...', ARRAY['Türk Edebiyatı','Şiir','Adı Güzel']::text[], 8.5, '{"poet":"Adı Güzel","poet_slug":"adi-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anilar-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün...', 'huzun-adi-guzel-mfw6d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Korkuyorum, çünkü neşeliyim, 

Her an üzülecekmiş gibiyim, 

N'' olur hüzün...

Bugün benden uzak dur! 

Bu anım böyle geçsin, 

Yarın seninleyim yine! ! ! : (', 'Korkuyorum, çünkü neşeliyim,  Her an üzülecekmiş gibiyim,  N'' olur hüzün... Bugün benden uzak dur!  Bu anım böyle geçsin,  Yarın seninleyim ...', ARRAY['Türk Edebiyatı','Şiir','Adı Güzel']::text[], 8.5, '{"poet":"Adı Güzel","poet_slug":"adi-guzel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/huzun-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-i-smail-korkmaz-0dfk8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen 

Uçurtmayı ve turnaları 

Sen 

Sevgiyi ve barışı 

Sen 

Süt kokulu yavrunun sıcaklığını 

Sen 

Bir bakışın anlattıklarını 

Sen 

Yaklaşıp yaklaşıp da ulaşılamayanı 

Anlatabilir misin sevgili 

Ve 

Psikolojik karmaşıklığımı 

Sosyolojik çelişkilerden 

Örnekler vererek 

Açıklayıp teselli edebilir misin beni 

Hayir 

Sen yozlaşan kültürün 

Esiri olmuşsun 

Ben dere kenarını düşünürken 

Sen pahalı bir restoranda 

Buluşmayı hayal ediyorsun. 

26 Şubat 1998- Niksar', 'Sen  Uçurtmayı ve turnaları  Sen  Sevgiyi ve barışı  Sen  Süt kokulu yavrunun sıcaklığını  Sen  Bir bakışın anlattıklarını  Sen  Yaklaşıp ya...', ARRAY['Türk Edebiyatı','Şiir','İsmail Korkmaz']::text[], 8.5, '{"poet":"İsmail Korkmaz","poet_slug":"i-smail-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sen-215-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su', 'su-selcuk-yilmaz-i1nf8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ana tanrıça kaynağında, su

Deviniminde  dünyanın, özünde su

Varlığın ve gökyüzünün sentezi, 

 Yelken misali açılır, gönüllerde su.....S. Y.  31.1.2003 İzmir', 'Ana tanrıça kaynağında, su Deviniminde  dünyanın, özünde su Varlığın ve gökyüzünün sentezi,   Yelken misali açılır, gönüllerde su.....S. Y. ...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Yılmaz']::text[], 8.5, '{"poet":"Selçuk Yılmaz","poet_slug":"selcuk-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/su-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost''la Söyleşi', 'dost-la-soylesi-faik-erol-ppc1m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dün yine Yıldız  Park’ına gittim Gülüm; 

yine o aşk anıtına.

Ve yine Dost geldi de yanıma; 

insanlığımdan utandım, yine selâm etti sana.

Önce onu ileteyim, üzerimde kalmasın, 

sonra Dost’la, dostça, 

biraz hakkın’da söyleşeyim; aklı sende kalmasın.

''işte dostum, biz insanlar böyleyiz.

Sevgiden, gelen yoksa, kolay kolay sevmeyiz.

Dost mu demişlerdi sana; dostluk mu demişlerdi? 

Tüylerini okşarken, gerçekten mi sevmişlerdi? 

Hayır dostum hayır; onların sevgileri sadece dillerinde.

Bir de; inandırmak için okşayan ellerinde.

Oysa sen dostluğu çok iyi bilirsin. Sadâkati, sevgiyi de. 

Ve sen; bu bankı da çok iyi bilirsin.

Bu bankta seviştiğim sevgiliyi de.

Onun için, söz ver bana.

Bu bankın kutsallığına, bir de benim dostluğuma inanıyorsan eğer, bana dostluk sözü ver.

İhmâl etme n’olursun; bu bankta hep, gerçekten sevenler gelsin, otursun.

Altıncı hissin var senin, hemencecik anlarsın.

Gerçekten sevmiyorsa biri, kendisine havlarsın! 

Ona gelince  ona; 

sadece dostluğu senin kadar bilseydi, bu da yeterdi bana.

Oysa hani? Bildi mi? 

Söz vermişti hani sana; şimdiye dek geldi mi? 

Daha da gelmeyecek! 

Belki yarın, bir başkasının elini tutup, sevgiden, aşktan söz edecek.

Belki yarın, bir başkasıylan gelecek.

Bugün bana, yarın ona; yine aşkı anlatacak, 

dostluktan söz edecek.

Sen gidersen yanlarına; 

tüylerini okşayıp, yine ''DOST'' diyecek sana.

Ama...

Yıllar sonra birgün, görmeye gittiğin zaman.

Belki bir Alman Kurdu, belkide bir doberman.

Bir başka Dost bulup bağlamışsa kapısına; 

önce o hırlayacak.

Sonra kendisi çıkıp, bu kez ''HOŞT'' diyecek sana! 

Bu kez ''HOŞT'' diyecek sana! ''', 'Dün yine Yıldız  Park’ına gittim Gülüm;  yine o aşk anıtına. Ve yine Dost geldi de yanıma;  insanlığımdan utandım, yine selâm etti sana. Önc...', ARRAY['Türk Edebiyatı','Şiir','Faik Erol']::text[], 8.5, '{"poet":"Faik Erol","poet_slug":"faik-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/dost-la-soylesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Dalıydı...', 'gul-daliydi-riza-akdag-zlgk9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'incecikti

gül dalıydı

dokunsam kırılacaktı

dokunmadım

kurudu..', 'incecikti gül dalıydı dokunsam kırılacaktı dokunmadım kurudu.....', ARRAY['Türk Edebiyatı','Şiir','Rıza Akdag']::text[], 8.5, '{"poet":"Rıza Akdag","poet_slug":"riza-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gul-daliydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Eli', 'dost-eli-faik-erol-yxml3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eğer sen de evlendiysen, nişanlı ya da sözlüysen; 

sevdâlın değilim ben.

Dostluğuna sevdalıyım.

O dopdolu dostluğuna sevdâlıyım ben.

Ellerim uzanır hep; 

biri dostluğa, sevgiye, diğeri aşka.

İkisini de tutarsan, onun tadı bambaşka! 

Ama, birinden biriyse; 

aşkın olmasın varsın.

Dost elini uzat bana, öteki sende kalsın.

Bir öpüşün, dudaktan; dostluğa kıyacaksa, 

sonunda benim yanıma, sensizlik kalacaksa, 

yılların dostluğu, böyle yıkılacaksa, 

böyle derinse bedeli; 

tadı olmasın varsın.

Yanağını uzat bana, dudağın sende kalsın.', 'Eğer sen de evlendiysen, nişanlı ya da sözlüysen;  sevdâlın değilim ben. Dostluğuna sevdalıyım. O dopdolu dostluğuna sevdâlıyım ben. Ellerim...', ARRAY['Türk Edebiyatı','Şiir','Faik Erol']::text[], 8.5, '{"poet":"Faik Erol","poet_slug":"faik-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dost-eli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yürekten Sevdim Ben', 'yurekten-sevdim-ben-halil-gulel-s8hpe', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çektirsen de cehennem azabını bana; 

Kin tutmam, çünkü, seni yürekten sevdim ben.

Boyansa da bu kalbim bakışınla kana

Dur gitmem, çünkü, seni yürekten sevdim ben.

Baharım döner kışa sen yoksan yanımda, 

Neice tufanlar kopar nice etrafımda, 

Sen varsın her yerremde sen varsın kanımda

Hiç yitmem, çünkü, seni yürekten sevdim ben.

Biliyorum bu dünya sana gelmekte dar, 

Saraylara layıksın kalbimde saray var, 

Seni aradım seni gezdim diyar diyar

Pes etmem, çünkü, seni yürekten sevdim ben.

Gel artık, zaman geçer bu sular aktıkça, 

Huzur ararsın huzur gözlerin baktıkça, 

Bir duman tüter senin bakışın yaktıkça

Hiç bitmem, çünkü, seni yürekten sevdim ben.

Ressam Halil, palette binbir çeşit boya, 

Benzer tuvalde gökten inmiş dolunaya, 

Gerçek olur bu sevda gerçek olur rüyâ

Söy katmam, çünkü, seni yürekten sevdim ben.

Düsseldorf / 16.12.2002', 'Çektirsen de cehennem azabını bana;  Kin tutmam, çünkü, seni yürekten sevdim ben. Boyansa da bu kalbim bakışınla kana Dur gitmem, çünkü, sen...', ARRAY['Türk Edebiyatı','Şiir','Halil Gülel']::text[], 8.5, '{"poet":"Halil Gülel","poet_slug":"halil-gulel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/yurekten-sevdim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Gidiyorum Elveda', 'artik-gidiyorum-elveda-salih-ozalasan-ff16s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Artık gidiyorum herşeye elveda

Ömrümün son demi bu son veda

Sevgiler yaşanmaya değer, ömür feda

Ömür kalmamışsa artık, yetmez seda

Sesimi duymadın, duymadı, duymadılar

Yüreğimi görmedin, görmedi, görmediler

Yazdığımı okumadın, okumadı, okumadılar

Kimsem yoksa, artık niye bunca çaba

Sevdaya adanmıştı küçücük yüreğim

Sayfalar dolusu yazdım yoruldu kalemim

Sana, size, sizlere değil asla sitemim

Sevgili kalmamışsa, ne gerek yazmama

Gidiyorum gözüm ardımda 

Umudum tükenmiş yüreğim yaralı

Biliyorum sevmek yetmiyor aslında

Sevgi kalmamışsa, ne işim var burada

Bana elveda siz erin mutlaka murada

Sevgiliyi bulun ister gurbet ister sılada

Eğer birgün bu kalem tekrar yazarsa

Bilinki sonserseride ermiş murada

y.Tarihi 31.01.2003 Saat 17.40', 'Artık gidiyorum herşeye elveda Ömrümün son demi bu son veda Sevgiler yaşanmaya değer, ömür feda Ömür kalmamışsa artık, yetmez seda Sesimi du...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/artik-gidiyorum-elveda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elifbamın Yapraklarında Gemilerim, Yelkenli Gemilerim', 'elifbamin-yapraklarinda-gemilerim-yelkenli-gemilerim-kucuk-i-skender-mahpg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '-asal sayıdır yalnız insan

                                                     bir''den ve kendisinden başka

                                                     kimselere bölünmez! -

kapaklanmışım kapkara bir neyin üstüne

başımdan aşağı kaynar karanfiller dökülüyor

kendimin elleri bunlar, kendimin gözleri, unutmadım

tavaf ediyor yüzümü

bir eşcinselin lalli ölüsü

tüller serpilmiş gençliğim

bir hicran kını sanki. sahil düşüyor pozum

filmin negatifinde. fotoğrafçı, asıl çocukluğum.

ve bana verdiği ödünç gülümsemeyi bırakıp oraya

bir masalı yazmaya başlıyorum yeniden

kötü üvey anne, iyi prenses

aciz, hasta padişah baba

kurbağalar, balkabakları ve kaf dağı

ne çare! efsun yetmiyor acımı dindirmeye

perikızı inandıramıyor beni hayatın gerçeklerine! 

ve ben çıkar çıkmaz

iri bir palyaço burnuna dönüşüyor

hayal kasabası

nerden aktığı belli olmayan bir kan var dudağımda

ve dudağımda nerden gelip konmuşsa bir kuş gözyaşısı! 

ağlıyorum, omzuma puhular yerleştirerek 

teselli ediyor beni elifbam, 

bu akşamüstü ben

hala kimi sevdiğimi ve kimi özlediğimi bilmeden

bir sıkıntıyı ateşe veriyorum

alevlerin leşini kucağımdan yatağıma yatırıyorum sonra, 

kalbim

altta hüznün uyuduğu

üstte umudun sabahladığı bir ranza

gibi sürekli gıcırdıyor birinin koynunda.

23.kasım.1989', '-asal sayıdır yalnız insan                                                      bir''den ve kendisinden başka                                ...', ARRAY['Türk Edebiyatı','Şiir','Küçük İskender']::text[], 8.5, '{"poet":"Küçük İskender","poet_slug":"kucuk-i-skender","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/elifbamin-yapraklarinda-gemilerim-yelkenli-gemilerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani', 'hani-sevda-cicegi-jvyz9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hani o beyaz düşlerinin 

Bembeyaz sevdalısı

Hani nerde? 

Buram buram sevda yüklü sözcüklerin

Nerede  kaldılar

Bir anlık kızgınlıkla

Uçup gittiler değil mi? 

Bir daha dönmemek üzere

Mavi Düşler Ülkesine.', 'Hani o beyaz düşlerinin  Bembeyaz sevdalısı Hani nerde?  Buram buram sevda yüklü sözcüklerin Nerede  kaldılar Bir anlık kızgınlıkla Uçup git...', ARRAY['Türk Edebiyatı','Şiir','Sevda Çiçeği']::text[], 8.5, '{"poet":"Sevda Çiçeği","poet_slug":"sevda-cicegi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hani-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdan', 'sevdan-sevda-cicegi-z4vpp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Benden daha iyi bilirsin

Ne kadar unuttum desemde

Sevdamın ateşini

Gözyaşlarımla dindirsemde

Sen  koca bebeğim

Sen hiç inanmazsın.', 'Benden daha iyi bilirsin Ne kadar unuttum desemde Sevdamın ateşini Gözyaşlarımla dindirsemde Sen  koca bebeğim Sen hiç inanmazsın....', ARRAY['Türk Edebiyatı','Şiir','Sevda Çiçeği']::text[], 8.5, '{"poet":"Sevda Çiçeği","poet_slug":"sevda-cicegi","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevdan-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dinle Tabip,', 'dinle-tabip-mine-ozdemirtas-1wr2s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Söylenecek sözler bitti diye mi? / başladı saltanatı suskunluğun? 

ne çabuk soluksuz kaldı? / Ölümsüz aşka tutkunluğun.

Sevin tabip sevin ki.... neşterinden yara almışım.

Gece sadece zamandır diyorsan eğer ve gerisi yalan

Bence; mutluluk değil. / yaşanmamışlık olacak avuçlarına dolan.

Anla tabip anla ki.... ustalığına hayran kalmışım', 'Söylenecek sözler bitti diye mi? / başladı saltanatı suskunluğun?  ne çabuk soluksuz kaldı? / Ölümsüz aşka tutkunluğun. Sevin tabip sevin ki...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dinle-tabip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoban Kızım', 'coban-kizim-halil-ozbek-r5k3y', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sana yağmurun hikayesini anlatmışmıydım çoban kızım

o incecik saçlarının kıvrımlarından

bir gümüş gibi dökülürdü damlalar 

germiyan sokakta bir türkün vardı

ayaklarımızın taktaklayışı

yağmurla berhava toprağı

ah çoban kızım ah..

sen olmadan kaldırmayacağım başımı

yorgun otobüs pencerelerinden 

sen olmadan koymacağım ismini 

melül kayığımın 

sen olmadan inmeyeceğim inzivaya

çekildiğim maltepeden 

rüzgar beni tokatlasada

alestadır gözlerim

kaybolmuş mavi derinliklerde 

saçlarımda ağardı

dizlerimde titriyor 

nerdesin be çoban kızım nerdesin..', 'sana yağmurun hikayesini anlatmışmıydım çoban kızım o incecik saçlarının kıvrımlarından bir gümüş gibi dökülürdü damlalar  germiyan sokakta ...', ARRAY['Türk Edebiyatı','Şiir','Halil Özbek']::text[], 8.5, '{"poet":"Halil Özbek","poet_slug":"halil-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/coban-kizim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Hiç Öldün Mü?', 'sen-hic-oldun-mu-ozan-rari-hrnq5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kıymetin bilinmeden göçtün mü hiç sen, 

Uzaklara bilinmezliklere doğru yolculuğa çıktın mı? 

Seni en çok sevdiğin bırakıp gitti mi yüz üstü hiç, 

Yaşadın mı acıların en büyüğünü, 

Yüreğin dağlanmış kor kor ateşlerde kaldı mı? 

Yanındayken onu kaybetmekten korkarken, 

Başına geldi mi hiç bu, 

Ansızın çekip giden sevgilinin yolunu gözledin mi gecelerce! 

Her gördüğünü o zanettin mi, 

Ne zaman bir çift renkli göz görsen dalıp gittin mi maziye

Alaca karanlıkta kaldın mı? 

İçinde ufak hatta minicik bir ümit kaldı mı, 

O çok sevdiğin geriye gelir diye! 

Seni bilemiyorum

Ben hepsini yaşadım

Senin sayende...', 'Kıymetin bilinmeden göçtün mü hiç sen,  Uzaklara bilinmezliklere doğru yolculuğa çıktın mı?  Seni en çok sevdiğin bırakıp gitti mi yüz üstü ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Rari']::text[], 8.5, '{"poet":"Ozan Rari","poet_slug":"ozan-rari","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-hic-oldun-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bosna', 'bosna-nizamettin-dereci-rpite', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevgi, hayattır.

Hayatta kalma sırrı.

Sevgi, sonsuzluğu özlemenin eseri.

Sevgi, her şeye, 

İnsana, canlıya tüm yaratığa.

Sevgisiz gönüller, yalnız, serseri.

Acımamak, sevgisizlik eseri.

Bir tomurcuk bile, sevgi beklerken, 

Lal kesildi dünya, Bosna inlerken.

Birleşmiş Milletler, İnsan hakları, 

Heyhat.. Bak ki, kimlere kaldı işin.

Ey Osmanlı, ne zaman dirilişin.?', 'Sevgi, hayattır. Hayatta kalma sırrı. Sevgi, sonsuzluğu özlemenin eseri. Sevgi, her şeye,  İnsana, canlıya tüm yaratığa. Sevgisiz gönüller, ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Dereci']::text[], 8.5, '{"poet":"Nizamettin Dereci","poet_slug":"nizamettin-dereci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bosna-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kader', 'kader-nizamettin-dereci-bumxm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yolunda yolcuyum, kader kurbanı, 

Bana beklemekten başka ne gerek.

Yıllar önce, kader çizdi bu anı.

Sevmek senin için zülüm mü demek.? 

Bir gün elemlerde, bir gün kederde, 

Gün boyu yaşanan, sevgiler nerde.? 

Gözlerin her şeyi anlatır bana, 

Bırak yorumumu, kendim yapayım.

Belki bir gün, cemre düşer odana.

Ben de, aynı derdin umudundayım.

Bir gün elemlerde, bir gün kederde, 

Gün boyu yaşanan, sevgiler nerde.?', 'Yolunda yolcuyum, kader kurbanı,  Bana beklemekten başka ne gerek. Yıllar önce, kader çizdi bu anı. Sevmek senin için zülüm mü demek.?  Bir ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Dereci']::text[], 8.5, '{"poet":"Nizamettin Dereci","poet_slug":"nizamettin-dereci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kader-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda Gençlik', 'elveda-genclik-nizamettin-dereci-kcygs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elveda gençlik..! 

Çocukluğumda, büyümek, 

Yaşlılığımda, küçülmek, 

Her yol sana mı çıkar.? 

Her arzuda sen mi varsın.? 

Nerdesin.? 

Pembe rüyalar, ölümsüz aşklar, 

Bitmeyen enerji, düşmeyen başlar, 

Nerdesin.? 

Ne çabuk ayrıldın, tanışamadan.? 

Ne çabuk susturdun, konuşamadan.? 

Evet, herkes seni arar durmadan, 

Nerdesin.? 

Dev ayna mı tuttun, benim karşıma.? 

Hadi itiraf et, yanıltın beni.', 'Elveda gençlik..!  Çocukluğumda, büyümek,  Yaşlılığımda, küçülmek,  Her yol sana mı çıkar.?  Her arzuda sen mi varsın.?  Nerdesin.?  Pembe r...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Dereci']::text[], 8.5, '{"poet":"Nizamettin Dereci","poet_slug":"nizamettin-dereci","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/elveda-genclik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otuz Yaş', 'otuz-yas-nizamettin-dereci-3sb37', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ey gökkubbe, nihayetin nerede.? 

Al beni yanına ordan bakayım.

Ey beni benlikten alan eğlence.

Geçen günlerimi kimden sorayım.? 

Ey otuz yaş, ey otuz yıl sahibi.! 

Adım adım seni hesap edeyim.

Hesapsızlık bende dünya ayıbı.

Bilmem ki ben yolun neresindeyim.

Ey kabir kapısı, ey mecburi yön.! 

İsterdim ki sana yalnız geleyim.

Yolcuya yük olan günahlara son.

Günahsız halimle sona ereyim.', 'Ey gökkubbe, nihayetin nerede.?  Al beni yanına ordan bakayım. Ey beni benlikten alan eğlence. Geçen günlerimi kimden sorayım.?  Ey otuz yaş...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Dereci']::text[], 8.5, '{"poet":"Nizamettin Dereci","poet_slug":"nizamettin-dereci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/otuz-yas-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmaz ki!', 'olmaz-ki-nizamettin-dereci-k84rq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşamak için hava, 

Yaşatmak için, sevgi, 

Bir kalemle, silip atmak olmaz ki..

Damla damla deler, 

Karataş’ı su, 

Çok su ile karataş yarılmaz ki..

Geceden sonra, gündüz, 

Kıştan sonra ilk bahar, 

Dört mevsim, bir anda yaşanmaz ki..

Her şeyin, kendine has, 

Güzelliği var amma..

  Görmek için bakmayan, gözlerin anlamaz ki..

 Kalp, sevgiyi besler, 

 Sevgi, her şeyi..

 Kırmak için kalbi, yol aranmaz ki..

 Yok ettin, nem  kaldı, 

 Sevgiye dair.? 

 Lekeler içinde toz aranmaz ki..', 'Yaşamak için hava,  Yaşatmak için, sevgi,  Bir kalemle, silip atmak olmaz ki.. Damla damla deler,  Karataş’ı su,  Çok su ile karataş yarılma...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Dereci']::text[], 8.5, '{"poet":"Nizamettin Dereci","poet_slug":"nizamettin-dereci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/olmaz-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Kız', 'kayip-kiz-barbaros-mustafa-guner-ftucx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kayıp Kız

bilmemki kayıp kız zamanın neresinde durur neresine gider.

heralde zamanın ötesinde duruyorki özlenmekte, 

heralde zamanın berisinde duruyorki yaşlanmakta..', 'Kayıp Kız bilmemki kayıp kız zamanın neresinde durur neresine gider. heralde zamanın ötesinde duruyorki özlenmekte,  heralde zamanın berisin...', ARRAY['Türk Edebiyatı','Şiir','Barbaros Mustafa Güner']::text[], 8.5, '{"poet":"Barbaros Mustafa Güner","poet_slug":"barbaros-mustafa-guner","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kayip-kiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdesin?', 'nerdesin-nizamettin-dereci-ngzhl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nerdesin, gecenin karanlığında, 

Aydınlığı  aratmayan rehberim.

Nerdesin, Gençliğin deli çağında, 

Çiçeğimi saratmayan rehberim.

Hani, dağda bir kuzuyu kurt kapsa, 

Kendini mes’ul tutar idi Ömerim.

Kuzuların, kurt olduğu bu çağda, 

Mecnun mecnun, aylak aylak gezerim.', 'Nerdesin, gecenin karanlığında,  Aydınlığı  aratmayan rehberim. Nerdesin, Gençliğin deli çağında,  Çiçeğimi saratmayan rehberim. Hani, dağda...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Dereci']::text[], 8.5, '{"poet":"Nizamettin Dereci","poet_slug":"nizamettin-dereci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nerdesin-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözleri Yakamozlu Kadın', 'gozleri-yakamozlu-kadin-ahmet-yetgin-74fc0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kocaman çocuk dövsen dövülmez

Sövsen sövülmeziydim ceviz ağaçlarının

Ve onlar topraktan böyle görmüşlerdi...

Yarın Istanbulda hava telli, duvaklıydı

Ve gözleri buluttu çeyiz sandığının

En kirli haliyle karşımda durur

Yalanlar söylerdi en beyazından

Sırf yaranmak için yapardı bunu

Yağmur gözlerinde deniz biriktirirken...

Fırtınalar kopardı akşamüstleri, ve ben

Kökleri toprağa sarılmış bir ceviz fidanıydım

Konstantiniyyeyi kandırali çok olmuştu ve Panama bandıralı

Şilepler öylece gelir, giderdi... ''Heey! 

Istanbula az kullanılmış liman aranıyooor...''

İskeleden yanaşırdı, gözlerinde yakamoz...

Bir ayağı suda hayaller giyinirdi

Haykırırdım: ''Sakın düşme! Boğulmak için erken''

Köpekler yüzerdi...

                          Ben yüzemezdim, -off! 

Deniz gözlerindeki yağmura imrenirken.

Kuştüyü tutardım pamuk ellerinden

Bir kuş yüreciğinden fışkıran bereket

Islatırdı kuruyan yerlerimi

Yağmur sonrası yakamozlu gözlerine

Güneşten martılar iniş izni isterdi

Aydınlanan toprak yürürdü sürgünlerime

Sıyrılırdım molozlarımdan bir bengisu kalırdım

Bir çift kanat ses verirdi denizin derinliklerinden

Çorak toprakları bırakırdık arkamızda

Deniz yangınlarını ve siren seslerini

Güneşin ülkesine doğru süzülürken', 'Kocaman çocuk dövsen dövülmez Sövsen sövülmeziydim ceviz ağaçlarının Ve onlar topraktan böyle görmüşlerdi... Yarın Istanbulda hava telli, du...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yetgin']::text[], 8.5, '{"poet":"Ahmet Yetgin","poet_slug":"ahmet-yetgin","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gozleri-yakamozlu-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Günler', 'guzel-gunler-hasan-huseyin-korkmazgil-0t226', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dalgındım dağlar gibi

Türkülüydüm çınar çınar

Ne kızarıp giden sarı

Ne kızarıp gelen yeşil

Dikilmiş dikmeninde 

Hoşçakal köprüsünün

Tam da mendil sallıyordum güzel günlere

Güzel günler güzel günler hey güzel günler

Gözlerinde gidenimin hey güzel günler

Güzel günler güzel günler hey güzel günler

Ellerinde gelenimin hey güzel günler

Balık attım olta tuttum

Yaşadım gençliğimi

Masal oldu çocukluğum

Gençliğim bahar seli

Ve bir akşam birdenbire 

Bir bulvar otelinde

İnce bir dal değdi alnıma

Koptu sazımın teli

Güzel günler güzel günler hey güzel günler

Gidenimin gözlerinde hey güzel günler

Güzel günler güzel günler hey güzel günler

Ellerinde gelenimin hey güzel günler

Güzel günler güzel günler hey güzel günler

Gözlerinde gidenimin hey güzel günler

Heey günler hey hey günler hey güzel günler

Ellerinde gelenimin hey güzel günler

Heey günler hey hey günler hey güzel günler

Gözlerinde gidenimin hey güzel günler...



 

Söz: Hasan Hüseyin Korkmazgil 

Müzik: Ahmet Kaya', 'Dalgındım dağlar gibi Türkülüydüm çınar çınar Ne kızarıp giden sarı Ne kızarıp gelen yeşil Dikilmiş dikmeninde  Hoşçakal köprüsünün Tam da m...', ARRAY['Türk Edebiyatı','Şiir','Hasan Hüseyin Korkmazgil']::text[], 8.5, '{"poet":"Hasan Hüseyin Korkmazgil","poet_slug":"hasan-huseyin-korkmazgil","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/guzel-gunler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ecel-1', 'ecel-1-mehmet-kursat-dos3z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ugruna yandıgım toprak 

Haydi beni al artık

Tehdidinden yok korkmak

Saracaksan sar artık

Egri kılıc kessin egilmez bası

Senden kacan senden vefasız olsun

Doldurmaya ne gerek var falanca yaşı

Gelde kurtar azap son bir bulsun

Düsün düsün dibi mi varsanki kuyunun

Arayanlar zannetme ki haklıdır

Ne tadı var ne  tuzu ömür suyunun

Bilmezler ki asıl tad sende saklıdır

Bıktım gayri durmaktan ondan beklemem 

Ha ilmek ha sehpa farksız sanma ha

Sana kosarken dahi rahat istemem

Sehpa kuş tüyünden rahat vallaha', 'Ugruna yandıgım toprak  Haydi beni al artık Tehdidinden yok korkmak Saracaksan sar artık Egri kılıc kessin egilmez bası Senden kacan senden ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Kürşat']::text[], 8.5, '{"poet":"Mehmet Kürşat","poet_slug":"mehmet-kursat","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ecel-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eteklerinin Rüzgarı', 'eteklerinin-ruzgari-oguzkan-bolukbasi-dbbov', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'uçuşurum eteklerinin rüzgarında saf değilim

bakarım endamına belki de eğilirim

dudakların bal desenli çatalı düğmelerine açık

tadını sanki bir ben bilirim güngörmemiş memelerinin

sarfınazar etsem de hayatın eyyamından

gelir bulursun beni deliler makamından

ey içi ateş dışı karlarla kaplı yanardağların kızı

patla yarıl ve çatla fırlat beni volkanından

tanıma kendini bende anlama kelimeler ne der

yaşamak sen olmasan söyle kaç  para eder

elimde kadeh dilimde ismin karşımda sarhoşlar

aşk bu mutluluk veriyor acı yerine keder', 'uçuşurum eteklerinin rüzgarında saf değilim bakarım endamına belki de eğilirim dudakların bal desenli çatalı düğmelerine açık tadını sanki b...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eteklerinin-ruzgari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün Olurda', 'bir-gun-olurda-nizamettin-dereci-tbwn1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bin ah işitirsin; gönlümü dinle.! 

Seni görmediğim, aylar aşkına.

Paylaşamam, seni, bilmem kiminle, 

Hayalinle geçen günler aşkına.

Bir gün olur da, seni bulursam, 

Gözümden, bir damla yaş, akmayacaktır.

Son bir kez göreyim, diye yüzüne, 

kuruyan gözlerim bakmayacaktır.', 'Bin ah işitirsin; gönlümü dinle.!  Seni görmediğim, aylar aşkına. Paylaşamam, seni, bilmem kiminle,  Hayalinle geçen günler aşkına. Bir gün ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Dereci']::text[], 8.5, '{"poet":"Nizamettin Dereci","poet_slug":"nizamettin-dereci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-gun-olurda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmuyor', 'olmuyor-nizamettin-dereci-sycz3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gün geçmez dertlerim, benle beraber

Alışsam olmuyor, bıraksam olmuyor.

Tanrım dertlerime biraz ara ver.

Güneşim tutuldu, gün ağarmıyor.

Sıra dağlar, ardı sıra dizildi.

Yürüsem olmuyor, bıraksam olmuyor.

Kötü talih, Ulu elde yazıldı.

Gün doğmadan yine akşam oluyor.

Sorsalar, hayatın günlük seyrini

Konuşsan olmuyor, sussan olmuyor.

Herkes, kendi çeker, kendi derdini.

Dertleşmeye bile zaman olmuyor.', 'Gün geçmez dertlerim, benle beraber Alışsam olmuyor, bıraksam olmuyor. Tanrım dertlerime biraz ara ver. Güneşim tutuldu, gün ağarmıyor. Sıra...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Dereci']::text[], 8.5, '{"poet":"Nizamettin Dereci","poet_slug":"nizamettin-dereci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olmuyor-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttum Artık', 'unuttum-artik-nizamettin-dereci-3v8rq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sesini özledim, bir de kokunu, 

Gözünün rengini, unuttum artık.

Sana hasretimin, gelmedi sonu, 

Yolumu, yönümü unuttum artık.

Bir rüyam var, seninle kavuşturan, 

Hayali, gerçeği, unuttum artık.

Buluştur, her şeyi buluşturan, 

Zamanı, zemini unuttum artık.', 'Bir sesini özledim, bir de kokunu,  Gözünün rengini, unuttum artık. Sana hasretimin, gelmedi sonu,  Yolumu, yönümü unuttum artık. Bir rüyam ...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Dereci']::text[], 8.5, '{"poet":"Nizamettin Dereci","poet_slug":"nizamettin-dereci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/unuttum-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düşmeye Gör', 'dusmeye-gor-nizamettin-dereci-4c1u9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşmeye görsün gözün, 

Düşmeye görsün başın.

Akraban değil sanki.! 

Ne kardeşin ne bacın

Düşmanı aratır dostlar, 

Onurun zan altında.

Sen dilenci olursun, 

Onlarsa kral tahtın da.

Tam zamanı değil mi.? 

Beş kuruş yardım ile.

Kendine kahrettirir, 

Ne özgürsün, ne köle.', 'Düşmeye görsün gözün,  Düşmeye görsün başın. Akraban değil sanki.!  Ne kardeşin ne bacın Düşmanı aratır dostlar,  Onurun zan altında. Sen di...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Dereci']::text[], 8.5, '{"poet":"Nizamettin Dereci","poet_slug":"nizamettin-dereci","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/dusmeye-gor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırık Teknem', 'kirik-teknem-nizamettin-dereci-zidhf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne kadar yalvardım, ulu Tanrıma, 

Al canımı diye, kurtulacağım.

Ya alıp beni de, götür yanına, 

Ya inan ki her an, çıldıracağım.

Bir hayat ki, ızdırap çemberinde, 

Izdıraplarınla barışacağım.

Fakat, dertlerimi, yalnız seninle, 

Senden başkasına, açmayacağım.

Sanki sır dolu alem, 

Öfke dolu insanlar.

Öfkenle, sevmeye alışacağım.

Akıntıya karşı, kırık teknemle, 

Sana varmak için, çalışacağım', 'Ne kadar yalvardım, ulu Tanrıma,  Al canımı diye, kurtulacağım. Ya alıp beni de, götür yanına,  Ya inan ki her an, çıldıracağım. Bir hayat k...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Dereci']::text[], 8.5, '{"poet":"Nizamettin Dereci","poet_slug":"nizamettin-dereci","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kirik-teknem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanma Ki', 'sanma-ki-nizamettin-dereci-krtee', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sanma ki, sensiz hayat, yürümeyecek.

Sanma ki, umutlarım, suya düşecek.

Senden sonra hayat, zor olsa bile, 

Sanma ki, gök yüzünden, taşlar düşecek.

Alın yazım, kader çizgim, 

Sensizlik söylüyorsa..

Sanmam ki, hayat, bizi birleştirecek.', 'Sanma ki, sensiz hayat, yürümeyecek. Sanma ki, umutlarım, suya düşecek. Senden sonra hayat, zor olsa bile,  Sanma ki, gök yüzünden, taşlar d...', ARRAY['Türk Edebiyatı','Şiir','Nizamettin Dereci']::text[], 8.5, '{"poet":"Nizamettin Dereci","poet_slug":"nizamettin-dereci","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sanma-ki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
