INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hırsız Bir Yalan', 'hirsiz-bir-yalan-orcun-oruc-aykac-i8hyh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İçimde hırsız bir yan

Dokunsam ağlar, dokunmasam çalar

Gölgemin bir yansımasıyım

Bedenim hırsız bir can.

Ulaşamıyorum kendime

Nereye gitsem bir ben, 

Baktığım yalan

Bakamadığım, göremediğim

Gölgemin içinde bir adam.

Aşk yormaz, 

Beni erişemediğim yorar

Bir erişemediğim gölgemde bir adam

Aşk benden uzak, ağzımda bir yalan.

Hırsızım ben, kendimi çalarım

Yalan söylerim kendimi bile aldatırım

Yalandan mı gelmez bu siyahlı adam? Bilmem...

Yalancıyım ben, hırsız bir yalan.

Dokunaklı bir sefalet öyküsü

Sefaletimin içinde bir yalan, 

Yalana kanan bir can

Ve gölgesini çalan bir adam...

Şubat 2002', 'İçimde hırsız bir yan Dokunsam ağlar, dokunmasam çalar Gölgemin bir yansımasıyım Bedenim hırsız bir can. Ulaşamıyorum kendime Nereye gitsem ...', ARRAY['Türk Edebiyatı','Şiir','Orçun Oruç Aykaç']::text[], 8.5, '{"poet":"Orçun Oruç Aykaç","poet_slug":"orcun-oruc-aykac","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hirsiz-bir-yalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sobe!', 'sobe-orcun-oruc-aykac-epnm2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sağım solum sobe

Kim yaşıyorsa o ebe

Ölenlerin oyunu bu

Kalanların ağıtından kime ne? 

Zaman kedere aşık

Ruhum sobelenmeye mahkum

Kalanların oyunu bu

Ölenlerden kime ne? 

Hangi merhamet yaşatıyor ölü vücutlarımızı? 

Hayatın rahminde nefes alamayan, 

Yaşamaya zincirlerle prangalanmış, 

Çığlıklarla fısıldaşan çocuklarız biz.

07.04.2002', 'Sağım solum sobe Kim yaşıyorsa o ebe Ölenlerin oyunu bu Kalanların ağıtından kime ne?  Zaman kedere aşık Ruhum sobelenmeye mahkum Kalanların...', ARRAY['Türk Edebiyatı','Şiir','Orçun Oruç Aykaç']::text[], 8.5, '{"poet":"Orçun Oruç Aykaç","poet_slug":"orcun-oruc-aykac","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sobe-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin Bir Gece Masalı', 'bin-bir-gece-masali-kaan-saygin-b9ika', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gönlümü dipsiz bir kuyuya salmışım.

Rüzgarın fısıldaştığı,

Bin bir gece masalıymışım.

Ruhumu yar kokulu güllere sattım.

Savrulmuş her parçası,

Yokluk neymiş anladım.

Sevdamı kalbimin Elif''basına yazdım.

Dört yanı kan boyalıyı,

Dünyaya sığmaz sanmışım.', 'Gönlümü dipsiz bir kuyuya salmışım. Rüzgarın fısıldaştığı, Bin bir gece masalıymışım. Ruhumu yar kokulu güllere sattım. Savrulmuş her parças...', ARRAY['Türk Edebiyatı','Şiir','Kaan Saygın']::text[], 8.5, '{"poet":"Kaan Saygın","poet_slug":"kaan-saygin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bin-bir-gece-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Platonik Aşk', 'platonik-ask-orcun-oruc-aykac-noi6n', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ok yaydan çıkmıştır bir kere

