INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakılabilir..', 'birakilabilir-yavuz-turhan-n1c1p', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevginin güzelliğini

derledik yüreklerimizde.

  En baştan çıkarıcı bakişlarımızı bileyip, 

gözlerimize sapladık.

  Delik deşik ettik  bedenlerimizi.

  Hoş sözler dökerken dillerimiz, 

dudaklarımıza, sevda şarkılarını değdirdik.

  Etrafımızı çevreleyen örtüyü, 

yırtıp savurduk.

  Gizlemedik çıplaklığımızı.

ruhlarımızın en yalın haliyle, sarılıp yatarken.

  Birden bire, yosun tuturduk aşkımızı.

  Denizin gelgitleri gibi, 

alışkanlığa dönüştürdük.

  Vazgeçilebilir veya yoksayılabilir.

  Bir sigara tiryakisinin, 

her zaman yinelediği gibi, 

  Bırakılabilir...

Bir alışkanlığa döndürdük aşkımızı....', 'Sevginin güzelliğini derledik yüreklerimizde.   En baştan çıkarıcı bakişlarımızı bileyip,  gözlerimize sapladık.   Delik deşik ettik  bedenl...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Turhan']::text[], 8.5, '{"poet":"Yavuz Turhan","poet_slug":"yavuz-turhan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/birakilabilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-akin-simsek-paqh0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ilık yaz akşamında

Ay ışığı altında

Bütün güzellikler karşımda

Eksik bir sen varsın yanımda

Böyle geçen gecelerde

Yaşıyorum sensizliği

Ankara bürünüyor benimle mateme

Sensiz geçen gecelerde

Biliyorum ben kadar yakınsın bana

Lakin yıldızlar kadar uzak

Uzakta olsa aydınlığı ulaşıyor bana

Tek tesellim resmin varlığın yanımda olmasa da

Gelsen bir an olsun yanıma

İşte o anı yaşamak var ya

Bir resmin bile yok karşımda

Gözlerimi kapatır seni hayal ederim

YALNIZLIĞIMLA', 'Ilık yaz akşamında Ay ışığı altında Bütün güzellikler karşımda Eksik bir sen varsın yanımda Böyle geçen gecelerde Yaşıyorum sensizliği Ankar...', ARRAY['Türk Edebiyatı','Şiir','Akın Şimşek']::text[], 8.5, '{"poet":"Akın Şimşek","poet_slug":"akin-simsek","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yalnizligim-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ucuz Sohret', 'ucuz-sohret-guner-kaymak-6dfi7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kalbim cok kiriliyor dariliyorum

Halk olarak une sana duskunuz

Sairine bakiyoruz siirine bakmadan

Reklama calima showa duskunuz

Kirik plak gibi hep basa aliyoruz

Her defasinda ayni sarkiyi caliyoruz

Geriden gelenin farkina varmiyoruz

Hep odunumuzun parasina duskunuz

Unlu sair yazmis gulmem geliyor

Yazdigi seyler ipe sapa gelmiyor

Tutturmus bir yerden asagiya inmiyor

Koru korune ovmeye ovulmeye duskunuz

Saire bak ceylanini daga kacirdi

Kacma ceylan seni vuramam diyor

Bizde sohret boyle ucuz gidiyor

Pit pazarindan satilan mala duskunuz

Amsterdam 11.03.2003', 'Kalbim cok kiriliyor dariliyorum Halk olarak une sana duskunuz Sairine bakiyoruz siirine bakmadan Reklama calima showa duskunuz Kirik plak g...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ucuz-sohret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'CONİ EVİNE DÖN', 'coni-evi-ne-don-ahmet-senkabak-vkahn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalbim

konuşlandırmıyor seni

haydi coni

evine dön

at elindeki baltaları

.....

Suları aşıpta geldin

elinde balta

hoş gelmedin

sefa gelmedin

Ne Nagazaki

Ne Hiroşima

Ne de Vietnam

affetmedi ki

balta veren elleri

.......

Kalbim

konuşlandırmıyor seni

haydi coni

evine dön

at elindeki baltaları

......

Çocuk ölülerinden boru yap

kadınlardan vana

gencecik tüysüz oğlanlardan

elektronik kumandalı pompa...

çalıştır...

              haydi akıt cebine

              kahrolası petrolü

......

Kalbim

konuşlandırmıyor seni

haydi coni

evine dön

at elindeki baltaları

.....

Barıştan ilaç yapın

şırınga edin coninin

             kalbine

tedavisi mümkündür

            kimbilir.....

insanlık tanıyı koydu coktan

         ''SAVAŞMA''

........

Kalbim

konuşlandırmıyor seni

haydi coni

evine dön

at elindeki baltaları

ŞİİRE ANNEMİN NOTU; 

annem sana cok kızıyor sam amca

''uydu sinyalli füzelerin

ajanların

casus uçakların

ve bilmem ne bela

baltaların

başında paralanır''

diyor......', 'Kalbim konuşlandırmıyor seni haydi coni evine dön at elindeki baltaları ..... Suları aşıpta geldin elinde balta hoş gelmedin sefa gelmedin N...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şenkabak']::text[], 8.5, '{"poet":"Ahmet Şenkabak","poet_slug":"ahmet-senkabak","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/coni-evine-don-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEMLEKET TÜRKÜSÜ', 'memleket-turkusu-ali-capan-3jyel', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1.

UZUN ÇARŞI

İşte Gaziantep’tesin sokaklardan bir sokak

Çarşılardan bir çarşı adı ‘’Uzun Çarşı’’

Karagöz Camisini sağına al ve yürü

Biraz sonra kendini ‘’Uzun Çarşı’’nın

Ortasında bulacaksın.

Yirmi beş Aralık’ta o soğuk kış günü

Üşüyen ellerinden öpüp soracak olursan

Gözleri çakmak, çakmak gülümseyen

Yaşlı gazilerden birine

Öyküsünü anlatır sana ‘’Uzun Çarşı’nın

Gaziantep’in

Şehit Şahin Beyin ve işgalin.

Uzun çarşıda sağına soluna bakınarak yürürsen

Üç tane Han göreceksin

-Bir zamanlar bu handa kimler konakladı acaba

diye soracak birini bulamazsın

Ama Pazar yerini geçer geçmez

Kale’nin Güney Burcu ‘nu

Karşında göreceksin.

Yoruldunsa

Gel birlikte oturalım Havuzlukahve’ye

İyi kaynamış yarım fincan kahveyi yudumla ve

Söyle getirsinler hazır duran nargileyi

Keçehane yokuşundan aşağı

Hiç yorulmadan ineceksin.

2.

BAKIRCILAR ÇARŞISI

Bakırcılar çarşısında çekiç sesleri

El ele tutuşmuş koşuşan

Çocukların seslerine karışıyor.

Buğday pazarındaki kahvede

Alışverişi bitirenler yudumlarken çaylarını

Barak türkülerinde yanık bir ezgi uçuşuyor: 

‘’Ezo gelin benim olsaydın

Seni vermezdim feleğe”...

Marangoz İhsan usta çeyiz sandığının

Son çivisini çakıyor.

Aynalı dolaplar dizilmiş yan yana

Birbirine bakıp, bakıp gülümsüyor.

Demirci örsünde tavlanmış demir

Nar gibi duruyor.

Zincirli camiinin önünde

İki yaşlı kadın ve üç çocuk

Cuma namazından çıkacakların vereceği

Sadakayı bekliyor.

Kolonyacı tozunu almış şişelerin ve tezgahın

Hasta görmeye gidecekler gelsin de

Kolonya satayım diyor.

Şerbetçi şıngır, şıngır şıngırdatarak 

Vurdukça iki küçük bakır tası birbirine

Susadığım aklıma geliyor.

3.

KUYUMCULAR ÇARŞISI

Kuyumcular çarşısında altın ve gümüşün parıltısı

Sırt sırta vermiş bankaların

Yükselen faizine göz kırpıyor.

Kaldırımda kol kola yürüyen delikanlı ve genç kız

Kuracakları sım sıcak yuvanın hayaliyle sarhoş

Şarkı söyler gibi konuşup gülümsüyor.

Hüseyin Paşa Camisinin minaresinden müezzin

Müslümanları Cuma namazına çağırıyor

Kunduracı Sami usta iş önlüğünü usulca çözdü

Emekli nüfus memuru Mehmet efendi

Arzuhali yazdı bitirdi

Gözlüğünün camını temizledi ve yürüdü.

Lastik tekerlekli el arabasını

Köşeye yerleştiren satıcı

Elindeki bezle parlatıyor elmaları

Üst üste yan yana özenle diziyor.

Belediyenin temizlik işçileri ellerinde aletleri

Yollara dökülmesin diye yaprakları

Ağaçların dallarını kesiyor.

Dalsız yapraksız ağaca kuş konar mı hiç

Onlar da telgrafın tellerine konuyor.

4.

KIKAYAK SAZ BAHÇESİ

İşte yirminci yüzyılın sonunda

Gaziantep’tesin.

Kibrit kutularını üst üste dizmişler sanki

Basık tavanlı

Az ışıklı apartmanlar yükseliyor

Eski Antep evlerinin yerinde.

...Bir zamanlar Kırkayak Saz Bahçesinde

yaşlı çınar ağaçlarının serin gölgesinde

batan güneşe karşı

oturur  dinlenirdik.

Ud’la Hicaz Peşrevi

Sonra geçiş taksimi tamburla

Hacı Arif Bey’den bir şarkı

Ve yorgunluk gideren rakı...

Birer, birer kesilen dut ağaçlarının

Kaldırımlarda uyuyakalmış gölgesi

Ayak izleri kol kola yürüyen aşıkların

Ve geçmişi  geleceğe taşıyan

Şarkılardan artakalan

Hamiyet Yüceses‘in 

Kulaklarımda çınlayan sesi; 

‘’Bakmıyor çeşmi siyah feryada ‘’...', '1. UZUN ÇARŞI İşte Gaziantep’tesin sokaklardan bir sokak Çarşılardan bir çarşı adı ‘’Uzun Çarşı’’ Karagöz Camisini sağına al ve yürü Biraz s...', ARRAY['Türk Edebiyatı','Şiir','Ali Çapan']::text[], 8.5, '{"poet":"Ali Çapan","poet_slug":"ali-capan","theme":"Türk Şiiri","is_hero":false,"total_lines":100,"source_url":"https://www.antoloji.com/memleket-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İZMİRNAME', 'i-zmi-rname-ali-capan-tlj7r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '1.

YOLCULUĞA BAŞLAMADAN

Siz benim aydınlığıma

Günaydın bile demeden

Birden bire bir kuş sürüsü

Çığlık çığlığa

Büyüyen yalnızlığımı

Çoğaltmak için mi geldiniz yoksa, 

-Seni seviyorum, diye başlayan

Bir şarkının 

Don hecesi miyim ben.

Daha dün öptünüz gözlerimden

Bu gün merdiven başında durup 

El sallamak yerine 

-Gitme, diyebilirdiniz oysa.

Siz mendillerimi dörde katlayıp

Yerleştiriyorsunuz ha bire

Benim ayrılıkları sevmediğimi

Bildiğiniz halde bavuluma

Çoraplarımı bir, bir

Gömleklerimi ve sigaramı 

Daha sonra kravatımı

Tıraş makinemi, havlumu.

Bir avuç hüzün yeter diyorum

Fazlasına dayanamam

Bir otobüs bileti yeter.

Balkondaki çiçeklere su ver

Kurumasınlar

Oğluma ninni söyle uyusun

Uyandığımda geleceğimi söyle

Sakın ağlamasınlar.











2.

OĞLUM MUSTAFA SERMEST UYANSIN DA

Bu sabah uyandım sokaklar bomboş

Ne sütçü geçmiş daha ne çöpçü

Hiç birinin yok ayak izi.

Balkona açılan pencereye

Tırmanırken yakaladım güneşi.

Birazdan oğlum gözünü açınca 

Bana gülümseyecek

O bilmiyor daha ayrılıkları

Hasreti ve sevinci

Ama öğrenecek.

Durdurabilseydim zamanı

Ve gidebilseydim çocukluğuma

Yeniden yaşayabilseydim

Geçip giden otuz üç yılını ömrümün 

Bu şiirleri yeniden yazardım

Bir başka biçimde 

Ve nasıl sever insan sevince

Nasıl özler 

Daha yola çıkmadan 

Bilirdim o zaman.



3.

ALLAHA ISMARLADIK

DİYE 

ÖPSEM GÖZLERİNDEN

Bir bardak çay içsem

Bir dilim ekmek üç beş zeytin

Çabuk, çabuk bağlasam

Ayakkabımın bağcığını

Ve Allahaısmarladık diye

Öpsem gözlerimden

On otuza yetişebilsem

Gideceğim İzmir’e

Ama dönüşü daha güzel olacak

Bu gidişin.

4.

DUR GİTME DİYEBİLİRDİN

Dur gitme diyebilirdin

Bizi böyle bırakıp gitme

Bak akşam yemeğini balkona hazırladım

Çorbamız yeni pişti daha

Çatal bıçak peçete hepsi hazır masada

Buz çıkardım dolaptan

Kavun kestim

Peynirimiz yok ama

İşte karpuz işte rakı

Haydi otur artık sandalyene

Çocuklar neredeyse gelir

Hep bir ağızdan söyleyelim mutluluk

Şarkımızı

Diyebilirdin.

5.

AVUÇ İÇİ KADAR GÖZYÜZÜ

İzmir’le bir gece yarısı aniden

Basmane de bir otelin kapısında tanıştım

Uyku gözümden akıyor

Bir şişe soğuk su

Son damlasına kadar içtim

Sigaram ha bire sönüyor

Tek kişilik otel odasının penceresinden

Avuç içi kadar gökyüzü görünüyordu

Renk, renk ışıklar

Yanıp, yanıp sönüyordu

Gökyüzünde yıldızlar

Durmadan göz kırpıyordu

Yastığa nasıl koydumsa başımı

Uyumuşum

Düşümde sevgilim beni çağırıyordu.

6.

GÜNEŞ KÖRFEZDE BOĞULURKEN

Bir başlarsa bitmek bilmiyor yolculuk

Bir yerden bir yere yürüdükçe yoruluyorum

/Yaşlandım mı yoksa/

Yoruldukça terliyorum

Terledikçe üşüyorum ve öksürüyorum

Ayakkabılarımı çıkarıp elime alsam diyorum

İzmirliler bana bakıp güler mi acaba 

Şimdi Karşıyaka ve Kordonboyu

Ve ben yalnızız

Yapayalnız/yürüsem/

Güneş körfezde boğulurken 

Ve ay yusyuvarlak

Bana gülümserken.

Yanı başımda gülümseyerek geçiyor bir kız

On sekiz yaşın sevincini

Arkadaşıyla paylaşan

Ve biz /Körfezde boğulan güneş ve ay/

Yalnızız.

Otobüse yetişmek için koşuşuyor

Bazı insanlar

Selamlaşarak gülümseyerek birbirine

Vapurdan iniyor bir kadın

Elinden tutmuş çocuğunun

/Yürümesinden belli ki hamile/

Kucağında eşyalar.

Geçip giden zamana karşı gelmek zor

Yeşil gözlerini

Benden kaçırıp

Akşam rüzgarının serinliğiyle 

Dağılan sarı saçlarını

Topladıktan sonra

Ağız dolusu gülebilmek

/Ve mutlu olabilmek/Güzel.



7/

BİRAZDAN İZMİR DE AKŞAM OLACAK

Bir özlem büyütüyorum şimdi yüreğimde

Karpuzu soğuk suya attım

Çatladı çatlayacak

Buzlu rakı buğulanıyor bardakta

Sigaram sönmek üzere.

Ben hiçbir şarkıyı 

Baştan sona söylemesini bilmem

Her şarkıda üç beş dize

O da -Seni seviyorum

Diye başlarsa.

Şimdi bir rüzgar patlayacak biliyorum

Denizi dalga, dalga getirecek

Vuracak olanca gücüyle kayalıklara

Paramparça olsun

Tuz buz olsun dağılsın diye.

Birazdan akşam olacak

Güneş dağların arkasına gizleniyor

Ormanda bir yangın başlayacak birazdan.

Bir nefes daha çekeyim

Bu serin gökyüzünden

Doldurayım ciğerlerimi alabildiğince.

Birazdan yağmur yağacak

Bulutlar koşuşuyor çünkü

Şemsiyem yok ıslanacağım

/Hem sırılsıklam/

İliklerim üşüyecek

Dudaklarım mosmor olacak

Ve seni düşüneceğim sevgilim

/İçimi ısıtan gülücüklerin 

Gelecek gözlerimin önüne/

Sevineceğim.

8.

KADİFEKALE’DEN

Kadifekale’den kuş bakışı seyrettim İzmir’i dün

Konak meydanı cayır, cayır yanıyordu

Talatpaşa bulvarına bakan penceresine 

Oturmuş yeşil gözlü bir kız

Elinde tarak durmadan saçını tarıyordu.

Kordonboyu’nda yürüdüm

Yalnızlığımı duya duya

Körfez leş gibi kokuyordu

Ilık, ılık esen imbat

Öpülmeye hasret kalmış

Yanağımı okşuyordu.

.../Bir dizini toprağa dayamış

Gazeteci Hasan Tahsin

Bir elinde 

İlk kurşunu sıktığı tabancası

Bir elinde

Bayrak dalgalanıyordu/...

Ben hep yalnızlığımı büyütüyorum

Saat kulesindeki saat altıyı vuruyor

Güvercinlerin biri konup biri uçuyor

Vapur düdüklerinin seni getirmeyeceğini

Bile, bile bekliyorum

Şu karşıdan gelen 

Sen değilsin biliyorum.

Seni düşündükçe dilim dudağım kuruyor.

Senden uzaktayım yine bu gün

Güneş batmak üzere

Akşam oluyor.

9.

KİBARİYE

Koşun, koşun denizi öldürüyorlar

Bakın çırpınıyor kurtulmak için

Hepsinin elinde birer kanlı bıçak

İzmirliler denizi öldürüyor.

Siz körfezi vapurla geçtiniz mi hiç

Karşıyakaya gittiniz mi

/Yürüdünüz mü Kordonboyu’unda/

Bu nasıl türkü söylemek böyle

Batan güneşe bakarak

Palmiyeler utancından eğmiş yüzünü

Öbür ağaçlar almış başını

Gitmiş İzmir’den

Neden.

Denizi öldürüyorlar.

Halbuki 

Doldursan denizi

Kocaman bir çamaşır leğenine

Boşaltan bir kutu çamaşır tozunu

Otursan başına

Ha bire yıkasan, yıkasan.

Sonra sereceksin bir uzun ipe boydan boya

Tutturdun mu düşmesin diye

Üç beş yerinden

Çamaşır mandalıyla

Bırak kurusun

Bak o zaman sen

Tertemiz 

Ap/ak/duru/pırıl-pırıl/aydınlık.

İstersen şarkı da söyleyebilirsin artık

Kim bilir.

10.

ONYEDİ EYLÜL PERŞEMBE

AYVALIKTA

O güzelim yazdan güneşli bir günü

Ödünç almıştı Eylül

Ayvalıkta ayvalar dalında sararıyordu

Ben incecik bir kuma yüzükoyun uzandım yattım.

Güneş kemiklerimi ısıtıyordu

Denizde küçük dalgaların hışırtısı

Kurumaya yüz tutmuş kavak ağaçlarının 

Birbirine söylediği şarkıyı anımsatıyordu.

/Yumdum gözümü ve uzaklara gittim

Çok uzaklarda beni bekleyen sevgilim

Beni karşısında görse aniden

Boynuma sarılır/

Oysa karşıda Midilli adası görünüyor

Bırakınca kendimi

Soğuk suların Kucağına

Üşüdüğümü anlıyorum

Ve uzakta olduğumu sevgilimden

/Kilometrelerce/

Ancak telefonda duydum gülüşünü de

Öyle ısındı içim

11.

BENİ ANLIYOR MUSUN

Sevgilim 

Seni elinden tutup

Bu şiirin baş köşesine

Oturtmak için çağırıyorum

Sesimi duyuyor musun? 

Bu şiirde dağılan saçlarını toplarken gülen

Ve durmadan tarayan

Yeşil gözlü o İzmir’li kız yok.

Günlerdir yüreğimde büyüttüğüm özlemimi

Haykırmak

Seni kucaklamak için çağırıyorum

Beni duyuyor musun? 

Dönme dolapta dönmüş gibiyim

Bir şişe rakıyı tek başıma içmiş gibiyim

Şarkılar söyleyip coşmak istiyorum

Şu dağları tek, tek aşıp

Sana giden yollarda koşmak istiyorum

Beni anlıyor musun? 

12.

BU AKŞAM YİNE SENDEN UZAKTA

Bu akşam yine senden uzakta

Yine yapayalnızım.

Tek arkadaşım

Ben yaktıkça sönen o berbat sigaram

Ve yazdan artakalan

Bu güneşli Eylül gününün sonunda

O mürekkep mavisi Eğe Denizi’ni seyrederken

Yudumladığım rakı.

Mırıldandığım şarkıları

Birbirine düğümleyecek

Kimse yok yanımda

Sen yoksun.

Bu akşam yine senden uzakta yine yapayalnızım.

Güneşi boğdu deniz.

O en çok sevdiğim

Martılar bile beni böyle hüzünlü/tek başıma/

Bırakıp gittiler.

Balıkçı tekneleri bir, bir dönüyorsa

Sustur artık şarkıları

Söylemesinler ayrılığın/hasretin

Buruk şarkısını

Olmaz mı? 

13.

BU ŞİİR SENİNLE DOLU

HER DİZESİNDE SEN VARSIN

Bu şiirde

Bavulum var./içinde giysilerim

Ve diğer eşyalar/

Her sabah gözünü açınca bize gülümseyen

Oğlumuz var –Mustafa Sermest-

Gökyüzü ve deniz var.

Yolculuğun başlangıcı –yani ayrılık-

Ve sen varsın herşeyden önce

Ve veda busesi.

İzmir kıyısından köşesinden girdi bu şiire

Nasıl olduysa

Çık git diyemezsin ki

Martılar uçup gittiği için

Onları koymayacaktım bu şiire ama

Dayanamadım

O masmavi denizi buyur edince

Arkadaş olsun diye bana

Martıları da çağırdım.', '1. YOLCULUĞA BAŞLAMADAN Siz benim aydınlığıma Günaydın bile demeden Birden bire bir kuş sürüsü Çığlık çığlığa Büyüyen yalnızlığımı Çoğaltmak...', ARRAY['Türk Edebiyatı','Şiir','Ali Çapan']::text[], 8.5, '{"poet":"Ali Çapan","poet_slug":"ali-capan","theme":"Türk Şiiri","is_hero":false,"total_lines":318,"source_url":"https://www.antoloji.com/izmirname-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pervaz', 'pervaz-deniz-altan-o8w17', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Senin için yazılan bir şiir yok...

Arama boşuna…

Kitaplar bahsetmiyor bizden…

Biz de bahsetmiyoruz…

Titreyen parmaklarımın seni yazmaya korkması gibi

Unutmuş taklidi yapıyoruz

Hatırlamama oyunları

Tek perdelik tek kişilik oyunlar

Herkes kendini söylüyor, öteki saydam…

Tüm camları kırmalı diyorum… 

Kuşları öldüremesinler artık…

Tam da çıkmak isterken dışarı, 

Tam da dönmek isterken evine...

Bir pencere pervazında beyin travması geçirmiş bir muhabbet kuşu cesedi

Ölüm sebebi fazlasıyla muhabbet

Öngörülemeyen konuşmalar sonrası intihar...

Kırılmış bir boyun kanamış bir kalp nefessiz bir ciğer

Gökyüzünden uzak durmalı

Saydam tuzaklarını boşa çıkarmalı hayatın...

Yavaş uçmalı, yavaş koşmalı, yada bir parça kan kalmalı her tuzakta...

Bir sonrakini uyarmak için...

Oysa boş durmuyor temizlik şirketleri 

Kadınlar pencerelerden her Pazartesi

Yağmurun kan izlerini siliyor 

Bir sonraki kurbanlarına hazırlıyorlar sahneyi

Ve hızla yaklaşıyoruz salıyı beklemeden

Akşam üstü kızıllığında pazartesinin

Daha bir kızıla boyuyoruz yüreğini ev sahibinin

Çatlaklardan akan kan, cama vuran kuşların tok sesi

Pervazdaki bu kez ben miyim sen mi?', 'Senin için yazılan bir şiir yok... Arama boşuna… Kitaplar bahsetmiyor bizden… Biz de bahsetmiyoruz… Titreyen parmaklarımın seni yazmaya kork...', ARRAY['Türk Edebiyatı','Şiir','Deniz Altan']::text[], 8.5, '{"poet":"Deniz Altan","poet_slug":"deniz-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/pervaz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık', 'yalnizlik-tuncay-kahraman-bwn6e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ne zaman yalnız kalsam, 

her şey bana düşman oluyor.

sesler yabancılaşıyor sanki, 

hiçbir şey neşe vermiyor.

geceleyin uyutmuyor kâbuslar, 

 kötü ruhlar varmışcasına peşimde.

kalabalığın içindeyken ve savaşırken hayatla hissetmediğim kötülük, 

yalnız kalınca mahvediyor beni, 

dibe vuruyorum iyiden iyiye.

ne zaman yalnız kalsam, 

sanki dünya değilmiş gibi geliyor yaşadığım yer.

hücrelerin en karanlığındayım ve bir gardiyan bile yok.

hayatın ciddiliğini farkediyoırum sanki, 

sanki benimle ilk kez ciddi ciddi  konuşuyor, 

kalabalıklar arasındaki şamatalardan sonra.', 'ne zaman yalnız kalsam,  her şey bana düşman oluyor. sesler yabancılaşıyor sanki,  hiçbir şey neşe vermiyor. geceleyin uyutmuyor kâbuslar,  ...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Kahraman']::text[], 8.5, '{"poet":"Tuncay Kahraman","poet_slug":"tuncay-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yalnizlik-98-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecedeki Yalnız Ağaç', 'gecedeki-yalniz-agac-tuncay-kahraman-gak73', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gece gibi, 

unutulmuş ve yalnızlığının sebebi hiç sorulmamış, 

akışı hissedilmemiş yıllardır.

çölün ve sessizliğin içinde: 

''Hiç konuşmaz ölen toprak, 

ayaklarım hiç yürümez, 

ölümleri hep duyarım, 

karanlık caddelerdeki, 

New York''ta, Paris''te, Londra''da...

yumrukları hissederim, 

...ve öfkeyi...

Bulutlara tekrar baktım, 

Bir ağustos gecesinde

tekrar gördüm o güzelliği, 

tekrar mutlu olabildim

ve sordum hepinize, 

Bu suçları kim işledi? 

Ahh... Bedenlerde hırs varmış, 

umut varmış ruhlarda.

Yaşayın ama unutmayın, 

Bu nefretle kararmış dünyada 

Bahçelerde çiçek varken, 

ölüm vardır bu çöllerde, 

Su gibi sıradan akar zaman.

Unutmayın sessizliği, 

Karanlık onunla ısınır, 

Ilık tatlılığını verir bana

ve kucağında avutur.', 'Gece gibi,  unutulmuş ve yalnızlığının sebebi hiç sorulmamış,  akışı hissedilmemiş yıllardır. çölün ve sessizliğin içinde:  ''Hiç konuşmaz öl...', ARRAY['Türk Edebiyatı','Şiir','Tuncay Kahraman']::text[], 8.5, '{"poet":"Tuncay Kahraman","poet_slug":"tuncay-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gecedeki-yalniz-agac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkizler', 'i-kizler-arif-nihat-asya-bjwcf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biz böyle bir gün için gelişmiş ikizleriz; 

Boyundan öpme çürür, öpülecek bizleriz...', 'Biz böyle bir gün için gelişmiş ikizleriz;  Boyundan öpme çürür, öpülecek bizleriz......', ARRAY['Türk Edebiyatı','Şiir','Arif Nihat Asya']::text[], 8.5, '{"poet":"Arif Nihat Asya","poet_slug":"arif-nihat-asya","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ikizler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Leke', 'leke-deniz-altan-8u9wu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Temmuz gecelerinin intikam sıcağında

küflenmiş bir yüreğin darmadağın sokaklarında 

terkedilmiş

öfkeli

eski bir koltuk gibi

lekeler içinde...

lekeler içimde...', 'Temmuz gecelerinin intikam sıcağında küflenmiş bir yüreğin darmadağın sokaklarında  terkedilmiş öfkeli eski bir koltuk gibi lekeler içinde.....', ARRAY['Türk Edebiyatı','Şiir','Deniz Altan']::text[], 8.5, '{"poet":"Deniz Altan","poet_slug":"deniz-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/leke-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönderi Mesajı', 'gonderi-mesaji-enis-batur-4d1pg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seyrek başdaşlar, 

hayatta ve / ya tefekkürde (âdemoğlu şiirde yalnızdır) : 

Krisis bir sözcük değil. 

Birinin içind
..........
..........', 'Seyrek başdaşlar,  hayatta ve / ya tefekkürde (âdemoğlu şiirde yalnızdır) :  Krisis bir sözcük değil.  Birinin içind .......... .............', ARRAY['Türk Edebiyatı','Şiir','Enis Batur']::text[], 8.5, '{"poet":"Enis Batur","poet_slug":"enis-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gonderi-mesaji-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Işığı', 'gun-isigi-ozgur-enguzel-3zxf1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'zihnimin,

güneşli bir gününde

yaşama baktım.

geceye dönmüş 

ardıma da...

birde 

kendime baktım.

sonra

gün ortasında! 

soyunmuş sevgim

çıplak ellerimle

çıkarabilmek için 

derinliklerinden sevgini.

düşünmeden kararsızlığını

göz kapaklarının 

atladım...

uçurumun

ölüm yüksekliğinden.

sevginin 

gözlerindeki denizine.

10/12/2002

Özgür ENGÜZEL', 'zihnimin, güneşli bir gününde yaşama baktım. geceye dönmüş  ardıma da... birde  kendime baktım. sonra gün ortasında!  soyunmuş sevgim çıplak...', ARRAY['Türk Edebiyatı','Şiir','Özgür Engüzel']::text[], 8.5, '{"poet":"Özgür Engüzel","poet_slug":"ozgur-enguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gun-isigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor durum', 'zor-durum-riza-aslan-8ghux', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'en zor durumlardan

biri olsa gerek

benliğe sinen çelişkiler', 'en zor durumlardan biri olsa gerek benliğe sinen çelişkiler...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/zor-durum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kim Özgür!', 'kim-ozgur-ozgur-enguzel-zbnpz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yalnızlığındı,

sevdiğini sandığın.

sözlerinin arkasına 

gizlendiğin.

Korkularındı,

beni

yaşama esir ettiğin.

susturulmuş 

sevgisiyle

yüreğine sürgülediğin

gözlerinin ardındaki çocuğu 

esir eden.

09/1/2003

Özgür ENGÜZEL', 'yalnızlığındı, sevdiğini sandığın. sözlerinin arkasına  gizlendiğin. Korkularındı, beni yaşama esir ettiğin. susturulmuş  sevgisiyle yüreğin...', ARRAY['Türk Edebiyatı','Şiir','Özgür Engüzel']::text[], 8.5, '{"poet":"Özgür Engüzel","poet_slug":"ozgur-enguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kim-ozgur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acılar Denizi', 'acilar-denizi-ozgur-enguzel-zrhbs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'nasıl bulacağım? 

onca giysinin arasında

kokunu, sesini bilmediğim.

yüzünü göremediğim

yüreğini göremediğim 

seni...

kırmızı göğün 

yağmuru altında.

karanlığın

gecesine kalmış umudumla

umutsuzluğun 

bilmediğim sona

durmamacasına kürek çektiği.

tüm insanların

kaptanı olduğu

bu ölüm gemisinde...

tanıdım seni. 

gözlerin çıplaktı! 

11/1/2003', 'nasıl bulacağım?  onca giysinin arasında kokunu, sesini bilmediğim. yüzünü göremediğim yüreğini göremediğim  seni... kırmızı göğün  yağmuru ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Engüzel']::text[], 8.5, '{"poet":"Özgür Engüzel","poet_slug":"ozgur-enguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/acilar-denizi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tahterevalli', 'tahterevalli-riza-aslan-p7th4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'tahterevallinin

bir ucunda ben

öbür ucunda

diğer ben

ortasında ise

yine ben

bundandır ki

bir aşağıda

bir yukarıda

o, dengenin hiç olmadığı

o, ölü noktada

aslında kaybedenimdir

ben...

Rıza Aslan

11 -  Mart 2003

Bergama / İZMİR', 'tahterevallinin bir ucunda ben öbür ucunda diğer ben ortasında ise yine ben bundandır ki bir aşağıda bir yukarıda o, dengenin hiç olmadığı o...', ARRAY['Türk Edebiyatı','Şiir','Rıza Aslan']::text[], 8.5, '{"poet":"Rıza Aslan","poet_slug":"riza-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tahterevalli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanımak!', 'tanimak-ozgur-enguzel-5k5x2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bilmezdim.

Yaşamın bunca güzel olduğunu.

önce,

kaç ömür sürdüğünü 

bilmediğim.

kırmızılığı durdu.

sonrada yağmur.

güneş doğdu 

umutlarıma.

göğü gördüm

maviydi.

aynaya baktım

korkularım dağıldı.

kendimi

yüreğimdeki çocuğu.

gördüm.

geçmişin sevgisizliğinde 

yitip giderken 

sen ve sesinin gerçeğiyle

sevginle varolmanın sevinciyle...

çığlık çığlığa bağırıyordu.

ve bilmeden

sensiz, sevginle dolu

bir boş sonsuzluğa 

varolduğunu...

10/12/2002

Özgür ENGÜZEL', 'Bilmezdim. Yaşamın bunca güzel olduğunu. önce, kaç ömür sürdüğünü  bilmediğim. kırmızılığı durdu. sonrada yağmur. güneş doğdu  umutlarıma. g...', ARRAY['Türk Edebiyatı','Şiir','Özgür Engüzel']::text[], 8.5, '{"poet":"Özgür Engüzel","poet_slug":"ozgur-enguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/tanimak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YaŞaMaK', 'yasamak-ozgur-enguzel-80b6y', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bilir misin? 

yaşaması 

ne acı bir duygudur; 

bilincime doğurduğun.

çaresizliğinden, 

iyi niyetinden faydalanmışlığımla

sana

“SENİ SEVİYORUM” diyememek.

ve

utanmak.

kendime söylerken

seni sevdiğimi.

10/12/2002', 'bilir misin?  yaşaması  ne acı bir duygudur;  bilincime doğurduğun. çaresizliğinden,  iyi niyetinden faydalanmışlığımla sana “SENİ SEVİYORUM...', ARRAY['Türk Edebiyatı','Şiir','Özgür Engüzel']::text[], 8.5, '{"poet":"Özgür Engüzel","poet_slug":"ozgur-enguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yasamak-49-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Başıma', 'bir-basima-ozgur-enguzel-99t07', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '16  yaşımda

yüklendim de umutlarımı

bindim...

bilinmezlik trenine.

27 yaşımda

henüz rayların üzerinde

durdu.

kaybolmuşluğun

gözyaşlarına boğulmuş

bir çocuğun çaresizliğiyle...

nereye gideceğini 

bulamayan.

18/12/2002

Özgür ENGÜZEL', '16  yaşımda yüklendim de umutlarımı bindim... bilinmezlik trenine. 27 yaşımda henüz rayların üzerinde durdu. kaybolmuşluğun gözyaşlarına boğ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Engüzel']::text[], 8.5, '{"poet":"Özgür Engüzel","poet_slug":"ozgur-enguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-basima-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız', 'zamansiz-ozgur-enguzel-0w9ya', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'kimsesizin zaferiyle,

şimdi bana kalan.

birkaç andan başka

birkaç anın devamsızlığıyla

yaşamdan uzaklaştırılmış

bir beden bir de aşk, 

yaşanmamış...

ve

yaşanmamışlığını yaşamak.

şimdi bana kalan! 

yitirilmiş zamanların

eksitilmiş yarınları...

26/12/2002

Özgür ENGÜZEL', 'kimsesizin zaferiyle, şimdi bana kalan. birkaç andan başka birkaç anın devamsızlığıyla yaşamdan uzaklaştırılmış bir beden bir de aşk,  yaşan...', ARRAY['Türk Edebiyatı','Şiir','Özgür Engüzel']::text[], 8.5, '{"poet":"Özgür Engüzel","poet_slug":"ozgur-enguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zamansiz-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SuSKuN', 'suskun-ozgur-enguzel-v4qox', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sen sustukça, 

canımın telleri çalınır.

yalnızlığın

akşam yamaçlarında.

gün doğmaz 

sen sustukça.

geceler kalır 

suskunluğunla...

13/12/2002', 'sen sustukça,  canımın telleri çalınır. yalnızlığın akşam yamaçlarında. gün doğmaz  sen sustukça. geceler kalır  suskunluğunla... 13/12/2002...', ARRAY['Türk Edebiyatı','Şiir','Özgür Engüzel']::text[], 8.5, '{"poet":"Özgür Engüzel","poet_slug":"ozgur-enguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/suskun-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-ozgur-enguzel-deb1i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'dökülüyorsa yaprakları

ağaçların

tekrar doğacaklarını bilmeden.

haykırıyorsa gök

bulut hüznü, ıslatırcasına 

yağdırıyorsa üstüne.

ırmaklar 

taşarcasına akıyorsa.

sakinliğine aldandığın

deniz.

birden kuduruyorsa

coşkuyla...

çaresiz eriyorsa

kış boyu 

yüreğimize yağan kar.

yeniden, ve 

yeniden açıyorsa 

tüm çiçekler 

sevinçle.

uçuyorsa bir kuş

varlığının kanat sesiyle.

bir martı

bıkmadan usanmadan

tekrar kere 

boş gagasıyla çıkıyorsa

denizden.

gökyüzüne baktığında

oluyorsa gece

koynuna alıp 

kamçılıyorsa acılarını.

ve güneş,

doğuyorsa inatla

asıyorsa günü boynuna.

üzme beni...

kendini ve çevreni

görebiliyorsan tüm bunları

yada hissedebiliyorsan! 

umut seninledir.

henüz terk etmemiştir.

unutma! 

umut 

soluk alabildiğin süreçtedir...

30/12/2002

Özgür ENGÜZEL', 'dökülüyorsa yaprakları ağaçların tekrar doğacaklarını bilmeden. haykırıyorsa gök bulut hüznü, ıslatırcasına  yağdırıyorsa üstüne. ırmaklar  ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Engüzel']::text[], 8.5, '{"poet":"Özgür Engüzel","poet_slug":"ozgur-enguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/umut-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-ozgur-enguzel-76mdz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sevgi var her yerde.

uçsuz bucaksız gökyüzünde

denizin maviliğinde

okyanusun derinliğinde

güneşin yedi renginde 

sevgi var.

küçük bir çocuğun

gülümseyişinde

yakın bir arkadaşı arayışında

canlıları sevişinde.

ve, 

sevgilerin ulaşılmazı

şimdi gözlerimde...

03/06/2002

Özgür ENGÜZEL', 'sevgi var her yerde. uçsuz bucaksız gökyüzünde denizin maviliğinde okyanusun derinliğinde güneşin yedi renginde  sevgi var. küçük bir çocuğu...', ARRAY['Türk Edebiyatı','Şiir','Özgür Engüzel']::text[], 8.5, '{"poet":"Özgür Engüzel","poet_slug":"ozgur-enguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ask-141-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saplantım', 'saplantim-ozgur-enguzel-dia9m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gözlerim seni arıyor.

hayal edemiyorum

bilmediğim güzelliğini.

yalnızım.

öksüz çocuklar doluşmuş 

yüreğime.

yüreğim ve ben! 

Birde çocukluğumu alıp 

dolaşıyoruz 

başıboş sokakları...

öksüzlüğümü topluyorum

her köşe başında.

bu günde bekliyorum      

duraksız yollarda.

ben,

öksüz yollarda durak.

sen, 

durmaksızın giden

masmavi gökyüzü.

19/09/1999

Özgür ENGÜZEL', 'gözlerim seni arıyor. hayal edemiyorum bilmediğim güzelliğini. yalnızım. öksüz çocuklar doluşmuş  yüreğime. yüreğim ve ben!  Birde çocukluğu...', ARRAY['Türk Edebiyatı','Şiir','Özgür Engüzel']::text[], 8.5, '{"poet":"Özgür Engüzel","poet_slug":"ozgur-enguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/saplantim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen 1', 'beklenen-1-ozgur-enguzel-p5dye', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 've anladım! .

beni sana getiren, 

sonuçlarında 

pişmanlığa sığındığım

seçimlerimdi.

evet, anladım...

seçimlerimdir

yaşamı şekillendiren.

20/01/2002', 've anladım! . beni sana getiren,  sonuçlarında  pişmanlığa sığındığım seçimlerimdi. evet, anladım... seçimlerimdir yaşamı şekillendiren. 20/...', ARRAY['Türk Edebiyatı','Şiir','Özgür Engüzel']::text[], 8.5, '{"poet":"Özgür Engüzel","poet_slug":"ozgur-enguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/beklenen-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen', 'beklenen-ozgur-enguzel-hutb8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ben seni düşünüyordum.

sen beni tanımadan

yıllar önce.

varlığından habersiz.

16 yaşımdaydım. 

bilinmezliğini

yüreğime ektiğimde. 

sesinin tonuna karar veremedim

günlerce...

17 yaşımda, 

ne isteyeceğimi biliyordum.

filizlenmiştin 

kalbimin derinliklerinde. 

şimdi seni bir çocuk gibi

büyütmeliydim.

düşünerek, düşleyerek.

her anı düşündüm

geçen yılların.

zor olmalıydın

hatta imkansız.

oldum olası sevmişimdir

imkansızı, ulaşılmazı.

adını değil. 

ama

giyinmeni yürümeni biliyordum.

doğal olmalıydı.

güzel olması şart değil.

giydikleri değil!    

yüreği güzel olmalıydı. 

sevgi dolu tıka basa.     

sevmeliydi etrafındaki canlıları 

dostça... 

hesapsız ve çıkarsız. 

ışık saçmalı,

mutluluk vermeli gülüşü.

yaşanası olmalı

bir ömür boyu.

bulutsuz gecede ki,

yeni ay gibi görebilmeli

yüreğimdeki sevgiyi.

ve, tek kelimeyle

mükemmel olmalı.

bir o kadar da imkansız.

oldu da  kanımca.

gözlerinin rengi kalmıştı

bilmediğim.

bir de tenin.

uzun mu olurdun, balıketi mi

onu da bilmiyordum.

bel ki çok güzel olacaktın.

haddinden fazla.

belki sarışın olacaksın

kömür karası gözlerinle.

çirkin olacak gülüşün.

belki de kahkaha atışın.

yada,

ipek gibi saçların olmayacak.

kötü espriler yapsan ne çıkar.

hiç önemi olmadı bunların.

düşündüklerim arasında.

yıllarca

düşündüm, düşledim

beklemedim...

varlığından habersiz

adını bilmeden.

pişmanlıklar içinde öğrendim

imkansız diye bir şey yokmuş.

inanmak düşlerine

istemek iradenle

ve yıllar geçse de 

beklemek yetiyormuş.

umutla......

13/01/2002

Özgür ENGÜZEL', 'ben seni düşünüyordum. sen beni tanımadan yıllar önce. varlığından habersiz. 16 yaşımdaydım.  bilinmezliğini yüreğime ektiğimde.  sesinin to...', ARRAY['Türk Edebiyatı','Şiir','Özgür Engüzel']::text[], 8.5, '{"poet":"Özgür Engüzel","poet_slug":"ozgur-enguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":74,"source_url":"https://www.antoloji.com/beklenen-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KORKU', 'korku-ozgur-enguzel-4lefr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir gün görürsem seni

mutsuz...

okursam gözlerinde

umutsuz.

bil ki, 

o gün direncim kaybolur

bil ki, o gün

son günüm olur..

18/04/2002', 'bir gün görürsem seni mutsuz... okursam gözlerinde umutsuz. bil ki,  o gün direncim kaybolur bil ki, o gün son günüm olur.. 18/04/2002...', ARRAY['Türk Edebiyatı','Şiir','Özgür Engüzel']::text[], 8.5, '{"poet":"Özgür Engüzel","poet_slug":"ozgur-enguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/korku-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Gelen Yaşam', 'yeni-gelen-yasam-ozgur-enguzel-izrdf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Güneşi, 

doğmamacasına batırmış

günebakandım ben...

gözlerindeki güneşin

gülüşünü  görene dek...

19/09/2002', 'Güneşi,  doğmamacasına batırmış günebakandım ben... gözlerindeki güneşin gülüşünü  görene dek... 19/09/2002...', ARRAY['Türk Edebiyatı','Şiir','Özgür Engüzel']::text[], 8.5, '{"poet":"Özgür Engüzel","poet_slug":"ozgur-enguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yeni-gelen-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamalı mı?', 'yasamali-mi-ozgur-enguzel-7j0sh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bu varoluşta 

bilmeden yürüdüğümüz

gök mavinin aydınlattığı

bir eylül 

sonbaharında...

sonunda zirvesi karlı

bir dağ ve 

önünde 

yaprak dökümünün

ilkbaharı yaşadığı

ağaçlı bir yoldu.

ayrı ayrı seçtiğimiz.

08/01/2003

Özgür ENGÜZEL', 'bu varoluşta  bilmeden yürüdüğümüz gök mavinin aydınlattığı bir eylül  sonbaharında... sonunda zirvesi karlı bir dağ ve  önünde  yaprak dökü...', ARRAY['Türk Edebiyatı','Şiir','Özgür Engüzel']::text[], 8.5, '{"poet":"Özgür Engüzel","poet_slug":"ozgur-enguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yasamali-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklayamadığın', 'saklayamadigin-ozgur-enguzel-f4pyl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yırtıyor; 

tutamadığım

batan güneşe inat.

gecenin yalnız,

gizemli

düşündürücülüğünü...

ardında; 

sevgini

acılarını sakladığın.

o saklamışlığınla

yalnızlığını

yalnızlığının paylaşılmazlığını 

büyüttüğün. 

her güne doğan

gözlerin! ....

10/07/2002

Özgür ENGÜZEL', 'yırtıyor;  tutamadığım batan güneşe inat. gecenin yalnız, gizemli düşündürücülüğünü... ardında;  sevgini acılarını sakladığın. o saklamışlığ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Engüzel']::text[], 8.5, '{"poet":"Özgür Engüzel","poet_slug":"ozgur-enguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/saklayamadigin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum', 'bilmiyorum-ozgur-enguzel-3hxc4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kimde bu sevgi? 

kim! 

kim saklamış 

gözlerinin ardına...

bu insan

bu sevginin yüreği

varolmalı...

gün kadar gerçekliğinle

her güne karışıyor 

varlığın...

kokusunu duyuyorum

teninin

sevgisinin

yağmur sonrası toprak gibi.

sesindeki 

büyümeyen çocuğu,

yüreğinin çocukluğunu da

biliyorum.

ama adını bilmiyorum

bekliyorum...

bir çocuğunun 

gülümseyişinde,

gözlerinde buluyorum seni

seni ve 

sevginin çıkarsızlığını...

“seni seviyorum” diyorum

nerdesin? 

adını yazamıyorum! 

yüzünü çizemiyorum! 

yıldızlarda çizmiyor

geceye...

güneş,

artık doğmam diyor.

yarınlarım penceresiz

kimsin? 

nerdesin? 

gözlerim kanıyor

gök benimle ağlıyor

bu kırmızılık 

maviyi özletiyor. 

Mavi

derinliklerine çağırıyor.

nerdesin? 

apansız... 

duran fırtınaya

yağmurlu güneş gibi

kaybolan umutlarımla

çık gel artık

ne olur gel.

gel...

gel al

bendeki sevgini.

soluk alamıyor 

boğuluyorum.

gel artık

sensiz taşıyamıyorum...

19/09/1991

Özgür ENGÜZEL', 'kimde bu sevgi?  kim!  kim saklamış  gözlerinin ardına... bu insan bu sevginin yüreği varolmalı... gün kadar gerçekliğinle her güne karışıyo...', ARRAY['Türk Edebiyatı','Şiir','Özgür Engüzel']::text[], 8.5, '{"poet":"Özgür Engüzel","poet_slug":"ozgur-enguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":58,"source_url":"https://www.antoloji.com/bilmiyorum-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen!', 'sen-ozgur-enguzel-v3eje', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sen, sevdiğim

sen

çocukluğum kadar uzakda

dokunacak kadar yakınımda

sonsuz gecede

ulaşılmaz yıldızdın bana...

05/02/2002

Özgür ENGÜZEL', 'sen, sevdiğim sen çocukluğum kadar uzakda dokunacak kadar yakınımda sonsuz gecede ulaşılmaz yıldızdın bana... 05/02/2002 Özgür ENGÜZEL...', ARRAY['Türk Edebiyatı','Şiir','Özgür Engüzel']::text[], 8.5, '{"poet":"Özgür Engüzel","poet_slug":"ozgur-enguzel","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sen-234-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-sumru-okyay-qirti', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Umut bu ya

Günler güzel ya

E daha ne

Demeyin öyle

Umut işte!', 'Umut bu ya Günler güzel ya E daha ne Demeyin öyle Umut işte!...', ARRAY['Türk Edebiyatı','Şiir','Sumru Okyay']::text[], 8.5, '{"poet":"Sumru Okyay","poet_slug":"sumru-okyay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/umut-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzünlü Kahkaha', 'huzunlu-kahkaha-sumru-okyay-0dxt9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eskaza konuşursam

Hüzünle dökülecek sözlerimi susturmak için

Çaresizliğimi

Gülümsemeyle kapatıyorum

Abartmak istediğimde

Kahkaha atıyorum.', 'Eskaza konuşursam Hüzünle dökülecek sözlerimi susturmak için Çaresizliğimi Gülümsemeyle kapatıyorum Abartmak istediğimde Kahkaha atıyorum....', ARRAY['Türk Edebiyatı','Şiir','Sumru Okyay']::text[], 8.5, '{"poet":"Sumru Okyay","poet_slug":"sumru-okyay","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/huzunlu-kahkaha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Sen', 'sadece-sen-bilsay-yildirim-2gtzz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aklıma tek gelen senin hakkında yazmak..

Uzun zaman sonra seni özlediğimdendir...sık sık yazıyorum bu aralar..

ne deniz aşırı aşklar yaşadığımızdan..ne de dün gece senin adınla uyandığımdan..

yaslanmışken omzuma..alnından öpmek..en çok özlediğim bu..

dalgaları karanlığa karışmış görmek..elini tutarken tek hissettiğimin..sen olması..ne İstanbul ne ötesi..

ne de deniz aşırı aşklar..

öncesine dayanıyor benim sevdam...

beyaz dağlarların arasına..iki yakanın arasında...boğazın ortasında..

kordona dayanıyor benim sevdam...

güneşi orda batırmaya alışmışız..

bırak yine orda batsın bu akşam..', 'Aklıma tek gelen senin hakkında yazmak.. Uzun zaman sonra seni özlediğimdendir...sık sık yazıyorum bu aralar.. ne deniz aşırı aşklar yaşadığ...', ARRAY['Türk Edebiyatı','Şiir','Bilsay Yıldırım']::text[], 8.5, '{"poet":"Bilsay Yıldırım","poet_slug":"bilsay-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sadece-sen-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Istanbul', 'istanbul-bilsay-yildirim-d53f7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'istanbul''u özledim bu akşam, 

Sırf sen ordasın diye.', 'istanbul''u özledim bu akşam,  Sırf sen ordasın diye....', ARRAY['Türk Edebiyatı','Şiir','Bilsay Yıldırım']::text[], 8.5, '{"poet":"Bilsay Yıldırım","poet_slug":"bilsay-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/istanbul-76-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huzur', 'huzur-bilsay-yildirim-9nal9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sesim soluğum çıkmıyor..

Sadece uzanmış seni dinliyorum..

seni izliyorum 

Ara sıra gözlerine dalıyorum

Çok uzaklara..senden uzaklara gidiyorum..

Ne seni..ne sesini duyabiliyorum

Gözlerimi açıyorum

Hep seni..

Bir tek seni seviyorum..', 'Sesim soluğum çıkmıyor.. Sadece uzanmış seni dinliyorum.. seni izliyorum  Ara sıra gözlerine dalıyorum Çok uzaklara..senden uzaklara gidiyor...', ARRAY['Türk Edebiyatı','Şiir','Bilsay Yıldırım']::text[], 8.5, '{"poet":"Bilsay Yıldırım","poet_slug":"bilsay-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/huzur-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seven', 'seven-oguzhan-tas-q2cvy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne aşk çığlıkları yükselir yeryüzünden, 

Kim kimi terkeder, 

neden terkeder? 

Neden daha çok seven

Her zaman ayrılığı hak eder...', 'Ne aşk çığlıkları yükselir yeryüzünden,  Kim kimi terkeder,  neden terkeder?  Neden daha çok seven Her zaman ayrılığı hak eder......', ARRAY['Türk Edebiyatı','Şiir','Oğuzhan Taş']::text[], 8.5, '{"poet":"Oğuzhan Taş","poet_slug":"oguzhan-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/seven-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul Gözlü', 'i-stanbul-gozlu-ozdemir-rafet-0opk4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen İstanbul gözlü, 

bu gece gözlerine beni al.

Ne değişir ki, 

İstanbul yerine

gözlerinde ben yanıp sönsem.', 'Sen İstanbul gözlü,  bu gece gözlerine beni al. Ne değişir ki,  İstanbul yerine gözlerinde ben yanıp sönsem....', ARRAY['Türk Edebiyatı','Şiir','Özdemir Rafet']::text[], 8.5, '{"poet":"Özdemir Rafet","poet_slug":"ozdemir-rafet","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/istanbul-gozlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İletken', 'i-letken-erdal-alga-n7i3p', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Tel iletkendir

Öyle olmasa

Mesafeler varken

Nasıl ulaşırdı

Kalbimdeki elektrik sana

Ve nasıl yanardı

Yüreğindeki ampul.', 'Tel iletkendir Öyle olmasa Mesafeler varken Nasıl ulaşırdı Kalbimdeki elektrik sana Ve nasıl yanardı Yüreğindeki ampul....', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/iletken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tükenmez Kalem', 'tukenmez-kalem-erdal-alga-zxkei', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tükenmez diye verilen kalem

Tükendi

Neyle yazarsan yaz alına yazıyı

Ya da tükenmeyecek san 

İstediğin kadar

Hayat da bir gün, tükenecek.', 'Tükenmez diye verilen kalem Tükendi Neyle yazarsan yaz alına yazıyı Ya da tükenmeyecek san  İstediğin kadar Hayat da bir gün, tükenecek....', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/tukenmez-kalem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aysılam', 'aysilam-hayrettin-turk-jar33', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşanacak ne kadar çokşey vardı

Nerdesin, söyle nerdesin aysılam

Sevdan bana nisanlı bir bahardı

Nerdesin, söyle nerdesin aysılam...

Biz güllerden güzelliği çalmıştık

Bülbüllerden muhabbeti almıştık

Aşkın demine seninle dalmıştık

Nerdesin, söyle nerdesin aysılam...

Gözlerinde hüzün, mevsimse hazan

Damlayla dolup bir anda boşalan, 

Sendin o zerreden kürreye dalan

Nerdesin, söyle nerdesin aysılam...

Az önceydi sanki, son kez sarıldık

Yarına deyip öylece ayrıldık, 

Ayrıldık işte, öylece ayrıldık, 

Nerdesin, söyle nerdesin aysılam...', 'Yaşanacak ne kadar çokşey vardı Nerdesin, söyle nerdesin aysılam Sevdan bana nisanlı bir bahardı Nerdesin, söyle nerdesin aysılam... Biz gül...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/aysilam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Uyurken Ben', 'sen-uyurken-ben-hayrettin-turk-pn9fb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen uyurken ben, 

Meleklere yalvardım

Bulutları boşaltsınlar

Belli olmasın gözyaşlarım

Ve hep sana, 

Sanaydı dualarım...

Sen uyurken ben

Saçlarından yıldız topladım

Ayışığı yansımalarını alıp

Nakış nakış

Gözlerime işledim

Sen uyurken ben, 

Yanağını okşadım

Bin yıllık sevgiyi

Çıkarıp küller altından

Bir kere, 

Son kere daha yaşadım...', 'Sen uyurken ben,  Meleklere yalvardım Bulutları boşaltsınlar Belli olmasın gözyaşlarım Ve hep sana,  Sanaydı dualarım... Sen uyurken ben Saç...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-uyurken-ben-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günün üstüne', 'dogum-gunun-ustune-huseyin-cayikli-y7lnm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'saatim durdu ve artık zamanı bilmiyorum.

ne zaman terkettiğini

takvim sayfalarından koparttım.

beşparmak dağlarının üzerinden haykırdım

samanlı dağlarına.

oysa tridos dağlarında sesim kaldı.

yine bir doğum günü zamanında yazıldı

bu yazı

ama bu yazı bizim yazgımız değildi.

bir kuş evinin önüne gelirse korkutma balkonunda ekmeğin olsun.

ben kaç gece beklemiştim

yine bir doğum gününde

kuşları ürkek şehrimin

en sevdiği körfezini düşüneceğim.

bir gece vakti farketmeden geleceğim.

sen olmayacaksın orada

belkide olacaksın

kaçacağım bir sonra ki şehre giden

otobüsten bilet alacağım.

son seferleridir o saate 

sonra o şehirden bütün anılarımı yükleyip kaçacağım

acılarım başarısızlakla dolu hayatım.

benim başarısızlıklarım aslında başardıklarımdı.

isterdim uyumlu zamanımda gelmeni...

ama hiç yapadın.

yalnış zamanlarımda geldim...

sonra gittin...

bana da şimdi bir iş düşüyor gideceğim şehirlerden uzağa gitmek.

seni seviyorum demeden uzaklaşmak...

sonra gittim

bilet aldım uzaklara giden uçaklardan

ne sen aradın nede ben seni.

haberimiz bile olmadı hayatımızdan

kadınlarım oldu

adlarını unuttuğum 

gece yalnız bırakmadılar beni.

senle yaşadım sende kaldı.

sonra aşklarım olu benim en içli ama içten olmauan sevdalarım

hiç birini sevmedim...

hep aklımdaydın

kadınım dedim

ağladım

yine bir doğum günün üstüne yazıldı bu yazı 

senin yerini tutan şimdi bir şarap şişesi...', 'saatim durdu ve artık zamanı bilmiyorum. ne zaman terkettiğini takvim sayfalarından koparttım. beşparmak dağlarının üzerinden haykırdım sama...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/dogum-gunun-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağlar Ötesi Aşk', 'caglar-otesi-ask-hayrettin-turk-su31i', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yüreğimde

nesli tükenmiş duygularla sevdim

dinazorlar çağından güllerle

gelişmiş tunç çağından

ilkel yazılarla sevdim

yılları binlere çarptım

durdum

bir daha sevdim

sevdim ve gördüm

mağara duvarlarında 

benim aşkım yazarmış

ve seni anlatırmış

kalem diye kullanılan çiviler....', 'yüreğimde nesli tükenmiş duygularla sevdim dinazorlar çağından güllerle gelişmiş tunç çağından ilkel yazılarla sevdim yılları binlere çarptı...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/caglar-otesi-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Vapur', 'son-vapur-hayrettin-turk-x8bu9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bu giden son vapurdu

son iftardı son açlığıma

kısa anlarda gizli kader

sahilde öylece kaldım aysılam...

gidenler anlamaz yüreğimi

onlar giden kervana el sallamadı

nasıl bir rüyaymış ki bu, 

yapayalnız uyandım aysılam...', 'bu giden son vapurdu son iftardı son açlığıma kısa anlarda gizli kader sahilde öylece kaldım aysılam... gidenler anlamaz yüreğimi onlar gide...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/son-vapur-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Issız Dağlar BAşında', 'issiz-daglar-basinda-hayrettin-turk-an116', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ıssız dağlar başında aysılam

sular bir başka akar

bir başka eser rüzgar

yüreğim gibi kuytularda

bir başka yanar çoban ateşi...

ıssız derler ya

değildir aysılam, 

bilenler bilir

eşkiyanın yol kestiği yeri

kınalı kekliklerin yayılıp

kurtların su içtiği yeri...

hele geceler bir başkadır

karanlık önce içine çöker

hissedersin yalnızlığı aysılam, 

gözlerin umutla yıldızları arar

şiir olursun ovalara

seni amlatır birileri

anlatırlar ayrılığı aysılam...', 'ıssız dağlar başında aysılam sular bir başka akar bir başka eser rüzgar yüreğim gibi kuytularda bir başka yanar çoban ateşi... ıssız derler ...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/issiz-daglar-basinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boynumda Kendi Ellerim', 'boynumda-kendi-ellerim-nuri-can-tra4e', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerim çocukları yoksul bir ülke şimdi 

içimin kızıllığınca gül ve yangın 

dalında unutulmuş bir üzüm tanesiyim belki 

belki bir söğüt dalının efil efil titreyen yaprağıyım 

uzak bir iklimde esip geçen rüzgarlara ağıt yakan 

bir gün çözüp bakışlarımı tel tel kirpiklerimden 

elif elif ağlayan gümüş saçlı bir anneye bağışlayacağım 

son kez ağlayacağım belki düşerken sevdanın eşiğine 

varsın bağışlamasın beni hayat ki, 

ay uzak tepelerin ardına çekilsin 

çarpa çarpa dövsün kıyılarımı acılar 

yarasına figan düşsün kırlangıçların 

eriyip gitsin hüzünlü bakışlarımda ne varsa 

yokluğuma kahırlanmayacaksa bu kent 

ah! çekmeyecekse ardımda kalan anılar 

Ah! ey yarasında nehirler fışkıran kalbim 

susuyorum işte acılara akan bir sesle

hayat ki, ateşten bir ip boynumda 

koynumda buzdan bir top

ne zaman doğrulsam dokuz yerimden vururlar beni

biliyorum her susuşun ardında bir yalnızlık var 

bir özlem, bir kahır var

bilinsin ki, bir yanı yangındır susuşlarımın, bir yanı ölüm

aşkın kor ateşlerinde sınanmış bir semenderim ben

her gece kalbimin ortasında bir çöl çiçeği açar adı Leyla

bir yanı Yusuf’tur acılarımın bir yanı Züleyha

yolları beklemekten yorgun, yıllara gözyaşı dökmekten

hüzünlü yüzüm, aykırı sakalımla

ondandır dünyanın orta yerinde kederli bir dağ gibi duruşum 

siyahlar giyinişim, saçlarımı taramayışım

bir yaban gülü gibi ıssızda ağlayışım

bir derviş gibi yakışım kalbimi, boynumu büküp bakışım

ondandır 

bunca incinmişliğim ondan 

kemirirken içimi utangaç ulalar heyulasında geçmişim 

susuyorum ki, acıma kimseler merhamet etmesin 

çünkü hep sevgilerden aldım suların derin akışını 

ve nakışını yüreği elmas bir kızın dantelinden söktüm 

biliyorum yangınlar kentinde kıvılcımlar 

bir sevdadır gül yaprağına konmuş 

bütün yıldızlar sırtını dönmüş bana, ayda küs 

hayat bu işte ey kalbim bir varmış bir yokmuş 

varsın kirpiklerimden acı dökülsün 

yüreğimde büyüttüğüm kır menekşeleri için 

son bir damla su istiyorum senden ey kalbim allah aşkına 

bu çölleri sen yarattın iflah olmaz ömrüme 

senden aldım bu kadar sevmeyi, özlemeyi, kahrolmayı 

şimdi boynumda kendi ellerim bağışlama beni 

tükenmiş ümitlere yeni vahalar gerekmiyor çünkü 

her bahar kuşlar kanat çırpınca özgürlüklere 

sesler gelince karlı dağların ardından türkü ırmaklarında 

ve ben uzanıp durduğumda yatağıma ince bir su gibi ıssız 

sorun kalbime özlemek nedir, acı nedir, hüzün nedir 

yasaksa aşk titreyen yüreklerin deltasında 

varsın kurusun güller, sular kararsın, kumlar yansın 

bir çöl akşamıyım artık 

bıçak keskinliğinde yakınmadan esip geçiyor düşlerim 

savunmasızım, sus ey kalbim intizarın sende kalsın 

gizle, vuslatı arzulayan bir kor ol yan kalbim, kimse bilmesin 

bütün çığlıklarını kuşansın gelsin ölüm', 'Gözlerim çocukları yoksul bir ülke şimdi  içimin kızıllığınca gül ve yangın  dalında unutulmuş bir üzüm tanesiyim belki  belki bir söğüt dal...', ARRAY['Türk Edebiyatı','Şiir','Nuri Can']::text[], 8.5, '{"poet":"Nuri Can","poet_slug":"nuri-can","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/boynumda-kendi-ellerim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Köy', 'kayip-koy-i-hsan-uncuoglu-o0bem', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kayıp Köy

Ey köyüm Nerdesin

Ben kayıbım bilesin

Yaşarım ince belde 

Sivri kayada tepede

Ay Yıldızlarla ışıyan

Gece kondu evimde, 

***

Bir dağ başı şehirde

Kölesi oldum öküzlerin

Beni arama ya o müzedeyim 

Bulamazsan bir meclisteyim

Böyyük şehirliyim artık piştim 

Kervan önünde yerim yurdum 

Rüyada yaşıyom yoksa bitikti sonum, 

***

Birileri tarihte vardık der der öterler

Çıktıkları yeri bilmezlerki söylesinler 

Ne günler yaşadık çok saygın arkadaşla

Şimdi edi ile büdü yanlız kaldık başbaşa, 

***

Köy rahattı çiftimi çubuğumu batırdım

Bir elimde inekler öbüründe koyunlarım

Parmakla gösterir sayardı yandaşlarım 

Kahvede muktarlara çıkar hesap sorardım, 

***

Tezek yollu meydanda banka posta bakkalım 

Sevenlerimle koşturur gönül hizmeti imamdım 

Uzun ağaç tepesinde düğün dernek yaşıtlarım 

Köyümde çift çubuk rahattım hayal uğruna sattım, 

***

Evimde katıksız yağım inek sütüm yoğurdum

Tarlada sokakta boldu selamlayan yoktu odun

Kazlara sözüm geçer kendi başıma buyruktum

Köyden taşa toprağa kandım şimdi İstanbul''luyum 

Göçtüm şehire bildiğimi benliğimi kimliğimi unuttum, 

***

Altında marka araba avrupa euro dolu kasa

Metresi beyimin pariste eksik olmaz yanınd

O çığırtkanlara takıldık binbir heves peşpeşe 

Şimdi hep kaybolduk oturduk kınalı pamuk ellerle

Davul zurna bağ bahçe otuz haneydik köyümüzde 

İşte geldik bando mızıka kalkındık her şehirde çıktık göğe! , 

Yazıyooor yazıyoor! , köylü efendimizi yazıyoor! 

KÖY GAZETESİ.', 'Kayıp Köy Ey köyüm Nerdesin Ben kayıbım bilesin Yaşarım ince belde  Sivri kayada tepede Ay Yıldızlarla ışıyan Gece kondu evimde,  *** Bir da...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/kayip-koy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümüne Sevdalar', 'olumune-sevdalar-abdulhamit-kanca-w8lyt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecenin bittiği yerde 

bir kız ağlıyor

Alçak bir pencerede

Kimbilir belki gurbettekine

Belki  parlak ışıklarda yitilmişliğine

Belki de düşünür gönderdiği sevgilisini

Ötelerin ötesinde...

Kız ağlıyor yine; 

İzliyor sanki çekilmiş fotoğrafları

Sırasıyla yüreğinde.

Almak istiyor birini

Tutamıyor her seferinde.

Yanıyor bu kız belki de

Sevmeyi bilmediğine, 

Belki de sevdayı öğretemediğine...

Haykırıyor yeni gelen şafağa sessizce

“Gözyaşlarım sürecek mi daha? 

Değecek mi ızdırapların şenliğini yaşamak, 

Yazılacak mı acaba muhteşemi kaderlerin.”

Hala ağlamakta bu kız; 

Kim ki acaba 

Gözlerinin daldığı yerdeki bu sevgili? 

Siler gözyaşlarını şimdi

Bakar ellerine damlaların birleştiği yerde.

Devam eder bu kız ağlamaya

Ummanlar yaratacakmış gibi, 

Bilmem ki bilir mi o birisi

Onun ona yandığını? 

Bilir mi gözyaşlarında yıkanmayı? 

Böyle büzülüp içe akmayı, 

Bilir mi yıldızları nişanlamayı, 

Böylesine Tanrı’yla konuşmayı? 

Yıldızları boşver, 

İster mi acaba hiç olmazsa 

Ahirette buluşmayı..

Hay Allah uyandım! 

Rüyaymış meğer bu gördüklerim.

Vurdum kafama sersemce; 

“Oğlum öğrenemedin hala 

Böylesine ölümüne sevdaların 

Kül tablalarında söndürüldüğünü.

                                    mart”99/Samsun', 'Gecenin bittiği yerde  bir kız ağlıyor Alçak bir pencerede Kimbilir belki gurbettekine Belki  parlak ışıklarda yitilmişliğine Belki de düşün...', ARRAY['Türk Edebiyatı','Şiir','Abdülhamit Kanca']::text[], 8.5, '{"poet":"Abdülhamit Kanca","poet_slug":"abdulhamit-kanca","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/olumune-sevdalar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mekansız Aşklar', 'mekansiz-asklar-abdulhamit-kanca-fc6sk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilmem ki neden koşarız

Gülmek uğruna

Ağlamaya kucak açmayı

Neden yeğledik 

Bile bile o masum ve 

İmkansız aşklarla boğuşmayı..

Yorgun yüreğim Neden bıkmaz

Ateşini korlarda söndürmeyi

Hem de bu yaşamın yasağında...

Alemleri sığdırdım da içime

Bomboş kaldı yine, 

Seninse yalnız adını koyabildim

Her baktığım yerde seni görebileyim diye

O yorgun yüreğime...

Sanki şimdi; 

Biz seninle ikimiz

İki kişilik bir dinin 

Muhteşem müritleriyiz.

Şahidi yok, 

Mekanı, mabedi yok

Günahı yok, ve de

Sevaba ihtiyacı yok.

Biz söyleyip biz yaşayacağız

Biz isteyip biz öleceğiz.

Açtığımızda avuçlarımızı göklere

Rahmet olsun dönsün

Yağmur olsun dökülsün dualar

Böylesine aşlara özlem duyanlara...

Hadi söyle 

Var mı sende böyle bir yürek? 

Sen de sığdırabildinmi benden bir şeyler.

O taptaze yüreğine...

Yoksa bana yok de

Ben de bir pusulayla başlayan 

O miladı külle örteyim.

Kalsın tazeliğinde

Beklesin  o beklenen deli rüzgarını yine

Taptaze ateşiyle...

                              

                                 temmuz”99/Samsun', 'Bilmem ki neden koşarız Gülmek uğruna Ağlamaya kucak açmayı Neden yeğledik  Bile bile o masum ve  İmkansız aşklarla boğuşmayı.. Yorgun yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Abdülhamit Kanca']::text[], 8.5, '{"poet":"Abdülhamit Kanca","poet_slug":"abdulhamit-kanca","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/mekansiz-asklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaralı Posta Güvercini', 'yarali-posta-guvercini-umut-ulbegi-9poyp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir posta güverciniyim

yönünü bulamayan

gece seni karartmadıkça

ağlamayan

Yönünü bulamayan 

bir posta güverciniyim

dudaklarım yoktur

ellerini ver de 

incineyim

Bir güvercine 

ellerinden yem yedirdiğinde

hem de bir posta güvercinine

sanma ki 

tüm mektuplarını sana verir

İhtimal

bir gün sarı bir zarf içinde

ellerini geri gönderir.', 'Bir posta güverciniyim yönünü bulamayan gece seni karartmadıkça ağlamayan Yönünü bulamayan  bir posta güverciniyim dudaklarım yoktur ellerin...', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yarali-posta-guvercini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye Yarar+', 'niye-yarar-bayram-tunca-7kuvv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dardayken yar olmadıktan sonra neye yarar

Varlıklıyken yar oluşun neye yarar neye yarar

Düşmanımdan ziyade verdin sen bana zarar

Neye yarar/neye yarar vefasızlığın verdi zarar

Söyle vefasız yar söyle yapılır mı hiç bu böyle

Hangi kitap, hangi örf/âdete sığar bu yaptığın

Böyle miydi, benimle yaptığın ahd-ı peymanın

Söyle kim öğretti vefasızlık etmeyi sana böyle

Çaresizlik girdabında hayat mücadelesi verirken

Doğru muydu her lahzsa deli gömleği giydirmen

İtikat men etmeseydi kıymıştım bu cana çoktan

O an, sen de katilim olmuş olacaktın hiç yoktan

Bana yaptıklarını dağlara yapsaydın dayanamazdı

Görselerdi düşmanlarım sevinir, dostlarım ağlardı

Bu ademoğlu çaresizlikten gece gündüz kıvranırdı

Yaptıklarını kime yapsaydın, o da bağırıp çağırırdı

11.03.2003-15:11

Aşk Ateşten Gömlek', 'Dardayken yar olmadıktan sonra neye yarar Varlıklıyken yar oluşun neye yarar neye yarar Düşmanımdan ziyade verdin sen bana zarar Neye yarar/...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/niye-yarar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksik Şiir', 'eksik-siir-ozgur-hatem-9oyf4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '(Eski izime basa basa

Yine geldim sesine!)

Yürünmüş sokakların

Gizli şiirlerinde

Uyaklar, eksik.

Ne gece tamamladı beni, 

Ne gözlerindeki kafiye...

Yolun boyu, 

İncilerimi topladım tek tek.

Çilek tadı bir duman! 

Eksik kalan şiirin

Her hecesi yolcudan.

Bakış acıya değmiş

Hasret 

Yokluk

     Murat! 

Bir başına efkar! 

Yalın kat yalnızlıklar.

Ne söz tamamladı beni, 

Ne sesindeki uyaklar.

Gözlerinden bakışımı seçtim, incecik

Katlı duran zamandan, düşlerimi

Karanlığın yazgısına ağıt olsun istedim

Ne saz tamamladı beni, 

Ne şiir! 

(11.03.2003)', '(Eski izime basa basa Yine geldim sesine!) Yürünmüş sokakların Gizli şiirlerinde Uyaklar, eksik. Ne gece tamamladı beni,  Ne gözlerindeki ka...', ARRAY['Türk Edebiyatı','Şiir','Özgür Hatem']::text[], 8.5, '{"poet":"Özgür Hatem","poet_slug":"ozgur-hatem","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/eksik-siir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öfke', 'ofke-ozgur-hatem-a936j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tut elimden! 

Sayalım, 

   Salalım

      Savrulalım.

Kent, bize kırsın dümeni

Sesimize darağacı kuralım.

Önce

Aşkı asalım! 

Korkunun kemendiyle.

Kayıtsızlık, iyi halden tahliye.

Başka ne düş kaldıysa, 

Yüzüne yastık kapatalım

Soluksuz bırakalım.

Sen, 

Sol elimi tut! 

Sağ elimde, süpürge.

Geri geri yürürken izlerinin üstünde

Silelim

   Süpürelim

       Yok edelim.

Aşktan yana

Başka ne söz kaldıysa

Tunçtan mezar yapıp

Gömelim! 

(11.03.2003)', 'Tut elimden!  Sayalım,     Salalım       Savrulalım. Kent, bize kırsın dümeni Sesimize darağacı kuralım. Önce Aşkı asalım!  Korkunun kemendi...', ARRAY['Türk Edebiyatı','Şiir','Özgür Hatem']::text[], 8.5, '{"poet":"Özgür Hatem","poet_slug":"ozgur-hatem","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ofke-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MAJOR', 'major-mine-ozdemirtas-jxkol', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Keşfetme tutkusunu seviyorum.

Çünkü aptallığımın çıplaklığını örtüyor.

Ama yine de

Bu yara almış serüven de

Silinmeyecek bir aşkın altına atılmış imzaların birinde

Söz biyografiye geldiğinde; 

Son satırın tercümesi sözlükleri zorluyor.

Okuması çok kolay. Fakat, 

Anlamını taşımak çok zor.

Ruhum satranç tahtası üzerinde

Çılgınca soyunuyor.

Cennet ya da cehennem iki sondan biri

Son hamle bu

Şah Mat ya da Major', 'Keşfetme tutkusunu seviyorum. Çünkü aptallığımın çıplaklığını örtüyor. Ama yine de Bu yara almış serüven de Silinmeyecek bir aşkın altına at...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/major-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oniki mayıs (Anneler Günü)', 'oniki-mayis-anneler-gunu-akif-karakoca-5sar2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Oniki mayıs anneler günü

Ne büyük bir gün bugün

Çocuk anasının koynunda

Şefkatinin doruğunda

Ana var ocağında niyazla

Bekler yavrusunu umutla

Şaşkın şaşkın dolaşır evlat

Umutla yolunu gözlediği

Hasret ile kavrulduğu

Anasının yüreğini hafifletmek için

Dolaşır dolaşor dolaşır da bulamaz

Biricik anası için bir hediyesini

Ama gelmez hiç aklına biçarenin

Bilmez ki hediyenin büyüğünü

Bilmez ki analar için evladının varlığını

Var olup ta dizinde yatmayı

Başını sırtını sıvazlatmayı

Bu büyük günde ne ararsın ey evlat

Dünyalık mı ararsın mutluluk için

Bilmez misin sen ey evlat

Dünyalık olsaydı mutluluk

Ne önemi kalırdı o zaman bu günün...

Ne büyük gün bugün

Ana evladını evlad anasını arar

Evlat gurbet elde ana berbat halde

Paralel, kendini durmaz ana

Durmaz da ana duymaz evlat

Yaşar o bir eli yağda bir eli balda

Bakmaz geriye gitmez ileriye

Ne büyük gün bugün

Yuhlar olsun yuhlar olsun

Elin anası sultan olmuş evinde

Benim anam ırgat olmuş el elinde

Nerdesin ey evlat ey zalim

Bugün onun günü değil senin günün

Senin imtihan günün bu gün

Sensiz geçirdiği günler zaten onun

Sen yaşa sen duy sen giy hep senin olsun

Zaten onun hiçbir şeyi olmadı ki

Olmaz senden başka bir şeyi

Yazıklar olsun bu günde sana

Yine senin olsun her şey...', 'Oniki mayıs anneler günü Ne büyük bir gün bugün Çocuk anasının koynunda Şefkatinin doruğunda Ana var ocağında niyazla Bekler yavrusunu umutl...', ARRAY['Türk Edebiyatı','Şiir','Akif Karakoca']::text[], 8.5, '{"poet":"Akif Karakoca","poet_slug":"akif-karakoca","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/oniki-mayis-anneler-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
