INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kum Tanesi', 'kum-tanesi-gencay-coskun-9ydg9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kum tanesi zamanlarda 

Yaşamak zordur aslında, 

Zaman kayıp gider

Ayaklarının altından.

Tutunur gidersin

Sözde bir yerlere

Eninde sonunda 

Dönersin yine kendine 

Kumdan tepeler, 

Kumdan kaleler

Kurarken hayatta

Hayat ne kadar 

Kısadır 

Aslında', 'Kum tanesi zamanlarda  Yaşamak zordur aslında,  Zaman kayıp gider Ayaklarının altından. Tutunur gidersin Sözde bir yerlere Eninde sonunda  D...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kum-tanesi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Kavga İsyan Kokar', 'her-kavga-i-syan-kokar-melih-coskun-d6j95', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir kokusu vardır hayatın

Burnunun direğini sızlatırcasına keskin 

Tüm ayrılıklar hüzün kokar

Tüm otogarlar, 

Tren istasyonları, 

Vapur iskelelerinde ayrılık,

Her kavga isyan kokar

Ve gelecek 

Bir kokusu vardır 

“Bizimle bitmez bu kavga” diye haykırmanın

İntikam kokusu zulmün dağlarında

Ve yüreğine aşk düşmeyenin duyduğu sadece

Çatlamış damarlardan sızan sıcak kan 

Bir kokusu vardır seni seviyorum demenin 

Fabrika bacalarının griye kesmiş dumanı

Ve yanık lastik kokusu

Sararken şehrin göğünü 

Kaplar geceyi güneyli rüzgarlarla

Yalnız kokusu yoktur ölümün 

Ölüm kokusuz 

Renksiz 

Sensiz 

Bensiz 

Ve aşksız...

22 Ocak 2003

01: 56', 'Bir kokusu vardır hayatın Burnunun direğini sızlatırcasına keskin  Tüm ayrılıklar hüzün kokar Tüm otogarlar,  Tren istasyonları,  Vapur iske...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/her-kavga-isyan-kokar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KAHPE AVRUPA (AHMİ KARARI DOLAYISIYLA)', 'kahpe-avrupa-ahmi-karari-dolayisiyla-erzurumlu-tokmakcibaba-yta4j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kahpe Avrupa’nın haline bakın

Haine hamilik adalet olmuş

Tüküreyim içine ben böyle çarkın

Puştluğun adı da asalet olmuş 

Bebek katiline şefkatmiş hukuk

Böylesine demek gerekir  guguk

Ne kadar var ise it ile kopuk

Türk’e engel, Türkiye’ye  set olmuş 

Daha kurumamış şehidin kanı

Yüreklerde yaşar binlerce anı

Kim katletti bunca günahsız canı

Caniliğin adı   hürriyet olmuş 

kimdir asrın kanlı katili: sorsak: 

“ Tek dişli canavar “  denilen  alçak..

haksız arar isen aynaya bir  bak

voyvodalık sana zürriyet olmuş

hele  bakın dostlar Türkün haline 

vermiş pak elini kimin eline

kahpe düşmanların hain dölüne

secde etmek bize marifet olmuş

silkin ey Türk oğlu, sen bu değilsin

sen eğilme namerde , onlar eğilsin

kaldır başın , dumanların dağılsın

utan, firengistan sana cet olmuş..

bırak uşaklığı beyliği dene

bu sene olmazsa bir başka sene

verme yularını  verheugene

tamam alametler, kıyamet olmuş

tokmakçım  kızıl elma çürük bu yıllar

o yüzden kelepçe yemiştir kollar

böyle sürmez ben eminim bu hallar

bakarsın Rabbim’den inayet olmuş! !', 'Kahpe Avrupa’nın haline bakın Haine hamilik adalet olmuş Tüküreyim içine ben böyle çarkın Puştluğun adı da asalet olmuş  Bebek katiline şefk...', ARRAY['Türk Edebiyatı','Şiir','Erzurumlu Tokmakçıbaba']::text[], 8.5, '{"poet":"Erzurumlu Tokmakçıbaba","poet_slug":"erzurumlu-tokmakcibaba","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kahpe-avrupa-ahmi-karari-dolayisiyla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Bir Gün', 've-bir-gun-murat-kilinc-y2bzm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zaman anlamını yitirmiş

Kelimeler ise yetersiz

Var olan tekşey umutlar

Birde dualar, 

Ve birgün umutlar yerini bulur, 

Ve birgün dualar gerçek olur, 

Ve bir kaç damla göz yaşı süzülür, 

Sonsuza kadar seni seveceğim', 'Zaman anlamını yitirmiş Kelimeler ise yetersiz Var olan tekşey umutlar Birde dualar,  Ve birgün umutlar yerini bulur,  Ve birgün dualar gerç...', ARRAY['Türk Edebiyatı','Şiir','Murat Kılınç']::text[], 8.5, '{"poet":"Murat Kılınç","poet_slug":"murat-kilinc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ve-bir-gun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Efkar', 'efkar-giray-ozer-66idh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gül efkarım derdime biçare olmaktan uzak

Hüznüme lokman, neyime nefes, meyime meze ol

Süreyyalar doldursun gökkubbeyi kirpiklerin kadar yakın

Gönlümün feri, zümrüt kadar yeşil, safir kadar mavi ol

Sinemi deldi geçti şu garip bülbülün figanı

Gel şimdi akşamın deli neharında derbeder ol

Ya gel sev beni ruhumla ebedi fermanım

Ya git bir an evvel başkasının ol

Neyleyim beni senden alan o vakti zamanı

Yağ gönlüme usul usul duama şükran ol

Hasret duyar bu gönül sana, derya kadar suskunum

Gözlerimde hülya, dudağımda buse ol', 'Gül efkarım derdime biçare olmaktan uzak Hüznüme lokman, neyime nefes, meyime meze ol Süreyyalar doldursun gökkubbeyi kirpiklerin kadar yakı...', ARRAY['Türk Edebiyatı','Şiir','Giray Özer']::text[], 8.5, '{"poet":"Giray Özer","poet_slug":"giray-ozer","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/efkar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdama', 'sevdama-unal-tuncel-encws', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni ben, öpmeğe doyamadığım

Dizine yeterince yatamadığım

Doyasıya sıkı sarılamadığım 

Anam kadar sevdim

Seni ben, türkülerimiz gibi sevdim

Derdimizi, tasamızı taşıyan

Kavgamızı, aşkımızı anlatan

Türküler kadar sevdim

Seni ben, sessiz, yılgın halkım gibi

Aç, çıplak bırakılmış halkım gibi

Ama gururlu, gözü tok halkım gibi

Seni ben halkım kadar sevdim

Seni ben Fırat gibi sevdim

Sevdam Fırat gibi

Fırat''ım sevdam gibi

Seni ben Fırat kadar sevdim

Seni ben o büyük ozan kadar sevdim

Nazım''ca şiirler yazmak isterdim sana

Sevdamı dökmek isterdim ak kağıtlara

Seni ben şiirler kadar sevdim

Seni ben Harput gibi sevdim.

Pambuğ ovaya bakan harput gibi

Gururlu, kendinden emin ve bulutlar üstünde

Seni ben Harput kadar sevdim

Seni ben kendim gibi sevdim

Yaşama ve kötülere eğilmeyen

Çıkarların peşinden gitmeyen

Sevgiye tapan, insana inanan

Seni ben benim kadar sevdim

Seni ben yaşam gibi değil, 

Seni ben yaşam kadar değil, 

Seni ben YAŞAM dan çok sevdim.

Haziran 2001Çengelköy', 'Seni ben, öpmeğe doyamadığım Dizine yeterince yatamadığım Doyasıya sıkı sarılamadığım  Anam kadar sevdim Seni ben, türkülerimiz gibi sevdim ...', ARRAY['Türk Edebiyatı','Şiir','Ünal Tunçel']::text[], 8.5, '{"poet":"Ünal Tunçel","poet_slug":"unal-tuncel","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/sevdama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rubai 3', 'rubai-3-cevri-yilmaz-x0f6o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşme, gafil nefsin peşine, 

Yıpratıp seni harcayacak.

Koşma, boş hayeller peşine, 

Birgün yüzüne bakmayacak.', 'Düşme, gafil nefsin peşine,  Yıpratıp seni harcayacak. Koşma, boş hayeller peşine,  Birgün yüzüne bakmayacak....', ARRAY['Türk Edebiyatı','Şiir','Cevri Yılmaz']::text[], 8.5, '{"poet":"Cevri Yılmaz","poet_slug":"cevri-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/rubai-3-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HER ŞEYİMSİN', 'her-seyi-msi-n-erkut-altug-ks2da', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bil ki sen, AYŞEGÜLSÜN

Sen  muhteşem bir büyüsün

Sen bir hayal, bir gerçeksin

Sen bir güneş, bir volkansın.

 Sen hem AYŞEGÜLSÜN, hem herşey-im

Bense kulun kölenim

Yolunda iz sürenim

Kapında bekleyenim

Aşkından kükreyenim

Yanında FESLEĞENİM

ÖZETLE her şey biraz AYŞEGÜL; 

AYŞEGÜLSE ZATEN HERŞEY.', 'Bil ki sen, AYŞEGÜLSÜN Sen  muhteşem bir büyüsün Sen bir hayal, bir gerçeksin Sen bir güneş, bir volkansın.  Sen hem AYŞEGÜLSÜN, hem herşey-...', ARRAY['Türk Edebiyatı','Şiir','Erkut Altuğ']::text[], 8.5, '{"poet":"Erkut Altuğ","poet_slug":"erkut-altug","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/her-seyimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AYŞEGÜL', 'aysegul-erkut-altug-8o8e1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Düşünemez oldum, 

Senden hriç herşeyi.

Gülemez oldum, 

Senden hariç her şeye.

Sensiz  olamaz oldum.

Senli de, sensiz de bir garip oldum.

Seni sevdikçe, daha çok sevecek, 

Seni sevdikçe daha çok diyecek oldum.

Sen bir gül oldun, 

Ben sana gülen.

Sen sen oldun, 

Ben seni seven.

Sen bir amaç oldun, 

Bir yaşam biçimi.

Sen benim öteki yarımdın

Sen ben oldun, 

Bense sen.

Artık bilmiyorum sen mi ben; 

Yoksa ben mi sen?', 'Düşünemez oldum,  Senden hriç herşeyi. Gülemez oldum,  Senden hariç her şeye. Sensiz  olamaz oldum. Senli de, sensiz de bir garip oldum. Sen...', ARRAY['Türk Edebiyatı','Şiir','Erkut Altuğ']::text[], 8.5, '{"poet":"Erkut Altuğ","poet_slug":"erkut-altug","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/aysegul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden Önce Severse', 'benden-once-severse-ceyhun-yilmaz-wq40x', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Acımdanmı bilemem, 

Yürüyemedim bu sabah

Çok sevdiğim sahili..

İçim sıkıldı bak şimdi..

Ya balıklarımı tutarsa birileri.. 

Ya martılarıma taş atarlarsa...

 Hepsinden önemlisi 

Ya benden önce biri görüp severse seni

KIRMIZI hırkanla o balkonda............', 'Acımdanmı bilemem,  Yürüyemedim bu sabah Çok sevdiğim sahili.. İçim sıkıldı bak şimdi.. Ya balıklarımı tutarsa birileri..  Ya martılarıma ta...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Yılmaz']::text[], 8.5, '{"poet":"Ceyhun Yılmaz","poet_slug":"ceyhun-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/benden-once-severse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasemin', 'yasemin-akgun-akova-ma2io', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'çimenlerin içinde bekledim seni sırtı dikenli bir böcek gibi

orkidelerin arasında, kara nanelerin, fesleğenlerin, 

kardelenlerin köklerinde

ve yapraklarında

	arıların ayak izlerini taşıyan gelinciklerin

sonra Yasemin, güzelim senin son yaprağın aşktı

aşktı aralık kapılara anlattığın

çıkıp gitmelerin aşktı

aşktı dönüp gelmelerin

sonra Yasemin güzelim

likenli kayaların üzerine adını yazdım

ve okuma yazma öğrettim kertenkelelere 

sersem gibiydiler, yeni uyanmışlardı  kış uykularından

sarı saçlarından söz edince onlara, 

	ilkbahardan dayak yedim

çünkü hem annen hem de babandı ilkbahar

allahtan arkadaşım yaz vardı, çok yakındaydı

	geldi beni kurtardı

yaşadığın bütüne vleri gezdim bir bir o yaz, 

ebene teşekkür ettim doğduğun evin bahçesinde

''bir zeytin dalına benziyordu elime aldığımda

sonra birden bir çiçeğe dönüşüverdi''

dedi ve sordu; 

''yeniden zeytin dalı mı oldu yoksa? ''

sonra Yasemin güzelim

taşbebeğine yeni elbiseler giydirdim

ahşabını kokladım merdivenlerinde bakıştığımız evin

ve bir avuç yem bıraktım havuzun yanına rdıç kuşalrı için

sonra Yasemin, güzelim

kendimi de bıraktım orda

yitirdiğim

ve yitireceğim bütün kadınlar için

sonra Yasemin, güzelim, senin son yaprağın aşktı

aşktı uçmak konmak

varmak ve dönmek aşktı

memelerinin arasından

bulutlara tırmanan

bir çocuk olarak duruyor aşk

bugün bile 

belleğimde', 'çimenlerin içinde bekledim seni sırtı dikenli bir böcek gibi orkidelerin arasında, kara nanelerin, fesleğenlerin,  kardelenlerin köklerinde ...', ARRAY['Türk Edebiyatı','Şiir','Akgün Akova']::text[], 8.5, '{"poet":"Akgün Akova","poet_slug":"akgun-akova","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/yasemin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lale', 'lale-akgun-akova-pcesu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'çantanda bir sürü anahtar var Lale

biri evinin

geceleri merdiveninden korkarak çıktığın

biri yalnızlığın, kalabalıklardan damıttığın

giysi dolabının biri

ki giysilerini sevmem

gizlerler güzelliğini

çantanda bir sürü anahtar var Lale

posta kutunun biri

sana dargın mı ne

biri saçının, örgüsü kolay çözülsün diye

arabanın biri

ah şu bitmeyen taksitler ve kasko! 

çantanda bir sürü anahtar var Lale

aşk mektuplarını sakladığın çekmecenin biri

epey eskimişler

öyle değil mi

biri uykunun

bazı geceler sıçramanla bölünen

şu yüreğe benzeyen anahtar nerenin

ne kadar da paslanmış

çantanda bir sürü anahtar var Lale

biri Ağrı Dağı''nın

hep tırmanmak istediğin

Salzburg kentinin biri

yüzlerce mozart seni çalıyor

biri dalgın bir nehrin

kucağında geçmelisin sevgilinin

Akdeniz kumsalının biri, 

ıssız ve mavi

çırılçıplak yüzen sen misin

çantanda bir sürü anahtar var Lale

ama açmıyor hiçbiri seni

açmıyor işte anla

kendini aşklara kapattığından beri', 'çantanda bir sürü anahtar var Lale biri evinin geceleri merdiveninden korkarak çıktığın biri yalnızlığın, kalabalıklardan damıttığın giysi d...', ARRAY['Türk Edebiyatı','Şiir','Akgün Akova']::text[], 8.5, '{"poet":"Akgün Akova","poet_slug":"akgun-akova","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/lale-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'PUSULAMDAKİ GÖL 1', 'pusulamdaki-gol-1-i-mdat-demir-mrm1c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sahne: 1

-iç ve/ya dış mekân-

şakağında uyuşmuş intihar izleri

gibi duran sıcak mı sıcak

yakarhayat

masalıyla çoğalan enfiye bir yaprak

boynu

ölümü çağıltan ince bir ırmak

düş ya da gerçek

K harfinin iki bacağı gerçek

düş ise arasında abanıyorolmak

insan düşen gerçek

ölüm iki bacağı olan gerçek

sahne: II

-açık ve kapalı mekan-

tül perde düşer benliğiyle arasına

kaybolur (o)  zaman çekilir dünyasına

iki üçlü bıçağı öfke ile bilenir

kanlanır sahici yaşamakla çiçekleri

ve köz vakitli sözleri

ince bir dil kıvrımında sallanır

bilir o zaman sahidenyaşıyorolmak

çıyanlardan tabutlar süslemektir

sahne: III

-yok mekânı-

genç bir kız geleceğini

-geleceksizliğini-

ıslak diliyle arar

arar arar arar

ve şair

kocaman bir elif’le

kendini

parçala(mış) tır', 'Sahne: 1 -iç ve/ya dış mekân- şakağında uyuşmuş intihar izleri gibi duran sıcak mı sıcak yakarhayat masalıyla çoğalan enfiye bir yaprak boyn...', ARRAY['Türk Edebiyatı','Şiir','İmdat Demir']::text[], 8.5, '{"poet":"İmdat Demir","poet_slug":"i-mdat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/pusulamdaki-gol-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Düşer Aklına', 'duser-aklina-yusuf-gencal-btpgp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gelir düşer aklına

Çoçukluğunun meyve ağaçları 

Salkım saçak dalda

Nasıl açarlardı tomurcuklarda

Oçakta pancar çorbasının

Buğulu kokusu

Sacın üstünde nar gibi

Kızarmış mısır ekmeği

Yayıkta köpük köpük

Ayranı ananın

Gelir düşer aklına

Çemberler topaçlar çevirdiğin

Patlangaçlar patlatıp

Misketler oynadığın

Derelerinde yüzdüğün

Tiril basmadan gömlek giydiğin

Nasıl mutluydun nasıl

Umrunda değildi

Yer döşeklerinde uyuduğun

Yalın ayaklığın salya sümük

15/04/2000k', 'Gelir düşer aklına Çoçukluğunun meyve ağaçları  Salkım saçak dalda Nasıl açarlardı tomurcuklarda Oçakta pancar çorbasının Buğulu kokusu Sacı...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Gençal']::text[], 8.5, '{"poet":"Yusuf Gençal","poet_slug":"yusuf-gencal","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/duser-aklina-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mesaj', 'mesaj-celalettin-algan-i5uon', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Benim de gözlerim vardı bir zaman

Ağaca kuşa denize sizinkiler gibi bakmış

Ayaklarım kaldırımlarınızda

İstanbulu kaderince yaşamış

Ayaklarım sizde kaldı

Gözlerim sizde

Ellerim vardı benim de 

Ki dost ellerinde el

Bölüştüğümüz kadehlerde ah

Dudağım dudak

Dudaklarım sizde kaldı

Ellerim sizde

Benim de düşlerim vardı denizli

Beyaz gemilerin yelkenlerinde

Bin parça olurdu kalbim

Binlerce yolun davetinde

Bütün yollar sizde kaldı

Gemiler sizde

Ben kurtuldum artık nefes almaktan

Her nefeste bir başka yaşamaktan

Can vermekten

Yok bir selâmım geceye güne

Bir beklediğim 954''ten

Çılgınlığım sizde kaldı

Selamım sizde', 'Benim de gözlerim vardı bir zaman Ağaca kuşa denize sizinkiler gibi bakmış Ayaklarım kaldırımlarınızda İstanbulu kaderince yaşamış Ayaklarım...', ARRAY['Türk Edebiyatı','Şiir','Celalettin Algan']::text[], 8.5, '{"poet":"Celalettin Algan","poet_slug":"celalettin-algan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/mesaj-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Her Limanda Bir Sevgili Olsa ya', 'her-limanda-bir-sevgili-olsa-ya-yusuf-gencal-bw4s4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uzaklardan

Bir çığlık gibi gelen gemi

Uğradığı her limanda

Gözleri üzüm karası

Kadınlar vardır kadınlar

Gecenin fahişe puştluğu

Kirletilen aşklar vardır aşklar

Herkesin herkesten korkusu

Para ve kadın kokusu

İnsanlığın açlık tortusu

Her limanda bir sevgili olsa ya 

Sevginin olmadığı bu pazarda

İki tık tık bir fık fik 

Bazen şişme bebek buz gibi

Esmer beyaz fark etmez

Alkolle karışık

Olur tatlı muz gibi

Sevdan kadını bulamazsın hiç

Çekip gitmek gelir içinden

Gidemezsin

Paslı bir yalnızlık

Bekler durur limanda seni

          

06.09.1997 k', 'Uzaklardan Bir çığlık gibi gelen gemi Uğradığı her limanda Gözleri üzüm karası Kadınlar vardır kadınlar Gecenin fahişe puştluğu Kirletilen a...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Gençal']::text[], 8.5, '{"poet":"Yusuf Gençal","poet_slug":"yusuf-gencal","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/her-limanda-bir-sevgili-olsa-ya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sersem', 'sersem-kadir-ozsoy-jmmer', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yufkadır annemin yüreği

Her sabah açar bana

Özene bezene

Doğan günün maviliğini

Bilse de 

Benim görmeyeceğimi

Uyku sersemi...', 'Yufkadır annemin yüreği Her sabah açar bana Özene bezene Doğan günün maviliğini Bilse de  Benim görmeyeceğimi Uyku sersemi......', ARRAY['Türk Edebiyatı','Şiir','Kadir Özsoy']::text[], 8.5, '{"poet":"Kadir Özsoy","poet_slug":"kadir-ozsoy","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sersem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hikaye-i Farzımuhal', 'hikaye-i-farzimuhal-abdurrahim-karakoc-qzt2e', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Lideri dese ki; ''evladım Hayri

Dört ayak üstünde yürü sen gayri''

Hiç itiraz etmez, bu emre uyar

Lider ne söylese ''hikmet var'' sayar

Takla atar, lider ''takla at'' dese

Yatar her çamura ''hadi yat'' dese

Lideri düşünür, Hayri düşünmez

Hayri liderlerinden ayrı düşünmez

Lideri karaya demiş ise ak

''Onun bir bildiği vardır muhakkak''

Aklı yok, beyni yok mazurdur Hayri

Kula kulluk için hazırdır Hayri

''Keramet'' hükmünü verir zırvaya

Emin adımlarla yürür zirveye

Lidere sarılan sarmaşık Hayri

Biraz bencil, biraz karmaşık Hayri

Tek gayesi makam, artı menfaat

Lider basamaktır, parti menfaat

Emeline vasıl olursa Hayri

Umut ettiğini bulursa Hayri

Kendine münasip köleler seçer

Açar tekkesini irşada geçer

İki ayak üzre yürür artık O

Sırrı bilir, gaybı görür artık O

Dalkavukluk böyle verir semere

Bundan sonra eşek biner semere.

(Akıl Karaya Vurdu)', 'Lideri dese ki; ''evladım Hayri Dört ayak üstünde yürü sen gayri'' Hiç itiraz etmez, bu emre uyar Lider ne söylese ''hikmet var'' sayar Takla at...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/hikaye-i-farzimuhal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-i-brahim-agah-cubukcu-vs7eo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hem tokluk var, hem de açlık

Gözlerimiz aç olmasın

Kıyametle gelir hiçlik

İçimizde hiç olmasın

Gerçekleri doğru görmek

Sevgi ile Hakk''a ermek

Karış karış hesap vermek

Ahirette güç olmasın

Sen kendinde ara seni

Hakk''a yönel unut beni

Erdem ile süsle teni

Vicdanında suç olmasın

Bu dünyanın boştur ünü

İyi öğren gerçek dini

İsteyerek bırak kini

Yüreğinde öç olmasın

Vurguncunu sinsi eli

Çıkarcının tatlı dili

Bahçemizde elin gülü

Başımızda taç olmasın

Havası var yazın, kışın

Kusur arar senin başın

Uymalıdır için dışın

Bir gün vakit geç olmasın', 'Hem tokluk var, hem de açlık Gözlerimiz aç olmasın Kıyametle gelir hiçlik İçimizde hiç olmasın Gerçekleri doğru görmek Sevgi ile Hakk''a erme...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Agah Çubukçu']::text[], 8.5, '{"poet":"İbrahim Agah Çubukçu","poet_slug":"i-brahim-agah-cubukcu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dilek-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-i-lhan-sahinoglu-sk16m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Geceler gözyaşıdır, 

şiirdir, ayrılıktır, acıdır

herkesin olabildiği tek şeydir

hiçkimse olmamaktır 

kendin olmaktır geceler.

Bazen bir yıldız şehri

kışları yağmurların üzerinde kurulu

bazen bir rüya

hiç olmadığı kadar gerçek

iki dudağın arasında fısıltıdır geceler

iki sevdanın arasında yanılgı

bir kalemdir gece 

yazdığı harf adedince

bir kağıttır gece

kalem üzerinden geçtiği sürece', 'Geceler gözyaşıdır,  şiirdir, ayrılıktır, acıdır herkesin olabildiği tek şeydir hiçkimse olmamaktır  kendin olmaktır geceler. Bazen bir yıld...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şahinoğlu']::text[], 8.5, '{"poet":"İlhan Şahinoğlu","poet_slug":"i-lhan-sahinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gece-66-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman zaman zaman', 'zaman-zaman-zaman-i-lhan-sahinoglu-t2lp1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eskiten ama eskimeyen 

o anlamsız kara yutan

bana vereceğin sonu

ellerimde eskimiş baharlardan kalan

küf kokulu güllerle

bana vereceğin sonu

gözlerimde kamaştırıcılığını yitiren 

pırıltıları eskimiş yıldızlarla

bana vereceğin sonu

saçlarımda üşüdüğümü hatırlatan

soğuk kışların biriktirdiği beyazlarla

bana vereceğin sonu

bedenimde kocalmışlığımı ilan eden 

çaresiz halsizlikler ve yorgunluklarla

bana vereceğin sonu

kalbimde ne yeri dolan nede unutulan 

birkaç insanın

doyamadığım sevgilerinin hasretleriyle

bekliyorum.', 'Eskiten ama eskimeyen  o anlamsız kara yutan bana vereceğin sonu ellerimde eskimiş baharlardan kalan küf kokulu güllerle bana vereceğin sonu...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şahinoğlu']::text[], 8.5, '{"poet":"İlhan Şahinoğlu","poet_slug":"i-lhan-sahinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/zaman-zaman-zaman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-i-lhan-sahinoglu-pqeow', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akıyor zaman 

ilerliyor zaman 

geçiyor zaman

bir gerçek var ki

hiç yorulmuyor 

hiç durmuyor zaman

bilmiyorum

kimsede bilmiyor 

neye uzandığımı

nereye uzandıklarını

birşeyler yitiyor

yaşanıyor ve bitiyor

gerçeklerden kuruluyor 

yaşanan yalanlar

ve hatırladığım onlar oluyor

yani 

geride kalanlar.', 'Akıyor zaman  ilerliyor zaman  geçiyor zaman bir gerçek var ki hiç yorulmuyor  hiç durmuyor zaman bilmiyorum kimsede bilmiyor  neye uzandığı...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şahinoğlu']::text[], 8.5, '{"poet":"İlhan Şahinoğlu","poet_slug":"i-lhan-sahinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/zaman-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bebek Ağlıyor', 'bir-bebek-agliyor-salih-ozalasan-y3lai', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bebek ağlıyor

İki gözü iki çeşme

Daha diyemiyor, ne baba

Nede neredesin, gel anne

Yıkılmış her yer olmuş harabe

Yığılıp kala kalmış

Bebeğine süt verirken

Bahtı kara bir anne

Şarapnel parçaları saplanmış

Yavrusu yerine göğsüne, sinesine

Ağlıyor zavallı bebek

Ne bilsin zamansız ölüm gelmiş

Bir cani elinden annesine

Belki de hiç bilmeyecek

Bir litre petrol uğruna 

Katledildiğini annesine

Bir ömür hasret kalacak

Onun tatlı sesine, sıcak sevgisine

Ağlıyor ya şimdi kim bilir

Belki çok az kaldı onunda ölmesine

Ya açlıktan, ya susuzluktan

Yada bir ateş topunun düşmesiyle

Bu ne ilk ne son olacak

Daha ne bebekler, ne anneler

Yok olup gidecek ülkesiyle

Petrol içen caniler

Daha ne canlar alacak

Ülke kurtarma bahanesiyle

Bir gün sıra onlara da gelecek

Boğulacaklar dilerim petrol denizinde

Dolardan mezarlarda, kızgın lavlarla

Eriyecek bedenleri, 

Hesabını verecekler mahşerde

Ağlama minik bebek ağlama

Duyamaz seni güzel annen

Artık onun ruhu seninle

Bedeni makber de

Sağ kalırda büyürsen ibret al

Yazdır bu savaşı tarihe

Güçlü olanlar vermez hesap

Koruma bahanesiyle ezdiklerine

Ama tarih; ama tarih

Bir gün hesap soracak sizlere

Y.Tarihi 12+13-03-2003

Salih ÖZALAŞAN', 'Bir bebek ağlıyor İki gözü iki çeşme Daha diyemiyor, ne baba Nede neredesin, gel anne Yıkılmış her yer olmuş harabe Yığılıp kala kalmış Bebe...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/bir-bebek-agliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zalim', 'zalim-i-lhan-sahinoglu-bq2jr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yolar çizdim sana 

yüreğimdeki özlemlerden

gelmeyişlerine inat

çocuklar gibi

unutkan oluşuna kızdım

hiç arayıp sormadığın 

aklıma geldiği zamanlar

sonra 

sanamı yazıyorum 

bir ikincinin okumadığı

sonu gelmez şiirlerimi

yoksa bir ölüyemi 

anlamış değilim.', 'yolar çizdim sana  yüreğimdeki özlemlerden gelmeyişlerine inat çocuklar gibi unutkan oluşuna kızdım hiç arayıp sormadığın  aklıma geldiği za...', ARRAY['Türk Edebiyatı','Şiir','İlhan Şahinoğlu']::text[], 8.5, '{"poet":"İlhan Şahinoğlu","poet_slug":"i-lhan-sahinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/zalim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Simdi hepsi yalan!', 'simdi-hepsi-yalan-selma-unsal-o1qj2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne cabuk gecti o güzelim günler.

Ne cabuk tükendi bütün ümitler.

Hic unutulmayacak sözler, 

daim kalacak tüm degerler, 

bir ömürboyu acacak güller.

Simdi hepsi yalan, hepsi soldu birer birer! 

Ben senin günesin, 

sense benim fenerim.

Birbirimizin isigi, 

icimizin issitigi, 

bir can, bir yürek, bir bedendik.

Simdi hepsi yalan, hepsini yitirdik! 

Nasilda uzakti ayrilik bize.

Gönlümzde sadece sevgimizle, 

yüregimizde sadece günesimizle, 

dudaklarimizda hasret türkülerimizle, 

icimizde yanan büyük özlemimizle, 

sevmistik birbirimizi delicesine.

Simdi hepsi yalan, hepsi yasanmis öylesine! 

Artik sadece kara gözlü degil, 

kara bahtli oldugumuda anladim.

Ilk defa böyle candan yandim.

Sen benim icine son sevdigim, 

son özledigim, 

son sayikladigim, 

son agladigim, 

beni tamamlayabilecek son insandin.

Simdi hepsi yalan, hepsi mazimde yansin! 

Korktugum basima geldi! 

Sana baglanmaktan, 

sensiz olamamktan, 

hayatmin tüm anlami olacagindan, korkuyordum.

Korkuyordum bu rüyadan uyanmaya, 

ebedi bir kabusda yasamaya.

Korkuyordum sana simsiki sarilmaya, 

birakip gittiginde arkandan aglamaya.

Simdi hepsi yalan, hepsi mahkum unutulmaya! 

Sana güvenip kalbimi ellerine biraktim.

Inan bu cileli oyunlardan biktim.

Geldin bana son kursunu siktin, 

icimde kapanmayacak yaralar actin.

Anladim simdi asil yalan olan yasananlar degil, 

sana besledigim tüm duygular yalan degil.

Yalan olan tek sey var yildizim, 

Yalan olan sensin üzgünüm.

Nasil günes icin yildiz, 

yildiz icinde günes yalan, 

iste sensin bundan sonra böyle anilan!', 'Ne cabuk gecti o güzelim günler. Ne cabuk tükendi bütün ümitler. Hic unutulmayacak sözler,  daim kalacak tüm degerler,  bir ömürboyu acacak ...', ARRAY['Türk Edebiyatı','Şiir','Selma Ünsal']::text[], 8.5, '{"poet":"Selma Ünsal","poet_slug":"selma-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/simdi-hepsi-yalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Ölelim', 'hadi-olelim-orhan-koldas-uhue6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Firari uçurumlar diyarındayım

Sürgün bir deniz yolculuğunda

Mor entari giyinmiş balıklar

Kamçılıyordu ellerimizi

Uyanmamış gecelerde

Yitirmiştik arkadaşlarımızı

Kaç kişiydik

Hep kaçları oynuyorduk? 

Kalplerimiz ürküyordu karanlıklardan

Küllerini savuruyordu

Yokluklar...

Yoklukları soluyordu gözlerimiz

Umudumuzun sürgününde

Çığlıklarımız esir düşmüş

Ruhlarımız tesellisiz

Önce volkan oluyoruz

Tenhalaşıyoruz sonraları

Topraklarımız boğuyor

Gaflet sarmış aşklarımızı

Böyle mi yaşanırdı? 

Böyle mi ölünürdü? 

Oysa ne kefenler giydirdik tarihe, 

Ne ateşler yaktık hasretimizle...

Kurtulamıyoruz işte, 

Kurtulamıyoruz.

Çapraz ateşlerin yatağında, 

Mahçup oluyoruz, 

Acılarla örtünüyoruz.

İşte yine bir sabah, 

Başka bir firari ölüm, 

Başka bir kırık dal...

Ne kolay arkadaş, 

Göçüp gitmek.

Dağlarımızda yas, 

Ovalarımızda ağıt, 

Ve umudu kırık bir ana...

Dönsün semahlarımız, 

Meçhul bir adres bekliyor.

Hadi bu sabah ölelim, 

Kalsın sesimiz...

Yarın sabahta ölelim, 

Kalsın...

Kalsın şerefimiz.', 'Firari uçurumlar diyarındayım Sürgün bir deniz yolculuğunda Mor entari giyinmiş balıklar Kamçılıyordu ellerimizi Uyanmamış gecelerde Yitirmi...', ARRAY['Türk Edebiyatı','Şiir','Orhan Koldaş']::text[], 8.5, '{"poet":"Orhan Koldaş","poet_slug":"orhan-koldas","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/hadi-olelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KUŞLARA BENZEMEMEK', 'kuslara-benzememek-mustafa-ercin-9mfam', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'günü ekmek gibi bölelim ortasından

yoksul bacaların dumanları tütsülesin şehri

gözlerin, tavanda iki kardeş örümcek 

gezinsinler, unutmuşken ağının üzerimde kaldığını

zamanı, kirpiklerin boyasın

palyaço resimleri  çizsin duvarlarına

bana gül, hüznü unut...

köprüleri keselim, su özgürlük demek

havadaki turna, gölde balık

sözünü tut...

şehir, sevincinden ağladı bu gece

kağıt uçaklar, dallarda sırt bezi

şenlik var! 

hamam yorgunu kadınlar gibi ağaçlar

derin düşünme canım

kuşlar ıslakken de uçar...

günün gündüz yarısı benim 

kuzey rotasında kutba kadar yıldız kovalamışım

yarım uyku saymışım dalgınlığımı

sayıklamak, uykunun canlı hali deme 

gülerim, kasıklarım ağrır...

yorgun karşılasam da olur sabahı

derim ki, saatin dar bölgesine sıkışmış kum

mevsim çarptı yalanım susturur insanları

düşünce aralarında tamlanır uykum

yer kesilmiş sus...kulakları dışarda, duyarlar

gök, bayram telâşındaki terzi masası

gri delisi bulutlar, dikişe hazır parça kumaş

iplik pazarda, şimşekler getirecek 

yirmi pare yıldırım parmaklarımız

aşırmışız ağır makası, suspusken masa

olağan kurdelâsını kesmişiz yaşamın

olağanüstü güzellikler tahta kapının ardında

menteşeler gıcırdamasa...

şehir düşünceli elbet

ıslak yer

çirkin yüzüne tutulmuş kirli ayna

boş ver canım 

yorgan yastık bize gerek

kuşlar, gözleri kapalıyken de tüner...', 'günü ekmek gibi bölelim ortasından yoksul bacaların dumanları tütsülesin şehri gözlerin, tavanda iki kardeş örümcek  gezinsinler, unutmuşken...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Erçin']::text[], 8.5, '{"poet":"Mustafa Erçin","poet_slug":"mustafa-ercin","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kuslara-benzememek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HİÇ BİLMEDİN Kİ', 'hi-c-bi-lmedi-n-ki-mustafa-ercin-aanrd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'HİÇ BİLMEDİN Kİ...

    

Hiç bilmedin ki, 

Ne hisseder ve ne düşünürüm.

Duvarlar bile, 

Bir çırpıda ezberlemişti, 

Senin anlamadıklarını. 

Kuru yeşil, 

Ve ayaz ayaz bakarken gözlerime, 

Hiç düşünmedin ki, 

Kırağı düşer de göz bebeklerime, 

Üşürüm.

Hiç bilmedin ki, 

Nereye bakar ve neler konuşurum.

Her gün tepemden bakan, 

Tavan bile insafa gelmişti.

Yeşil bir “ufo” gibi, 

Yırtarcasına karanlığı, 

Uğrayıp geçtiği anlarda bakışlarının, 

Hiç anlamadın ki, 

İçimdeki ümit dağlarının, 

Toz duman olup, 

Ufalandığını.

Hiç bilmedin ki, 

Neyle sevinir ve neyle üzülürüm.

Üzerine oturduğum koltuk bile, 

Hislerimin ağırlığından olacak, 

Halimi pek kolay bilmişti.

Eylül yağmurları yağdırıp 

Yeşertirken gözlerimi, 

Hiç çiçek açtırmadıki bahar bakışların, 

Şöyle zambak zambak.

İlk olmak ve nisanca yağmak varken gönlüme, 

Hep sonbahar olurdun.

Bilmem, saçlarınca sarı, 

Bakışlarınca ayaz, 

O sonbaharlarda ne bulurdun? 

Hiç bilmedinki…..', 'HİÇ BİLMEDİN Kİ...      Hiç bilmedin ki,  Ne hisseder ve ne düşünürüm. Duvarlar bile,  Bir çırpıda ezberlemişti,  Senin anlamadıklarını.  Ku...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Erçin']::text[], 8.5, '{"poet":"Mustafa Erçin","poet_slug":"mustafa-ercin","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/hic-bilmedin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günlük Turfanda Hayaller', 'gunluk-turfanda-hayaller-mustafa-ercin-6xdxk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün vereceğim sana

Aydınlığı olmayan, gecesiz

Sur üflenmiş gibi evrenin uykuya daldığı

Dolu dolu benle olacağın bensiz

Artık günlerden biriktirdiğim

Takvimlerden gizli

Gözlerde susayıp, dudaklarda doyacağın

Sana saklanmış 

Başkalarının yok saydığı bir gün

Adını gülümseyerek koyacağın...

Sana bir gün vereceğim

Bir gün... kuruttuğun güller içinde taze

Nü renkli, büsbütün giz

Yolların  ıssız, yolcuların sessiz olduğu

Ve ardımız ayak izsiz

Hülyanın ufuk çizgisinde gerçekle seviştiği

Kuzeyin alçak basıncına sıkışıp

Batıya sığındığında doğu...

Sana bir gün vereceğim

Günlüğümüzün ilk sayfasının yazılacağı

Bir gün, ne yazık

Hayal mahsulü büsbütün...', 'Bir gün vereceğim sana Aydınlığı olmayan, gecesiz Sur üflenmiş gibi evrenin uykuya daldığı Dolu dolu benle olacağın bensiz Artık günlerden b...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Erçin']::text[], 8.5, '{"poet":"Mustafa Erçin","poet_slug":"mustafa-ercin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/gunluk-turfanda-hayaller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SİTARE...', 'si-tare-mustafa-ercin-zkkpr', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'aşikâre, 

söylenmeyen şeyler vardı, 

aramızda.

hani kenetlenirdi de, 

ağız, 

yıldız kaymışcasına, 

yalayıp geçerdi ya, 

gözlerini.

öylece dillendirirdi ya, 

bakışlarım, 

anlayamadıklarını.

o kara yağız, 

düşüncelerdeki pervasızlık, 

dil ucunda, 

pek ağırbaşlı oluyordu, 

Sitare, 

ya da zincirleniyordu, 

akıl neferlerince..

yüz bir pare, 

top atışı mı gerekirdi, 

duyurmaya bir şeyleri? 

hiç görmedin mi, 

gözlerinde patlattığım, 

maytapların parıltılarını? 

“göz okumayı  bilmem ki? ”

diyorsun.

anlıyorum Sitare, 

anlıyorum.

cam gerisinden, 

kaktüsü bile menekşe görürdün de, 

papatyayı papatya, 

gülü gül görmezdin hiç.

ya ne görürdün, 

bana baktığında? 

- biçare ha? 

bak ki kadere, 

“en uzaklarda bir yıldız” 

demiştin bir gün, 

sormuştum da adını.

kadınca güzelliğine dalıp, 

yürekce yaklaşırken sana, 

usulca, 

sen, 

adınca, 

ve doludizgin uzaklaşırdın, 

ay olmayı, 

yıldız olmayı denerdim de, 

yanı başında durmak için, 

olamazdım Sitare.

hep karanlıkta kalırdım, 

o yüzden.

sen pırıl pırıl ışırken, 

en uzaklarda; 

yalnızca, 

gece olmak kalırdı  bana, 

ve kararmak, 

ne çare.. 

o kadar çok  benziyorsun ki, 

yüreğimdekine.

o kadar andırıyorsun ki onu.

sen o’ sun aslında Sitare, 

o sensin.

ya ben kimim?', 'aşikâre,  söylenmeyen şeyler vardı,  aramızda. hani kenetlenirdi de,  ağız,  yıldız kaymışcasına,  yalayıp geçerdi ya,  gözlerini. öylece di...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Erçin']::text[], 8.5, '{"poet":"Mustafa Erçin","poet_slug":"mustafa-ercin","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/sitare-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR İSTANBUL MASALI..', 'bi-r-i-stanbul-masali-mustafa-ercin-eoark', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'BİR İSTANBUL MASALI..

Sağ elim..kristal asalı

Dokunduğum hayal, al basmış yanaklarınla sen

Çelik kancaymış meğer, sol elin

Ayrılık..gönlüme ansızın düşen bir korsan baskını..

Son kırkikindi belki şu yağmur

Gökkuşağı son mahya, semalarda

Renkli akvaryumundan dökülüyor gibi Marmara

Ayaklarımda bir lâcivert serinlik

Bir sarı meltem başımda

Kulağımda son vapurun ürperten düdüğü

İstanbul.. rüya şehir

İstanbul.. kalabalıklar içinde mahşeri yalnızlık

Sevginin can çekişe çekişe öldüğü..

Yüreğim çoktan “Ankara Karşılaması” yollarda

Günlerden, ne yazık ki Salı

Çok olmadı diyorum hani, gittiğin

Ama sen..şimdiden bir İstanbul Masalı..

Ortalıkta bir ölüm sessizliği..sen susalı

Kulağımda med-cezir çınlayışlar

Martı çığlıkları, kumru fısıldayışları 

Saçların, hüzün küremde sarı tül

Bir büyücü kehaneti, seni görmüşlüğüm

Tulumbacıların külhanbey koşuşturmaları

Eyvah..ahşap yüreğinde yalı yangınları

Gövdem boydan boya Marmara

Kollarım Heybeliada, omuzlarımda

Boğazımda adın, düğüm düğüm

Üzerimde, bir Kumkapı sarhoşluğu

İçimi hafakanlar basalı..

Az giden senin, uz gitmişliği

Gökten bir türlü düşmeyen elmalar

Ve sen..hâlâ bir İstanbul Masalı..', 'BİR İSTANBUL MASALI.. Sağ elim..kristal asalı Dokunduğum hayal, al basmış yanaklarınla sen Çelik kancaymış meğer, sol elin Ayrılık..gönlüme ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Erçin']::text[], 8.5, '{"poet":"Mustafa Erçin","poet_slug":"mustafa-ercin","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bir-istanbul-masali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ümidim! !', 'umidim-gulay-atilay-x8vue', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İçime sığmayan, benliğimden taşan sevgin var yüreğimde. Uzakta olsanda anılarla avunduğum, heran beynimde koşuşturup duran anılarla varolduğum o yüce sevgin var. Üzerinden dalgalanmalar geçsede, bazı zamanlar bastırıldığı sanılsada gerçek ve ölümsüz sevgin var taa... içimde. Kendimi ölüme yakın hissettiğimde, boşluğun tam ortasına düştüğümde, yediğim darbelerden kalkamaz hale geldiğimde, karanlıklarda yaşadığımda, bir kalem ve bir kağıtla ağladığımda, bana güç ve destek veren sevgin var yanımda. 

En uzaktayken de en yakındayken de kavuruyor içimi sevgin.. Hiç bir zaman sakinleşmeyen aksine, aksine gittikçe büyüyen fırtınasın zihnimde, duygularımda, hayatımda.Sen gerçek aşkım, gerçek büyümsün benim. 

Ben artık ben değilim.Tamamen seni yaşıyorum. Dışardan güçlü ve berrak gözüksemde aslında karmakarışık, bulanık ve sevginle zayıf düşmüş haldeyim. Sen varsın her yerde. Sürekli anılar var zihnimin içinde, gözlerim ise değil kapalıyken, açıkken bile o can alıcı bakışlarını görüyor. Dünyamda tek sen varsın tek başına....

Sonra birden ''hayır''lar ''olamaz''lar, ''olmamalı''lar geliyor aklıma, pürüzler hatalar, engeller geliyor önüme. Bütün bunlar yaralıyor. Neden sevgini dizginlemedin diyor. Ama tüm bunlara rağmen seviyorum diyorum, tüm zorluklar, tüm sıkıntılar, tüm sorunlara rağmen benim olmanı, ölene dek seni yaşamayı istiyorum seninle birlikte! ! ! . Bütün karşı çıkan sebeblere rağmen hissettiklerim değişmiyor. Bana en büyük mutluluk ve huzuru veren erkeğimsin, sevgilimsin. Hayatta hiçbir zaman olmadığı kadar azimliyim. Sana layık olabilmek, hakettiğine ulaşmana yardımcı olmak amacıyla; hayatta seni istediğim için ilk kez bu kadar hırslı, ilk kez bu kadar kararlıyım dönmemecesine. ilk kez düzen kurmayı planlıyorum kendimce hayata dair. Mutluluğa dair. Mutlu olup mutlu etmeğe dair. 

Bunca darbeden sonra kötümser hayatımda bir ışıksın. Ben isteksizcede olsa ilerlerken yardım eden, önüme ışık tutan, aydınlıksın. Umudumu yitirdiğim bu kötümser hayatımda, seni görmek, seninle olmak, anılara daha özel ve güzellerini, ekleme umudunu büyüttüm içimde ve ona gözüm gibi bakıyorum. Bunun için herşeyi yoluna koyup bu uğurda yaşıyorum...

Gerçekten ''O'' Sun.Hayatta herşeyimi paylaşmak istediğim, sevmek ve sevilmek istediğim, yaşanılabilinecek mutluluklar ön plana çıkınca vazgeçmek istemediğim, kaybetmekten korktuğum Sevgilimsin. Seni Seviyorum. Eğer ipuçları doğruysa seninde beni sevmenden, gurur duyuyorum. Umarım benim kadar çok seviyorsundur. Kendi hayatımdaki herşeyi ve senin hayatını paylaşmak istiyorum.Seni Seviyorum çünkü sen benim desteğimsin, aşkımsın, en doğru kararımsın, hırsımsın, umudumsun, ÜMİDİM''sin herşeyimsin, çünkü sen benim için ''O'' SUN! ! ! Gel gittiği yere kadar yaşayalım.

SENİ ÇOK SEVİYORUM ÜMİDİM! ! ! 

19/ARALIK/2002

Umarım sonsuza dek yaşatacağız 07/Şubat/2003              evlendik....', 'İçime sığmayan, benliğimden taşan sevgin var yüreğimde. Uzakta olsanda anılarla avunduğum, heran beynimde koşuşturup duran anılarla varolduğ...', ARRAY['Türk Edebiyatı','Şiir','Gülay Atilay']::text[], 8.5, '{"poet":"Gülay Atilay","poet_slug":"gulay-atilay","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/umidim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hacer''in Ağlaması', 'hacer-in-aglamasi-turgay-akbulut-exnho', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gülen bir yüz

İki damla gözyaşı

Aynı anda çıktılar padoktan

Aynı anda atbaşı

Güneşli bir günde

Korsan bulutun

Korsan damlaları gibi

Korsan tebessüm 

Korsan gözyaşı

Aynı anda atbaşı

Hacer''in ağlaması; 

Hislerin çaktığı Flaş

Hislerin Resmi... 

(mayıs2001)', 'Gülen bir yüz İki damla gözyaşı Aynı anda çıktılar padoktan Aynı anda atbaşı Güneşli bir günde Korsan bulutun Korsan damlaları gibi Korsan t...', ARRAY['Türk Edebiyatı','Şiir','Turgay Akbulut']::text[], 8.5, '{"poet":"Turgay Akbulut","poet_slug":"turgay-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hacer-in-aglamasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cehennemlikim', 'cehennemlikim-turgay-akbulut-xqq7o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen yoksan, baharımda yok, 

Soldu çiçeklerin

Sen yoksan, yazımda yok, 

Güneş girmez içeri

Yokluğun karakış gibi, 

Kaplar yüreğimi

Uykusuz gecelerim, yastıksız başım

İçerisi buz gibi

Sen yoksun...sen yoksun...

Sen yoksan bende yokum

Gittiğin yerde; 

kokla gülleri, 

Benim için

Almazlar beni oralara! 

Ben Cehennemlikim...

(ocak 2002)', 'Sen yoksan, baharımda yok,  Soldu çiçeklerin Sen yoksan, yazımda yok,  Güneş girmez içeri Yokluğun karakış gibi,  Kaplar yüreğimi Uykusuz ge...', ARRAY['Türk Edebiyatı','Şiir','Turgay Akbulut']::text[], 8.5, '{"poet":"Turgay Akbulut","poet_slug":"turgay-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cehennemlikim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ilkbahar havasından', 'ilkbahar-havasindan-yasar-aksit-ol092', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dinlemez ruhumu ey aziz kalp

ne var bu aşkta? 

rahat burak yüreğimi

bozma bu ölüm sesizliğimi...

yakma benim gözlerimi, 

gecenin aleviyle yakma bedenimi...

ağlatma yüreğimin bebeğini, 

kandırma kalbimin nedenini...

aldırma ey gönlüm sen yoluna bak, 

özgürlüğün peşinden koşma, 

nereye kadar aziz sevgi? ? 

nereye kadar ağır hafiflik? ? 

bu güller senin için...

hüzünlü bir ilk bahar havasından, 

sen gülümse daima son bahar

tadını çaıkar hayatın sıra sanada gelecek...

bükme boynunu şanlı eylülüm...', 'dinlemez ruhumu ey aziz kalp ne var bu aşkta?  rahat burak yüreğimi bozma bu ölüm sesizliğimi... yakma benim gözlerimi,  gecenin aleviyle ya...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Akşit']::text[], 8.5, '{"poet":"Yaşar Akşit","poet_slug":"yasar-aksit","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ilkbahar-havasindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatirlar misin?', 'hatirlar-misin-huseyin-hacioglu-6qeae', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seninle zamanlarin en ölmezini yasamistik

En uzak çemberini çizmistik mutlulugun

En uzak mesafelere aski tasimistik beraberce

Hatirlar misin? 

Yagmurlar yagdirmistik en kurak mevsimlerde

Boy boy umutlar büyütmüstük içimizde

O ne özlemlerdi gözledigimiz

Hatirlar misin? 

Bir sarkimiz vardi ki en içlisiydi sarkilarin

Siirlerim vardi, sana okurdum misra misra

Ve sonra göz göze gelirdik

Hatirlar misin? 

Sen bensiz, ben sensiz az mi agladik? 

Az mi kaçtik ayriligin gölgesinden

Tanriya kaç geceler avuç açtik

Hatirlar misin? 

Ve neden sonra sarardi yapraklari mutlulugun

Ve neden bir bir kuruttuk umutlari, özlemleri

Oysa bir agaçtik dal dal; çiçek açan, meyve veren

Hatirlar misin? 

Öyle ya bir kara tren ayirmaya yetti

Bir mendil bile sallayamadim ardindan

Öyle yalniz, öyle sessiz kaldim ki

Hatirlar misin? 

Simdi bos vagonlarda seni ariyorum

Anilari yasiyorum yeni bastan

Elimde degil; seni hatirliyorum

Bilmem sen de beni 

Hatirlar misin? ...', 'Seninle zamanlarin en ölmezini yasamistik En uzak çemberini çizmistik mutlulugun En uzak mesafelere aski tasimistik beraberce Hatirlar misin...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Hacioglu']::text[], 8.5, '{"poet":"Hüseyin Hacioglu","poet_slug":"huseyin-hacioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hatirlar-misin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'akşam hüznü', 'aksam-huznu-sitki-dursel-5n44f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'bir akşam düşünki yaz olsun

karanlık çöksün erkenden, 

kuşlarda bir çılgınlık

rüzgarın esintisi, 

vursun yüzüne güneyden

bir sıgaran olsun yarılanmış, 

açık demli bir bardakda çay

dilinde ezgilerden eski bir fasıl

hüzün otursun gözlerine

eski günlere ağlama vakti bu an

aşklar dostluklar 

artık çok geride kalmış

yaprak sesleri gelsin kulaklarına, 

rüzgar üşütmeye başlasın seni. 

fasıldaki mağmelerin başıboş, 

sıgaranın da bitmeye niyeti yok gibi

çay olmuş zehir, 

çay olmuş katran.

dalmış gitmişsin maziye

şimdi yalnız bir potre 

şimdi öylesine garib

ve bir okadarda pişman

yığınlar ortasında

kocaman bir adam

eyvah demek vakti, 

gelmiş demektir, 

hazırlan.', 'bir akşam düşünki yaz olsun karanlık çöksün erkenden,  kuşlarda bir çılgınlık rüzgarın esintisi,  vursun yüzüne güneyden bir sıgaran olsun y...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Dürsel']::text[], 8.5, '{"poet":"Sıtkı Dürsel","poet_slug":"sitki-dursel","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/aksam-huznu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Ve Gül', 'biz-ve-gul-kamil-colak-jbmjx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gideriz vay be vay 

Onu vurdular bülbüle matem düştü

Yaralı bir sesti yüzlerimize çarpan

Yüzlerimiz soldu, onu vurdular

Bülbüle matem düştü

Mayıs saçlarında açsam ellerimi

Vurulurum vurulurum her damarımdan

Taşları yumuşatan yağmurlar yağar

Bense kanımdan kırmızı elifler çıkartırım

Elifler endam olur renk olur, 

Gül ile gelen kırmızı, beyaz ve pembe.

Kime ne olmuş vay be vay 

Karlar yağarken yağmura ne olmuş

Aradım leziz şarabımı mahzenimde kaybolmuş

Şimdi o köşelerden geçerken ellerim dillenir

Bana gül getiren çocukları görür okşarım

Kime ne olmuş vay be vay 

Güle ne olmuş, bülbüle ne olmuş', 'Gideriz vay be vay  Onu vurdular bülbüle matem düştü Yaralı bir sesti yüzlerimize çarpan Yüzlerimiz soldu, onu vurdular Bülbüle matem düştü ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Çolak']::text[], 8.5, '{"poet":"Kamil Çolak","poet_slug":"kamil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/biz-ve-gul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneş Eğlenmez Gözlerinde', 'gunes-eglenmez-gozlerinde-kamil-colak-z4qus', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneş  eğlenmez gözlerinde

Sonra tutunursun dillerin gelmez

Islak ay ışıkları bürür sokaklarını

Sokulursun kahrına kalırsın öylece

Başlarsın saçlarını incitmeye

Kuşatılmış aynaları ve fenerleri kırar

Başlarsın saçlarını incitmeye

Gözlerin en derin iç çekmeleri anlatır

Yutkunursun, o dem ıslak bir rüzgar eser

Yığılırsın derman ermez dizlerine

Örümcek ağını işler onun olmayan kirpiklerine

Kavline koşan çocuklar da ölür

Yığılırsın derman ermez dizlerine

Sarı bir tutku dur gitmek

Her harmanın tutuk evidir

Kırılmalar başlar ekinleri büyüten şafakla

Kuşlar tüylerinden vurulur ağlarsın

Kemerlerine kuş resmi çizen çocuklara

Açılır çardaklarını saran sarmaşıklar

Bakarsın güneş eğlenmez gözlerinde', 'Güneş  eğlenmez gözlerinde Sonra tutunursun dillerin gelmez Islak ay ışıkları bürür sokaklarını Sokulursun kahrına kalırsın öylece Başlarsın...', ARRAY['Türk Edebiyatı','Şiir','Kamil Çolak']::text[], 8.5, '{"poet":"Kamil Çolak","poet_slug":"kamil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gunes-eglenmez-gozlerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MANİ', 'mani-hasan-kagan-yayla-4lt71', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerin aldı beni...

Dertlere saldı beni.

Köşe bucak kaçarken, 

Sevdalar buldu beni...', 'Gözlerin aldı beni... Dertlere saldı beni. Köşe bucak kaçarken,  Sevdalar buldu beni......', ARRAY['Türk Edebiyatı','Şiir','Hasan Kağan Yayla']::text[], 8.5, '{"poet":"Hasan Kağan Yayla","poet_slug":"hasan-kagan-yayla","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mani-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Sevmeye Görsün', 'gonul-sevmeye-gorsun-ali-aksoy-hfeh7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gönül sevmeye görsün, 

                                           Dur durak tanımaz ki.

                                           Kor düşsün alev alsın, 

                                           Söndüren olamaz ki…

                                                         Kalbe kilit vurulmaz, 

                                                         Mühürlesen ne çare.

                                                         Sen sevmek iste yeter, 

                                                         Aşkın düşer dillere…

                                           Sevmek yeniden doğmak, 

                                           Huzura kavuşmakmış.

                                           Her doğan yeni güne, 

                                           Bin umut taşımakmış…

                                                         Güzellik mutluluklar, 

                                                         Emsalsiz aşkta saklı.

                                                         Sevmeyi bilen insan, 

                                                         Sevdikçe olur haklı…', 'Gönül sevmeye görsün,                                             Dur durak tanımaz ki.                                            Kor düşsü...', ARRAY['Türk Edebiyatı','Şiir','Ali Aksoy']::text[], 8.5, '{"poet":"Ali Aksoy","poet_slug":"ali-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gonul-sevmeye-gorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ALÇAK', 'alcak-ali-aksoy-7jfe8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hayret!              

                                     Ben seni nasıl yanlış tanımışım

                                     O tatlı, güzel sözlerin sahteliğine, 

                                     O yalancı gülüşlerin kahpeliğine

                                     Acaba ben nasıl aldanmışım.

                                     Nasılda her şeyi bir anda silip attın

                                     Taş kalbin olsa da buna dayanamaz

                                     Çatlar…Paramparça olur.

                                     Onca yaşananlar, 

                                     Onca paylaşılanlar

                                     Hepsi yalan olamaz

                                     Hepsi bir çırpıda bir kenara atılamaz.

                                     Sevmek…

                                     Sevdiğine bağlanmak

                                     Senin kitabında yazmasa da

                                     Sonuçta seninde kalbin var.

                                     Bir kalp ne kadar kararmış, 

                                     Ne kadar kötülük dolu olsa da

                                     Yaşananların silinmeyen izleri kalır.

                                     Ama sen her şeye, 

                                     Tüm yaşananlara inat

                                     Hem yaşananları yaşanmamış sayıyor, 

                                     Hem de anıları silip atıyorsun.

                                     Yoksa sen bunları hep yapıyor, 

                                     Tarif imkansız zevkler mi alıyorsun? 

                                     Senin bu yaptığın

                                     Kalleşliğin daniskası.

                                     Bir insan ancak 

                                     Bu kadar sırtından vurulur.

                                     Ama sen…

                                     Bununla da kalmayıp

                                     Sanki zevk alıyor gibisin.

                                     Söyle: 

                                     Bir insanı sırtından vurmanın zevk   neresinde? 

                                     Bir tek zil takıp oynamadığın kaldı         

                                     Bari onu da yap.

                                     İnan…

                                  

                                     Biri çıkıpta ihanete adres sorsa                                                                                                                                    Seni göstereceğim, seni…

                                     İnan ihanete şifre koysalar bile

                                     İsmini yazacağım

                                     Ve de şifre çözülecek biliyorum.

                                     Çünkü sen olmadık yerde 

                                     En gerekli olduğun zamanda 

                                     Kapımı çalıyor ve

                                     Seni unutmamı, 

                                     Kalbimden söküp atmamı söylüyorsun.

                                     Ve bunları söylerken de 

                                     Ne bir utanç belirtisi var

                                     Nede bir damla gözyaşı döküyorsun

                                     Ve en sonunda da 

                                     Utanmadan gülümsüyorsun.

                                     Hadi sen unuttun

                                     Hadi sen taş kalplisin

                                     Be vefasız…

                                     Be insafsız…

                                     Be kalleş…

                                     Benim ne senin gibi taş kalbim, 

                                     Nede yalandan beslediğim hislerim var.

                                     Var sen git, 

                                     Var sen unut.

                                     Ama ben…

                                     Senin unut demene inat

                                     Seni unutmayacağım.

                                     Sakın ha…

                                     Bu yara beni öldürür sanma

                                     Öldürmez…

                                     Boş sanma beni…

                                     Boş sanma ben ne aşk yarası sardım       

                                     Yıkamazsın da…

                                     Ben neler çektim yıkılmadım.

                                     Git hadi… Git.

                                     Ardına bile bakma

                                     Bu aşkın cezasını sen bana kestin 

                                     Ama ben yıkılmadım.

                                     Sana kesilecek cezayı

                                     İnşallah ben görmem.

                                     Sen benim cezama şahit olsan da       

                                     Ben seninkine şahit olmak istemem. 

                                     Çünkü ben, 

                                     Hak etmediğimi buldum.

                                     Sense

                                     Hak ettiğini bulursun

                                     Amma yarın

                                     Amma öbür gün.

                                     Kaçamazsın.

                                     Çünkü…

                                     Eden bulur derler ya

                                     Sende bulacaksın.

                                     Dua ette faiziyle bulmayasın

                                     Alçak…', 'Hayret!                                                    Ben seni nasıl yanlış tanımışım                                      O tatlı, güz...', ARRAY['Türk Edebiyatı','Şiir','Ali Aksoy']::text[], 8.5, '{"poet":"Ali Aksoy","poet_slug":"ali-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":90,"source_url":"https://www.antoloji.com/alcak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SENİNKİ SEVMEK DEĞİL', 'seni-nki-sevmek-degi-l-ali-aksoy-9lmd7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen..

	Sevgi yoksulu, 

	Utanç yorgunu, 

	

	Sen bu sevmeleri nereden öğrendin, 

	Kim öğretti sana, 

	Yalanlı sevgilerin sonsuzluğunu, 

	Karanlık hayallerin mutluluğun, 

	Sevgilerin bu kadar basit, 

	Umutların böyle hüsranla biteceğini, 

	Ne aşk kitaplarında seninki gibi sözler 

	Nede yalan dolan üzerine kurulu 

	Yaşanmış sevgiler var...

	Seninki sevmek değil 

	Olsa, olsa 

	Uçsuz bucaksız hayallere dalmak

	İmkansız umutlara kapılmaktır.

	Yada sevdim sandığını 

	Sevmelerden soğutmaktır.

	Ama yok...

	Ben buna gelemem.

	Bir kere bu tuzağa düştüm

	Senelerce hayatta küstüm.

	Ne yapayım, 

	Gençtim, saftım, 

	

	Bir vefasız uruna 

	Yaşamın kıyısından dönmüşüm 

	Bir mum gibi bir yanıp bir sönmüşüm, 

	Bu yüzden Annem hep der 

	“Seni sonradan buldum, 

	Bir daha düşme oğlum.”

	İşte belkide benim şansım bu

	Kaderim hep vefasızlardan yana 

	Sahte sevmeliler çıkıyor karşıma 

	Yok...

	Ya ben sevenden anlamıyorum, 

	Yada her söze doğru sanıp kanıyorum.

	İşte... bu yüzden korkarım hep.

	Bir daha aynı hataya düşmekten 

	Bir daha  hayata küsmektten.

	Bırak çek git  yakamdan 

	Ben sana uymuyorum

	Israr etmen boşuna

	İlgi de duymuyorum...

	Uzatma hiç elini 

	Tutamam tutmuyorum

	Umut veremem sana 

	Hiçbir his duymuyorum...

	En iyisimi sen git.

	Başka kapıları çal yıkacak 

	Başka kalpleri bul yakacak.

	Benim kalbim zaten kırık 

	Hayallerim zaten yıkık 

	

	Sen... 

	Daha ne yapacaksın ki?', 'Sen.. 	Sevgi yoksulu,  	Utanç yorgunu,  	 	Sen bu sevmeleri nereden öğrendin,  	Kim öğretti sana,  	Yalanlı sevgilerin sonsuzluğunu,  	Karan...', ARRAY['Türk Edebiyatı','Şiir','Ali Aksoy']::text[], 8.5, '{"poet":"Ali Aksoy","poet_slug":"ali-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/seninki-sevmek-degil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SEVMEK İNSAN TARAFINI BULMAKSA... SENSİZ OLMAK HİÇ OLMAMAK GİBİ ŞEY', 'sevmek-i-nsan-tarafini-bulmaksa-sensi-z-olmak-hi-c-olmamak-gi-bi-sey-ali-aksoy-dywyq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gülmek her yanına neşe saçmaksa, 

	Ümit yarınlara mutlu bakmaksa, 

	Sevmek insan tarafını bulmaksa, 

	Sensiz olmak hiç olmamak

					GİBİ ŞEY...

	Seven güzel, sevilmeyen çirkinse, 

	Hasretlerde kavuşmalar mümkünse, 

	Güzellikler gönüllere hakimse, 

	Halâ keder yaşamamak 

					GİBİ ŞEY...

	Seviyorken sevenlerin vurması, 

	Gülüyorken gözlerin yaş dolması, 

	Hiçte yoktan dertlerinin olması, 

	Şeytanların azap vakti

					GİBİ ŞEY...

	Gurur için karartılan aydınlık, 

	Fesat için çıkarılan ayrılık, 

	Sevdalara gem vurmalar alçaklık, 

	Hem de bir aşk cinayeti

					GİBİ ŞEY...

	Unutmayıp unutulmak acısı, 

	Özlem dolu hasretlerin sancısı, 

	İhanete düşmüş kalbin ağrısı, 

	Cehennem türü bir azap

					GİBİ ŞEY...', 'Gülmek her yanına neşe saçmaksa,  	Ümit yarınlara mutlu bakmaksa,  	Sevmek insan tarafını bulmaksa,  	Sensiz olmak hiç olmamak 					GİBİ ŞEY...', ARRAY['Türk Edebiyatı','Şiir','Ali Aksoy']::text[], 8.5, '{"poet":"Ali Aksoy","poet_slug":"ali-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevmek-insan-tarafini-bulmaksa-sensiz-olmak-hic-olmamak-gibi-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KARANLIKLARIN ARDINDAN UZANAN ELDİN YA', 'karanliklarin-ardindan-uzanan-eldi-n-ya-mustafa-dag-ytj5a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dört duvar arası, karanlık ve sessiz

Yanlız ve kimsesiz

Yinede bir umut içimde

Büyük bir sevda idi kalan geride

Yanılmışmıydım yoksa

Anlarsın sanmıştım sadece 

Yalan da söyleyemezdim ya

Söz vermiştim kendime

Bir el uzandı birden

Sımsıkı tutan ellerimi

Sevmeye başlıyordum ilk defa birini

Elin kime ait olduğunu bile bilmeden seviyordum 

Seviyordum onu o diye

Rüyada da olsam seviyordum işte

Çünkü o çoktan gitmişti

Kendini ellerime bıraktığı gün parlıyordu gözlerim

Şimdi kan ağlıyor

O gün cok hızlı atarken kalbim 

Şimdi hiç carpmıyor

Beni tekrar karanlıklara bıraktın ya...

Karanlıkların ardından uzanan eldin ya

Olsun ben seni sevdim ya

Hani şu gülüşün vardı ya 

Sana kedim deyişim

sen vardın ya bir zamanlar...

O ZAMAN SEVMİŞTİM SENİ...', 'Dört duvar arası, karanlık ve sessiz Yanlız ve kimsesiz Yinede bir umut içimde Büyük bir sevda idi kalan geride Yanılmışmıydım yoksa Anlarsı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Dağ']::text[], 8.5, '{"poet":"Mustafa Dağ","poet_slug":"mustafa-dag","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/karanliklarin-ardindan-uzanan-eldin-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-bilsay-yildirim-dphzc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sabah olmuş..

Sen omzumda uyuya kalmışsın

Ne ben Ne de sen biliyoruz o zamanlar

Taksimi, ara sokakları

Dün farkına vardım seni ne kadar sevdiğimi

Yanlız kalınca 

Sessiz kalınca

Yüreğim acıyınca

Yolumu kaybedince sokaklarda

Ne sen Ne de ben biliyoruz o zamanlar

Üzülmeyi

Bir aşk

Bir biz..

Umrumuzda değil o zamanlar

Bizi biz yapan yanlışlar', 'Sabah olmuş.. Sen omzumda uyuya kalmışsın Ne ben Ne de sen biliyoruz o zamanlar Taksimi, ara sokakları Dün farkına vardım seni ne kadar sevd...', ARRAY['Türk Edebiyatı','Şiir','Bilsay Yıldırım']::text[], 8.5, '{"poet":"Bilsay Yıldırım","poet_slug":"bilsay-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/biz-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatunum', 'hatunum-bilsay-yildirim-l8kms', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özledim sana dair herşeyi, 

Kısa saçlı halini, 

Şımarıp gülmeni, 

Seni ufak gösteren şu kot kıyafetini bile, 

Fuarda yakalanmayı özledim, 

Kordonda uzanmayı, 

Sana şiir yazmayı özledim, 

Elini tutmayı, 

Vapurda çay içmeyi seninle.

Seni öpmeyi özledim, 

İlk defa beni öpüşünü unutamıyorum.

Seni bıraktığımı da, 

Bana kızdığını da, 

Benden sonra yaşadıklarını da, 

Doğumgününde içtiğim rakıyı da.

Ne seni ne de sana dair hiçbirşeyi

Unutamıyorum

Nolur hatunum, 

Sen de unutma beni.', 'Özledim sana dair herşeyi,  Kısa saçlı halini,  Şımarıp gülmeni,  Seni ufak gösteren şu kot kıyafetini bile,  Fuarda yakalanmayı özledim,  K...', ARRAY['Türk Edebiyatı','Şiir','Bilsay Yıldırım']::text[], 8.5, '{"poet":"Bilsay Yıldırım","poet_slug":"bilsay-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/hatunum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen ol', 'sen-ol-bilsay-yildirim-ou9nf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tek andımız olsun, 

Ölüm de ondan, yaşam da ondan.

Şart olsun her sevdamız, 

Kan da ondan, selam da ondan.

Bırakmasın gözyaşımız ardımızı

Melek de ondan, Şeytan da ondan

Canımız tek olsun 

Söz de onla, ser de.

Yalana inat kalsın dostluğumuz.

Hayır da ondan, Şer de ondan

 Bir tek sen kal gözlerimin önünde son nefesimde.

Ölüm de sen ol

Yaşam da.', 'Tek andımız olsun,  Ölüm de ondan, yaşam da ondan. Şart olsun her sevdamız,  Kan da ondan, selam da ondan. Bırakmasın gözyaşımız ardımızı Me...', ARRAY['Türk Edebiyatı','Şiir','Bilsay Yıldırım']::text[], 8.5, '{"poet":"Bilsay Yıldırım","poet_slug":"bilsay-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sen-ol-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KARIŞIK', 'karisik-sair-palyaco-f2r5m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'herkes herşey birbirine karıştı

adımı anımsamak

kim olduğumu

düşünmek

kalemin kalem olduğunu

kağıda yazdığını

zorlamak hafızamı

oynamak kelimelerle

ya kaleme tren desem

ya elmaya yastık

çıkıversem bir pencereden yukarı

girsem bir palyaçodan içeri

öpsem dudaklarımdan bir kitabı

ama annem yine annem

ama babam yine babam

kukla ipleri ele geçirdi', 'herkes herşey birbirine karıştı adımı anımsamak kim olduğumu düşünmek kalemin kalem olduğunu kağıda yazdığını zorlamak hafızamı oynamak keli...', ARRAY['Türk Edebiyatı','Şiir','Şair Palyaco']::text[], 8.5, '{"poet":"Şair Palyaco","poet_slug":"sair-palyaco","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karisik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkak insanlar uyanınca', 'korkak-insanlar-uyaninca-arzu-dincer-40m6y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Mühür olmuş dudaklar, 

Korkar olmuş yürekler

Bildiklerini bilmez olmuş demalar

Acılar mayalanmış şerbet niyetine, 

Kadehlere doldurulmuş, 

Sunuluyor. 

Umutlar meze, 

Beklemede...

Gelecekte bir yerde, 

Cesur bir yürek çıkacak ortaya, 

Ölü toprağını silkip insanların

Kıracak kalıplarını

Açılacak perdeler, 

Güzel insanlar sahne alacak, 

Özgürlük akan kanlarında, 

Cesaret bileklerinde

Çağlayacak 

O vakit

Mühürlü dudaklardan

Gerçekler dökülecek

Korku yok edilmiş bir düşman

Acılar sevinçlerle harmanlanacak

Gülecek insanlar

Sahip çıkıp yaşamlarına, 

Yaşamanın erdeminde

Atılacaklar güzel günlere', 'Mühür olmuş dudaklar,  Korkar olmuş yürekler Bildiklerini bilmez olmuş demalar Acılar mayalanmış şerbet niyetine,  Kadehlere doldurulmuş,  S...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/korkak-insanlar-uyaninca-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynalar', 'aynalar-arzu-dincer-ogpn4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eyy aynalar, 

Yalancı olduğunuzu düşünmemiştim 20’lerde, 

Ne de güzel bakılası bir yüz sunardınız bana.

Hele bir de boyandımı gözler, dudaklar

Hollwood aktristleri kim olurdu yanımda? 

Eyy aynalar, 

Olgunluk çağlarımda da nankörlük etmediniz, 

Bir iki kırışık vardı, 

Göze batırmadınız hani..

Yılların öğretileri pek bi yakışmıştı yansıttığınıza

Eyy aynalar, 

Gördüğüm aynı yeşil gözler

-Ama o altındaki torbalar ne olsa gerek? 

Saçlarım, Allahın boş zamanında kızıla boyadığı saçlarım

Yıldızlar bezeli her bir yanı..

-Ne kadar gürdüler ve sararlardı omuzlarımı..şimdi nerdeler? 

Eyy aynalar, 

Anlatmak istediğiniz yolun sonu mu yoksa? 

Oysa bir bahar tazeliğinde yaşarken hayatı

Rakamlarken ilerleyen

İspatmı tüm bunlar..

Daha başımı dayayacak omuz bulamazken, 

Gençlik ateşi ile nazlanırken aşklara, 

Reva mıdır bu yalnızlık.. 

Okuduğum romanlar böyle bitmezdi.

Güzel kızlar, güzelliklerine yakışır aşklarla

Karşı gelirlerdi zamana

Ve hiçbir zaman 

Ama hiçbir zaman

Nankörlük etmezdi aynalar...

Söyleyin kırdım mı sizi? 

Kaplumbağların kabuklarındaki çizgiler, 

Yaşlarını gösterirmiş, 

Pamuk olan ellerim çizgilere yenik

-Saymaya çalışıyorum...

  Aman ne saçma...ne yaş’ı..

  Onlar hala benim ellerim

  Tamam biraz titriyorlar

  Ve genç değiller..

Gezdiğim yerler geliyor aklıma, 

Anılar yoldaş 

Ve sen karşımdaki ayna! 

Söyle zamana mı yenildim, 

Yoksa ben zamanı yaşayamadan

Doyamadan güzelliklere

Çeyiz sandığına mı kaldırdım gençliğimi?', 'Eyy aynalar,  Yalancı olduğunuzu düşünmemiştim 20’lerde,  Ne de güzel bakılası bir yüz sunardınız bana. Hele bir de boyandımı gözler, dudakl...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/aynalar-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kabak Tadı Verme+', 'kabak-tadi-verme-bayram-tunca-ewkup', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şairlikte kabak tadı verdiğimin farkındayım

Çünkü, her taşın altından ben çıkmaktayım

Ne edeyim, alışmışım bir kere şiir yazmaya

Nedense, bırakamıyorum aşk şiiri yazmaya

Kiminin yarasına tuz, kimininse buz olmaktayım

Kimine kaş, kimine yaş, kimine taş, olmaktayım

Bazense kaş yapayım derken göz çıkarmaktayım

Ama şiir yazmadan aşkımı çilemi nasıl anlatayım

14.03.2003-11:45

Aşk Ateşten Gömlek', 'Şairlikte kabak tadı verdiğimin farkındayım Çünkü, her taşın altından ben çıkmaktayım Ne edeyim, alışmışım bir kere şiir yazmaya Nedense, bı...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kabak-tadi-verme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Kocaman Bir Kelebek Gibi', 'mavi-kocaman-bir-kelebek-gibi-ekmel-denizer-d6i7p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mavi

kocaman bir kelebek gibi, 

kanatları açılıp kapanan, 

yüzümün her anlamında 

konacak bir yer arayan, 

mavi

kocaman bir kelebek

gibi 

gözlerin kadınım.', 'Mavi kocaman bir kelebek gibi,  kanatları açılıp kapanan,  yüzümün her anlamında  konacak bir yer arayan,  mavi kocaman bir kelebek gibi  gö...', ARRAY['Türk Edebiyatı','Şiir','Ekmel Denizer']::text[], 8.5, '{"poet":"Ekmel Denizer","poet_slug":"ekmel-denizer","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/mavi-kocaman-bir-kelebek-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Düşmüş Bir Dağ Rüzgarı', 'yorgun-dusmus-bir-dag-ruzgari-ekmel-denizer-xw6q4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yorgun düşmüş bir dağ rüzgarı

ya da 

yaşlı dizeleri gibi

bir eski şiirin

yılkımış ellerimle pürtelaş

şiir zamanını geri getirmek kadar umutsuz

ve 

türlü sararmışlığın usancında

toprakta unutulmuş

o son yumruyu

aruyorum.', 'Yorgun düşmüş bir dağ rüzgarı ya da  yaşlı dizeleri gibi bir eski şiirin yılkımış ellerimle pürtelaş şiir zamanını geri getirmek kadar umuts...', ARRAY['Türk Edebiyatı','Şiir','Ekmel Denizer']::text[], 8.5, '{"poet":"Ekmel Denizer","poet_slug":"ekmel-denizer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yorgun-dusmus-bir-dag-ruzgari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Derin Sularından Çıkarıp', 'en-derin-sularindan-cikarip-ekmel-denizer-60ttu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'En derin sularından çıkarıp

denizlerinin

saklar

gencecik bir çabayla

ummaksızın bulunabilineceğini

ne kadar aransa da

bir gece yarısı aralığında

diz üstü çökmüş ağlıyor gibi

yüzü avuçlarının içinde

şiirine kadar batmış mutsuzluğunun

bulunmazı ararken

kısık nefen alışlarıyla

bulsa da 

yüreği yatışmaz artık.', 'En derin sularından çıkarıp denizlerinin saklar gencecik bir çabayla ummaksızın bulunabilineceğini ne kadar aransa da bir gece yarısı aralığ...', ARRAY['Türk Edebiyatı','Şiir','Ekmel Denizer']::text[], 8.5, '{"poet":"Ekmel Denizer","poet_slug":"ekmel-denizer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/en-derin-sularindan-cikarip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgarlı şiir -I-', 'ruzgarli-siir-i-ekmel-denizer-qf4sd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hoş görün telaşını

rüzgarı, 

daha çok dere tepe aşıp, 

serinliğini yetiştirecek

bu sıcak yaz akşamına

İstanbul''un.', 'Hoş görün telaşını rüzgarı,  daha çok dere tepe aşıp,  serinliğini yetiştirecek bu sıcak yaz akşamına İstanbul''un....', ARRAY['Türk Edebiyatı','Şiir','Ekmel Denizer']::text[], 8.5, '{"poet":"Ekmel Denizer","poet_slug":"ekmel-denizer","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ruzgarli-siir-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgarlı şiir -II-', 'ruzgarli-siir-ii-ekmel-denizer-tcgup', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne ayışığını karıştır şiirine

ne dalgaların sesini

fısılda kulağına rüzgarın

söylesin sevdiğime

saçlarının bağını çözsün

çözmediyse

giysin sarı elbisesini şimdi 

giymediyse', 'Ne ayışığını karıştır şiirine ne dalgaların sesini fısılda kulağına rüzgarın söylesin sevdiğime saçlarının bağını çözsün çözmediyse giysin s...', ARRAY['Türk Edebiyatı','Şiir','Ekmel Denizer']::text[], 8.5, '{"poet":"Ekmel Denizer","poet_slug":"ekmel-denizer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ruzgarli-siir-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgarlı şiir -IV-', 'ruzgarli-siir-iv-ekmel-denizer-0vk6x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Selamlarımızı bırak 

kumkapıya deli rüzgar

az anason kokusu getir

dönüşte tekirdağ üzerinden 

gel bize', 'Selamlarımızı bırak  kumkapıya deli rüzgar az anason kokusu getir dönüşte tekirdağ üzerinden  gel bize...', ARRAY['Türk Edebiyatı','Şiir','Ekmel Denizer']::text[], 8.5, '{"poet":"Ekmel Denizer","poet_slug":"ekmel-denizer","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ruzgarli-siir-iv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '27 ŞUBAT ÖNCESİ', '27-subat-oncesi-sickboy-che-onsil', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir büyü, bir sancı...

Gece ne kadar sıcak olursa olsun!', 'Bir büyü, bir sancı... Gece ne kadar sıcak olursa olsun!...', ARRAY['Türk Edebiyatı','Şiir','Sickboy Che']::text[], 8.5, '{"poet":"Sickboy Che","poet_slug":"sickboy-che","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/27-subat-oncesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldız', 'yildiz-ramazan-coskun-yko8n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen yanlız bir yıldız

Benim gönlümse avuç kadar gökyüzü

Sevgiler sonsuz, duygular yoğun

Sızıp gider gönlümden kuyruklu yıldız gibi, 

Seni düşünmek yaşamakmış meğer, 

Bunu anladım sensiz olan düşlerimin renklerinde', 'Sen yanlız bir yıldız Benim gönlümse avuç kadar gökyüzü Sevgiler sonsuz, duygular yoğun Sızıp gider gönlümden kuyruklu yıldız gibi,  Seni dü...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Coşkun']::text[], 8.5, '{"poet":"Ramazan Coşkun","poet_slug":"ramazan-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yildiz-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşıyorum Aşkımı', 'yasiyorum-askimi-ramazan-coskun-s6d8n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşıyorum aşkımı, düşlerimin renklerinde

Kırmızıyla tutkuyu, maviyle huzuru, 

Yeşille cenneti, Beyazla saflığı

Sonsuz bir güç alıyorum sevginle, 

Verebiliyorsam mutluluğu, 

Yanlızlık benim için son duraktır.

O''da musalla taşı', 'Yaşıyorum aşkımı, düşlerimin renklerinde Kırmızıyla tutkuyu, maviyle huzuru,  Yeşille cenneti, Beyazla saflığı Sonsuz bir güç alıyorum sevgi...', ARRAY['Türk Edebiyatı','Şiir','Ramazan Coşkun']::text[], 8.5, '{"poet":"Ramazan Coşkun","poet_slug":"ramazan-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yasiyorum-askimi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anama Inandigim gibi', 'anama-inandigim-gibi-huseyin-cayikli-td0iu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'inandim

toprak anama...

Nazimin dedigi gibi

hurmet ettim ona anam gibi.

inandim cekic ve oraga

hic sasmadim devrim yolundan

devrimi kucakladim umitsiz anlarimda

Babam icin agladim 

elinde ki nasirlari yuzunden...

yoldaslarima sesleniyorum

karadenizde ki laz takalarina

ve akdenize yelken actim

bir kibris planindan...

ve yasadigim surece 

DENIZ lerin uzerinde GEZMIS olacagim...

sevdigim kadinida unutmadim

bilir ki hic donmeyecegim oralara 

belki atarlarda beni mapushane damina.

yatarim bir kac yil

zaten beni unuttu sevdigim kadin

unutmak icin onu belki mesgale cikar icerde

belki mimarlik sanatimi yazilarima dokerim kim bilir

kim bilir idami yine cikartarak ederlerde beni...

kisacasi olurkende yasarkende severkende

tek diyecegim sey

tek yoldur devrim...', 'inandim toprak anama... Nazimin dedigi gibi hurmet ettim ona anam gibi. inandim cekic ve oraga hic sasmadim devrim yolundan devrimi kucaklad...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Cayıklı']::text[], 8.5, '{"poet":"Hüseyin Cayıklı","poet_slug":"huseyin-cayikli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/anama-inandigim-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Korkutmuyor Beni', 'olum-korkutmuyor-beni-ferhat-sener-6ocm6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben küçücük bir köyde doğdum.

Çayırlarında kuzular meleyen.

Bahar yaz aylarında yeşil ağaçlarından

kuşların şarkılarını dinledim.

Çocukluğum geçti bu öyde

Tozlu yollarında oynadım.

Bahçelerinden menekşe sümbül

Tarlalarından gelincik topladım.

Tabiat olsun istiyordum anam.

Buram buram kokan taoprağından.

Fışkırıyordu bir güzellik

Hiçbir zaman sonu olmayan.

Yalnız oynamayı severdim

Toprak anamın kucağında.

Kötü söylemezdi hiç

Onda tadardım mutluluğu da.

Ölüm korkutmuyor beni

Toprak olmakta

Meçhul sayfalara karışıp unutulmak

Bir daha hiç anılmamak var ya.', 'Ben küçücük bir köyde doğdum. Çayırlarında kuzular meleyen. Bahar yaz aylarında yeşil ağaçlarından kuşların şarkılarını dinledim. Çocukluğum...', ARRAY['Türk Edebiyatı','Şiir','Ferhat Şener']::text[], 8.5, '{"poet":"Ferhat Şener","poet_slug":"ferhat-sener","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/olum-korkutmuyor-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül', 'gul-ferhat-sener-dszs6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir demet karanfil mi? 

Yoksa bir tek mi gül? 

Karanfil dudaklarınla

Bir defacık olsun gül.', 'Bir demet karanfil mi?  Yoksa bir tek mi gül?  Karanfil dudaklarınla Bir defacık olsun gül....', ARRAY['Türk Edebiyatı','Şiir','Ferhat Şener']::text[], 8.5, '{"poet":"Ferhat Şener","poet_slug":"ferhat-sener","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gul-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yetim Şair*', 'yetim-sair-bayram-tunca-w2g1m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zaten felek vurmuş tâ ezelden

Azığı kahır olmuş bir güzelden

Hem gelen hem giden vurmuş

Duygu ve düşleri hazan olmuş

Garibime, yel vurmuş, el vurmuş

Yetmemiş bir de dostları vurmuş

Ayçiçeği misali boynu burkulmuş

Ne etsin onun da kaderi buymuş

Yüreğinde yanıyor fersiz bir mum

Gözyaşıyla da sönmüyor bu mum

Şu hayat yoluysa çay çamur kum

Vicdanın elveriyorsa gözünü yum

Gözyaşları içtiği su, çilesi aş olmuş

Kimilerinin, yüreği sanki taş olmuş

Bayram’ın yüreği yanıyor cayır cayır

Başkaları kayırmadı, sen olsun kayır

14.03.2003-14.03', 'Zaten felek vurmuş tâ ezelden Azığı kahır olmuş bir güzelden Hem gelen hem giden vurmuş Duygu ve düşleri hazan olmuş Garibime, yel vurmuş, e...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yetim-sair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızılın Gizemine-2', 'kizilin-gizemine-2-savas-burak-dincel-paihy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gün batımı kızıllığı içinde bir vurdumduymazlık

Özlemlerin, yalnızlıkların biçimsel tarifsizliği

Sevgilerin hüküm sürdüğü zincirler halkası

Çağırıyor bilinmezlik girdabı, kızılın rengine! 

İnsan çirkinlikleri içerisinde yalnızlık çiçeği

Kurtarmaya çağırıyor kendini.

Hafif esen rüzgarın çırpınışları içerisinde

Bir yer arıyor kendisine kızılın renginde.

Mor halkalar büyüyor için için içerisinde.

Bir kavganın ortasına sürüklüyor yalnızlık bedenleri

Çaresiz akşamlara çağırıyor sevgileri.

Tükenmez uğultular yükseliyor kızılın renginde.

Uzaklardan dalgalı denizin sesleri

Dinletmek istiyor, yakamozların ışıltısında

Yalnızlık düşleri içinde

Çağırıyor birisini kızılın rengine.

Uzayan yalnızlıklarla dolu gecelerin gizemli koynunda 

Bir nefes, bir sıcaklık arıyor.

Dönünce bir yanından diğer bir yanına

Boşluklar sarıyor bedenini, kızılın renginde! 

Unutulmuş ne varsa hatırlanıyor buğulu gözlerde 

Eski resimler dökülüyor ortaya alay edercesine

Hatıralar saçılıyor yerlere.

Umut ve umutsuzluk sarılıyor kızılın rengine.

Bir iç çekiş, bir düşünüş korkusu sersemliğiyle

Sarsılıyor bedenler, titriyor yerler

Cesaret denilen korkaklar ordusu 

Sığınıyor kızılın rengine.

Bir tuval, bir boya, belki bir resim.

Goya ile gülümsüyor duvardaki gölgelere

Tango ritmiyle biçimselleşiyor titreşimler.

Adım adım güzelleşiyor özlemlere.

Sarılıyor bedenler kızılın gizemli rengine! ...', 'Gün batımı kızıllığı içinde bir vurdumduymazlık Özlemlerin, yalnızlıkların biçimsel tarifsizliği Sevgilerin hüküm sürdüğü zincirler halkası ...', ARRAY['Türk Edebiyatı','Şiir','Savaş Burak Dinçel']::text[], 8.5, '{"poet":"Savaş Burak Dinçel","poet_slug":"savas-burak-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kizilin-gizemine-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SUSAMAMALIYDIM', 'susamamaliydim-savas-burak-dincel-10j3v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ufak bir mavi yaz kaleminden

Hatıralarla dolu olmasın ama.

Bir vadinin dumanlı ucunda

Sahte yüzleri kelimele...

Karanlık camların aynalı simasından

Bir gülüş gönder bana.

Sakın bırakma ucunu korkunun, 

Parçala giyotinsiz başımı! 

Ayağınla vur yerdeki şişeye; 

İçinde kalan bir kaç damla suyun

Şıkırdaması yankılansın bu sokakta.

Susuzluğumu ört bas etmek için 

Bakarken aranayım asfaltlarda...

Boğazım öyle kurumuş ki

Arasam bile bulamam bir yudum suyu

Bu eski kuyu başında.

Kulaklarım, 

O yerdeki çanların hipnozunda...

Pandomim yapmak istiyorum.', 'Ufak bir mavi yaz kaleminden Hatıralarla dolu olmasın ama. Bir vadinin dumanlı ucunda Sahte yüzleri kelimele... Karanlık camların aynalı sim...', ARRAY['Türk Edebiyatı','Şiir','Savaş Burak Dinçel']::text[], 8.5, '{"poet":"Savaş Burak Dinçel","poet_slug":"savas-burak-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/susamamaliydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onlara', 'onlara-sair-cakar-gxkkz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ve ölüm kapıda

pusu kurmuş, haince beklemede

dört eli karanlık güçlerin

faşist köpekleri, 

Onlar ki yüce ideolojinin

devrim neferleri, orda katledildiler

Onlar ki can, onlarca insan

Hepsi..

Mahir

Ömer

Cihan...', 'Ve ölüm kapıda pusu kurmuş, haince beklemede dört eli karanlık güçlerin faşist köpekleri,  Onlar ki yüce ideolojinin devrim neferleri, orda ...', ARRAY['Türk Edebiyatı','Şiir','Şair Çakar']::text[], 8.5, '{"poet":"Şair Çakar","poet_slug":"sair-cakar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/onlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekmek', 'ekmek-sair-cakar-mccti', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gülüşün sabah serinliğinde

              elleri yakan bir ekmek

                     sıcaklığında gülüm.

Seni bir işçinin, 

               nasırlı elleriyle bölüp yediği

                      ekmeği sevdiği kadar çok seviyorum

Ve onun ekmeği hakettiği kadar

                haketmek isterim.

                                        

                                                     Metehan ÖZCAN', 'gülüşün sabah serinliğinde               elleri yakan bir ekmek                      sıcaklığında gülüm. Seni bir işçinin,                 n...', ARRAY['Türk Edebiyatı','Şiir','Şair Çakar']::text[], 8.5, '{"poet":"Şair Çakar","poet_slug":"sair-cakar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ekmek-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski', 'eski-muhammed-ali-erol-sgrfc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'taş yuvarladığım yamaç

elma çaldığım bahçe

ömürden gidiyor

ne giderse

anımsamak şimdi

elverdiği kadar hatıraları

akşam batan güneşin gölgesini

anımsamak...

eski gözlerde bir dolunay

eski, ne beter ne afili

üzerinde gezindiğim okul duvarı

elveda dediğim dut ağacı

ve yaşlı bir kadın yüzünde hatırladığım

bostan perçinleri.

ağlamak geliyor içimden

alçak balkonlu evleriyle

baktıkça dünyaya

ağlamak geliyor içinden.

yürüdüğüm tozlu yollar

her anıdan bir çocuk sümüğü akar

eski diyorum ne beter ne afili

yalnızca eski

eski

eski...', 'taş yuvarladığım yamaç elma çaldığım bahçe ömürden gidiyor ne giderse anımsamak şimdi elverdiği kadar hatıraları akşam batan güneşin gölgesi...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Ali Erol']::text[], 8.5, '{"poet":"Muhammed Ali Erol","poet_slug":"muhammed-ali-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/eski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KABAHATLİ', 'kabahatli-zubeyir-sasmaz-qmsav', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir tatlı söz, 

güzel bir çift göz ile nasıl başladı.

Nasıl sevdim, 

Sana nasıl söyledim.

Sana neler söyledim.

Hiç birini tam diyemedim.

Kendimi hep frenledim.

Kendimi rüyada sandım

Konuşursam, söylersem, 

uyanırım diye sakındım

İşte onun için beni hiç anlamadın

Ama....    sana kabahat hiç salmadım

bütün suçların bende olduğunu anladım.

Sevgimi de, adını da sakladım

Sensiz geçen geçen bu günlerde 

Seni hiç unutamayacağımı  anladım', 'Bir tatlı söz,  güzel bir çift göz ile nasıl başladı. Nasıl sevdim,  Sana nasıl söyledim. Sana neler söyledim. Hiç birini tam diyemedim. Ken...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kabahatli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OLSA', 'olsa-zubeyir-sasmaz-9k7u6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kollarım çok uzun olsa, taa uzansa oralara.

Sarılsa sana doyasıya.

Burdan ışınlansam, oraya.

kapına kadar gelsem

zilini çalsam.

Kapıyı açsan, 

Elimde bir tek gül ile  beni karşılasan 

Beni kucaklasan

Bir merhaba desem

bir kaç dakikalığına güzel yüzünü görsem.

Sonra hemen geri dönsem.

Razıyım,  sadece görsem.', 'Kollarım çok uzun olsa, taa uzansa oralara. Sarılsa sana doyasıya. Burdan ışınlansam, oraya. kapına kadar gelsem zilini çalsam. Kapıyı açsan...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/olsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KÖTÜ GÜN DOSTU', 'kotu-gun-dostu-zubeyir-sasmaz-ud5qq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen dost aradığında, koş bana

Canın ağlamak istediğinde, yavrum

Yalnız kaldığında, 

Yanında kimseleri bulamadığında.

Yaslanacak bir omuz aradığında

Koş bana sen dost aradığında, 

Canının sıkıldığında, 

derdini kimseye anlatamadığında

Seni kimselerin anlamadığında

Dünya da tek kaldığını sandığında

Sen koş bana yavrum.

Yaslanman için bekler omuzum', 'Sen dost aradığında, koş bana Canın ağlamak istediğinde, yavrum Yalnız kaldığında,  Yanında kimseleri bulamadığında. Yaslanacak bir omuz ara...', ARRAY['Türk Edebiyatı','Şiir','Zübeyir Şaşmaz']::text[], 8.5, '{"poet":"Zübeyir Şaşmaz","poet_slug":"zubeyir-sasmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kotu-gun-dostu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim çocuklarımız', 'bizim-cocuklarimiz-i-rfan-topcu-qt43d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elleri kelepçeli sırtında cop izleri, 

Başları örtük diye kırdılar filizleri.

Bu gün okul kapalı kızım sen git işine, 

Cahillik dura dura okumak ne işine.

Müfredat değişiyor zaten Türkçe yok artık, 

Eğitimin dilini biz İngiliz e sattık.

Ana okullarında bundan sonra hello var, 

Yerini terk ediyor o güzel merhabalar.

Okumak istiyorsan tercihini yaparsın, 

Ya yaşasın sömürge ya başını açarsın.

Korkar mı çocuğundan devletin büyükleri, 

Coplatmayın onları uzatın şefkat eli.

Zaten türkün kültürü bir gün Arap bir gün Fars, 

Şimdi sıra batıda ne zaman eder iflas.

Sadece güvenelim bu yavrular hep bizim, 

Başı açık kapalı ikbali ülkemizin., 

Yalvarmak yetmez ise bu benim haykırışım, 

Kurucunun izinde zarif baş kaldırışım.

O nasıl dedi ise işte öyle bir türküm, 

Atamın çizgisidir benim mukaddes ülküm.', 'Elleri kelepçeli sırtında cop izleri,  Başları örtük diye kırdılar filizleri. Bu gün okul kapalı kızım sen git işine,  Cahillik dura dura ok...', ARRAY['Türk Edebiyatı','Şiir','İrfan Topçu']::text[], 8.5, '{"poet":"İrfan Topçu","poet_slug":"i-rfan-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bizim-cocuklarimiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşli Gün', 'gunesli-gun-ahmet-ozturk-xo08b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Geceleri duayla nurlanırmış eskilerde

Köleliğim tüm gün sürüyor

Gece karanlık filmlerle devam ediyor

Ağlayacak gibi oluyorum...ağlıyorum

Oysa bugün karnaval renginde bir ferah başladı

Bugün bedenim tutmasam göğe fırlayacak

Güneşi yudum yudum içesim var 

Bir öğlen yemeği bir kurtuluş 

bir devrim bir devinim

dışarı çıktım havayı kucakladım

dilim neşeli bir şarkıya döndü

yaşam birden doluyor hepten boşalıyor

hepten dolsa da birden boşalsa keşke

(15 Şubat 2003 - Cumartesi)', 'Geceleri duayla nurlanırmış eskilerde Köleliğim tüm gün sürüyor Gece karanlık filmlerle devam ediyor Ağlayacak gibi oluyorum...ağlıyorum Oys...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gunesli-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum Seni', 'seni-seviyorum-seni-ahmet-ozturk-e1lup', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eski bir İran halısıyım

sevildikçe yıpranmışlığım

Denizler kıbleleri buluyor gene

Seni seviyorum

Nerdesin yüreği tipideki yaprak

Üşüntünü ver hadi

Bak omuzlarım yerlerde

Karıncalar sırtladı beni

Yalnız durma ağlarsın

Seviyorum seni

Şehrimi kar kapladı gene

Gel bak dağların zirvesinden

Buralar da bembeyaz

Biçare yürüme, ben biçareyim çünkü

Haydi sor dünyayı bana

Gene kanlanayım, gene canlanayım

Ve mahcup diriliğimle dinle beni 

Seni seviyorum

(16 Şubat 2003)', 'Eski bir İran halısıyım sevildikçe yıpranmışlığım Denizler kıbleleri buluyor gene Seni seviyorum Nerdesin yüreği tipideki yaprak Üşüntünü ve...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-seviyorum-seni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akrep ve Yelkovan', 'akrep-ve-yelkovan-ahmet-ozturk-j17r7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Akrebe sormuşlar yelkovanı

“daha çocuk” demiş

yelkovan duramaz yerinde

yer ve gök bir adım

aşk ve son

Yelkovana sormuşlar akrebi

“miskinin biri” demiş

akrep ağır molla

ezel ve ebede tutkun

aşk ve sonsuzluk

(20 Şubat 2003-02-22)', 'Akrebe sormuşlar yelkovanı “daha çocuk” demiş yelkovan duramaz yerinde yer ve gök bir adım aşk ve son Yelkovana sormuşlar akrebi “miskinin b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/akrep-ve-yelkovan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani Hiç Hani Demek Yoktu', 'hani-hic-hani-demek-yoktu-ahmet-ozturk-5peqm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hüküm kıyafeti giyilir ayaklar yalın

ciğerler titrek ve nikotin 

Mapusanenin duvarına çizmiştim seni

tırnaklarım sökülene dek kazıdım

Bir çift güvercinim koklaşır 

gece gündüze sürtünür

hırsımdan ağlarım, yoksun

Geceler mazeret kabul etmez 

ayaz ve sonsuz

hani yürek ferman dinlemezdi

hani yangın çıktı mı dünyalar yanardı

hani hiç hani demek yoktu

(11 Mart 2003)', 'Hüküm kıyafeti giyilir ayaklar yalın ciğerler titrek ve nikotin  Mapusanenin duvarına çizmiştim seni tırnaklarım sökülene dek kazıdım Bir çi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Öztürk']::text[], 8.5, '{"poet":"Ahmet Öztürk","poet_slug":"ahmet-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hani-hic-hani-demek-yoktu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ANLAMIM', 'anlamim-omer-avsar-69hjw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç bir şey yada her şey

Ya cennet yada cehennem

Siyahla beyaz

Ölüm....diriliş

Ve daha yüzlerce kelime

Hepsi seni anlatır inceden inceye

Seninle yaşayacagım, yaşıyorum

Hayatın tarifini ancak böyle anlatıyorum...', 'Hiç bir şey yada her şey Ya cennet yada cehennem Siyahla beyaz Ölüm....diriliş Ve daha yüzlerce kelime Hepsi seni anlatır inceden inceye Sen...', ARRAY['Türk Edebiyatı','Şiir','Ömer Avşar']::text[], 8.5, '{"poet":"Ömer Avşar","poet_slug":"omer-avsar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/anlamim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başbuğ-a hasret', 'basbug-a-hasret-i-rfan-topcu-wtion', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir göz yaşı masalı, 

Nisanda başladı yokluğunla.

Ve sensizlik başbuğum, 

Nede zormuş, 

Nede zormuş vallaha.

Alışamadık, 

Sensizlik sadece bizimi, 

Bizimi boğdu bir göz yaşı masalına? 

Bizleri, 

Mecnunu yaptığın leylanın

Adını ülkü koymamışmıydın? 

İşte oda mahsun, 

Oda garip sen yokken.

Onunda bir göz yaşı masalı var.

Ülküde ağlıyor başbuğum, 

Ülküde ağlıyor sen yokken.

................

Bir göz yaşı masalı, 

Nisanda başladı yağmur gibi, 

Tibet yaylalarının, 

Soğuk rüzgarları aldı göz yaşlarını, 

Taşıdı doğu türkistana, 

Yaralı uyguru birdaha yaraladı

Değince yarasına.

Aral çölleri dahada çölleşti, 

Şimdi sensiz başbuğum.

Sen yokken, 

Ağlıyor, 

Gelinlik kızı kırımın eli kınalı, 

Ağlıyor, 

Birde vatansız hala ahıskalı.

Sen yoksun.

Yetim, yetim türk dünyası.

Anadolu garip, kıbrıs çaresiz, 

Türkmen tükeniyor başbuğum.

Bir göz yaşı masalı gibi ayrıldın aramızdan.

Gözü yaşlı bir nisan günü.

...............

Uçmağa varmak derlerya, 

Bilge kağanlar gibi, 

Fatih sultanlar gibi, 

Mustafa kemaller gibi.

...........

Sen yoksun, 

.............

Sadece bir göz yaşı masalı var, 

Nisanda başlayan, 

Ve nisandan obür nisana kadar uzayan.', 'Bir göz yaşı masalı,  Nisanda başladı yokluğunla. Ve sensizlik başbuğum,  Nede zormuş,  Nede zormuş vallaha. Alışamadık,  Sensizlik sadece b...', ARRAY['Türk Edebiyatı','Şiir','İrfan Topçu']::text[], 8.5, '{"poet":"İrfan Topçu","poet_slug":"i-rfan-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/basbug-a-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairler Ağlamaz', 'sairler-aglamaz-ahmet-selcuk-i-lkan-eokic', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Farzet ki bu aşkı yaşamadık seninle

Farzet ki hiç bir geceyi paylaşmadık ikimiz

Farzet ki saçlarını bile hiç okşamadım

Hadi git, gözlerime baka baka git

Hadi git, hayatımdan çıka çıka git

Hadi git, yüreğimi yaka yaka git

Şairler ağlamaz gülüm, şairler ağlamaz

Farzet ki unutulmuş bir şairim köşe başında

Farzet ki hiç bir şiirimi sana yazmadım

Farzet ki hiç bir şarkımda adını bile anmadım

Hadi git, sevdiğimi bile bile git

Hadi git, bir kalemde sile sile git

Hadi git, hiç üzülme güle güle git

Şairler ağlamaz gülüm, şairler ağlamaz

Farzet ki bir kum tanesiyim sahilde

Farzet ki bir çakıl taşıyım yol kenarında

Farzet ki boş bir kibrit kutusuyum ellerinde

Hadi git, üzerime basa basa git

Hadi git, umutları asa asa git

Hadi git, hiç konuşma susa susa git

Şairler ağlamaz gülüm, şairler ağlamaz

Fazet ki yokum artık

Farzet ki öldüm

Farzet ki isimsiz bir mezarım dağ başında

Hadi git, saçlarından bir tel bırakmadan git

Hadi git, avucumda bir el bırakmadan git

Hadi git, başucumda bir gül bırakmadan git

Şairler ağlamaz gülüm, şairler ağlamaz', 'Farzet ki bu aşkı yaşamadık seninle Farzet ki hiç bir geceyi paylaşmadık ikimiz Farzet ki saçlarını bile hiç okşamadım Hadi git, gözlerime b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sairler-aglamaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zavallılar Arkada', 'zavallilar-arkada-abdurrahim-karakoc-rgs8s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kevser bardakları atıldı raftan

Her şaraba KÜP olanlar ön safta.

İffet timsalleri kovuldu saftan

Her bebeğe TÜP olanlar ön safta.

Kurt revaçta, kuzu düştü gündemden

Yemeklerin tuzu düştü gündemden

Haysiyet, tevazu düştü gündemden

Her şalvara CEP olanlar ön safta.

On partiyle flört yapan yiğitler

El yalayıp etek öpen yiğitler

Canlı, cansız puta tapan yiğitler

Her çöplükte ÇÖP olanlar ön safta.

Sayınlar var, zaman çalar zamandan

İkram sağar süpürgeden, samandan

Puştlar amir, hokkabazlar kumandan

Her baltaya SAP olanlar ön safta.

Dahiler var, muz aşılar meşeye

Cin çıkarır, cin doldurur şişeye

Köşe dönücüler yattı köşeye

Her çembere ÇAP olanlar ön safta.

Fırtına başladı, meltemler dindi

Namus, ahlâk, vakar tahtından indi

Postallar, papuçlar kıymete bindi

Her kelleye KEP olanlar ön safta.

İnancına uyandadır adamlık

Zarardadır, ziyandadır adamlık

Gören yok ki ne yandadır adamlık

Her şerife COP olanlar ön safta.

Aç gözleri makam hırsı bürüdü

Siyasi zırzopluk aldı-yürüdü

Sosyal yapı, milli doku çürüdü

Her hastaya HAP olanlar ön safta.

(Akıl Karaya Vurdu)', 'Kevser bardakları atıldı raftan Her şaraba KÜP olanlar ön safta. İffet timsalleri kovuldu saftan Her bebeğe TÜP olanlar ön safta. Kurt revaç...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/zavallilar-arkada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Görev Olmalı', 'sevmek-gorev-olmali-berrin-tas-8ijcl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir bulutun yere inişini gözlerinde izlemeliyim 

Öfkelerini bilmeliyim fırtınadan önce 

Sevinçlerine dokunmalıyım bahar gelmeden 

Kızgınlık.... neye.... kime.... sezmeliyim 

Seni anlamalıyım gideceğin yönü 

işaret etmeden önce 

Sevmeliyim.', 'Bir bulutun yere inişini gözlerinde izlemeliyim  Öfkelerini bilmeliyim fırtınadan önce  Sevinçlerine dokunmalıyım bahar gelmeden  Kızgınlık....', ARRAY['Türk Edebiyatı','Şiir','Berrin Taş']::text[], 8.5, '{"poet":"Berrin Taş","poet_slug":"berrin-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sevmek-gorev-olmali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmeyi Yaşamak', 'sevmeyi-yasamak-berrin-tas-6r1a0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sizi ölesiye sevmek 

yaşamın en ağır yüküydü 

taşıdım ağrıyan soluğunuzu 

anlamayı geceler boyu sesinizde 

oynaşan titreşim ulaştı en ince sancılarla bana 

kapalıydı duyumlarınız-işitmediniz

Sizi ölesiye sevmek yaşamın en ağır bedeliydi

ödedim.', 'Sizi ölesiye sevmek  yaşamın en ağır yüküydü  taşıdım ağrıyan soluğunuzu  anlamayı geceler boyu sesinizde  oynaşan titreşim ulaştı en ince s...', ARRAY['Türk Edebiyatı','Şiir','Berrin Taş']::text[], 8.5, '{"poet":"Berrin Taş","poet_slug":"berrin-tas","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sevmeyi-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Öyle Bir Sevdaki', 'bu-oyle-bir-sevdaki-omer-sevim-rqgim', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sevdanın içindeyim ya Rabbi

Etrafım ateş çemberi

Çıkar bir yol göster yarabbi

Kalbim artık taşımaz oldu bu kederi

Bu öyle bir sevdaki ya Rabbi

Sözler esir olmuş gözlerin bakışına

Leyla gibi beklemeye gücüm yok ya Rabbi

Sen yardım et bu sevda kalmasın ortalıkta

Bu sevda bir bebek misali masumdur ya Rabbi

Emekliyor, yürümesine sen yardım et

Ferhat gibi önümüze dağ çıkarma ya Rabbi

Sen bu sevdanın sonunu hayır et

Ben dertli dertli akan bir ''nehir''im ya Rabbi

Sevda denizim hangi yönde

Yönümü ona yönünü bana çevir ya Rabbi

Ne olur artık vuslata ersin bu sevda....

(Tüm sevdalıların sevdalısına kavuşması temennisi ile)', 'Bir sevdanın içindeyim ya Rabbi Etrafım ateş çemberi Çıkar bir yol göster yarabbi Kalbim artık taşımaz oldu bu kederi Bu öyle bir sevdaki ya...', ARRAY['Türk Edebiyatı','Şiir','Ömer Sevim']::text[], 8.5, '{"poet":"Ömer Sevim","poet_slug":"omer-sevim","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bu-oyle-bir-sevdaki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük Karmaşa', 'buyuk-karmasa-selin-gungor-pge6d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İçimden bir ses yap diyor, 

Gözlerim, kulaklaım eskiyi unutmuyor.

İçimdeki ışık kör ediyor gözlerimi, 

Gözlerim ısrarla savunuyor gerçeği.

İçimdeki ses sağır ediyor kulaklarımı, 

Kulaklarım asla geri almıyor savını.

Aklımsa iki derede bir arada, 

Sarhoş oldu bu karmaşık oyunda...', 'İçimden bir ses yap diyor,  Gözlerim, kulaklaım eskiyi unutmuyor. İçimdeki ışık kör ediyor gözlerimi,  Gözlerim ısrarla savunuyor gerçeği. İ...', ARRAY['Türk Edebiyatı','Şiir','Selin Güngör']::text[], 8.5, '{"poet":"Selin Güngör","poet_slug":"selin-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/buyuk-karmasa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O AN', 'o-an-i-ro-dissa-ltca5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O AN

Masun gibi oturuyorsundur

Güneşin batışını seyrederken

Sadece kızıllığın güzelliğini, 

Batışın romatikliğini 

Düşünüyorsundur o an

Yediğin en güzel yemeğin

Niçin tuzunun eksik olduğunu, 

Sevdiğin en güzel filmin

Neden reksiz olduğu düşünürsün 

O AN

Gelirki! 

En güzel yemeğin tuzunu değil

Neden lokmasının boğazını sıktığını, 

En sevdiğin filimin rengini değil

Neden ruhunun sıkıldığını düşünürsün

Masun gibi otururken o an

Güneşin kızıllığını 

Neden yaptığını

Güneşin batışını 

Neden buhrana ittiğini düşünürsün

O AN 

Gelirki! 

işte o an boğazını sıkan lokmaların, 

Canını sıkan o güzel filimin 

Buhrana  itten o ramantik batışın, 

Sebebini düşünürsün.

Sana zevklerin en iyisini tattıracak 

Romantizim en güzeliğini yaşatacak

O ateşiyle yakan kızıllığın 

Aşkın esartliği olduğunu anlarsın

En güzel baharın onunla 

En güzel kokuların onunla 

En güzel romantik yaşamın onunla 

Onun varlığıyla olacağını hiss edersin

Soğukta buz kesilen bedenin 

Sevgisiz taş kesilen ruhun

Açmamış gülün suyunu 

Gülmemiş  çaresiz yüzleri düşünürsün

Tek çaresinin onun aşkı, 

Tek çaresinin onun verarliğı, 

Yaşamın tek gayesinini.

işte AŞKIN gerçek varlığını, 

Anladığın zamandır O AN....', 'O AN Masun gibi oturuyorsundur Güneşin batışını seyrederken Sadece kızıllığın güzelliğini,  Batışın romatikliğini  Düşünüyorsundur o an Yedi...', ARRAY['Türk Edebiyatı','Şiir','İro Dissa']::text[], 8.5, '{"poet":"İro Dissa","poet_slug":"i-ro-dissa","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/o-an-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-selin-gungor-wpyxf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hayat bir ırmağa benzer; 

Yosun tutmuş kayalar, 

Ve özgürlük tutsağı balıklar...

İnsanlar ise; 

Ya akıntıya kapılmış bir çiçek, 

Ya dibe vurmuş bir şişe...

İkisi de birbirinden farksız, 

İkisi de ırmağa mahkum...

Hayat bir buluta benzer; 

Bazen; 

Karanlık sisler içinde kaybolmuş, 

Rotasız bir gemi.

Bazen; 

Aydınlığa kavuşma umuduyla kavrulan, 

Bir yudumluk nefes, 

Bazen; yaptıklarından bin pişman, 

Ağlamaklı bir çocuk.

İster ırmak, ister bulut, 

Aslında hayat küçük bir umut.

Sırayla nefslere dolan, 

Akıbeti belli olmayan, küçücük bir umut....', 'Hayat bir ırmağa benzer;  Yosun tutmuş kayalar,  Ve özgürlük tutsağı balıklar... İnsanlar ise;  Ya akıntıya kapılmış bir çiçek,  Ya dibe vur...', ARRAY['Türk Edebiyatı','Şiir','Selin Güngör']::text[], 8.5, '{"poet":"Selin Güngör","poet_slug":"selin-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hayat-82-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DUYARLILIK', 'duyarlilik-filiz-angay-bccsb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Duyarlılık nedir? 

İnce düşünmek, 

Detayları hesaplamak, 

İnsanların gözlerindeki ışığın

Kuvvetini ve zayıflığını hissedebilmek, 

Kalbin yönlendirmesiyle

Devirebilmek dağları, 

“Olmaz”ları, “olur” yapmak...

Dilimize pelesenk olmuş

“Duyarlıyım” demek...

Yüreğin çırpınışını hissedemedikten sonra, 

Ağızdan çıkan bu sözcük, 

Sadece maskedir yüze, 

Bir süre sonra

Alerji yapar...', 'Duyarlılık nedir?  İnce düşünmek,  Detayları hesaplamak,  İnsanların gözlerindeki ışığın Kuvvetini ve zayıflığını hissedebilmek,  Kalbin yön...', ARRAY['Türk Edebiyatı','Şiir','Filiz Angay']::text[], 8.5, '{"poet":"Filiz Angay","poet_slug":"filiz-angay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/duyarlilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alaca Karanlıkta Gözlerim', 'alaca-karanlikta-gozlerim-turgay-akbulut-g79yy', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Penceremde sis bulutları

Geçiyoruz Bolu Dağlarını

Sarılmış boyunlu kazak gibi

Dağlar, hakikaten dumanlı

Eteğinde bir köy var! Minaresi çıplak

Örtülmüş üzeri, beyaz yorgan misali

Bir göz bir aralık

Bir yorgan altında bilmem kaç çocuk

Sarılmıştır, küçük bedenleri

Ilık nefeslerinin ısıttığı, sönük tezek sobaları

Etrafında, düş kuran körpe oğlaklar

Şimdi çocukluğum uyuyor, orada

Aynı yorgan altında...

Yan profilden ezberlediğim kız

Nasılda büzülmüş, koltuğuna

Boynu da düşmüş, O şimdi tatlı rüyasında

Ağrısını önleyebilirim, ellerim dokunsa

Ellerim...

Birazdan boynu ağrıyacak! 

Çaresizim...

Alaca karanlıkta gözlerim

Gökyüzünde kalmış, birkaç nöbetçi yıldızlar

Günü devredecek birini arıyorlar

Çocukluğum geliyor aklıma

Penceremde dedemin sesi

Sabah ayazı gibi

“Kalk öğlen oldu! ” derdi

Daha güneş doğmamıştı...

Kaç zaman rüyalarımız yarım, 

Uykuya hasret koştuk tarlalara

Kaç zaman tepemizde alev, 

Turşu suyu içtik, çinko çaydanlıklarda

Uykulu Öküzler dönerdi, çiğ düşen saplarda

Islak saplar erir miydi? 

Neydi bu telaş? bu kavga? 

Gün doğmadan güne başlama telaşı! 

Neydi...

Günü, Yıldızlardan devralır,

Yıldızlara devredene kadar çalışırdı

Bir ömür yoksulluğa, 

Oraklar, tırpanlar sallandı

Ömürler tükendi

Yoksulluk bırakmadı, yakamızı

Bir ömür, yıldızlarla nöbet tutup

Bir gün yıldızlar gibi, kayıp gittiler

Bir ömür tükettiler

Ne bağdaki üzümün tadı

Ne çift ne çubuk ne öküzler

Ne örs ne çekiç ne tırpan

Nede şafakta yankılanan, dingil sesleri

Hiçbir şeyin kalmadı, anlamı...

Bir ömür, şafak vakti kalktılar! 

Bir ömrü, şafak vakti habersiz terkettiler! 

Dedeler! 

Onlar şimdi Gökyüzündeler...

(haziran 2002)', 'Penceremde sis bulutları Geçiyoruz Bolu Dağlarını Sarılmış boyunlu kazak gibi Dağlar, hakikaten dumanlı Eteğinde bir köy var! Minaresi çıpla...', ARRAY['Türk Edebiyatı','Şiir','Turgay Akbulut']::text[], 8.5, '{"poet":"Turgay Akbulut","poet_slug":"turgay-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/alaca-karanlikta-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BEKLEYIS', 'bekleyis-seref-kaya-yzssu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ümitler sararip solsada, 

Kalbime dünyanin acisi dolsada, 

Her yer karanlik olsada, 

Sevgilim yolunu bekliyecegim.

Hicranla belirse sacimda aklar, 

Her telinde; hatira saklar, 

Unutsa ismimi o yerler.

Sevgilim yolunu bekliyecegim.

Ayrilik hasreti kanimi icse! 

Kainat baska diyara göcse, 

Aradan aylar, seneler gecse, 

Sevgilim yolunu bekliyecegim.

Unutma sevgimi kalbinde tasi, 

Vatani korumak, her seyin basi, 

Sil benim sevgilim gözünden yasi, 

Sevgilim yolunu bekliyecegim.', 'Ümitler sararip solsada,  Kalbime dünyanin acisi dolsada,  Her yer karanlik olsada,  Sevgilim yolunu bekliyecegim. Hicranla belirse sacimda ...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bekleyis-42-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yudum Akşam Gönder', 'bir-yudum-aksam-gonder-oktay-yivli-mvmzy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Uzat afyon dudaklarını

leylak kokulu

biraz zaman

serin gölgesiyle

bir yudum akşam gönder

çok değil

Ayışığı böler karanlığı

dağda kurt uluması yalnızlık

ben''den ben''e kadar

biraz bekle

çok değil

Gözlerin

her nasılsa günümü belirler

elin değince elime

uzak bir nehir

uyur-uyanık akar

içime

Ilık bir türkü

gibi çağır ismimi

biraz sevmek

çok değil', 'Uzat afyon dudaklarını leylak kokulu biraz zaman serin gölgesiyle bir yudum akşam gönder çok değil Ayışığı böler karanlığı dağda kurt ulumas...', ARRAY['Türk Edebiyatı','Şiir','Oktay Yivli']::text[], 8.5, '{"poet":"Oktay Yivli","poet_slug":"oktay-yivli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-yudum-aksam-gonder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ben Yaniyorum', 'bir-ben-yaniyorum-guner-kaymak-81uzz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yolu yakin iken kalbimden cik nolur

El alem halime guluyor utaniyorum

Denedik seviselim olmadi kapatalim

Madalyonun obur kismini anlatamiyorum

Gelecegi ikimizde farkli gorebiliriz

Benim umitlerim galiba coktan bitmis

Seni bos vahatlerle avutmak zor bence

Nolursun beni sen anla anlatamiyorum

Bilirim gercekler acidir buda gercek

Dunyami karartsada gercegi gizlemiyorum

Elimden birsey gelmiyor guc ver rabbim

Iki ates arasindayim bir ben yaniyorum

Amsterdam/14.03.2003', 'Yolu yakin iken kalbimden cik nolur El alem halime guluyor utaniyorum Denedik seviselim olmadi kapatalim Madalyonun obur kismini anlatamiyor...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-ben-yaniyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öbür Yarı', 'obur-yari-oktay-yivli-388xu', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saklardım benliğimin bir köşesinde ben

Gizli bir tapınak gibi seni

Bu akşam, neden benzemiyor düne? 

Ey soylu ve tanrısal kadın

ki gövden kan ve topraktandır

Karışır gölgemiz suyun ahengine

Deniz evim, kadınım benim

Sararım seni ahtapot kollarımla

Benzesek de iki aykırı kareye

Duyumsuyor tenim işte, öbür yarımı

Artık gizli tapınağımı

Perde perde açıyorum kendime', 'Saklardım benliğimin bir köşesinde ben Gizli bir tapınak gibi seni Bu akşam, neden benzemiyor düne?  Ey soylu ve tanrısal kadın ki gövden ka...', ARRAY['Türk Edebiyatı','Şiir','Oktay Yivli']::text[], 8.5, '{"poet":"Oktay Yivli","poet_slug":"oktay-yivli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/obur-yari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyleyemiyoruz', 'soyleyemiyoruz-oktay-yivli-qme48', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Biz neyiz şimdi

iki eski dost

iki yeni yabancı

aynı batında gelişen

ihtiras ve utanma gibi

Söylenecek bütün sözler bitmiş nasılsa

geçmiş günlerden dem vuruyoruz, 

dostluğumuzun eskiliğinden

mektupların güzelliğinden, 

denizin ne kadar mavi

gökyüzünün ne kadar berrak olduğundan...

Söylenecek onca şey var oysa

söyleyemiyoruz', 'Biz neyiz şimdi iki eski dost iki yeni yabancı aynı batında gelişen ihtiras ve utanma gibi Söylenecek bütün sözler bitmiş nasılsa geçmiş gün...', ARRAY['Türk Edebiyatı','Şiir','Oktay Yivli']::text[], 8.5, '{"poet":"Oktay Yivli","poet_slug":"oktay-yivli","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/soyleyemiyoruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gorursem Seni Mutlaka Operim', 'gorursem-seni-mutlaka-operim-guner-kaymak-gwl2c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gorur gormez seni mutlaka operim

Olur olmaz yerde cikma hemi karsima

Saclarini egilip koklamadan gecemem

Yakana kirmizi karanfil takma olurmu

Arada bir gel evime geceleri gizlice

Usta hirsiz gibi sessiz sessiz sinsice

Olurya tesadufen biri seni gorunce

Sakin hemen panige kapilip kacma olurmu

Ruzgar esebilir belki agam gordu deme

Dallar sallaninca babam geldi deme

Gordugun herseyden korkup vay anam deme

Hic degilse bu defa beni aldatma olurmu

Amsterdam/14.03.2003', 'gorur gormez seni mutlaka operim Olur olmaz yerde cikma hemi karsima Saclarini egilip koklamadan gecemem Yakana kirmizi karanfil takma olurm...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gorursem-seni-mutlaka-operim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atmak İçin', 'atmak-i-cin-aysenur-yazici-i3vvc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biliyor musun ne düşündüm

Dün gece hastanede, 

Kalbim seni içinden atmasını bilemiyor

Kalp spazmı filan bahane...', 'Biliyor musun ne düşündüm Dün gece hastanede,  Kalbim seni içinden atmasını bilemiyor Kalp spazmı filan bahane......', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/atmak-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bol Olur', 'bol-olur-dost-inan-1ykej', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Niye yükselirsin divane basim, 

Her zaman yükseyin kis''i bol olur, 

Sak ol su alemde dalma gaflete, 

Uyuyup gezenin düs''ü bol olur.

Yaramaz yerlerde bosa gezinme, 

Sen ol basliksiz tesbihe dizilme, 

Meyveli ol taslansanda üzülme, 

Meyveli agacin tasi bol olur.

Dost Inan böyledir kafana takma, 

Sen olsun alem''in karamsar bakma, 

Felekle kaderle kumara kalkma, 

Zar ustasi onlar sesi bol olur.', 'Niye yükselirsin divane basim,  Her zaman yükseyin kis''i bol olur,  Sak ol su alemde dalma gaflete,  Uyuyup gezenin düs''ü bol olur. Yaramaz ...', ARRAY['Türk Edebiyatı','Şiir','Dost Inan']::text[], 8.5, '{"poet":"Dost Inan","poet_slug":"dost-inan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bol-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Gene Seni Düsündüm', 'ben-gene-seni-dusundum-dost-inan-xu377', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Daldim ilham deryasina, 

Ben gene seni düsündüm, 

Boyandim hasret yasina, 

Ben gene seni düsündüm.

Umutlarim eyledim taç, 

Dünyalari verseler hiç, 

Nasil çöl yagmura muhtaç, 

Ben gene seni düsündüm.

Gecelerime düs gibi, 

Geçer baharim kis gibi, 

Ciçeklere günes gibi, 

Ben gene seni düsündüm.

Dost Inan''im ey sevdalim, 

Sana ayandir bu halim, 

Umurumda degil ölüm, 

Ben gene seni düsündüm.', 'Daldim ilham deryasina,  Ben gene seni düsündüm,  Boyandim hasret yasina,  Ben gene seni düsündüm. Umutlarim eyledim taç,  Dünyalari versele...', ARRAY['Türk Edebiyatı','Şiir','Dost Inan']::text[], 8.5, '{"poet":"Dost Inan","poet_slug":"dost-inan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-gene-seni-dusundum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yucelsin Medeniyet', 'yucelsin-medeniyet-guner-kaymak-qm74v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gonlumun bagina zarar vermeyin

Umitlerim sararmasin solmasin

Neler cektim neler bu gune kadar

Emeklerim barhavaya gitmesin

Raziyim ben haktan gelen herseye

Atarim kederi karisirim neseye

Yapa yalniz cekilmem ben koseye

Gun ola harman ola demisler

Umudim nesem sevgim tukenmez

Ne zaman kiminle mechul bilinmez

Dereden gecene hic zarar gelmez

Ilimden irfandan kacinmak olmaz

Laleden sumbulden kokular aldim

Ari gibi petek petek dolandim

Nergize menekseye gule ugradim

Seher vakti bulbulleri dinledim

Akti gozum yasi akti sevincten

Keder gam tasa ayrildi bedenimden

Insan gibi insanca yasamak varken

Ne bu enaniyet neden rezalet

El ele verelim yucelsin medeniyet

Amsterdam/15.03.2003', 'Gonlumun bagina zarar vermeyin Umitlerim sararmasin solmasin Neler cektim neler bu gune kadar Emeklerim barhavaya gitmesin Raziyim ben hakta...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yucelsin-medeniyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Şarkı Aklımda Kalan', 'bir-sarki-aklimda-kalan-ender-guncelik-4g27m', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ellerini uzatınca 

Hemen tutardım onları

Saatlerce bakardım gözlerine

Kaybedecekmişim gibi

Hasretle bakardım o güzel yüze

Gizlice buluştururduk ellerimizi

Okulun soğuk sıralarında

Bazen bir camın önünde 

Bir başka bakardık dünyaya.

Bir şiirdi, pencere önünde 

Kim bilir? Hangi garip karalamıştı o satırları

Ne acılarla yıpranmıştı? 

Hangi hain, yalancı onu yarı yolda bırakmıştı? 

O zaman anlayamamıştık içindeki manayı

Ama şimdi anlıyorum ki 

Sende en az o şiirdeki kadar yalancıymışsın.

“Hani bekleyecektin bir ömür boyu

Hani olmayacaktın başkalarının

Sen yalancı çıktın, vefasız çıktın”

Ve bugün baktım da o yazıyı bulamadım

Belki yazı oradaydı 

Ama sen gittikten sonra hiçbir şeyi görmedi bu gözler

Sadece kapalı tuttum onları

Çünkü gözümü her kapattığımda

Sen gelirdin karşıma

Bir de bana söylediğin bir söz vardı

“Seni Seviyorum” derdin ya

İlk söylediğin anda

Bir demet papatya diktim evimin köşesine

Yetiştirip onları

Evlendiğimiz gün verecektim sana

Bilirim sen papatyaları seversin

Ama sen gittiğinde 

Onlarda boyunlarını büküp öldüler sevdiğim 

Benim mezarımın üstünde

O yaralı, seni özleyen kalbin içinde.', 'Ellerini uzatınca  Hemen tutardım onları Saatlerce bakardım gözlerine Kaybedecekmişim gibi Hasretle bakardım o güzel yüze Gizlice buluşturur...', ARRAY['Türk Edebiyatı','Şiir','Ender Günçelik']::text[], 8.5, '{"poet":"Ender Günçelik","poet_slug":"ender-guncelik","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bir-sarki-aklimda-kalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ari Oldum', 'ari-oldum-guner-kaymak-tcq3q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ari oldum cicek gezdim bal verdim

Yinede hic kimselere yaranamadim

Namertlik edip hic yalan soylemedim

Umudum gonlumde oldu her zaman

Riayet eyledim ben hakka hukuka

Aslen karsiyim siyasete nutuka

Latifeler sakalar cikti ayyuka

Icerden iceri kazilan tunel gibiyiz

El ele verip hepimiz birlik olmadik

Kol kanat germedik sahip cikmadik

Biz bir butunuz ayrilmayiz demedik

Eller bizi nerden bilsin ne bilsin

Raziyim memleketime gelen canima gelsin

Amsterdam/15.03.2003', 'Ari oldum cicek gezdim bal verdim Yinede hic kimselere yaranamadim Namertlik edip hic yalan soylemedim Umudum gonlumde oldu her zaman Riayet...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ari-oldum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabit Ince', 'sabit-ince-guner-kaymak-ljez4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Siirlerin guzel emegin guzel

Ari gibi cicek cicek gezmissin

Bitmesin enerjin solmasin azmin

Icerde disarida cok yer gezmissin

Tabiati sen yuregine yazmissin

Inatla cahalete karsi durmussun

Nice yobaz nice zalim gormussun

Cesaretle gercekleri yazmissin

El ele verelim kalkinalim demissin

Amsterdam/15.03.2003', 'Siirlerin guzel emegin guzel Ari gibi cicek cicek gezmissin Bitmesin enerjin solmasin azmin Icerde disarida cok yer gezmissin Tabiati sen yu...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sabit-ince-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '++ve Asırlık Çınar Devrildi', 've-asirlik-cinar-devrildi-zeki-ergin-a2m29', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'davullar vuruldu

doğan güne karşı

düşmanı yurttan kovmak için

yürüdü

ana bacı

genç ihtiyar

yürüdü

zulmün üstüne

ve garp cephesi komutanı

ismet yürüdü

yılmadan

dirençle

davullar vuruldu

doğan güne karşı

zafer için

bayramlar için

devrimler için

insanca yaşamak için

vuruldu davullar

ve asırlık bir çınar devrildi

25 aralık 1973 günü

boşluğa değil

halkın kucağına

_istanbul şubat1974

_kelebek şubat1974 mansiyon', 'davullar vuruldu doğan güne karşı düşmanı yurttan kovmak için yürüdü ana bacı genç ihtiyar yürüdü zulmün üstüne ve garp cephesi komutanı ism...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ve-asirlik-cinar-devrildi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle doya doya...', 'seninle-doya-doya-ali-umran-sonmez-h8b7g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karanlık geceler hiç bitmez diyordum.

Sevmeyi yıllardır hep bekliyordum.

Hasretinle yanıp artık gelmez diyordum.

Uzatsana ellerini tutayım doya doya...

Yapayalnız anlamsızdı bana o yerler, 

Konuşurken deniz ve martılarla, 

Artık birlikte gezeriz senle, 

O sahilleri doya doya...

Sevgiyi muhabbeti sende buldum, 

Kaybettiğim neşemi de sende.

Ne olur yakın ol hep bana, 

Öpeyim seni doya doya...

                              1975', 'Karanlık geceler hiç bitmez diyordum. Sevmeyi yıllardır hep bekliyordum. Hasretinle yanıp artık gelmez diyordum. Uzatsana ellerini tutayım d...', ARRAY['Türk Edebiyatı','Şiir','Ali Ümran Sönmez']::text[], 8.5, '{"poet":"Ali Ümran Sönmez","poet_slug":"ali-umran-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seninle-doya-doya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Senin Cesur Yürekli Serçen Değilim Artık', 'ben-senin-cesur-yurekli-sercen-degilim-artik-bahar-temmuz-i4tl7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '. Ben senin cesur yürekli serçen değilim artık, 

Ne kadar değiştim, bilsen ağlarsın.

Boşa gitti onca yıllık savaşım, 

Bir mum yakamadım insanlık için, 

Bir dal yeşermedi ektiğim tohumlardan.

-Ya ben nasıl yaşadım? -

Ne aydınlatabildim karanlıkları bir parça, 

Ne insanca yaşamı öğretebildim köle ruhlara, 

Ne umut verebildim umutsuzlara, 

Ne başkaldırmayı öğretebildim haksızlıklara, 

Ben senin cesur yürekli serçen değildim zaten

-Ya ben nasıl yaşadım? -

Sitem etmeye hakkım yok hiç kimseye, 

Anlamadılar diyemem, anlatamadım.

Hani ideallerim vardı benim, mücadele gücüm, 

Hani savaşacaktım insanlık için

Çok çabuk kırıldı kanatlarım, uçamadım.

- Ya ben niye yaşadım? -

Ben senin cesur yürekli serçen değilim, ne yazık! 

Çoktan ayak uydurmuşum bu düzene.

Çoktan kapılmışım bu çarkın dişlilerine, 

Yaşamışım bir ipek böceği misali, 

Kendi kozam içinde, umarsız.

Vurmuşlar beni bir havuz başında su içerken

VURULDUĞUMU BİLE ANLAMAMIŞIM.', '. Ben senin cesur yürekli serçen değilim artık,  Ne kadar değiştim, bilsen ağlarsın. Boşa gitti onca yıllık savaşım,  Bir mum yakamadım insa...', ARRAY['Türk Edebiyatı','Şiir','Bahar Temmuz']::text[], 8.5, '{"poet":"Bahar Temmuz","poet_slug":"bahar-temmuz","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ben-senin-cesur-yurekli-sercen-degilim-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerime Bak Ne Olursun', 'gozlerime-bak-ne-olursun-bahar-temmuz-14j98', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerime bak ne olursun, 

Ve sevdiğini söyle beni delice.

Tüm duyguların yansısın gözlerine, 

Ve ben olayım, kahverenginde.

Gözlerime bak ne olursun, 

Sarsın beni kahverengi sıcaklığın.

Yangınları göreyim gözlerinde, 

Benim gözlerimdeki yangınlara eş.

Gözlerime bak ne olursun, 

Daima seveceğini söyle beni, 

Öyle yalın ve gerçek olsun ki aşkın

Kahverengi denizlerde boğulayım.

Gözlerime bak ne olursun, 

Birlikte bir gelecek vaat ederek.

Öyle yoğun olsun ki sevdan, 

Kahverengi gözlerinde yok olayım.', 'Gözlerime bak ne olursun,  Ve sevdiğini söyle beni delice. Tüm duyguların yansısın gözlerine,  Ve ben olayım, kahverenginde. Gözlerime bak n...', ARRAY['Türk Edebiyatı','Şiir','Bahar Temmuz']::text[], 8.5, '{"poet":"Bahar Temmuz","poet_slug":"bahar-temmuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gozlerime-bak-ne-olursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakın', 'yakin-muhammed-ali-erol-hqijx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'arada bir hatırla beni

hep yaptığın gibi

saklı kalan içimizdeki

bir anıyı hatırlamak için

arada bir hatırla beni

kendimi avutmak için

seçtiğim bütün yüzleri

ve yaşanmamışlık saydığım her şeyi

inadına dökülen saçlarımı

son defa taramadan

denize son taşı atmadan

artık bu son demeden

sonumuzun ne olduğunu bile bile

arada bir hatırla beni.

biz istemesek de 

geçiyor bak yalancı zaman

eski defterleri karıştırmadan

ve yepyeni bir hayatı

yaşayacağımızı umarak

hatırla beni...

sana biçilen gelecek

geleceğini çalmadan yakala umutlarını.

hiçbir şey için geç değil

hiçbir şey için geç değil!', 'arada bir hatırla beni hep yaptığın gibi saklı kalan içimizdeki bir anıyı hatırlamak için arada bir hatırla beni kendimi avutmak için seçtiğ...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Ali Erol']::text[], 8.5, '{"poet":"Muhammed Ali Erol","poet_slug":"muhammed-ali-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/yakin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçuruma Düşerken', 'ucuruma-duserken-naime-erlacin-s8eog', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sürgülendi gönül 

kilitli kapılardan beter

bir şimşekle derdim var 

uçurumda 

benimle dillenen

yaşamdan siliniyor muyum ne? 

derdim 

kara bir bulutla

karanlığı gözlüyorum

kışa dönüyor bahçem 

yağmur yuttu masalları

ruhtan kopan 

ince duyguları

şair kim

şiir ne 

ben kimim? 

derdim kendimle 

uçuruma 

kendimle düşerken 

(2003)', 'sürgülendi gönül  kilitli kapılardan beter bir şimşekle derdim var  uçurumda  benimle dillenen yaşamdan siliniyor muyum ne?  derdim  kara bi...', ARRAY['Türk Edebiyatı','Şiir','Naime Erlaçin']::text[], 8.5, '{"poet":"Naime Erlaçin","poet_slug":"naime-erlacin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ucuruma-duserken-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Gün', 'i-ki-gun-zaman-baykara-98xun', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki gün kutsaldır

Biri doğum, öteki ölüm.

ikisinin arasında yaşadıkların senindir

Yaşayamadıklarınsa benim...', 'İki gün kutsaldır Biri doğum, öteki ölüm. ikisinin arasında yaşadıkların senindir Yaşayamadıklarınsa benim......', ARRAY['Türk Edebiyatı','Şiir','Zaman Baykara']::text[], 8.5, '{"poet":"Zaman Baykara","poet_slug":"zaman-baykara","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/iki-gun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nice Zamandır', 'nice-zamandir-muammer-kurt-pr3y8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nice zamandır...

Sana bir şey söyleyeceğim.

Çoookk... 

Çok şey söyleyeceğim.

Ama yüreğim küt küt vuruyor

dilim susuyor.

Gözlerine bakacağım...

Ağustosun sahilinde buz gibi

eriyip yüreğine akacağım.

Ama bakamıyor gözlerim

gözüm korkuyor.

Elimi tutsam eline, 

tenimi sürsem tenine, 

çılgın bahar olurum kendi kendime.

Ama tarif edemiyorum

Bir şey oluyor.

Uzatacağım elimi, 

saçlarından yıldız tutacağım.

Fırlayacağım karanlıktan şafağa.

Sana doyacağım.

Ama ruhum titriyor.

Yine olmuyor.                

......................Dilim susuyor

............................Gözüm korkuyor

..........................................Bir şey oluyor

.....................................................Yine olmuyor,

.................................................................Olmuyor işte...', 'Nice zamandır... Sana bir şey söyleyeceğim. Çoookk...  Çok şey söyleyeceğim. Ama yüreğim küt küt vuruyor dilim susuyor. Gözlerine bakacağım....', ARRAY['Türk Edebiyatı','Şiir','Muammer Kurt']::text[], 8.5, '{"poet":"Muammer Kurt","poet_slug":"muammer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/nice-zamandir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavrum', 'yavrum-muammer-kurt-yraz9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karanfiller arasında

Kundak kundak bebeler var

Yağlı kurşun yarasında

Ana sütü meme arar

Tahta çarmıh salıncağı

Zindanlarda büyüyecek

Hücreler baba ocağı

Direnmeden ölmeyecek

Yavrum yaşamın başında

Yürüyemez emekliyor

Civanım on beş yaşında

İdam sehpası bekliyor

Bir gün hesap sormak için

Yaşadığın bunca çile

Aydınlığa varmak için

Durma! yürü koş menzile

Artık şafak vakti oldu

Yıldızlarım tek tek kayar

Karanlığın günü doldu

Milyon milyon yıldız doğar', 'Karanfiller arasında Kundak kundak bebeler var Yağlı kurşun yarasında Ana sütü meme arar Tahta çarmıh salıncağı Zindanlarda büyüyecek Hücrel...', ARRAY['Türk Edebiyatı','Şiir','Muammer Kurt']::text[], 8.5, '{"poet":"Muammer Kurt","poet_slug":"muammer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yavrum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Damla Gözyaşı', 'i-ki-damla-gozyasi-zaman-baykara-83npm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İki damla gözyaşıdır 

Senden geriye kalan 

İki damla gözyaşı 

Ve sana ait olmayan', 'İki damla gözyaşıdır  Senden geriye kalan  İki damla gözyaşı  Ve sana ait olmayan...', ARRAY['Türk Edebiyatı','Şiir','Zaman Baykara']::text[], 8.5, '{"poet":"Zaman Baykara","poet_slug":"zaman-baykara","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/iki-damla-gozyasi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavgalarım', 'kavgalarim-zaman-baykara-ivmxa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kavgalarım vardır benim, 

Kendimle yaptığım 

Sevgilerim vardır benim, 

Yalnızken yaşadığım. 

Bir de hayallerim vardır, 

Olmasada uzak, hiç ulaşamadığım.', 'Kavgalarım vardır benim,  Kendimle yaptığım  Sevgilerim vardır benim,  Yalnızken yaşadığım.  Bir de hayallerim vardır,  Olmasada uzak, hiç u...', ARRAY['Türk Edebiyatı','Şiir','Zaman Baykara']::text[], 8.5, '{"poet":"Zaman Baykara","poet_slug":"zaman-baykara","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kavgalarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi', 'simdi-muammer-kurt-3n3ec', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşayıp giderken kendi halıma

Yeşil yaprak oldun kuru dalıma

Bal vermez çiçektim kondun alıma

Gönlüme gazeli düşürme şimdi

Issız bir kuytuda mekan kurmuştum

Aşkın kapısına mühür vurmuştum

Karanfilden, gülden uzak durmuştum

Gözyaşı bendimi taşırma şimdi

Ya gerçekten sevdin yada aldattın

Menzilsiz yolcuyu kervana kattın

Açmayan goncaydım daldan koparttın

Meçhul diyarlara aşırma şimdi

Sen benim gönlümün çilesi miydin

Leyla’nın Mecnuna hilesi miydin

Aslının Kereme sillesi miydin

Hasret alazında pişirme şimdi

Hazan iken beni bahara katıp

Ölü denizimde tufan kopartıp

Hüzün pazarımda mutluluk satıp

Beni bir kenarda şaşırma şimdi', 'Yaşayıp giderken kendi halıma Yeşil yaprak oldun kuru dalıma Bal vermez çiçektim kondun alıma Gönlüme gazeli düşürme şimdi Issız bir kuytuda...', ARRAY['Türk Edebiyatı','Şiir','Muammer Kurt']::text[], 8.5, '{"poet":"Muammer Kurt","poet_slug":"muammer-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/simdi-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmak', 'olmak-zaman-baykara-2oavv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Olmak, bildiğin gibi 

Olmak 

yaşadığın gibi 

Olmak 

senin gibi, benim gibi 

Olmak 

Olmak, istediğin gibi', 'Olmak, bildiğin gibi  Olmak  yaşadığın gibi  Olmak  senin gibi, benim gibi  Olmak  Olmak, istediğin gibi...', ARRAY['Türk Edebiyatı','Şiir','Zaman Baykara']::text[], 8.5, '{"poet":"Zaman Baykara","poet_slug":"zaman-baykara","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/olmak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik Yaşam', 'yitik-yasam-nurhan-gokturk-mxg9p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Adımı soruyorlar hatırlamıyorum.

Dilimin ucunda bir isim, 

Şimdi söyleyeceğim.

Karanlık kapılar aralanıyor, 

Ufukta bir gölge hatırlamıyorum! 

Ama orada beni bekleyen biri var, 

Biliyorum! ! ! 

Kapılar açılıyor, kapanıyor, 

Bir çift göz hasretle, 

Biraz da buruk beni izliyor, 

Kimm! ! ! tanıdım tanıyacağım.

Ellerimi avuçlarında tutuyor, 

Öbür elinde tahta bir valiz, 

Cebinden otobüs bileti görünüyor, 

Apar, topar biniyoruz, 

Teker üstünde, bir kişilik yere, iki kişi.

Sımsıkı bağrına basıyor, 

Yanaklarından çaresizlik akıyor, 

Yüzünü saçlarıma gömüyor, 

O zaman anlamadım, 

Ağlıyordu! şimdi hatırlıyorum.

Bir şehirden, bir gardan diğerine.

Ne kadar zaman geçti, yollarda

Umutsuzca yürüdük, 

Kimi arıyorduk? Kimi soruyorduk? 

Bizi bekleyen biri var mıydı? 

Bu şehirde evler sıra dışı.

Çatılar, bacalar üstümüze üstümüze geliyor.

Evler büyüdükçe, biz küçülüyorduk.

Gökyüzünde yıldızlar görünmüyor

Işıl ışıl sokaklar, 

Yıldızlar yer yüzüne inmiş

Umutsuzluğun izinde

Akşam uykusuzluk gibi

Çöktü gözlerimize

Ne dizlerimizde derman kaldı.

Ne de bizi tanıyan. hatırlayan vardı.

Ellerim üşüyor, 

Koltuk altında ısıtıyorum, 

Ama ellerimi tutan biri vardı, 

Onu bulamıyorum.! ! ! 

Olur olmaz düşlerle avunuyorum.

Şimdi şu köşeden çıkacak, 

Ellerimi yeniden tutacak.

Darmadağınığım, 

Ağlarda ki balıklar gibi çırpınmaktayım.

Geniş caddelerinde gölgelerim, 

Benim peşimde, ben bu şehrin.

Bir ot nasıl yaşarsa öyle, 

Yağmurdan su, topraktan kan emerek, 

Ekmek elden, su gölden yaşıyorum.

Bir de kar yağmasa üşüyorum.

İki kolumdan tutup, beni niye kaldırıyorlar? 

Kim bu adamlar? 

Yüzüme neden böyle acıyarak bakıyorlar? 

''Tüm evsizleri toplayın, 

Kimliklerini sorun''

Elime yarım bir sigara tutturuyorlar, 

Adımı soruyorlar, hatırlamıyorum.

Sihirli bir değnekle dokunsa peri

Annem yeniden tutsa elimi.

Geçmişinden koparılan, 

Ben o gün sokakta bırakılan, 

Çocuk değilim.

Işıklarına sevdalandığım, 

Hasretine yandığım, 

Bu şehir beni unutur, 

Kimim? Nerden gelip, nereye gidiyorum? 

Çöplerde şişe, kağıt, poşet

Toplayan çocuklar! ! ! 

Bende kendimi atsam

Yeniden dönüşe bilir miyim? 

Bu şehir beni hatırlar mı? 

Annem elimi yeniden tutar mı? 

Nurhan Göktürk

(22 Şubat 2003 Antalya)', 'Adımı soruyorlar hatırlamıyorum. Dilimin ucunda bir isim,  Şimdi söyleyeceğim. Karanlık kapılar aralanıyor,  Ufukta bir gölge hatırlamıyorum...', ARRAY['Türk Edebiyatı','Şiir','Nurhan Göktürk']::text[], 8.5, '{"poet":"Nurhan Göktürk","poet_slug":"nurhan-gokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/yitik-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül', 'eylul-nurhan-gokturk-03a3b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hazan mevsiminde, 

Ne hüzünlüdür Eylüller.

Dökülen yaprakların içinde yürümek, 

Toprakları avuçlarımda dinlendirmek.

Sabahları çiğ olup, yapraklarla oynaşmak, 

Eylül''ün yakıcı sıcağında, 

Sırtımı duvara verip uyuşuk uyuşuk oturmak, 

Karıncaların gayretini, 

Ağustos böceklerinin kayıtsızlığını, 

Ne inanılmaz, doğadaki bitişi, gözlemek.

Şimdi seri zamanı gelmiştir, bağlarda.

Üzüm toplama, bağ bozumu, 

Pekmez, Köfter kokuları doluşur, 

Komşu evlerden.

Başak toplamanın zevkini, 

Benden iyi kim bilebilir ki,! 

Böyle bir Eylül sabahında

Geldim dünyaya, 

Ve inanıyorum ki; 

Yine bir Eylül de hüzünlü olacak gidişim.

Kızım olursa adını Eylül koymalıyım.

Adını her söyleyişimde, 

Daldan düşen yaprak gibi titresin içim.

Eylül hüznüm, terk edilmişliğim, 

Eylül düşlerim, geçmişim, 

Eylül tüm ayak dirememe karşın, 

Çaresizce gidişim.

Nurhan Göktürk

(29 Ocak2003Antalya)', 'Hazan mevsiminde,  Ne hüzünlüdür Eylüller. Dökülen yaprakların içinde yürümek,  Toprakları avuçlarımda dinlendirmek. Sabahları çiğ olup, yap...', ARRAY['Türk Edebiyatı','Şiir','Nurhan Göktürk']::text[], 8.5, '{"poet":"Nurhan Göktürk","poet_slug":"nurhan-gokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/eylul-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-umudun-yolcusu-5ld21', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gece

içinde sensizliğimin acı çığlığı var

gece

içinde seninle alev alan dudaklar

yıldızları gözlerindeki ışıltıyla sildiğin

gece

karanlığı ateşinle aydınlattığın

gece

o gece ki 

aklıma bir saplanıştı

bir daha hiç çıkmayacağını

gösterdiğin günün en güzel saatlerinde gizliydi

gece

yüreğime bıraktığın sevginin en tatlı

ayak iziydi.', 'Gece içinde sensizliğimin acı çığlığı var gece içinde seninle alev alan dudaklar yıldızları gözlerindeki ışıltıyla sildiğin gece karanlığı a...', ARRAY['Türk Edebiyatı','Şiir','Umudun Yolcusu']::text[], 8.5, '{"poet":"Umudun Yolcusu","poet_slug":"umudun-yolcusu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gece-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığın Ayrıldığı An', 'ayriligin-ayrildigi-an-umudun-yolcusu-v75qj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Düşlüyorum

düşünüyorum

gözlerimi kapayıp

ellerimi saçlarında ısıtıyorum

sanki sen dönmüşsün gibi

kendimi kandırıyorum

aldatıyorum yüreğimi

aldandıkça 

aydınlanıyorum.', 'Düşlüyorum düşünüyorum gözlerimi kapayıp ellerimi saçlarında ısıtıyorum sanki sen dönmüşsün gibi kendimi kandırıyorum aldatıyorum yüreğimi a...', ARRAY['Türk Edebiyatı','Şiir','Umudun Yolcusu']::text[], 8.5, '{"poet":"Umudun Yolcusu","poet_slug":"umudun-yolcusu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ayriligin-ayrildigi-an-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü', 'olu-nurhan-gokturk-0sjpj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Görmedi sandılar, oysa gördüm.

Önce ayakkabılarımı attılar.

Çoraplarımı, gömleklerimi, 

Pijamalarımı verdiler, 

Dilencinin birine.

Zavallı nasılda sevindi.

Enayi! ! ! 

Eskiydi aldattılar seni.

Şuna bak sağlığımda yüzüme bakmazdı! 

Öldüm salımın ucundan tuttu.

Değerimi anlaman için, 

Ölmem mi lazımdı? 

Getirdiler attılar bu karanlık çukura.

Hey! ! Yok mu? buranın  ışıkları! ! 

Yaksana! ! 

Üşüyorum! ! Üstüme bir battaniye atsana.

Kilidi kim vurdu kapıma? 

Kim dikti bu taşı başıma? 

Gitmeliyim! ! 

En güzel gençliğim, kaldı orada.

O yaşanmamış dün müydü? 

Yazık şimdi biz öldük mü? 

Nurhan Göktürk

(19 Şubat 1985 Konya)', 'Görmedi sandılar, oysa gördüm. Önce ayakkabılarımı attılar. Çoraplarımı, gömleklerimi,  Pijamalarımı verdiler,  Dilencinin birine. Zavallı n...', ARRAY['Türk Edebiyatı','Şiir','Nurhan Göktürk']::text[], 8.5, '{"poet":"Nurhan Göktürk","poet_slug":"nurhan-gokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/olu-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız Kuşlar', 'yalniz-kuslar-nurhan-gokturk-7qjs9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her hazan mevsiminde, 

Terk eder sılayı, son kuşlar.

Arkalarında  yaşlı gözler, 

Hasta, yaralı kalır.

Yalnız kuşlar.

Kış tül perdeleri, 

Çekince pencerelere.

Onlarda kaybolup gider, 

Bir garip yalnızlık  içinde.

Şimdi geceler, ökse kurmuş, 

Yılanlı kayada, 

Yalnız kuşları avlamakta.

Nurhan Göktürk

(21Şubat 1985 Konya)', 'Her hazan mevsiminde,  Terk eder sılayı, son kuşlar. Arkalarında  yaşlı gözler,  Hasta, yaralı kalır. Yalnız kuşlar. Kış tül perdeleri,  Çek...', ARRAY['Türk Edebiyatı','Şiir','Nurhan Göktürk']::text[], 8.5, '{"poet":"Nurhan Göktürk","poet_slug":"nurhan-gokturk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalniz-kuslar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geometrik Aşk', 'geometrik-ask-umut-ulbegi-dykrx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Açı üstüne açı yapar

üçgenin

üç

kenarı

ama asırlardır

sekizgene vurgundur.', 'Açı üstüne açı yapar üçgenin üç kenarı ama asırlardır sekizgene vurgundur....', ARRAY['Türk Edebiyatı','Şiir','Umut Ülbegi']::text[], 8.5, '{"poet":"Umut Ülbegi","poet_slug":"umut-ulbegi","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/geometrik-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarasızlar', 'yarasizlar-sair-musturk-h0hnq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaram sızlar

Yaram sızlar

Açtığın yara sızlar

Ben yaramdan utanmam

Utansın yarasızlar

Can demiştim ben sana 

El oldun şimdi sen bana 

Onca yaşanandan sonra

Nasıl gülerim yüzüne 

Hiçbir şey olmamışçasına

Belki o da haklı

Böyle diyordu aklı

Galiba aşkın sırrı

Mantıksızlıkta saklı', 'Yaram sızlar Yaram sızlar Açtığın yara sızlar Ben yaramdan utanmam Utansın yarasızlar Can demiştim ben sana  El oldun şimdi sen bana  Onca y...', ARRAY['Türk Edebiyatı','Şiir','Şair Mustürk']::text[], 8.5, '{"poet":"Şair Mustürk","poet_slug":"sair-musturk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yarasizlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gerçekçiyim ya!', 'gercekciyim-ya-ozer-bal-gspg0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'düşündüğümde seni

sıcaklık sarar içimi

buruk bir haz duyarım

yüreğim, yakalanmış kuş yüreği.

bir daha düşünürüm

seni, beni

soğuturum içimi.

kuş uçar, 

üşürüm...', 'düşündüğümde seni sıcaklık sarar içimi buruk bir haz duyarım yüreğim, yakalanmış kuş yüreği. bir daha düşünürüm seni, beni soğuturum içimi. ...', ARRAY['Türk Edebiyatı','Şiir','Özer Bal']::text[], 8.5, '{"poet":"Özer Bal","poet_slug":"ozer-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gercekciyim-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AY', 'ay-evrim-nisan-y4exe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'ay doğduğunda yeni bir yazın olur

çünkü beklediğin gölgelerin çekilmesi

karışır uzaklarda bir adam

ay doğduğunda yeni bir kışın olur

uykuya çekilir elinin ayası

düşünür uzaklarda bir adam

ay doğduğunda yeni bir işin olur

güzeldir kara dizeleri sayması

ilişir uzaklarda bir adam

ay doğduğunda yeni bir yaşın olur

zaman acemi bir yıldız kayması

sevinir uzaklarda bir adam', 'ay doğduğunda yeni bir yazın olur çünkü beklediğin gölgelerin çekilmesi karışır uzaklarda bir adam ay doğduğunda yeni bir kışın olur uykuya ...', ARRAY['Türk Edebiyatı','Şiir','Evrim Nisan']::text[], 8.5, '{"poet":"Evrim Nisan","poet_slug":"evrim-nisan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ay-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'beyaz geceler', 'beyaz-geceler-firat-erol-rnnfm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Beni düşündün bir tren camından dünyaya bakarken, sonra hayatlarını okuduğun roman kahraamanlarını getirdin aklına ayrı roller denedin onlara bize ve başkalarına yaptığın gibi. Sen şimdi bunları düşünürken ben seni bekliyorum düş sokağında kurban ediyorum kendimi sana sonra ulaşıyorum nirvanaya nirvanaya.

karanlığa direniyor kuzey güneşi, ışığı yansıyor tren camına bu sıcak yaz gününde beyaz gecede beyaz gecede', 'Beni düşündün bir tren camından dünyaya bakarken, sonra hayatlarını okuduğun roman kahraamanlarını getirdin aklına ayrı roller denedin onlar...', ARRAY['Türk Edebiyatı','Şiir','Fırat Erol']::text[], 8.5, '{"poet":"Fırat Erol","poet_slug":"firat-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/beyaz-geceler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pudra Şekerim', 'pudra-sekerim-aysenur-yazici-q1yy6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Pembe bir lokumun içindeki fındık, 

Gitmeden önce, uzatılan ömrümdün sen

Aşık olduk, pudra şekerine bulandık

Genzimize kaçırdık ne olduğunu bilmeden...', 'Pembe bir lokumun içindeki fındık,  Gitmeden önce, uzatılan ömrümdün sen Aşık olduk, pudra şekerine bulandık Genzimize kaçırdık ne olduğunu ...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/pudra-sekerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resmini Yaktım', 'resmini-yaktim-aysenur-yazici-7i2wn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sahura kalktı yine ruhum

Gecenin bir yerinde...

Sen de uyumuyordun biliyordum

Bir minareden seslendin sanki bana

Ağzıma iki zeytin attım

Pencereden boş bir bakış sokağa..

''Gönül nikahım yok sana'' deyişin

Ezanın sonunda tekrarlandı..

İsmin kımıldandı yüreğimde

Güya aldırmadım

Dürttü birşeyler işte

Resmini yaktım

Ağladım..

Ağladım...', 'Sahura kalktı yine ruhum Gecenin bir yerinde... Sen de uyumuyordun biliyordum Bir minareden seslendin sanki bana Ağzıma iki zeytin attım Pen...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/resmini-yaktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Tamiratta', 'zaman-tamiratta-aysenur-yazici-2ywsl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aklım bağırır

''Git acılardasın'' diye

Kalbim azarlar, 

''Onsuz yapamazsın'' der

Hele dene! 

Yüreğim ürker

Gördüğüm herşey titrer

Yanlışlar hasatta, 

Sap saman aynı yere düşer...

İçimdeki tüm Ayşe''ler bağırır

''Olur bu kadar kavga''der, 

Olur bu kadar karmaşa

Aşk sızısı ardından

Zaman tamiratta...', 'Aklım bağırır ''Git acılardasın'' diye Kalbim azarlar,  ''Onsuz yapamazsın'' der Hele dene!  Yüreğim ürker Gördüğüm herşey titrer Yanlışlar hasa...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/zaman-tamiratta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arayış', 'arayis-selami-ozturk-tnmor', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aslında gitmek değil benimki

Kendimden kaçıyorum

Gitmek olsaydı eğer

Elveda demeden gidemezdim

Beklersen Döneceğim

Aslında gitmek değil benimki

Beni hayata bağlayan

Umudumu kaybettim.

Onu arıyorum.

Bulursam Döneceğim', 'Aslında gitmek değil benimki Kendimden kaçıyorum Gitmek olsaydı eğer Elveda demeden gidemezdim Beklersen Döneceğim Aslında gitmek değil beni...', ARRAY['Türk Edebiyatı','Şiir','Selami Öztürk']::text[], 8.5, '{"poet":"Selami Öztürk","poet_slug":"selami-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/arayis-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SEN VE YİNE SEN', 'sen-ve-yi-ne-sen-selami-ozturk-llqoi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yeni bir sabaha kapanırken gözlerim.

Ruhumda yanlızlıgım

Düşüncelerimde hayatın anlamsızlıgı

Kalbimde beni kovalayan ölüm korkusu

Ve hayatımda mutlu olabildiğim tek şey

SEN SEN SEN  SEN SEN SEN', 'Yeni bir sabaha kapanırken gözlerim. Ruhumda yanlızlıgım Düşüncelerimde hayatın anlamsızlıgı Kalbimde beni kovalayan ölüm korkusu Ve hayatım...', ARRAY['Türk Edebiyatı','Şiir','Selami Öztürk']::text[], 8.5, '{"poet":"Selami Öztürk","poet_slug":"selami-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sen-ve-yine-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BASİT ŞAİR', 'basi-t-sai-r-selami-ozturk-s8ofe', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Basit düşüncelerden yola çıkan

Basit kelimelerden oluşan

Basit cümlelerle son bulan

Basit şiirlerin 

Basit şairiyim ben.', 'Basit düşüncelerden yola çıkan Basit kelimelerden oluşan Basit cümlelerle son bulan Basit şiirlerin  Basit şairiyim ben....', ARRAY['Türk Edebiyatı','Şiir','Selami Öztürk']::text[], 8.5, '{"poet":"Selami Öztürk","poet_slug":"selami-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/basit-sair-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana İşkence Etti Polis Bey', 'bana-i-skence-etti-polis-bey-aysenur-yazici-6cpsf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bana işkence etti polis bey

Ama şikayetçi değilim

İlk gözlerime ateş etti

''Gözüm'' oldu ellerim, 

Dokunarak bakmayı

Ondan sonra öğrendim

    Sabrımı sarmaşık yapıp boynuma

    Nefesime ortak oldu ah..

    Karıncalar su taşıdı dilime

    Darağacına astı üç yüz gün ölmedim! 

    Günah..

Bana işkence etti polis bey

Ama şikayetçi değilim

Yüreğime zincir vurup, 

Yangın çıkaran O, tenimde

Dumana direnen aşk yaşadı

Ama kömür oldu bedenim de...

Her kahkahamda bir tırnak söküldü

Ceza! 

İnlemelerime kapılar kapandı

Kanlarım tüm şehre döküldü

Yazda ve ayazda...

      Bana işkence etti polis bey

      Ama şikayetçi değilim

      Sözlerini kızgın yağ yapıp, 

      Her gece kulaklarıma döktü

      Gurur kadar ağır topuzlar

      Omuzlarımı çürüttü

      Kemiklerim köpeklere atıldı

      Saçlarım kuyulara

      Cesedim bir cüzdana satıldı

Bana işkence etti polis bey

Ama şikayetçi değilim

O parasının derdinde

Herkes zalimliğini bilsin diye

Kanım dövme kalacak ellerinde..

...Şikayetçi değilim polis bey

   Değilim yine de', 'Bana işkence etti polis bey Ama şikayetçi değilim İlk gözlerime ateş etti ''Gözüm'' oldu ellerim,  Dokunarak bakmayı Ondan sonra öğrendim     ...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/bana-iskence-etti-polis-bey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Yarısı Kanayışları', 'gece-yarisi-kanayislari-harun-taskin-byjoh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hasretinden prangalar eskimese de

Bir ömrün

Son nefes alma tarihi çoktan geçti...

Dehlizlere kaptırdığım hayallerim

Gün oldu

Güneşle filizlendi..

Bitmeyen günlerin sağanağında

Bu gönül

Sepkenlere inat harelendi..

Sustuysa satırlarım bir gün

Düşmediyse eline göz yaşlarım

Saatlerce çalıp ta açılmadıysa telefon

Seni içimde söndürdüğümden değil

İçimdeki nefesin tükendiğindendir...

14.01.2003', 'Hasretinden prangalar eskimese de Bir ömrün Son nefes alma tarihi çoktan geçti... Dehlizlere kaptırdığım hayallerim Gün oldu Güneşle filizle...', ARRAY['Türk Edebiyatı','Şiir','Harun Taşkın']::text[], 8.5, '{"poet":"Harun Taşkın","poet_slug":"harun-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gece-yarisi-kanayislari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yara', 'yara-mutluhan-kurt-yt89s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bu yorgun gecelerin ellerine bırakma demiştim yüreğini.ıslatır bu kirli yağmurlar ellerini, tenini, bedenini.ıslatır bizi...kirleniriz...demiştim...

gidişinin ardından bir suskunluk büyüttüm yüreğimde avaz avaz susarak.boşluğuna dolsun diye.dolmadı...artık ellerimi yüzüme çivileyip çıkıyorum kendi içimden.acılarımı yaralarıma sarıyorum.acı sağdıkça hayattan damarlarıma, damarlarıma bir ülke sığdırıyorum...

kimi morglara adımı taşıdım.adımı adının yanına taşıdım yitik cenazeler eşliğinde.bir gül kaldı, bir ağıt geride bıçak kadar keskin kaldı biraz(senden de) ...-senden kalırmıydı kimbilir, her mevsim intihar edip, her gün adını susmasaydım yüreğime...-sen kal içimde hep biraz, kalmazsan içim tükenir...

şiir ölür bazı akşamlar, her şey biter, rakı, söz, kalem.ay ışığı biter.sen bitme diye ben şiir yazarım.bitsemde...

bittim sonra...gözlerime intihar değmişti nasıl olsa, ellerime kan.sonra kuşlar uçurum getirdiler biraz.uzak haritalar, uzak iklimler.tenini getirdi sonra kuşlar.kanatlarına takmıştım yüreğimi kuşların.kanadılar.

kimi kuşlar taşır yükünü sevdanın kanasalarda...

unutma; o kuşlar teninde boğuldular...', 'bu yorgun gecelerin ellerine bırakma demiştim yüreğini.ıslatır bu kirli yağmurlar ellerini, tenini, bedenini.ıslatır bizi...kirleniriz...dem...', ARRAY['Türk Edebiyatı','Şiir','Mutluhan Kurt']::text[], 8.5, '{"poet":"Mutluhan Kurt","poet_slug":"mutluhan-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yara-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aksaray', 'aksaray-celalettin-koz-egg94', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yıllar çabuk geçti, geldim Aksaray, 

Yollar tıkansa da sana aksa ray, 

Gecem olduğunda bende aksar ay, 

Sevda mağrur sultan, gönül ak saray.

Yollar tıkanır da gelemezsem bil, 

Şair gönlüm kırık, sana Aksaray.

Kulak ver gönlüme, birazcık eğil,

Nice sultanlar gitti, kaldı ak saray.', 'Yıllar çabuk geçti, geldim Aksaray,  Yollar tıkansa da sana aksa ray,  Gecem olduğunda bende aksar ay,  Sevda mağrur sultan, gönül ak saray....', ARRAY['Türk Edebiyatı','Şiir','Celalettin Koz']::text[], 8.5, '{"poet":"Celalettin Koz","poet_slug":"celalettin-koz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aksaray-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GELİYORUZ HA', 'geli-yoruz-ha-atilla-kaya-96so3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dağların yücesinde yanan ateş

İçimizdeki odunları tutuşturdu

Nasıl şekillenirse demir

Nasıl işlenirse toprak

İnce, ince kazılıyor yüreklere

Geçiyoruz diyalektik elekten

Öğrendik, her şeyi elimizde

Ne bekleriz bilmem şu felekten

Gözlerimizde yanan inançlı yalım

Kavuracak herkesi

Kucaklıyacağız dünyayı

Artık bu savaş ölum değil yalnız kalım

Geliyor genç nefesler çığ gibi

Yürüyerek değil yalnızca

Tankla değil

Tüfekle değil

Sevgiyle, kitapla, bilgisayarla

Belki şimdi, belki elli yılda

Bükeceğiz bileğini zalim kapitalizmin

İnanın

Dikeceğiz bayrağını sosyalizmin

Değiliz ütopik, maceracı

Bazıları gibi dönek, numaracı

Biliyoruz güveniyoruz kendimize

Düzgün kesin adımla yürüyoruz

Çünkü; 

Biz ademoğluyuz.', 'Dağların yücesinde yanan ateş İçimizdeki odunları tutuşturdu Nasıl şekillenirse demir Nasıl işlenirse toprak İnce, ince kazılıyor yüreklere ...', ARRAY['Türk Edebiyatı','Şiir','Atilla Kaya']::text[], 8.5, '{"poet":"Atilla Kaya","poet_slug":"atilla-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/geliyoruz-ha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OLACAK TI', 'olacak-ti-atilla-kaya-01bhr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıkılıp

Terkedilip

Yüzüstü bırakıldığında

Umarsız

Göçüp gittiğimi öğrenince

Çaresiz, yılgın ve acı içinde

Çocuğunu kaybetmiş analar gibi

Dört bir yana dağılacaksın

Geçte olsa sonunda

Beni sevdiğini anlayacaksın.', 'Yıkılıp Terkedilip Yüzüstü bırakıldığında Umarsız Göçüp gittiğimi öğrenince Çaresiz, yılgın ve acı içinde Çocuğunu kaybetmiş analar gibi Dör...', ARRAY['Türk Edebiyatı','Şiir','Atilla Kaya']::text[], 8.5, '{"poet":"Atilla Kaya","poet_slug":"atilla-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olacak-ti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YİTİK YILLARIN BİLANÇOSU', 'yi-ti-k-yillarin-bi-lancosu-atilla-kaya-6lyrb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hızla yol alırken ulaşılası güneşe

Sorgular süreç içimizdeki kaosu

Anlamsızlıkta anlam arayanı

Bitip tükenmeyen ihanetten yılanı

Sevgi adına sevgisizce

         Sapıtıp kendini Napolyon, Sezar

                         Peygamber sananı

İlericilik adına kinini kusup

                       Azdıkca azanı

Rotasını şaşırıp ukalaca

                         Barlarda sızanı

Hala biçilmeyi bekleyen altın başak

Ve inadına çoraklaşan beyinlerdeki toprak

İşte

Memleketimdeki son insan manzaraları

Devrim adına nasıl yaratıldı bilmem

Böyle yüzlerce lümpen hanzoları', 'Hızla yol alırken ulaşılası güneşe Sorgular süreç içimizdeki kaosu Anlamsızlıkta anlam arayanı Bitip tükenmeyen ihanetten yılanı Sevgi adına...', ARRAY['Türk Edebiyatı','Şiir','Atilla Kaya']::text[], 8.5, '{"poet":"Atilla Kaya","poet_slug":"atilla-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yitik-yillarin-bilancosu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bazen Diyorum', 'bazen-diyorum-salih-ozalasan-5ontr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sen ağlıyorsun, bir ben

Kader bize düşman mı, bir bilsem

Günün yarısında ağlıyoruz, yarısında gülsem

Bazen diyorum ah, kaderimizi yeniden yazabilsem

Daima birkaç damla gözyaşı

Akmaya hazır, gülerken gözlerimizden

Kahkahaya çeyrek kala boşanır birden

Bazen diyorum ah, şu gözyaşlarına son verebilsem

Bizde topraktan bir can

İki damla kan pıhtısı ceninden

Yaratılmadık mı herkes gibi etten kemikten

Bazen diyorum ah, keşke yaratılsaydık çelikten

İçimde hep bir umut

Karanlıkta parlayan bir ışık hafiften

Bugün belki iyi olur diye dünümden

Bazen diyorum ah, keşke zamanı durdurabilsem

Razıyım her şeye, gözlerini gülerken 

Yüreğin mutlu, bir kuş gibi uçarken

Yolsam da saçlarımı, kurtulmasam da  sitemden

Bazen diyorum ah, senin yerinede ben ağlayıp üzülebilsem

Y.Tarihi 15-03-2003 Saat 12-35

Salih ÖZALAŞAN', 'Bir sen ağlıyorsun, bir ben Kader bize düşman mı, bir bilsem Günün yarısında ağlıyoruz, yarısında gülsem Bazen diyorum ah, kaderimizi yenide...', ARRAY['Türk Edebiyatı','Şiir','Salih Özalaşan']::text[], 8.5, '{"poet":"Salih Özalaşan","poet_slug":"salih-ozalasan","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/bazen-diyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '2023''te gelecek', '2023-te-gelecek-aysenur-yazici-3m1jw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sakın öleyim deme! 

Ben de ölürüm

Öyle bir mektup alacaksın ki 

İki bin yirmi üçte

Görünce

Ne çatısı kalacak dünyanın

Ne sancısı yüreğinin

Kendimi sarıp sarmalayıp, 

Sandık lekesine bulayıp, 

67 Yaşına yolladım sevdiğim...

Tabii ki hatırlayacaksın! 

Hesapsız kaç kadının var ki? 

Saçlarımı, ellerimi

Mektuptan uzatacağım

İkiz ruhumuz kavuşacak

Kesin ağlayacağım..

Şaşıracaksın ama

Gerek yok telaşa

Sen sadece ne olur

Yirmi bir yıl daha yaşa! ..', 'Sakın öleyim deme!  Ben de ölürüm Öyle bir mektup alacaksın ki  İki bin yirmi üçte Görünce Ne çatısı kalacak dünyanın Ne sancısı yüreğinin K...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/2023-te-gelecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AKSAM VAKTI', 'aksam-vakti-seref-kaya-5n76f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Heryerde Eflatun tüyleri, 

Gölgelenir, aksam vakti.

Icli öten bülbüllerle, 

Duygulanir aksam vakti.

Özleyis atesden bir ok, 

Sen isikta teselli yok, 

Gönlüm sevgiyle cok, 

Ilgilenir aksam vakti.

Biraz sonra dogacak ay, 

Duygum keman, düsüncem yay, 

Renk, isik, ses kalpte hersey, 

Calkalanir aksam vakti.

Silindi gökteki; mor iz, 

Sustu bülbül soldu beniz, 

Ruhumdaki engin deniz, 

Calkalanir aksam vakti.

29.09.71 adana               seref kaya', 'Heryerde Eflatun tüyleri,  Gölgelenir, aksam vakti. Icli öten bülbüllerle,  Duygulanir aksam vakti. Özleyis atesden bir ok,  Sen isikta tese...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/aksam-vakti-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklambaç', 'saklambac-hayrettin-turk-ttgz3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kırkyedi, kırksekiz

kırkdokuz, elli

Sağım solum, önüm arkam

saklanan ebe...

Saçlarının ışığından 

tanırdım seni.

Bana bakardın gözlerin kapalıyken

ve yakalanırdın hep..

Ersin tepesinde asırlık ağaç

başımı dayayıp saydığım

Ebe hep ben olurdum

Sen ise aradığım...

Gökle yer ikimizindi

Yeşillle mavi gözlerimiz

Sobe, sobe yankılanırdı o ağaçta

ve vuran masum ellerimiz...

Aşıktım o zamanlar sana

Senin bana olduğun kadar

Bilirdi aşkımızı Ersin tepesi

ve ötesindeki dağlar...

Saymasını elliye kadar bilirdik

Sonrası yalnız iki

Sen bir, ben iki

Ben bir, sen iki...

Bazen ağacıda sayardık

Üç derdik ama şahit

Toplardık dökülmüş yapraklarını

Herbiri olurdu bir şahit...

Bir gün gene saydım

Kırkyedi, kırksekiz

kırkdokuz, elli

Saçlarının ışığını aradım yoktu

Işık yoktu..

Bağırdım hep çıkarsın diye

Elli, elli, elli...

İLk defa ebe oldum gerçekten

Hep seni aradım

Bulamadım gözlerimizin 

Mavisinde yeşilinde

Kızardı çaresiz gözlerim

Kırmızı ve karada aradım...

Döndüm gene şahidimiz ağaca

başımı dayadım saydım

Bozuldu oyun, bozuldu sihir

tek başıma saydım ve ağladım...

DK 1986', 'Kırkyedi, kırksekiz kırkdokuz, elli Sağım solum, önüm arkam saklanan ebe... Saçlarının ışığından  tanırdım seni. Bana bakardın gözlerin kapa...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/saklambac-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deli Saçması', 'deli-sacmasi-hayrettin-turk-vzs3t', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir puslu duman

Azrail''in nefesinden

Birşeyler çalmış...

Aman Allah''ım aman

Korkunun sessiz feryadı

Gözlerimde Kalmış...

Pembe bulutlar

Mavi gökyüzü, yeşil deniz

Renkler dans ediyor

Ben dans bilmem

Makberi bilirim yalnız

O da bir varmış, bir yokmuş...

Hayaletlerin yürüdüğü yollarda

Bir gölgeyi takip eder

Belirsiz ayak izlerim

Konuşamaz dillerim

Gözlerim deli deli

Deli saçması sözlerim...

DK 1985', 'Bir puslu duman Azrail''in nefesinden Birşeyler çalmış... Aman Allah''ım aman Korkunun sessiz feryadı Gözlerimde Kalmış... Pembe bulutlar Mavi...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/deli-sacmasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Gün', 'o-gun-hayrettin-turk-ft9zl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gelecek elbeto gün

Günlerden bir gün, bilemediğim

Ezelle ebed arası bir nokta

Takviimde işaretli, göremediğim...

O, kara kaderin celladı gelecek

Kara kader, kara adam bitecek

O gün bütün sevgiler olacak gerçek

Gerçekler.. görüpte bilemediğim...

DK 1984', 'Gelecek elbeto gün Günlerden bir gün, bilemediğim Ezelle ebed arası bir nokta Takviimde işaretli, göremediğim... O, kara kaderin celladı gel...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/o-gun-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdanın Günü', 'sevdanin-gunu-hayrettin-turk-p2alc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu gün

Sevdanın günüBu yol

Sevdanın sürgünü

Kavuşmak ise

Kefenin düğünü...

Bu gün

Merhaba merhaba

Hal, hatır

Ve akraba...

İki sevda

Kafeste iki kuş

Kurtulurmu acaba...

Bu gün 

sigaranın dumanında

Hayal edip durduğun 

işte yanında...

İki kelimeyi 

Bir kez söyle hayatında...

Bu gün Affına sığın Yaradanın

O ki herşeyi bilir

Başlatanıdır sevdanın

Kavuşmak istiyorsan, kolay

Yeterki arkası

Kesilmesin duanın...

DK Ekim 1983', 'Bu gün Sevdanın günüBu yol Sevdanın sürgünü Kavuşmak ise Kefenin düğünü... Bu gün Merhaba merhaba Hal, hatır Ve akraba... İki sevda Kafeste ...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sevdanin-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sır', 'sir-hayrettin-turk-gs55f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İki göz ve bir nokta

Bakmanın, görmenin sırrı

Bir gözden çıkan bin okta

Yakmanın, sevmenin sırrı...

Kültablam dertli, izmaritim çok

Kadehlerim dertli meyim yok

Kırk gündür orucum, karnım tok

Açlıkta gizli tokluğun sırrı...

Aramayın ne para ne varlık

Madde; göz boyayan canavarlık

Sonunda bir baston ve ihtiyarlık

Gençlikte saklı ihtiyarlığın sırrı...

Elbisem kirli ama temiz

Ayakkabılarım taşır kırk kişiden kırk iz

Varlığım hiç yok, yokluğum deniz

Yoklukta saklı varlığın sırrı...

Bir seccadem var bana sadık

Birde Yunusça kalbim, gerçek aşık

Su olsunda ha bir deniz, ha bir kaşık

Gönülde saklı tadmanın sırrı...

DK 1983', 'İki göz ve bir nokta Bakmanın, görmenin sırrı Bir gözden çıkan bin okta Yakmanın, sevmenin sırrı... Kültablam dertli, izmaritim çok Kadehler...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sir-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resim', 'resim-hayrettin-turk-gnu34', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kirli bir cam

Boyası gitmiş bir çerçeve

Dudaklarda acı bir tebessüm

Ve eskimi eski bir resim...

Kimi ölmüş kimi hayatta

Kimisi en arkada kimisi en başta

Birisi var mekanı mescit, kalbinde Allah

Birisi var pismi pis hala oynaşta...

Biriisi, birisi daha vardı

Aşkla doyar aşkla yaşardı

Ölüp gitti dediler bir gün

Duydum, duydumda dünyam karardı...

Sonra nasıl öldüğünü anlattılar

Oruçlu halinde alıp gitmiş sular

Şehit, şehit olmuş o

Çünkü mezarına gelmiş beyaz beyaz kuşlar...

Ya işte böyle

Mazide kalmış keder ve neşeyle

Eski bir resim eski günleri getirdi

Kimisine hasret, kimisine öfkeyle..

Her köşede bir resim

Her resimde bire isim

Aylar, yıllar ve ağaran saçlar

Bakar bakarda ağlamak isterim...

DK 1983', 'Kirli bir cam Boyası gitmiş bir çerçeve Dudaklarda acı bir tebessüm Ve eskimi eski bir resim... Kimi ölmüş kimi hayatta Kimisi en arkada kim...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/resim-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırakın Beni', 'birakin-beni-hayrettin-turk-0q11g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnler cinler hepsi tepemde

Gebersin Mecnun, Aslı Kerem''de

Ne isterseniz isteyin veremde

Bırakın, bırakın ne olur beni...

DK 1983', 'İnler cinler hepsi tepemde Gebersin Mecnun, Aslı Kerem''de Ne isterseniz isteyin veremde Bırakın, bırakın ne olur beni... DK 1983...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/birakin-beni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Damla Kan', 'bir-damla-kan-hayrettin-turk-xit0c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tetik oynadı, boş kaldı kovan

Mermi uçtu, uçtu yandı can

Ümit hedefte kendini öldürdü

Ve, sonunda bir damla kan...

Izdırap işledi ta içine

Şaşar oldu tutmayan dizine

Birden bir hayal geldi gözüne

Sızdı yanağına bir damla kan...

Susadı, içmek istedi deryaları

Haykırdı, yıkmak istedi dünyaları

Çaresizce kaldı, duyulmadı feryatları

Düştü dudağına bir damla kan...

Artık bitmiş, ölmüştü sevdası

Zaten yalnızdı oldu olası

Dünyada bu kadarcıkmış molası

Ondan kalan... bir damla kan...

DK Kasım 1983', 'Tetik oynadı, boş kaldı kovan Mermi uçtu, uçtu yandı can Ümit hedefte kendini öldürdü Ve, sonunda bir damla kan... Izdırap işledi ta içine Ş...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-damla-kan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yansın', 'yansin-hayrettin-turk-cb9ma', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kimsenin olmadığı yollarda

Bir ben

bir yalnızlık

birde hayalin...

Karanlığın ağladığı sokaklarda

Lambalar sönmüş

Umutlar ölmüş

ufuklar ise hala

kapkara

Ve ben gülüm

Yakmışım kibriti

Ufuklarım belki aydınlanır diye

Deli kafa

Tutuşturmuşum kendimi...

Karanlık dünyamın ışığı

Gene ben olacaksam gülüm

Umut diye kendimi yakacaksam

Ve aydınlıkta da sen yoksan...

Bırak gülüm, bırak kalsın

Karanlık içinde hiç olmazsa hayalin

Hiç olmazsa umutlarım, ızdırabım var..

Bırak gülüm, bırak kalsın

Elimde kibrit

Kibritte sevdam

Yansın gülüm, yansın...

DK Kasım 1983', 'Kimsenin olmadığı yollarda Bir ben bir yalnızlık birde hayalin... Karanlığın ağladığı sokaklarda Lambalar sönmüş Umutlar ölmüş ufuklar ise h...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yansin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşım', 'yasim-hayrettin-turk-n80l1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biri yaşımı sordu bana

Söyledim sinirlendi? ..

Neymiş efendim, 

      Alay edemezmişim...

Alay eden kim

      Benim yaşım

Bir yıl önce ondokuzdu

        Şimdi bir milyon! ..

Olamazmı? 

Doğrusu bende inanmazdım

         Bu kadar yaşlanacağıma

Tilkiyi görünce karşımda 

         Kuzuyken kurtlaşacağıma...

Kader beni buldu

           Ağını kurdu

Cellatın elinde kırk satır

           Kelleme vurdu...

Sırat köprüsünü gördüm

          Bir saç telinde

Azrail herkesi doğruyor

          Bin kılıç elinde...

Acıyan olmadı bana

          Daha ondokuz yaşımda

Şimdi çok mutluyum 

          tam birmilyon yaşımda...

Enseme inmişti bir zaman

          Kıldan ince kırk satır

Her birinde binlerce yıl yaşlandım

          harf harf, satır satır...

Şimdi tek derdim

            Bu kadar yapınca hız

Acaba nasıl bulunur

             Birmilyon yaşında kız....

DK

Kasım 1983', 'Biri yaşımı sordu bana Söyledim sinirlendi? .. Neymiş efendim,        Alay edemezmişim... Alay eden kim       Benim yaşım Bir yıl önce ondok...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/yasim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zilan', 'zilan-yasar-aslan-std1z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bir papatya gülümseyişinde beliri verdin

Kokun  bahar, kokun sevda 

toprak kokusu

biraz çiğ, 

az yaban 

nasır tutmuş ellerin, 

bakışın az korkak,

utangaç

gülümseyişinde mahsumiyetin adı  beliriveriyor

hırçın ama kendi içinde 

suskun  ama kendi yüreğinde

hayallerinde sınır

sanki zaruri

gözüm...

toprak kokulum 

sen şehir yosması da  olamadın değil mi  zilan? 

yüzüme bak 

olmayı ver ne olur.

sen çiğ kal 

birazda yaban

ama temiz

haykırmayı ver, sen suskun kal

gözlerin konuşur sen anlat ben dinlerim zilan

sen şehir yosması da olamadın değil mi zilan? 

kaldır başını gözüm yüzüme bak 

olmayı ver ne olur.! ! ! 

sen çiğ kal

birazda yaban

gözlerin konuşur sen anlat ben dinlerim zilan

ne diyeyim başka 

bir şehir yosması da olamadın

biraz çiğ 

birazda yaban

değişme sakın, sana  utanmak yakışıyor! 

sen konuş ben dinlerim zilan.', 'bir papatya gülümseyişinde beliri verdin Kokun  bahar, kokun sevda  toprak kokusu biraz çiğ,  az yaban  nasır tutmuş ellerin,  bakışın az ko...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Aslan']::text[], 8.5, '{"poet":"Yaşar Aslan","poet_slug":"yasar-aslan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/zilan-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir işvebaza gazel', 'bir-isvebaza-gazel-ali-umran-sonmez-4onhs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni düşündüm de dün yine 

Geldi gözlerimin önüne en güzel hayalin.

O işveli bakışların sevecen halin

Cıvıl cıvıldın ruhlara neşe saçan

Bir çiçektin sen gönüllerde açan.

Kaçamak bakışlarla baygın bakardın, 

Seni sevenleri hepten yakardın.

Vefasızdın biraz ne olur darılma.

Seviyorum onu derdin, bakardık terketmişsin.

Bir saman alevi gibiydi sevgin.

Mutlu görünürdün seviyorum derdin, 

Bilirdik onunda geçici olduğunu.

Uslanırsın elbet bulursan aradığın mutluluğu.

Görmek ister gönlüm seni her dem bahtiyar.

Kırdıysa sözlerim affet sevimli yar.

                                         1984', 'Seni düşündüm de dün yine  Geldi gözlerimin önüne en güzel hayalin. O işveli bakışların sevecen halin Cıvıl cıvıldın ruhlara neşe saçan Bir ...', ARRAY['Türk Edebiyatı','Şiir','Ali Ümran Sönmez']::text[], 8.5, '{"poet":"Ali Ümran Sönmez","poet_slug":"ali-umran-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bir-isvebaza-gazel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birahane gülleri', 'birahane-gulleri-ali-umran-sonmez-fshpa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dizilirler kapı önlerine

Çapkınca bakarlar geçenlere, 

Birahane gülleri...

Bakışları davetkar, kıyafetleri açık saçık, 

Ağızlarında cigara...

Müşterileri kabasaba külhanbeyleri.

Yanaşır çapkınca masaya

Birahane gülleri...

İçerler meyvesuyunu bayan içkisi diyerek.

İki içmişsen üç yazarlar, 

Geçirirler hesabı kikirdiyerek.

Hepsinin kendince vardır bir öyküsü...

Kimi anlatır hain kocasını, 

Kimide zalim babasını.

Anlattıklarının çoğu yalanla karışık, 

Uyutur masalları ile 

Birahane gülleri...

Onlarda sever, gönülden yanar, 

Adama bakınca gözünden anlar, 

Güçlü olana vallahi tapar, 

Bir alem kadınlardır 

Birahane gülleri...', 'Dizilirler kapı önlerine Çapkınca bakarlar geçenlere,  Birahane gülleri... Bakışları davetkar, kıyafetleri açık saçık,  Ağızlarında cigara.....', ARRAY['Türk Edebiyatı','Şiir','Ali Ümran Sönmez']::text[], 8.5, '{"poet":"Ali Ümran Sönmez","poet_slug":"ali-umran-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/birahane-gulleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye özlem', 'sevgiliye-ozlem-ali-umran-sonmez-u30u6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Özlemin sarmış tüm benliğimi

Hayalin gitmiyor gözlerimden.

O sımsıcak ellerin nerde? 

Arıyorum sevgilim seni kadehlerde.

Gönlümü nasılda yakmışsın kafir! 

Düşünemiyorum senden başkasını.

Yapılırmı aşkolsun böyle, 

Benim gibi yaşı kırkı aşmışa.

Sen hep taze bahardın benim için, 

Neredeyse benim yarı yaşımda.

Sürekli aşkım dedin bana.

Aldırmazdın etrafındakilere.

Bekliyorum buluşacağımız günü.

İçim hala kıpır kıpır aşkınla.

Gençlik veriyor bu aşk bana, 

Bulmasamda vefa senin aşkında.', 'Özlemin sarmış tüm benliğimi Hayalin gitmiyor gözlerimden. O sımsıcak ellerin nerde?  Arıyorum sevgilim seni kadehlerde. Gönlümü nasılda yak...', ARRAY['Türk Edebiyatı','Şiir','Ali Ümran Sönmez']::text[], 8.5, '{"poet":"Ali Ümran Sönmez","poet_slug":"ali-umran-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgiliye-ozlem-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonbahar', 'sonbahar-ozcan-ozgun-lmw0z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen ki

Her dilde isyan

Her isyanda özgürlüksün

Yanık ormanların

Yanık türküsüsün

Eylül sürgün zamanıdır

Sarhoş ve yalnız kentlere

Bu kent Eylül''dür

Oturumların en çok konuşupta

En az şey söyleyen konuğudur

Ama sana dair ne varsa

Bu kentte topladım

Gözlerinde taklacı güvercinler dolaşan

Saçları kürt inadı kadın', 'Sen ki Her dilde isyan Her isyanda özgürlüksün Yanık ormanların Yanık türküsüsün Eylül sürgün zamanıdır Sarhoş ve yalnız kentlere Bu kent Ey...', ARRAY['Türk Edebiyatı','Şiir','Özcan Özgün']::text[], 8.5, '{"poet":"Özcan Özgün","poet_slug":"ozcan-ozgun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sonbahar-38-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyutalım Bu Kenti', 'uyutalim-bu-kenti-ozcan-ozgun-0czef', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu kenti uyutalım

Baka baka saatlere

Taş sekelim caddelerinde

Güller takalım yakalarına meydanlarının

Simitçiler kalk borusunda

Fırınlar ekmek buğusunda

İşçiler vardiyadadır

Ver elini

Karanfil kokulu 

Bildirileri kuşluyalım sokaklara

Şarapların kırmızısını çalalım

Başakların kokularını

Anne kucaklarını

Bir de düdüklerini bekçilerin

Gecenin en mahrem yerinde 

Pusudayken zaman sevişmelere

Şiirler okuyalım

Nazim renkli şiirler', 'Bu kenti uyutalım Baka baka saatlere Taş sekelim caddelerinde Güller takalım yakalarına meydanlarının Simitçiler kalk borusunda Fırınlar ekm...', ARRAY['Türk Edebiyatı','Şiir','Özcan Özgün']::text[], 8.5, '{"poet":"Özcan Özgün","poet_slug":"ozcan-ozgun","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/uyutalim-bu-kenti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağrıma, ey ayrılık dikeni! her zaman saplanma', 'bagrima-ey-ayrilik-dikeni-her-zaman-saplanma-ali-sir-nevai-6mnxl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bağrıma, ey ayrılık dikeni! her zaman saplanma

Ey gönül! Yüz eziyet gelse; göze başkasını alma.

Bin bela yüzlense ey can! Yardan ayrılma.

Olsa yüz bin canım al ey hicran! Lakin kılma, 

Yarımı benden cüda, yahut beni ondan cüda.', 'Bağrıma, ey ayrılık dikeni! her zaman saplanma Ey gönül! Yüz eziyet gelse; göze başkasını alma. Bin bela yüzlense ey can! Yardan ayrılma. Ol...', ARRAY['Türk Edebiyatı','Şiir','Ali Şir Nevai']::text[], 8.5, '{"poet":"Ali Şir Nevai","poet_slug":"ali-sir-nevai","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bagrima-ey-ayrilik-dikeni-her-zaman-saplanma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağlara Deniz Ektim', 'daglara-deniz-ektim-abdurrahim-karakoc-qczww', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uykuları yatağıma bağladım

Geceleri delip çıktım dağlara..

Ormanların kâkülünü taradım

Bulutlardan gömlek diktim dağlara..

Ağaran şafakta gördüm yarını

Tuttum nakış nakış ördüm yarını

Yağmur damlasına sardım yarını

Dalga dalga deniz ektim dağlara..

Kartal kanadıyla biçtim gökleri

Duru pınarlardan içtim gökleri

Ya Allah! . diyerek açtım gökleri

Demet demet ışık döktüm dağlara..

Hayal var ki hakikatten evlâdır

Çile var ki çok nimetten evlâdır

Sabır, şükür her ziynetten evlâdır

Üçüncü gözümle baktım dağlara..

Akıl Karaya Vurdu', 'Uykuları yatağıma bağladım Geceleri delip çıktım dağlara.. Ormanların kâkülünü taradım Bulutlardan gömlek diktim dağlara.. Ağaran şafakta gö...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/daglara-deniz-ektim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ben ve O', 'sen-ben-ve-o-ahmet-selcuk-i-lkan-rb3lh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyorum

Sen yine bu akşam o bomboş odanda

Onu düşüneceksin

Onu arayacak titrek ellerin

Onu düşleyecek gözlerin

Deli yağmurlar gibi düşecek özlemin avuçlarına

Gelmeyeceğini bile bile

Biliyorum

Sen yine bu akşam o bomboş odanda

Onu bekleyeceksin

Dudaklarında unutamadığın o isim

Yanıbaşında yırtamadığın o resim

Ve en paslı bıçaklar gibi umutlar yüreğinde

Dönmeyeceğini bile bile

Biliyorum

Sen yine bu akşam o bomboş odanda

Onu arayacaksın

Hasreti mum gibi eritecek seni

Çarpacak yüreğinde dev boyu bir yalnızlık

Ve bir batmış geminin kaptanı gibi bakışların ufukta

Görmeyeceğini bile bile

Biliyorum

Sen yine bu akşam o bomboş odanda

Onu anacaksın

Dilinde hüzünlü bir şarkının son satırı

Bir gün gibi yaşayıp bütün yılları

Özlem nöbetine tutulup ağlayacaksın

Çaresizliğini bile bile

Oysa ben

Yine bu akşam bekar odamda

Seni düşüneceğim

Seninle dolduracağım yalnızlığımı

Sigara dumanlarında gözlerin yakacak gözlerimi

Kırık kadehler gibi dökülüp kalacağım pencerelerden

O zehir şarkılara inat

Yine seni bekleyeceğim

Onu sevdiğini bile bile', 'Biliyorum Sen yine bu akşam o bomboş odanda Onu düşüneceksin Onu arayacak titrek ellerin Onu düşleyecek gözlerin Deli yağmurlar gibi düşecek...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/sen-ben-ve-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '_ Sana Yöneldim', 'sana-yoneldim-cengiz-numanoglu-607f3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kuluna göz verdin, ''''gör Beni'''' dedin,

Dil verdin, ''''bilene sor Beni'''' dedin,

Gönül verdin, ''''hayra yor Beni'''' dedin,

Gördüm, sordum, yordum, Sana yöneldim.

Nice dervişlerle, uzun söyleştim,

Kör kör bakan, kullarınla eyleştim,

İyi, kötü, ne verdiysen paylaştım,

Aldığım hisseyle, Sana yöneldim.

Bolca bolca verdin, gönül aşımı,

Müjdelere yordun, şu göz yaşımı,

Hiç kimseye, eğmediğim başımı,

Yalnız Sana eğdim, Sana yöneldim.

Beşer, kazanında, piştim pişeli,

Kimi üzgün gördüm, kimi neş''eli,

Kimi döner durur, aşka düşeli,

Pervaneler gibi, Sana yöneldim.

Kimi uykulara, derince dalmış,

Kimisi kararsız, ortada kalmış,

Kimi, Seni arar, kimi de bulmuş,

Bulanlardan oldum, Sana yöneldim.

Kimi der ki; ''''varsa görünsün, bize''''.

Kimi, görmüş, gelmiş önünde dize.

Nasıl göstermeli, görmeyen göze? 

Görenlerden oldum, Sana yöneldim.

Bir ana serçenin, içgüdüsünde,

Tavus kuşlarının ince süsünde,

Nice örümceğin, ak örtüsünde,

Hep, Seni gördüm de, Sana yöneldim.

Bir lokma, bir hırka hâllere düştüm,

Herkesi dost bildim, dillere düştüm,

İncecik, dikenli yollara düştüm,

Kan revan içinde, Sana yöneldim.

Bir kitap gönderdin, cümle âleme,

Tek hecesi bile gelmez kaleme,

Dedin ''''Benden başka bir şey dileme''''

Satır satır çözüp, Sana yöneldim.

Toprak verdin, tohum verdin ekmeye,

Çile verdin, dergâhında çekmeye,

O zengin sofranda, kuru ekmeğe,

Razı ola ola, Sana yöneldim.

Hak verdin, bâtılı yanında kıldın,

Şeytanı, insanın kanında kıldın,

Akıl verip, nefsin, önünde kıldın,

Nefsime hükmedip, Sana yöneldim.

Âlimin ilmini, zâlim bilir mi? 

Yol sokak bilmeyen, Seni bulur mu? 

Bilenle bilmeyen, eşit olur mu? 

Bilenlerden oldum, Sana yöneldim.

Kâbe''de şahlanan, elleri gördüm,

Yalvarıp yakaran, dilleri gördüm,

Önünde durulmaz, selleri gördüm,

Kapıldım sellere, Sana yöneldim.

Gördüm; dolup taşan mâbetlerini,

Dinledim; çınlayan âyetlerini,

Hele, o kulların niyetlerini,

Duydum, duya duya, Sana yöneldim.

Duydum; kul hakkını, yiyenler varmış,

''''Mahşer günü yoktur'''', diyenler varmış,

Kürkten kefen dikip, giyenler varmış,

Buna şaşıp kaldım, Sana yöneldim.

Yürüdüm, sağı da solu da gördüm,

Kavşakta yıllarca, düşünüp durdum,

Verdiğin vicdana, elimi vurdum,

''''Başka yol yok'''' dedi, Sana yöneldim.

Câmi kubbeleri, güyâ büyüktü,

Kubbeni görünce, bir korku çöktü,

Bu nasıl mîmâri, bu nasıl yüktü? 

Aczimi bildim de, Sana yöneldim.

Bir köprü kurmuşsun, derler incedir,

Sordum, düşenlerin hâli nicedir? 

Dediler; bağışlar, O çok yücedir,

Nice ümitlerle, Sana yöneldim.

Kulda kusur gördüm, kuldan sakladım,

Nice lekeleri, silip pakladım,

Sır verdiler, sır üstüne ekledim,

Doldum, dola dola, Sana yöneldim.

Akrabaya koştum, dedim; ''''yaram var'''',

''''Biraz derincedir, incitmeden sar''''

Ne yeminler etti, dedi; ''''elim dar''''

Asıl, bu yarayla, Sana yöneldim.

Kul gördüm, kuluna hased çekmede,

Kin tohumun, nesil nesil ekmede,

Bir yudum su verse, başa kakmada,

''''Muhtaç etme'''' dedim, Sana yöneldim.

Kulunu denedin, çöle düşürdüm,

''''Bir damla su'''' dedim, göle düşürdün,

''''Ya hidâyet'''' dedim, sele düşürdün,

Boğuldum, boğuldum, Sana yöneldim.

Kimdir, dedim, hücrelere can veren? 

Bunca görünmezi, bakmadan gören? 

Kilitli, kilitsiz her yere giren? 

Hep, Seni dediler, Sana yöneldim.

Kimdir, dedim, kalp gözüme nûr veren? 

Bana, bunca güzellikler gösteren? 

Bütün, şek ve şüpheleri susturan? 

Hep, Seni dediler, Sana yöneldim.

Kimdir dedim, o şeytanı nâr eden? 

''''Ol '''' deyip de, âlemleri vâr eden? 

Melekleri kullarına yâr eden? 

Hep, Seni dediler, Sana yöneldim.

Hikmetinden ''''sorgu sual'''' olunmaz,

Bir sel var ki içimde, karşı durulmaz,

Yazdıkça yazar da, elim yorulmaz,

İçim döküp döküp, Sana yöneldim.

Günah denizine, boyumca daldım,

Çırpına çırpına kumsala geldim,

Gör ki; bir kum tanesi de, ben oldum,

Yerimi buldum da, Sana yöneldim.

Bin kez tövbelerden, şaşırıp döndüm,

Bin kere nûrlandım, bin kere söndüm,

Gel gör ki; bu defa, bir başka yandım,

Küllere döndüm de, Sana yöneldim.

Bir zaman, şeytana eşlik ederdim,

''''Herşey bu dünyada, öte yok'''' derdim,

Bir kara boşlukta, koşup giderdim,

Gör ki; döndüm Yârab, Sana yöneldim.

Kendi gafletimden, düştüm kedere,

Yıllarca suçladım, küstüm kadere,

Ne fayda ki, geçen geçti bir kere,

Zararlardan dönüp, Sana yöneldim.

Dünya nimetleri, başım döndürdü,

Gönül gözlerime, perde indirdi,

Yüreğimde, ne fenerler söndürdü,

Birer birer yakıp, Sana yöneldim.

Haram pazarında, tacirlik ettim,

Sermayeden oldum, kârı tükettim,

İtibârım vardı Sende, yok ettim,

Binbir ''''eyvah! '''' ile, Sana yöneldim.

Şarap; nice derde, sandım ki değer,

Bunca içer miydim, bilseydim eğer,

Beni sarhoş eden, adınmış meğer,

Kırdım kadehleri, Sana yöneldim.

Bilmedim, verdiğin, can kıymetini,

Yüklendim dünyanın, bin zahmetini,

Gerçi yüzüm yok ya; o rahmetini,

Yine de ver, diye, Sana yöneldim.

Nankör oldum, buldum Sana bahane,

Kibirlendim, oldum deli divane,

En sonunda, harmanında bir tane,

Savrula savrula, Sana yöneldim.

Dediler; ''''Hani, sen böyle değildin,

Gaflet lekelerin, neyledin sildin? 

Adresi kim verdi, yolu ne bildin? ''''

Anlata anlata, Sana yöneldim.

''''Yıllarca durmadan, meyhane sordun,

Kumarhanelere tezgahı kurdun,

Dört nala koşarken, nasıl da durdun? ''''

Dedim; ''''durduran var'''', Sana yöneldim.

Yön bilmez kullara, yollar neylesin,

Bağlanmış kollara eller neylesin,

Mızrap, sarhoş vurur, teller neylesin,

Tel tel inledim de, Sana yöneldim.

Gönül pınarları, gördüm ki kurur,

Kapılar kapanmış kilitli durur,

Açan yok, ellerim boşuna vurur,

Anahtar sormaya, Sana yöneldim.

Katı yürek gördüm, kurşunlar delmez,

Yüz adım giderim, bir adım gelmez,

Dediler; ''''nankördür, teşekkür bilmez,''''

Dedim; bilen bilir, Sana yöneldim.

Zavallı bir zümre, gördüm ki hele,

Müşrikle, münâfık, vermiş elele,

Hasetten çatlatır, şeytanı bile,

Hâlime şükredip, Sana yöneldim.

Gördüm, daha nice, yoldan sapanlar,

Dünya malın, putlaştırıp tapanlar,

Haram harmanında, hasat yapanlar,

Binlerce ''''vah! '''' ile Sana yöneldim.

Ölümsüz kim? dedim, aradım durdum,

Bilgelere vardım, kapılar vurdum,

Nice âlimlere, danışıp sordum,

Hep, Seni dediler, Sana yöneldim.

Ölümsüz kim? dedim; güneş ve aya,

Dört milyar yaşında, fâni dünyaya,

Ölümsüz kim? dedim; ateş ve suya,

Hep, Seni dediler, Sana yöneldim.

Nice âhu gözler, samur saçlara,

Zümrüt saraylara, yakut taçlara,

Krallara, kılıçlara, meçlere

Hep, Seni dediler, Sana yöneldim.

Kimseye benzemez, doğmaz ölmezsin,

Ağlayıp sızlamaz, coşup gülmezsin,

Kulumsun dediğin, dostu silmezsin,

Vefâna yâr olup, Sana yöneldim.

Sabahın geceyi, kovduğu yerde,

İlmin cehâleti, boğduğu yerde,

Îmânın kalbime, doğduğu yerde,

Hep, Seni gördüm de, Sana yöneldim.

Ağaçlar, çiçekler, çimler, fidanlar,

Akrepler, böcekler, kuşlar, yılanlar,

Bütün emirleri, Senden alanlar,

Gördüm, göre göre, Sana yöneldim.

Fakir, fukaranın, dik başlarını,

Seyrettim, onurlu savaşlarını,

Bir yetim yavrunun, göz yaşlarını,

Mendil mendil sildim, Sana yöneldim.

Sahipsiz, kimsesiz, felçli düşkünler,

Yaşları yetmişi, çoktan aşkınlar,

Bir el bekliyorlar, öyle şaşkınlar,

El verdim, verdikçe, Sana yöneldim.

Bir gâzi yanında, durasım geldi,

Hâli vakti nedir, sorasım geldi,

Biraz vefâ bulup, veresim geldi,

Yüreğim sızlayıp, Sana yöneldim.

Veren el alandan, üstün buyurdun,

Bunu bütün kullarına duyurdun,

Sonra da, onların seyrine durdun,

Verdim, vere vere, Sana yöneldim.

Komşu kapısını, usulca vurdum,

Aç mıdır, tok mudur, gizlice sordum,

İki lokmam vardı, birini verdim,

Rızânı almaya, Sana yöneldim.

Binbir çeşit, mahlukâtı türettin,

Kimine göz verdin, kimin kör ettin,

Bunca denge hesabını sır ettin,

Çözmek için Yârab, Sana yöneldim.

Ölüm, bir karanlık geceyse eğer,

Bunca korkulara, dedim ki; değer.

Oysa; uyanmakmış, sabahmış meğer,

Seherin gördüm de, Sana yöneldim.

Anam, atam, çoktan Sana varmışlar,

Huzurunda, huzur ile durmuşlar,

Fâtihâ gönderen evlât sormuşlar,

''''Vâsıl eyle'''' diye, Sana yöneldim.

Bilirim ki; adâletin yücedir,

Kılıçlardan keskin, kıldan incedir,

Ya, hukuk dağıtan, kullar nicedir? 

Sen bilirsin Yârab, Sana yöneldim.

Hak yolunda, zincirlere vuruldum,

Ne fırtınalardan, durdum duruldum,

Seni, serap serap, sordum yoruldum,

Şimdi, pınar pınar, Sana yöneldim.

Zengin, fakir demez, bakmazsın yaşa,

Sevdiğin kulunu, çalarsın taşa,

Senden ne gelirse, razıyım başa,

Affına sığındım, Sana yöneldim.

Dedim; vâdettiğin, o Cennet nerde? 

Dedin; ''''kâlp gözüyle baktığın yerde.''''

''''Belki, bir fakirde, belki hakirde''''

Kalbim göz eyleyip, Sana yöneldim.

Oruç mükâfatı, yalnız Sendeymiş,

Açlığın böylesi, ne güzel şeymiş,

Sabrın lezzetine, vardım ki; neymiş! .

Onu, tada tada, Sana yöneldim.

Kul gördüm; yoksundur, elden ayaktan,

Dedim; yürüyemez, kalkıp yataktan,

Meğerse, o Sana, yürümüş çoktan,

Koştum, nefes nefes, Sana yöneldim.

Gördüm, kadın hakkı, bilmez er kişi,

Zulmeder, aklınca, çünkü o dişi,

En kutsal emânet, verdin ki; eşi,

Başıma tâc edip, Sana yöneldim.

Kötürüm anaya, dertler yükledin,

Oğlunda kızında, sabır yokladın,

Ayağı altına, Cennet sakladın,

Öptüm o Cenneti, Sana yöneldim.

Çektim gözlerimden, gaflet tülünü,

Neyleyim, mevsimlik dünya gülünü? 

Yeter ki; kulunun ahret çölünü,

Gül gülistan eyle, Sana yöneldim.

İster isen, bağışlarsın kulunu,

Ateşlerden döndürürsün yolunu,

Atlastan biçersin, kabir çulunu,

Bağışla ki Yârab, Sana yöneldim.

Gördüm ki; kullara hudut çizilmiş,

Gurur, kibir, kullar için değilmiş,

En gururlu başlar bile eğilmiş,

''''Yerle yeksan'''' olup, Sana yöneldim.

Mahşerde çözülür, diller konuşur,

Diller inkâr etse, eller konuşur,

Göz, kulak, parmaklar, kollar konuşur,

Ben, nice ikrarla, Sana yöneldim.

Duydum ki; düşünce bir ibâdetmiş,

Gönül tahtın; düşünenler fethetmiş,

Bilmem; bu lezzeti, kaç kulun tadmış,

Tadanlardan oldum, Sana yöneldim.

Bir damladan yaptın, insan denizi,

Ne huyları benzer, ne parmak izi,

Daha neler gördü, şu gönül gözü,

Kudretine hayran, Sana yöneldim.

Vermekle bitse de, dünya nimeti,

Verdikçe artıyor, gönül serveti,

Bu nasıl ticaret, nedir hikmeti? 

Bunca servet ile, Sana yöneldim.

Cennetten haber mi, güller lâleler? 

O namus beyazı, gür şelâleler? 

Hani, dağılır ya; suda hâleler,

Büyüdüm, büyüdüm, Sana yöneldim.

Milyarlarca galaksiler, yıldızlar,

Akıllar durduran, ulu sonsuzlar,

Kimbilir ötede, daha neler var,

Bir sorup, bin kere, Sana yöneldim.

Rızkına, bilerek, haram katmadım,

Para pul verdiler, inanç satmadım,

Kul elini, minnet ile tutmadım,

Minnet, diye diye, Sana yöneldim.

Nefsimle savaştım, yendim, yenildim,

Dostum oldu, iyi günde anıldım,

Dünya makâmına, kandım yanıldım,

Makâm istemeye, Sana yöneldim.

Yıllar geçer, ömür geçer âheste,

İstemem, gözüm yok, altın kafeste,

Bana, bir servet ver, o son nefeste; 

Îmân, diye diye, Sana yöneldim.

Serveti verirsin, her isteyene,

İlmi, ancak, onu servet bilene,

Ne mutlu ki; o serveti bulana,

Gör ki; bulmak için, Sana yöneldim.

Dedin: ''''Bir düşkünü, kim ki, dost seçer,

O ince köprüden, kolayca geçer,

Merhamet ekenler, merhamet biçer,

Ektim de, biçmeye, Sana yöneldim.

Rızân için, karşılıksız verenler,

Rızân için, gönüllere girenler,

Müjdelenmiş, kâlp gözünden görenler,

Müjdemi almaya, Sana yöneldim.

''Tasavvuf'' dedim de, düşündüm derin,

Aşk ile kalbimi kapladı yerin,

Şaşırıp kaldığım, bunca eserin,

Ustasını görüp, Sana yöneldim.

Kim, ne yapar, Senden, bedelin alır,

Ne tehir edilir, ne hakkı kalır,

Herkesin serveti, peşinden gelir,

Ben, fakir hâlimle, Sana yöneldim.

Her kula katında, bir yer vermişsin,

''''Onu ancak, ben bilirim'''' dermişsin,

Hüküm verenlere, kahredermişsin,

Haddimi bildim de, Sana yöneldim.

Nefesleri sayıp, verirsin bize,

Gün be gün, tükenir, görünmez göze,

Şehâdet denilen, o güzel söze,

Nefes ihsân eyle, Sana yöneldim.

Bunu anlatması, zor gelir dile,

Nedir ki, dünyada çekilen çile,

Kabir azâbını, düşünmek bile,

Kuluna yetti de, Sana yöneldim.

Ne yaralar gördüm, ilâç kâr etmez,

Ne hastalar gördüm, gecesi bitmez,

Yine de; sabreder, isyana gitmez,

Hayran, hayran bakıp, Sana yöneldim.

Kin ve intikamda, uyardın bizi,

Dedin; ''''Yumuşatın kâlplerinizi,

Sonra; boğar sizi, öfke denizi.''''

Kıyılardan döndüm, Sana yöneldim.

Topladın, beş vakit, mâbette bizi,

Olduk, dalga dalga, insan denizi,

Çözüldü göklerde, ruhların gizi,

Onların izinden, Sana yöneldim.

Bu dünya; üç günlük bir saltanatmış,

Hani, var mı onu, bir gün uzatmış? 

Ölüm; bazen azat, bazen azapmış,

Azat, diye diye, Sana yöneldim.

Geceler sultanı, Kadir Gecesi,

Yedi kat göklerde, kulların sesi,

Duydum ki; yerini, bulmuş nicesi,

Bir yer ver demeye, Sana yöneldim.

''''O gece'''' hacetler, bol tutulurmuş; 

''''O gece'''' arayan, Dost''u bulurmuş,

Gönüller, Muhammed tahtı olurmuş,

Gönlümü taht edip, Sana yöneldim.

''''O gece'''' nefesler, yel yel olurmuş,

Bulutlar nûr döker, sel sel olurmuş,

Bedenler semâda, el el olurmuş,

Yel yel, sel sel, el el, Sana yöneldim.

''''O gece'''' melekler, saf saf inermiş,

''''O gece'''' acılar, dertler dinermiş,

''''O gece'''' cehennem bile sönermiş,

Ben aşk ateşiyle, Sana yöneldim.

Sahip kimdir? dedim, yüce dağlara,

Engin denizlere, sonsuz çağlara,

Göçüp gidenlere, kalan sağlara,

Hep, Seni dediler, Sana yöneldim.

Sahip kimdir? dedim, kurda kuşlara,

Ağaçlara, topraklara, taşlara,

Nice sultanlara, mağrur başlara,

Hep, Seni dediler, Sana yöneldim.

Sahip kimdir? dedim, ıssız çöllere,

Şimşeklere, tayfunlara, sellere,

Yedi kat semâya, bakan ellere,

Hep, Seni dediler, Sana yöneldim.

Aylar döner, mevsim döner, yıl döner,

Dünya döner, devran döner, yol döner,

Bir gün gelir, tövbe eder, kul döner,

Döndüm, döne döne, Sana yöneldim.

Mânâyı, maddeyi, önüme serdin,

Defteri kalemi, elime verdin,

''''Beni tanıyorsun, yaz artık'''' dedin,

Ne mümkün dedim de, Sana yöneldim.

Bu nâciz kuluna, ömür verdikçe,

Hayrına binlerce, hayır kat YÂ RAB,

Dünya var oldukça, mahşere kadar,

Amel defterini, açık tut YÂ RAB

ÂMİN! 

(1988)', 'Kuluna göz verdin, ''''gör Beni'''' dedin, Dil verdin, ''''bilene sor Beni'''' dedin, Gönül verdin, ''''hayra yor Beni'''' dedin, Gördüm, sordum, yordum...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Numanoğlu']::text[], 8.5, '{"poet":"Cengiz Numanoğlu","poet_slug":"cengiz-numanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":394,"source_url":"https://www.antoloji.com/sana-yoneldim-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Şarkısı', 'ask-sarkisi-ender-korkmaz-hp4sf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'BAŞKA ŞARKI

Bu şarkı başka şarkı

Bu şarkı hüzünle bitmeyen şarkı

Bu şarkı başka şarkı

Bu şarkı sevgiyi anlatan şarkı.

                               

                                                 Ender KORKMAZ', 'BAŞKA ŞARKI Bu şarkı başka şarkı Bu şarkı hüzünle bitmeyen şarkı Bu şarkı başka şarkı Bu şarkı sevgiyi anlatan şarkı.                       ...', ARRAY['Türk Edebiyatı','Şiir','Ender Korkmaz']::text[], 8.5, '{"poet":"Ender Korkmaz","poet_slug":"ender-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ask-sarkisi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşteyim.', 'atesteyim-ahmet-kurnaz-5r0ew', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerinin derinliğinde boğuluyorken bütün zamanlarım, 

gül kurusu akşamlarına düşlerinin, 

yüreğimi düşürdüm.

Yüreğim düştü akşamlarına, 

Ben, bir ateşin orta yerine.

Yani bir ateşteyim, korlar içinde, 

Ateşteyim, 

ateşteyim ama, 

Yanmıyorum...

Her yağmur damlasına yeminimi gizledim, 

bahar sabahlarında gurbetin.

Kavlimi koydum aramıza, 

sevdamı koydum.

Bir yudum su gibi 

akıp gitti düşlerim gözlerimden.

Bir bitmez hasret oldu bütün hayatım.

Günler döndü, Dünya döndü, ay döndü, 

sen, dönmedin.

Dün, düşüme gelmiştin sessizce.

Ellerini tuttum, 

gözlerine baktım, baktım, baktım.

Yüreğinin ateşini koydun yüreğime, 

bende yüreğimi avuçlarına.

Ve öylece gittin yine

yüreğimi alarak.

Sessiz ve isteksiz, 

alıp başını gittin.

Sana hasret çekecek sabır mı kaldı bende.

Yokluğuna katlanacak yürek mi? 

Aylar öncesinden ulaşmadı feryadım sana, 

sen duymadın.

Düşlerinde görmedin de yandığımı.

Uzattığım ellerimi görmedin.

Ses verdim, seslenmedin, 

yürek verdim, yüreğini gönderdin sadece, 

sen, gelmedin.

Geceleri mi sensiz zamanlarımın? 

Ben mi sensizim? 

Sitem mi yoksa yüreğinin çığlıkları, 

gözyaşların isyanlarda mı? Kırçiçeğim.

Ben ateşteyim dedim sana, 

sen ne haldesin? 

Hasretin neresinde yanıyorsun, 

neresinde yaşıyor? 

Beni düşündüğün geceleri düşündüm.

Yokluğuma, yokluğunu kattığın geceleri.

Gözyaşlarının ıslattığı yastığının altında ezildim, 

hıçkırıklarının bozduğu sessizliğinde o şehrin, 

dağıldım birtanem, 

toplayan olmadı beni.

Her bir parça''m bir yerde, 

Yüreğim, duygularım, hasretim

Ve, ve sen başka yerde, 

Ama nerdesin.....

                       12.03.2003   ELBİSTAN', 'Gözlerinin derinliğinde boğuluyorken bütün zamanlarım,  gül kurusu akşamlarına düşlerinin,  yüreğimi düşürdüm. Yüreğim düştü akşamlarına,  B...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kurnaz']::text[], 8.5, '{"poet":"Ahmet Kurnaz","poet_slug":"ahmet-kurnaz","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/atesteyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bakterinin Yaşama Gayreti 2', 'bir-bakterinin-yasama-gayreti-2-muhammed-ali-erol-33z9x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kaderim duello sessizliği

ellerim son yangının yüzülmüş derisi

şimdi bilir misin ki ettiğim yolculukları? 

bilemezsin

bilseydin

keşke bilseydin

bilemezsin...

bilmekle bilememek arası kaç metre 

bu yol nereye

yüzüm ıslak kaldırım ama

bu yol nereye

neden basıp geçer üstümden 

onca bulup yitirdiklerim

bulmakla yitirmek arası kaç metre.

kaç saniye daha sürer hayatım

ve daha kaç kez hapşırırım sence.

yerine yenisi çıkar mı saçların? 

çıkmaz! 

yani şimdi çıkmaz bir sokakta mıyım? 

ilk göz ağrısı unutulmazsa

ilk baş ağrısı unutulur mu? 

ilk ve son arası kaç metre? 

bu şiirin uzunluğu hayat kadar sürer mi? 

sürmez! 

dökülen saçlar da 

dökülen yıllar da geri gelmez...', 'kaderim duello sessizliği ellerim son yangının yüzülmüş derisi şimdi bilir misin ki ettiğim yolculukları?  bilemezsin bilseydin keşke bilsey...', ARRAY['Türk Edebiyatı','Şiir','Muhammed Ali Erol']::text[], 8.5, '{"poet":"Muhammed Ali Erol","poet_slug":"muhammed-ali-erol","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bir-bakterinin-yasama-gayreti-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığın Gölgesi', 'yalnizligin-golgesi-savas-burak-dincel-eqc9o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ağaçlar alık alık bakakalmıştı karşı göldeki kızıllığa

Yaşam her zamankinden daha soğuktu.

Bembeyaz bir çarşafla örtülüydü sokaklar.

Avuçlarımın arasından havaya karışan küçük rüzgarlarım

Bir masal anlatıyordu hiç dinlemediğim...

Hep aynı yerde asılı kalan bakışlarım, keşfindeydi büyüsünün

Buğulu  bir camın silinen görünürlüğünden habersiz...

Manzaralar, pencerler arkasında eli kolu bağlı

Yetim bir çocuğun arka sokaklardaki rüyalarının derinliğinde..

İşte muhabbet fasıllarında yitirdiğim anılarım

Hatırlayınca sakladığım ilk yaz kuşlarının suskunluğu, 

Dışarıda sıradan insanların çığlıklarından esinlendiğim

Ayrılık şiirleri.

Elimde kırmızı gözlü kılıcın kabzasına vuran 

Yolcu gemilerinin sonsuz vedaları var.

Hiçbir zaman sahip olamadığım beyaz mendillerin 

Güneşe el sallarken dağlara bıraktığı tebessüm var.

Bilinen görünürlüğün sahipsizliğinde...

Ben kendi merdivenimden çıkınca gökyüzüne, 

Ateşböceklerinin ışıltıları arasında 

Bulutlarda kaybolan gözyaşlarımı bulacağım; 

İpsi ipsi yağmurların odağında...

Karbeyazı akşamlar, toprak ananın bağrında uyuyor.', 'Ağaçlar alık alık bakakalmıştı karşı göldeki kızıllığa Yaşam her zamankinden daha soğuktu. Bembeyaz bir çarşafla örtülüydü sokaklar. Avuçlar...', ARRAY['Türk Edebiyatı','Şiir','Savaş Burak Dinçel']::text[], 8.5, '{"poet":"Savaş Burak Dinçel","poet_slug":"savas-burak-dincel","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yalnizligin-golgesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DEĞİŞİM', 'degi-si-m-uzeyir-lokman-cayci-nksr2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Onların

sararmış sarkıtlarını kırmadan

dokunmadan uçlarındaki 

kin damlalarına

ellerinle çeke çeke

kurumuş duygularını

bulaştırmadan başkalarına

girebilirsen içlerine

o zaman sen değişeceksin.

Onların

düşürmeden varlıklarını

ayak altlarına

bayır aşağı kaydırmadan

özlerini

dimdik tutarak bakışlarınla

girebilirsen içlerine

o zaman sen değişeceksin.

Onların

hırslarındaki

karışıklıkları dağıtarak

sererek önlerine 

utandırıcı kimliklerini

geçmişlerinde gezinmeden

ve belirsizliklerinde ezilmeden

girebilirsen içlerine

o zaman sen değişeceksin.

Zamanın üstünde 

senin duyguların

hiç endişelenme 

belirsizse yarın

kirlenmiş manzaralar karşısında

« kendilerini görsünler » diye

silkele yansımalarını 

üzerlerine.

onların

girebilirsen içlerine

o zaman sen değişeceksin.

Üzeyir Lokman ÇAYCI

Versailles  - 12.12.2002', 'Onların sararmış sarkıtlarını kırmadan dokunmadan uçlarındaki  kin damlalarına ellerinle çeke çeke kurumuş duygularını bulaştırmadan başkala...', ARRAY['Türk Edebiyatı','Şiir','Üzeyir Lokman Çaycı']::text[], 8.5, '{"poet":"Üzeyir Lokman Çaycı","poet_slug":"uzeyir-lokman-cayci","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/degisim-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Alışkanlık', 'aliskanlik-abdurrahim-karakoc-056j4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu kirli düzenin düzenbazları

Azrail''e rüşvet vermeyi dener; 

Ölünce dünyanın en kurnazları

Torpille cennete girmeyi dener.', 'Bu kirli düzenin düzenbazları Azrail''e rüşvet vermeyi dener;  Ölünce dünyanın en kurnazları Torpille cennete girmeyi dener....', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/aliskanlik-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecikmiş Borç', 'gecikmis-borc-ahmet-selcuk-i-lkan-xk84y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adana''ya bir gün yolun düşerse

Beni bitpazarında ara

Bil ki anıları bir sandığa koyup

Haraç-mezat satıyorumdur

Sana yazdığım şiirleri

Bir kadeh şaraba değişiyorumdur

Berlin''e yolun düşerse bir gün

Metrolarda beni ara

Kayıp çocuklar gibi ağlıyorumdur

Adını duvarlardan siliyorumdur

İstanbul''a yolun düşerse bir gün

Kadıköy''de beni ara

Ben de seni arıyorumdur

Sevdiğimi söyleyecektim sana

Seni bekliyorumdur', 'Adana''ya bir gün yolun düşerse Beni bitpazarında ara Bil ki anıları bir sandığa koyup Haraç-mezat satıyorumdur Sana yazdığım şiirleri Bir ka...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gecikmis-borc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yağmur', 'yagmur-ali-atmaca-p4c4y', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bilir misin? 

bu yağmurlu geceleri yaşamak ne zordur

kıvrak tayların ritminde iner yağmur taneleri

sara nöbetleri tutar denizi

sonra kapkara bir hüzün dolar odama

yanhzlık boylu boyunca yatağıma uzanır

içimin en azgın saatlerinde

bir fırtına kopar...

hasretin martı kanatlarından sıyrılıp yeryüzüne iner

sevda işlemeli türkülerle

bir fırtına kopar

her nefes alışımda

ve fırtınada yapayalnız ben kalırım.

ve yağmur yîne başlar.

yine ihanete uçar yarasalar, 

bilinmeyen bir sevdanın sancısıyla...

ey yağmur, boğum boğum kestin türkülerimi

yağmur...

usulca dokunur akşamlarıma

damlalarının soğukluğuna inat bir sıcaklıkla

bıçak ve gül

ikisini de alıp gider

bıçak senin olsun derim

gülü gönder bana, onu gönder

ey ölüm, 

ey! Yeryüzünü tekrar tekrar onaran Ölüm

masal ülkesinde gezerken, 

güneş yeniden doğacak görmelisin, 

ve  ben  yine  geleceğim,  sana  sevda  türküleri

söylemeye...', 'Bilir misin?  bu yağmurlu geceleri yaşamak ne zordur kıvrak tayların ritminde iner yağmur taneleri sara nöbetleri tutar denizi sonra kapkara...', ARRAY['Türk Edebiyatı','Şiir','Ali Atmaca']::text[], 8.5, '{"poet":"Ali Atmaca","poet_slug":"ali-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yagmur-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım Ben ve Moda', 'yalnizligim-ben-ve-moda-berna-ocakcioglu-1kbq0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir eylül ikindisi

Almışım yalnızlığımı karşıma

Bir bardak çayım yanımda 

Yorgunluğumu seriyorum 

Akşam rüzgârına Moda ''da 

Ne güzel anlaşıyoruz

Yalnızlığım  Ben ve Moda

Ah ne olurdu sanki

Biraz da bizim masaya

Uğrasaydı şu sevgi.

Ama ne güzel söylemiş şair: 

'' Ben sevmeyi beceremedim

Belki de sevilmeyi''', 'Bir eylül ikindisi Almışım yalnızlığımı karşıma Bir bardak çayım yanımda  Yorgunluğumu seriyorum  Akşam rüzgârına Moda ''da  Ne güzel anlaşıy...', ARRAY['Türk Edebiyatı','Şiir','Berna Ocakçıoğlu']::text[], 8.5, '{"poet":"Berna Ocakçıoğlu","poet_slug":"berna-ocakcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalnizligim-ben-ve-moda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-gokhan-gokbulut-2wb87', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düştüm ki öyle bir gurbete, 

Sana bağlı bitmesi garipliğimin, 

Sevdiğim sensin, sılam sensin elbette, 

Gurbetine bile hasretim, sevdiğimin.

Yaşıyorum en acı gurbeti, 

Ne dönüş yolu var, ne dönüş bileti, 

Umutsuzluğum had safhaya ulaştı, 

Buymuş yaşamın beteri.

Üç beş adım ötede sılam, 

Ama ona nasıl yaklaşam, 

Bu acı ekleniyor bir de üstüne, 

Düşünüyorum bir de! Ya uzakta kalırsam.', 'Düştüm ki öyle bir gurbete,  Sana bağlı bitmesi garipliğimin,  Sevdiğim sensin, sılam sensin elbette,  Gurbetine bile hasretim, sevdiğimin. ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Gökbulut']::text[], 8.5, '{"poet":"Gökhan Gökbulut","poet_slug":"gokhan-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gurbet-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'hoyat sevda', 'hoyat-sevda-ali-atmaca-awzlb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana pembeyle başlayan bir cümleyle seslenmek için yordum kendimi koç zamandır. Kaç zamandır, 

yıkanmış yağmurlara vurdum adını yalan kahkahalarına küstü yüreğim Yakalanmış kuşların duygularıydı ellerin ellerimde bıçaklanmış kumruların sancısı anlarsın diye korktu yüreğim sonra anlarsın ve yanarsın diye... oysa acımasız alevlerin etrafında masum bir ateşböceği öyküsüydün

Bu kahpe şehir, bu sürgün şehir kırıyordu ellerini kendini arıyordun ve gülüyordun kan doluyordu gözlerin, öyle ulu sevdalarda anılmıştı ki adın Tanrı katında korktum...

Yağmurları da

alıp içine koydun, sonra taştın

aynalara koştun sonra korktun

oyuncağını kırdılar kaç kez

yaşayıp durdun hep utana utana

kendin olmadın ve güldün hep

ağlaya ağlaya güldün sonra

korktum hep ağlayıp yanarsın diye

sonra gözlerim yaşardı

ben mi ağladım, bilemedim...

söylenmemiş türkülerim heybede ölümlerim, delikanlı sevdalarım vardı ve bıçak açmaz bir geceydim kurşun kâr etmezdi bana bulutlara sığmazdı yüreğim

Bela yumruklarıyla oynayan

küçük bir çocuktum...

hoyrat ellerimle, 

beyaz elbiseli bayram çocuklarının sevincini

çaldım, görmedin...

ve seni sen olarak

bilmediğin ulu sevdalara yazdığım

ve sonra hatırlatıp ta yandırdığım için

affet...', 'Sana pembeyle başlayan bir cümleyle seslenmek için yordum kendimi koç zamandır. Kaç zamandır,  yıkanmış yağmurlara vurdum adını yalan kahkah...', ARRAY['Türk Edebiyatı','Şiir','Ali Atmaca']::text[], 8.5, '{"poet":"Ali Atmaca","poet_slug":"ali-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/hoyat-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklı Sevgi', 'sakli-sevgi-berna-ocakcioglu-muhfg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Çığlık çığlık susuyorum sevgini 

Haykırmak istiyor, 

Kalbime saklıyorum.

Ne zormuş sevip te söyleyememek

Sana tel örgüler  ardından bakıyorum.', 'Çığlık çığlık susuyorum sevgini  Haykırmak istiyor,  Kalbime saklıyorum. Ne zormuş sevip te söyleyememek Sana tel örgüler  ardından bakıyoru...', ARRAY['Türk Edebiyatı','Şiir','Berna Ocakçıoğlu']::text[], 8.5, '{"poet":"Berna Ocakçıoğlu","poet_slug":"berna-ocakcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sakli-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ağlama', 'aglama-ali-atmaca-4ym6u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yaran derindi bilirim

Yolun uzaktı

Sussan camlar kırılırdı içinde

Susmasan yüreğin

Ya geç kalınmış saatlere kanardı yüreğin

Ya da yeni emekleyen çocuklar gibi koşmak isterdin

Koşamazdın ki

Her defasında düşüp

Her defasında yürümeyi dahi bilmeden

Hep koşmak isterdin

Hep koşmak üzre içlenip

Koşmak isterdin...

İlle de ebemküşağına takılırdı ayak bileklerin

Ağlardın

Gözlerin damla damla kan olurdu

Melek olurdun

Ağlardın

İçine bir hüzün dolardı

Bir düş kurardın

Adını ben koyardın

Ben bilirdim 

Ama sen anlatmazdın

Şakağına düşen yağmurları  saklardın

Ben bilirdim 

Senin ülkende bulutlar ağlamazdı

Sen ağlardın

Yalnızlıktan usanmış yalnızlığa inat

Sevda dolu bakışlarla

Sen ağlardın

Yüreğinde bir mermi patlardı

Bir katil öper ya annesini

Öldürmeden önce

İşte öyle ağlardın', 'Yaran derindi bilirim Yolun uzaktı Sussan camlar kırılırdı içinde Susmasan yüreğin Ya geç kalınmış saatlere kanardı yüreğin Ya da yeni emekl...', ARRAY['Türk Edebiyatı','Şiir','Ali Atmaca']::text[], 8.5, '{"poet":"Ali Atmaca","poet_slug":"ali-atmaca","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/aglama-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Kaybetmek Seni', 've-kaybetmek-seni-ahmet-selcuk-i-lkan-83k2i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'O seni düşünmek yok mu

Geceler dolusu seni düşünmek

Sarılmak karanlıklara sen diye

Sen diye kucaklamak yorganı okşamak, öpmek

O seni beklemek yok mu

Her gün sabahlara dek uykusuz beklemek

Ahh, ayak sesleri, kapı gıcırtıları bilemezsin

Bir defa yaşamaktır o, bin defa ölmek

O seni özlemek yok mu

Saçlarını, ellerini, dudaklarını özlemek

Uzun uzun gözgöze gelmek seninle

Seninle bir olmak, beraber olmak, sevişmek

O seni gizlemek yok mu

Kuşlrdan, çiçeklerden bile kıskanıp gizlemek

Seni saklamak içimde delice, divanece

Öylece yaşamak seni, öylece sevmek

Ve seni kaybetmek yok mu

Bulduktan sonra seni kaybetmek

İşte o beni yakan, yıkan, solduran

Ses versem de duyamazsın artık

Yüreğimde kan, gözlerimde kan, dudaklarımda kan', 'O seni düşünmek yok mu Geceler dolusu seni düşünmek Sarılmak karanlıklara sen diye Sen diye kucaklamak yorganı okşamak, öpmek O seni bekleme...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ve-kaybetmek-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VER YÜREĞİNİ', 'ver-yuregi-ni-berna-ocakcioglu-lt7qh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kış yapraklarının ardına gizlediğim

Güneşimi alıp ta elime

Ben geliyorum sana 

Ver yüreğini yüreğime.

2001', 'Kış yapraklarının ardına gizlediğim Güneşimi alıp ta elime Ben geliyorum sana  Ver yüreğini yüreğime. 2001...', ARRAY['Türk Edebiyatı','Şiir','Berna Ocakçıoğlu']::text[], 8.5, '{"poet":"Berna Ocakçıoğlu","poet_slug":"berna-ocakcioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ver-yuregini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen - 2', 'sen-2-gokhan-gokbulut-966mf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Elbet bu karanlıklar bir gün geçer, 

Hayatta olmasa bile ölünce biter, 

Gecelerden daha karanlık gündüzler, 

Işığım da sensin, karanlığım da sensin.

Aşk bu çekilecek bir kaç çile, 

Belki ayrılıkla belki hasret ile, 

Ama aşk da gelir bir gün dile, 

Çilem de sensin hasretim de sensin.

Bülbül şarkı söylermiş gülü için, 

Ferhat dağları yarmış Şirin için, 

Ben de birkaç mısra dizdim senin için, 

Gülüm de sensin, Şirinim de sensin.

Dile gelse yastığım, neler söyler acaba, 

Söyler mi ağladığımı geceler boyunca, 

Ya da ne kadar aşık olduğumu sana, 

Gözyaşım da sensin, gecem de sensin.', 'Elbet bu karanlıklar bir gün geçer,  Hayatta olmasa bile ölünce biter,  Gecelerden daha karanlık gündüzler,  Işığım da sensin, karanlığım da...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Gökbulut']::text[], 8.5, '{"poet":"Gökhan Gökbulut","poet_slug":"gokhan-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sen-2-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlığa Açılacak Gözler', 'karanliga-acilacak-gozler-orcun-oruc-aykac-z3mep', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimde karanlık, 

Elimde sen, 

Seni arıyorum

Karanlığın içinde.

Biliyorum, 

Gözlerim kamaşacak

Seni görünce.', 'İçimde karanlık,  Elimde sen,  Seni arıyorum Karanlığın içinde. Biliyorum,  Gözlerim kamaşacak Seni görünce....', ARRAY['Türk Edebiyatı','Şiir','Orçun Oruç Aykaç']::text[], 8.5, '{"poet":"Orçun Oruç Aykaç","poet_slug":"orcun-oruc-aykac","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/karanliga-acilacak-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğamın Yalancısıyım', 'dogamin-yalancisiyim-orcun-oruc-aykac-sfbmi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni duyuyorum ama seslenemiyorum

Öylesine oturmuş seni dinliyorum

Düşüncelerimi bıçak açmıyor.

Aklımda ne çok cümle var

Bir kelimesini bile söyleyemiyorum

Seni çok özledim ama

Özlemezlikten geliyorum

Ben doğamın yalancısıyım.

04.10.2000', 'Seni duyuyorum ama seslenemiyorum Öylesine oturmuş seni dinliyorum Düşüncelerimi bıçak açmıyor. Aklımda ne çok cümle var Bir kelimesini bile...', ARRAY['Türk Edebiyatı','Şiir','Orçun Oruç Aykaç']::text[], 8.5, '{"poet":"Orçun Oruç Aykaç","poet_slug":"orcun-oruc-aykac","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dogamin-yalancisiyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam Sevmezsen Daha Kolay', 'yasam-sevmezsen-daha-kolay-gokhan-gokbulut-zqr0n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne olur sanki öyle bakmasan, 

İçim gidiyor sen öyle bakınca, 

Su gibi yüreğimden akmasam, 

Herşey siliniyor kalbimden sen akınca.

Sesin kulağımdan hiç eksilmese, 

Hiç ayrılmasa gözüm senden, 

Geçen yıllar seni kalbimden silmese, 

Uzaklaştırmasa beni senden.

İnan çok zor söylemek sevdiğini, 

İnan yaşamak daha kolay, 

Kıyaslanamaz asla yaşamla sevgi, 

Yaşam dediğin üç beş günlük olay.', 'Ne olur sanki öyle bakmasan,  İçim gidiyor sen öyle bakınca,  Su gibi yüreğimden akmasam,  Herşey siliniyor kalbimden sen akınca. Sesin kula...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Gökbulut']::text[], 8.5, '{"poet":"Gökhan Gökbulut","poet_slug":"gokhan-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasam-sevmezsen-daha-kolay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam Sevmekten Daha Kolay', 'yasam-sevmekten-daha-kolay-gokhan-gokbulut-w7jrw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne olur sanki öyle bakmasan, 

İçim gidiyor sen öyle bakınca, 

Su gibi yüreğimden akmasam, 

Herşey siliniyor kalbimden sen akınca.

Sesin kulağımdan hiç eksilmese, 

Hiç ayrılmasa gözüm senden, 

Geçen yıllar seni kalbimden silmese, 

Uzaklaştırmasa beni senden.

İnan çok zor söylemek sevdiğini, 

İnan yaşamak daha kolay, 

Kıyaslanamaz asla yaşamla sevgi, 

Yaşam dediğin üç beş günlük olay.', 'Ne olur sanki öyle bakmasan,  İçim gidiyor sen öyle bakınca,  Su gibi yüreğimden akmasam,  Herşey siliniyor kalbimden sen akınca. Sesin kula...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Gökbulut']::text[], 8.5, '{"poet":"Gökhan Gökbulut","poet_slug":"gokhan-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yasam-sevmekten-daha-kolay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni bulamazsın...', 'beni-bulamazsin-ataman-kaya-5dy1j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yanacak yüreğin ateş ile, 

Bir damla sevdamı arar bulamazsın.

Yanarsın kül olana dek

Sığınacak bir kucak bulamazsın.

Sararıp solacaksın zaman içinde, 

Bir damla göz yaşımı arar göremezsin.

Yüreğin kurur, ellerin donar, 

Kalbini ısıtacak bir yürek bulamazsın.

Dalıp dalıp gideceksin yaşadığımız hayallere, 

Bir damla teselli arar bulamazsın.

Gözlerin mahmurlaşır yüreğin daralır, 

Seviyorum prenses! Diyen birini bulamazsın.

Dönüp bakacaksın o mutlu günlerimize, 

Bir damla ışık hissedemezsin, 

Denizi her gördüğünde, 

Nefesimi hissedecek bir dudak bulamazsın.

Okuyup ağlayacaksın senin için yazdıklarıma, 

Böyle bir hissedişi anlayamazsın.

Okudukça hıçkırıklar saracak göğsünü, 

Zaman geçecek beni bulamazsın.

23 Haziran 2000 İstanbul

Ataman Kaya', 'Yanacak yüreğin ateş ile,  Bir damla sevdamı arar bulamazsın. Yanarsın kül olana dek Sığınacak bir kucak bulamazsın. Sararıp solacaksın zama...', ARRAY['Türk Edebiyatı','Şiir','Ataman Kaya']::text[], 8.5, '{"poet":"Ataman Kaya","poet_slug":"ataman-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/beni-bulamazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum - 2', 'seni-seviyorum-2-gokhan-gokbulut-v7cf8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazen gözün gözüme deyiyor, 

O zaman daha güzel geliyorsun, 

Yüzün gözlerin kadar güzel, 

Gözlerin sen kadar güzel geliyor.

Eşsiz bir güzellik senin ki, 

Dünyada yok senin gibisi, 

Bunu hep bil ki, 

Her şeyinle seviyorum seni.

Bazen hayallerimdeki ruhsun, 

Bazen rüyamdaki billursun, 

Bazen hayatımdaki nursun, 

Kalbimin sultanısın, herkes duysun.

Sen benim Zümrüt Ankamsın, 

Kafdağına bir kere gidilir hayatta, 

Sen beni Kafdağına götürecek aşksın, 

Lütfen bensiz gitme Kafdağına.', 'Bazen gözün gözüme deyiyor,  O zaman daha güzel geliyorsun,  Yüzün gözlerin kadar güzel,  Gözlerin sen kadar güzel geliyor. Eşsiz bir güzell...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Gökbulut']::text[], 8.5, '{"poet":"Gökhan Gökbulut","poet_slug":"gokhan-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seni-seviyorum-2-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-gokhan-gokbulut-nsx5q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sensiz yapamıyorum, 

Çekilmiyor bu hayat, 

Sensiz olamıyorum, 

Sensiz bu günler hoyrat.

Olmuyor asla sensiz, 

Geçmiyor sensiz günler, 

Sensiz bu kalbim aciz, 

Çekilmiyor çileler.

Sensiz gülmüyor yüzüm, 

Kalbim keder içinde, 

Seni arıyor hep gözüm, 

Keder dostumken bile.', 'Sensiz yapamıyorum,  Çekilmiyor bu hayat,  Sensiz olamıyorum,  Sensiz bu günler hoyrat. Olmuyor asla sensiz,  Geçmiyor sensiz günler,  Sensi...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Gökbulut']::text[], 8.5, '{"poet":"Gökhan Gökbulut","poet_slug":"gokhan-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sensiz-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Acı Aşk', 'en-aci-ask-gokhan-gokbulut-3a5q6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne biliyor musun? Aşkın en acıklı hali, 

Sevmen ama kavuşamaman sevdiğine, 

Bu aşk ki yolları hep dikenli, 

Yanında kırmızı bir gül olsa bile.

Derler en acı aşk en üstün aşktır, 

Ama aşkın olur mu üstünü alçağı, 

Derler aşk birkaç bakıştır, 

Biter çekilince gönül ağı.', 'Ne biliyor musun? Aşkın en acıklı hali,  Sevmen ama kavuşamaman sevdiğine,  Bu aşk ki yolları hep dikenli,  Yanında kırmızı bir gül olsa bil...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Gökbulut']::text[], 8.5, '{"poet":"Gökhan Gökbulut","poet_slug":"gokhan-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/en-aci-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudun Ezgisi', 'umudun-ezgisi-gokhan-gokbulut-hae1x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben umudum.

Her zaman bir köşede duran, 

Saatini son ana kuran, 

Her şeyin bittiğinde çıkan, 

Umudum ben.

Etrafınızda kimse kalmadığı zaman, 

Kalbinizin bile sizi unuttuğu zaman, 

İçinizi her zaman ferahlatan, 

Umudum ben.', 'Ben umudum. Her zaman bir köşede duran,  Saatini son ana kuran,  Her şeyin bittiğinde çıkan,  Umudum ben. Etrafınızda kimse kalmadığı zaman,...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Gökbulut']::text[], 8.5, '{"poet":"Gökhan Gökbulut","poet_slug":"gokhan-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/umudun-ezgisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BAHTI KARALIM', 'bahti-karalim-ali-aksoy-jd5km', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşamak bir defa, ölmek bir defa, 

                                     Bile bile neden çekilir cefa, 

                                     Sürmek varken bilmem zevk ile sefa, 

                                     Neden hala hüzün gönlü yaralım…

                                                   Artık yalanı bil doğruyu tanı, 

                                                   Yaşananı unut saymada anı, 

                                                   Bak geldi geçiyor aşkın zamanı, 

                                                   Sevmek hiç zor değil bahtı karalım…

                                     Tren gelir geçer bazen hoş gelir, 

                                     Bazen hüzne gider ama boş gelir, 

                                     Düşünüp atla bak sonra taş gelir, 

                                     Kır zinciri aç kalbini maralım…

                                                   Tut kolundan sımsıkı sar sarmala, 

                                                   Aşk treni göründü bak yakala, 

                                                   Sil maziyi fırlat at bir kenara, 

                                                   Gel yeni bir aşka sayfa açalım…', 'Yaşamak bir defa, ölmek bir defa,                                       Bile bile neden çekilir cefa,                                       ...', ARRAY['Türk Edebiyatı','Şiir','Ali Aksoy']::text[], 8.5, '{"poet":"Ali Aksoy","poet_slug":"ali-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bahti-karalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimin Sıcaklığı', 'yuregimin-sicakligi-gokhan-gokbulut-i1rg2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir kara kış sabahı kalktım uykumdan, 

Her tarafım donmuş, bir tek kalbim sıcak, 

Kalbimi alev sarmış senin aşkından, 

Donmuşum, üşüyorum, tek kalbim sıcak.

Belki temmuzun sıcaklığı seninki, 

Ama hayır temmuz bile daha soğuk

Aşkının sıcaklığı bu kalbimdeki, 

Yüreğimin dışında her yerim soğuk.', 'Bir kara kış sabahı kalktım uykumdan,  Her tarafım donmuş, bir tek kalbim sıcak,  Kalbimi alev sarmış senin aşkından,  Donmuşum, üşüyorum, t...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Gökbulut']::text[], 8.5, '{"poet":"Gökhan Gökbulut","poet_slug":"gokhan-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yuregimin-sicakligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Dönmeyecekmiş Gibi Sözlerin', 'hic-donmeyecekmis-gibi-sozlerin-ali-aksoy-n8zkz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç dönmeyecekmiş gibi sözlerin, 

	Hiç gülmeyecekmiş gibi gözlerin, 

	Sensiz olmak yaşamamak bir tanem, 

	Benden yana değişmesin hislerin...

	Nene gerek elveda deyip gitmek, 

	Nene gerek sevene hüzün vermek, 

	Zordur gülüm gurbette hasret çekmek, 

	Gecelerce korku dolar düşlerin...

	Güzel değil yaşanan sensiz günler, 

	Avunmaya kafi gelmezde dünler, 

	Son kez düşün kararmasın gönüller, 

	Kaybolursun bulunmazda izlerin...

	Sanma her şey daha güzel olacak, 

	Sanma maziler hep aynı kalacak, 

	İlk aşklar bir daha yaşanmayacak, 

	Bilmelisin olacak hüzünlerin...', 'Hiç dönmeyecekmiş gibi sözlerin,  	Hiç gülmeyecekmiş gibi gözlerin,  	Sensiz olmak yaşamamak bir tanem,  	Benden yana değişmesin hislerin......', ARRAY['Türk Edebiyatı','Şiir','Ali Aksoy']::text[], 8.5, '{"poet":"Ali Aksoy","poet_slug":"ali-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hic-donmeyecekmis-gibi-sozlerin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GİT AYRILIKLAR SENDEN/GÖZYAŞI BENDEN OLSUN', 'gi-t-ayriliklar-senden-gozyasi-benden-olsun-ali-aksoy-ih54l', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayrılıp gideceksen, 

                                           Dilinde sözüm olsun, 

                                           Sana dur kal diyemem, 

                                           Ardında gözün olsun.

                                                         Unutma hep hatırla, 

                                                         Boş hayale kapılma, 

                                                         Yaz bir şeyler karala, 

                                                         Mektubun uzun olsun.

                                           Özle ve dilek dile, 

                                           Hayattan bir şey bekle, 

                                           Kapılıp gitme sele, 

                                           Kavuşmak arzun olsun.

                                                         Yoluna engel komam, 

                                                         Hüznüne sebep olmam, 

                                                         Kötü sözde vuramam, 

                                                         Git yolun açık olsun.

                                           Yoksam da bana güven, 

                                           Ve yine bil tek seven, 

                                           Git ayrılıklar senden, 

                                           GÖZYAŞI BENDEN OLSUN.', 'Ayrılıp gideceksen,                                             Dilinde sözüm olsun,                                             Sana dur ka...', ARRAY['Türk Edebiyatı','Şiir','Ali Aksoy']::text[], 8.5, '{"poet":"Ali Aksoy","poet_slug":"ali-aksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/git-ayriliklar-senden-gozyasi-benden-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Tanımı', 'askin-tanimi-gokhan-gokbulut-p64h0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalbim sürekli seni arıyor, 

Hiçbir zaman unutmuyor, 

Aşk diyorlar sanırım buna, 

Vurunca geçmiyor asla.

Kalbim senin için herşeyi yapar, 

Bedenim de kalbime uyar, 

Sen iste dünyayı durdurur, 

Senin dışında herşeyi unutturur.

Unutamam asla seni, ömrüm boyunca

Seni anar bu kalp her attığında, 

Ben unutsam bile kalbim unutmaz, 

Çünkü bilir senin gibisini bir daha bulamaz.

Kalbimdeki alev her yere sıçrar, 

Bu sayede aşkını her yerde yaşar, 

Herkes sevdiği için Roma''yı yakar, 

Ama senin için bu alev tüm dünyayı yakar.', 'Kalbim sürekli seni arıyor,  Hiçbir zaman unutmuyor,  Aşk diyorlar sanırım buna,  Vurunca geçmiyor asla. Kalbim senin için herşeyi yapar,  B...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Gökbulut']::text[], 8.5, '{"poet":"Gökhan Gökbulut","poet_slug":"gokhan-gokbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/askin-tanimi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalanmış', 'yalanmis-yilmaz-sezgin-bsq23', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalanmış sevenler 

Yalanmış sözler

Mazide kalmış nice dostluklar

Düşmanın olsaymış bütün insanlar

Ödün vermezdin

Hiç güvenmezdin

Sırrını başkalarına

Dost bilip söylemezdin

Başında esen bunca fırtına

Ya dolaşan siyah bulutlar

Bil ki

Dost görünüp seni aldattılar

Onlara kandın 

Yalanlarına inandın

Yüzüne gülünce mutluluk sandın

Onlar mutluydular senin mutsuzluğunla

Onlara çok zaman eğlence oldun ya

Bu dünya 

Seninle sensizlik sanki umurunda

İnsanı bencil

Sevgiyi bilmez 

Sevimsiz bir dünya

     16 Haziran 1993', 'Yalanmış sevenler  Yalanmış sözler Mazide kalmış nice dostluklar Düşmanın olsaymış bütün insanlar Ödün vermezdin Hiç güvenmezdin Sırrını baş...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Sezgin']::text[], 8.5, '{"poet":"Yılmaz Sezgin","poet_slug":"yilmaz-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yalanmis-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SOKAK ÇOCUKLARININ NAFAKASI', 'sokak-cocuklarinin-nafakasi-yilmaz-sezgin-lwpfd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir sonbahar günü sabahında

Çığ taneleri arasında güneşin soğuk ışıklarıyla

Aydınlanan yeşil vadi parkında

Don gömlek içinde bir çocuk kaldırımda uzanmakta

Sarı panjurlu evin köpeği balkonda havlamakta

Uzay çatılı konaktan bir çığlık kopmakta

İthal köpeği Nataşa

Pisliğini salon yerine banyoda çıkarmakta

Çocuksa hala kaldırımda uzanmakta

Gözleri bir mermer taşına bakmakta

Gelip geçen umursamaz bir havada

Oda gelip geçeni umursamıyor ya

Karın tokluğu neşesi ile şakımakta

Köşedeki dükkanda sarı kanarya

Parkın bitişiğindeki köşkün kedisi Tamara

Sahibinin verdiği ciğer için kuyruk sallamakta

Çocuk hala kaldırımda uzanmakta

Ya anası babası yoksa

Sorsam küfreder mi bana

Birilerinin dediği gibi sen kendi işine baksana

Birilerinin çocukları diskolarda zıplamakta

Birilerinin cebi ihaleyle dolmakta

Birilerinin göbeği tıkınmakla çatlamakta

Birilerinin elleri sarmaş dolaş enflasyonla

Birilerinin zihinleri devalüasyonla uğraşmakta

Birileri sokak çocuklarının nafakasını çalmakta

Sanki birilerinin parktaki çocuk umurunda

Ve çocuklar hala kaldırımlarda uyanmakta

                                               1998', 'Bir sonbahar günü sabahında Çığ taneleri arasında güneşin soğuk ışıklarıyla Aydınlanan yeşil vadi parkında Don gömlek içinde bir çocuk kaldı...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Sezgin']::text[], 8.5, '{"poet":"Yılmaz Sezgin","poet_slug":"yilmaz-sezgin","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sokak-cocuklarinin-nafakasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstemek...', 'i-stemek-ahmet-firat-p10tj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gönlüm seni ister, 

Sözler bahane.

Sözler ağız ister, 

Dil bahane.

Dil insan ister, 

Utanç bahane.

Utanç olsa, 

Gidilemeyen yer olurdu meyhane.

Şarabımı yudumlarkene

Aklıma sen geldin.

Başkası olsa, 

Diyeceği ilk kelam, bana ne! 

Ama sen bi tanesin, bi tane

Bulmacam seni istedi

Güzelliğini sayamadım.

O kadar alim değilim.

Adın kaç hane? 

Şimdi bu da soru mu? 

Bilmesem bunun utanç olduğunu

Kalırdım biçare.', 'Gönlüm seni ister,  Sözler bahane. Sözler ağız ister,  Dil bahane. Dil insan ister,  Utanç bahane. Utanç olsa,  Gidilemeyen yer olurdu meyha...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Fırat']::text[], 8.5, '{"poet":"Ahmet Fırat","poet_slug":"ahmet-firat","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/istemek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benden iste.	! !', 'benden-iste-mert-kaan-2vc0w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Derya kadar derdin, coksa, 

Karnın acta, Gözün toksa, 

Arkadaşın, dostun yoksa, 

benden iste, benden iste.

Gönlümden, bir gül istersen, 

Ömrümden, bir dal istersen, 

Tatlısözlü, bal istersen, 

benden iste, benden iste.

Karanlıga, ışık dersen, 

İnsanlıga, Aşık dersen, 

Adaletli, ne istersen, 

benden iste, benden iste.

Merhametli, histen yana, 

Umudu, yitirmiş Cana, 

Aşk istersen, kana kana, 

benden iste, benden iste.

Unutma, bende İnsanım, 

Sevdalıyım, farklı yanım, 

Gerekirse, kuru Canım, 

benden iste, benden iste.', 'Derya kadar derdin, coksa,  Karnın acta, Gözün toksa,  Arkadaşın, dostun yoksa,  benden iste, benden iste. Gönlümden, bir gül istersen,  Ömr...', ARRAY['Türk Edebiyatı','Şiir','Mert Kaan']::text[], 8.5, '{"poet":"Mert Kaan","poet_slug":"mert-kaan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/benden-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir yüzük isterim', 'bir-yuzuk-isterim-mert-kaan-0fz6h', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir yüzük isterim, kaşıda olsun, 

İcinde bir fiske, zehir bulunsun, 

Dara düşersem, zora düşersem, 

Gül´üm sana, kavuşamazsam, 

Kaşındaki fiske, ilacım olsun, 

Pırlantası olsun, göz kamaştıran, 

Mecnunu cöllerden, susuz aştıran, 

Aşık kavuşturan, küs barıştıran, 

Tılısımı, mucizesi, uguru olsun.

Kardeşlige, barışa vesile olsun, 

Kötü yüreklere, sevgi doldursun, 

Mert kaan corbada, tuzum bulunsun, 

İllede savaş diyen, buş canisini, 

Şişeye hapsedip, bekcisi olsun.', 'Bir yüzük isterim, kaşıda olsun,  İcinde bir fiske, zehir bulunsun,  Dara düşersem, zora düşersem,  Gül´üm sana, kavuşamazsam,  Kaşındaki fi...', ARRAY['Türk Edebiyatı','Şiir','Mert Kaan']::text[], 8.5, '{"poet":"Mert Kaan","poet_slug":"mert-kaan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-yuzuk-isterim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan', 'yalan-osman-i-slam-9cz21', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yılan çiyan ile dolmuş etrafım

Beni benden almak istercesine

Yalan olmuş dünkü doğru tarafım

Beni bana satmat istercesine

Dünkü doğrularım gitmiş de elden

Bugün beni kemirmekteler

En sadık bildiklerim yanımda

Beni sömürmekteler

Yalan, olanca gücüyle herşey yalan

Dünya, insan, vefa, duygu, sevgi yalan

Aşk, arkadaş, dost, hepsi yalan

Var biraz da sen oyalan', 'Yılan çiyan ile dolmuş etrafım Beni benden almak istercesine Yalan olmuş dünkü doğru tarafım Beni bana satmat istercesine Dünkü doğrularım g...', ARRAY['Türk Edebiyatı','Şiir','Osman İslam']::text[], 8.5, '{"poet":"Osman İslam","poet_slug":"osman-i-slam","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yalan-56-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uğramıştım Sadece', 'ugramistim-sadece-elif-gultekin-34wp3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Geçiyordum…

Uğradım, 

Hayat denen macera evine…

İnsanları gördüm tertemiz, 

Sonra farkına vardım kötü olanların…

Ağaçları gördüm, 

Nehirleri, çiçekleri ve, 

Kana kana su içtim çoban çeşmesinden…

Hatta bir gün ağladım…

Belki bir daha ağlayamam diye, 

Tadını çıkardım hıçkırıkların…

Hatırlıyorum, 

Birkaç kez de gülmüştüm, 

Tadını çıkardım kahkahalarımın…

Tarlada çalışmak mutlulukmuş, 

Meyvelerimi toplayınca anladım…

Hiç unutmam, 

Ben bir gece karanlığı yaşarken, 

Güneşi fark ettim doğdu doğacak, 

İnsanlarda bir telaştır başlayacak…

Baktım koşuşturan insanlara…

Tadını çıkardım simitçi sesinin, 

Ve bir parça simit attım güvercinlere…

Yüzdüm koskoca denizde, 

Yüzmüyor, uçuyordum, 

Farkına vardım…

Nice medeniyetleri ağırlamış, 

İstanbula konuk oldum…

Kanuniyle aynı havayı soludum, 

Ve yürürken İstanbul sokaklarında, 

Fatihi hissettim yanıbaşımda…

Yemek yedim mutlulukla…

Koklaya koklaya, 

Farkına vara vara, 

Bir çorba içtim…

Tatlı yedim, 

Acı yedim, 

Ekşi yedim, 

Tuz yedim, 

Farkına vardım her dört tadın, 

Tadını çıkardım tadların…

Aşık oldum, 

Ve kalbimin farkına vardım, 

Çılgınca çarptığında…

Ne yazık ki ben, 

Geçerken uğramıştım…

Ölmeyi de isterdim, 

Zamanın farkına varabilmek için, 

Ölmeyi de isterdim…', 'Geçiyordum… Uğradım,  Hayat denen macera evine… İnsanları gördüm tertemiz,  Sonra farkına vardım kötü olanların… Ağaçları gördüm,  Nehirleri...', ARRAY['Türk Edebiyatı','Şiir','Elif Gültekin']::text[], 8.5, '{"poet":"Elif Gültekin","poet_slug":"elif-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":49,"source_url":"https://www.antoloji.com/ugramistim-sadece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DÜŞ', 'dus-orhan-onur-udetd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'DÜŞ

önce

burnunun ucuyla çizersin

sonra

boyarsın içini hayallerin

uyanma ne olur

yüzyılın güzelliği var bu düşte

yüzyıl uyuyan güzel gibi

yaşamak düşlerde

                                              

20.10.1999/Kütahya

ORHAN ONUR', 'DÜŞ önce burnunun ucuyla çizersin sonra boyarsın içini hayallerin uyanma ne olur yüzyılın güzelliği var bu düşte yüzyıl uyuyan güzel gibi ya...', ARRAY['Türk Edebiyatı','Şiir','Orhan Onur']::text[], 8.5, '{"poet":"Orhan Onur","poet_slug":"orhan-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/dus-44-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİLMEK yada BİLMEMEK', 'bi-lmek-yada-bi-lmemek-orhan-onur-jdixn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'BİLMEK  yada BİLMEMEK                     

tek şey var bildiğim, 

keza bilmediğim, bilemediğim! 

bilemediğim bildiğime dair, 

bildiğimse sana! 

bildiğim bende, 

bilemediğimse sende saklı! 

sen biliyorsun, bilemediğimi...

bildiğimi ise yanlız ben.

o halde, 

bir bildiğin var senin, 

aynı zamanda bilmediğin.

belki de bilemediğin, 

veya bilmek istediğin! 

kimbilir  belki de, 

bilmediğin benim tek bildiğim, 

bildiğinse benim tek bilemediğim.

kimbilir belki de, 

bildiğimiz aynı şey bizim, 

                                    

01.11.1999/Kütahya

ORHAN ONUR', 'BİLMEK  yada BİLMEMEK                      tek şey var bildiğim,  keza bilmediğim, bilemediğim!  bilemediğim bildiğime dair,  bildiğimse san...', ARRAY['Türk Edebiyatı','Şiir','Orhan Onur']::text[], 8.5, '{"poet":"Orhan Onur","poet_slug":"orhan-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bilmek-yada-bilmemek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR ANLIK GÜNLÜK', 'bi-r-anlik-gunluk-orhan-onur-89lmh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'BİR ANLIK GÜNLÜK

merhaba sevgili günlük

bu yalnızlığımın bilmem kaçıncı günü

bazen yoklama alıyor ruhum

aklım bir yerlerde

bedenim devamsızlıktan kaldı

kalbim baştan aşağı kırık

yaşadığımı hatırlatanlar var

hatırı pek sayılmasa da

şu kuru öksürük daha ziyade

bir özrün özünde ben; 

kendimi kaybettim: hükümsüzdür! 

01.12.1999/Kütahya

ORHAN ONUR', 'BİR ANLIK GÜNLÜK merhaba sevgili günlük bu yalnızlığımın bilmem kaçıncı günü bazen yoklama alıyor ruhum aklım bir yerlerde bedenim devamsızl...', ARRAY['Türk Edebiyatı','Şiir','Orhan Onur']::text[], 8.5, '{"poet":"Orhan Onur","poet_slug":"orhan-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bir-anlik-gunluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'NEYE YARAR', 'neye-yarar-orhan-onur-sabes', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'NEYE YARAR

yüreğimin atmasına gerek yok

nefsimin devamına gerek kalmadığı gibi

varsın hiç başlamamış gibi öylece dursunlar

ben, benliğimi yitirmişim neye yarar

zamanın ilerlemesine gerek yok

tarihe ve geleceğe ihtiyaç olmadığı gibi

varsın sonsuza dek suskun kalsınlar

ben hala aynı yerdeyim, neye yarar

gözlerimin görmesine gerek yok

kulaklarımın duymasına gerek olmadığı gibi

varsın hacet kalmasın beş duyumda

seni sen gibi hissedemedikten sonra neye yarar

umutlarımın olasılığa ihtiyacı yok

hayallerimin gerçekliğe olmadığı gibi

varsın kahpe bir tuzağa yenik düşsünler

işim şansa kalmışsa bundan böyle neye yarar

mutlulukların gayrımeşrularına tenezzürüm yok

avuntuların irili ufaklılarına olmadığı gibi

varsın küskün kalsınlar ebediyete dek

ben kendimi kandırdıktan sonra neye yarar

azrailin pis pis sırıtmasına gerek yok

kılınçını bilemesine gerek olmadığı gibi

varsın felekler yansın ahımdan

ölümlere aşinayım ben neye yarar 

                                          

27.11.1999/Kütahya

ORHAN ONUR', 'NEYE YARAR yüreğimin atmasına gerek yok nefsimin devamına gerek kalmadığı gibi varsın hiç başlamamış gibi öylece dursunlar ben, benliğimi yi...', ARRAY['Türk Edebiyatı','Şiir','Orhan Onur']::text[], 8.5, '{"poet":"Orhan Onur","poet_slug":"orhan-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/neye-yarar-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'EY GÖNÜL', 'ey-gonul-orhan-onur-s5u17', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'EY GÖNÜL! 

tıpkı bir fahişe gibisin.

her sevdanla mı yatıyorsun, 

yoksa her yattığına mı sevdalanıyorsun

bilmiyorum..

belki de bu yüzden, 

sevmemeyi seviyorum.

belki de bu yüzden, 

sevmeyi sevmiyorum.

                            

Temmuz’99/Bartın-İnkumu

ORHAN ONUR', 'EY GÖNÜL!  tıpkı bir fahişe gibisin. her sevdanla mı yatıyorsun,  yoksa her yattığına mı sevdalanıyorsun bilmiyorum.. belki de bu yüzden,  s...', ARRAY['Türk Edebiyatı','Şiir','Orhan Onur']::text[], 8.5, '{"poet":"Orhan Onur","poet_slug":"orhan-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ey-gonul-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALNIZLIK', 'yalnizlik-orhan-onur-n671h', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'YALNIZLIK...

affedilir gibi değil yalnızlığım

sanki bela arayan bir serseri

ezeli kavgada belki hala sağım

bu içimdeki saklı umudun eseri

ha ben ha çöldeki kaktüs

yada ıssız bir ada ben

sanki dünyadaki her şey küs

fakat öbür taraf içinde erken

her yanımda sayamıyorum acılarımı

gökteki yıldızlar misali geceleyin

bu yalnızlığa ortak biri var mı

Allah aşkına yalvarırım söyleyin

                                          

03.02.1999/Devrek

ORHAN ONUR', 'YALNIZLIK... affedilir gibi değil yalnızlığım sanki bela arayan bir serseri ezeli kavgada belki hala sağım bu içimdeki saklı umudun eseri ha...', ARRAY['Türk Edebiyatı','Şiir','Orhan Onur']::text[], 8.5, '{"poet":"Orhan Onur","poet_slug":"orhan-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yalnizlik-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÖLÜM KALIM', 'olum-kalim-orhan-onur-3ka2s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ÖLÜM KALIM

Kapanır  gibi  perde  perde  gözkapaklarım

Ellerimde son  bulan belki birkaç  umut var

Ne yaşantım  ne  çocuklarım   ne  de  karım

Ufkuma dökülen koskoca bir boşluğum var

Acınıyorum  sanmayasın  sakın  ey  tanrım

Sinsice   çöküyor   üstüme    kara   bulutlar

Yeryüzü  diye  yolladığın  yer benim hanım

önümde  onca  şişe   elimde   kadehler  var

Yazgıma küskün kalmış gibi  tanıdıklarım

Çiçeği    böçeği   kurduna   kuşuna   kadar

Gözlerim gördükçe ağrımakta herbiryanım

Baktığım    anda    ötüyor   ecelime   radar

Yaşam harlaşıp gözlerime sinmiş  anladım

Her  vakit oradan  süzülüp  sağanak  yağar

Buysa   yaşam  anasını   avradını    satarım

Ki  kaybedeceğim şunun  şurasında  ne var

Cenneti de tasavvur edemez oldum kaldım

İçinde  güller  bülbüller  huri  başka ne var

Cennet dediğin  önce  yanıcığımda  sandım

Orayı  bilmem  amma  burada  sefiller  var

Yaşamıyorum    inanın    açım     açıktayım

Güya   burada   yaşadığını   sananlar   var

Ölümle    kalım    arasındaki    sapaktayım

Nasılsa   arayan   yok   beni   bulamasınlar

İçin   için    yanıyorum    ve    sayıklıyorum

Rüyamda gördüğüm yaşanılası bir yer var

Yoo, asla  hayır!  onları   hiç   istemiyorum

Zira    onlar    oranın    da   içine   sıçarlar

                                                             

Şu dünyada üçün  birinden başka  ne aldım

Yaşamda yaşamaktan gayrı ne ararsan  var

Vapur rıhtımında turnalarla bir ben kaldım

Cebimde  son  sefere   amade   bir  bilet  var

                                                                                                     

03.06.2000/Kütahya

ORHAN ONUR', 'ÖLÜM KALIM Kapanır  gibi  perde  perde  gözkapaklarım Ellerimde son  bulan belki birkaç  umut var Ne yaşantım  ne  çocuklarım   ne  de  karı...', ARRAY['Türk Edebiyatı','Şiir','Orhan Onur']::text[], 8.5, '{"poet":"Orhan Onur","poet_slug":"orhan-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/olum-kalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HEİDİ', 'hei-di-orhan-onur-7y3gw', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'HEİDİ

onüçünde ya vardım ya yoktum

ne yıllardı o yıllar hey gidi

yabanıl bir kısrak kadar toydum

ilklerimin aşkıydı düşlerimde Heidi

alplerin vadi yırtmacı eteklerinde

yaşayan bir ailenin küçük kızı idi

yemyeşil kırların tahtındaki ece

doğanın gülümseyen yüzüydü Heidi

en sevdiği kekti içinde karamela

hayvanların biricik dostu idi

bembeyaz elbisesinin yakasında kurdela

güzelliklerin atsız prensesiydi Heidi

kurak kalplere yağan bir yağmur

sevginin en rağbet gören geçidi

elinden birşey gelmediğinde mağdur

vasıflarının çok üstündeydi Heidi

çocuk kalmak isterdim an be an

beni ona bağlayan acaba neydi

en adamıl yıllarımdan bana beyan

kırmızı bültenle aradığım bir hayal Heidi

fısıltılarla konuşurken her gece rüyamda

kulağıma eğilip seni seviyorum derdi

gerçi o hala yaşar durur masallarda

bekle! bir gün seni gelip alacağım Heidi

                                                             

01.05.2000/Kütahya

ORHAN ONUR', 'HEİDİ onüçünde ya vardım ya yoktum ne yıllardı o yıllar hey gidi yabanıl bir kısrak kadar toydum ilklerimin aşkıydı düşlerimde Heidi alpleri...', ARRAY['Türk Edebiyatı','Şiir','Orhan Onur']::text[], 8.5, '{"poet":"Orhan Onur","poet_slug":"orhan-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/heidi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VERESİYE UMUT', 'veresi-ye-umut-orhan-onur-bqtxc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'VERESİYE UMUT

bu halin nedir

dudakların bir heceyi titrer gibi

söylemekten açiz

dişlerini görebiliyorum yanlız

arasında düş kırıntıları

içine her ne girdiyse

paragraf paragraf çıkıyor

giriş ve gelişme var

ama sonuçsuz

ve bakışların desen

yap-boz misali

parçaları birbirinden bağımsız                       

kekeme olmuşsun büsbütün

ve ellerin körkütük sarhoş

sende hayat yok besbelli

yüzün öylesine andırıyor ki

bir bakkalın buğusuz camını

‘umut kalmamıştır’

‘umut bulunmaz’

bende veresiye umut alacaktım

heya, umut alacaktım...

                                              

Mayıs’00/Kütahya

ORHAN ONUR', 'VERESİYE UMUT bu halin nedir dudakların bir heceyi titrer gibi söylemekten açiz dişlerini görebiliyorum yanlız arasında düş kırıntıları için...', ARRAY['Türk Edebiyatı','Şiir','Orhan Onur']::text[], 8.5, '{"poet":"Orhan Onur","poet_slug":"orhan-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/veresiye-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'VESTİYER', 'vesti-yer-orhan-onur-qcxa1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'VESTİYER

Olur olmadık her yerde

Bir vestiyer gibiyim

Önüne gelen

Hayallerini asıp gidiyor

Benimkiler altta kalmış

Boşversene

Ha altta

Ha üstte

Sonunda hepsi bir yerde

Takılıp kalmıyor mu? 

                                     

22.06.2000/Kütahya

ORHAN ONUR', 'VESTİYER Olur olmadık her yerde Bir vestiyer gibiyim Önüne gelen Hayallerini asıp gidiyor Benimkiler altta kalmış Boşversene Ha altta Ha üst...', ARRAY['Türk Edebiyatı','Şiir','Orhan Onur']::text[], 8.5, '{"poet":"Orhan Onur","poet_slug":"orhan-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/vestiyer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'KÜSTÜM', 'kustum-orhan-onur-q2thr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'KÜSTÜM

Küstüm

Yanlış anlama canım

Sana değil kastım

Umutlarımı süresiz 

Rafa kaldırdım

Belki arada bir

Tozunu alırım

01.09.2002/Devrek

ORHAN ONUR', 'KÜSTÜM Küstüm Yanlış anlama canım Sana değil kastım Umutlarımı süresiz  Rafa kaldırdım Belki arada bir Tozunu alırım 01.09.2002/Devrek ORHAN...', ARRAY['Türk Edebiyatı','Şiir','Orhan Onur']::text[], 8.5, '{"poet":"Orhan Onur","poet_slug":"orhan-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/kustum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'OLMAZ', 'olmaz-orhan-onur-asyjm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'OLMAZ

Ne desem az gelir

Ne kalbe sığarsın

Ne ömre

Ne düşlesem sığmaz

Dar gelir

Ne kadar sevsem az

Sevmesem olmaz

Sevgilim

Sadece sevişelim

Başka türlü olmaz

01.09.2002/Devrek

ORHAN ONUR', 'OLMAZ Ne desem az gelir Ne kalbe sığarsın Ne ömre Ne düşlesem sığmaz Dar gelir Ne kadar sevsem az Sevmesem olmaz Sevgilim Sadece sevişelim B...', ARRAY['Türk Edebiyatı','Şiir','Orhan Onur']::text[], 8.5, '{"poet":"Orhan Onur","poet_slug":"orhan-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olmaz-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DÜŞ, GERÇEK ve SEN', 'dus-gercek-ve-sen-orhan-onur-8cqmk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'DÜŞ, GERÇEK ve SEN...

-I-

Halet-i ruhiyemsin sevda çiçeği

Koklamaya ne hacet

Senden küçük bir parça yeter bana

Sensizliği aklamaya

Tanrım, n’olur kalbimi incelt

Ramak kalsın kopmaya

-2-

Belki düş gördüm sanırsın

Seni öyle muhteşem

Güzellikler içinde ışıltılı

Asıl düş gerçeği görsün

Seni öyle muhteşem 

Güzellikler içinde ışıltılı

-3-

bir avuca sığar mı ömür

ya sevda sığar mı ömre

zaman yüzünde asılı kalır

ölümsüz tebessümünle

ömrüme avuç avuç sevdan akar

sevdan sonsuza kadar

-4-

belki düş gördüm sanırsın

öylesine güzelsinki emsalsiz

sisler arasında esrarengiz

asıl düş gerçeği görsün

öylesine güzelsinki düşsüz

düş kadar yalan ve rütuşsuz

10.08.2002/Devrek

ORHAN ONUR', 'DÜŞ, GERÇEK ve SEN... -I- Halet-i ruhiyemsin sevda çiçeği Koklamaya ne hacet Senden küçük bir parça yeter bana Sensizliği aklamaya Tanrım, n...', ARRAY['Türk Edebiyatı','Şiir','Orhan Onur']::text[], 8.5, '{"poet":"Orhan Onur","poet_slug":"orhan-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/dus-gercek-ve-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İKİLEM', 'i-ki-lem-filiz-angay-90x56', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yüzlerde mutluluk maskesi, 

Yüreklerde boşluk, 

Günümüzdeki insan tiplemeleri...

Yalnızlık korkusu değil mi

Kangrene dönüşecek ilişkileri

Kesmeyi engelleyen

Ya da uzağı görme duyusunu

Kör eden...

Hastalıklı, saplantılı sevgi kırıntıları sunan

Klasik, sömürücü maskeyi takınanlarca

Kendini sömürten, 

Adına da vicdan yükümlülüğü diyen

Karşısına çıkan mantık ve duygu paylaşımından korkan

Ve ikileme düşenlere ne demeli? 

Hangisi daha güçsüz? 

Maskeli sömürücü mü, 

İkilemdeki sömürülen mi? 

Sömürücüye sömürecek vicdan saplantılı çok, 

Ama ikilemdeki, 

Kazanılabilecek körler, 

Gözlerine kataraktvari ikilem zarını çektikçe, 

Hiç göremeyecekler gökyüzündeki enginliği, 

Dalgalardaki yoğunluğu, 

Yeşildeki huzuru, 

Cıvıltılardaki sıcaklığı...', 'Yüzlerde mutluluk maskesi,  Yüreklerde boşluk,  Günümüzdeki insan tiplemeleri... Yalnızlık korkusu değil mi Kangrene dönüşecek ilişkileri Ke...', ARRAY['Türk Edebiyatı','Şiir','Filiz Angay']::text[], 8.5, '{"poet":"Filiz Angay","poet_slug":"filiz-angay","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ikilem-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömr-ü Heba', 'omr-u-heba-ahmet-yilmaz-01-kjh2h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Denizde giden kayık bir düz bir yan olur

Seviyorsa bir kişi yüreği büryan olur

Sakın gülme aşığa hem sen bilmezsin onu

Uyanıkken kişiye sevdiği ayan olur', 'Denizde giden kayık bir düz bir yan olur Seviyorsa bir kişi yüreği büryan olur Sakın gülme aşığa hem sen bilmezsin onu Uyanıkken kişiye sevd...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Yılmaz 01']::text[], 8.5, '{"poet":"Ahmet Yılmaz 01","poet_slug":"ahmet-yilmaz-01","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/omr-u-heba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nokta Koymuyorum Şiirlerime', 'nokta-koymuyorum-siirlerime-abdulkadir-paksoy-oqkgg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nokta koymuyorum şiirlerime 

Yoktur çünkü sona eren hiçbir şey bende 

Kimi yarım kalmıştır / aşklarım gibi

Kimi gündüz gibidir / her geceden sonra sürmekte', 'Nokta koymuyorum şiirlerime  Yoktur çünkü sona eren hiçbir şey bende  Kimi yarım kalmıştır / aşklarım gibi Kimi gündüz gibidir / her geceden...', ARRAY['Türk Edebiyatı','Şiir','Abdülkadir Paksoy']::text[], 8.5, '{"poet":"Abdülkadir Paksoy","poet_slug":"abdulkadir-paksoy","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/nokta-koymuyorum-siirlerime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıradan', 'siradan-osman-fatih-hfyvr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Git artık...

Arkana bakmadan, yolundan sapmadan git..

Ne bir an olsun duraksaycak, 

Ne de son bir bakış geçmişi umursayacak..

Değiştik artık, dedin ya değiştik, 

Sıcaklıklarımız sıradan gülüşlerimiz sıradan..

Herkes gibi olmak bir yana, 

Anılarımız sıradan, bakışlarımız sıradan...', 'Git artık... Arkana bakmadan, yolundan sapmadan git.. Ne bir an olsun duraksaycak,  Ne de son bir bakış geçmişi umursayacak.. Değiştik artık...', ARRAY['Türk Edebiyatı','Şiir','Osman Fatih']::text[], 8.5, '{"poet":"Osman Fatih","poet_slug":"osman-fatih","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/siradan-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pukiyi', 'pukiyi-sair-tanura-atjgb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Andğa si gdzi zade kay 

Mundeşkule aşo bozo vabdziyi

Tis nosi mamtu hekule 

Modvamulu çkimdekele 

Dağız paluyi yulun 

Çkimi bozo khavala modkulun 

Mana mdziyas gza iktiyups

Ardga ikhven eti komulun', 'Andğa si gdzi zade kay  Mundeşkule aşo bozo vabdziyi Tis nosi mamtu hekule  Modvamulu çkimdekele  Dağız paluyi yulun  Çkimi bozo khavala mod...', ARRAY['Türk Edebiyatı','Şiir','Şair Tanura']::text[], 8.5, '{"poet":"Şair Tanura","poet_slug":"sair-tanura","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/pukiyi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rabbim', 'rabbim-hayrettin-turk-oaglj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu ardına bakmadan giden güzel

Bir gün olurda ah etmezmi Rabbim

Goncayı dalından ayıran o el

Senin korkunla titremezmi Rabbim...

Ayaklar altındaki başlar kimin

Başlar üstündeki ayaklar kimin

Şu tahtta oturan sultanlar kimin

Bana sultan artık gelmezmi Rabbim...

Bir yabancıyım şu garib alemde

Bu çile, ızdırap bitmezmi Rabbim? 

Ölmeye mahkum olmuş son çaremde

Adın ile ölsem yetmezmi Rabbim...

DK

09.10.1995/Taşkent', 'Şu ardına bakmadan giden güzel Bir gün olurda ah etmezmi Rabbim Goncayı dalından ayıran o el Senin korkunla titremezmi Rabbim... Ayaklar alt...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/rabbim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damla', 'damla-hayrettin-turk-h0ub4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bazen akıllısın 

bazen deli

Sen delisin

ben zır deli...

Gene de 

takma kafana

kepten başka hiçbir şey

Şu zırtıllı dünyanın

zırtıllı delilerini düşün

Az yada çok

akıllı olduğunu anla...

Bırak rüzgarlarla savaşmayı

Bırak, dağıtsın saçlarını

Ağaçlar kuşlar alışmış

sende alışırsın

alışırsın zamanla...

Gökten düştü iki damla

bulutsuz bir havaydı

kimseler görmedi..

Damla damla 

can damla

Yağdınmı estinmi

masallar içindemiydin

kaf dağındamı

kimseler bilmedi...

Aysberglerden soğuksun

bazen güneşten sıcak

Sosyoloji iflas etti, 

batmakta felsefe

Mantık ölmekte bazen

bazen çorba

bazen pilav

Yemekten önce başka

sonra başka mantık

Esme

esme deli rüzgarlar gibi

karar ver

karar ver artık...

DK 

1995/Nevai

(Damla: Özbekçede öğretmen anlamına kullanılmakta olup, ''da-molla'' dan türemiştir)', 'Bazen akıllısın  bazen deli Sen delisin ben zır deli... Gene de  takma kafana kepten başka hiçbir şey Şu zırtıllı dünyanın zırtıllı delileri...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/damla-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Denizler Üstünde Ay', 'denizler-ustunde-ay-hayrettin-turk-m95gi', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bilirmisin

karanlık gecelerde

Ay doğar

denizler üstünde...

İşte o an sevgi

bir nefes kadar yakındır

işte o an! 

olmak yada olmamak

nefes almak yada almamak

yakalanmak ya da

dönüp gitmek

ciğerinde son nefesle...

Düşün ki, 

Atmosferi

tabiatı terkedip gitmektesin

Mum değilsin

pervane değilsin

Söyle niye

an be an

tükenmektesin...

Aç gözlerini

tatlı mahmurluğun kalsın 

ama uyan

Yeniden doğduğunu farzet

Hiç nefes almamış ciğerlerinle

Karanlık gecelerde

Ay doğarsa denizler üstünde

Gülümse tatlı tatlı

gülümse...

gülümse ve seyret...

DK

1995/Nevai', 'Bilirmisin karanlık gecelerde Ay doğar denizler üstünde... İşte o an sevgi bir nefes kadar yakındır işte o an!  olmak yada olmamak nefes alm...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Türk']::text[], 8.5, '{"poet":"Hayrettin Türk","poet_slug":"hayrettin-turk","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/denizler-ustunde-ay-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasımdı', 'kasimdi-hakan-yavuz-4boo5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kasımdı yapraklar ölmüştü

şehir sebepsiz bir uykuya dalmıştı

rüyasını yalnız ben görmüştüm

tüm korkusunu üstüme dökmüştü

kalbim yanmış ruhum sönmüştü

kasımdı, yanımda bir ben vardım

kasımdı yapraklar ölmüştü

şehir uykudan uyanmıştı

rüyası artık zihnimdeydi

gördüğüm en son perdeydi

bağırdım nefesim yetmiyordu 

kasımdı, yanımda bir ben vardım', 'kasımdı yapraklar ölmüştü şehir sebepsiz bir uykuya dalmıştı rüyasını yalnız ben görmüştüm tüm korkusunu üstüme dökmüştü kalbim yanmış ruhum...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yavuz']::text[], 8.5, '{"poet":"Hakan Yavuz","poet_slug":"hakan-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kasimdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pelin''e', 'pelin-e-hakan-yavuz-ehrrv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sen değil başkasıydı

benim sevdiğim pelin

ruhumun aynasıydı 

kalbimi yakan tenin

gözlerin olmasaydı 

uykular kadar derin

sen değil başkasıydı

benim sevdiğim pelin

herşey bir bir silindi

beynime yüklediğin

dudakların ellerin

o ateşten sözlerin 

yabancı bir fısıltı 

kulaklarımda sesin 

sen değil başkasıydı

benim sevdiğim pelin', 'sen değil başkasıydı benim sevdiğim pelin ruhumun aynasıydı  kalbimi yakan tenin gözlerin olmasaydı  uykular kadar derin sen değil başkasıyd...', ARRAY['Türk Edebiyatı','Şiir','Hakan Yavuz']::text[], 8.5, '{"poet":"Hakan Yavuz","poet_slug":"hakan-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/pelin-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DUYGUM', 'duygum-seref-kaya-0y46d', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Duyar yoklugunu biraz üsüse, 

Yanan elllerini arar ellerim.

Ne zaman icime kederdüsse, 

Dolanir boynuma sarar ellerin.

Gün olur avutur; beni yürekten, 

Kokular getirir bin bir cicekten.

Esma gözümde sudan, ekmekten, 

Öpüp oksamaya yarar ellerin.

                                                           seref kaya

Duyar cagirdigimi gelir gel desem, 

Tek tessellim olur kederli isem.

Inanmaz bir türlü ne kadar sevsem, 

Severmisin diye sor ellerim.

Hayaller güzeldir elemleri olmasa, 

Güller güzeldir dikenleri olmasa, 

Insanlar güzeldir yalanlari olmasa, 

Ask daha güzeldir, aldatilmak olmasa.

1971', 'Duyar yoklugunu biraz üsüse,  Yanan elllerini arar ellerim. Ne zaman icime kederdüsse,  Dolanir boynuma sarar ellerin. Gün olur avutur; beni...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/duygum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgede Kaldı', 'golgede-kaldi-aydin-bayrakdar-wlm4t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bülbülün sesine çok hasret çektim, 

Gelmedi bülbülüm, gölgede kaldı.

Rüşvet olsun diye bağa gül ektim, 

Nurdan koptu gülüm gölgede kaldı.

Bir aşk mağduruyum, böyleyim dedim, 

Onu kendime yar eyleyim dedim

Hoş bir aşk türküsü söyleyim dedim, 

Diyemedim dilim gölgede kaldı.

Hissimi kağıda zarfa dökerken, 

Sevda beni işkenceyle bükerken, 

Beden hasta idi, ayak sekerken

Gidemedim, yolum gölgede kaldı.

Son gölgeler aşka, sevdaya düştü, 

Lütuflar, umutlar havaya düştü

Kurduğum hayaller hep suya düştü, 

Yüzemedim salım gölgede kaldı.

Bu gölgeler bana çok oyun etti, 

Oyunun ardından direncim bitti, 

Sevgiler Aydın''ı ıssıza itti

Ruhum, tavrım, halim gölgede kaldı', 'Bülbülün sesine çok hasret çektim,  Gelmedi bülbülüm, gölgede kaldı. Rüşvet olsun diye bağa gül ektim,  Nurdan koptu gülüm gölgede kaldı. Bi...', ARRAY['Türk Edebiyatı','Şiir','Aydın Bayrakdar']::text[], 8.5, '{"poet":"Aydın Bayrakdar","poet_slug":"aydin-bayrakdar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/golgede-kaldi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapışkan Çamur', 'yapiskan-camur-i-hsan-uncuoglu-hvk0f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsan görünümlü o İnsan Çamur

Yanlış''sa İnsanoğlunu Dondurur, 

Kime verdin Ey Hüda! 

Bu sivri aklı dünyada

Yüzyıl sonra acabayı

Düşünür bak olacağa, 

***

Bomba uçak her silahınla 

Bu siyasetinle durma yaşa 

Kimsede hiç akıl yok korkma

Ebesi kör dünya dokunamaz sana,

***

Selam para  kelam para

Para yapışık çık duvara

Ye ye yetmiyor insanlara

Nekadar dolaşık bu dünya, 

***

Gel takıl bana bu neydir anla yaşa

Birlikleri parçala sonra ye tıka basa

Sevgi saygı say ney varsa namus ar

Dünyada ülkelerle oynayan insanlar 

Doğruları bilmez ki kendileri canavar! ,', 'İnsan görünümlü o İnsan Çamur Yanlış''sa İnsanoğlunu Dondurur,  Kime verdin Ey Hüda!  Bu sivri aklı dünyada Yüzyıl sonra acabayı Düşünür bak ...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yapiskan-camur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Gönül', 'ah-gonul-sezgin-keles-icyy6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ah gönül bu ne haşmetli zulümdür

Nasıl dayanırsın bu ızdıraba

Zulüm büyüdükçe ölümdür

Gönül kapılmıştır bir kez sevdaya', 'Ah gönül bu ne haşmetli zulümdür Nasıl dayanırsın bu ızdıraba Zulüm büyüdükçe ölümdür Gönül kapılmıştır bir kez sevdaya...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Keleş']::text[], 8.5, '{"poet":"Sezgin Keleş","poet_slug":"sezgin-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ah-gonul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Piyango', 'piyango-nafiz-sen-ith26', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Umut ile sarıldım sana 

Gelecek sağlayasın diye bana 

Bir damla su verdim 

Irmak ol içeyim kana kana 

Hayallerimi yelin aldı 

Umutlarım söndü karardı 

Verdiğim su damlası 

Buz oldu dona kaldı 

İlham saatim geçti, geldik sabaha 

Umudum kayboldu, uçtu aya 

Güneş doğdu, aydınlandı dünya 

Kahvaltıda kaldık bulanık bir çaya.', 'Umut ile sarıldım sana  Gelecek sağlayasın diye bana  Bir damla su verdim  Irmak ol içeyim kana kana  Hayallerimi yelin aldı  Umutlarım sönd...', ARRAY['Türk Edebiyatı','Şiir','Nafiz Şen']::text[], 8.5, '{"poet":"Nafiz Şen","poet_slug":"nafiz-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/piyango-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabahlara kadar konuşmak sevgiliyle', 'sabahlara-kadar-konusmak-sevgiliyle-sezgin-keles-jx4nr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine sen vardın aklımda

Sesini duymak için, 

Sabahlara kadar konuşmak için aramıştım

Telefonu hiç kapatmadan.

Aynı rüyayı görmek, 

Aynı güneşle uyanmak, 

Ve aynı gecede mehtaba bakmak için, 

Yanlızlığıma çare bulmak için, 

Seni unutamadığım için, 

Sesine, tenine ve nefesine dayanamadığım için, 

Aramıştım ben seni

Telefonu hiç kapatma

Sevgilim ne olur beni anla! 

Herşeyimi vermiştim ben sana...', 'Yine sen vardın aklımda Sesini duymak için,  Sabahlara kadar konuşmak için aramıştım Telefonu hiç kapatmadan. Aynı rüyayı görmek,  Aynı güne...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Keleş']::text[], 8.5, '{"poet":"Sezgin Keleş","poet_slug":"sezgin-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sabahlara-kadar-konusmak-sevgiliyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'TÜRK''ÜM DİYENE', 'turk-um-di-yene-nafiz-sen-hrvnm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Türk''üm 

''Ne mutlu Türk''üm diyene'' 

Atatürk veczeyledi aslını 

bilene 

Ne söylemeli bilmiyorum 

Hayalimdeki Türk''lüğü silene 

Doğruyum 

Sözde doğruluğu paylaşamayana 

Dürüst insanla kaynaşamayana 

Ne söylemeli bilmiyorum 

Haklı olan ile anlaşamayana 

Çalışkanım 

Çalışkanım diyerek övünene 

Hazıra konmaktan sövülene 

Ne söylemeli bilmiyorum 

Özünü kaybedip dövünene 

Yasam 

Kızdık kanun nizam düzenleyene 

Üzüldük adaletsizlikten inleyene 

Ne söylemeli bilmiyorum 

Yasağı yasayı çiğneyene 

Küçüklerim 

Bunları söyleyerek büyüttük 

Doğruluk ninnileriyle uyuttuk 

Ne söylemeli bilmiyorum 

Geleceğe böyle bir ışık tuttuk', 'Türk''üm  ''Ne mutlu Türk''üm diyene''  Atatürk veczeyledi aslını  bilene  Ne söylemeli bilmiyorum  Hayalimdeki Türk''lüğü silene  Doğruyum  Sözd...', ARRAY['Türk Edebiyatı','Şiir','Nafiz Şen']::text[], 8.5, '{"poet":"Nafiz Şen","poet_slug":"nafiz-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/turk-um-diyene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağaç', 'agac-nafiz-sen-3mnzs', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağaçla konuşurum 

Taşla, toprakla konuşurum 

Onlarla anlaşabiliyorum 

İnsanlara küsüm ben 

Yeller sallasın yapraklarını 

Seller sürüklemesin topraklarını 

Başın göğe değsin 

Köklerin yerden kopmasın', 'Ağaçla konuşurum  Taşla, toprakla konuşurum  Onlarla anlaşabiliyorum  İnsanlara küsüm ben  Yeller sallasın yapraklarını  Seller sürüklemesin...', ARRAY['Türk Edebiyatı','Şiir','Nafiz Şen']::text[], 8.5, '{"poet":"Nafiz Şen","poet_slug":"nafiz-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/agac-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Aşkı', 'bahar-aski-nafiz-sen-etlcs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kış bitip bahara erince havalar durulmuş 

Bir zerdali çiçeği badem çiçegine vurulmuş 

İçin için bu umutsuz aşk ile üzülürmüş 

Aşkının bütün gözyaşıyla bahara süzülürmüş 

Olmaz olmaz umutsuz bir aşk bu ya 

Oradan geçen bir arı bu sevdayı duya 

Zerdali çiçeği arıya bütün içtenliği ile açılmış 

Aşkının tozları her yere buram buram saçılmış 

Arı bu aşk-ı ilanı badem çiçeğine götürmüş 

Badem çiçeğinin aşk nağmelerini geri getirmiş 

Zerdali çiçeği ile badem çiçeği murat almış 

Bu aşkın meyvesi insanoğluna sunulan balmış 

Yıllarca açmış çiçeklerini zerdali ile badem 

Bulmuş o bahçede cenneti Havva ile Adem.', 'Kış bitip bahara erince havalar durulmuş  Bir zerdali çiçeği badem çiçegine vurulmuş  İçin için bu umutsuz aşk ile üzülürmüş  Aşkının bütün ...', ARRAY['Türk Edebiyatı','Şiir','Nafiz Şen']::text[], 8.5, '{"poet":"Nafiz Şen","poet_slug":"nafiz-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bahar-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erkekler Ağlamaz', 'erkekler-aglamaz-nafiz-sen-smt7p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Soruyorsun be güzelim, erkekler ağlamaz mı? 

Kalp burkulmaz mı, görünce göz yaşını? 

Düşünce od yüreğe, yüreği dağlamaz mı? 

Dert girince sineye, akıl alır gider başını. 

Sanma, ağlamak erkeğe acizliğin bir ifadesi 

Çektiği her acının bütün cefası 

Akıtır gözyaşlarını damla damla kalbine 

Duyulmasa da açıktan açığa ağlama sesi', 'Soruyorsun be güzelim, erkekler ağlamaz mı?  Kalp burkulmaz mı, görünce göz yaşını?  Düşünce od yüreğe, yüreği dağlamaz mı?  Dert girince si...', ARRAY['Türk Edebiyatı','Şiir','Nafiz Şen']::text[], 8.5, '{"poet":"Nafiz Şen","poet_slug":"nafiz-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/erkekler-aglamaz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BAHT', 'baht-nafiz-sen-psaoq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hey! Yağmur içmiş, sarhoş bulutlar 

Çarpışın, çaksın şimşekler 

Çarpsın kalbime, parçalansın cam kırıkları gibi 

Baldıran acısı almış yüreğim yanıyor. 

Hey! çılgın deli dalgalar 

Şaklasın bagrımda darbelerin 

Sarsın bütün bedenimdeki alevi. 

Bana göz kırpan yakamozlar 

Beni kandırdınız karşılıksız bir aşkla. 

Yalan mı söyledin, yüzüme gülerek dolunay? 

Hey! baht açıklığı dileyen parlak yıldızlar 

Kuyruklu yalan söyleyerek kayıyorsunuz birer birer. 

Dörtnala koşan azgın atlar, 

Alın beni, götürün uzak diyarlara 

Mutluluklar ülkesine, rüyalar diyarına. 

Gülsün artık şu kara bahtım.', 'Hey! Yağmur içmiş, sarhoş bulutlar  Çarpışın, çaksın şimşekler  Çarpsın kalbime, parçalansın cam kırıkları gibi  Baldıran acısı almış yüreği...', ARRAY['Türk Edebiyatı','Şiir','Nafiz Şen']::text[], 8.5, '{"poet":"Nafiz Şen","poet_slug":"nafiz-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/baht-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BENİM MEMLEKETİM', 'beni-m-memleketi-m-nafiz-sen-sk3gx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Baharda çiğdem tarlasıdır, bütün dağı düzü 

Meyve bahçesi, üzüm bağıdır deresi özü 

Dört mevsimi: kışı, ilkbaharı, yazı, güzü 

Daima güzeldir, benim memleketim. 

Kangal, geven, sığırkuyruğu, kekikli dağlarında 

Ala karga, keklik, bülbül öter bağlarında 

Kuzu otlatırdım çocukluk çağlarında 

Hayalimdedir daima, benim memleketim. 

Her deresinden bir pınar, bir çeşme akar 

Mor sümbülleri, gelincikleri birbirine bakar 

Yaz sıcakları cayır cayır sinemi yakar 

Dost gibi sıcaktır, benim memleketim. 

Ekmek kavgası herkes şehre gitti 

Kalmadı kimseler sıcak ilişkiler bitti 

Kayboldu bütün anılar, od ocak yitti 

Issızdır şimdi, benim memleketim. 

Yıllarca memleketi anılarımda özlerim. 

Hasretini, gönül ocağımda közlerim 

Onu göreceğim günleri heyecanla gözlerim 

Anılarımda güzeldir, benim memleketim.', 'Baharda çiğdem tarlasıdır, bütün dağı düzü  Meyve bahçesi, üzüm bağıdır deresi özü  Dört mevsimi: kışı, ilkbaharı, yazı, güzü  Daima güzeldi...', ARRAY['Türk Edebiyatı','Şiir','Nafiz Şen']::text[], 8.5, '{"poet":"Nafiz Şen","poet_slug":"nafiz-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/benim-memleketim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SANAT', 'sanat-nafiz-sen-c7q87', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eldeki maharetin, gözdeki güzelliğin 

O eşsiz sırrın adı sanat olmuş 

Masmavi, sonsuz göklerde uçmanın 

Sırrı, bir çift kanat olmuş 

Sonsuz arzuların, isteklerin bitimi 

Sınırsız bir kanaat olmuş 

İktidarda mezara dek kalmanın adı 

Ne yazık doyumsuz bir saltanat olmuş 

Amaçsız boşu boşuna direnmenin 

Adı şanssızlık bu ya inat olmuş 

Kötülüklerin, musibetin, şerrin anası 

O iblisin adı sonunda lanet olmuş 

Ne yazık ki hırsızlığın adı dahi 

Medeni çağımızda zanaat olmuş 

Ruhtaki güzelliğin, gözdeki nurun 

En güzeli, o eşsiz sırrın adı sanat olmuş', 'Eldeki maharetin, gözdeki güzelliğin  O eşsiz sırrın adı sanat olmuş  Masmavi, sonsuz göklerde uçmanın  Sırrı, bir çift kanat olmuş  Sonsuz ...', ARRAY['Türk Edebiyatı','Şiir','Nafiz Şen']::text[], 8.5, '{"poet":"Nafiz Şen","poet_slug":"nafiz-sen","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sanat-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep gözlerimize bakarak öldük', 'hep-gozlerimize-bakarak-olduk-seckin-cingoz-smbqi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hep gözlerimize bakarak öldük

sanki bir zevk sarnıçında doğmuş gibi

her şeyin yeniden doğduğunu görmüşçesine

öylesine bir yaşam ki 

taşı kıskanan ses

bizlere eşlik ederdi o şarkılarda..

Ah o parlayan ışık

dostumsun yani, 

kal benimle 

ağla bu akşam derdime, gördüklerime

bilesin bu akşam 

sadece sen dınleyecek

ben anlatacağım', 'Hep gözlerimize bakarak öldük sanki bir zevk sarnıçında doğmuş gibi her şeyin yeniden doğduğunu görmüşçesine öylesine bir yaşam ki  taşı kıs...', ARRAY['Türk Edebiyatı','Şiir','Seçkin Cingöz']::text[], 8.5, '{"poet":"Seçkin Cingöz","poet_slug":"seckin-cingoz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hep-gozlerimize-bakarak-olduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'HATIRLA BENİ HAYAT', 'hatirla-beni-hayat-sair-khan-oh9ut', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Önce güneş kaybolmaya başladı, deniz coştu martılar sustu, 

Kara bulutlar yoğunlaştı hızlıca geldi güneşi yuttu, 

Kader denilen ince ama çok acı çizgi yüz hatları ile buluştu

İşte başladı yağmur denen rahmet, gökyüzü ile gözler de coştu

Ağla utanma dostum ağla sana başka şans kalmadı ki

Hayata dair attığın her zar geldiyse hep yek senin suçun yok

Sana bakan o pırıltı gözler artık düşman olmuşsa yapacak bir şey yok

Üzülme hep aynı durum ”Hatırlamadı yine beni Hayat”

Hatırlar mısın ufak bir çocuktun mahallenin çamurlu yollarında oynayan, 

Hastalıktan sararmış benzinle gizlice koşmaya çalışır da beceremezdin, 

Annen hep seni gizlice camdan kontrol ederdi yaşlı gözlerle

Sanki bir anda onu terk etmeye hazırlanıyormuşsun gibi

Yüzünde çamurun yanı sıra hep bir boş bakan gözlere sahiptin

Sanki biliyordun büyüme sevdası ile gelecek o kara günleri

Bir yok oluş destanında hep ama hep başrol oynayacağını

Hani çamura saplayarak oynadığın çivi oyunundaki gibi

Saplanacak olan yüreğine kirli sevdaları, hataları günahları biliyormuş gibi

Uzun lafı kısası “Hatırlamadı yine Hayat“

Bazen yakaladım diye sevinerek kucaklanan mutluluk salkımları diken tarlası çıkar

Özenle kesilmiş gülün dikeni sadece hatırını sorar, 

Yakaladım derken sevda trenini bir bakarsın dudakta solar

Bir bakmışsın sana verilen sadece o trenin kara kalın isi değer

Bazen anılara en çok yakışan elbise birkaç damla gözyaşı olmuşsa eğer

Boş veremezsin yalvarırsın ona ne olur ”Hatırla hayat hatırla beni”

KHAN

17/03/2003', 'Önce güneş kaybolmaya başladı, deniz coştu martılar sustu,  Kara bulutlar yoğunlaştı hızlıca geldi güneşi yuttu,  Kader denilen ince ama çok...', ARRAY['Türk Edebiyatı','Şiir','Şair Khan']::text[], 8.5, '{"poet":"Şair Khan","poet_slug":"sair-khan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hatirla-beni-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-mustafa-uyar-9jprn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gurbeti ben zor bilirdim

Gurbet zordan öte imiş, 

Sineleri yakar derdim

Gurbet kordan öte imiş.', 'Gurbeti ben zor bilirdim Gurbet zordan öte imiş,  Sineleri yakar derdim Gurbet kordan öte imiş....', ARRAY['Türk Edebiyatı','Şiir','Mustafa Uyar']::text[], 8.5, '{"poet":"Mustafa Uyar","poet_slug":"mustafa-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hasret-99-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Gidiyorum', 'ben-gidiyorum-atila-gunal-4nn6t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yolları devriyeler kesmiş

Aman vermezler kaçana bilirim

Sevdadan kaçanın cezası idammış

Kulda affetmezmiş, tanrı da

Kar boran olsa dinlemez aşardım

Sana gelen yolları.

Yağlı kurşunlarla bezemişler

Yine de engel değildi de bana

Kara haberin geldi ben sana varamadan.

Duydum ki başkalarının olmuşsun

Bende ki bu sevdaya kurşun bile işlemezdi de

Ellerin olmuşsun ya, 

Zayıf düştü bedenim

Attığın ok deldi de geçti

Karanlıklar içinde kalıverdim

Temmuz ateşiyle yanarken 

Yüreğim, bedenim

Bir bahar yeli gibi

Değdin de geçiverdin.

Ben gidiyorum sensizliğe

Mekanım cennet olsa neye yarar

İçinde sen yoksan

Okun yüreğimi deldi geçti

Zebaniler sorsa cevabım kalmadı artık

2003-03-17', 'Yolları devriyeler kesmiş Aman vermezler kaçana bilirim Sevdadan kaçanın cezası idammış Kulda affetmezmiş, tanrı da Kar boran olsa dinlemez ...', ARRAY['Türk Edebiyatı','Şiir','Atila Günal']::text[], 8.5, '{"poet":"Atila Günal","poet_slug":"atila-gunal","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ben-gidiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Nesin', 'sen-nesin-ferhat-sener-025c0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen sevilecek

Rüyalara düşüncelere girip

İnsanı deli edecek

kadar güzelsin.

Söyle yoksa bir peri misin? 

Ruhta arzular uyandıracak

İnsanın dikkatini üzerinde toplayacak

Düşünceleri zorlayacak

Kadar güzelsin.

Söyle bir melek misin? 

Sanki dopdoluyum seninle

Ama sen...

Bilmiyorsun bilemezsin de.

Söyleyeyim mi nesin? 

Kalbimde taht kuran prensesimsin! ...', 'Sen sevilecek Rüyalara düşüncelere girip İnsanı deli edecek kadar güzelsin. Söyle yoksa bir peri misin?  Ruhta arzular uyandıracak İnsanın d...', ARRAY['Türk Edebiyatı','Şiir','Ferhat Şener']::text[], 8.5, '{"poet":"Ferhat Şener","poet_slug":"ferhat-sener","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sen-nesin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülümseme', 'gulumseme-abdulhamit-bayer-r0x34', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gökyüzü

O gün tek isteğim gökyüzünü, 

görmekti.

Ama öyle olmadı.

Olması da gerekmezdi, 

Bulutlar kaplamıştı 

Onlarda gökyüzüne aitti

ve beyaz değildiler.

Belki mutluluğa kavuşçaklardı.

Ben mi? 

Yanlızca baktım, 

Yağmurun yağmasını bekledim

Soğuk kış gününde 

ardındaki berrak gökyüzüne

bakmak 

uzakları görmek için

Biliyor musun, 

Seni de özledim......', 'Gökyüzü O gün tek isteğim gökyüzünü,  görmekti. Ama öyle olmadı. Olması da gerekmezdi,  Bulutlar kaplamıştı  Onlarda gökyüzüne aitti ve beya...', ARRAY['Türk Edebiyatı','Şiir','Abdulhamit Bayer']::text[], 8.5, '{"poet":"Abdulhamit Bayer","poet_slug":"abdulhamit-bayer","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gulumseme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökyüzü', 'gokyuzu-abdulhamit-bayer-6imkj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gökyüzü

O gün tek isteğim gökyüzünü, 

görmekti.

Ama öyle olmadı.

Olması da gerekmezdi, 

Bulutlar kaplamıştı 

Onlarda gökyüzüne aitti

ve beyaz değildiler.

