INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Savaş', 'savas-musa-tektas-18ikc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SAVAŞ 

İkibin üç yılı yirmi Mart’ında

Soğuk savaş birden sıcağa döndü.

Orta doğu alev alev yanıyor

Yer-gök ateş dolu ocağa döndü.

Bağdat, nurlu şehir veliler yurdu

Dicle’nin suyuyla meyveler verdi

Şimdi ehl-i salip seni mi vurdu

Feza çağı zâlim bir çağa döndü.

Muharrem ayında Kerbelâ kanda

Ehl-i beyti Resul yüce mekânda

Burya bomba atıp, kurşun sıkanda

Yezid gibi edna alçağa döndü.

İmam-ı A’zamın ruhu ayakta

Şeyhi Geylani’nin elleri okta

Germiştir yayını şöyle bir bakta

Roketler, füzeler uçağa döndü

Manevi bir el var Bağdat üstünde

İşaret Dicle’yle Fırat üstünde

Muhkem bina olmaz feryat üstünde

Hürriyet kesmeyen bıçağa döndü

Çünkü; müslümana kılıç vuranlar

“Özgürlük! ” adına düzen kuranlar

Çifte standarla hüküm sürenler

Âdelet bâbında kaçağa döndü

Hilâlin gücüne güç kat Ya Rabbi

Mü’mine ihsan et nusret Ya Rabbi

Türkiyem görmesin zillet Ya Rabbi

Tektaş’ım dâneler burçağa döndü.

			21.03.2003, Darende

			Musa TEKTAŞ', 'SAVAŞ  İkibin üç yılı yirmi Mart’ında Soğuk savaş birden sıcağa döndü. Orta doğu alev alev yanıyor Yer-gök ateş dolu ocağa döndü. Bağdat, nu...', ARRAY['Türk Edebiyatı','Şiir','Musa Tektaş']::text[], 8.5, '{"poet":"Musa Tektaş","poet_slug":"musa-tektas","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/savas-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİTMEYECEK SEVGİMİZ', 'bi-tmeyecek-sevgi-mi-z-caglar-akarsu-dcxn4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'BİTMEYECEK SEVGİMİZ

.....

Milletleri ayakta tutan değerler vardır, 

Halkı ile bütünleşirken, her sabah yeniden doğar, 

Vatan ise kutsal bir emanettir, 

Tarihsel ruhumuzu, geleceklere taşır, 

Tan yeri ağarırken, semalarımızda, 

Yurdumun üzerinde dalgalanan, 

Sancakların altında yaşadık, 

Ulusal törelerimiz, kutsal davamız oldu, 

Asker ocakları, ”din”ile bütünleşirken, 

Giden her delikanlının arkasından, 

Şehitlik ve gazilik makamlarında, 

Dualarımızla yolcu ettik..

Şimdi sömürü içinde kalmış, 

İnsanlık ayıplarını gördükçe, 

Meyhane sofralarında, bayraklar, 

Çığırından çıkmış insanların, sözünde

Sadistçe  emellerine alet olur, 

......

Sırtımızda taşıdık, emanetleri yere değirmeden, 

Vatansız kalmış insanlar, biliyorlardı, 

Gurbet yollarında çektikleri çileyi, 

Öz yurtlarında yaşayanlar ise, 

Sahipsiz kalmış atlar gibi, tepişiyorlardı, 

Şimdi, içini yemiş boş bir ağaç gibi, 

Orta yerde kalmış bir zavallıyız, 

......

Vatan, bayrak, sevgisini arıyoruz, 

Buz tutmuş yüreklerimizde, 

Sancakların kırmızı rengi, 

Hilal ve yıldızın beyazı, 

Her yeni günle birlikte, 

Bizde yeniden doğmasını bekliyor

.....', 'BİTMEYECEK SEVGİMİZ ..... Milletleri ayakta tutan değerler vardır,  Halkı ile bütünleşirken, her sabah yeniden doğar,  Vatan ise kutsal bir ...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bitmeyecek-sevgimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'icime dert oldu', 'icime-dert-oldu-dilek-ve-burhan-kardesler-72vf1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'icime dert oldu 

hosgeldin diyipte sarilamadim, 

omuzuna yaslanip agliyamadim, 

sevmiyorum derken seni aldattim, 

icime dert oldu nasil yanildim, 

kimbilr bir daha gelecek misin, 

bana yeni bir sans vecek misin, 

unutamadim canim diyecek misin, 

icime dert oldu donecek misin, 

verdigin o resmi sakliyamadim, 

senden kalanlarin hepsini yaktim, 

seviyorum derdin inanamazdim, 

icime dert oldu nasil yanildim,', 'icime dert oldu  hosgeldin diyipte sarilamadim,  omuzuna yaslanip agliyamadim,  sevmiyorum derken seni aldattim,  icime dert oldu nasil yani...', ARRAY['Türk Edebiyatı','Şiir','Dilek Ve Burhan Kardesler']::text[], 8.5, '{"poet":"Dilek Ve Burhan Kardesler","poet_slug":"dilek-ve-burhan-kardesler","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/icime-dert-oldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Dergahı', 'gonul-dergahi-haci-ozturk-2kilj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kırk  yıllık  ömrümün  son  baharında, 

Birgün  olsun  boş  kalmadı  gönül  dergahı..! 

Acı  tatlı  günlerle   geçen  bu  handa, 

Kimseye  eyvallah  etmedi  gönül  dergahı.

Mutluluğu  aramaktan  hiç  yorulmadı, 

Sevgi  için  çağladıda  hiç  durulmadı, 

Çiğnediler  gururunu   hiç   kırılmadı, 

Kimseye  incinmedi  gönül  dergahı.

Ne  bulduysa  onunla  yetindi  durdu, 

Her  zaman garibin, yetimin  halını  sordu, 

Kendi  yaralarını   hep  kendisi   sardı, 

Kimseye  kul, köle  olmadı  gönül  dergahı.

Can  cana  yakındır, canda  canana, 

Yalanla  doğruyu getirsen durmaz  yanyana, 

Bu  günü   yaşarız  senedimiz yok  ki yarına, 

''Hacı''ya  rehber  oldu   GÖNÜL  DERGAHI......

Hacı  Öztürk                         LİBYA  /14-09-2001

KAYDEDEN                         Hacı  Öztürk', 'Kırk  yıllık  ömrümün  son  baharında,  Birgün  olsun  boş  kalmadı  gönül  dergahı..!  Acı  tatlı  günlerle   geçen  bu  handa,  Kimseye  e...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gonul-dergahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Engel Olmayın', 'engel-olmayin-haci-ozturk-pxdm2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yol  verdim  hasrete  gider  sahraya, 

Engel  olmayın  engel  olur  mu yollar,,? 

Bir  damla  mutluluğu  çok  görmen  bana, 

Engel  olmayın  engel  olur mu  çöller,,? 

Yıldızlarla  arkadaş  olurum  her gece, 

Kulak  kesilirim   sıladan  gelecek  sese, 

Dilimden  düşmeyen  mısra mısra  hece hece, 

Engel  olmayın  engel  olur mu  türküler,,,? 

Bir  ummansınız size  erişemem ki,,! 

Bir  umut  peşindeyim  yetişemem  ki,,! 

Narindir  gönüller kırılsa  sevinemem  ki,,! 

Engel  olmayın  engel  olur mu  sözler,,? 

Nefesimsiniz   sizlerle  yaşamam  için, 

Gurbeti  seçimim  bir  yuva  almak  için, 

''Hacım,, der gurbette  dost  bulmak  için, 

Engel  olmayın  engel  olur mu  diller,,? 

Hacı  Öztürk                      LİBYA  /27-09-2001

KAYDEDEN                     Hacı    Öztürk', 'Yol  verdim  hasrete  gider  sahraya,  Engel  olmayın  engel  olur  mu yollar,,?  Bir  damla  mutluluğu  çok  görmen  bana,  Engel  olmayın ...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/engel-olmayin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir daha', 'bir-daha-haci-ozturk-qlwzf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güzelim  bu  kadar  üzme  kendini,, 

Gelirsem  sılaya  dönmem  bir  daha.

Gün  olur  aşarsam şu  AKDENİZİ,, 

Gelirsem  sılaya  dönmem  bir  daha.

Anladım ki  ayrılık bu  kadar  zormuş, 

Geçen  günlere  bak  yedi  ay olmuş, 

Demek  hasret, özlem  gurbet  buymuş, 

Gelirsem  sılaya  dönmem  bir  daha.

Ahtım  var geçeceğim yolumda  çöl  olsan, 

Durdurmak  için  sahradan esen  yel  olsan, 

Umut  zincirlerini  birer, birer  kırarasam, 

Gelirsem  sılaya  dönmem  bir  daha.

''Hacım,, der  sözlerimi  atma  yabana, 

Dünya  malı  olsa  güvenme  babana, 

Ya öyle, ya  böyle  döneceğim  vatana, 

Gelirsem   sılaya  dönmem  bir  daha...

Hacı   Öztürk                   LİBYA /03-10-2001

KAYDEDEN                    Hacı   Öztürk', 'Güzelim  bu  kadar  üzme  kendini,,  Gelirsem  sılaya  dönmem  bir  daha. Gün  olur  aşarsam şu  AKDENİZİ,,  Gelirsem  sılaya  dönmem  bir  ...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-daha-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saz', 'saz-i-hsan-uncuoglu-ibg7n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Saz

Aşk ile meşkte zamanım

Türküm idin nazlı sazım

Bana düz ova''lar atlattın

Dünyamı boşa harcadım, 

***

Nefes nefese baktım giden zamana

Ne kadar çabuk kaçtı ellerimden hızla 

Boşa harcamışım seni rüyada yalanda

Anlarmıydım geçtiğini elde avuçta olsa

O terane ne hatıra gerilere dönüp bakınca, 

***

Parçalara ayır, böl istediğin tarzda ye, yenir 

Top bomba at patlat dünya kadar çal semir

Rakkamlar bir kağıt ta biraraya gelir getirilir

Harfler düzen olunca meydana bir anlam gelir

Saz, söz kelam anlarsa anında bana selam verir,', 'Saz Aşk ile meşkte zamanım Türküm idin nazlı sazım Bana düz ova''lar atlattın Dünyamı boşa harcadım,  *** Nefes nefese baktım giden zamana Ne...', ARRAY['Türk Edebiyatı','Şiir','İhsan Uncuoğlu']::text[], 8.5, '{"poet":"İhsan Uncuoğlu","poet_slug":"i-hsan-uncuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/saz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Yağmuru', 'gul-yagmuru-kamil-colak-a4s63', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'gül yağmuru içmeye geldim

keskin akreplerin zehrinden korunayım diye

bana eğik bir hançer kaldı

öldürmem için, her şeyi

sesler birlik oldu, gök derinliklerinde

yağmurlar yağdı yağmurlar yağdı

yeşerten yağmurlar yağdı

bu yağmurlar bana ve size yağdı

gülü yazdığımdan bu yana

yağmurlar yağdı yağmurlar yağdı

bu yağmurlar bana ve size yağdı

sesler birlik oldu gök derinliklerinde

yağmurlar yağdı yağmurlar yağdı

bu yağmurlar bana ve size yağdı

ben çocukluğum da 

kırmızı güller kazırdım bileklerime

sonra ay ışığında tütsülenirdik gül ile

ve bir güz bahçesinde yağmur suları içerdik

yumuşacık yıldızlar takarak saçlarımıza

yağmurlar yağdı yağmurlar yağdı

kırmızı yağmurlar yağdı', 'gül yağmuru içmeye geldim keskin akreplerin zehrinden korunayım diye bana eğik bir hançer kaldı öldürmem için, her şeyi sesler birlik oldu, ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Çolak']::text[], 8.5, '{"poet":"Kamil Çolak","poet_slug":"kamil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gul-yagmuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serçe Ve Bahar', 'serce-ve-bahar-kamil-colak-s39nt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'nev-baharda saçlarına yuva yapsın turnalar

sırtımızı ısıtan güneş 

her sabah gülsün göğsümüzde

ıssız bir koyda yıkanan yaralı serçem

sedef gaganı yakma bahtına

sevdanı ülkesine sürüklüyor acı fırtanalar

uykularımızı serinleten meltemler ölüyor

yaralı serçem, 

bir tümsek diz vurmamızı bekliyor

serçem serçem geliyor nev-baharın muştusu

tüylerin allı pulludur

sularda kıpraşan renklerin bellidir

konuş bana da gönlüm tazelensin

eğil kulağıma, gözlerime bir söz yaz

yaz ki serçem, bu söz nev-bahar olsun', 'nev-baharda saçlarına yuva yapsın turnalar sırtımızı ısıtan güneş  her sabah gülsün göğsümüzde ıssız bir koyda yıkanan yaralı serçem sedef g...', ARRAY['Türk Edebiyatı','Şiir','Kamil Çolak']::text[], 8.5, '{"poet":"Kamil Çolak","poet_slug":"kamil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/serce-ve-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MESCİD-İ AKSA', 'mesci-d-i-aksa-kamil-colak-o1ga3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'mescid-i aksa kâkülünde  sitem 

ezanlar susmuş yitirilmiş Kudüs

şahadet parmağı giymiş hüzünden pelerin 

kapkara bulutlarda gelmez baharın

bir gül tomurcuğu acınca geceleyin

dokunuyor yanaklarına sükutun sabahı

kelebeklerin uçmaz olduğu yörelerinden

eşiğine akıyor şimdi küfrün karanlığı

biliriz sendeydi bir zamanlar müminler saf saf

şimdi ejderler solur o mahzun halini

bu diyarın tek eşiydin

cevaba erişen ilk kıplesiydin nebinin

sana gelsem bir şafak meltemiyle

damarından içsem sıcak kanını

başım alsa da başını düşerek eteklerine

göklerim yitiktir benim ya leyl

Mescid-i aksam küsülüdür benim', 'mescid-i aksa kâkülünde  sitem  ezanlar susmuş yitirilmiş Kudüs şahadet parmağı giymiş hüzünden pelerin  kapkara bulutlarda gelmez baharın b...', ARRAY['Türk Edebiyatı','Şiir','Kamil Çolak']::text[], 8.5, '{"poet":"Kamil Çolak","poet_slug":"kamil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mescid-i-aksa-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Yağmuru', 'hasret-yagmuru-haci-ozturk-abs7o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine  kara  bulutlar  sardı  burayı, 

Belli ki yağacak  hasret  yağmuru.

Düştüm  bir  ummana  göremem  karayı, 

Belli ki  yağacak   hasret   yağmuru.

Kara  toprak   suya  özlem  duyarken, 

Günleri  üst üste  koyup  aylar  sayarken, 

Gün  ağarıp  güneş  doğacak  derken, 

Belli ki  yağacak   hasret   yağmuru..

Şafakla   çöker  bir  sis  bir  duman, 

Sabahın   altısıydı   koptu  bir  tufan, 

İçimde  hasret  fırtınası  koparken, 

Belli ki  yağacak  hasret  yağmuru.

Bir  hüzün  çöker üstüme böyle  günlerde, 

Hiç  bir  arzum yoktur   geçen  günlerde, 

''Hacım,, der ki  beni  beklediğiniz  yerde, 

Bilmem ki  yağar mı  hasret  yağmuru.

Hacı   Öztürk                     LİBYA /30-10-2001

KAYDEDEN                     Hacı  Öztürk', 'Yine  kara  bulutlar  sardı  burayı,  Belli ki yağacak  hasret  yağmuru. Düştüm  bir  ummana  göremem  karayı,  Belli ki  yağacak   hasret  ...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/hasret-yagmuru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Kuşları', 'yagmur-kuslari-haci-ozturk-lmhv8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilmem  hangi  illerden  gelirsiniz, 

Selam  sabah  yok mu  yağmur  kuşları,? 

Öyle  hasret  dulu ki bilseniz  sesiniz, 

Mutlusunuz  yinede  yağmur  kuşları, 

Gurbette  aylardır  neşemiz  yoktur,,! 

İzinciler  gider gelir  sıramız  yoktur,,! 

Sizin  gibi  serbest  uçmamız  yoktur,,! 

Mahkumuz  buraya  yağmur  kuşları.

Siz  şakıdıkça  sessiz, sessiz  ağlarım, 

Dumanım  tütmez ta içimden  yanarım, 

Aklıma  geldikçe canları mı anarım, 

Şu  an  yastayım  yağmur  kuşları.

Sizin  kadar  özğürlüğüm  olmasada, 

Nice  umutlarla  koşuyorum  yarınlara, 

''Hacım,, der  seyredeyim  doya, doya, 

Güle, güle  gidin   yağmur  kuşları.

Hacı   Öztürk                     LİBYA / 03-12-2001

KAYDEDEN                       Hacı  Öztürk', 'Bilmem  hangi  illerden  gelirsiniz,  Selam  sabah  yok mu  yağmur  kuşları,?  Öyle  hasret  dulu ki bilseniz  sesiniz,  Mutlusunuz  yinede ...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yagmur-kuslari-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümlü Yaşamaya Hergünkü Çağrı-2', 'olumlu-yasamaya-hergunku-cagri-2-turgut-uyar-lova9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'RAHAT AYRILIKLAR İÇİN GİRİŞ

sosisli sandeviçlerin en seçmesi sizin için

hardallar ve denizaşırı bitkileri

gönlünüze göre aygın baygın ezgiler

inanmışlığınız, sevinmişliğiniz, uygunluğunuz

bir adamın bakışı size

bir kadının kalçalarını oynatması size

gök mavi oldumuydu sizin içindir

aşkolsun size

sizden utanıyorum özür dilerim

gelecek günlere başsağlığı dilerim

Artık bütün iş buluttaydı anlıyorsunuz.Üstelik onların söyledikleri beni hiç ilgilendirmiyordu.Ama doğrusu bulutun neler söyleyeceğini merak ediyordum.Bir bildiği var gibiydi.Polis ona baktı söyledi sonunda

ÖLÜMLÜ YAŞAMAYA ÖVGÜ

herkesin aşkının bir parça azımsandığı yerde

ben üç kişi biliyorum

ben bir ekmekle tuz biliyorum

bir de aşk biliyorum (Dedi) 

benim işim gece gündüz gökyüzünde durmaktır

meryem oğlu İsa''nın ballandıra ballandıra anlattığı yerdeyim

köhne ama güneşli sokaklara bayılıyorum

şarkıların adam öldürmek için yettiği kenar sokaklara 

       meymenet sokağı böyle bir sokaktır

29 Ekim bayramında gider üstünde dolanırım

14 Temmuz gecesi ne yapar yapar Van Gogh''un cümbüşüne

     
..........
..........', 'RAHAT AYRILIKLAR İÇİN GİRİŞ sosisli sandeviçlerin en seçmesi sizin için hardallar ve denizaşırı bitkileri gönlünüze göre aygın baygın ezgile...', ARRAY['Türk Edebiyatı','Şiir','Turgut Uyar']::text[], 8.5, '{"poet":"Turgut Uyar","poet_slug":"turgut-uyar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/olumlu-yasamaya-hergunku-cagri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelemem', 'gelemem-haci-ozturk-jupwf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünlerim  kayboldu,  bu  günler  mechul, 

Hazanı  yaşıyorum  hep  melul  mahzun, 

Seslensende  duyamam  kömürgözlüm,,,! 

Bil ki  dönülmez  bir  yerdeyim  gelemem.

Yıkılan  hayallerimin  sahibi  sensen, 

İnce  bir  kar  yağar  umutlarım  üstüne, 

Tüm  ıstıraba  katlanıp  evet  desende, 

Bil ki  dönülmez  bir yerdeyim  gelemem.

Gözyzşların  sel  olup  çağlasada, 

Kaybetsen  bir  gecede  tüm  ümitlerini, 

Bana uzansada tutmak  için  ellerin, 

Bil ki  dönülmez  bir  yerdeyim  gelemem.

Alnındaki  çizğiler  süs  olmuşsa  yüzüne, 

Bu  dünyada  aldırma  yalnızlığa  hüzüne, 

Gelirsen  sonunda''Hacı,, nın  sözüne, 

Bil ki  dönülmez  bir  yerdeyim  gelemem..

Hacı  Öztürk                     İZMİR  / 1980

KAYDEDEN                    Hacı    Öztürk', 'Dünlerim  kayboldu,  bu  günler  mechul,  Hazanı  yaşıyorum  hep  melul  mahzun,  Seslensende  duyamam  kömürgözlüm,,,!  Bil ki  dönülmez  b...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gelemem-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Akçaabat Pazarı', 'akcaabat-pazari-ceyhun-atuf-kansu-vyscx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Denize Karşı insan 

Karadeniz dediğin deniz değil insan

Gelir vurur Akçaabat pazarına.

Güneşe bırakılmış balık ağlarıyla

Kayıklarıyla kum/ara çekilmiş

Denize karşı insan! 

Kalabalık, güzel, çalışkan, 

iner çam direkli gemilerle.

Karadeniz dediğin mavi değil yeşil, 

Çocuk dudaklarını yakan incir, 

Yaprak tütün boyatmış mısır yeşil, 

Dağ taş karanlık fındık yeşil, 

Gözleri zeytin koyu yeşil, 

Yeşiloğlu yeşil Tanrı torunu yeşil.

Deniz gelmiş Akçaabatta durmuş

Kimin için bu deniz? 

Ağlarımız, bir yıldız düşmüş içine, 

Düşmüşüz çoluk çocuk peşine, 

Fındık dallarını aralayıp baktığımız

Oh -dediğimiz

Yırtık ağlarımızdan can balığını yitirdiğimiz

Bizim için bu deniz.

Irmak dağlardan dolana dolana, 

Kimin için bu ırmak? 

Tomruklar iner kara ormanlardan, 

Alabalık tutar bir yaz günü

Gözleri sulara düşen çocuklar.

Oh -dediğimiz, 

Yonttuğumuz o daldır, yüzer, yitik, 

Bizim için bu ırmak.

Gece gündüz büyür fındık dalları, 

Kimin için bu bahçeler? 

Gelen geçen yolcu bulutlar, 

Yeşil yağmurları bırakıp gider, 

Kızlarımız ufak ufak sefere sürdüğümüz, 

Oh -dediğimiz, 

Solgun yüzlerle dönülen yorgun deniz, 

Bizim için bu bahçeler.

Karadenizin yolları gemilere bakar, 

Kimin için bu yollar? 

Göreleye varmak için, 

Ardarda otobüsler, kamyonlar, 

Ana baba kardeş bir dağ ardında, 

Oh -dediğimiz, 

Bir kavuştuğumuz, bir yitirdiğimiz, 

Bizim için bu yollar.

Tireboluda demirciler örse vursa, 

Akçaabat denizinden duyulur.

Çarşılarda bakır dövse bakırcılar, 

Denizler kızarır gün batarken.

Bir kız peştemal dolasa beline, fındık dalı beline, 

Köylüler konuşsa noter kapısı önünde, 

Bir terzi ceket dikse iğnesinin türküsü

Duyulur Akçaabat denizinde.

Bir adam çıksa ses etse, 

Sesi gelir buralara kadar.

Akçaabat denizinde bir ağ çekilir, 

Sesi çıkar şu dağlara dağlara, 

Horon havasıyla, elele ölüme karşı, 

Yürür denize karşı insanlar.

Deniz Kahvesi

Bir kahve, sabah, kapısında deniz, 

Giren yabancı kim? 

Sorar kupa kızları, yorgun uşaklar, 

Açık pencerelerde deniz.

Denizde Erzurum vapuru, 

Nerelisin uşağım buralı mısın? 

Nereli? Nereli? Yolcu susuk, 

Unutmuş.

Ben yurdumu şu vapurda yitirdim, 

Benim yurdum koç boynuzu, 

Dolaşık bir karışık geçilmez, 

Benim yurdum halk masalı.

Bir deniz kahvesi, akşam kapısında ay ışığı, 

Duvarlarda Fatih Mehmet''in resimleri, 

Garip yolcu daha gitmedi, 

Ay düştü çoktan denize.

Ay düştü Kanlıca tepelerine, 

Giden Erzurum vapuru, 

Geçer mor salkım ikindilerde, 

Ötey gün Kanlıca önlerinden.

Vurmuş denizin karanlığı pencerelere, 

Pencerelerden geçer ışıklı direkler, 

Tutamazsın akıp giden gemileri, 

Yüreğinin dibinde yosunlar kan içinde, 

Yüreğinden demir almış, gitti gider.

Deniz tanrılarının seviştiği demler, 

Ak direkli gemilerle dalga dalga, 

İnmiş olmalılar Vona kıyılarına, 

O günden kalma şölen artığı bu deniz, 

Tanrıların öpüştüğü yerdir, taze tüter, 

O günden kalma, bu kekik kokusu.

Deniz tanrıları bayram edip gitmişler, 

Gökyüzünde durur hala bıçakları, 

Unutulmuş giysilerin kıvrımlarında çıplak çocuklar

Yol kıyısında bir küçük kız çilek satar yalınayak, 

Mutlu çocukların ormanlarda oynadığı günlerden, 

O bayram günlerinden kalma dağ çiçekleri.', 'Denize Karşı insan  Karadeniz dediğin deniz değil insan Gelir vurur Akçaabat pazarına. Güneşe bırakılmış balık ağlarıyla Kayıklarıyla kum/ar...', ARRAY['Türk Edebiyatı','Şiir','Ceyhun Atuf Kansu']::text[], 8.5, '{"poet":"Ceyhun Atuf Kansu","poet_slug":"ceyhun-atuf-kansu","theme":"Türk Şiiri","is_hero":false,"total_lines":98,"source_url":"https://www.antoloji.com/akcaabat-pazari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam Sana Yaylacik', 'selam-sana-yaylacik-guner-kaymak-xtiw7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Selam olsun yaylaciga koyume

Gozumde tutuyor hayli zamandir

Hasret kaldim ruzgarina karina

Hayali gonlumde hayli zamandir

Ilkbaharda cigdemleri aciyor

Cocuklari oynasiyor nese saciyor

Daglarinda karlari kolay kalkmiyor

Karlarini gormedim hayli zamandir

Demirci babanin tepesine cikinca

Tabiat ne guzel kozlucaya bakinca

Cemilbey, den Corum, a arabalar gecince

O ani yasamadim hayli zamandir

Ruzgari cok sert yazin bile usursun

Sulari soguk hic dokunmaz icersin

Veled pinarindan yokusu zor cikarsin

O yokusu cikmadim hayli zamandir

Mollahasana varinca icin burkulur

Az ileride keslik yolu ayrilir

Orayi gecersin baraj gorulur

O baraja gidemedim hayli zamandir

Sogucak yolundan sola donunce

Heyecan sarar Yaylacik, i gorunce

Hele arabayla gece koye girince

Koye arabayla girmedim hayli zamandir

Kizilhamza findikli oralarda guzel

Yaylacik bambaska ozelmi ozel

Asik Guner gurbette olurse eger

Koyume goturun diyor hayli zamandir

Amsterdam/23.03.2003', 'Selam olsun yaylaciga koyume Gozumde tutuyor hayli zamandir Hasret kaldim ruzgarina karina Hayali gonlumde hayli zamandir Ilkbaharda cigdeml...', ARRAY['Türk Edebiyatı','Şiir','Güner Kaymak']::text[], 8.5, '{"poet":"Güner Kaymak","poet_slug":"guner-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/selam-sana-yaylacik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttular Mı Seni?', 'unuttular-mi-seni-sair-desert-eagle-3sarn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine bir yaz akşamı

Unutulmuşluğun

Binlerce kez daha arttığı

Diğer akşamlardan sadece biri

Söylermisin? bana, söylermisin ey sevgili! ! ! 

Dün, bu gün ve yarın

Kimler aradı seni

Kimler arayacak seni

Efendim? 

Kimse Mi? ? 

yoksa senide benim gibi

yoksa 

yoksa....', 'Yine bir yaz akşamı Unutulmuşluğun Binlerce kez daha arttığı Diğer akşamlardan sadece biri Söylermisin? bana, söylermisin ey sevgili! ! !  D...', ARRAY['Türk Edebiyatı','Şiir','Şair Desert_eagle']::text[], 8.5, '{"poet":"Şair Desert_eagle","poet_slug":"sair-desert-eagle","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/unuttular-mi-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kömürgözlüm (2)', 'komurgozlum-2-haci-ozturk-u0sj2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben  senin  için  bağlanmıştım  hayata,, 

Senin  için  yaşıyordum   umutluca, 

Mutlu  günleri senin  için   diledim, 

Senden  almıştım   yaşamanın  gücünü, 

Sen  yaşadığın  müddetçe  kömürgözlüm,,,! 

Seninle her  şeye  razı  idim  ben

En  kahırlı  günü  en  çilekeş  günlere, 

En  çekilmez  azaba, dayanılmaz  acılara,,! 

Mutsuzluğa, yosulluğa  razıydım  kömürgözlüm...

BENİ   HİÇ   SEVMESEYDİN.......! 

Hiç  yüzüme  bakıp  umut  vermesetdin,, 

Adımı  anmasaydın, aramasaydın  beni, 

Yeter ki gözlerim  görseydi  yaşadığını, 

Bağrım  yansaydı  alev, alev, 

Yanımda  sen  olmasydın  da,,, 

Yine  seni  severdim  kömürgözlüm....! 



Hacı  Öztürk                 İZMİR /  1980

KAYDEDEN                 Hacı   Öztürk

1', 'Ben  senin  için  bağlanmıştım  hayata,,  Senin  için  yaşıyordum   umutluca,  Mutlu  günleri senin  için   diledim,  Senden  almıştım   yaş...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/komurgozlum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nedendir Dersin', 'nedendir-dersin-kadir-sevinc-1t2au', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'geceler efsun dolu

bekleyişler asude

yapraklar başka sarı

nedendir dersin

gözlerin ve yağmur

eczadır derde

nisansız mevsimler

geçer mi dersin...', 'geceler efsun dolu bekleyişler asude yapraklar başka sarı nedendir dersin gözlerin ve yağmur eczadır derde nisansız mevsimler geçer mi dersi...', ARRAY['Türk Edebiyatı','Şiir','Kadir Sevinç']::text[], 8.5, '{"poet":"Kadir Sevinç","poet_slug":"kadir-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/nedendir-dersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoktan Yere mi Var oldun Bende', 'yoktan-yere-mi-var-oldun-bende-haci-ozturk-69oc2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölmeliyim   anlıyormusun   ölmeliyim,,,! 

Mutluluk   yok  bana  bu  dünyada, 

Bunca  gözyaşının  ardından  soruyorum..? 

Yoktan    yeremi  var  oldun  bende.

Ölmeliyim   anlıyormusun   ölmeliyim,,,! 

Hançer  gibi  saplanıyor  anılar  yüreğime, 

Düşlere  inat  yoksun   beklemek  nafile, 

Yoktan  yeremi   var  oldun   bende....

Ölmeliyim    anlıyormusun   ölmeliyim,,,! 

Yapraksız  dalı  kırık  umut  ağaçlarımın, 

Yokluğun  yağıyor  kanayan  şu  yarama, 

Yoktan  yeremi   var  oldun  bende...

Ölmeliyim   anlıyrmusun   ölmeliyim,,,! 

Omuz, omuza  yürüdüğümüz  yollar  için, 

En  güzel  yarınlarımız  için ağlama,,,! 

Ağlama  be  kömürgözlüm  ağlama,,, 

Yoktan   yeremi   var   oldun   bende...

Hacı   Öztürk                         İZMİR / 1980

KAYDEDEN                         Hacı   Öztürk', 'Ölmeliyim   anlıyormusun   ölmeliyim,,,!  Mutluluk   yok  bana  bu  dünyada,  Bunca  gözyaşının  ardından  soruyorum..?  Yoktan    yeremi  v...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yoktan-yere-mi-var-oldun-bende-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitsin', 'bitsin-haci-ozturk-bkzge', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu   sevdanın  sonuda  hazin  olcaksa,, 

Yok  öyle  şey  bırak  başlamadan  bitsin.

Bu  garibe  dert  acı   yazdıracaksa,,,! 

Yok  öyle  şey  kır   kalemide   bitsin.

Sana  öylesine  yanmışım ki  tüterim,, 

Nerde  başına dert  gelse orda  biterim,, 

Yeter ki  sen  mutlu  ol ben  çilemi  çekerim, 

Yok öyle  şey  kır  şu  zicirleride  bitsin.

Ne dersen de  ayrılık   demiyesin  sakın,, 

Sonu yok  deryaya  benzer  bende   aşkın,, 

Bana  benden   uzak  dur  demiyesin  yarın,, 

Yok  öyle  şey  sar  bu  bedenide   bitsin.

Dünyamı  yalan  yosa  içindeki  canlar mı,,,? 

Karşılıksız  sevipte  yoksa  yalnız  kalan mı,,,? 

''Hacım,, seni  yıkan  yalan  sevdalar  mı,,,? 

Yok  öyle  şey  kömürgözlüm  sev de  bitsin.

Hacı  Öztürk                             İZMİR / 1980

KAYDEDEN                         Hacı   Öztürk', 'Bu   sevdanın  sonuda  hazin  olcaksa,,  Yok  öyle  şey  bırak  başlamadan  bitsin. Bu  garibe  dert  acı   yazdıracaksa,,,!  Yok  öyle  şey...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bitsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazda Okuyam', 'yazda-okuyam-haci-ozturk-88gns', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hesabımız   kaldımı  acaba  dünden,,? 

Şu  bizim  mektubu  yaz da  okuyam.

Hazırım  her  zaman yok  korkum  ölümden,, 

Şu  bizim   mektubu   yaz da  okuyam.

Bu  alemde  bende  düşmanım  yok  derdim, 

Darda  birini  görsem  kol  kanat  geredim, 

Dost  acı  söylermiş bunu  sonra  ögrendim, 

Şu  bizim   mektubu  yaz da   okuyam.

Bir  canım  var  hayatta  tek   sermayem, 

Dönen  döner  ben  dönmem  ki  yolumdan, 

Umutların  tükendiği yer de  yek   gayem, 

Şu  bizim   mektubu   yaz  da  okuyam.

Bu   misafirlik  elbet  bir  gün  bitecek, 

''Hacım,, emanet  canını  teslim  edecek, 

Üstümüzü  bir  avuc  toprak  örtecek, 

Şu  bizim    mektubu   yaz da  okuyam.

Hacı   Öztürk                       LİBYA / 01-12-2001

KAYDEDEN                       Hacı    Öztürk', 'Hesabımız   kaldımı  acaba  dünden,,?  Şu  bizim  mektubu  yaz da  okuyam. Hazırım  her  zaman yok  korkum  ölümden,,  Şu  bizim   mektubu  ...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yazda-okuyam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölen', 'olen-oktay-rifat-35u4w', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kavunu almak için uzanmış ve ölmüş

Kavunlar varmış, aralarından birine uzanıyormuş, uzanmış ve ölmüş

Ölenini uzandığı o kavunu başka biri almış, yemiş olmalı.

Oysa ölen o kavuna uzanıyor durmadan, kokulu ve olgun, 

o kavuna uzanan anlatıldıkça, sofrada ya da bahçede.

Anlatan rakı kadehine uzanacak, 

yanıbaşında duran kadehine: ''İşte böyle'', diyecek, 

''kavunu almak için uzanmış ve ölmüş.''

Ay doğuyor, üşüyor musun, ölü kaçıyor hızla, 

artık çok uzakta, uzandığı kavundan ve bizden çok uzakta.', 'Kavunu almak için uzanmış ve ölmüş Kavunlar varmış, aralarından birine uzanıyormuş, uzanmış ve ölmüş Ölenini uzandığı o kavunu başka biri al...', ARRAY['Türk Edebiyatı','Şiir','Oktay Rifat']::text[], 8.5, '{"poet":"Oktay Rifat","poet_slug":"oktay-rifat","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklım Sende Kalacak/1', 'aklim-sende-kalacak-1-mustafa-onder-4d146', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aklım sende kalmasın; 

Akşam ezanları okunduğunda

Saate bak arada bir, 

Beni beklediğini sanayım.

Aklım sende kalmasın; 

Gecenin bir yarısı sıçradığında

Adımı an arada bir, 

Kulaklarımın çınladığını sanayım.

Aklım sende kalmasın; 

Yalnız yürürken sokaklarda

Koluma gir arada bir, 

Kendimi kollarında sanayım.

Aklım sende kalmasın; 

Yapayalnız bunaldığında

Yastığına kapanıp ağla arada bir, 

Hala beni beklediğini sanayım.

Aklım sende kalmasın; 

Gurbet yollarına düştüğünde

Köylere el salla arada bir, 

Beni uğurladığını sanayım.

Ne edersem edeyim

Aklım hep sende kalacak, 

Kadehlerdeki el izlerin

Avuçlarımı yakıp kavuracak, 

Aklım yine sende kalacak!', 'Aklım sende kalmasın;  Akşam ezanları okunduğunda Saate bak arada bir,  Beni beklediğini sanayım. Aklım sende kalmasın;  Gecenin bir yarısı ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Önder']::text[], 8.5, '{"poet":"Mustafa Önder","poet_slug":"mustafa-onder","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/aklim-sende-kalacak-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Sanırım', 'sen-sanirim-mustafa-onder-v7yhw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gecenin bir yarısı kapım çalınır, 

Sen sanırım; 

Açsam bir türlü, açmasam bir türlü! 

Sokaklarda yalnızlığım parçalanır, 

Sen sanırım; 

Alsam bir türlü, almasam bir türlü! 

Durup dururken dudağımdaki cıgara efkarlanır, 

Sen sanırım; 

İçsem bir türlü, içmesem bir türlü! 

Baş yastığa düşmeden düşlerim ayaklanır, 

Sen sanırım; 

Görsem bir türlü, görmesem bir türlü! 

Bir dal karanfil penceremde tomurcuklanır, 

Sen sanırım; 

Koklasam bir türlü, koklamasam bir türlü! 

Seni sana sana ümitlerim yaşlandı, 

Ne çare, 

Buralarda hala gölgen dolanır, 

Sen sanırım; 

Sevsem bir türlü, sevmesem bir türlü!', 'Gecenin bir yarısı kapım çalınır,  Sen sanırım;  Açsam bir türlü, açmasam bir türlü!  Sokaklarda yalnızlığım parçalanır,  Sen sanırım;  Alsa...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Önder']::text[], 8.5, '{"poet":"Mustafa Önder","poet_slug":"mustafa-onder","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sen-sanirim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmiyorum', 'sevmiyorum-ayhan-ozyilmaz-16xsi', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kazanmayı sevmiyorum çünkü; 

Kaybedenlerin yüzlerindeki ifadeye dayanamıyorum.

Fırsatım var, yaşamayı sevmiyorum çünkü; 

Sahip olduklarımdan yoksun olanları tanıyorum.

Ağlamayı, hissetmeyi, aşık olmayı sevmiyorum çünkü; 

Tutkuyu, ihtirası, zarureti aşk kılıfına sokanları

ve istediğini elde edince, 

''Aşk Bitti! '' diyenleri biliyorum.

Kendimden tiksiniyorum çünkü; 

Doğruyu söyleyebiliyorum, doğruyu yazabiliyorum, 

Ama asla kendi doğrumu yaşayamıyorum.

İstanbul,1998', 'Kazanmayı sevmiyorum çünkü;  Kaybedenlerin yüzlerindeki ifadeye dayanamıyorum. Fırsatım var, yaşamayı sevmiyorum çünkü;  Sahip olduklarımdan...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Özyılmaz']::text[], 8.5, '{"poet":"Ayhan Özyılmaz","poet_slug":"ayhan-ozyilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sevmiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meğer Kalbim Ağlarmış', 'meger-kalbim-aglarmis-yasin-sahin-2-srvpe', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün doğmadan akşam oluyor içimde.

Fırtına kopuyor içimde.

Kalbim yelkensiz bir gemi 

Ve dalga geçiyor denizbenle.

Umut ise hiç bilmediğim bir yerde...

Bazen haykırarak ağlıyorum.

Bazen içime akıtıyorum gözyaşlarımı.

Yakıyor içimi, kalbimi! ..

Sonra avuçlarımda görüyorum gözyaşlarımı, 

içinde hasret 

içinde özlem 

içinde nefret

içinde aşk

..        ..

..        ..

Ve içinde rengi solmuş, matlaşmış umut.

Meğer kalbim ağlarmış...

(16-03-2002)', 'Gün doğmadan akşam oluyor içimde. Fırtına kopuyor içimde. Kalbim yelkensiz bir gemi  Ve dalga geçiyor denizbenle. Umut ise hiç bilmediğim bi...', ARRAY['Türk Edebiyatı','Şiir','Yasin Şahin 2']::text[], 8.5, '{"poet":"Yasin Şahin 2","poet_slug":"yasin-sahin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/meger-kalbim-aglarmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belkide Deli Olmuşum', 'belkide-deli-olmusum-yasin-sahin-2-1shot', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dönmek istesem dönebilir miyim, 

haykırsam duyar mısın kısık sesimi? ..

yalnızım ve hep ağlıyorum.

Artık zevk veriyor yalnızlık. Acı bir zevk..

Belkide deli olmuşum! 

Kalbim tersliyor beni...

Sevmiyorum, unutacağım diyorum.

Aşıksın diyor! ..

Ne yapsam? 

Kalbimi söküpte atsam, 

peşinden gelir mi? 

Peşinden gelse, beynimi dağıtsam.

Sonra yine çıkar mısın karşıma, 

yine sever miyim seni? ..

(2000)', 'Dönmek istesem dönebilir miyim,  haykırsam duyar mısın kısık sesimi? .. yalnızım ve hep ağlıyorum. Artık zevk veriyor yalnızlık. Acı bir zev...', ARRAY['Türk Edebiyatı','Şiir','Yasin Şahin 2']::text[], 8.5, '{"poet":"Yasin Şahin 2","poet_slug":"yasin-sahin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/belkide-deli-olmusum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huzurum Geri Gel', 'huzurum-geri-gel-lora-mora-cf66d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bır şeyler var benı rahatsız eden 

Bırseyler var bılmıyorum ıcımı kıyım kıyım eden 

Bu huzursuzluk bır gun gecermırkı bılmem? 

Bırseyler var benı benden alıp goturen 

Korkuyorum mutluluktan 

Korkuyorum yarından 

Korkuyorum caya seker atıp karıstırmaktan 

Nedır bılmıyorum benı bu kadar darmadagın eden 

Emınım bırseyler var benı huzursuz eden 

Sıkıntı ıcımı butun butun kaplamıs 

Geçıt vermez kı geceyım 

Bır yol gıdıp kım caldıysa 

ondan huzurumu ısteyım 

Ne dedım bılmemkı sana 

Nıye kırıldın bunca senedır bana 

Huzurum! Özur dılerım senı uzduysem 

Gerı don ne olur bana 

Gunduzler haram geceler helal bana 

Uykusuz geceler sersem sabahlarda 

Gun boyu sarhos gıbı dolasan bu kuluna 

Yardım et allahım 

Huzurumu gerı ver bana', 'Bır şeyler var benı rahatsız eden  Bırseyler var bılmıyorum ıcımı kıyım kıyım eden  Bu huzursuzluk bır gun gecermırkı bılmem?  Bırseyler var...', ARRAY['Türk Edebiyatı','Şiir','Lora Mora']::text[], 8.5, '{"poet":"Lora Mora","poet_slug":"lora-mora","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/huzurum-geri-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Salıncak Gıcırtısı', 'salincak-gicirtisi-turgay-akbulut-fk7qx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yazgımızın gerçek dostları 

Ay ışığı, yıldızlar

Yol arkadaşımız karanlıklar

Gecelerde yaşarız özgürlüğü

Geceler bize, 

Gündüzden daha hoşgörülü

Kimse bilmez derdimizi

Bilse de anlamaz ki 

Nedensiz gülüşünü

Kahkahasını

Sebepsiz ağlamalarını 

Suskun bakışlarını

Muhatap kalırız, 

İnciten bakışlara

Cevabını bulamadığımız, 

Nedenlerini bilmediğimiz sorulara...

Soruldukça tırmalanır yaramız

İçimiz kan ağlar

Kimse bilmez aktığını

Kan, içimize akar...

Bu yüzden kaçışımız gündüzden

Hesap soran yüzlerden

Geceler örter kusurumuzu

Gecelerde ararız huzuru

Issız parkları 

Boş salıncakları

Bizi teselli eden, 

Bir kavak yaprakları

Birde salıncak gıcırtısı...

(eylül 2002)', 'Yazgımızın gerçek dostları  Ay ışığı, yıldızlar Yol arkadaşımız karanlıklar Gecelerde yaşarız özgürlüğü Geceler bize,  Gündüzden daha hoşgör...', ARRAY['Türk Edebiyatı','Şiir','Turgay Akbulut']::text[], 8.5, '{"poet":"Turgay Akbulut","poet_slug":"turgay-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/salincak-gicirtisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bağ', 'bag-harun-taskin-iwgaz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her denizin kaderinde bir ''''ufuk'''' vardı

Buğday sarısına çalmış saçlarıyla

Utangaç bir ufuk...

Her sözün gizinde bir ''''susmak'''' vardı

Gözyaşlarını sakladığı haykırışlarıyla

Yaşlı bir susmak...

Her sufinin nedesinde bir ''''Allah'''' vardı

Ufuktaki suskunluğun sebebi

Yazılmıştan ziyade, yüce bir Allah...', 'Her denizin kaderinde bir ''''ufuk'''' vardı Buğday sarısına çalmış saçlarıyla Utangaç bir ufuk... Her sözün gizinde bir ''''susmak'''' vardı Gözyaş...', ARRAY['Türk Edebiyatı','Şiir','Harun Taşkın']::text[], 8.5, '{"poet":"Harun Taşkın","poet_slug":"harun-taskin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bag-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Özlüyorum', 'seni-ozluyorum-damla-koc-2gfz9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tenim tir tir titrer, seni düsündükce

Gözlerimde dereler baglar, seni gördükce

Aynada yarim aglar, ben öldükce

ama hep seni istiyorum...

Sanki günler gecmiyor

Gülmek icimden gelmiyor

Bana yemek, icmek haram oluyor

cünkü hep seni seviyorum...

Sensiz düsünemiyorum

Bazen ölüp ölüp kalkiyorum

Geceleri yildizlari sayarken agliyorum

sebebi seni hep özlüyorum...', 'Tenim tir tir titrer, seni düsündükce Gözlerimde dereler baglar, seni gördükce Aynada yarim aglar, ben öldükce ama hep seni istiyorum... San...', ARRAY['Türk Edebiyatı','Şiir','Damla Koç']::text[], 8.5, '{"poet":"Damla Koç","poet_slug":"damla-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/seni-ozluyorum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'AYRILIK', 'ayrilik-seref-kaya-iztsk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'En mesut günlerimiz de, beraberdik seninle, 

Cöller Deniz, Deniz`leri cöl yapardik seninle, 

Hayal, Umut dünyamizda, mutluluk vadederdi, 

Her beraberligimizde, simdi.............

Iste ayriliyoruz, simdi; senin isteginle, 

Son ve tek dilegim, mesut olursun bensizde.

Bir gün dersen; döner mi? Kendi kendine, 

Ben, sen degilim; Sevecegim ebediyen.

                                                                             seref kaya', 'En mesut günlerimiz de, beraberdik seninle,  Cöller Deniz, Deniz`leri cöl yapardik seninle,  Hayal, Umut dünyamizda, mutluluk vadederdi,  He...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ayrilik-100-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir gün bir an', 'bir-gun-bir-an-seref-kaya-geqm2', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bakiyorum engine, varligin yok yine.

Düsünüyorum, görebilirmiyim bir daha, 

Ayriyim cok uzakta, yalniz sensiz, 

Bir gün, bir an görebilecekmiyim seni.

Her zaman düsümde, görürüm yesil gözlerini.

Hickiriklarla uyanirim, yanimda yoksun! 

Saat`ler gecsede, uyku girmiyor gözüme, 

Bir gün, bir an görebilecekmiyim seni.

                                                                      

Gün agarirken, daglarin ardindan görürüm günesi, 

Hep hayal kurarim, görecekmisim gibi seni, 

Bozguna ugratir, karanlik Ay beni.

Bir gün, bir an görebilecekmiyim seni

                                                                   seref kaya', 'Bakiyorum engine, varligin yok yine. Düsünüyorum, görebilirmiyim bir daha,  Ayriyim cok uzakta, yalniz sensiz,  Bir gün, bir an görebilecekm...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bir-gun-bir-an-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kötü Gece İyi Gün', 'kotu-gece-i-yi-gun-cihan-bay-swk9g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Düş görüyorum baş eğdim gecenin buyruklarına.

Doğuşumun tüyünü kurşuna çeviriyorum.

Yalın bir kristalden bir sağır yapıyorum karanlıklarda.

Sessizlik büyüyor ölü dallar boyunca.

Tenini beyazlığı düşümde yakıyor beni.', 'Düş görüyorum baş eğdim gecenin buyruklarına. Doğuşumun tüyünü kurşuna çeviriyorum. Yalın bir kristalden bir sağır yapıyorum karanlıklarda. ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Bay']::text[], 8.5, '{"poet":"Cihan Bay","poet_slug":"cihan-bay","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kotu-gece-iyi-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YALVARIS', 'yalvaris-seref-kaya-8nhy1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Haykirdim bosluga, 

Ayrilanlar icin agladim.

Yalvardim Tanrim a, 

Darilan sevgilime.

Afetmediler yine beni, 

Raziyim ölmeye böyle sürerse, 

Kaderim elimde degil, bu benim, 

Agalamak, yalvarmakla.

Razi edemedim o tas kalp li, 

Sevgilimi.... Neden? 

Layik görmüyor, bana kendini, 

Issizliga bogdum, ben benligimi.

                                                            Seref kaya', 'Haykirdim bosluga,  Ayrilanlar icin agladim. Yalvardim Tanrim a,  Darilan sevgilime. Afetmediler yine beni,  Raziyim ölmeye böyle sürerse,  ...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalvaris-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ANKA KUSU', 'anka-kusu-seref-kaya-uncf0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Senmi kurtaracaksin dünyayi, 

Ideal de ne demek? 

Birak hayallerle avunmayi, 

Dogruluk aramak bosuna emek...

Herkes kendin degil, inanma

Kadinin adaletine siginma, 

Kadi insandir, önce kendine yontar, 

Artanlarla yetinme, hakkini ara...

Bu ögüt tutmaya deger, 

Gel bu sözlere bir deger ver, 

Biz anlariz bizim halimizdan, 

Gel, dertlerini bir bir ortaya ser...

Gül bahcesi degilse hayal sana, 

Dogruluk icin raziysan savasmaya, 

Gel, sen bir yandan kaz mezarini

Git, sonra dogrulugu kaf daginda ara...

1977(T.GÜRMEN.)          Ablam bana yazdigin bu siir i burada siir dostlarimla paylasmak istedim.Seni öpüyorum  2003.  seref kaya', 'Senmi kurtaracaksin dünyayi,  Ideal de ne demek?  Birak hayallerle avunmayi,  Dogruluk aramak bosuna emek... Herkes kendin degil, inanma Kad...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/anka-kusu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SENSİN', 'sensi-n-mehmet-i-mal-ajhpg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Eğer tek bir ışık varsa yüreğimde

Eğer son bir nefes kaldıysa ömrümde

Eğer pişman olmuyorsam tek bir canımı onun için verdiğimde

Bilki

O ışıkta, o nefeste, o canda 

SENSİN BİTANEM

                                                  Mehmet İMAL', 'Eğer tek bir ışık varsa yüreğimde Eğer son bir nefes kaldıysa ömrümde Eğer pişman olmuyorsam tek bir canımı onun için verdiğimde Bilki O ışı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet İmal']::text[], 8.5, '{"poet":"Mehmet İmal","poet_slug":"mehmet-i-mal","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sensin-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SADECE', 'sadece-mehmet-i-mal-1ktfk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben zaten ne üzerime Güneş gibi doğacak birini, 

ne de üzerine toprak misali basılacak birini arıyorum.

Bana rüyalarımı verin yeter

Hemde 

Sadece senin olduğun rüyalarımı...

                                                    Mehmet İMAL', 'Ben zaten ne üzerime Güneş gibi doğacak birini,  ne de üzerine toprak misali basılacak birini arıyorum. Bana rüyalarımı verin yeter Hemde  S...', ARRAY['Türk Edebiyatı','Şiir','Mehmet İmal']::text[], 8.5, '{"poet":"Mehmet İmal","poet_slug":"mehmet-i-mal","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sadece-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'IRAKLI ÇOCUKLAR AĞLIYOR', 'irakli-cocuklar-agliyor-sabit-i-nce-iji09', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Iraklı çocuklar ağlıyor, 

kara gözleri yaş değil, kan içinde...

Iraklı çocuklar, kara gözlü çocuklar...

Dünya çocukları da ağlıyor, 

ıraklı çocuklara değil, 

geleceklerine, dünyanın kararmasına 

ağlıyorlar...

Caniler, canavarlar açmış ağızlarını, 

gelecek çocukları da yutmaya hazır, 

dünyanın geleceğini yutmaya hazır, 

Iraklı çocuklar ağlıyor, 

Anaların yüreklerini dağlıyor...

Ben de Iraklı çocuklara, 

dünya çocuklarına ağlıyorum, 

Onların geleceğine, kanlı dünyalarına

yok olan hülyalarına ağlıyorum.

Ya siz? 

Siz de Iraklı çocuklara ağlıyor musunuz? 

Kararan dünyaya umut bağlıyor musunuz? 

ve geleceğinize, çocuklarınıza, 

dünya çocuklarının yok olan geleceklerine, 

ağlıyor musunuz? 

Iraklı çocuklar ağlıyor, 

Onlar geleceklerine, yok olan dünyalarına

dünya çocuklarına ağlıyorlar...

Sabit İnce Kayseri 22.03.2003

YASAL UYARI: Bu şiir sadece internet sitelerinde ve e maillerde kullanılabilir. Tv, Radyo, gazete ve dergilerde telif hakkı ödenmeden yayınlanıp, çoğaltılması yasaktır. 

Telif Hakkı için Sabit İnce  0352 2350458 -0532 2919163 nolu telefonlarla iletişim kurulabilir.', 'Iraklı çocuklar ağlıyor,  kara gözleri yaş değil, kan içinde... Iraklı çocuklar, kara gözlü çocuklar... Dünya çocukları da ağlıyor,  ıraklı ...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/irakli-cocuklar-agliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kerküklü Hişam', 'kerkuklu-hisam-sabit-i-nce-bcgv8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'KERKÜKLÜ HİŞAM

		Kerküklü Albay Hişam’a-

Bir garip kuştur havada, 

Kerküklü Hişam kardeşim.

Dert kaynatır bir tavada, 

Kerküklü Hişam kardeşim.

Yarasadır görmez gözü, 

Hakka dosdoğrudur özü, 

Erkekçe, mertçedir sözü, 

Kerküklü hişam kardeşim.

Kavga verir ekmek için, 

Sıla der de yanar için, 

Neden mutsuz, neden, niçin

Kerküklü hişam kardeşim.

Ana Türkmen baba Arap, 

Sen yardım eyle sen Yarab, 

Hak uğrunda olmuş turap, 

Kerküklü hişam kardeşim.

Mültecidir O’nun adı, 

Dünyadan almamış tadı, 

Arşa yükselir feryadı, 

Kerküklü Hişam kardeşim.

On parmakta bin marifet, 

Hatıra etmez iltifat, 

İnce’ye yaptı bir suret, 

.Kerküklü Hişam Kardeşim.

4.8.1999 Kayseri Sabit İnce', 'KERKÜKLÜ HİŞAM 		Kerküklü Albay Hişam’a- Bir garip kuştur havada,  Kerküklü Hişam kardeşim. Dert kaynatır bir tavada,  Kerküklü Hişam kardeş...', ARRAY['Türk Edebiyatı','Şiir','Sabit İnce']::text[], 8.5, '{"poet":"Sabit İnce","poet_slug":"sabit-i-nce","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kerkuklu-hisam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Annemi Özledim Ben', 'annemi-ozledim-ben-gursel-colak-6267w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Küçükken bizi koruyan

Bizim için ağlayan

Bizi uyutan, kendisi uyumayan

Annemi Özledim Ben.

Yemeyip yediren, giymeyip giydiren

Okuyamadığı için bizi okutan

Bizi büyütmek için çabalayan

Annemi Özledim Ben.

Alış veriş için pazara giden

Çeşme başında yardımımı bekleyen

İki filesini taşırken kızdırdığım

Annemi Özledim Ben.

Bize hayatı, yaşamayı ve dürüstlüğü

Yardım etmeyi ve kimseyi ezmemeyi

Zayıflara el kaldırmamayı ve korumayı öğreten

Annemi Özledim Ben

Yanımda olsada gene kızsa

Yemesemde o yese

Hasta olmasada ben olsam

Yok olan Annemi Özledim ben', 'Küçükken bizi koruyan Bizim için ağlayan Bizi uyutan, kendisi uyumayan Annemi Özledim Ben. Yemeyip yediren, giymeyip giydiren Okuyamadığı iç...', ARRAY['Türk Edebiyatı','Şiir','Gürsel Çolak']::text[], 8.5, '{"poet":"Gürsel Çolak","poet_slug":"gursel-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/annemi-ozledim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'thomas hanks', 'thomas-hanks-sair-lolan-m8c5n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'THOMAS HANKSLAR

Gök her zamanki hayat ve müzik

Yeryüzüne çökmüş bütün sisler

Herkesin ağzında bir garip emzik

Yağmurlara yetmiyor silecekler

Öyle sıradan bir yağmur değil bu

Bağdat’a tomas hankslar yağıyor

Ateşe verilmiş tapınılan kuyular

Çöl artık cehennem gibi yanıyor

Melek ve şeytanlar peyda oldu

Füze ve tank eşliğinde bir balo

Maskenin düşmediği salon oldu

Tüm medyalara çalan aynı bando

Birini al öbürüne vur

Aralarında fark yoktur

Biri texas kovboyudur

Öteki gaz silahşörü’dur 

Katil katili hırsız hırsızı kovalarken

Masum insanlar hep  ödüyor faturayı

Birde onura ve gurura her şey kalırken

İçinde sızlıyor bir şeyleri kurtarmayı

Ey dünyalı kardeşlerim

Gelin kovalım şeytanı ve meleği tahtından

Bu hayat bu dünya bizim

Yaşam umut olsun herkese bu harikalardan

Polusyonlar artık yetti canımıza

Az kaldı yetmek için dünyamıza

Gelin yeni değerler verelim hayatımıza

Yeni sevdalar kirlenmemiş aşklarımıza

LOLAN	23/03/03', 'THOMAS HANKSLAR Gök her zamanki hayat ve müzik Yeryüzüne çökmüş bütün sisler Herkesin ağzında bir garip emzik Yağmurlara yetmiyor silecekler...', ARRAY['Türk Edebiyatı','Şiir','Şair Lolan']::text[], 8.5, '{"poet":"Şair Lolan","poet_slug":"sair-lolan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/thomas-hanks-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-saadet-guldursun-rnsi2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmek 

Bir karıncayı bile incitmemek 

Sevmek 

Bir çiçeği dalında okşayabilmek 

Sevmek 

Bir MARTI nin kanadında gökyüzüne erebilmek 

Sevmek 

İçin kan ağlarken, kahkahayla gülebilmek 

Sevmek 

Kötüye, güzellikle gidebilmek 

Sevmek 

Yapılanları affedebilmek 

Sevmek 

Herkesi olduğu gibi kabul edebilmek 

Sevmek 

Büyüğe saygı, küçüğe sevgi verebilmek 

Sevmek 

Gönlünde kendinle sevişebilmek 

Sevmek 

Yaradılanı Yaradan dan dolayi sevebilmektir... 

23.3.2003 Münih 4: 45', 'Sevmek  Bir karıncayı bile incitmemek  Sevmek  Bir çiçeği dalında okşayabilmek  Sevmek  Bir MARTI nin kanadında gökyüzüne erebilmek  Sevmek ...', ARRAY['Türk Edebiyatı','Şiir','Saadet Güldürsün']::text[], 8.5, '{"poet":"Saadet Güldürsün","poet_slug":"saadet-guldursun","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sevmek-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sev beni', 'sev-beni-saadet-guldursun-j3v7g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çıkar yüreğimdeki hançeri

Acılarım dinsin

Sarıl sevginle bağrıma

Hasretim bitsin

Ayda bir değil, hergün gelmelisin

Beni, laf olsun diye değil

Ölümüne sevmelisin

(11.3.2003 Münih-Almanya 23: 00)', 'Çıkar yüreğimdeki hançeri Acılarım dinsin Sarıl sevginle bağrıma Hasretim bitsin Ayda bir değil, hergün gelmelisin Beni, laf olsun diye deği...', ARRAY['Türk Edebiyatı','Şiir','Saadet Güldürsün']::text[], 8.5, '{"poet":"Saadet Güldürsün","poet_slug":"saadet-guldursun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sev-beni-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Affim Yok Sana', 'affim-yok-sana-saadet-guldursun-lfj04', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özlemindi bana ferman yazdiran

Bagrimda ki atesi yakipta azdiran

Sendin, birakip ta kizdiran

Affim yok sana birtanem

Bir sevdin, bir sevemedin

Belli degil, nedir istedigin

Sen ask''i oyun mu belledin

Affim yok sana birtanem

Ne aradin, ne de sordun

Ummadigim anda tuzaklar kurdun

Sen beni arkamdan vurdun

Affim yok sana birtanem

Git simdi, gidebilirsen

Sev istedigini, sevebilirsen

Çok ararsin ben gibisini sen

Affim yok sana birtanem

4.1.2003 Münih 6: 00', 'Özlemindi bana ferman yazdiran Bagrimda ki atesi yakipta azdiran Sendin, birakip ta kizdiran Affim yok sana birtanem Bir sevdin, bir sevemed...', ARRAY['Türk Edebiyatı','Şiir','Saadet Güldürsün']::text[], 8.5, '{"poet":"Saadet Güldürsün","poet_slug":"saadet-guldursun","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/affim-yok-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Başka', 'senden-baska-sezgin-keles-trk9o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir bakarsın gün doğmuş görmüşsün sevdiğini, 

Bir bakarsın akşam olmuş o unutmuş her şeyi, 

Karanlığı sevmedim, bu yüzden hiç kimseyi

Sevemedim senden başka kimseyi.', 'Bir bakarsın gün doğmuş görmüşsün sevdiğini,  Bir bakarsın akşam olmuş o unutmuş her şeyi,  Karanlığı sevmedim, bu yüzden hiç kimseyi Seveme...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Keleş']::text[], 8.5, '{"poet":"Sezgin Keleş","poet_slug":"sezgin-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/senden-baska-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost''a', 'dost-a-arzu-dincer-qp4eo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ağladığında, mendil misali yanında olmak, 

Olmak canının yandığında melhemin.

Yüreğin her kanadığında sözsüz dinlemek, 

Dinlemek anlatılarını.

Anlatılarına gülmek, 

Paylaşmak zevkini yaşamak 

Yaşamak istediğin kadar, 

Adına yaraşır tanımlar oluşturmak.

Yılları ardımızda bırakıp, 

Beraberce  yoldaş olmak.', 'Ağladığında, mendil misali yanında olmak,  Olmak canının yandığında melhemin. Yüreğin her kanadığında sözsüz dinlemek,  Dinlemek anlatıların...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dost-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma', 'unutma-haci-ozturk-nfuef', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seni  sevdiğimi  unutursan,, 

Benim   yaşadığım  şehirde,, 

Seni  beklediğimi   sanma,,,! 

Çünkü  o  zaman  beni,,, 

ARAMA,,,,,,,! 

Ne  olur   eskiye  dönmemei  isteme, 

Evrenime   girme  ne  olur,,,! 

Orada  artık  sana  yer   yoktur.

Sevdamı  bile  haram  ettim,,,! 

UNUTMA,,,,,,,,,, 

Hacı  Öztürk                  İZMİR /1980

KAYDEDEN                 Hacı   Öztürk', 'Seni  sevdiğimi  unutursan,,  Benim   yaşadığım  şehirde,,  Seni  beklediğimi   sanma,,,!  Çünkü  o  zaman  beni,,,  ARAMA,,,,,,,!  Ne  olur...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/unutma-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Arama', 'beni-arama-haci-ozturk-f5s92', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senin  için  akan  gözyaşlarımda, 

Bir  sevgi, bir  şevkat  bulamadıysan, 

İçimdeki  kanayan  yarayı, 

Ellerinle   saramadıysan, 

Yıktığın  dünyamızı,, 

Dertlerinle  yaratmadıysan, 

Sakın  ha,,,!  sakın,,,, 

Sana  olan  sevgim  soğudu, 

Kırılan   kalbimin  tamiri,,,, 

Bir  ömre  sığmaz  bilesin,,,! 

Gün  olurda  sevdiğini  anlarsan,, 

Benliğini  pişmanlık  duygusu  sararsa,, 

Eski  günlere  dönmemizi  isteme, 

Sana  son  sözüm  ne  olur,,,! 

Sakın   ha,,,!  sakın,,,,,, 

Artık  beni   arama.

Hacı   Öztürk                 İZMİR / 1981

KAYDEDEN                  Hacı   Öztürk', 'Senin  için  akan  gözyaşlarımda,  Bir  sevgi, bir  şevkat  bulamadıysan,  İçimdeki  kanayan  yarayı,  Ellerinle   saramadıysan,  Yıktığın  ...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/beni-arama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamadan Ölmek mi,?', 'yasamadan-olmek-mi-haci-ozturk-l1u6m', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dinle  be  arkadaş,, 

Beni  bu  karanlığa, 

Yaşaduğım yıllar  attı.

O  yıllarda  bir  ilham  perim  vardı,,,! 

Umutlarım, inançlarım  ondaydı.

Şimdigeçen  yılları, 

Başım  ellerim  arasında,, 

Acı, acı  düşünüyorum.

Kimbilir  ne   zaman  dinecek, 

Esen  bu  fırtına, 

Kimbilir  ne  zaman  bitecek, 

Sonu  gelmeyen  bu  kabus,,,! 

Yorğunum  arkadaş  anlasana,, 

Bitsin  diyorum  bu  düş  bu  rüya, 

Hani  herşeyin  bir  başlangıcı  varya,,,! 

Yoksa, yoksa  söyle  be  arkadaş, 

Yaşamadan   ölmek  mi,,,? 

Hacı   Öztürk                      İZMİR /  1981

KAYDEDEN                    Hacı  Öztürk', 'Dinle  be  arkadaş,,  Beni  bu  karanlığa,  Yaşaduğım yıllar  attı. O  yıllarda  bir  ilham  perim  vardı,,,!  Umutlarım, inançlarım  ondayd...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yasamadan-olmek-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama Küçüğüm', 'aglama-kucugum-arzu-dincer-rrdi9', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerin korku ile dolu küçüğüm.

Korkma annen, 

Kefenini yırtıp gelecek yanına

Ve sen onun kollarında

Tekrar öğreneceksin

İnsanlara güvenmeyi

Kulaklarından silinecek mi? 

Bilmiyorum, 

Yıldız yağmurunun sesi..

Ağlama küçüğüm

Koluna saplanan şarapnel

İnsan  olmayı unutmuş, 

Bir büyüğün hediyesi

Ağlama küçüğüm

İri siyah gözlerinden dökülen 

Her gözyaşın 

Dalga dalga büyüyüp

Okyonuslar oluşturacak

Ve insanlar

İnsanlar ki 

Kendi elleri ile yarattıkları ölüm’de

Bir utanç olarak yazılacaklar tarih’e', 'Gözlerin korku ile dolu küçüğüm. Korkma annen,  Kefenini yırtıp gelecek yanına Ve sen onun kollarında Tekrar öğreneceksin İnsanlara güvenmey...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/aglama-kucugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canlı Yayın', 'canli-yayin-arzu-dincer-nsmfq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Füzeler uçuşuyor, 

Beyaz cam’da, canlı..

İnsanlar vuruluyor, 

Beyaz cam’da, canlı..

Evler ve hayatlar yıkılıyor, 

Beyaz cam’da, canlı...

İki yüz beliriyor, 

Beyaz cam’da, canlı..

Hırslar çarpışıyor

Beyaz cam’da, canlı..

Cansız bedenler sergileniyor, 

Beyaz cam’da, canlı...

Sıra kim’e geliyor? 

Beyaz cam’da, az sonra...', 'Füzeler uçuşuyor,  Beyaz cam’da, canlı.. İnsanlar vuruluyor,  Beyaz cam’da, canlı.. Evler ve hayatlar yıkılıyor,  Beyaz cam’da, canlı... İki...', ARRAY['Türk Edebiyatı','Şiir','Arzu Dinçer']::text[], 8.5, '{"poet":"Arzu Dinçer","poet_slug":"arzu-dincer","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/canli-yayin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demişsin,,,', 'demissin-haci-ozturk-kst0j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saat  gecenin  üçü,,, 

Bir   duble  rakı, iki  tek  sigara, 

Seni  anarak  içeceğim,, 

Resmine  bakıp, bakıp.

Kaç  mevsim  geçti  bilirmisin,,,? 

Kaçıncı   baharı  yaşadım  sensiz, 

Senden  kalan  küçük  bir  resim, 

Birde   yokluğun.....

Çaresizim, bir  ömre  yetecek, 

Uzaktasın  bir  tanem  çok  uzak, 

Kilometrelerce   uzakta,,,! 

Bir  rüzğardı   gelip  geçti,,, 

DEMİŞSİN,,,,! 

Unuttun  mu  beni  unuttun  mu,,? 

Unutmak  o  kadar  kolaysa, 

Ne   olur  bende    unutayım  ebediyen,,,,! 

Hacı    Öztürk                    İZMİR / 1981

KAYDEDEN                    Hacı   Öztürk', 'Saat  gecenin  üçü,,,  Bir   duble  rakı, iki  tek  sigara,  Seni  anarak  içeceğim,,  Resmine  bakıp, bakıp. Kaç  mevsim  geçti  bilirmisin...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/demissin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnat İçin,,', 'i-nat-i-cin-haci-ozturk-emgyt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sana  inat  seveceğim   yeniden, 

Ayrılığın  yasını  bile  tutmayacağım, 

Unutacağım,,, 

Sesini, gözlerinin  rengini, 

Ellerinin   sıcaklığını,, 

Saçlarının  yumuşaklığını, 

Adını  bile   anmayacaağım

NİÇİN  Mİ,,,,? 

Bana  sevgi  dilenen  ellerini, 

Uzatsan  bile  tutmatacağım, 

İnat  için,,,,! 

Karanlık  gecenin  elleri, 

Sımsıkı  saracak  tüm  benliğini, 

Kömür gözlerinden  akan  yaşları,, 

Silmeyeceğim,,, 

NİÇİN  Mİ,,,? 

Adımı  binlerce  defa   haykırsanda,,! 

Duymamazlıktan  geleceğim,,, 

İNAT     İÇİN,,,,,! 

Hacı    Öztürk                        İZMİR / 1981

KAYDEDEN                       Hacı    Öztürk', 'Sana  inat  seveceğim   yeniden,  Ayrılığın  yasını  bile  tutmayacağım,  Unutacağım,,,  Sesini, gözlerinin  rengini,  Ellerinin   sıcaklığı...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/inat-icin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ebediyen', 'ebediyen-haci-ozturk-py841', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sende  mi  bıktın  yaşamaktan,, 

Sende  mi  terkedildin   acımasız, 

Sende  mi  her gün  batan  güneşle,, 

ÖLÜYOR,,,,! 

Doğan  güneşle   mutsuzsun.

Umutların  yarınlara  mahkum mu,? 

Mahkum mu  isyan  duyguların,,, 

Öyleyse   boş  ver.

Üzülme  terkedilmişliğe, 

Üüzülme  kaybolan  umutlara.

Bak  işte  yine  gün  doğuyor, 

Umut  doğuyor, sevgi  doğuyor, 

Uzat  hayata  mahkum  olan  ellerini, 

Kurtar  gözlerini  kör  karanlıklardan, 

Sana  uzanan  elleri  tut, 

TUT Kİ  BIRAKMA,,,,! 

Kavuşalım   özlenen  sevgilere, 

Bir  daha  sevelim  birbirimizi, 

AYRILMAMAK  İÇİN  EBEDİYEN.

Hacı   Öztürk                   İZMİR / 1981

KAYDEDEN                Hacı   Öztürk', 'Sende  mi  bıktın  yaşamaktan,,  Sende  mi  terkedildin   acımasız,  Sende  mi  her gün  batan  güneşle,,  ÖLÜYOR,,,,!  Doğan  güneşle   mut...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ebediyen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şafakta Öleceğim', 'safakta-olecegim-haci-ozturk-ssy25', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni   düşlediğim  geceler, 

İçim  acıyla  burkulurdu, 

Yalnız  sensizliği, 

Ak  kağıtlara  dökerdim, 

Uyuyamazdım,,,! 

Uyku  girmezdi  gözlerime, 

Bir  türlü  alışamadım, 

Seni  anar, seni  aradım.

Gecelerin  yalnızlığında, 

Beklerdim  çaresiz

Tutam, tutam  hislerim  ezik

Demek  ki  kara  bahtım, 

Gömülmüş  bir  kere  mutsuzluğa, 

Birde   sensizlik  kopmuş,,,,! 

Uzaklaş  artık   taklaşma  bana, 

Çünkü   hayallerimle  ben,,,, 

Şafakta   öleceğim....

Hacı   Öztürk                     İZMİR/ 1981

KAYDEDEN                      Hacı   Öztürk', 'Seni   düşlediğim  geceler,  İçim  acıyla  burkulurdu,  Yalnız  sensizliği,  Ak  kağıtlara  dökerdim,  Uyuyamazdım,,,!  Uyku  girmezdi  gözl...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/safakta-olecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladım', 'anladim-haci-ozturk-hi08a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevmek  var  olmaktır,,, 

Sevmek  yaşamak, 

Bende  bir  zamanlar,, 

Kullandım  hakkım  olan  sevgiyi,,! 

Ne  yazık ki  çabuk  bitti, 

Tek  başıma  bırakıp, 

Yalnızlığın  ellerine  terketti.

Yinede  onu  aradım, 

Kömürgözlerini, sevgisini, 

Ellerini,,,, 

Anladım  sonunda, 

Ölen  sen  değildin, 

Bulmalıydım,,,,! 

İşte  ben  hep  bu  ümitle  yaşadım, 

Gelecek  diyordum  kendikendime, 

Sensiz  yaşamın  gereksizliğini, 

O   zanam  anladım,,,! 

Ve  sonunda  ben  yok  olacağım, 

Ve  sana  yazdığım  şiirler  kalacak.....

Hacı  Öztürk                      İZMİR / 1981

KAYDEDEN                    Hacı   Öztürk', 'Sevmek  var  olmaktır,,,  Sevmek  yaşamak,  Bende  bir  zamanlar,,  Kullandım  hakkım  olan  sevgiyi,,!  Ne  yazık ki  çabuk  bitti,  Tek  b...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/anladim-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onsuz', 'onsuz-haci-ozturk-uqadk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yürürken  gözleri  kapanırcasına  ağır, 

Adımları  kaldırım  taşlarını,, 

Sayarcasına   yavaş, 

Bitkin  birini  görürseniz  bilin  ki,,,! 

Hatıralarıyla  pençeleşiyordur.

Ya   sevdiklerinden   ayrı, 

Ya   sevdiğinden, 

Ya   bir  derdi  vardır, 

Ya   terkedilmiş, 

HÜZÜNLÜ,,,,,,! 

Her  şey  başkadır  onun  için, 

Gözyaşları  bir  perdedir, 

Hayal  deryası  gibi.

Hele  en  çok  sevdiği, 

Canı  kadar  kıymet  verdiği, 

Bırakıp  göklere  uçmuş, 

Bulutlarla  kucaklaşıp, 

Meleklere  arkadaş  olmuşsa,,,! , 

Hayattaydı  nefes  alıp  yaşıyordu,, 

Her  şeyi  görüyordu  ama,,,,,,! 

ONSUZ.

Hacı   Öztürk                    İZMİR /1981

KAYDEDEN                   Hacı   Öztürk', 'Yürürken  gözleri  kapanırcasına  ağır,  Adımları  kaldırım  taşlarını,,  Sayarcasına   yavaş,  Bitkin  birini  görürseniz  bilin  ki,,,!  H...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/onsuz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gördüm', 'gordum-haci-ozturk-pwp3r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Benim  gibi  masa  başında, 

Titreyen  elleriyle,,, 

Satırlara  döküyorsa  içindekileri, 

KUSARCASINA, 

İnsanları  sev  dediniz,,,! 

Sevdim, sevdimde  gördüm, 

Sevimli  yüzlerin  ardındaki, 

Kalleşliği, kahpeliği  gördüm,, 

Tüm  acısıyla  tattım, 

Tattım da  o  büyük  sevginin, 

Bir  kin, bir  nefret   olduğunu, 

GÖRDÜM......

Yoruldum, yoruldum yoruldum, 

Yazamıyorum,,,! 

Uyumak   istiyorum  uyumak, 

Her  şeyi  unuturcasına  uyumak.....

Hacı   Öztürk                     İZMİR / 1981

KAYDEDEN                     Hacı  Öztürk', 'Benim  gibi  masa  başında,  Titreyen  elleriyle,,,  Satırlara  döküyorsa  içindekileri,  KUSARCASINA,  İnsanları  sev  dediniz,,,!  Sevdim,...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gordum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle Güle Sevdiğim', 'gule-gule-sevdigim-orhan-gencebay-qency', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güle güle sevdiğim, bahtın açık olsun.

Bütün özlediklerimiz, seni bulsun.

Ne ilk temennim bu ne son olacaktır, 

Hasretlere benden de selam olsun.

Geri döneceksen eğer, yolu biliyorsun.

Git diyen yok ki sana, gidiyorsun.

Aşkı sen öğretmiştin, unutmayı da öğret.

Seni nasıl sevdiğimi bilmiyorsun.

Ne vardı ayrılığa koşupta sarılacak, 

Hasretinde gözyaşı var görmüyorsun.

Neydi bizi ayıran, neydi bizi kıran.

Kim olmuşki ayrılıkla mutlu olan.

Her gurbet yolcusunun bir sılası vardır, 

Senin sılan şu gönlüm, senle dolan.', 'Güle güle sevdiğim, bahtın açık olsun. Bütün özlediklerimiz, seni bulsun. Ne ilk temennim bu ne son olacaktır,  Hasretlere benden de selam o...', ARRAY['Türk Edebiyatı','Şiir','Orhan Gencebay']::text[], 8.5, '{"poet":"Orhan Gencebay","poet_slug":"orhan-gencebay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gule-gule-sevdigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinde ışık göremiyorum', 'gozlerinde-isik-goremiyorum-gulay-yenilmez-ixaz6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'GÖZLERİNDE IŞIK GÖREMİYORUM 

HATTA SENİ YİTİRDİM 

RAÜZGARA KÜSTÜM 

ARADA KOKUNU GETİRİRDİ 

VEFASIZ ARTIK ESMEZ OLDU 

HASRET ANLAMSIZ KALDI 

ÖLÜM UMUT OLDU RÜYALARDA 

DÖNSEN NEYE YARAR 

BEN SENDE YİTİP GİTTİM 

GÜLAY YENİLMEZ 23/11/2002', 'GÖZLERİNDE IŞIK GÖREMİYORUM  HATTA SENİ YİTİRDİM  RAÜZGARA KÜSTÜM  ARADA KOKUNU GETİRİRDİ  VEFASIZ ARTIK ESMEZ OLDU  HASRET ANLAMSIZ KALDI  ...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yenilmez']::text[], 8.5, '{"poet":"Gülay Yenilmez","poet_slug":"gulay-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gozlerinde-isik-goremiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıramı bekliyorum', 'sirami-bekliyorum-gulay-yenilmez-zjrrt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'YANIYORUM KENDİ ATEŞİMLE 

KIVILCIMI VEREN KAVRULDU GİTTİ İÇİMDE 

DAHA BÜYÜK AŞKA AÇTIM KOLLARIMI 

BEKLEDİĞİM ANA NE ZAMAN GELECEK 

GELDİĞİNDE BULACAK BENİ AYAKTA 

ÇOK GÖZ YAŞI DÖKTÜM ATEŞİME 

SÖNDÜRMEK GÜÇSÜZLÜKMÜŞ 

TEKAMÜLÜMÜ TAMAMLIYORUM 

YAN BE ATEŞİM KAVUR BENİ 

SIRAMI BEKLİYORUM 

GÜLAY YENİLMEZ   19/8/2002', 'YANIYORUM KENDİ ATEŞİMLE  KIVILCIMI VEREN KAVRULDU GİTTİ İÇİMDE  DAHA BÜYÜK AŞKA AÇTIM KOLLARIMI  BEKLEDİĞİM ANA NE ZAMAN GELECEK  GELDİĞİND...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yenilmez']::text[], 8.5, '{"poet":"Gülay Yenilmez","poet_slug":"gulay-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sirami-bekliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir acı name çalar', 'bir-aci-name-calar-gulay-yenilmez-bq03h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'BİR DELİ RÜZGAR ESER 

KOKUNU GETİRİR SENİN DİYARINDAN 

BİR ACI NAME ÇALAR 

SESİNİ DUYURUR KULAĞIMA 

YÜREĞİM YERİNDEN ÇIKAR 

ÜMİTLENİRİM GERİ GELDİN DİYE 

ELLERİMİ UZATIRIM HAYALİNE 

TAM DOKUNACAK OLURUM 

YİTİP GİDERSİN ÜMİTSİZLİĞİMDE 

GÜLAY YENİLMEZ 1/3/2001', 'BİR DELİ RÜZGAR ESER  KOKUNU GETİRİR SENİN DİYARINDAN  BİR ACI NAME ÇALAR  SESİNİ DUYURUR KULAĞIMA  YÜREĞİM YERİNDEN ÇIKAR  ÜMİTLENİRİM GERİ...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yenilmez']::text[], 8.5, '{"poet":"Gülay Yenilmez","poet_slug":"gulay-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bir-aci-name-calar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana mecburum ben', 'sana-mecburum-ben-gulay-yenilmez-as2gk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'SANA MECBURUM BEN 

TUTKUSUN KALBİMDE HİÇ BİTMEYECEK 

GÖZ YAŞLARIM TÜKENMEDEN AKIYOR 

GÜLÜMSEYEREK YAŞAYAMIYORUM SENİ 

ÖZLEMİN ACI VERİYOR YÜREĞİME 

SENİ SEVMEKTEN YORULDUM 

ASLA VAZGEÇMEYECEĞİM AMA 

BU BEDEN 

BU YÜREK 

BU RUH 

SANA SÖZ VERDİ 

GÜLAY YENİLMEZ 28/2/2001', 'SANA MECBURUM BEN  TUTKUSUN KALBİMDE HİÇ BİTMEYECEK  GÖZ YAŞLARIM TÜKENMEDEN AKIYOR  GÜLÜMSEYEREK YAŞAYAMIYORUM SENİ  ÖZLEMİN ACI VERİYOR YÜ...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yenilmez']::text[], 8.5, '{"poet":"Gülay Yenilmez","poet_slug":"gulay-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sana-mecburum-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İzmit geliyorum', 'i-zmit-geliyorum-gulay-yenilmez-e36av', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'KÖRFEZE BAKIYORUM DOLU GÖZLERLE 

ŞİMDİ BİR KAÇ DAMLA YAŞ DÜŞECEK BİLİYORUM 

SEVİNÇDEN DE AĞLANIR BE DOSTUM 

BUGÜN SEN GİDELİ 610 GÜN OLDU 

KOKUN HALA KÖRFEZİN ÜZERİNDE 

BU SABAH MELTEMİNDE DERİN DERİN İÇİME ÇEKİYORUM 

ÇOK SEVİNÇLİYİM, ÇOOOOK..... 

ELİMDE SON YAZDIĞIN MEKTUP 

BEKLE İZMİT GELİYORUM DİYORSUN 

BEKLE GÜLÜM... 

BEKLİYORUM BE TOPRAĞIM 

ZATEN BEKLEMEYİ HİÇ BIRAKMADIM 

SABAH YÜRÜYÜŞÜNE BAŞLADIĞIM SARAY YOKUŞUNDAN 

KIVRILA KIVRILA İNERKEN ESKİ GARA SENİ DÜŞÜNDÜM 

ORADAN VER ELİNİ SAHİL, YİNE YANIMDASIN 

BİR SICAK POÇA, BİR TAVŞAN KANI ÇAY 

BİR DE SEN, BİR DE İZMİT YANIMDA 

BU SABAH KÖRFEZ BİR BAŞKA GÖZÜKTÜ GÖZÜME 

KÜÇÜK DALGALAR ARASINDAN ÇIKAN FISILTILAR GELDİ KULAĞIMA 

GELİYOR O, BUGÜN GELİYOR 

DÖNÜYOR O, BUGÜN DÖNÜYOR 

BİRADAN YENİ OTOGARA GİDECEĞİM 

SENİ İLK ORADAN UĞURLAMIŞTIM BAŞAKA DİYARLARA 

BUGÜN YİNE ORADA KARŞILAYACAĞIM, ÖZLEMLE, AŞKLA 

GÜLAY YENİLMEZ  20/2/2002', 'KÖRFEZE BAKIYORUM DOLU GÖZLERLE  ŞİMDİ BİR KAÇ DAMLA YAŞ DÜŞECEK BİLİYORUM  SEVİNÇDEN DE AĞLANIR BE DOSTUM  BUGÜN SEN GİDELİ 610 GÜN OLDU  K...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yenilmez']::text[], 8.5, '{"poet":"Gülay Yenilmez","poet_slug":"gulay-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/izmit-geliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Dem', 'son-dem-yerhan-yildirim-1f6zn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir köşede iki büklüm oturuşun, 

Ve birde arada  ümitsiz bakışın itmişti, 

Beni bu İLAH''larla savaşa.

Ne oldu ki sana? 

Birzamanlar tanrı ZEUS''u altetmiş, 

Ve PİRAMİT''le daim kılmıştın sanaatını.

Ya BABİL''in ASMA KÖPRÜ''sü, 

Heyhat...

BUDA''da kurtaramadı seni bu oturuştan.

Biliyorum az çırpınmadık, balığın karnından atılmaya.

Ne mahkemeler kurduk biz, 

FRANSIZ İHTİLALİ''nda

Tüm malımızı vermemiz yetmedi

Yarının emeğinide rehin verdik RAHİP MARTİN''e.

İlk darbe değildi yediğim kardeşlerimden, çölde kuyuya atılışım.

Tam kurtulmuşken karanlıktan, 

Terkeyledi hayat ortağım LUT diyarında.

Nedendi tüm bunlar? 

Bir oğlum kalmıştı yanımda, 

Oda yüz çevirdi bana NUH TUFANI''nda.

Az İLAH değiştirmedim bu sürgünde, 

İşlemediğim suçtan yargılandım, 

Bana ait olmayan kostümle çıktım idam sehbasına.

Hakimde bendim, savcıda.

Yaktığımız dağ ateşleri geldi birden aklıma, 

Nede hoş giderdi, bıldırcın etinden sonra birkaç nefes sigara.

Bizi yıldızlardan saklayacak hiçbirşey yoktu, 

Bir meşe ağacından başka.

Alev yüzümüzü yalardı esen rüzgarın itmesiyle, 

Çok geçmeden köz olurdu kor alevler.

Küçük bir demlik koyardık o köze, 

yarıya kadar çamur sıvalı.

O kaynadıkça ocakta, ben ritim tutardım tüfeğimi harbilerken, 

Uyumaya çalışırdım sarıldığım palazın arasında.

Hem kundağım, hem de anam gelirdi aklıma.

Sen mırıldandıkça o şarkıyı, 

Duyduğum en manalı sesti, HAYYALELSALAH uyandığımda.

Kılacağım ilk NAMAZ''ım olacaktı ama, 

Onuda kaybetmiştim, 

Bir İMAM ve bir URGAN''la.', 'Bir köşede iki büklüm oturuşun,  Ve birde arada  ümitsiz bakışın itmişti,  Beni bu İLAH''larla savaşa. Ne oldu ki sana?  Birzamanlar tanrı ZE...', ARRAY['Türk Edebiyatı','Şiir','Yerhan Yıldırım']::text[], 8.5, '{"poet":"Yerhan Yıldırım","poet_slug":"yerhan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/son-dem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '21 Şubat', '21-subat-gulay-yenilmez-rrene', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BEN HEP MAHZUN OLURUM 21 ŞUBATLARDA 

YÜREĞİM DALAR GİDER ESKİ GÜNLERE 

SENİNLE GEÇEN İKİ 21 ŞUBAT VAR ÖMRÜMDE 

ŞİMDİLERDE YOKSUN NAFİLE 

DALDIM GİTTİM O YEŞİL ŞEHRİN YOLLARINA 

YİNE KAR VARDI DEĞİLMİ O AYLARDA 

SENİNLE ISINMIŞTIM YILDIZLI MEKANDA 

GÜN GEÇMEMİŞTİ, GECE ÇABUK BİTMİŞTİ 

NELER UMMUŞTUM ŞİMDİ NE DURUMDAYIM 

SENİNLE OLDUĞUM GÜN 

GEBEYMİŞ BİR ÖMÜR BOYU YALNIZLIĞA 

GÜLAY YENİLMEZ  21/2/2001', 'BEN HEP MAHZUN OLURUM 21 ŞUBATLARDA  YÜREĞİM DALAR GİDER ESKİ GÜNLERE  SENİNLE GEÇEN İKİ 21 ŞUBAT VAR ÖMRÜMDE  ŞİMDİLERDE YOKSUN NAFİLE  DAL...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yenilmez']::text[], 8.5, '{"poet":"Gülay Yenilmez","poet_slug":"gulay-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/21-subat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine de bekliyorum', 'yine-de-bekliyorum-gulay-yenilmez-lxd6w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'GÜN GELİYOR ÜMİT ETMEYİ KESİYORSUN 

YÜREĞİN ACIDAN KATRANLAŞIYOR 

UMUT ETTİĞİN HER İNSANI ÇIKARTIYORSUN HAYATINDAN 

ÖZLEMİN DAHA DA YAKIYOR YÜREĞİMİ 

DAYANAMAYACAĞIM DEDİĞİM ANLARDA 

BİR DAHA DENE DİYORUM 

ARTIK AĞLAYAMIYORUMDA, GÖZYAŞIM BİTTİ 

SENİ HALA ÇOK SEVİYORUM 

DÖNMEYECEĞİNİ BİLE BİLE, YİNE DE BEKLİYORUM 

GÜLAY YENİLMEZ 28/4/2000', 'GÜN GELİYOR ÜMİT ETMEYİ KESİYORSUN  YÜREĞİN ACIDAN KATRANLAŞIYOR  UMUT ETTİĞİN HER İNSANI ÇIKARTIYORSUN HAYATINDAN  ÖZLEMİN DAHA DA YAKIYOR ...', ARRAY['Türk Edebiyatı','Şiir','Gülay Yenilmez']::text[], 8.5, '{"poet":"Gülay Yenilmez","poet_slug":"gulay-yenilmez","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yine-de-bekliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğum Günü', 'dogum-gunu-sami-aydin-90vfa', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İyi ki doğdun, 

İyi ki varsın, 

İyi ki buradasın, 

İyi ki dünyadasın.

Bundan sonrasına gelince....

Sakın GİTME....! 

Ne yaşamımızdan, 

Ne yaşamdan.....

 (12.Mart.2003)', 'İyi ki doğdun,  İyi ki varsın,  İyi ki buradasın,  İyi ki dünyadasın. Bundan sonrasına gelince.... Sakın GİTME....!  Ne yaşamımızdan,  Ne ya...', ARRAY['Türk Edebiyatı','Şiir','Sami Aydın']::text[], 8.5, '{"poet":"Sami Aydın","poet_slug":"sami-aydin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dogum-gunu-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimin İniltisi', 'kalbimin-i-niltisi-yasin-sahin-2-vpm0y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneşe baktığımda, gözlerimi kapamazdım.

O saklanırdı bulutların arkasına! ..

Ellerimi ateşe tuttuğumda, çekmezdim ellerimi.

Ateş sönerdi! ..

Ellerim üşürdü. Ağlardım.

Gözyaşı dökmezdim. Çünkü kalbim ağlardı.

İniltisini en derinliklerimde duyardım.

Ne dediğini anlamazdım, 

anlasaydım bile umursamazdım...

Gözlerim aldırmazdı kalbime.

Onunla hiç ağlamazdı. Belki acımasızdı gözlerim, 

belki yorgun, belkide dargındı kalbime...

Duygularım hep aldattı.

''''Aklınla hareket et'''' demişti birisi rüyam da.

BAŞARAMADIM...

(09-12-2000)', 'Güneşe baktığımda, gözlerimi kapamazdım. O saklanırdı bulutların arkasına! .. Ellerimi ateşe tuttuğumda, çekmezdim ellerimi. Ateş sönerdi! ....', ARRAY['Türk Edebiyatı','Şiir','Yasin Şahin 2']::text[], 8.5, '{"poet":"Yasin Şahin 2","poet_slug":"yasin-sahin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kalbimin-iniltisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duymuyorsun', 'duymuyorsun-alper-uluses-fzd9e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'inanmıyorum yaşadıklarıma, seni kaybettiğime, 

bunu kabullemeye çalışmama.

nasıl olabilir de bu hale gelebilir bizim ilşkimiz? 

anlamıştım benden uzaklaşmaya çalıştığını 

kendini korumak istemiştin daha çok üzülmekten.

bunun içindi çaban şimdi anlıyorum, 

bir anda ayrılamazdın, sevgini yavaş yavaş bitirdin, 

ayrılığı usulca çağırdın aramıza, 

bense bütün bunlar olurken yaşantıma devam ettim, 

hissetmeme rağmen umursamadım.

nerden bilebilirdim ki seni kaybettiğimde daha çok seveceğimi? 

hani derler ya elindekinin değerini bilmezsin diye 

nerden bilebilridimki bunu yaşayarak öğreneceğimi? 

seni seven ben, beni sevmekten vazgeçen sen.

biz artık yokuz sen ve ben ayrıyız.

sen ve ben, bizi özlüyorum şimdiden, 

kendimden daha çok sevdiğim içinmi bizi, 

yoksa bana benden daha yakın olduğun içinmi sen  bilmiyorum.

seni özlüyorum ama ne yazıkki sen beni duymuyorsun biliyorum.', 'inanmıyorum yaşadıklarıma, seni kaybettiğime,  bunu kabullemeye çalışmama. nasıl olabilir de bu hale gelebilir bizim ilşkimiz?  anlamıştım b...', ARRAY['Türk Edebiyatı','Şiir','Alper Uluses']::text[], 8.5, '{"poet":"Alper Uluses","poet_slug":"alper-uluses","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/duymuyorsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkım Seni Seviyorum', 'askim-seni-seviyorum-ahmet-akarsu-o34fc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkım seni seviyorum

İnanmazsan sözüm yoktur sana

Oysa ağaçta ki  dallar bile

Biliyor seni sevdiğimi

Ama sen yine inanmadın

Kim bilir sana olan 

Tutkumu sevgimi hasretimi, 

Gün gelir anlarsan bil ki o zaman ben

ÖLMÜŞÜM

Diyorum ya gönül

Ben seni sevmişim', 'Aşkım seni seviyorum İnanmazsan sözüm yoktur sana Oysa ağaçta ki  dallar bile Biliyor seni sevdiğimi Ama sen yine inanmadın Kim bilir sana o...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Akarsu']::text[], 8.5, '{"poet":"Ahmet Akarsu","poet_slug":"ahmet-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/askim-seni-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemedik', 'bilemedik-mustafa-onder-topgr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Fırtına gibi geçti ömrümüz, 

Vefâlıyı, vefâsızı bilemedik.

Bir kadehlik meydi gönlümüz, 

Bir yudumda içeni bilemedik! 

Bir zalime kul olmuş bülbül, 

Kadir bilmez elinde şimdi gül..

Geriye ne kor kaldı, ne de kül, 

Ansızın yakıp geçeni bilemedik! 

Karlı dağdı, esip durdu başımız, 

Yerine varmayan mektuptu aşkımız, 

Yârdan öksüz artık mezar taşımız, 

Ayrılığa zulüm derken, ölümü bilemedik!', 'Fırtına gibi geçti ömrümüz,  Vefâlıyı, vefâsızı bilemedik. Bir kadehlik meydi gönlümüz,  Bir yudumda içeni bilemedik!  Bir zalime kul olmuş ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Önder']::text[], 8.5, '{"poet":"Mustafa Önder","poet_slug":"mustafa-onder","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilemedik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlarım Feryadı Bırakın Artık,,,!', 'umutlarim-feryadi-birakin-artik-haci-ozturk-fp8s1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Haydi   ağlama  sil  gözyaşlarını, 

Hayat  gözyaşlarına  değmezmiş,,! 

Bunu   bana  biri   öğretti.

AĞLAMAK  MI,,,? 

Geceler   boyu  sokak, sokak, 

Bırak  kim  ağlarsa  ağlasın, 

Kahrı  çekilmeyen  gecelerde, 

İnsan  severken bile mutlu  olmazmış.

İnsan  severken de ağlarmış,, 

Unut, unut ogeçen  günleri, 

O  anılardan  bu  gözlere  hayır  yok,,,! 

Ah,,,! birde  şu  sol  yanımdaki  sancı,, 

Sancı  olmasa,,,,, 

Umutlarım  feryadı  bırakın  artık,,,,! 

Boşuna  yorulmayın, 

Unutma  ki  vefasız  unutma,,, 

Umut  güneşin  hiç bir  zaman  doğmayacak.....

Hacı    Öztürk                       İZMİR / 1980

KAYDEDEN                        Hacı   Öztürk', 'Haydi   ağlama  sil  gözyaşlarını,  Hayat  gözyaşlarına  değmezmiş,,!  Bunu   bana  biri   öğretti. AĞLAMAK  MI,,,?  Geceler   boyu  sokak, ...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/umutlarim-feryadi-birakin-artik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evet Evet', 'evet-evet-charles-bukowski-wwu1d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Evet Evet 

tanrı aşkı yarattığında çoğu insana yaramadı

tanrı köpekleri yarattığında köpeklere yaramadı

tanrı bitkileri yarattığında eh işte idare ederdi

tanrı nefreti yarattığında standart bir hizmete kavuştuk

tanrı beni yarattığında beni yaratmış oldu

tanrı maymunu yarattığında uyuyordu

zürafayı yarattığında sarhoştu

uyuşturucuları yarattığında kafası kıyaktı

ve intiharı yarattığında bunalımdaydı

senin yatakta uzanmış halini yarattığında

ne yaptığını biliyordu

sarhoştu ve kafası kıyaktı

ve sonra dağları ve denizi ve ateşi

aynı anda yarattı

bazı hataları oldu

ama senin yatakta uzanmış halini yarattığında

tüm Kutsal Evren'' in üzerine boşaldı.

                                   Charles Bukowski', 'Evet Evet  tanrı aşkı yarattığında çoğu insana yaramadı tanrı köpekleri yarattığında köpeklere yaramadı tanrı bitkileri yarattığında eh işte...', ARRAY['Türk Edebiyatı','Şiir','Charles Bukowski']::text[], 8.5, '{"poet":"Charles Bukowski","poet_slug":"charles-bukowski","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/evet-evet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Ölüm Orucundayım ya Sen,,', 'ben-olum-orucundayim-ya-sen-haci-ozturk-9zv9s', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sende  istiyorsun  besbelli, 

Benim  kadar  arzuluyorsun  gelmeyi,, 

Ama  şaşkın  ve  karasız, 

Hayat   acılarıyla  küflenmiş  yüreğim,, 

Bense  ölüm  orucundayım  ya  sen,,,! 

Hani  mutlu  olacağız  derdik ikide  bir, 

Öylesine  güçlüydüki  içimizdeki  umut,, 

Oysa  sabır  küpü  olduk   ikimiz, 

Bense  ölüm  orucundayım  ya  sen,,,,! 

Bizi  ayıracaklar  hiç  acımadan, 

Daha   yeşermeden   dallarımız, 

Yapraklarımız  güz  gelmeden  soldu, 

Kime  el  açalım  bir  parça  sevda  için, 

Biz  böyle  başlamadık ki,,, 

Kanımıza   girdiler  kömürgözlüm,, 

Kanımıza  hiç  acımadan

Bense  ölüm  orucundayım   ya  sen,,,! 

Hacı   Öztürk                   İZMİR / 1980

KAYDEDEN                   Hacı    Öztürk', 'Sende  istiyorsun  besbelli,  Benim  kadar  arzuluyorsun  gelmeyi,,  Ama  şaşkın  ve  karasız,  Hayat   acılarıyla  küflenmiş  yüreğim,,  Be...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ben-olum-orucundayim-ya-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeyen Sevgim Sana Helalım', 'bitmeyen-sevgim-sana-helalim-haci-ozturk-z6uag', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Nice  umutlar  yaşardı  nice  hayaller, 

Hepsine  hasret, hepsine  özlem  gönüllerimiz, 

Yanar, yanar  durur  bağrımız, 

Yaşamak  istedin  yükseklerde  yaşamak, 

Solumak  istedin  ışıklı  pencerelerden, 

Yaşamak  istedin  hayallerini, 

Umutlu   umutsuz,,,! 

KÖMÜRKARASI   GÖZLÜM,,,, 

Sen  yanıldın, 

Sende   yanıldın  diğer  mutsuzlar  gibi, 

Acımasızca  ezilmişliğini  anladın, 

Hayat   dersini  acı  bile  olsa, 

Yaşamak  istedin...

Çaresiz  ölümsüz   aşkını, 

Kalbinin   en  ücra  köşesine  gömdün,,,! 

Unutmayı  denedin  belki, 

Ne   olursa  olsun    unutmayı,, 

Ama  unutmaya  çalıştıkça, 

Daha  çok  sevdiğini   anladın, 

Umudum  bitmedi  daha  sevdalım, 

Bitmeyen   sevgim  sana  HELALIM,,,, 

Hacı   Öztürk                        İZMİR/ 1980

KAYDEDEN                       Hacı   Öztürk', 'Nice  umutlar  yaşardı  nice  hayaller,  Hepsine  hasret, hepsine  özlem  gönüllerimiz,  Yanar, yanar  durur  bağrımız,  Yaşamak  istedin  y...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bitmeyen-sevgim-sana-helalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Mavi Çiçek', 'bir-mavi-cicek-ataol-behramoglu-3g5oe', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Önce top mermileriyle dövüldü alan

Tarandı sonra mitralyözlerle

Sonra boğaz boğaza dövüşüldü

Ve sonra usulca indi gece

BİR MAVİ ÇİÇEK KALMIŞTI SADECE

AMA YOKTU KOKLAYACAK KİMSE

Sabaha karşı dindi iniltiler

Yan yana, üst üste yığılı ölüler

Ağaçlar devrilmiş, kavrulmuş çimenler

Boğulmuş yaşayan ne varsa bu yerde

BİR MAVİ ÇİÇEK KALMIŞTI SADECE

AMA YOKTU KOKLAYACAK KİMSE

O sabah yine maviydi gökyüzü

Başladı az sonra kuşların türküsü

Sabah rüzgarı ne bilsin ölümü

Esti durdu kırlarda keyfince

BİR MAVİ ÇİÇEK KALMIŞTI SADECE

AMA YOKTU KOKLAYACAK KİMSE', 'Önce top mermileriyle dövüldü alan Tarandı sonra mitralyözlerle Sonra boğaz boğaza dövüşüldü Ve sonra usulca indi gece BİR MAVİ ÇİÇEK KALMIŞ...', ARRAY['Türk Edebiyatı','Şiir','Ataol Behramoğlu']::text[], 8.5, '{"poet":"Ataol Behramoğlu","poet_slug":"ataol-behramoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bir-mavi-cicek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamansız Sevmek', 'zamansiz-sevmek-haci-ozturk-v9z04', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevmek  öylesine  zorki  sevdalım, 

Gündüzleri  unutmuş  gözlerim, 

Geceler  ezberimdeki  şiirler  gibi, 

Geç  saatlerde  ezilişimdir  bu  benim,, 

Zamanı  kısıtlı  bir  mahkum  gibi, 

Bir  ileri, bir  geri  yürüyorum, 

Tutsaklığım  pencere  önü, 

Adımlarım  inadına  yorgun, 

Şafakların  ötesingüneşin  doğuşu  gibi, 

Uzuyor da  uzuyor,,,! 

Ne  zaman  yorgun  düşünce  dizlerim, 

Yağmur  gözyaşım, rüzgar   yodaşım,,,! 

Böyle   sevdalım  sevmenin  zamanı  yok,,, 

Zamansız  sevmek  kahrediyor   beni, 

Zamansız    sevmek,,,,,! 

Hacı   Öztürk                       İZMİR /1980

KAYDEDEN                       Hacı    Öztürk', 'Sevmek  öylesine  zorki  sevdalım,  Gündüzleri  unutmuş  gözlerim,  Geceler  ezberimdeki  şiirler  gibi,  Geç  saatlerde  ezilişimdir  bu  b...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/zamansiz-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lanet Olsun,,!', 'lanet-olsun-haci-ozturk-g26xa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen    farkındamısın,,,? 

Sen   bilebilirmisin,,,? 

Benim  dünyam  sensiz, 

Hayat   olmayan  gezegene  benzer, 

Sabahlar   olmaz, 

Güneş  doğmayı  unutur, 

Ay  ise  gülümsemeyi, 

Yıldızlar  ise  parlamayı,,,, 

Sen   görebilirmisin,,,? 

Sen  bilebilrmisin,,,? 

Benim  dört  mevsimimde, 

kara kış  hüküm  sürer, 

Buralara    bahar  gelmez, 

Burada  doğa  öyle  mahzundur  ki,,,! 

Öyleyse   gel  gel,,,,,, 

KÖMÜRKARASI   GÖZLÜM,, 

Seninle  yeşersin   yine  sevdam, 

Seninle  güneş  doğsun  dünyama, 

Sensiz  geçen   karalık  gecelerime, 

LANET     OLSUN,,,,,,! 

Hacı   Öztürk                    İZMİR / 1980

KAYDEDEN                Hacı    Öztürk', 'Sen    farkındamısın,,,?  Sen   bilebilirmisin,,,?  Benim  dünyam  sensiz,  Hayat   olmayan  gezegene  benzer,  Sabahlar   olmaz,  Güneş  do...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/lanet-olsun-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim İçin Ağlama', 'benim-i-cin-aglama-haci-ozturk-66uk1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sevmek  suç mu  oldu  sevenler, 

Maziye  gidercesine  geri, geri, 

Gidiyor  zaman,,, 

İçimde  bir  his  var, 

Seni  kaybetmekten  korkuyorum, 

Her  şey  kapkara  uçsuz  bucaksız, 

Yaşantımda  her  şey  sensiz,,, 

Kalemler  bitene  dek  seni  yazacam, 

Seni  kaybetsemde   yaşamımda, 

Her  şey  bitti  desen de  alın  yazım,, 

ANADOLULUYUM   ben,,,! 

Kömürkarası  gözlüm,,,, 

Anadoluluyum  inandım  sana, 

İZMİR''in  şu  haline   bakta,,, 

Sakın  ha  sakın,,, 

Benim  için  ağlama.

Hacı   Öztürk                      İZMİR / 1980

KAYDEDEN                   Hacı   Öztürk', 'Sevmek  suç mu  oldu  sevenler,  Maziye  gidercesine  geri, geri,  Gidiyor  zaman,,,  İçimde  bir  his  var,  Seni  kaybetmekten  korkuyorum...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/benim-icin-aglama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve Ağlamasını Bilmeyen Sen,,', 've-aglamasini-bilmeyen-sen-haci-ozturk-v7tdt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'SEN,,,,,,! 

Düşünmek  nedir  bilirmisin,,,? 

Gecelerin   karanlığında  iç  çekerek, 

Hiç    ıslandın  mı,,? 

Pencereden  baktığında  gördün mü,,? 

Sokakta  sırılsıklam   olanları,, 

Sordun mu  hiç,,? 

Yağmurdan mı  ıslanmışlardı.

Baharda   baktın mı  doğaya,,? 

Yemyeşil,,, 

Ben  baktıkça  gözlerini  hatırlarım, 

Ya   sen,,,! 

Kuru  bir  ağaca  dalıpta, 

Beni  hatırladın mı,,? 

İşte  böyle  başlar  benim  gecelerim, 

Düşünceli, düşündükçe  teselli  olurum, 

AĞLAMAKLI,,,,, 

Saatın  akrebiyle  dönüp  sabahlarım, 

Sende  benim  gibi   böylemisin,,? 

Ve  ağlamasını    bilmeyen,, 

KÖMÜRGÖZLÜM,,,,! 

Ve  ağlamasını  bilmeyen   sen,,, 

Oturup  hüngür, hüngür,,, 

AĞLAYACAKSIN........! 

Hacı   Öztürk                     İZMİR / 1980

KAYDEDEN                       Hacı    Öztürk', 'SEN,,,,,,!  Düşünmek  nedir  bilirmisin,,,?  Gecelerin   karanlığında  iç  çekerek,  Hiç    ıslandın  mı,,?  Pencereden  baktığında  gördün ...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ve-aglamasini-bilmeyen-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Desem Ki,,,', 'nasil-desem-ki-haci-ozturk-cqchi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu  hasret,  bu  özlem  birde  gözyaşı, 

Çağlar, çağlar  dururum  nasıl  desem ki, 

Beni   kahreden  sevdalım  gurbet  ateşi, 

Yanar,  yanar  dururm  nasıl  desem  ki.

Zaman  uzun  zaman  içimde  sızı, 

Hasretlik   ayrılığın  en  amansızı, 

Geceler dersen  yalnızlığın en allahsızı, 

Gezer, gezer  dururum  nasıl  desem  ki.

Gurbette  hasretlik  bitmeyen   çile, 

Derdini  anlatsan  kime  ne  geçer  ele, 

Dert  ortağı   olmazsan  kendi kendine, 

Söylenir, söylenir  dururum  nasıl desem  ki.

Bir  zamanlar  bende  çağlayan  seldim, 

Gün  oldu  ağladım  gün oldu  güldüm, 

Kömürgözlümü  artık  defterden  sildim, 

''Hacım,, doğrumu  yaptı  nasıl  desem  ki.

Hacı   Öztürk                       İZMİR / 1980

KAYDEDEN                  Hacı    Öztürk', 'Bu  hasret,  bu  özlem  birde  gözyaşı,  Çağlar, çağlar  dururum  nasıl  desem ki,  Beni   kahreden  sevdalım  gurbet  ateşi,  Yanar,  yanar...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/nasil-desem-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ÇAY TERCİHİMİZ', 'cay-terci-hi-mi-z-caglar-akarsu-1fyag', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çay Tercihi

.....

Rize''nin dağları yüksek, 

Yolları çıkmaz ve dolambaçlı, 

Çay bahçeleri küme-küme

Yamaçlarda, yemyeşil  toplanmış, 

Çilesi çekilirken  bir- bir, 

Günler hep yarı ıslak ve yağmurlu, 

Yollar kaygan ve aşılmaz, 

Hemşin tepelerinde bulutlar, 

Sarmışlar bir çarşaf gibi, her yeri

Gün doğarken bir çiğ damlası, 

Bitkilerin üzerinde elmas gibi parlar, 

...

Karadeniz diyarlarından bir çayımız var, 

Her sabah, ocaktaki demlik de bir yaprak, 

Yayla  evlerinde bir soba, yanarken, 

Odunlar, yığılmıştı karlı  dağlara, 

.....

Kahve ateşinde, söndürmedik, 

Gönüller artık,  bir fincanda

Bin bir bahaneler aramaz oldu, 

Çamlı dağların yamaçlarında, 

Çayın kokusunu duyarken, 

Anadolu''nun bağrına doğru, 

İnsanlarda, demli sevgileri, 

Paylaşılırken, her gün yeniden doğduk..

....

2003/subat/caglar akarsu', 'Çay Tercihi ..... Rize''nin dağları yüksek,  Yolları çıkmaz ve dolambaçlı,  Çay bahçeleri küme-küme Yamaçlarda, yemyeşil  toplanmış,  Çilesi ...', ARRAY['Türk Edebiyatı','Şiir','Cağlar Akarsu']::text[], 8.5, '{"poet":"Cağlar Akarsu","poet_slug":"caglar-akarsu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/cay-tercihimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BİR BAŞKA MEVSİM', 'bi-r-baska-mevsi-m-omer-bayhan-igrz3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Binlerce çiçek yaprağı dökülür başımdan, 

Gelin pulu gibi her yanım..

Sonbahar değil mevsim..

İlkbahar hiç değil.

İnsanın içinde bazen, 

Açan bir başka mevsim vardır.

Farklıdır, çiçeği o mevsimin, 

Rengi..Kokusu farklıdır.

Buram buram aşk kokar..', 'Binlerce çiçek yaprağı dökülür başımdan,  Gelin pulu gibi her yanım.. Sonbahar değil mevsim.. İlkbahar hiç değil. İnsanın içinde bazen,  Aça...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bayhan']::text[], 8.5, '{"poet":"Ömer Bayhan","poet_slug":"omer-bayhan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-baska-mevsim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Böyle Bir Kardeş', 'i-ste-boyle-bir-kardes-abdulhamit-kanca-oczly', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şimdi biz 

Seninle ikimiz

Cehennem pusularına inat

Cennet tuğlalarından 

iki kişiyiz.

Koşamayız aşk tarlalarında

Mecnunları kıskandırmaya, 

Ölmesinler diye

Koparamayız kır çiçeklerini

Dünyalı sevdalara...

Gün ışıkları ödünç gelse de

Yaşanmayan gecelere

Gözuçlarıyla aydınlatırdık

Tehir ettiklerimizi o mekanlarda.

Mahkumu olduk seve seve

Dizüstlerine ve  o muhteşem sineye

Muhabbetler kucaklaştı

Hep bu misafirhanede

Odalar utandı kararmaya

Utandı gören kumrular 

Dallarında sarılmaya

Anlattık onlara bu sevgiyi aheste aheste

Dostlar; 

Bu şarkıda ne güfte var ne de beste

Biz aynı anadan doğmadık ama

Cehennemleri öksüz bırakan

İki kardeşiz biz  işte...

                24.03.2003/Samsun', 'Şimdi biz  Seninle ikimiz Cehennem pusularına inat Cennet tuğlalarından  iki kişiyiz. Koşamayız aşk tarlalarında Mecnunları kıskandırmaya,  ...', ARRAY['Türk Edebiyatı','Şiir','Abdülhamit Kanca']::text[], 8.5, '{"poet":"Abdülhamit Kanca","poet_slug":"abdulhamit-kanca","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/iste-boyle-bir-kardes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ölünün Ağzından Ölüm Hikayesi', 'bir-olunun-agzindan-olum-hikayesi-murat-yakin-i13u5', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'En son öldügümde yazıyorum bunu

bu  seferki çok kötüydü bu ölüm yıkmıştı

çürütmüştü beni

ne yapacağımı bilmeden yatıyodum sırt üstü

önce çok ağlandı başımda

boynu bükük insanlar duruyor başucumda 

bense gülümsüyorum senin avuçlarında.

kaldırdılar bir arabaya bindirdiler 

ford mudu yada kaç modeldi bilmiyorum

bildiğim benim umutların bittiği beyazlar ülkesine götürülmemdi.

sürekli toprak atıyorlar üstüme çok kızdım ilk önce 

ve baktım beni getiren araba uzaklaşıyodu umutların bittiği yere gidiyodu herhalde 

dedimya kızmıştım ölünce ne kum atılsın istemiştim nede tahta bi kümesin içine sokulmayı deniza atılmak istemiştim kül olup savrulmayı

sonra dağıldı kalabalık, tek başımamı bırakılmıştım be konuşacak kimse yoktu herkes küsmüştü hayata yatıyodu sadece bekçi mehmet efendi dolaşıyodu başucumda

yıllar aylar günler geçti derken toprakla sıkı pıkı olduk iyice

ve beni benliğine kattı yavaş yavaş yiyice 

Şu kaç gündürde kendi mezarımın üstünde bi çiçeğe hayat

variyorum.

herkes beni içerde sanıyor ben küçük bi çiçeğin 

dalından gülümsüyorum her geçtiğinde

mehmet efendiye', 'En son öldügümde yazıyorum bunu bu  seferki çok kötüydü bu ölüm yıkmıştı çürütmüştü beni ne yapacağımı bilmeden yatıyodum sırt üstü önce çok...', ARRAY['Türk Edebiyatı','Şiir','Murat Yakın']::text[], 8.5, '{"poet":"Murat Yakın","poet_slug":"murat-yakin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-olunun-agzindan-olum-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Duvar', 'dort-duvar-murat-yakin-0i2u9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Karanlıklar içindeyim

üstüme, üstüme 

geliyo duvarlar tutamıyorum

önüne geçilmez duygular alıkoydu beni

şimdide seni seviyorum

unutamıyorum!', 'Karanlıklar içindeyim üstüme, üstüme  geliyo duvarlar tutamıyorum önüne geçilmez duygular alıkoydu beni şimdide seni seviyorum unutamıyorum!...', ARRAY['Türk Edebiyatı','Şiir','Murat Yakın']::text[], 8.5, '{"poet":"Murat Yakın","poet_slug":"murat-yakin","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dort-duvar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Garip Adama', 'o-garip-adama-murat-yakin-urqbv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çocukluğumun haylazlığında

koşardım sıcacık sobanın yanına, 

küçük bi aralıktan seyrederdim bulutları 

babam sokulurdu yanıma sorardım

bulutlar nereye gider diye? 

sessizce fısıldardı kulağıma evlerine diye gülerdim 

geçenlerdede, sordum mahallenin delisine

olgunlaşmış halimle sence babam nerelerdedir diye 

gösterdi bulutları belki oradadır diye şaşırdım

o günden bu yana simsiyah olunca bulutlar bi özlem içinde yağmasını beklerdi

bu köz tutmuş yüreğime', 'Çocukluğumun haylazlığında koşardım sıcacık sobanın yanına,  küçük bi aralıktan seyrederdim bulutları  babam sokulurdu yanıma sorardım bulut...', ARRAY['Türk Edebiyatı','Şiir','Murat Yakın']::text[], 8.5, '{"poet":"Murat Yakın","poet_slug":"murat-yakin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/o-garip-adama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yar', 'yar-vedat-bayrak-q73gm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sitem kuşlarını taşladım 

ah gönül

gam telin sızlıyor ciğerimde

bir sigara dumanı boğsun istiyorum

acıyla yoğrulmuş taş plaklar çınlasın

odam hiç ışımasın

seni bekliyorum ya

kara şeytanları kovaladım

senin gelmeyeceğini saldılar aklıma

bedenim hasretine kilitli

içimi titreten ayak seslerin 

anlara hiç inanmadım 

hala seni beklerim', 'sitem kuşlarını taşladım  ah gönül gam telin sızlıyor ciğerimde bir sigara dumanı boğsun istiyorum acıyla yoğrulmuş taş plaklar çınlasın oda...', ARRAY['Türk Edebiyatı','Şiir','Vedat Bayrak']::text[], 8.5, '{"poet":"Vedat Bayrak","poet_slug":"vedat-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yar-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşil Gözlüme', 'yesil-gozlume-unal-tuncel-croms', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gönül şehrim gül çitiyle çevrili

Hendeği duvarı kulesi yoktur

Beyaz seher kuşum cama vuranda

Yanında bir kulu kölesi yoktur.

Yanıp yanıp söner çoban ateşi

Yaşamaya küskün ölesi yoktır

Ömür duvarından taş çalar zaman

Neden bu işin molası yoktur

İşte kuşluk vakti karanlık çöktü

Yine de yüreğin yılası yoktur

Beyaz seher bülbülüm şakımayınca

Bahçemde güllerin gülesi yoktur

Sevdalım korktuğun yağmur başladı

Beklenen konuğun gelesi yoktur', 'Gönül şehrim gül çitiyle çevrili Hendeği duvarı kulesi yoktur Beyaz seher kuşum cama vuranda Yanında bir kulu kölesi yoktur. Yanıp yanıp sön...', ARRAY['Türk Edebiyatı','Şiir','Ünal Tunçel']::text[], 8.5, '{"poet":"Ünal Tunçel","poet_slug":"unal-tuncel","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yesil-gozlume-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜN GELİR BAYIM', 'gun-geli-r-bayim-i-hsan-i-lkin-b1866', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'GÜN GELİR BAYIM

Siz şüphesiz hürsünüz

Bir solucanın bir beyaz balığın

Yemin edersiniz yapışkan yanına

İnsan üzerine yemin edersiniz.

Sokaklara dökülen gençlerin 

Sloganları üzerine yemin edersiniz.

Parkların bahçelerin bankların 

Bir tadımlık sarhoşları üzerine 

Kocaman yeminler edersiniz

Amansız yeminler.

Şüphesiz hayretteyiz hepimiz

Kör bir dilenci kadar da olsa.

Biz birleri binler 

Binleri birler yaparız

Biz ayda oturur güneşi izleriz

Şüphesiz hayretteyiz hepimiz.

Siz rüyalarınızla yaşarsınız

Siz isteklerinizle bitmek bilmeyen

Biz saman arabasının ardında

Koşturan çocuklarız yorulmak bilmeyen

Sizin zindanınız ise toprak

Bizim aydınlığımız

Gözümüzü açtığımızdan beri dünyaya

Aynı minval üzereyiz bayım.

Biz kalbimizle yaşarız

Kar içimize yağar yağmur da

Siz aklınızla yaşarsınız

Bin yaşayın

Kar ne, yağmur ne bilir misiniz? 

Gün gelir elbet bayım

Aynı toprağın aynı kuyunun

Uzanacağız eşitçe içine

Toplanın emrini bekleyeceğiz.

		İhsan İlkin

		14.01.2003', 'GÜN GELİR BAYIM Siz şüphesiz hürsünüz Bir solucanın bir beyaz balığın Yemin edersiniz yapışkan yanına İnsan üzerine yemin edersiniz. Sokakla...', ARRAY['Türk Edebiyatı','Şiir','İhsan İlkin']::text[], 8.5, '{"poet":"İhsan İlkin","poet_slug":"i-hsan-i-lkin","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/gun-gelir-bayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'öfkenin dili', 'ofkenin-dili-vedat-bayrak-d919r', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'öfke ile kalkmışlığım var yerimden

taa! şehre kadar koştum 

çamurlu göl kenarından

bir hışımla

gözüm dönmüş bir kere

bu olmamalıydı ya 

nafile yüzüm, gözüm

elbiselerim sırılsıklam

bataklık kokusunda kurbağa sesleri

ay gökyüzünde yok

öfkem çok

kırık kalp, buruk yürek bitti

şimdi tam alma verme zamanı

ensesinde koşan gölgesi olmalıyım

yatağında uykusundan rahatlık çalmalıyım

bitmemeli, 

bu küpe

keskin sirke zarar vermemeli

ve öfkem dinmemeli', 'öfke ile kalkmışlığım var yerimden taa! şehre kadar koştum  çamurlu göl kenarından bir hışımla gözüm dönmüş bir kere bu olmamalıydı ya  nafi...', ARRAY['Türk Edebiyatı','Şiir','Vedat Bayrak']::text[], 8.5, '{"poet":"Vedat Bayrak","poet_slug":"vedat-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ofkenin-dili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'bugün gurbetin onaltısı', 'bugun-gurbetin-onaltisi-vedat-bayrak-5qcio', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'bugün gurbet, 

Sümeyye''yi seyrettim

anam diye bir çığlık koptu içimden

yüreğim bir doldu ki, sorma

boğuldum...gözyaşım içime aktı

seni istedei hislerim

kurşun yarası oldun beynimde

anam dedim canım anam

sen sardın benliğimi

alnım kırış kırış

parmaklarım titrek

içim burkrldu öylesine

anacım diye bir hıçkırık aktı içime

gırtlağım düğümlendi, kupkuru

aman dedi ciğerim ana

bugün hasretin onaltısı

Sümeyye''yi seyrettim

gözlerim doldu

sarardı benzim sanki

nutkum tutuldu

ana dedim, gurbet dedim

akşamların hüznü kapladı efkarlandım

sulandı gözkapaklarım

ülserim sancıdı şöyle bir

sana dua selamı yolladım

Allah gönderir ya ana

senin de bana dua ettiğini hissettim

anacım dedi gözyaşım

ağladım.', 'bugün gurbet,  Sümeyye''yi seyrettim anam diye bir çığlık koptu içimden yüreğim bir doldu ki, sorma boğuldum...gözyaşım içime aktı seni isted...', ARRAY['Türk Edebiyatı','Şiir','Vedat Bayrak']::text[], 8.5, '{"poet":"Vedat Bayrak","poet_slug":"vedat-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bugun-gurbetin-onaltisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'bitiremediğim', 'bitiremedigim-vedat-bayrak-vk9su', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yılgınlık biçti ömür tarlamı

afakanlarım, 

sen inciteceksin gözyaşlarımı

ağlarım.

içim tütsülenmiş, ürpertilerim

soğukta kanım bir damla buzul

sokul demek istedim, yanıma sokul', 'yılgınlık biçti ömür tarlamı afakanlarım,  sen inciteceksin gözyaşlarımı ağlarım. içim tütsülenmiş, ürpertilerim soğukta kanım bir damla buz...', ARRAY['Türk Edebiyatı','Şiir','Vedat Bayrak']::text[], 8.5, '{"poet":"Vedat Bayrak","poet_slug":"vedat-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bitiremedigim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlamlar', 'anlamlar-elif-sebnem-akal-8hdw6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hayat..., seçtiğimizdir, 

Kader...., savaşmadığımız

Sevmek yüzleşmek demek, 

O...., hep kaçtığımız....

Oysa her gün denk ölüme...

Yüzleşmeye korktuğumuz....

Gönülsüz beyaz bayrakla, 

Teslim olan kaderine, 

Kapı kolundaki eldir, 

Cesaret vermediğimiz.........

Sevmek....., ''kendini sevmektir''

Aynalarda gördüğümüz

Sonrası berrak bir nehir, 

Deli...deli....aktığımız

Derelikten çıktığımız....

Beyaz mermerlerde yazan, 

Tarihlerden anlam alan, 

Hayat......

Hayattır o zaman, 

Bir işe yaradığımız', 'Hayat..., seçtiğimizdir,  Kader...., savaşmadığımız Sevmek yüzleşmek demek,  O...., hep kaçtığımız.... Oysa her gün denk ölüme... Yüzleşmeye...', ARRAY['Türk Edebiyatı','Şiir','Elif Şebnem Akal']::text[], 8.5, '{"poet":"Elif Şebnem Akal","poet_slug":"elif-sebnem-akal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/anlamlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'göç', 'goc-vedat-bayrak-dqdxe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hadi sen de git

al başını uç

güz geldi ya

kırlangıca göç yaraşır, 

kapkara kırlangıca 

kapkara göç yaraşır', 'hadi sen de git al başını uç güz geldi ya kırlangıca göç yaraşır,  kapkara kırlangıca  kapkara göç yaraşır...', ARRAY['Türk Edebiyatı','Şiir','Vedat Bayrak']::text[], 8.5, '{"poet":"Vedat Bayrak","poet_slug":"vedat-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/goc-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'kime ne', 'kime-ne-vedat-bayrak-kts3b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ne ağaran bir saçım, ne aşina bir çehre

sevdanın çeşmesinden ayrı kaldım kime ne

gözden ırak bu derdi yaşadım katre katre

yüregimin bahçesi gül vermedi, kime ne', 'ne ağaran bir saçım, ne aşina bir çehre sevdanın çeşmesinden ayrı kaldım kime ne gözden ırak bu derdi yaşadım katre katre yüregimin bahçesi ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Bayrak']::text[], 8.5, '{"poet":"Vedat Bayrak","poet_slug":"vedat-bayrak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kime-ne-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Mektubu', 'ask-mektubu-erdal-alga-c0pgm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana yazdığım mektubun

Zarfını yapıştırmak için

Dudaklarımla ıslattığımı sanıyorlar

Oysa ben

Sen o mektubu açarken

Dokunacağın ince ve narin ellerini

Öpmeye çalışıyorum.', 'Sana yazdığım mektubun Zarfını yapıştırmak için Dudaklarımla ıslattığımı sanıyorlar Oysa ben Sen o mektubu açarken Dokunacağın ince ve narin...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ask-mektubu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Körü', 'ask-koru-erdal-alga-xcwbm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hipermetroptun

Uzaklaştım

Miyoptun

Yaklaştım

Ne söylenecek bir söz kaldı

Ne de yapılacak başka bir şey

Ben, elimden geleni yaptım.', 'Hipermetroptun Uzaklaştım Miyoptun Yaklaştım Ne söylenecek bir söz kaldı Ne de yapılacak başka bir şey Ben, elimden geleni yaptım....', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ask-koru-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dua', 'dua-erdal-alga-37qdb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tanrı her yerde derler

Öyle öğrettiler

Çocukluğumuzdan beri bize

Madem öyle

Neden elimizi açıyoruz

Hala ve boşuna, gökyüzüne!', 'Tanrı her yerde derler Öyle öğrettiler Çocukluğumuzdan beri bize Madem öyle Neden elimizi açıyoruz Hala ve boşuna, gökyüzüne!...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dua-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülen Yüz', 'gulen-yuz-erdal-alga-ioayf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kalbin kırıklarını yansıtan

Yüzdeki fay hatlarını

Kapatınca sis

Biz, sirke satanlar

En azından o anlık, tatildeyiz.', 'Kalbin kırıklarını yansıtan Yüzdeki fay hatlarını Kapatınca sis Biz, sirke satanlar En azından o anlık, tatildeyiz....', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gulen-yuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşli Gün', 'gunesli-gun-erdal-alga-x44sg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eğer Tanrı ağlamıyorsa

Ve eğer bulutlarsa yağmuru var eden

Bu gün güneş çıksın istiyorum

Berrak mı berrak

Ressam, sil ne olur bulutları

Semanın tuvalinden.', 'Eğer Tanrı ağlamıyorsa Ve eğer bulutlarsa yağmuru var eden Bu gün güneş çıksın istiyorum Berrak mı berrak Ressam, sil ne olur bulutları Sema...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gunesli-gun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzin Abla', 'guzin-abla-erdal-alga-ojm1j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Herkes Güzin Ablaya 

Derdini anlatıyor

Güzin Ablanın derdi var mı yok mu

Soran yok

Güzin Abla derdini kime anlatıyor acaba

Onun bir Güzin Ablası bile yok!', 'Herkes Güzin Ablaya  Derdini anlatıyor Güzin Ablanın derdi var mı yok mu Soran yok Güzin Abla derdini kime anlatıyor acaba Onun bir Güzin Ab...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/guzin-abla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayvansöver', 'hayvansover-erdal-alga-cfkyg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Üzerindeki kürkle

Hayvanseverler Derneğine 

Üye olmaya gitme

Hayvanlar söver.', 'Üzerindeki kürkle Hayvanseverler Derneğine  Üye olmaya gitme Hayvanlar söver....', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hayvansover-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlık Dersi', 'i-nsanlik-dersi-erdal-alga-47wat', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bize insanlık dersi verenler

Tarihlerini yoklasınlar

Unutmasınlar

Kızılderililere yaptıklarını

Sömürgeleri kimlerin kurduğunu

Ve de köleliğin hangi coğrafyalarda caiz olduğunu.', 'Bize insanlık dersi verenler Tarihlerini yoklasınlar Unutmasınlar Kızılderililere yaptıklarını Sömürgeleri kimlerin kurduğunu Ve de köleliği...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/insanlik-dersi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırkikindiler', 'kirkikindiler-erdal-alga-pl7o5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yükselirken sıcak hava

Üşür 1 derece

Her 200 metrede.

Her  çocuk ağlar

Donarken

Aç ve açıkta.

İlkbahar geldiğinde

Şenlenir İçanadolu

Ülkemin tahıl ambarı

Ağlamasın

Misket, zeybek oynayabilsin

Horon tepebilsin diye

Çocuklar.', 'Yükselirken sıcak hava Üşür 1 derece Her 200 metrede. Her  çocuk ağlar Donarken Aç ve açıkta. İlkbahar geldiğinde Şenlenir İçanadolu Ülkemin...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kirkikindiler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mart', 'mart-erdal-alga-nboql', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kazma kürek yaktırır derler

Saplar yandı eyvallah

Demir taraflar da yanar mı

Yanacaksa yandık vallah

Bahar gecikecek demektir.

Geceyi bir ses böler

Ağlamaklı, boğuk ama ateşli

Alabildiğine devam eder, artarak

Yakmak ister gibi erkek kedi

Dişisinin yüreğini.

21’ne girmiş genç bir adam

Ateşi keşfeder tekrar içinde

Isınsın diye yüreği

Bahar gelir önce, sonra aşk

Mevsimin haylaz çocuğu.', 'Kazma kürek yaktırır derler Saplar yandı eyvallah Demir taraflar da yanar mı Yanacaksa yandık vallah Bahar gecikecek demektir. Geceyi bir se...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/mart-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Masaj', 'masaj-erdal-alga-zw3ch', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Cep telefonunla 

Yüreğime attığın sevgi mesajı

Yumuşattı kalp kasımı

Adeta masaj.', 'Cep telefonunla  Yüreğime attığın sevgi mesajı Yumuşattı kalp kasımı Adeta masaj....', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/masaj-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nevruz', 'nevruz-erdal-alga-y3mjd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kış geçti

Karanlığın erken çöktüğü

Hayatın içe kapandığı

Sus pus zamanlar

Yürek üşüyerek.

Bir ateş yandı

Yaşama ateşi

Günü aydınlatarak

Renkler belirdi

Çocuklar tekrar koşacak.', 'Kış geçti Karanlığın erken çöktüğü Hayatın içe kapandığı Sus pus zamanlar Yürek üşüyerek. Bir ateş yandı Yaşama ateşi Günü aydınlatarak Renk...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/nevruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Petrol', 'petrol-erdal-alga-9fo1k', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Rengini kara sananlar

Yanılır

Körfez Savaşında gördüm

Senin rengin kıpkırmızıdır.', 'Rengini kara sananlar Yanılır Körfez Savaşında gördüm Senin rengin kıpkırmızıdır....', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/petrol-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ressama Sesleniş', 'ressama-seslenis-erdal-alga-sd635', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Fırçayı eline aldığında

Neyi çizersen çiz

Ama gökyüzü mutlaka olsun

Kuşların kanat çırpabildiği

Limansız şehirlerde yaşayan çocukların

Deniz kokusunu alabileceği.', 'Fırçayı eline aldığında Neyi çizersen çiz Ama gökyüzü mutlaka olsun Kuşların kanat çırpabildiği Limansız şehirlerde yaşayan çocukların Deniz...', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ressama-seslenis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk Alfabesi', 'turk-alfabesi-erdal-alga-i3hm3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğim ne zaman seni ünlese

Sessiz harfler iyice susuyor

8 büyüktür 21 olsun diye

Sevgi yazılabilsin diye

Yüreğindeki kitabeye, 

Öz Türkçe.', 'Yüreğim ne zaman seni ünlese Sessiz harfler iyice susuyor 8 büyüktür 21 olsun diye Sevgi yazılabilsin diye Yüreğindeki kitabeye,  Öz Türkçe....', ARRAY['Türk Edebiyatı','Şiir','Erdal Alga']::text[], 8.5, '{"poet":"Erdal Alga","poet_slug":"erdal-alga","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/turk-alfabesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'MEKTUP', 'mektup-seref-kaya-vg52s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir mektup bekliyorum senden, 

Mutluluk, beraberlik vadetsin, her sözünden.

Süphe! bahsetmesin kelimelerin, 

Inancinla sev, ugrunda ölmesini bilsin.

Cekinme; yazdan, bahardan, ask tan anlat, 

Doymasin her satirina, aglasada kahrindan.

Sevmiyorsan ümit ver, muhtac ona bu anda, 

Sen yüz cevirirsen, kalem, kagit ne yapsin.

                                                                             Seref  kaya

Onun icin agliyan.Ana, kardes ne yapsin

Onun da hakki sevsin, sevilsin.

Terk edilmis, deliden farksiz, 

Yalnizlik yikmis, sararmis beniz.

Gördüm gözlerimle kalmamis, 

Renk, nese, senlik.

Belki! Mutlu edersin sen, 

Anlat bolca hikaye dinlesin.

                                                    Seref kaya', 'Bir mektup bekliyorum senden,  Mutluluk, beraberlik vadetsin, her sözünden. Süphe! bahsetmesin kelimelerin,  Inancinla sev, ugrunda ölmesini...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/mektup-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'BIRAK BENI', 'birak-beni-seref-kaya-409vq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Birak beni, kaderimle, aci ceken bu halimle, 

Izdirabi iciyorum, göz yaslarimi sile, sile.

Seytan girmis kanimiza, ask derdi var kalbimizde, 

Birak beni, unutayim sensiz bir gün gülmesemde.

Nerden ciktin karsima, dertler actin basima

Askin bana zehir oldu, girdin benim sen kalbime

Ben kendimden kaciyorum, artik beni hic arama

Birak beni unutayim, aci cekip tek basima.

                                                                                Seref kaya', 'Birak beni, kaderimle, aci ceken bu halimle,  Izdirabi iciyorum, göz yaslarimi sile, sile. Seytan girmis kanimiza, ask derdi var kalbimizde,...', ARRAY['Türk Edebiyatı','Şiir','Şeref Kaya']::text[], 8.5, '{"poet":"Şeref Kaya","poet_slug":"seref-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/birak-beni-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayten', 'ayten-kaan-tekin-ocmb2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adı Aytendi genç kızın

Soyadını hiç öğrenemedim

Ve ayrıldık', 'Adı Aytendi genç kızın Soyadını hiç öğrenemedim Ve ayrıldık...', ARRAY['Türk Edebiyatı','Şiir','Kaan Tekin']::text[], 8.5, '{"poet":"Kaan Tekin","poet_slug":"kaan-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ayten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayan Yıldız', 'kayan-yildiz-fazli-coban-vzloz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Itır kokan gecede

             Çocuklar gökyüzünü seyreder

             Bir yıldız kayar

             Dilek tutar hepsi, sevgi üstüne', 'Itır kokan gecede              Çocuklar gökyüzünü seyreder              Bir yıldız kayar              Dilek tutar hepsi, sevgi üstüne...', ARRAY['Türk Edebiyatı','Şiir','Fazlı Çoban']::text[], 8.5, '{"poet":"Fazlı Çoban","poet_slug":"fazli-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kayan-yildiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitimsiz Sevgiler', 'bitimsiz-sevgiler-fazli-coban-i3fnd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dağ yamacında çoban ateşi, 

             Isıtırken yüreğini.

             Kızıla varmış bulutlar.

             Bir yarasa uçar, 

             Gün geceye ulanırken.

             Sigara dumanında uzak sevdalar, 

             Soluklanır, ney

             Çotanak yorgunluğu, 

             Alır, yeni doğan  çığlıklar.

             Bitimsiz sevmeler yok olmadan

             Eee, sesinde uyur çocuklar.', 'Dağ yamacında çoban ateşi,               Isıtırken yüreğini.              Kızıla varmış bulutlar.              Bir yarasa uçar,             ...', ARRAY['Türk Edebiyatı','Şiir','Fazlı Çoban']::text[], 8.5, '{"poet":"Fazlı Çoban","poet_slug":"fazli-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bitimsiz-sevgiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönemeyebilirim Eve', 'donemeyebilirim-eve-yasar-guclu-x79wo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir gün dönemeyebilirim eve

haberimi alırsın...

üzülme diyemem 

elbette üzülürsün ama

dağlamasın hasret ateşi yüreğini 

senden önce menzile vardığım için

sanma ki herkes ölür yatağında

belki de teslim olurum

yolda, işyerinde, otobüste, 

ya da bir hipermarkette 

alışveriş arabasının peşinde

modern kentliye yakışır şekilde

tüketme yarışındayken tükeniveririm', 'bir gün dönemeyebilirim eve haberimi alırsın... üzülme diyemem  elbette üzülürsün ama dağlamasın hasret ateşi yüreğini  senden önce menzile ...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Güçlü']::text[], 8.5, '{"poet":"Yaşar Güçlü","poet_slug":"yasar-guclu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/donemeyebilirim-eve-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçti', 'gecti-yasar-guclu-8kzzj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir tren geçti mutad tıkırtılarla

somurtan yolcular

boş gözlerle kaybolan umutlarını arıyorlardı

bıkkınlığı vardı üzerlerinde şehrin

gökyüzünde isten akbabalar uçuşurken

kuzular otluyordu yeşil çayırlarda

beyinlerinin bir köşesinde

doldurdular şehrin dumanını ciğerlerine

kayboldu bir parçası hayatımın

bir otomobil vınladı

tozları savurarak yüzüme

canavar düdüğünü çaldı

beynimin her hücresini ayaklandırmak istercesine

kaldırımlara da sahip olmak istiyordu

sürdü beni duvar diplerine

“çekil be adam” dercesine

yüreğimden bir şeyler kopardı

bir çocuk geçti sırtında çanta

elinde resim dosyası

okuldan geliyordu

dershaneye devam ediyordu 

belli ki akşamları

yüzünün süzgünlüğünden okunuyordu yorgunluğu

saklambaca, körebeye, birdirbire özlemi vardı

oyuncaklarla oynuyordu rüyalarında

çocukluğumdan bir şeyler eksildi

bir martı geçti tepemden

denizi yaladı ayakları

ve birden yükseldi iğrenircesine

insanların kiriyle lekelenmiş denizden

çığlık çığlığa uçtu 

güneşin ışıklarına

dünyamdan bir şeyler götürdü', 'bir tren geçti mutad tıkırtılarla somurtan yolcular boş gözlerle kaybolan umutlarını arıyorlardı bıkkınlığı vardı üzerlerinde şehrin gökyüzü...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Güçlü']::text[], 8.5, '{"poet":"Yaşar Güçlü","poet_slug":"yasar-guclu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gecti-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mübadele', 'mubadele-yasar-guclu-qobpf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yalnızlığın ortasında 

gece kırparken gözlerini 

bir gizemli sevgili gibi

garipliğe mahkum eden beni

ne gelir tutar ellerimden 

ne de bir lahza kalır köşede

yarasaların eşliğinde 

eteğini savurarak

uçar gider karanlıklara doğru

tüllenen şafaklarda

doğudan boy verirken umutlarım

yersiz aşkların peşinde

perişan ve süzgün 

kum fırtınasında yolunu yitirmiş

şaşkın  yolcu gibi

bir fasit dairenin girdabında dönüyorum

fasılasız.

sahte güneşlerin yörüngesinde

şimşek çakımı ömür

ışık hızıyla ölüm

ve bunlar için mezatta ebediyet

serbest piyasa ahlaksızlığında

öğrensek de alış verişin sırrını

çok geç

kandırılmışlığın hüznü içimde

satılan mal geri alınmaz

yaftası asılı dönülmez kapının üzerinde

pişmanlık

içimi kemiren bir kurt', 'yalnızlığın ortasında  gece kırparken gözlerini  bir gizemli sevgili gibi garipliğe mahkum eden beni ne gelir tutar ellerimden  ne de bir la...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Güçlü']::text[], 8.5, '{"poet":"Yaşar Güçlü","poet_slug":"yasar-guclu","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/mubadele-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzağımda Kal', 'uzagimda-kal-gazi-kizilcelik-harqi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzağımda kal

Hep ulaşacakmış gibi ama

Kapını her çalışta açacakmış gibi

Sevgimiz kısılmış bir gaz lambasının 

Işığı gibi sürsün 

Uzun zamanlar boyunca

Birlikte olmadan 

Ama hep birlikte olmayı 

Düşleyerek ve merak ederek

Sürdürelim bu yaşamı

Sonuna gelmeyelim hiç bu ilişkinin 

Yeni başlayacakmış gibi

Yeniden sarılıp kucaklaşacakmış gibi

Heyecan duyalım hep

Aklımız hep birbirimizde olsun

Telefonu değil 

Mektubu kullanalım haberleşmek için 

Özlemle bekleyelim postacıyı

Gelmediğinde üzülüp telaşlanalım

Uzağımda kal

Hep ulaşacakmış gibi ama

Kapını her çalışta açacakmış gibi', 'Uzağımda kal Hep ulaşacakmış gibi ama Kapını her çalışta açacakmış gibi Sevgimiz kısılmış bir gaz lambasının  Işığı gibi sürsün  Uzun zamanl...', ARRAY['Türk Edebiyatı','Şiir','Gazi Kızılçelik']::text[], 8.5, '{"poet":"Gazi Kızılçelik","poet_slug":"gazi-kizilcelik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/uzagimda-kal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DE Kİ EY BEZİRGAN', 'de-ki-ey-bezi-rgan-ali-capan-mw0wk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerinin rengine uygun kafiye aradığımı 

İnkar edersem yalan olur günaha girerim.

Yolum bir bedestene düştü.

Sordum satıcıya

-“Var mı sende sevdiğimin kızıla kaçan saç rengine 

Denkdüşen kenarları oyalı pembe bir yazma? ”

Dedi ki.-“Sen geç kaldın 

Dün gelen bir tüccar 

Hepsini de satın aldı yazmaların “

Ben sadece gül alırım gül satarım', 'Gözlerinin rengine uygun kafiye aradığımı  İnkar edersem yalan olur günaha girerim. Yolum bir bedestene düştü. Sordum satıcıya -“Var mı send...', ARRAY['Türk Edebiyatı','Şiir','Ali Çapan']::text[], 8.5, '{"poet":"Ali Çapan","poet_slug":"ali-capan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/de-ki-ey-bezirgan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'DÖRT UCU GÜL İŞLEMELİ MENDİLDİR', 'dort-ucu-gul-i-slemeli-mendi-ldi-r-ali-capan-y9mo9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne varsa dünde kaldı unutuldu yaşananlar

Ey yorgun şair dönüşü olmayan yollara 

Sürme şiirin al yeleli atını

Çünkü hüzün kenarları oyalı yazma /

Dört ucu gül işlemeli mendildir; 

Sevda çiçeklerini bir, bir sarıp sarmalayan', 'Ne varsa dünde kaldı unutuldu yaşananlar Ey yorgun şair dönüşü olmayan yollara  Sürme şiirin al yeleli atını Çünkü hüzün kenarları oyalı yaz...', ARRAY['Türk Edebiyatı','Şiir','Ali Çapan']::text[], 8.5, '{"poet":"Ali Çapan","poet_slug":"ali-capan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/dort-ucu-gul-islemeli-mendildir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'şehrazat', 'sehrazat-evrim-nisan-bxq1q', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kadıköy’de hep işi olan bir çift ayak gezinse

içimde nüfusu ikiye katlanır gidilecek yolların

herkesin beyninde ur halinde bir istanbul vardır

ayağa batan kırık cam keskinliğiyle acıtan

kan sermiş gibi yere düşünüyor yağmurlar

trakya’nın yedi göğsünden yalınayak damlayan

istanbul! kaç doktor hipokrat yeminli sende

hastasına tek bir sözle bir yaşam bağışlayan

bir kentin tüm sokakları öksürüyor sırtından

uzak yakın anlamlar...herşeyi çağrıştıran

oturup istanbul düşünmek perdesini çeker, ağır

yaşamın suni teneffüsüyle boğulan odaların', 'kadıköy’de hep işi olan bir çift ayak gezinse içimde nüfusu ikiye katlanır gidilecek yolların herkesin beyninde ur halinde bir istanbul vard...', ARRAY['Türk Edebiyatı','Şiir','Evrim Nisan']::text[], 8.5, '{"poet":"Evrim Nisan","poet_slug":"evrim-nisan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sehrazat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜZ BİR ŞARKIDIR', 'guz-bi-r-sarkidir-ali-capan-l3gjr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güz 

geceden önce gelen

akşam karanlığı başlamadan daha

sararan yapraklar düşmeden dalından

usul, usul yaklaşan 

eskimiş dostluklardan artakalan 

sevinç ve hüzün karışımı 

bir şarkıdır

canım efendim.

Güz

Sonbaharın son  gününde

Kemancının  ağlamadan çaldığı

Hüzzam  bir şarkıdan önce

Sana seni sevdiğimi söylediğim 

Geçiş taksimidir

Canım efendim.', 'Güz  geceden önce gelen akşam karanlığı başlamadan daha sararan yapraklar düşmeden dalından usul, usul yaklaşan  eskimiş dostluklardan artak...', ARRAY['Türk Edebiyatı','Şiir','Ali Çapan']::text[], 8.5, '{"poet":"Ali Çapan","poet_slug":"ali-capan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/guz-bir-sarkidir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GÜZ ÖLÜMÜN KARDEŞİ DEĞİLSE DE', 'guz-olumun-kardesi-degi-lse-de-ali-capan-y270s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Güz 

elli altı yaşında 

bu dünyadan göçüp gitmek midir

Yoksa daha gezip görülecek

yerler mi var dünyada

Yaşanacak güzel günler 

Parka oyuna götürülecek torunlar

koklanacak hanımeli fesleğenler

Güz; 

geçmiş zaman masalları anlatılan

Çocukluğumun kış gecelerini çağrıştıran 

Kırlangıçların ve leyleklerin göç ettiği

Mevsimin adı değil sadece. 

Ölümün kardeşi 

yada arkadaşı bence.

Sen ölümün habercisi misin 

Ey Güz

Söyle yolculuk mu var? 

Kimlerle öpüşüp koklaşayım

Geri dönüşü olmayan yollara

götürme beni

Söylenecek çok sözüm var daha

Şiirler yazmalıyım sevgiye aşka dair

Sararan yaprağa inat açan 

Güz güllerini koklayacağım.', 'Güz  elli altı yaşında  bu dünyadan göçüp gitmek midir Yoksa daha gezip görülecek yerler mi var dünyada Yaşanacak güzel günler  Parka oyuna ...', ARRAY['Türk Edebiyatı','Şiir','Ali Çapan']::text[], 8.5, '{"poet":"Ali Çapan","poet_slug":"ali-capan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/guz-olumun-kardesi-degilse-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'ŞİİRİME GÜZ DAMLADI', 'si-i-ri-me-guz-damladi-ali-capan-goasi', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ya ben ne yaparım sensiz

Beni yarı yolda bırakıp gidersen.

Güz gelir sırası geleni alıp götürür

Dönüşü olmayan yollara gül dökülür

Ne kadar kovmaya çalışsan da

Gelmiş dayanmıştır kapına

Adı ister ölüm ister güz olsun

Hoş geldi sefa geldi.

Ölümün  bir başka adı ayrılık

Tekrar kavuşmak ve kucaklaşmak

Öpüşüp koklaşmak olası değil.

Güz gelince sevdiğim dostlarım

Giderler birer, birer

Allahaısmarladık bile demeden.', 'Ya ben ne yaparım sensiz Beni yarı yolda bırakıp gidersen. Güz gelir sırası geleni alıp götürür Dönüşü olmayan yollara gül dökülür Ne kadar ...', ARRAY['Türk Edebiyatı','Şiir','Ali Çapan']::text[], 8.5, '{"poet":"Ali Çapan","poet_slug":"ali-capan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/siirime-guz-damladi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün''den Çok Yarın''dan Az', 'dun-den-cok-yarin-dan-az-mine-ozdemirtas-pfp1v', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçime hapsettiğim bütün kadınlar

Varlığını keşfedince saçlarını dağıttılar.

Çok değil... sadece

Ilık bir bahar meltemi gibi

Esip geçmendi bütün istedikleri.

Ama; içlerinden hiç biri; 

Bir daha asla dinmeyecek bir kasırganın

Oluşmakta olduğunu görmedi

Önce kızıla boyadın ufku

Sonra... gümbür, gümbür

Gök gürültüleriyle geldin.

Gelişinle... içimdeki kadınlar

Atomlarına kadar bölünüp parçalandılar.

İkimizde dünleri dünlere bıraktık.

Dönüş yok / Fırtınanın gözündeyiz artık.

Şimdi sana getirdiğim

Senin olan kadınların her biri

Safkan birer kısrak gibi / İstiyorlar seni.

Bundan sonra; 

? Dünden çok, Yarından az? Çoğalıp duracak sevgi

Savrulacağız birlikte Yoğun bir hortum misali, 

Mutluluğa yolculuk ürkütürse seni; al ellerimi

Düşmekten korktuğun anlar olursa eğer; 

Bana tutunabilirsin sevgili.', 'İçime hapsettiğim bütün kadınlar Varlığını keşfedince saçlarını dağıttılar. Çok değil... sadece Ilık bir bahar meltemi gibi Esip geçmendi bü...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/dun-den-cok-yarin-dan-az-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'CEVİZ DALINA SALINCAK KURDUM', 'cevi-z-dalina-salincak-kurdum-ali-capan-iyf5r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yorgunum çok yorgunum

Gelincik dalına konan kelebek

Senin peşinden koşamam artık

Hayatın ipi kısaldı

Ceviz ağacına salıncak 

Kuramam artık.

Uçurtma mevsimi geride kaldı

O eskidendi 

Köyde harman yerinde 

O tepenin yamacında

İlk bahar rüzgarlarına karşı

Uçurtma  uçurmanın sevinci

Çocukluğumun o en güzel

Günleri geri gelmez ki.

Söğüt dalından atıma binip

Dört nala koşturduğum

Tozlu yollar

Şimdi asfalt oldu

Soğuk sularında yıkanıp serinlediğim

Çay kurudu

Ve ben yoruldum artık.

Zamanın yorgun atının yelesinden

Tutunmuşum

Bu kaçıncı durak

Durup soluklandığım

Unutmuşum.

Sevda türkülerini

Sesimin son perdesine kadar

Bağırarak söylediğim

Barak ovasında

Şimdi yabani kuşlar uçuşuyor

Ve türkülerin boynu bükük.', 'Yorgunum çok yorgunum Gelincik dalına konan kelebek Senin peşinden koşamam artık Hayatın ipi kısaldı Ceviz ağacına salıncak  Kuramam artık. ...', ARRAY['Türk Edebiyatı','Şiir','Ali Çapan']::text[], 8.5, '{"poet":"Ali Çapan","poet_slug":"ali-capan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ceviz-dalina-salincak-kurdum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Yıllar', 'mutlu-yillar-tukenmez-kalem-8ar6i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıllar acıyı katlayarak seriyor önüme

Yıllar güzelim uzatıyor bu müebbeti

Ben çoktan vazgeçmişken sensiz yollardan

Her konakta sensizliğin acısı kadehimde

Ve her 1 Ocak sabahı Azraille yapılıyor antlaşma

Diyor ki daha çok acı için daha çok sene

Ve altına atıyor imzasını dalga geçercesine

Mutlu Yıllar!', 'Yıllar acıyı katlayarak seriyor önüme Yıllar güzelim uzatıyor bu müebbeti Ben çoktan vazgeçmişken sensiz yollardan Her konakta sensizliğin a...', ARRAY['Türk Edebiyatı','Şiir','Tükenmez Kalem']::text[], 8.5, '{"poet":"Tükenmez Kalem","poet_slug":"tukenmez-kalem","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/mutlu-yillar-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Bana Uzak', 'sen-bana-uzak-sezgin-keles-cv6e7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dünya iki adım sen bana uzak

Hiç bir şeye kanma hepsi bir tuzak.

Aklına bir gün  ben gelirsem, 

Beni düşünerek etrafına bak!', 'Dünya iki adım sen bana uzak Hiç bir şeye kanma hepsi bir tuzak. Aklına bir gün  ben gelirsem,  Beni düşünerek etrafına bak!...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Keleş']::text[], 8.5, '{"poet":"Sezgin Keleş","poet_slug":"sezgin-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-bana-uzak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzzam Şarkıların Kadınısın Sen', 'huzzam-sarkilarin-kadinisin-sen-munire-aksaray-1lxl5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güzel gözlerinde bir ıslak eylül

Duyguların ipek kanadısın sen

Sevdalardan yorgun argın bir gönül

Hüzzam şarkıların kadınısın sen

Sevdanın selinde delice yüzen

Çileli bir aşkın adımısın sen

İçli kemanımın telinde gezen

Hüzzam şarkıların kadınısın sen

Hüzünle çevrilmiş kırık çerçeven

Solgun bahçelerde bir yediveren

Dilimin ucuna hep geliveren

Hüzzam şarkıların kadınısın sen

(İstanbul 2001)', 'Güzel gözlerinde bir ıslak eylül Duyguların ipek kanadısın sen Sevdalardan yorgun argın bir gönül Hüzzam şarkıların kadınısın sen Sevdanın s...', ARRAY['Türk Edebiyatı','Şiir','Münire Aksaray']::text[], 8.5, '{"poet":"Münire Aksaray","poet_slug":"munire-aksaray","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/huzzam-sarkilarin-kadinisin-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biter Derlerdi', 'biter-derlerdi-sezgin-keles-oe5ft', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bu akşam yine hüzünlü bir akşam

Ama olsun alışacağız artık.

Ben bu sevda için kendimi yaktım, 

Canım fedadır sana al artık.

Biter derlerdi içtiğin zaman

Acıları bir kenara bıraktık.

Bu gönül hoş olsun samanlık seyran

Sevdanın üstüne çiçekler saldık.', 'Bu akşam yine hüzünlü bir akşam Ama olsun alışacağız artık. Ben bu sevda için kendimi yaktım,  Canım fedadır sana al artık. Biter derlerdi i...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Keleş']::text[], 8.5, '{"poet":"Sezgin Keleş","poet_slug":"sezgin-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/biter-derlerdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emek', 'emek-sezgin-keles-u5anp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kurtulmak bu kör kuyudan

Karanlıktan, cehaletten.

Çıkmak aydınlığa emeğimle.

Bir güneş gibi aydınlatmak isterdim çevremi, 

Bütün çırpınışlarımla, çalışarak...', 'Kurtulmak bu kör kuyudan Karanlıktan, cehaletten. Çıkmak aydınlığa emeğimle. Bir güneş gibi aydınlatmak isterdim çevremi,  Bütün çırpınışlar...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Keleş']::text[], 8.5, '{"poet":"Sezgin Keleş","poet_slug":"sezgin-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/emek-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendin Gibi Olmak', 'kendin-gibi-olmak-sezgin-keles-we0oi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kendin gibi ol! 

Çünkü daha güzel kendin gibi olmak.

Yaşamak herşeyi kendi benliğinle, 

Hür olup özgürce yaşamak.

Ufuklara açılmak bir yelken gibi, 

Sonsuzluğun maviliğini yaşamak.

Yaşamak mavinin bütün tonlarını, 

Kendi içinde yaşamak.', 'Kendin gibi ol!  Çünkü daha güzel kendin gibi olmak. Yaşamak herşeyi kendi benliğinle,  Hür olup özgürce yaşamak. Ufuklara açılmak bir yelke...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Keleş']::text[], 8.5, '{"poet":"Sezgin Keleş","poet_slug":"sezgin-keles","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kendin-gibi-olmak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'baharsiz kelebek', 'baharsiz-kelebek-yasin-kirmizi-7w18d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir cocugun gozlerinde dunya aglamakli

Bulutlar huznu gezdiriyor sokaklarda

Ayriliklar firar etmis bugun

Yanibasimda bir kelebek baharsizligi yasamakta

Kadersizim benim, kinali kekligim

Senin bahcelerinde guller solmus, bulbuller yasta

Ruzgarlar da postaciligi unutmus bu aksam.......

Gurbet ellerine gun dogmamakta

Zaman Azralille dost olmus kolkola

Yine ilaclarini getimeyi unutmus bu aralar

O bedbaht insanoglu herseyi kendine benzetmis

Sanal  besteler yapmis

Seni Buselikte dinleyenler yok simdi gulum

Bir cocugun gozlerinde dunya aglamakli

Bulutlar huznu gezdiriyor sokaklarda

Ayriliklar firar etmis bugun

Yanibasimda bir kelebek baharsizligi yasamakta

Sana bunlari anlatirken yuregim askin cenaze konvoyuna kosmakta! ! ! ! ! ! ! ! ! !', 'Bir cocugun gozlerinde dunya aglamakli Bulutlar huznu gezdiriyor sokaklarda Ayriliklar firar etmis bugun Yanibasimda bir kelebek baharsizlig...', ARRAY['Türk Edebiyatı','Şiir','Yasin Kirmizi']::text[], 8.5, '{"poet":"Yasin Kirmizi","poet_slug":"yasin-kirmizi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/baharsiz-kelebek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi git...', 'simdi-git-nebahat-yokus-q620i', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gideceksen şimdi git, yarını bekleme.

Aldın tüm güzellikleri elimden

Gitsende üzüleceğim, gitmesende. 

Gideceksen şimdi git, yarını bekleme.

Işıkları yakma, Gideceksen karanlıkta git.

Veda etmeden. 

Kapat bütün kapıları, dönüp bakmadan git.

Gideceksen şimdi git, yarını bekleme. 

Ne adın kalsın dilimde, 

Ne sevgin kalsın yüreğimde, 

Sadece anıda, bir resmin olsun üstü çizilmiş.

Gideceksen şimdi git, yarını bekleme', 'Gideceksen şimdi git, yarını bekleme. Aldın tüm güzellikleri elimden Gitsende üzüleceğim, gitmesende.  Gideceksen şimdi git, yarını bekleme....', ARRAY['Türk Edebiyatı','Şiir','Nebahat Yokuş']::text[], 8.5, '{"poet":"Nebahat Yokuş","poet_slug":"nebahat-yokus","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/simdi-git-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haberin yoktur Senin', 'haberin-yoktur-senin-aysenur-yazici-ds4jz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kadın karşında güzel, saf, narin

Üstelik yüreğini çalmışsın..

Avuçlarına tuba ağaçları dikmiş

Buluttan döşekte uyur yanında

Aklına tozşeker bulaşmış, 

Cismin cibinlik olmuş hayatına

Ruhu teninde kamaşmış...

Öl desen ölecek kadar

Sığınmış koluna...

Ne diye örselersin? 

   Bir melek konmuşken omuzuna

   Sen vefayı da bilmezsin..

Cefa çektirmeye ne dürter seni? 

Hangi akıl kıskanır karıncayı topraktan? 

Tutuşturmak için serin günleri

Hangi insan katar sevgiye kin? 

Aşk sokakta, üşümüş, bedbin

Muhtemelen ahiret gününden de

Haberin yoktur senin...', 'Kadın karşında güzel, saf, narin Üstelik yüreğini çalmışsın.. Avuçlarına tuba ağaçları dikmiş Buluttan döşekte uyur yanında Aklına tozşeker ...', ARRAY['Türk Edebiyatı','Şiir','Ayşenur Yazıcı']::text[], 8.5, '{"poet":"Ayşenur Yazıcı","poet_slug":"aysenur-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/haberin-yoktur-senin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'kapı', 'kapi-evrim-nisan-ag0my', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'benimde kapılarım var diyorsun arkasına sandalye dayanan olasılıklara  karşı      

benim de kapılarım var dışarda kalmaya ya da içerde kalmaya

birden açılan-ki bütün kapılar birden açılır- iklimler değiştirir

birden açıldı akşamdı, ölüyordum ne güzel, tahtadan bir kapıydı açıldı kapandı

rüzgarda sallandı, dağıldı, açık unutulmuş hırsız bayramıydı

ne diyecektim? kimdin? kapıya sıçradı sorgudan bir damla ter

ısrar etti. ısrar. her kapıda duvar ayrıtı bir anahtar deliği

kapılar çarpılmak içinse ilkel insanlar ne yapıyorlardı mağaralarında

kapılar ikiler içinse niye kapanırlar bir midye gibi teklerin yüzüne

sustu. sus pustu – gıcırdamıyordu bile- eksilterek kendini gürültüsünden

kapıyı biliyorsun ya niye anlatıyorum sana duvarın en zayıf yeri

kale surlarında bile olur koç boynuzlarıyla zorlanan

ben de sigara içerim ben de sabahlarım kimin açacağını bilmeyen bir kapı gibi

ben de titrerim gündüz gözüne akşam alacasına gecenin derdine bir kapı gibi

seni ormanda bulurlar o zaman, menteşelerin hariç tutunacak dalın mı kalmıştır

seni çalışma odalarına açılan sessiz tıkırtılarda bulurlar o zaman

ya seni içimde bulurlarsa! bulurlarsa işte o zaman kopar kıyamet

bütün kapılar çarpılır kayar ekseninden içimizdeki dünya- parçalanır-

belki kıta kayma teorisi oluruz her depremin ardından yerine oturan

belki daha iyi oluruz şimdi olduğumuzdan bir adım daha belirli

bir kapı açılır iyi oluruz bir yabancı gibi girersin içeri belki

yabancı mı? ama sanki ben seni daha önce bir iki kez öldüm

sanki daha önce yüz yılını erittik sahanımızda yalnızlığımızın

belki o zaman başladı kimbilir hangi kapının yabanıl telaşı

belki o zaman sustuk gülümsedik başka bir şiire taşıdık hüznü

doğrudur...sustuk avazı kadar açılan kapılardan kaçını geçtiysek

doğrudur kapılar ki size açılır bize açılır sessize açılır', 'benimde kapılarım var diyorsun arkasına sandalye dayanan olasılıklara  karşı       benim de kapılarım var dışarda kalmaya ya da içerde kalma...', ARRAY['Türk Edebiyatı','Şiir','Evrim Nisan']::text[], 8.5, '{"poet":"Evrim Nisan","poet_slug":"evrim-nisan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/kapi-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeytan Görsün Yüzünü', 'seytan-gorsun-yuzunu-erdogan-ciray-7g7ko', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne hayaller kurmuştuk

Sözler verip durmuştuk

Nasıl oldu ayrıldık

Yalnızlığı yormuştuk

Riya sarmış özünü

Tutamadın sözünü

Hadi yaylan güzelim

Şeytan görsün yüzünü

Eller sana tatlıymış

Düşündeki atlıymış

Yüzündeki maskeler

Katmer katmer katlıymış

Oysa sana tapmıştım

Başıma taç yapmıştım

Doğru giden yolumdan

Senin için sapmıştım

Şu dünyayı ettin dar

Senden bana olmaz yar

Yazdığım bu son şarkı

Benden sana yadigâr', 'Ne hayaller kurmuştuk Sözler verip durmuştuk Nasıl oldu ayrıldık Yalnızlığı yormuştuk Riya sarmış özünü Tutamadın sözünü Hadi yaylan güzelim...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Çıray']::text[], 8.5, '{"poet":"Erdoğan Çıray","poet_slug":"erdogan-ciray","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/seytan-gorsun-yuzunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kulakların Çınlıyormu', 'kulaklarin-cinliyormu-haci-ozturk-j0di5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine  kördüğüm  duygulara  büründüm, 

Şu  gün  batımlarında, 

Çaresiz   umutlarla, 

Dolaşıyorum  sensiz,, 

Ve  erkekliğimden  utanmadan

yutkunuyorum,,,,! 

Sen  doğan  çocuklarımın  anası, 

Evimin  direği, yuvamın  bereketi, 

Sana  öyle  özlem  doluyum ki,,,! 

Sorma,,,,,, 

Her  an, her  saat, 

Senli  düşler  sarıyor  benliğimi, 

Öylesine  anıyorum ki,,,,! 

Seninde   kulakların  çınlıyor mu,,,? 

Hacı  Öztürk                 İZMİR / 1980

KAYDEDEN                  Hacı   Öztürk

1', 'Yine  kördüğüm  duygulara  büründüm,  Şu  gün  batımlarında,  Çaresiz   umutlarla,  Dolaşıyorum  sensiz,,  Ve  erkekliğimden  utanmadan yutk...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kulaklarin-cinliyormu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmasın Yalan,,,', 'olmasin-yalan-haci-ozturk-nom2i', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seninle  yeşerdi  umut  çiçeklerim, 

Seninle  başladı  bende  bahar, 

Seninle  doğdu  güneş  yarınlarıma,, 

Sen  verdin  en  güzel  düşleri, 

Senini  sayende  öğrendim  sevmeyi

Ne  olur  bu  düşler  yalan  olmasın,,,,, 

Ayrılık    bulutları  kalksın  aradan, 

Gözyaşlarımın  son  damlasına  kadar, 

Uzat  bana  tütün  kokan  ellerini,, 

Ve   o  elleredeki   mutluluk,,,,! 

Ne  olur  yalan   olmasın.....

Hacı   Öztürk                 İZMİR / 1980

KAYDEDEN                Hacı   Öztürk', 'Seninle  yeşerdi  umut  çiçeklerim,  Seninle  başladı  bende  bahar,  Seninle  doğdu  güneş  yarınlarıma,,  Sen  verdin  en  güzel  düşleri,...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/olmasin-yalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söyle Be Adam', 'soyle-be-adam-lora-mora-znpje', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kendine göre haklı tarafların vardır

hatasız kul olmaz mutlaka hatalıyımdır

Ama söylermisin? Bu kadar mı yapılır? 

Sevgisiz saygısız böylemi yaşanır? 

Sen görmüş geçirmiş bir adamsın aslında

Söylediğin gibi dünyanın kıçına parmak atmışsında! 

Şimdi artık bir durulsanda! 

Gözünü açıp çevrene şöyle bir baksanya

Güzel şeyler var aslında çevrende ama

Göremezsen yeşillikler bile kuru ot sana! 

Doya doya gülerdim bir zamanlar yanında

Konuşurdum korkmadan karşında

Şimdi ne oldu canım ne oldu sana? 

Güzel günler bize haram artık

Anladığım kadarıyla! ! !', 'Kendine göre haklı tarafların vardır hatasız kul olmaz mutlaka hatalıyımdır Ama söylermisin? Bu kadar mı yapılır?  Sevgisiz saygısız böylemi...', ARRAY['Türk Edebiyatı','Şiir','Lora Mora']::text[], 8.5, '{"poet":"Lora Mora","poet_slug":"lora-mora","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/soyle-be-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Yazık', 'ne-yazik-lora-mora-yp03m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne yazık seviyorum seni hala diyemiyorum

Ne yazık artık sohbet bile edemiyorum

Saygısız günlerde sevgisiz yaşıyorum

Ne yazık sevdiğim ben artık sevinemiyorum

Güzel günler çok geride kaldı biliyorum

Ne yazık hiç düzelmeyecek kötü bir yoldayız

Görüyorum! 

Ne yazık ne yazık demekten başka birsey yapamıyorum! !', 'Ne yazık seviyorum seni hala diyemiyorum Ne yazık artık sohbet bile edemiyorum Saygısız günlerde sevgisiz yaşıyorum Ne yazık sevdiğim ben ar...', ARRAY['Türk Edebiyatı','Şiir','Lora Mora']::text[], 8.5, '{"poet":"Lora Mora","poet_slug":"lora-mora","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ne-yazik-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyordum', 'biliyordum-hafize-zuluflu-w9ibl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biliyordum

Biliyordum

Mutlaka bir gün sen

Habersizce, zamansızca

Giriverecektin  o kapıdan

Yüzünde gülümseyişle

Gelecektin

Zambaklar açtığında

Biliyordum', 'Biliyordum Biliyordum Mutlaka bir gün sen Habersizce, zamansızca Giriverecektin  o kapıdan Yüzünde gülümseyişle Gelecektin Zambaklar açtığın...', ARRAY['Türk Edebiyatı','Şiir','Hafize Zülüflü']::text[], 8.5, '{"poet":"Hafize Zülüflü","poet_slug":"hafize-zuluflu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/biliyordum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Doğmadan,,,', 'gun-dogmadan-haci-ozturk-0yxro', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün  ağarıyor  gün,, 

Gideceğim  birazdan, 

Gözlerin  ardıma  takılacak, 

Kısılacak  usulca  nefesin, 

Ardımdan  gitme  kal  diyeceksin, 

Yalnızlık  öldürür  beni,,, 

Gitme  kal  desende  mecburum,,, 

İşte  güneşte  doğuyor, 

Ayıracak  beni  senden, 

Kaybolacak  senli  düşler,, 

Çseresiz,,,! 

Bütün  şafaklar  gibi, 

Yine  sensiz  uyanacağım,,,,! 

GÜN  DOĞMADAN,,,, 

Hacı    Öztürk             İZMİR /1980

KAYDEDEN          Hacı   Öztürk', 'Gün  ağarıyor  gün,,  Gideceğim  birazdan,  Gözlerin  ardıma  takılacak,  Kısılacak  usulca  nefesin,  Ardımdan  gitme  kal  diyeceksin,  Ya...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gun-dogmadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Aradım Hep Seni,,', 'seni-aradim-hep-seni-haci-ozturk-l2poi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaşaran   gözlerimin, 

Islak   perdelerinden, 

Deyada   martılar  gibi, 

Seni   aradım,,,,! 

Bazen  gecenin, 

Tek  yıldızı  gibi, 

İsmini  haykırdım,, 

Yalvardım  ağladım,,,,! 

Kaldırım  yaşlarına, 

Sordum  seni,, 

Darağacına  astım, 

Çaresizliğimi,,,! 

Saçlarım  tarumar, 

Bedenim   harap, 

Ak  kağıtlara   seni,,, 

YAZIPTA,,,,! 

SENİ  ARADIM  HEP  SENİ,,,, 

Hacı   Öztürk                   İZMİR /1980

KAYDEDEN                  Hacı   Öztürk', 'Yaşaran   gözlerimin,  Islak   perdelerinden,  Deyada   martılar  gibi,  Seni   aradım,,,,!  Bazen  gecenin,  Tek  yıldızı  gibi,  İsmini  h...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/seni-aradim-hep-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Yüreğim', 'hasret-yuregim-haci-ozturk-o94xc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hasret  mevsimini  yaşıyorum, 

Sensiz  gecelerimde  fırtınalar  esiyor,, 

Alıp  düşüncelerimi götürür  sana, 

Haykırmak  istiyorum  ama  nafile,,,! 

Sessiz  sedasız  durma  öyle, 

Hasretin  bir  kördüğüm  yüreğimde, 

Özlem  türküleri  dökülüyor  dudağımdan, 

Şimdi   karanlıklar  çöktü, 

Kestane  rengi  gözlerime, 

Sensizlik  sabahsız  gecelere  mahkum  etti, 

Boynum  bükük umutlarımı  yitirdim,,! 

Susturamıyorum, susturamıyorum, 

Sana  hasret   yüreğimi,,,,,! 

Hacı   Öztürk                      İZMİR /1980

KAYDEDEN                    Hacı   Öztürk', 'Hasret  mevsimini  yaşıyorum,  Sensiz  gecelerimde  fırtınalar  esiyor,,  Alıp  düşüncelerimi götürür  sana,  Haykırmak  istiyorum  ama  naf...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hasret-yuregim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biri Var Biri', 'biri-var-biri-haci-ozturk-i1966', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdi  biri  var seni  arayan, 

Yana  yakıla  seni  çağıran, 

Her  gün  doğuşunda ve  batımlarında, 

Yüreğine  bıçaklar  saplanan, 

Biri  var, biri  seni  arayan,,,,! 

Şimdi  biri  var  uzakta, 

Yeşile  vurgun    yeşile  hasret,, 

Başı  köpük, köpük  gözleri  bulut, 

Bir  var  seni  soruyor  duyuyormusun,,? 

Senden  kilometrelerce  uzakta, 

Yüreğine  bıçaklar  saplanan, 

Biri  var  biri  seni  arayan....

Hacı   Öztürk                    İZMİR /1980

KAYDEDEN                   Hacı  Öztürk', 'Şimdi  biri  var seni  arayan,  Yana  yakıla  seni  çağıran,  Her  gün  doğuşunda ve  batımlarında,  Yüreğine  bıçaklar  saplanan,  Biri  va...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/biri-var-biri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşımı Sormayın Yaşamadım ki Ben,,,', 'yasimi-sormayin-yasamadim-ki-ben-haci-ozturk-cr8vl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öyle  kolay  sanırdım  bu  genç  taşımda, 

Yüce  dağları aşar  düze  çıkar  sanırdım.

Ölüp    gideceğim    günün     birinde, 

Yaşımı  sormayın  yaşamadım ki  ben.

Vakitsiz   beyazlar   düştü  saçıma, 

Çekilmez  ne dert  varsa  geldi  başıma, 

Ölünce    yazın    mezar     taşıma, 

Yaşımı  sormayın  yaşamadım ki  ben.

Çile  cefa  dert  benim  arkadaşım, 

Yokluk   fakirlik   oldu  yoldaşım, 

İçin  için  akar  durmaz  gözyaşım, 

Yaşımı  sormayın  yaşamadım ki  ben.

''Hacım,, böyle  kendini  salma  diyorlar, 

Muhanetin  suyu  acıdır  içme  diyorlar, 

Ölüm  hepimiz  için   korkma  diyorlar, 

Yaşımı  sormayın  yaşamadım ki  ben.

Hacı   Öztürk                 İZMİR /1998

KAYDEDEN                Hacı   Öztürk', 'Öyle  kolay  sanırdım  bu  genç  taşımda,  Yüce  dağları aşar  düze  çıkar  sanırdım. Ölüp    gideceğim    günün     birinde,  Yaşımı  sorma...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yasimi-sormayin-yasamadim-ki-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zordur Be Gurban,,,,!', 'zordur-be-gurban-haci-ozturk-dxzlx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Başın  dişin  ağrırsa  vardır  çaresi, 

Hasretlikte  daralır  göğüs  kafesi, 

Özlem, sıla  kokar  insanın  nefesi, 

Gurbette  erkeklik  zordur be gurban.

Burada  bir  hoş  olur  akşam  sefası, 

Nereye  baksan  karşında  bulursun  yarı, 

Kalmazsa  elinde  tutunacak  dalın, 

Gurbette   erkeklik  zordur  be  gurban.

Feryadını   duyarsa  duyar  sadece  kum, 

Koğuşa    girdiğimde    daralır     ruhum, 

Bu  senede  çöllere  olmuşum   mahkum, 

Gurbette  erkeklik   zordur  be  gurban.

''Hacım,, der kör  olsun  şu  yokluğun  gözü, 

Yanar,  yanar   durur   hasretlik    közü, 

Kırk   yılda  bir  dinlemezsen  avrat  sözü, 

Gurbette  erkeklik  zordur  be  gurban.

Hacı   Öztürk                   LİBYA /01-06-2002

KAYDEDEN                     Hacı   Öztürk', 'Başın  dişin  ağrırsa  vardır  çaresi,  Hasretlikte  daralır  göğüs  kafesi,  Özlem, sıla  kokar  insanın  nefesi,  Gurbette  erkeklik  zord...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/zordur-be-gurban-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-tarik-akgun-2jlwq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'yoksa nasil zannedersin, 

beraberken cabuk gecen zamanin bir

hilesi oldugunu bilmedigimi, 

hasret zamanlarin ezip gectigini.', 'yoksa nasil zannedersin,  beraberken cabuk gecen zamanin bir hilesi oldugunu bilmedigimi,  hasret zamanlarin ezip gectigini....', ARRAY['Türk Edebiyatı','Şiir','Tarik Akgun']::text[], 8.5, '{"poet":"Tarik Akgun","poet_slug":"tarik-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zaman-61-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'hayat', 'hayat-tarik-akgun-oeyhy', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hayat acayip birsey, 

suda seken yasamlar...

dost dedim de, 

sevgilinin umursamazligina iliklenen 

yavan sevgi ceketine benzermi be..

ozlem dedikleri bu olsa gerek

bizi hayata baglayan kopru misali

kalbim artik benden cikti, sevenlerimin oldu', 'hayat acayip birsey,  suda seken yasamlar... dost dedim de,  sevgilinin umursamazligina iliklenen  yavan sevgi ceketine benzermi be.. ozlem ...', ARRAY['Türk Edebiyatı','Şiir','Tarik Akgun']::text[], 8.5, '{"poet":"Tarik Akgun","poet_slug":"tarik-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayat-84-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'uyku', 'uyku-tarik-akgun-v5yhh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'birazdan uyurum, 

yatiyorum, 

orada henuz erkendir

kimbilir belkide gectir.

dus ile gercek arasinda-sindir.

bilki ben uyusam da

gozum sana aciktir.', 'birazdan uyurum,  yatiyorum,  orada henuz erkendir kimbilir belkide gectir. dus ile gercek arasinda-sindir. bilki ben uyusam da gozum sana a...', ARRAY['Türk Edebiyatı','Şiir','Tarik Akgun']::text[], 8.5, '{"poet":"Tarik Akgun","poet_slug":"tarik-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/uyku-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaylule Suları', 'kaylule-sulari-omer-lutfi-mete-3w4f3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Toprak döşek, taş yastık

Huzme emziren ağaç

Dünyayı dala astık

Bir saatlik bir ilaç

Oruç bozmayan su

Peygamber uykusu

Peygamber uykusu

Büründük gölgemize

Güneş bakarken dimdik

Uzandığımız göze

Gönül dağında geldik

Yar eteğinden su

Peygamber uykusu

Peygamber uykusu

Birkaç pamuk bulutla

Sarılır göz yaramız

Ten kavgasına mola

Dalıp dolmak sıramız

Rüzgar yüzdüren su

Peygamber uykusu

Peygamber uykusu', 'Toprak döşek, taş yastık Huzme emziren ağaç Dünyayı dala astık Bir saatlik bir ilaç Oruç bozmayan su Peygamber uykusu Peygamber uykusu Bürün...', ARRAY['Türk Edebiyatı','Şiir','Ömer Lütfi Mete']::text[], 8.5, '{"poet":"Ömer Lütfi Mete","poet_slug":"omer-lutfi-mete","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kaylule-sulari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'kahve', 'kahve-tarik-akgun-4f06e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'zaman zaman sütsüz nescafelere

sigaralar ilistiriyorum, 

bir iki kadinla tanistim 

özrü kabahatinden büyük sevdalar iste, 

beni bilirsin, 

boyle uzun saclara tarak olmadim hic, 

tutupta kolundan getiremem ki, 

özlenmeyi beklemek aci..

öyle birini sevmisim ki, 

öyle bir sevmisim ki, 

lugatima oyle bir girdiki cikmiyor', 'zaman zaman sütsüz nescafelere sigaralar ilistiriyorum,  bir iki kadinla tanistim  özrü kabahatinden büyük sevdalar iste,  beni bilirsin,  b...', ARRAY['Türk Edebiyatı','Şiir','Tarik Akgun']::text[], 8.5, '{"poet":"Tarik Akgun","poet_slug":"tarik-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kahve-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'huzun', 'huzun-tarik-akgun-qcz3o', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu ciglik cigliga dalgalar, 

hüzünlü güzel martilar, 

rüzgara carpip gelip doluyorlar kalbime, 

yalnizim ucurumun kiyisinda, 

hayat ve olum arasinda 

tum hayatim akip geciyor ayaklarimin altindan

kar tanesi o kadar yolu ucup dudagima 

konmus, 

eriyipgitmis sonra...

hayat ögrenciligide

boyle birsey

biraktim artik 

yolumda ilerliyorum 

benim eksikligim degil,', 'bu ciglik cigliga dalgalar,  hüzünlü güzel martilar,  rüzgara carpip gelip doluyorlar kalbime,  yalnizim ucurumun kiyisinda,  hayat ve olum ...', ARRAY['Türk Edebiyatı','Şiir','Tarik Akgun']::text[], 8.5, '{"poet":"Tarik Akgun","poet_slug":"tarik-akgun","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/huzun-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Esirgedin', 'esirgedin-suleyman-sicimli-p9bdz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben beni verdim sana

Sen seni esirgedin

Gülleri sundum sana

Dikeni esirgedin

Gözüm her an gözünde

Ötesi hayalimde

Ay parçası gamzede

Gülmeyi esirgedin

Diyemedim, yutkundum

Sandım sana vuruldum

Boşuna biryan oldum

Bilmeyi esirgedin

Yasaksın anlıyorum

O yüzden gidiyorum

-Aslında biliyorum

Demeyi esirgedin', 'Ben beni verdim sana Sen seni esirgedin Gülleri sundum sana Dikeni esirgedin Gözüm her an gözünde Ötesi hayalimde Ay parçası gamzede Gülmeyi...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Sicimli']::text[], 8.5, '{"poet":"Süleyman Sicimli","poet_slug":"suleyman-sicimli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/esirgedin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dön Bak Arkana', 'don-bak-arkana-haci-ozturk-3j0h2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Zalim  gurbet  bilmemki acep sende  ne  var,,? 

Gelen   insanların   hep  boynu  bükülmektedir, 

Merak  edip  adını  duyan    sana  geliyor, 

Ayakta   duramayıp    hep    yıkılmaktadır,,,, 

Kimi  inat  uğruna bir  türlü  gitmek  bilmiyor, 

Geceler   azptır   sevene   bitmek  bilmiyor, 

Özlem  ateşi  yakar  özümü  sönmek  bilmiyor, 

Sessiz    sedasız   yanalar   hep    görülmektedir,,, 

Ağlamak  yakışmaz  derler  bilirim  merde, 

Dertsiz  olan  gurbette  düşüyor  derde, 

Gelmyeceğim  diyor  gittiği  her  seferde, 

Yinede    hırsına     hep     yenilmektedir,,, 

''Hacım,,  zaten   ezelden   beri  fukara, 

Burada   insanın  dini yok  imanı   para, 

Unutma  her   şeyi  bir  dön  bak  arkana, 

Seni   özleyenler  dötr  gözle   beklemektedir,,, 

Hacı   Öztürk                      LİBYA/ 26-05-2002

KAYDEDEN                       Hacı   Öztürk', 'Zalim  gurbet  bilmemki acep sende  ne  var,,?  Gelen   insanların   hep  boynu  bükülmektedir,  Merak  edip  adını  duyan    sana  geliyor,...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/don-bak-arkana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahırda Benim....', 'kahirda-benim-haci-ozturk-iwwyq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşüne     düşüne  yoruluyorum, 

Bir  çıkar  yol  olsun  bulamıyorum, 

Ellemeyin   beni  bende  kalayım, 

Her şey  sizin  olsun  kahırda  benim.

Değer  verdim  gurbette  insanoğluna, 

Çile  çekerde  bilmez  kendikendine, 

Yaptığı  işle  onur duyar  satar  özünü, 

Her şey  sizin  olsun  kahırda   benim,,, 

Oluruna  uydum  burada  olmaz  insanın, 

Kessenizde  akmak  bilmez ki  kanım, 

Bir   dost  bulsam  keşke verirdim  canım, 

Her şey  sizin     olsun     kahırda    benim,,, 

''Hacım,, der   nedir  bu kadar   telaşın, 

Yanar, yanarda   sönmez  ataşın, 

Sahtekar   düzenbazla   olmaz ki  işim, 

Her   şey   sizin   olsun  kahırda   benim,,,, 

Hacı    Öztürk                      LİBYA/15-05-2002

KAYDEDEN                      Hacı    Öztürk', 'Düşüne     düşüne  yoruluyorum,  Bir  çıkar  yol  olsun  bulamıyorum,  Ellemeyin   beni  bende  kalayım,  Her şey  sizin  olsun  kahırda  be...', ARRAY['Türk Edebiyatı','Şiir','Hacı Öztürk']::text[], 8.5, '{"poet":"Hacı Öztürk","poet_slug":"haci-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/kahirda-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babam', 'babam-cevat-capan-sfm5b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Babam iki tek atınca oğlum hadi seni karpuzlara götüreyim derdi..

(karpuzlar Gebzede oturan kızlardı) 

Annem kızarır kızar''bey çocuk daha küçük''diya çıkışır mutfağa gider ağlardı...

Babam karpuzdan anlardı.', 'Babam iki tek atınca oğlum hadi seni karpuzlara götüreyim derdi.. (karpuzlar Gebzede oturan kızlardı)  Annem kızarır kızar''bey çocuk daha kü...', ARRAY['Türk Edebiyatı','Şiir','Cevat Çapan']::text[], 8.5, '{"poet":"Cevat Çapan","poet_slug":"cevat-capan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/babam-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine Ölesiye', 'oylesine-olesiye-fazil-husnu-cakiroglu-4tozs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Korku dilsiz öfke sagirken, 

Cekip gitmek var öylesine.

Herseyi birakip, 

Uzun bir carsafa dolanip.

Yasanmisliklari yok sayan

Uzaklara inat.

Öylesine gitmek, 

Avaz avaz yada dilsiz lal.

Bükemedigin demiri, 

Tutamadigin eli, 

Öpemedigin bebegi, 

Egdim sayip.

Tuttum sayip.

Öptüm sayip.

Cekip gitmek öylesine, 

Bagira bagira avaz avaz.

Uzun bir carsafa dolanip, 

Apansiz yol alip.

Cekip gitmek var ölesiye.

Avaz avaz yada dilsiz lal.', 'Korku dilsiz öfke sagirken,  Cekip gitmek var öylesine. Herseyi birakip,  Uzun bir carsafa dolanip. Yasanmisliklari yok sayan Uzaklara inat....', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Çakıroğlu']::text[], 8.5, '{"poet":"Fazıl Hüsnü Çakıroğlu","poet_slug":"fazil-husnu-cakiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oylesine-olesiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kül Ve Duman', 'kul-ve-duman-fazil-husnu-cakiroglu-swdfr', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kül ve duman

Yasadiklarimdan arta kalan.

Biri göge asli isli, 

Digeri topraga karismis pasli.

Ikiside yönsüz ikiside dokunaksiz.

Yasanmis ve bitmis.

Elimde tek kalan! 

Kül ve duman.

Ve uzak sehrin, 

Deniz islagi kivrimli yollarinda

Göcebe yasamlar.

Ve ayrilanlar

Denize bakan yamacta uzananlar.

Yanlizlik denize bakan bir kapinin

Artik el tutulmayan tokmagindami? 

Yoksa daglara bakan pencere kapaklarinin

Derin gicirtisindami? 

Ve yanan evde yandi cocuklugum

Asili kaldi birseyler isli ocagin isli demirine.

Ölülerin bile gömülmedigi o yerde, 

Ne daglara gicirdiyan pencere kapaklari

Nede dokunaksiz kapi tokmagi.

Herseyden arta kalan simdi

Yanlizca kül ve duman.

                                      25.03.2003', 'Kül ve duman Yasadiklarimdan arta kalan. Biri göge asli isli,  Digeri topraga karismis pasli. Ikiside yönsüz ikiside dokunaksiz. Yasanmis ve...', ARRAY['Türk Edebiyatı','Şiir','Fazıl Hüsnü Çakıroğlu']::text[], 8.5, '{"poet":"Fazıl Hüsnü Çakıroğlu","poet_slug":"fazil-husnu-cakiroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/kul-ve-duman-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çarşamba Gözlü Ali', 'carsamba-gozlu-ali-cengiz-oyke-rkrbd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben Iraklı Ali 

Anamın öksüz Alisiyim

Gözlerim bir çarşamba gecesi kadar kara

Bir perşembe sabahı kadar aydınlık.

Garip anam bana hep Kara gözlü Alim diyecek yerde

Çarşamba gözlü Alim derdi.

Garip  kadındı şu anam

Her çarşamba gecesinde

Sandığından babamın resmini çıkartır.

Avazının çıktığı kadar bağırırdı.

Kara gece, katil gece, kara çarşamba

Karabasan gibi çöktün üstüme derdi

Sanki hiç bir şey olmamışcasına 

Perşembe sabahı  boynuma sarılıp

Çarşamba gözlü Alim

Sende olmasaydın  ne olurdu halim

Yıllarca Anamın  bu garipliğini

Bir gece ortasında  çıldırışını, çaresizliğini

Yine bir sabahın aydınlığında 

Bir çocuk kadar sevindiğini

Hep  merak ettim durdum 

Ona hep 

Ana neden kara çarşamba

Neden çarşamba gözlü Ali

Neden kara gözlü Alim demezsin

Söyle anam gözlerimi niye sevmezsin

Oysa ben o gözlerle dünyaya sevgi dolu bakarım

Anam canım anam ben daha on iki yaşımdayım.

Eğer incitiyorsa gözlerim seni

Onları yuvasından sökerim.

Yine bir çarşamba gecesi 

Anam aldı karşısına beni

Ağlamadı bağırmadı çağırmadı

Ve ilk defa 

Kara gözlü Alim dedi bana

Bu gece çek git buralardan

Komşular yola çıkacak

Sende git yavrum, sende 

Niye ana, Ya sen,  ya vatan

Ya kara toprakta yatan  babam ne olacak

Nasıl giderim ana nasıl

Bak oğul tam on iki yıl evvel

Bir çarşamba  gecesi kızılca kıyamet koptu başımızda

Bombalar yağıyordu tepemizde

Babanı o zama kaybettim.

Yine aynı gecenin sabahında

Bir perşembe aydınlığında

Bir hastane köşesinde

Sen dünyaya geldin

Kara gözlüm git bu gece

Çarşambalar artık aydınlık olsun

Olmaz anam gideceksek beraber gidelim

Öleceksek beraber ölelim

Olmaz yavrum ben yaşımı aldım

Türkiyeye git orda insanlık varmış

Hep öyle diyor herkes

Onlarda bizi kardeş bilip 

Barış için uğraşırlarmış.

Git oğlum birde  sana yanmayayım

Sana iyi baksınlar

O vatana bir de ben yük olmayayım.

Hey her memleketin başkanları

Ben kara gözlü Ali, Anamın Alisi

On iki yaşımdayım 

Sizin kara gözlü Alileriniz yokmu.

Beni babasız bıraktınız

Anama can feda

Anamı Alisiz koymayın.

		Cengiz ÖYKE

		  10.02.2003', 'Ben Iraklı Ali  Anamın öksüz Alisiyim Gözlerim bir çarşamba gecesi kadar kara Bir perşembe sabahı kadar aydınlık. Garip anam bana hep Kara g...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Öyke']::text[], 8.5, '{"poet":"Cengiz Öyke","poet_slug":"cengiz-oyke","theme":"Türk Şiiri","is_hero":false,"total_lines":70,"source_url":"https://www.antoloji.com/carsamba-gozlu-ali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aglamakli bir yürek', 'aglamakli-bir-yurek-esra-turkoglu-ggd4r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yine sessiz sedasiz 

gecemdeyim

uykum firari yine

bu saatte

bir sen varsin aklimda

bir de sensizligin agir yükü

yüregimde

gecmiyor saatler

gecmiyor sanki günler

bir tek seni bekler

aglamakli bir yürek

bir de nemli sanki bu gözler

25 mart 2003', 'yine sessiz sedasiz  gecemdeyim uykum firari yine bu saatte bir sen varsin aklimda bir de sensizligin agir yükü yüregimde gecmiyor saatler g...', ARRAY['Türk Edebiyatı','Şiir','Esra Türkoğlu']::text[], 8.5, '{"poet":"Esra Türkoğlu","poet_slug":"esra-turkoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/aglamakli-bir-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memo', 'memo-gran-kizil-no3vy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Memo	

Baban anlatırdı

Çırayla yanan geceler de 

Harmanları

Çamurlu yolları

Gelinleri

Ekin başakları arasında

Hasoyu Husoyu  Memoyu

Çarıklarıyla

Kanlar içinde

Dili varmaz anlatsın

Kahrolası düşmanı

Çanakkale geçilmez Memo

Süngüler  beline 

Beynine 

Yüreğine saplanmış

Topraktan feryat kopuyor 

Hüzün

Heyacan 

Öfke ve kin

Ateşler içinde 

Bedenler geçit vermez

Ihanete

Namussuza

Kavga sarmış vatanı 

Dili varmaz anlatsın 

Çanakkale geçilmez Memo

Güneş doğar tan kımızısı

Ay batar nar kırmızısı 

Bulut yok

Utanç gökyüzünde

Düşürmüş yıldızı 

Gölleşen kanın içine

Barut kokar geceler

Uykusuz virane edepsiz

Parmak yetişmiyor tetiğe

Kalmış beden kolsuz ayaksız

Dili varmaz anlatsın 

Çanakkale geçilmez Memo

Altın sarısı genç

Al yanaklı kız

Bedenler miğfer 

Saplanmış süngüler

Geçit vermez potinler

Yürekler paramparça

Oofff anam ooffff 

Dili varmaz anlatsın

Çanakkale geçilmez  Memo

Gitti on kardeş ocağından ayrı

Gül bahçesi Diyarbakır viran

Bitlis uzakta Harput talan

Ooffff anam ooooff

Önce Sevr sonra Lozan

Dili varmaz anlatsın

Çanakkale geçilmez Memo', 'Memo	 Baban anlatırdı Çırayla yanan geceler de  Harmanları Çamurlu yolları Gelinleri Ekin başakları arasında Hasoyu Husoyu  Memoyu Çarıkları...', ARRAY['Türk Edebiyatı','Şiir','Gran Kizil']::text[], 8.5, '{"poet":"Gran Kizil","poet_slug":"gran-kizil","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/memo-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığım', 'yalnizligim-turgay-akbulut-zuxsm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu akşam yalnızım

Bir çay demledim kendime

Bardakları aradım dolaplarda

Çay tepsisi nerede? 

Üç bardak almışım elime

Oysa  yalnızdım ben, 

Şiirlerimle...

Bir fırsat yalnızlığım

Bağlarım bahçelerim yok

Yetmeyen bir maaşım

Ekmeliyim düşlerimi sayfalara

Meyve versin, hasat olsun, 

Yar olsun 

Bu gece bana....', 'Bu akşam yalnızım Bir çay demledim kendime Bardakları aradım dolaplarda Çay tepsisi nerede?  Üç bardak almışım elime Oysa  yalnızdım ben,  Ş...', ARRAY['Türk Edebiyatı','Şiir','Turgay Akbulut']::text[], 8.5, '{"poet":"Turgay Akbulut","poet_slug":"turgay-akbulut","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yalnizligim-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senden Önce', 'senden-once-selvi-celik-jm2r2', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin icinde yıldızlar rakkase dansını yaptıklarını kesfetmedim.

Ayın batısında gecenin sona erişimi, 

Gún dogusunu hic seyretmedim, 

                                Senden önce...

Birgün daha biterken, 

Yarınlar da umudun yaşadığını, 

Hayallerin rüya olduğunu inanmadım, 

                               Senden önce...

Kaldırım taşlarının nakış gibi işlenecek, 

Sokağın üstüne örüldügünü hiç farketmedim, 

                               Senden önce...

İnsanların doyumsuz koşuşturmalarını, 

Bir ressamın keşfini bilinçsizce cignediklerini görmedim, 

                                                Senden once...

Acıların birgün habersiz gelip kapıma dayanacagını, 

Hasretin bu kadar ağır yük oldugunu, 

Ve gayesizce bedenime mekan kurup, 

Nasıl altında caresizce ezdigini yaşamadım, 

                                       Senden önce...

Şayet ağlamak korkakların sığınağı, 

Gülmek, güçlü, mantıklı yaşayan insanların simgesi, 

 zengin düşüncenin onuru kabullenirdim, 

                                      Senden önce...

Bir şeyleri feda için bedel ödenmesini düşünmedim, 

                                     Senden önce...

Mecburiyetin bir ömrü yargısız idam kararını vermesini

                                                             engelleyemedim.

                                  Senden sonra.....', 'Gecenin icinde yıldızlar rakkase dansını yaptıklarını kesfetmedim. Ayın batısında gecenin sona erişimi,  Gún dogusunu hic seyretmedim,      ...', ARRAY['Türk Edebiyatı','Şiir','Selvi Çelik']::text[], 8.5, '{"poet":"Selvi Çelik","poet_slug":"selvi-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/senden-once-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelecekden Umutlarım', 'gelecekden-umutlarim-alim-vedat-suner-8v3dv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünüm güzeldi

             Güzellikleri yaşayabildikçe

Bugünüm daha güzel

             Seninle olabildikçe

Yarınım mükemmel olacak

             Sen bana yàr gelince

19.03.2003', 'Dünüm güzeldi              Güzellikleri yaşayabildikçe Bugünüm daha güzel              Seninle olabildikçe Yarınım mükemmel olacak          ...', ARRAY['Türk Edebiyatı','Şiir','Alim Vedat Süner']::text[], 8.5, '{"poet":"Alim Vedat Süner","poet_slug":"alim-vedat-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/gelecekden-umutlarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşlar', 'yaslar-alim-vedat-suner-vceh3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gözyaşının diliymiş

Sahil boyu martılar

